const enum SolveType {
	FULL,		// Inputs to the solver have changed, and the existing solution may not work
	SUGGESTED,	// Inputs to the solver have changed, but there is a suggested solution to work with
	UPDATE,		// Inputs to the solver have changed, but the current solution remains valid (override to same value)
	NONE,		// Nothing at all changed that could affect the solution
}

