	private simulationProgress: number = 0;
	private createFetchSimDataFunc = memoizeOne((runtime, modalService) =>
		(simulationTreeNode: SimulationTreeNode, progressCallback: ProgressCallback) =>
			fetchSimData(simulationTreeNode, runtime, modalService, progressCallback));

	constructor(
		protected sysConfig: SysConfig,
		private readonly notificationService: INotification,
		private readonly modalService: IModalService,
		private readonly errorStore: ErrorStore,
		private cliArgs: string[],
		private readonly deviceDiscoveryData: DiscoveryJSON,
	) {
		registerAnalytics(sysConfig.getResolvedArgs());

		if (isCCS()) {
			// inject navigation for eclipse problem view
			window.pinmuxNavigateToValidationMsg = (errorLocation: string) => {
				try {
					this.navigateToByCliMsg(errorLocation);
				} catch (e) {
					this.errorStore.registerException(convertUnknownToError(e));
				}
			};

			window.pinmuxNavigateToScript = (scriptPath: string) => {
				try {
					const normalized = path.normalize(scriptPath);
					const runtimeIndex = _.findIndex(this.sysConfig.getRuntimes(), (r) => r.getCurrentScript().get() === normalized);
					this.setSelectedContext(runtimeIndex);
				} catch (e) {
					this.errorStore.registerException(convertUnknownToError(e));
				}
			};
		}

		this.eclipseDeviceState = getEclipseDeviceState(this.cliArgs, this.sysConfig);

		this.userPreference = sysConfig.getUserPreference();

		this.navHistory = new NavigationHistory(
			(selection: SelectionInConfigStore) => {
				const changed = this.setSelection(selection, false);
				if (changed) {
					this.eventAnyChange.fire();
				}
			},
		);

		const selectedContex = this.sysConfig.getInitialContextSelection();
		const runtimeIndex = _.findIndex(this.sysConfig.getRuntimes(), (runtime) => runtime.getName() === selectedContex);
		this.selection = createSwitchTabSelection(runtimeIndex, this.getTabs(this.sysConfig.getRuntimes()[runtimeIndex])[0]);
		this.navHistory.record(this.selection);

		this.history = new ChangeHistory(
			this.sysConfig,
			this.getSelectionByName(),
			(selection, previousDeviceData, newSysConfig) => {
				this.updateSysConfig(newSysConfig);
				this.setSelectionByName(selection);
				this.deviceDataChanged(previousDeviceData);
				this.changeOccurred(this.revertedDescription, SolveType.SUGGESTED);
			},
			(dirty) => {
				_.each(this.sysConfig.getRuntimes(), (r) => r.getCurrentScript().setDirty(dirty));
				if (isCCS()) {
					window.eclipseSetEditorDirty(dirty ? "true" : "false");
				}
				this.updateTitle();
			},
		);
		if (_.some(this.sysConfig.getRuntimes(), (r) => r.getCurrentScript().get())) {
			this.history.setSavedPoint();
		}
		this.createOutputViewMgrs();

		_.each(this.sysConfig.getRuntimes(), (r) => r.getValidations().reSummarize());
	}

