	public async refreshFileTree(moduleMgr: FileModuleMgr) {
		const newRootPath = moduleMgr.getRequestedRootPath();
		let newTreeRoot: IStorageFile;
		if (!newRootPath) {
			newTreeRoot = undefined;
		} else {
			const children = await storage.readDirectory(storage.formatPathFromUser(newRootPath), newRootPath);
			newTreeRoot = {
				name: "/",
				path: newRootPath,
				relativePath: newRootPath,
				isDirectory: true,
				children,
			};
		}
		moduleMgr.refreshTree(newTreeRoot);
		this.sysConfig.validateAndSolve();
		this.history.updateCurrent();
		this.eventAnyChange.fire();
	}

	public requestFile(moduleMgr: FileModuleMgr, file: IStorageFile) {
		if (file.path === moduleMgr.getRootPath()) {
			this.setSelection(createSwitchInstanceSelection(this.selection, moduleMgr.static.getID()));
		} else if (!file.isDirectory) {
			if (!moduleMgr.getInstanceByRelativePath(file.relativePath)) {
				moduleMgr.createFileInstance(file);
			}
			const listItem = moduleMgr.getInstanceByRelativePath(file.relativePath);
			this.setSelection(createSwitchInstanceSelection(this.selection, listItem.getID()));
		}
		this.eventAnyChange.fire();
	}

