	// ITemplateActions
	public downloadFiles(folderOrZipName: string, fileList: CodeGenTemplateFile[], downloadFilesImpl = downloadFiles) {
		const [userScript, templates] = _.partition(fileList, isConfigScript);
		assertNeverThrows(this.errorStore, async () => {
			try {
				const generatedCode = this.getSelectedRuntime().getCodeGenerator().generateAll(templates);
				if (!_.isEmpty(userScript)) {
					const fileName = path.basename(_.first(userScript).path);
					generatedCode.push({
						fileName,
						contents: toScript(this.getSelectedRuntime(), fileName),
					});
				}

				await downloadFilesImpl(
					generatedCode,
					folderOrZipName,
				);
			} catch (e) {
				this.modalService.showErrorModal("Failed to save generated files", convertUnknownToError(e));
			}
		});
	}

	public generateCode(file: CodeGenTemplateFile) {
		if (isConfigScript(file)) {
			return toScript(this.getSelectedRuntime(), file.path);
		}
		return this.getSelectedRuntime().getCodeGenerator().generate(file);
	}

	public generateLastChangeCode(file: CodeGenTemplateFile) {

		// Do we actually have a previous point to compare with?

		if (0 === this.history.getCurrentPointIndex()) {
			throw "There is no previous code to compare with";
		}

		// Restore a specific state in the runtime created for just this purpose

		const sysConfig = this.history.copySysConfigAt(-1);

		// Return the result

		const runtime = sysConfig.getRuntimes()[this.selection.runtimeIndex];
		if (isConfigScript(file)) {
			return toScript(runtime, file.path);
		}
		return runtime.getCodeGenerator().generate(file);
	}

