	public allowConflict(obj: PinMgr | InterfaceInstanceMgr) {
		this.changeConfiguration(() => {
			const conflictDevicePinName = obj.memberMgrs.$assign.getValue();
			const adversaries = obj.getLockedAdversaries();
			_.each([obj, ...adversaries], (p) => {
				p.getSolverRequirement().allowConflicts(conflictDevicePinName);
				p.memberMgrs.$assignAllowConflicts.set(conflictDevicePinName, SetSource.USER_ASSIGN);
			});

			return `Ignore conflict between ${_.map([obj, ...adversaries], (p) => p.getName()).join(", ")}`;
		});
	}

	public disallowConflict(obj: PinMgr | InterfaceInstanceMgr) {
		this.changeConfiguration(() => {
			const adversaries = obj.getLockedAdversaries();
			obj.getSolverRequirement().disallowConflicts();
			obj.memberMgrs.$assign.set(obj.memberMgrs.$assignAllowConflicts.getValue(), SetSource.USER_ASSIGN);
			// If the conflict is shared between only two objects.
			// Disallowing conflict on one object should also disallow conflict on the other.
			if (_.size(adversaries) === 1) {
				adversaries[0].getSolverRequirement().disallowConflicts();
				adversaries[0].memberMgrs.$assign.set(
					adversaries[0].memberMgrs.$assignAllowConflicts.getValue(),
					SetSource.USER_ASSIGN,
				);
			}
			return `Don't ignore conflict on ${obj.getName()}`;
		});
	}

