	protected handleSave(saveOperation: () => Promise<void>) {
		assertNeverThrows(this.errorStore, async () => this.handleSaveAsync(saveOperation));
	}

	protected async handleSaveAsync(saveOperation: () => Promise<void>) {
		try {

			// IAR only runs the SysConfig command line if the ipcf file is older than the script
			// Unfortunately, even though windows supports ms file timestamp resolution, IAR uses
			// seconds resolution, and we don't want to wait 2 seconds to save the IPCF file.
			// Instead, we save the IPCF file and generate all templates when in the UI and in
			// IAR mode.  That way, the build doesn't NEED to run SysConfig.  But, if there's an 
			// error, we need to delete the IPCF file to force the build to run and fail.
			// See PMUX-2244 for details

			const hasErrors = _.some(this.sysConfig.getRuntimes(), (r) => r.hasErrors());
			for (const runtime of this.sysConfig.getRuntimes()) {
				const output = this.getOutputPath(runtime);
				if (this.shouldWriteIPCF(output)) {
					if (hasErrors) {
						await this.deleteIPCF(output);
					} else {
						await this.saveIPCF(runtime, output);
						const codeGenerator = this.getSelectedRuntime().getCodeGenerator();
						const templates = codeGenerator.getTemplates(false, TemplateSelectionType.ALL);
						if (!_.isEmpty(templates)) {
							const generated = codeGenerator.generateAll(templates);
							writeOutputFiles(output, generated);
						}
					}
				}
			}

			await saveOperation();
		} catch (e) {
			this.notificationService.pushNotification("Failed to save file: " + e);
		}
		this.postSave();
	}

