import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";
import { ClassesType } from "../styling/graphStyles";
import { PositionedDiv } from "../nodes/PositionedDiv";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { CursorMode, isProbingMode } from "../CursorMode";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";

// Renders a single port

interface IProps<PortMgr extends AnyMemberMgr> {
	port: Layout.Port<PortMgr>;
	onMouseDown: (event: React.MouseEvent, port: PortMgr) => void;
	onMouseUp: (event: React.MouseEvent, port: PortMgr) => void;
	onClick: (event: React.MouseEvent, port: PortMgr) => void;
	cursorMode: CursorMode;
}

export class Port<PortMgr extends AnyMemberMgr> extends React.Component<IProps<PortMgr> & ClassesType> {
	public override render() {
		const { port, classes } = this.props;
		const portSize = port.width;
		const className = this.getClassName();
		const tooltip = className === classes.disabledPort ? "Port does not support this type of probe" : "";
		return <PositionedDiv
			id={port.id}
			x={(port.x === 0 ? -portSize + port.x : port.x)}
			y={(port.y - portSize / 2)}
			height={portSize}
			width={portSize}
			className={className}
			onMouseDown={this.onMouseDown}
			onMouseUp={this.onMouseUp}
			onClick={this.onClick}
			tooltip={tooltip}
		/>;
	}

	private getClassName() {
		const { cursorMode, port, classes } = this.props;
		if (!(port.memberMgr instanceof PortMemberMgr) || !isProbingMode(cursorMode)) {
			// We don't need to worry about probing for the clock tree case
			return classes.port;
		}

		const probeType = cursorMode.probingMode;
		const probes = port.memberMgr.getValue().probes;
		if (_.some(probes, ({ type }) => type === probeType)) {
			return classes.probedPort;
		} else if (port.memberMgr.probeTypeIsPermitted(probeType)) {
			return classes.portInProbingMode;
		} else {
			return classes.disabledPort;
		}
	}

	private onMouseDown = (event: React.MouseEvent<HTMLDivElement>) => {
		event.stopPropagation();
		this.props.onMouseDown(event, this.props.port.memberMgr);
	}

	private onMouseUp = (event: React.MouseEvent<HTMLDivElement>) => {
		event.stopPropagation();
		this.props.onMouseUp(event, this.props.port.memberMgr);
	}

	private onClick = (event: React.MouseEvent<HTMLDivElement>) => {
		event.stopPropagation();
		this.props.onClick(event, this.props.port.memberMgr);
	}
}
