import * as _ from "lodash";
import { ModuleInstance, ScriptingObject, System } from "public/runtime";
import { AccessSpecification } from "../deprecatedAccessGuard";
import { findNode, findParentTabGroup } from "../objectManagers/viewNodes";
import { contextify } from "../resources/contextify";
import { Runtime } from "../resources/runtime";
import { runAsUserScript } from "./scriptingGuard";

type UpdateScript = (system: System,
	scripting: ScriptingObject,
	collapse: ReturnType<typeof getCollapse>,
	tabSelect: ReturnType<typeof getTabSelect>) => void;
export function updateRuntimeWithScript(runtime: Runtime, script: string, deprecatedAccess: AccessSpecification = {}) {
	const scriptFunc = contextify<UpdateScript>("<internal>", script, ["system", "scripting", "collapse", "tabSelect"]);
	runAsUserScript(
		() => scriptFunc(runtime.createSystemObj(),
			runtime.getScripting(),
			getCollapse(runtime),
			getTabSelect(runtime)),
		deprecatedAccess);
}

function getCollapse(runtime: Runtime) {
	return (inst: ModuleInstance, viewNodePath: string, enable: boolean) => {
		const mgr = runtime.getManager(inst);
		if (mgr) {	// could be a invalid assignment proxy, and thus have no manager
			const viewNodes = mgr.getViewNodes();
			const node = findNode(viewNodes, viewNodePath);
			if (node) { // Node may not exist on a different target
				node.setCollapsed(enable);
			}
		}
	};
}

function getTabSelect(runtime: Runtime) {
	return (inst: ModuleInstance, tabKey: string) => {
		const mgr = runtime.getManager(inst);
		if (mgr) {	// could be a invalid assignment proxy, and thus have no manager
			const parentTabGroup = findParentTabGroup(mgr.getUINodes().tabGroup, tabKey);
			if (parentTabGroup) { // Node may not exist on a different target
				parentTabGroup.setCurrentTab(_.find(parentTabGroup.getNodes(), (node) => node.getKey() === tabKey));
			}
		}
	};
}
