import * as _ from "lodash";
import React = require("react");
import { CardContent, Typography, Switch } from "../../../imports/material-ui-imports";
import { Formatted2ColRow } from "../../Formatted2ColRow";
import { MultiDropDown } from "../../DropDown";
import { assertUnreachable } from "../../../services/utils";
import {
	PreferenceType,
	MultiSelectPreference,
	SwitchPreference,
	PinDisplayType,
	ButtonAction,
} from "../../../services/userPreferences";
import { SecondaryButton } from "../../buttons/SecondaryButton";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { UserPreferenceViewMgr } from "../../../services/ui/outputView";
import { IUserPreferenceActions } from "../../actions/IUserPreferenceActions";
import { commonStyles } from "../../styles/common";
import { Tooltip } from "../../Tooltip";
import { SwitchButton } from "../../buttons/SwitchButton";
import { IOutputActions } from "../../actions/IOutputActions";
import { isCCS, isEmbedded } from "../../../services/platform";
import { ATheme, ThemeType } from "../../styles/themes";

interface IProps {
	mgr: UserPreferenceViewMgr;
	actions: IUserPreferenceActions & IOutputActions;
}

export class UserPreferenceView extends React.Component<IProps & IGlobalServiceProps> {

	public override render() {
		const { mgr, actions, theme } = this.props;
		const uPref = mgr.getUserPreferences();
		const hasBoard = mgr.hasBoard();
		const lockAction = uPref.getLockAction();
		return (
			<CardContent>
				<table>
					<UserPrefGrouping
						heading="Preferences"
						key="userPrefGroup"
						top
					>
						{_.map(uPref.getPreferences(), (curPref, name) => {
							if (curPref.requireBoard && !hasBoard) {
								return null;
							}
							let col2Content = null;	// empty DOM element

							if (PreferenceType.MULTISELECT === curPref.type) {
								col2Content =
									<MultiSelectPreferenceView actions={actions} preference={curPref} name={name} />;
							} else if (PreferenceType.Switch === curPref.type) {
								col2Content =
									<SwitchPreferenceView actions={actions} preference={curPref} theme={theme} />;
							} else {
								return assertUnreachable(curPref);
							}

							return (
								<Formatted2ColRow
									key={name}
									col1={<Typography style={{ marginLeft: 12 }}>{curPref.description}</Typography>}
									col2={col2Content}
								/>
							);
						})}
					</UserPrefGrouping>
					<UserPrefGrouping
						heading="Actions"
						key="userActionsGroup"
					>
						{lockAction && !hasBoard && <LockPinMux actions={actions} theme={theme} lockAction={lockAction} />}
						{mgr.isMigrationAllowed() && <SwitchTarget mgr={mgr} actions={actions} theme={theme} />}
					</UserPrefGrouping>
				</table>
			</CardContent >
		);
	}
}

interface CommonProps {
	actions: IUserPreferenceActions & IOutputActions;
	theme: ATheme
}

function LockPinMux({ lockAction, theme, actions }: { lockAction: ButtonAction } & CommonProps) {
	const onClick = React.useCallback(() => {
		lockAction.onClick(actions);
	}, [lockAction, actions]);
	return (
		<Formatted2ColRow
			col1={
				<Tooltip
					title={lockAction.tooltip}
					placement="top"
				>
					<Typography style={{ marginLeft: 12 }}>{lockAction.description}</Typography>
				</Tooltip>
			}
			col2={
				<SecondaryButton
					theme={theme}
					id={`userPreferencesBtn${lockAction.buttonName}`}
					onClick={onClick}
				>
					{lockAction.buttonName}
				</SecondaryButton>
			}
		/>
	);
}

function SwitchTarget({ actions, mgr, theme }: { mgr: UserPreferenceViewMgr } & CommonProps) {
	return (
		<Formatted2ColRow
			key="Switch"
			col1={
				<Tooltip
					title={""}
					placement="top"
				>
					<Typography style={{ marginLeft: 12 }}>{"Switch Target"}</Typography>
				</Tooltip>
			}
			col2={
				<SwitchButton
					theme={theme}
					mgr={mgr}
					actions={actions}
				/>
			}
		/>
	);
}

interface MultiSelectProps {
	preference: MultiSelectPreference<PinDisplayType>;
	name: string;
	actions: IUserPreferenceActions;
}

function MultiSelectPreferenceView({ preference, name, actions }: MultiSelectProps) {
	const enabledOptions = _.map(
		preference.getAllSelectableOptions(), (o) => {
			return { name: o.id.toString(), displayName: o.optionText, description: o.description };
		});
	const selectedValues = _.map(preference.getSelectedEnums(), (selected) => selected.toString());
	const setValues = React.useCallback((values: string[]) => {
		actions.setPreferenceValue(preference, _.map(values, (value) => parseInt(value, 10)));
	}, [actions, preference]);
	return (
		<span>
			<MultiDropDown
				id={name + "MultiSelect"}
				disabled={false}
				onChange={setValues}
				selectedOptionName={selectedValues}
				enabledOptions={enabledOptions}
				displayScriptName={false}
			/>
		</span>
	);
}

interface SwitchPreferenceProps extends CommonProps {
	preference: SwitchPreference;
}
function SwitchPreferenceView({ preference, actions, theme }: SwitchPreferenceProps) {
	const onChange = React.useCallback((_e, checked: boolean) => {
		actions.setPreferenceValue(preference, checked);
	}, [actions, preference]);
	const getValue = React.useCallback(() => {
		if (preference.name === "darkMode" && (isCCS() || isEmbedded())) {
			// The theme user preference is solely controlled by the editor if in CCS, 
			// it'd be odd if sysconfig was dark while the rest of CCS is light however, we should still
			// want the checkbox to reflect what CCS is currently showing so show this value on the fly
			return theme.name === ThemeType.DARK;
		} else {
			return preference.getValue();
		}
	}, [preference, theme]);
	return (
		<Tooltip title={preference.getTooltipIfDisabled()}>
			<Switch
				color={"primary"}
				id={preference.name}
				onChange={onChange}
				disabled={!_.isEmpty(preference.getTooltipIfDisabled())}
				checked={getValue()}
			/>
		</Tooltip>
	);
}

interface UserPrefGroupingProps {
	heading: string,
	top?: boolean
}

function UserPrefGrouping({ heading, children, top }: React.PropsWithChildren<UserPrefGroupingProps>) {
	return (<>
		<thead key={"userPrefHead" + heading} >
			<tr>
				<th>
					<Typography
						style={top ? commonStyles.headingStyleTop : commonStyles.headingStyleNotTop}>
						{heading}
					</Typography>
				</th>
			</tr>
		</thead >
		<tbody key={"userPrefBody" + heading}>
			{children}
		</tbody>
	</>
	);
}
