import * as _ from "lodash";
import React = require("react");
import DeviceData = require("dataInterfaces");
import { isColumnDimensions, isEmptySpace } from "../services/boardSupport/boardParser";
import { Header, RowDimension, EmptySpace, ColumnDimension } from "public/defs";
import { BoardViewCollection, IBoardViewCollectionProps } from "./BoardViewCollection";
import { PinInfo } from "../services/pinInfo";
import { Placement } from "./BoardViewEntry";
import { ATheme } from "./styles/themes";

interface IColumnRowInfo {
	begin: number;					// start number of the row/column
	end: number;					// end number of the row/column
	firstLabelPlacement: Placement;	// how labels should be justified at the start of the row/column
	lastLabelPlacement: Placement;	// how labels should be justified at the end of the row/column
	horizontal: boolean;			// true if this is a row; false if it is a column
}

interface IBoardViewHeadersProps {
	deviceData: DeviceData.AdaptedDeviceInfo;
	pinInfo: PinInfo;
	header: Header;
	shouldShowModeTable: boolean;
	theme: ATheme;
}

// Headers are collection of pins that are oriented as rows or columns
export class BoardViewHeaders extends React.Component<IBoardViewHeadersProps, {}> {
	public override render() {
		// the collection of rows or columns properties, use for rendering <BoardViewCollection> components
		const collectionPropsArr: IBoardViewCollectionProps[] = [];
		let columnRowWrapper: (EmptySpace | ColumnDimension | RowDimension)[];
		let numCollections = 0;

		if (isColumnDimensions(this.props.header.dimensions)) {	// columns
			columnRowWrapper = this.props.header.dimensions.columns;
			numCollections = this.props.header.dimensions.columns.length;
		} else {
			columnRowWrapper = this.props.header.dimensions.rows;
			numCollections = this.props.header.dimensions.rows.length;
		}

		let emptyIndex = _.findIndex(columnRowWrapper, (entry) => {
			return isEmptySpace(entry);
		});

		_.each(columnRowWrapper, (columnRow, index) => {
			if (isEmptySpace(columnRow)) {
				// draw an empty column
				collectionPropsArr.push({
					start: 1,
					end: 1,
					increment: 1,
					type: "empty",
					pinInfo: this.props.pinInfo,
					shouldShowModeTable: this.props.shouldShowModeTable,
					theme: this.props.theme,
				});

				emptyIndex = _.findIndex(columnRowWrapper, (entry) => {
					return isEmptySpace(entry);
				}, index);
			} else {
				// apply label on left side on first column, or if the previous column was empty
				const info = this.generateColumnRowInfo(columnRow);

				if (index === 0 || index === emptyIndex + 1) {
					collectionPropsArr.push({
						start: info.begin,
						end: info.end,
						increment: columnRow.increment,
						displayNumbers: this.props.header.displayNumbers,
						type: "label",
						placement: info.firstLabelPlacement,
						headerPins: this.props.header.pins,
						devicePins: this.props.deviceData.devicePins,
						pinInfo: this.props.pinInfo,
						horizontal: info.horizontal,
						shouldShowModeTable: this.props.shouldShowModeTable,
						theme: this.props.theme,
						boardNumberOffset: this.props.header.boardNumberOffset,
					});
				}

				// column of pin entry
				collectionPropsArr.push({
					start: info.begin,
					end: info.end,
					increment: columnRow.increment,
					displayNumbers: this.props.header.displayNumbers,
					type: "pin",
					side1: index === 0 || index === emptyIndex + 1,
					side2: index === numCollections - 1 || index === emptyIndex - 1,
					headerPins: this.props.header.pins,
					devicePins: this.props.deviceData.devicePins,
					pinInfo: this.props.pinInfo,
					horizontal: info.horizontal,
					shouldShowModeTable: this.props.shouldShowModeTable,
					theme: this.props.theme,
					boardNumberOffset: this.props.header.boardNumberOffset,
				});

				// apply label on right side on last column or if next column is empty
				if (index === numCollections - 1 || index === emptyIndex - 1) {
					collectionPropsArr.push({
						start: info.begin,
						end: info.end,
						increment: columnRow.increment,
						displayNumbers: this.props.header.displayNumbers,
						type: "label",
						placement: info.lastLabelPlacement,
						headerPins: this.props.header.pins,
						devicePins: this.props.deviceData.devicePins,
						pinInfo: this.props.pinInfo,
						horizontal: info.horizontal,
						shouldShowModeTable: this.props.shouldShowModeTable,
						theme: this.props.theme,
					});
				}
			}
		});

		return (
			<div>
				{
					_.map(collectionPropsArr, (content, index) => {
						return <BoardViewCollection key={`${index}`} {...content} />;
					})
				}
			</div>
		);
	}

	// generate IColumnRowInfo for the given column/row object
	private generateColumnRowInfo(columnRow: ColumnDimension | RowDimension): IColumnRowInfo {
		if (isColumnDimenion(columnRow)) {
			return {
				begin: columnRow.top,
				end: columnRow.bottom,
				firstLabelPlacement: "left",
				lastLabelPlacement: "right",
				horizontal: false,
			};
		} else {
			return {
				begin: columnRow.left,
				end: columnRow.right,
				firstLabelPlacement: "top",
				lastLabelPlacement: "bottom",
				horizontal: true,
			};
		}
	}
}

function isColumnDimenion(columnRow: ColumnDimension | RowDimension): columnRow is ColumnDimension {
	return "top" in columnRow;
}
