import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { Alignment, MainLabel } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import * as Layout from "../types/layoutTypes";
import { typedMemo } from "../../typedMemo";
import { INodeProps } from "../types/nodeTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// A label just below the connection edge and nothing else

export const LabeledConnectionNode = typedMemo(
	function LabeledConnectionNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
		{
			node,
			onClickNode,
			onMouseDownNode,
			displayScriptName,
			classes,
			validations,
			formatter,
		}: React.PropsWithChildren<INodeProps<InstMgr, PortMgr> & ClassesType>
	) {
		return (
			<PositionedNode
				node={node}
				onClick={onClickNode}
				onMouseDown={onMouseDownNode}
				className={classes.positionedDiv}
				validations={validations}
				formatter={formatter}
			>
				<MainLabel
					node={node}
					displayScriptName={displayScriptName}
					alignment={getAlignment(node)}
					classes={classes}
				/>
			</PositionedNode >
		);
	});

function getAlignment<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(node: Layout.Node<InstMgr, PortMgr>) {
	if (_.size(node.ports) === 1) {
		return _.first(node.ports).type === "input" ? Alignment.RIGHT : Alignment.LEFT;
	}
	return Alignment.CENTER;
}
