import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { INodeValidationProps, NodeStatusIndicator } from "../nodes/NodeStatusIndicator";
import { NodeSelectionIndicator } from "./NodeSelectionIndicator";
import { getConfigurationChangeNumber } from "../../../services/changeNumber";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import * as Layout from "../types/layoutTypes";
import { typedMemo } from "../../typedMemo";
import { CanMemoize, NodeFactory } from "../types/nodeTypes";
import { IUnStyledNodeProps, Node } from "./Node";
import { IGraphTreeNode } from "../types/IGraphTreeNode";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { UserGraphAction } from "../types/IGraphProps";

// This renders a collection of nodes

// Props to render a collection of nodes that ignores errors/warnings/selection.  That allows the component to render
// less often, on the assumption that errors/warnings/selection is rendered over top

interface INodesProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends Omit<IUnStyledNodeProps<InstMgr, PortMgr>, "node" | "validations" | "selection" | "formatter"> {
	nodes: Layout.Node<InstMgr, PortMgr>[];
	nodeFactory: NodeFactory<InstMgr, PortMgr>;
	canMemoize: CanMemoize<InstMgr, PortMgr>;
}

type IProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	= INodesProps<InstMgr, PortMgr>
	& Omit<INodeValidationProps<InstMgr, PortMgr>, "configurationNumber">
	& {
		treeNode: IGraphTreeNode<InstMgr>;
		userAction: UserGraphAction;
	};

export function Nodes<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>({
	nodes,
	nodeFactory,
	canMemoize,
	treeNode,
	usedInstances,
	disabledInstances,
	searchText,
	onClickNode,
	onMouseDownNode,
	onMouseDownPort,
	onMouseUpPort,
	onClickPort,
	actions,
	validations,
	displayScriptName,
	classes,
	userAction,
	cursorMode,
	formatter,
}: IProps<InstMgr, PortMgr> & ClassesType) {
	const nodeProps = {
		nodes,
		nodeFactory,
		canMemoize,
		usedInstances,
		disabledInstances,
		searchText,
		onClickNode,
		onMouseDownNode,
		onMouseDownPort,
		onMouseUpPort,
		onClickPort,
		actions,
		displayScriptName,
		cursorMode,
		classes,
	};
	const statusProps = { ...nodeProps, validations, treeNode, formatter };

	// So the idea is that we don't want to redraw everything on any change to the parent (which will re-render 
	// whenever a connection is hovered over or clicked on).  So lets break down when we do need to re-render:
	// 1) When the selection changes
	// 2) When errors/warnings change
	// 3) When the controls on a node change (mux radio buttons, gate check boxes, divider/multiplier drop downs)
	// 4) When nodes become unused or disabled
	// 5) When the search text changes, and nodes must be filtered.
	//
	// However, we can make some broad observations about the above
	// 1) Only affects two nodes max - the previously selected node and the newly selected one
	// 2) Can happen any time, as suppressing a warning is outside of regular configuration changes.  However, we 
	//    expect we expect few errors/warnings, since users will likely address those issues as they arise, so this
	//    should affect few nodes
	// 3) Affects only some node types (those with controls), and only happens on a configuration change
	// 4) Affects every node type, but only on a configuration change
	// 5) Affects every node, but only when the search text changes
	//
	// Based on that, we can take some strategies to mitigate re-rendering
	// 1) Selected nodes are drawn on top of other nodes (NodeSelectionIndicator), meaning all other components can 
	//    ignore the selection state and not re-render.  However, NodeSelectionIndicator must re-render every time, but
	//    it is just the one node
	// 2) Errors/warnings are also drawn on top of of other nodes (NodeStatusIndicator), but we assume it will render
	//    very few nodes.
	// 3) Nodes can be split into two groups, static and dynamic, based on if they have controls to re-render or not.
	//    Static nodes can memoize based on props and ignore the configuration number, but dynamic nodes need to 
	//    consider the configuration number
	// 4) Could affect anything, but is passed in as a prop so memoizing will minimize re-renders
	// 4) Could affect anything, but is passed in as a prop so memoizing will minimize re-renders
	//
	// This should explain the purpose behind each of the components below

	const configurationNumber = getConfigurationChangeNumber();
	return <>
		<StaticNodes {...nodeProps} />
		<DynamicNodes {...nodeProps} configurationNumber={configurationNumber} />
		<NodeStatusIndicator {...statusProps} />
		<NodeSelectionIndicator {...statusProps} userAction={userAction} />
	</>;
}

// Static nodes can use a memo as they will never change

const StaticNodes = typedMemo(function StaticNodes<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: INodesProps<InstMgr, PortMgr> & ClassesType
) {
	return renderNodes(props, false);
});

// Dynamic nodes must be re-rendered only when the configuration changes

const DynamicNodes = typedMemo(
	function DynamicNodes<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
		props: INodesProps<InstMgr, PortMgr> & ClassesType & { configurationNumber: number }
	) {
		const { configurationNumber, ...rest } = props;
		return renderNodes(rest, true);
	}
);

// Renders some of the nodes based on a filter
// We have to filter inside this function vs outside or props would change on every render anyway

function renderNodes<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	{
		nodes,
		canMemoize,
		usedInstances,
		disabledInstances,
		searchText,
		classes,
		...rest
	}: INodesProps<InstMgr, PortMgr> & ClassesType, dynamic: boolean
) {
	return <>
		{_.chain(nodes)
			.filter((node) => dynamic === canMemoize(node))
			.map((node) => {
				return <Node
					key={node.id}
					node={node}
					classes={classes}
					disabledInstances={disabledInstances}
					usedInstances={usedInstances}
					searchText={searchText}
					validations={null}		// Do not consider validations - we'll do that separately
					formatter={null}
					{...rest}
				/>;
			})
			.value()
		}
	</>;
}
