import * as React from "react";
import * as _ from "lodash";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { DropDownOption } from "../../ComponentUtils";
import { FormattedMsg } from "../../FormattedMsg";
import { ILinkActions } from "../../actions/ILinkActions";

export class CBaseEnumConfigurable<T extends {
	actions: ILinkActions;
	formatter: IFormatter;
}> extends React.Component<T, {
	key: number;
}> {
	public override state = { key: 0 };
	protected formatOptions(options: DropDownOption[]) {
		return _.map(options, (option) => {
			return {
				...option,
				description: option.description
					? <FormattedMsg
						message={this.props.formatter(option.description)}
						actions={this.props.actions}
						onClick={this.handleOnClick} />
					: option.description,
			};
		});
	}

	private handleOnClick = () => {
		this.setState({ key: this.state.key + 1 }); // Generate a new key so we force a close on a tooltip click-away
	}
}
