import * as _ from "lodash";
import { IFormatter } from "./formatting/formattingTypes";
import { ILinkActions } from "../components/actions/ILinkActions";
import { ATheme } from "../components/styles/themes";
import { DevicePinSolutionMap } from "./solver/requirements";
import * as data from "dataInterfaces";
import { PinInfo } from "./pinInfo";
import { BGAPkg } from "./devicePinviews/bgaPackage";
import { QFPPkg } from "./devicePinviews/qfpPackage";
import { CustomPkg } from "./devicePinviews/customPackage";
import { Stage } from "konva/lib/Stage";
import { Layer } from "konva/lib/Layer";
import * as Konva from "konva";

let pkg: QFPPkg;
let stage: Stage;
let pinLayer: Layer;
let pkgLayer: Layer;

export function init(
	pinInfo: PinInfo,
	deviceData: data.AdaptedDeviceInfo,
	devicePinSolutionMap: DevicePinSolutionMap,
	selectedPins: Set<string>,
	formatter: IFormatter,
	shouldShowModeTable: boolean,
	actions: ILinkActions,
	theme: ATheme) {
	pkg = createPkg(pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

	stage = null;
	pinLayer = null;

	pkgLayer = new Layer();
	pkg.addBorder(pkgLayer);
	pkg.addDimple(pkgLayer);

	pinLayer = new Layer();
	pkg.addPins(pinLayer);
	pkg.addPinActions(pinLayer, shouldShowModeTable);

	const { width, height } = pkg.getStageDimensions();

	stage = new Stage({
		container: "deviceView",
		width,
		height,
	});
	stage.add(pkgLayer);
	stage.add(pinLayer);
	stage.draw();
}

export function redraw(
	pinInfo: PinInfo,
	formatter: IFormatter,
	selectedPins: Set<string>,
	devicePinSolutionMap: DevicePinSolutionMap,
	strokeColor: string,
) {
	if (stage) {
		pkg.pinInfo = pinInfo;
		pkg.selectedPins = selectedPins;
		pkg.devicePinSolutionMap = devicePinSolutionMap;
		pkg.formatter = formatter;
		pkg.redraw(strokeColor);
	}
}

export function destroy() {

	// destroy is not recursive
	// we have to first destroy the stage, then its children
	// and then children of the children.

	pkgLayer.destroyChildren();
	pkgLayer.destroy();
	pinLayer.destroyChildren();
	pinLayer.destroy();
	stage.destroyChildren();
	stage.destroy();

	// Clear Konva impl cache to avoid memory leaks.
	(Konva as any).shapes = {};
}

function createPkg(
	pinInfo: PinInfo,
	deviceData: data.AdaptedDeviceInfo,
	devicePinSolutionMap: DevicePinSolutionMap,
	selectedPins: Set<string>,
	formatter: IFormatter,
	actions: ILinkActions,
	theme: ATheme): QFPPkg {

	if (deviceData.customDeviceView) {
		const customPkg = new CustomPkg(pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);
		return customPkg;
	} else if (deviceData.packageDescription.type === "QFP") {

		const qfpPkg = new QFPPkg(
			pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

		return qfpPkg;

	} else if (deviceData.packageDescription.type === "BGA") {

		const bgaPkg = new BGAPkg(
			pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

		return bgaPkg;

	}

	throw new Error("Unsupported Package Type");
}
