import { isCloud, isNode, isCCS } from "./platform";
import * as ChokidarType from "chokidar";
import { assertNeverThrows } from "./utils";
import { ErrorStore } from "./errorStore";

export interface IFileWatcher {
	close: () => void;
	getWatchedPath: () => string;
}

class BaseFileWatcher implements IFileWatcher {
	constructor(protected path: string, _cb: () => void, protected readonly errorStore: ErrorStore) {
	}

	public getWatchedPath() {
		return this.path;
	}

	public close() {
	}

	protected watch(_cb: () => void) {
	}
}

class NWFileWatcher extends BaseFileWatcher {
	private chokidar: typeof ChokidarType = require("chokidar");
	private watcher: ChokidarType.FSWatcher;
	constructor(path: string, cb: () => void, errorStore: ErrorStore) {
		super(path, cb, errorStore);
		this.watch(cb);
	}

	public override close() {
		if (this.watcher) {
			assertNeverThrows(this.errorStore, this.watcher.close());
			this.watcher = null;
		}
	}

	protected override watch(cb: () => void) {
		this.watcher = this.chokidar.watch(
			this.path,
			{
				persistent: true,
				ignoreInitial: true,
			},
		);
		this.watcher.on("all", cb);
	}
}

class EclipseFileWatcher extends BaseFileWatcher {
	constructor(path: string, cb: () => void, errorStore: ErrorStore) {
		super(path, cb, errorStore);
		this.watch(cb);
	}

	public override close() {
		eclipseWatchDirectory(this.path, null);
	}

	protected override watch(cb: () => void) {
		(window as any).pinmuxWatcherCallback = cb;
		eclipseWatchDirectory(this.path, "pinmuxWatcherCallback");
	}
}

export let FileWatcher: typeof BaseFileWatcher;

if (isNode()) {
	FileWatcher = NWFileWatcher;
} else if (isCCS()) {
	FileWatcher = EclipseFileWatcher;
} else if (isCloud()) {
	FileWatcher = BaseFileWatcher;
}
