import * as React from "react";
import * as _ from "lodash";
import { Joint } from "./Joint";
import * as Layout from "../types/layoutTypes";

// Renders a collection of joints

export const Joints = React.memo(function Joints({ joints, className }: { joints: Layout.Point[], className: string }) {
	return <>
		{_.map(joints, (joint) => {
			return <Joint
				key={`joint(${joint.x},${joint.y})`}
				joint={joint}
				className={className}
			/>;
		})}
	</>;
});
