import { createFinalSvgPathNode } from "./createSvgPathNode";

// Looks like a giant T.  Single output port always connects at the bottom of the T

function powerPath(width: number, height: number) {
	return "M 0 0 "				// Start in top left corner
		+ `H ${width} `			// Top bar stretching the width
		+ `M ${width / 2} 0 `	// Move to the middle
		+ `V ${height}`;		// Vertical bar to the bottom
}

// Offsets are forced to the middle, with the assumption y is always the middle

export const PowerNode = createFinalSvgPathNode(powerPath, {
	heightFactor: 1 / 2,
	widthFactor: 1 / 2,
	portYOffset: ({ height }) => height,
	outputLabelXOffset: (nodeSize) => -nodeSize.width / 2,
	outputPortXOffset: (nodeSize) => -nodeSize.width / 2,
});
