export interface ITargetID {
	board?: string;
	device: string;
	partID: string;
	packageID: string;
	targetDBDevice: string;
	contexts: string[];
}

// Returns true if running in a new-enough eclipse to support migrating the eclipse project

export function supportsProjectMigration() {
	return isCCS() &&
		window.eclipseGetCurrentTargetDBDevice &&
		(window.eclipseMigrateProject || window.eclipseMigrateProject2) &&
		window.eclipseGetTargetDBDeviceDisplayName;
}

// Migrate the current configuration across all runtimes, to new runtimes associated with a 
// different target

export async function migrate(oldSysConfig: SysConfig, newTarget: ITargetID, lockPinmux: boolean) {

	// Create the new device data and empty SysConfig

	const newDeviceData = await createDeviceData(
		oldSysConfig.getRawResourceLoader(), newTarget, oldSysConfig.isCorePinmux(), oldSysConfig.getDeviceData().board);
	const newSysConfig = oldSysConfig.clone(
		newDeviceData, newTarget.targetDBDevice, updateArgs(oldSysConfig, newTarget));

	// The contexts for the existing target were ordered by the runtime order.
	// But, the data will be written to a new context which won't necessary be in the same offset.
	// As such, we must find matching new runtime by it's name.

	const oldRuntimes = oldSysConfig.getRuntimes();
	const newRuntimes = _.map(newTarget.contexts, (c) => _.find(newSysConfig.getRuntimes(), (r) => c === r.getName()));

	// Now remove any modules/peripherals from the current configuration that won't make sense

	const unsupportedInstances: string[] = [];
	for (let i = 0; i < oldRuntimes.length; ++i) {
		unsupportedInstances.push(...removeUnsupportedInstances(oldRuntimes[i], newRuntimes[i]));
		await yieldToRendering();
	}

	// Migrate everything remaining

	unsupportedInstances.push(
		...migrateConfiguration(oldSysConfig, oldRuntimes, newSysConfig, newRuntimes, lockPinmux).invalidModules);

	for (const runtime of newSysConfig.getRuntimes()) {
		await preFetchForResponsiveUI(runtime);
	}

	// Run the onMigrateHandler for each module and its instances for each runtime then return

	runPostMigrateCallacks(newRuntimes, oldRuntimes);
	return { newSysConfig, unsupportedInstances: _.uniq(unsupportedInstances) };
}

// Runs all the "onMigrate" callback handlers for any modules that participated in the migrate.

export function runPostMigrateCallacks(newRuntimes: Runtime[], oldRuntimes: Runtime[]) {
	_.each(newRuntimes, (newRuntime, index) => {
		const oldRuntime = oldRuntimes[index];
		_.each(newRuntime.getModuleMgrs(), (newMgr) => {
			const name = newMgr.getName();
			_.each(newMgr.allInstancesIncludingStatic(), (newInst) => {
				if (newInst.module.onMigrate) {
					const oldMgr = oldRuntime.getModuleMgr(name);
					const oldInst = newInst.isStatic() ? oldMgr.static : oldMgr.getInstance(newInst.managedObject.$name);
					runAsUserScript(
						() => newInst.module.onMigrate(newInst.managedObject, oldInst.managedObject, oldRuntime.createSystemObj(name)));
				}
			});
		});
	});
}

// Create a new deviceData for the given target.  RawResourceLoader can only be used to load json, needed for 
// boards/boosterpacks, and the old board data is passed in order to capture boosterpacks

export async function createDeviceData(
	resourceLoader: RawResourceLoader,
	newTarget: Omit<ITargetID, "contexts" | "targetDBDevice">,
	isCorePinmux: boolean,
	oldBoard?: Board
) {
	const newDeviceData = await getDeviceData(newTarget.device, newTarget.partID, newTarget.packageID, isCorePinmux);
	await migrateBoardAndBoosterpacks(resourceLoader, newTarget.board, newDeviceData, oldBoard);
	return newDeviceData;
}

function updateArgs(oldSysConfig: SysConfig, newTarget: ITargetID) {
	const resolvedArgs = _.cloneDeep(oldSysConfig.getResolvedArgs());

	// Update target

	resolvedArgs.boardId = newTarget.board;
	resolvedArgs.deviceId = newTarget.device;
	resolvedArgs.partId = newTarget.partID;
	resolvedArgs.packageId = newTarget.packageID;

	// Update contexts

	resolvedArgs.script = _.map(resolvedArgs.script, (scriptArgs) => {
		const runtimeIndex = _.findIndex(oldSysConfig.getRuntimes(), (r) => r.getName() === scriptArgs.context);
		const context = newTarget.contexts[runtimeIndex];
		return {
			...scriptArgs,
			context,
		};
	});
	return resolvedArgs;
}

// If the new target is a board, parse the board definition to create the runtime representation of
// it.  Then re-attach any currently attached boosterpacks associated with the current board

async function migrateBoardAndBoosterpacks(
	resourceLoader: RawResourceLoader,
	newBoardName: string,
	newDeviceData: AdaptedDeviceInfo,
	oldBoard?: Board,
) {
	if (!_.isEmpty(newBoardName)) {
		const parser = new BoardParser(resourceLoader, newDeviceData);
		await parser.loadBoard(newBoardName);
		_.each(getAttachedBoosterpacks(oldBoard), (bp) => {
			parser.loadBoosterPack(bp.definition, bp.attachedTo);
		});
	}
}

// returns any user-added modules/peripherals that no longer makes sense

export function getUnsupportedInstances(currentRuntime: Runtime, newRuntime: Runtime) {
	return [
		...getUnsupportedModules(currentRuntime, newRuntime),
		...getUnsupportedPeripherals(currentRuntime, newRuntime),
	];
}

// Any module that was a top module before, but no longer is, yet is user added, really wouldn't
// be possible to add in the new runtime.  Most likely this is because the module only makes sense
// on the original target.
//
// There are some cases where non-top modules are being added by the script, but those won't be top
// modules in either case, and thus are ignored.
//
// Non-user added modules (ie pulled in by something else) we also keep.  They may not be pulled in
// the new configuration, but serialization will handle that appropriately.

function getUnsupportedModules(currentRuntime: Runtime, newRuntime: Runtime) {
	if (!currentRuntime.isCorePinmux()) {
		const topModules = currentRuntime.getTopModules();
		const newTopModules = newRuntime.getTopModules();
		const noLongerTopNames = _.difference(topModules.getModuleNames(), newTopModules.getModuleNames());
		return _.chain(currentRuntime.getModuleMgrs())
			.filter((m) => _.includes(noLongerTopNames, m.getName()))
			.flatMap((m) => m.allInstancesIncludingStatic())
			.filter((m) => m.isUserCreatedOrTouched() && m.canRemove().enabled === ActionEnabled.YES)
			.value();
	}
	return [];
}

// Same as getUnsupportedModules, but for peripherals.  In this case, remove-ability and user-created
// doesn't matter, as there's no such concept for these

function getUnsupportedPeripherals(currentRuntime: Runtime, newRuntime: Runtime) {
	const peripherals = _.keys(currentRuntime.getDeviceData().interfaces);
	const newPeripherals = _.keys(newRuntime.getDeviceData().interfaces);
	const noLongerExists = _.difference(peripherals, newPeripherals);
	return _.chain(currentRuntime.getInterfaceMgrs())
		.filter((i) => _.includes(noLongerExists, i.getName()))
		.flatMap((i) => i.getInstances())
		.value();
}

// This function will remove any unsupported modules from the current runtime so that they aren't 
// included in the serialization statements

function removeUnsupportedInstances(currentRuntime: Runtime, newRuntime: Runtime) {

	// Keep calling getUnsupportedModules until there's none left.  A module might not initially
	// appear removable until others that are holding it in are removed

	const removed: string[] = [];
	let instanceMgrs = getUnsupportedInstances(currentRuntime, newRuntime);
	while (!_.isEmpty(instanceMgrs)) {
		removed.push(..._.chain(instanceMgrs)
			.each((m) => m.remove())
			.map((m) => m.getNameMgr().getDisplayValue())
			.value());
		instanceMgrs = getUnsupportedInstances(currentRuntime, newRuntime);
	}
	return removed;
}

// Just serialize the current configuration and restore it to the new runtime, while capturing errors

export function migrateConfiguration(
	oldSysConfig: SysConfig,
	oldRuntimes: Runtime[],
	newSysConfig: SysConfig,
	newRuntimes: Runtime[],
	lockPinmux: boolean
) {
	// Setup a map to lookup displayNames from the old runtime, then migrate everything

	try {
		_.each(oldRuntimes, (o) => insertOldRuntime(o.getId(), o));
		const awayFromBoard = oldSysConfig.getDeviceData().board && !newSysConfig.getDeviceData().board;
		const options = {
			includeUIState: true,
			includeNonSerializable: true,
			deviceDataMigration: awayFromBoard ? MigrationType.BOARD_TO_DEVICE : MigrationType.DEFAULT,
			lockPinmux,
		};
		const configurations = _.map(oldRuntimes, (r) => r.serialize(options));
		return captureSync(InvalidAssignmentReason.TARGET_MIGRATION,
			() => resetAndUpdateRuntimes(newSysConfig, newRuntimes, ...configurations));
	} finally {
		clearOldRuntimes();
	}
}

// For builtin products, we really want to migrate to not just a different device, but also
// a different builtin product.  Those might be the same product underneath, but we don't
// know that.  Plus, we might want to migrate to/from a regular core-pinmux case with no
// builtin product.  As such, we would need a scheme of how to convert to/from each, and
// require that all builtin products adhere to that scheme.  That's not hard, but we 
// haven't done that yet.  As such, the feature is disabled (for now) unless you are using 
// a non-builtin product (as then the builtin product wouldn't come into play)
// Both of the next two functions prevent this

export function allowMigrationTo(device: DeviceDescription, products: Product[]) {

	// Prevent migration if we're not using products (core pinmux) and would migrate to a device with
	// a builtin product

	return !device.builtInProduct || !_.isEmpty(products);
}

// Returns true if we should show a migration switch dialog at all
// Returns false if contexts exist and none of them expose the targetdb id.  This is to stop a migration dialog showing up 
// for which it would never work in CCS (legacy MCU+ SDK for instance)
// Also returns false if using a builtin product (see above generic comment)

export function isMigrationSupported(sysConfig: SysConfig) {
	const products = sysConfig.getProducts();
	const contexts = getCLIContextChoices(products, sysConfig.getDeviceData());
	const onlySystemContext = _.size(contexts) === 1 && _.first(contexts).name === systemContext;
	return _.every(products, (product) => !product.file.isBuiltIn) &&
		(onlySystemContext || _.some(sysConfig.getRuntimes(), (r) => r.getContextInfo().targetdbId));
}
