import * as _ from "lodash";
import * as React from "react";
import { Divider, IconButton, Tab, TabsActions, Tabs } from "../../imports/material-ui-imports";
import { DockRight } from "../../imports/mdi-material-ui-imports";
import { ITreeNode } from "../TreeNode";
import { ConfigStoreActions } from "../../services/configStore";
import { UserPreference } from "../../services/userPreferences";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ResourceLoader } from "../../services/resources/metaContentLoaders/resourceLoader";
import { OutputViewMgr } from "../../services/ui/outputView";
import { Validations } from "../../services/objectManagers/validations";
import { View } from "./Output";
import { Tooltip } from "../Tooltip";
import { getViewIcon } from "../ComponentUtils";
import { commonStyles } from "../styles/common";
import { Dock } from "../actions/IOutputActions";

interface IProps {
	actions: ConfigStoreActions;
	validations: Validations;
	formatter: IFormatter;
	selectedTreeNode: ITreeNode;
	userPreference: UserPreference;
	resourceLoader: ResourceLoader;
	viewMgrs: OutputViewMgr[];
	displayScriptName: boolean;
	currentView: OutputViewMgr;
}

const divStyle = { width: "100%", height: "100%", display: "flex", flexDirection: "column", overflowY: "hidden" } as const;
const contentContainerStyle = { flex: 1, height: "100%", overflowY: "auto" } as const;
const topSpanStyle = { alignItems: "center", display: "flex" };
const tabsStyle = { flex: 1 };

export class TabbedOutput extends React.Component<IProps & IGlobalServiceProps> {

	private tabsActions = React.createRef<TabsActions>();

	public override render() {
		const { viewMgrs, currentView } = this.props;
		const minWidth = `${100 / _.size(viewMgrs)}%`;
		return (
			<div style={divStyle} >
				<span style={topSpanStyle}>
					<Tabs
						value={currentView}
						onChange={this.onChange}
						indicatorColor="primary"
						style={tabsStyle}
						action={this.tabsActions}
					>
						{
							_.map(viewMgrs, (viewMgr) =>
								<Tab
									id={viewMgr.id + "Icon"}
									label={
										<Tooltip title={viewMgr.displayName}>
											{getViewIcon(viewMgr)}
										</Tooltip>
									}
									key={viewMgr.id}
									value={viewMgr}
									style={{ minWidth }}
								/>
							)
						}
					</Tabs>
					<Divider orientation="vertical" flexItem />
					<DockRightButton actions={this.props.actions} />
				</span>
				<div style={contentContainerStyle} id={currentView.id + "_card"}>
					<View {...this.props} mgr={currentView} />
				</div>
			</div >
		);
	}

	// There is a bug in the MUI Tabs component where it will not update the indicator on a resize.  The suggested 
	// workaround is to explicitly trigger it using updateIndicator.  The recommendation was to do that using 
	// useEffect, which didn't work.  That's basically the same as componentDidUpdate, which also didn't work - in both
	// cases the callback is triggered before the Tabs component re-renders.  So, I've added this below horrible hack 
	// to explicitly update it after 200ms.  It works, but it's ugly.  
	// See https://github.com/mui/material-ui/issues/9337

	public override componentDidUpdate() {
		setTimeout(() => {
			this.tabsActions?.current?.updateIndicator();
		}, 200);
	}

	private onChange = (_event: React.ChangeEvent<{}>, view: OutputViewMgr) => {
		this.props.actions.setCurrentView(view);
	}
}

const iconButtonStyle = { paddingTop: 0, marginLeft: 10, marginRight: 10 };

class DockRightButton extends React.Component<{ actions: ConfigStoreActions }> {
	public override render() {
		return (
			<Tooltip title="Dock right">
				<IconButton onClick={this.onClick} style={iconButtonStyle} id="dockRightButton">
					<DockRight style={commonStyles.mediumIcon} />
				</IconButton>
			</Tooltip>
		);
	}

	private onClick = () => this.props.actions.setOutputDocking(Dock.RIGHT);
}
