import * as _ from "lodash";
import React = require("react");
import { IFormatter } from "../services/formatting/formattingTypes";
import { LockOutline, LockOpenOutline } from "../imports/mdi-material-ui-imports";
import { Tooltip } from "./Tooltip";
import { ILinkActions } from "./actions/ILinkActions";
import { defaultFontSize } from "./styles/themes";
import { lockSelection, unlockSelection } from "../services/toolTip";
import { Solution } from "../services/solver/requirements";
import { Const } from "../services/utils";
import { FormattedMsg } from "./FormattedMsg";

interface ISelectionSupplementaryProps {
	solution: Solution;
	formatter: IFormatter;
	selectedValue: string;
	onChange: (value: string) => void;
	isHover: boolean;		// indicates if the parent control is being hovered over
	actions: ILinkActions;
	memberName: string;
	disabledReason: string; // Set to a valid string with the reason why it's disabled
}

interface IState {
	tooltipOpen: boolean;
}

export class SelectionSupplementary extends React.Component<ISelectionSupplementaryProps, IState> {
	public override state = {
		tooltipOpen: false,
	}

	public override render() {
		const locked = this.isLocked();
		const { solution } = this.props;
		return (
			// Show the tooltip if we hover over the icon
			<span
				onMouseEnter={this.showTooltip}
				onMouseLeave={this.hideTooltip}
			>
				{(locked || solution.assignedToName) &&
					< Tooltip
						title={this.getTooltipTitle()}
						placement={"right-start"}
						open={this.state.tooltipOpen}
					>
						{locked &&

							<LockOutline
								className="svgIcon lockIcon"
								style={this.getIconStyle()}
								onClick={this.unlock}
							/>
						}
						{!locked &&
							<LockOpenOutline
								className="svgIcon unlockIcon"
								style={this.getIconStyle()}
								onClick={this.lock}
							/>
						}
					</Tooltip>
				}
			</span>
		);
	}

	private getTooltipTitle() {
		const { disabledReason, formatter, actions } = this.props;

		if (disabledReason) {
			return <FormattedMsg
				message={formatter(disabledReason)}
				actions={actions}
			/>;
		} else {
			return this.isLocked() ? unlockSelection : lockSelection;
		}
	}

	// determine if this configurable is locked
	private isLocked() {
		return this.props.selectedValue !== Const.ANY;
	}

	private showTooltip = () => this.setState({ tooltipOpen: true });
	private hideTooltip = () => this.setState({ tooltipOpen: false });

	private lock = () => {
		// onMouseLeave disappears after icon changes, so we need to explicitly
		// hide the tooltip (PMUX-2631)
		this.hideTooltip();

		// if unlocked, change to {assigned value} (ie; unlocked to locked)
		this.props.onChange(this.props.solution.assignedToName);
	}

	private unlock = () => {
		if (!this.props.disabledReason) {
			// onMouseLeave disappears after icon changes, so we need to explicitly
			// hide the tooltip (PMUX-2631)
			this.hideTooltip();

			// change to "Any" (ie; locked to unlocked)
			this.props.onChange(Const.ANY);
		}
	}

	private getIconStyle() {
		let iconStyle: React.CSSProperties = {
			verticalAlign: "bottom",
			transition: "all 0.25s ease",
			position: "relative",
			top: -3,
			fontSize: defaultFontSize + 6,
		};

		// Always show icon when locked
		// Otherwise, show when hovering (over the assign box or this icon) and has solution and no error
		iconStyle = this.isLocked()
			|| (this.props.isHover
				&& this.props.solution.assignedToName
				&& !this.props.solution.errorText) ?
			{ ...iconStyle, color: "#777", cursor: "pointer" } :
			{ ...iconStyle, color: "transparent" };

		return iconStyle;
	}
}
