import * as React from "react";
import { ModalButton } from "../buttons/ModalButton";
import { BasicModal, IBasicModalProps } from "./BasicModal";
import { Alert, AlertCircle, Console } from "../../imports/mdi-material-ui-imports";
import { tiStatusColor } from "../styles/colors";
import { commonStyles } from "../styles/common";

type ConfirmModalType = "Terminal" | "Error" | "None";

interface IConfirmModalProps extends React.PropsWithChildren<Omit<IBasicModalProps, "onClose">> {
	confirmAction?: () => void;
	cancelAction?: () => void;
	confirmText?: string;
	cancelText?: string;
	hideConfirmButton?: boolean;
	disableConfirmButton?: boolean;
	type?: ConfirmModalType;
}

const buttonsPositioning: React.CSSProperties = {
	float: "right",
};

// Add confirm/cancel buttons to modal
export function ConfirmModal({
	confirmAction,
	cancelAction,
	confirmText,
	cancelText,
	hideConfirmButton,
	disableConfirmButton,
	type,
	...rest
}: IConfirmModalProps) {
	return (
		<BasicModal {...rest}
			titleIcon={<ConfirmModalIcon type={type} />}
			onClose={cancelAction}
			actions={
				<div style={buttonsPositioning}>
					{cancelAction &&
						<ModalButton id="confirmNoBtn" onClick={cancelAction} type="cancel">
							{cancelText ? cancelText : "Cancel"}
						</ModalButton>}
					{confirmAction && !hideConfirmButton &&
						<ModalButton id="confirmYesBtn" onClick={confirmAction} disabled={disableConfirmButton} type="action">
							{confirmText ? confirmText : "Confirm"}
						</ModalButton>}
				</div>
			}
		/>
	);
}

function ConfirmModalIcon({ type }: { type: ConfirmModalType }) {
	switch (type) {
		case "Error":
			return <AlertCircle style={{ ...iconStyling, color: tiStatusColor.error }} />;
		case "None":
			return null;
		case "Terminal":
			return <Console style={iconStyling} />;
		default:
			return <Alert style={{ ...iconStyling, color: tiStatusColor.warning }} />;
	}
}

const iconStyling: React.CSSProperties = {
	...commonStyles.smallIcon,
	verticalAlign: "text-bottom",
};
