import * as React from "react";
import * as _ from "lodash";
import { ClickAwayListener } from "../../imports/material-ui-imports";
import { ZoomableGraph } from "./graph/ZoomableGraph";
import { GraphLowerPane } from "./otherPanes/GraphLowerPane";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { commonStyles } from "../styles/common";
import { ResizableBorder } from "../ResizableBorder";
import { ModuleInstanceMgr } from "../../services/objectManagers/moduleInstance";
import { IGraphProps, UserGraphAction } from "./types/IGraphProps";
import { AnyMemberMgr } from "../../services/objectManagers/member";

// This component represents the middle pane view of multiple module instances represented as nodes in the graph.  The 
// tree node selection in the left pane will indicate the layout and which module instances are included.  The 
// currently selected module instance (node) will have it's configurables visible underneath the graph.  The third 
// column is by default docked into a tabbed view to the right of the configurables, but may also be expanded to take 
// up the full 3rd column if so desired.
//
// This was used originally to represent the clock tree setup, where the left pane provided multiple cut-down views of 
// the overall circuity.  It is now also being used for a drag-n-drop interface, primarily for TPLD, but likely for 
// other use cases as well.

export interface INonGraphProps extends Omit<React.ComponentProps<typeof GraphLowerPane>, "selectedTreeNode">, IGlobalServiceProps {
	heightPercent: number;
}

interface IAdditionalGraphProps {
	onClickAway: () => void;
}

const topDivDefaultStyle = {
	overflow: "hidden",
	flex: 1,
	cursor: "move",
};

// Keep a default cursor while connecting.  This is because as the mouse is being moved to establish a connection, the
// mouse may point to nothing for a moment until the connection line catches up.  We don't want the mouse to show the 
// "pan" indication during those moment or it will flicker

const topDivConnectingStyle = _.omit(topDivDefaultStyle, "cursor");

export class GraphView<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.Component<IGraphProps<InstMgr, PortMgr> & INonGraphProps & IAdditionalGraphProps> {
	public override render() {
		const {
			layout,
			nodeFactory,
			onClickNode,
			onMouseDownNode,
			onMouseDownPort,
			onClickPort,
			onMouseMove,
			onMouseUp,
			onMouseEnterEdge,
			onMouseLeaveEdge,
			onClickEdge,
			canMemoize,
			getEdgeToolTip,
			onAutoArrange,
			onClickAway,
			usedInstances,
			disabledInstances,
			actions,
			treeNode,
			highlightedEdges,
			selectedEdges,
			validations,
			errorStore,
			displayScriptName,
			formatter,
			resourceLoader,
			modalService,
			notificationService,
			theme,
			branding,
			heightPercent,
			userAction,
			setCursorMode,
			cursorMode,
		} = this.props;

		const zoomableGraph =
			<div style={userAction === UserGraphAction.CONNECTING ? topDivConnectingStyle : topDivDefaultStyle}>
				<ZoomableGraph
					layout={layout}
					treeNode={treeNode}
					nodeFactory={nodeFactory}
					canMemoize={canMemoize}
					onClickNode={onClickNode}
					onMouseDownNode={onMouseDownNode}
					onMouseDownPort={onMouseDownPort}
					onMouseMove={onMouseMove}
					onMouseUp={onMouseUp}
					onMouseEnterEdge={onMouseEnterEdge}
					onMouseLeaveEdge={onMouseLeaveEdge}
					onClickEdge={onClickEdge}
					getEdgeToolTip={getEdgeToolTip}
					onClickPort={onClickPort}
					onAutoArrange={onAutoArrange}
					usedInstances={usedInstances}
					disabledInstances={disabledInstances}
					highlightedEdges={highlightedEdges}
					selectedEdges={selectedEdges}
					actions={actions}
					validations={validations}
					errorStore={errorStore}
					displayScriptName={displayScriptName}
					formatter={formatter}
					resourceLoader={resourceLoader}
					modalService={modalService}
					notificationService={notificationService}
					theme={theme}
					branding={branding}
					userAction={userAction}
					setCursorMode={setCursorMode}
					cursorMode={cursorMode}
				/>
			</div>;

		return <div style={commonStyles.columnFlexLayout}>

			{
				// The ClickAwayListener is here vs inside ZoomableGraph as otherwise it will interfere with 
				// <WithZoom>'s ability to get a reference to the parent div in order to determine the bounding box 
				// size and thus default zoom level.  
				// The mouse/touch props are necessary to intercept clicks on configurables
			}
			{onClickAway &&
				<ClickAwayListener
					mouseEvent="onMouseDown"
					touchEvent="onTouchStart"
					onClickAway={onClickAway}
				>
					{zoomableGraph}
				</ClickAwayListener>
			}
			{!onClickAway && zoomableGraph}
			<ResizableBorder
				theme={theme}
				borderAfterChild={false}
				position={heightPercent}
				onPositionChanged={this.updateHeight}
				percentage={true}
				displayed={true}
				horizontal={false}
				showBorder={true}
				id="graphBorder"
			>
				<GraphLowerPane
					{...this.props}
				/>
			</ResizableBorder>
		</div>;
	}

	private updateHeight = (height: number) => {
		this.props.actions.setGraphHeight(height);
	}
}
