import * as React from "react";
import * as _ from "lodash";
import { GenericNode } from "../../graph/nodes/GenericNode";
import * as Layout from "../../graph/types/layoutTypes";
import { INodeProps } from "../../graph/types/nodeTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";
import { mapType } from "../../../services/utils";
import { AndNode } from "../../graph/nodes/logicGates/AndNode";
import { OrNode } from "../../graph/nodes/logicGates/OrNode";
import { XOrNode } from "../../graph/nodes/logicGates/XOrNode";
import { NandNode } from "../../graph/nodes/logicGates/NandNode";
import { nodeLayoutAdjustmentDefaults, NodeLayoutAdjustments } from "../../graph/nodes/withLayoutAdjustments";
import { BufferNode } from "../../graph/nodes/logicGates/BufferNode";
import { NotNode } from "../../graph/nodes/logicGates/NotNode";
import { NorNode } from "../../graph/nodes/logicGates/NorNode";
import { XNorNode } from "../../graph/nodes/logicGates/XNorNode";
import { OscillatorNode } from "../../graph/nodes/OscillatorNode";
import { PinNode } from "../../graph/nodes/PinNode";
import { BiDirectionalPinNode } from "../../graph/nodes/BiDirectionalPinNode";
import { GroundNode } from "../../graph/nodes/GroundNode";
import { PowerNode } from "../../graph/nodes/PowerNode";
import { LabelNode } from "../../graph/nodes/LabelNode";

// There's no point implementing this until all major UI graph features are complete
// https://jira.itg.ti.com/browse/PMUX-3504

export function canMemoize(_node: Layout.Node<ModuleInstanceMgr, PortMemberMgr>) {
	return false;
}

export function nodeFactory(props: INodeProps<ModuleInstanceMgr, PortMemberMgr>) {
	const NodeClass = getNodeClass(props.node.inst);
	return <NodeClass {...props} />;
}

export function getNodeAdjustments(inst: ModuleInstanceMgr): NodeLayoutAdjustments {
	const NodeClass = getNodeClass(inst);
	if ("extraWidth" in NodeClass) {
		return NodeClass;
	}
	return nodeLayoutAdjustmentDefaults;
}

const shapeMap = {
	square: GenericNode,
	and: AndNode,
	or: OrNode,
	buffer: BufferNode,
	xor: XOrNode,
	nand: NandNode,
	nor: NorNode,
	not: NotNode,
	xnor: XNorNode,
	oscillator: OscillatorNode,
	pin: PinNode,
	biDirectionalPin: BiDirectionalPinNode,
	power: PowerNode,
	ground: GroundNode,
	label: LabelNode,
};

const nodeClassMapper = mapType("shape", shapeMap);

function getNodeClass(inst: ModuleInstanceMgr) {
	const shape = inst.getShape();
	return nodeClassMapper(shape);
}
