import * as React from "react";
import * as _ from "lodash";
import type * as Plotly from "plotly.js-basic-dist-min";
import { Plot, Units } from "public/defs";
import { ErrorStore } from "../../services/errorStore";
import { Typography, Grid } from "../../imports/material-ui-imports";
import { asPlotlyIcon, PlotlyIcon } from "./toPlotlyIcon";
import { PreScaledPlotly } from "./PreScaledPlotly";
import { toIdealUnit, UNITS_PREFIX } from "../../services/utils/unitsUtils";

// This is a component that displays the plot data from a simulation run in a set of graphs.  It then allows the user 
// to interact with the graphs including setting points from which various relative calculations will be performed.  
// This is done by adapting the "Plot" data type to a plotly type and asking plotly to render that.  It also keeps 
// track of which sub-graphs the user wants compressed and points the user has selected on the graph to perform 
// calculations.
//
// Zooming is handled outside of this class in order to eventually facilitate reading simulation data from a file on 
// demand should the file be too large to open in node.

// cSpell:ignore customdata, pointcloud, scattergl, yaxis

interface IProps {
	plotly: typeof Plotly;
	plotData: PlotWithRange[];
	errorStore: ErrorStore;
	onZoom: (min: number, max: number) => void;
	onResetZoom: () => void;
}

export interface PlotWithRange extends Plot {
	xRange: [min: number, max: number]
}

export function SimulationResults({ plotData, errorStore, plotly, onZoom, onResetZoom }: IProps) {

	// Which graphs are compressed, and where custom markers are set.  Also, keep track if we are toggling the 
	// compress state or setting markers

	const [clickState, setClickState] = React.useState(ClickState.MARK_POINT);
	const [compressed, setCompressed] = React.useState(_.map(plotData, (d) => !!d.compress));
	const [markers, setMarkers] = React.useState([]);

	// When a new marker is selected, erase the previous one as necessary so we at most have two

	const onMarkPoint = React.useCallback((event: Plotly.PlotMouseEvent) => {
		const plotName = event.points[0].data.name;
		const plotIndex = _.findIndex(plotData, (d) => d.yAxisName === plotName);
		const point: Marker = {
			x: event.points[0].x as number,
			y: event.points[0].y as number,
			plotIndex,
		};
		setMarkers([..._.takeRight(markers), point]);
	}, [plotData, markers]);

	// Clear markers
	const onMarkedPointsReset = React.useCallback(() => setMarkers([]), []);

	// Extract which sub-graph was clicked and change it's compression state

	const onCompressPlot = React.useCallback((event: Plotly.PlotMouseEvent) => {
		const plotName = event.points[0].data.name;
		const index = _.findIndex(plotData, (d) => d.yAxisName === plotName);
		const newCompressed = _.clone(compressed);
		newCompressed[index] = !newCompressed[index];
		setCompressed(newCompressed);
	}, [plotData, compressed]);

	// Callbacks when buttons are clicked to toggle the click action

	const onToggleCompressOrMark = React.useCallback(() =>
		setClickState(clickState === ClickState.MARK_POINT ? ClickState.COMPRESS_PLOT : ClickState.MARK_POINT), [clickState]);

	// Generate the plotly data/layout/config

	const data = React.useMemo(() => toPlotlyData(plotData, markers), [plotData, markers]);
	const layout = React.useMemo(() => getLayout(plotData, compressed), [plotData, compressed]);
	const config = React.useMemo(() =>
		getConfig(onToggleCompressOrMark, onMarkedPointsReset), [onToggleCompressOrMark, onMarkedPointsReset]);

	// Render the plotly graph as well as external calculations

	return <>
		<PreScaledPlotly
			plotly={plotly}
			data={data}
			errorStore={errorStore}
			layout={layout}
			config={config}
			onClick={clickState === ClickState.MARK_POINT ? onMarkPoint : onCompressPlot}
			onResetZoom={onResetZoom}
			onZoom={onZoom}
			activeButtonTitle={clickState === ClickState.MARK_POINT ? markPointButton : compressButton}
		/>
		<div style={statisticsContainerStyle}>
			{2 === _.size(markers) &&
				<Grid
					container
					justify="center"
					spacing={10}
				>
					<Grid item>
						<Typography >{`Voltage Delta: ${format(delta("y", markers), "V", volts, 5)}`}</Typography>
					</Grid>
					<Grid item>
						<Typography >{`Time Delta: ${format(delta("x", markers), "s", seconds, 5)}`}</Typography>
					</Grid>
					<Grid item>
						<Typography >{`Frequency: ${format(1 / delta("x", markers), "Hz", frequency, 5)}`}</Typography>
					</Grid>
				</Grid>
			}
			{2 !== _.size(markers) &&
				<Grid
					container
					justify="center"
					spacing={10}
				>
					<Grid item>
						<Typography >{"Select points on the graph to view deltas"}</Typography>
					</Grid>
				</Grid>
			}
		</div>
	</>;
}

const enum ClickState {
	MARK_POINT,
	COMPRESS_PLOT,
}

interface Marker {
	x: number;
	y: number;
	plotIndex: number;
}

// Converts the meta-content's plot data into plotly format.  

function toPlotlyData(metaPlotData: Plot[], markers: Marker[]): Partial<Plotly.PlotData>[] {

	// During a hover, if customdata is an array, it will appear to the hover template as the value at the array index
	// that the value hovered on points to.  As such, to display a tooltip showing all plot data, we need customdata to
	// be an array of all the y values like this: [[plot0.y0, plot1.y0], [plot0.y1, plot1.y1], ...]

	const customdata = _.zip(..._.map(metaPlotData, "y"));

	// The data plots for each of the lines.  Note the hover template is customized as plotly will not generate a 
	// hover template correctly when there are multiple plots

	const sharedXAxis = _.first(metaPlotData).xAxisName;
	const dataPlots: Partial<Plotly.PlotData>[] = _.map(metaPlotData, (data, index) => {
		if (data.xAxisName !== sharedXAxis) {
			throw new Error("Support for multiple x-axes is not yet available");
		}

		// "scattergl" and "pointcloud" are recommended for better performance with large number of points, but:
		// 1) neither are supported in the basic plotly distro (ie we'd need the larger gl dist)
		// 2) both appear to upload slower for smaller data sets (ie you can see the plotly zoom happen before our 
		//	  update smooths it out)
		// As such, it makes more sense to use "scatter"

		return {
			type: "scatter",
			x: data.x,
			y: data.y,
			yaxis: "y" + (index + 1),
			name: data.yAxisName,
			mode: "lines",
			line: {
				width: 1,
			},
			customdata,
			hovertemplate: _.chain(metaPlotData)
				.map(({ yAxisName }, i) => {
					const label = `${yAxisName}: %{customdata.${i}:.5s}`;
					if (yAxisName === data.yAxisName) {
						return `<b>${label}</b>`;
					}
					return label;
				})
				.join("<br>")
				.value()
				+ "<extra></extra>",
		};
	});

	// The markers are a separate markers-only plot that happens to be on the same y-axis as the lines

	const markerPlots: Partial<Plotly.PlotData>[] = _.map(metaPlotData, (data, index) => {
		return {
			x: _.chain(markers).filter((m) => m.plotIndex === index).map(({ x }) => x).value(),
			y: _.chain(markers).filter((m) => m.plotIndex === index).map(({ y }) => y).value(),
			yaxis: "y" + (index + 1),
			name: data.yAxisName,
			type: "scatter",
			mode: "markers",
			marker: {
				symbol: "diamond",
				size: 6,
			},
			hoverinfo: "skip",
		};
	});

	return [
		...dataPlots,
		...markerPlots,
	];
}

// The layout sorts the sub-graphs so that compressed graphs are on top.  Compression is done via the plotly "domain"
// attribute.  The x-axis is shared and the spike line crosses all sub-graphs.

function getLayout(
	plotData: PlotWithRange[],
	compressed: boolean[],
): Partial<Plotly.Layout> {
	const domains = getDomains(compressed);
	const bottomPlotIndex = getBottomPlotIndex(compressed);
	const yAxisIndices = _.map(plotData, (_unused, index) => index ? `${index + 1}` : "");

	const yaxes = _.map(plotData, (data, index) => {
		return [
			`yaxis${yAxisIndices[index]}`,
			{
				title: data.yAxisName,
				domain: domains[index],
			},
		];
	});

	return {
		..._.fromPairs(yaxes),
		showlegend: false,
		xaxis: {
			showspikes: true, // spike lines are the horizontal line that appears on a hover
			spikemode: "across",
			spikethickness: 1,
			spikedash: "dot",
			spikesnap: "cursor",
			title: _.first(plotData).xAxisName,
			anchor: `y${yAxisIndices[bottomPlotIndex]}` as Plotly.YAxisName, // locks x-axis to bottom plot
			// Plotly is mutating the value passed in here, lets pass a copy each time
			range: [...plotData[0].xRange],
		},
		margin: { l: 150 }, // Add extra room on the left to accommodate y axis titles
		hovermode: "x",
		hoverdistance: -1, // Distance to show hover label of data point
		uirevision: 1, // Ensure that any changes we make to the plot won't undo user zoom/pan changes
	};
}

const compressedSize = .05;
const gap = .025;

function getDomains(compressed: boolean[]) {

	// Domain is fractional range between 0 and 1 with 1 representing the top of the screen and 0 the bottom. For
	// instance, [0.75, 1] represents the top quarter of the screen.
	// The goal is for compressed graphs to appear at the top with no gap, and for uncompressed to expand to  take up
	// what is left with a reasonable gap in between.

	const numCompressed = _.sumBy(compressed, (c) => c ? 1 : 0);
	const numExpanded = _.size(compressed) - numCompressed;
	const endCompressed = numCompressed ? 1 - numCompressed * compressedSize : 1 + gap;
	const expandedSize = endCompressed / numExpanded;

	let compressedIndex = 0;
	let uncompressedIndex = 0;
	return _.map(compressed, (c) => {
		if (c) {
			++compressedIndex;
			return [1 - compressedIndex * compressedSize, 1 - (compressedIndex - 1) * compressedSize];
		} else {
			++uncompressedIndex;
			return [endCompressed - uncompressedIndex * expandedSize, endCompressed - gap - (uncompressedIndex - 1) * expandedSize];
		}
	});
}

function getBottomPlotIndex(compressed: boolean[]) {
	// The bottom plot changes depending on what is compressed, as compressed plots are moved to the top
	const bottomPlotIndex = _.findLastIndex(compressed, (d) => !d);
	return bottomPlotIndex === -1 ? _.size(compressed) - 1 : bottomPlotIndex;
}

// Generates the plotly config object.  It mainly adds two toggle buttons so that you can toggle the click action 
// between compress/un-compress and marking points.

const markPointButton = "Mark point";
const compressButton = "Compress/expand plot";
const resetMarkedPointsButton = "Clear marked points";
function getConfig(
	onToggleCompressOrMark: () => void,
	onMarkedPointsReset: () => void,
): Partial<Plotly.Config> {
	return {
		modeBarButtonsToRemove: [
			"zoomIn2d",			// Zoom in and out buttons zoom both height and width, which typically is not what we want
			"zoomOut2d",		// so instead we disable and rely only on the zoom toggle which lets you draw.
			"autoScale2d",		// Auto scale does not differ from "reset axis" as we don't start zoomed.
			"lasso2d",			// Select tools won't help us as we're overriding click
			"select2d",
		],
		modeBarButtonsToAdd: [
			{
				name: "resetMarkedPoints",
				title: resetMarkedPointsButton,
				icon: asPlotlyIcon(PlotlyIcon.Eraser),
				click: onMarkedPointsReset,
			},
			{
				name: "markPoint",
				title: markPointButton,
				icon: asPlotlyIcon(PlotlyIcon.MapMarker),
				click: onToggleCompressOrMark,
				toggle: true,
				attr: "markOrCompressMode",	// If not defined, any other toggle button will toggle us
			},
			{
				name: "compressExpandPlot",
				title: compressButton,
				icon: asPlotlyIcon(PlotlyIcon.ArrowExpandVertical),
				click: onToggleCompressOrMark,
				toggle: true,
				attr: "markOrCompressMode",	// If not defined, any other toggle button will toggle us
			},
		],
		displayModeBar: true,	// Hiding it unless hovered is silly as there's nothing else on the page.
		displaylogo: false,		// Why give plotly advertizing?
		responsive: true,		// Auto-resizes on window resize.
	};
}

const statisticsContainerStyle = {
	position: "absolute",
	left: 0,
	top: 60,
	display: "flex",
	width: "100%",
	overflow: "hidden",
	pointerEvents: "none",
} as const;

// Utility to format volts/second/frequency into reasonable units
// We allow any range for V and Hz, but restrict time to no higher than "seconds" as it should go to minutes not ks

const seconds: [low: number, high: number] = [_.indexOf(UNITS_PREFIX, ""), _.indexOf(UNITS_PREFIX, "n")];
const volts: [low: number, high: number] = [0, UNITS_PREFIX.length - 1];
const frequency: [low: number, high: number] = [0, UNITS_PREFIX.length - 1];

function format(val: number, units: Units, unitRange: [low: number, high: number], precision: number) {
	const asIdealUnit = toIdealUnit({ val, units }, ...unitRange);
	return `${asIdealUnit.val.toPrecision(precision)} ${asIdealUnit.units} `;
}

function delta(axis: "y" | "x", markers: Marker[]) {
	return Math.abs(markers[0][axis] - markers[1][axis]);
}
