
// The following type and function combination allows you to verify that two types are equal.  It is used like this:
// type A = { foo: string, bar: number }
// const b = { foo: "", bar: 1 };
// const c = { foo: "", bar: "" };
// assert<Equals<A, typeof b>>();		// No error
// assert<Equals<A, typeof c>>();		// Typescript error

// Evaluates to never only if T and U are equal
export type Equals<T, U> =
	(<G>() => G extends T ? 1 : 2) extends
	(<G>() => G extends U ? 1 : 2) ? never : unknown;

// Generates a compile error if the template type is not never
export function assert<_T extends never>() { }

