import React = require("react");
import { isNode, isCCS } from "../services/platform";
import { CloudFileBrowse } from "./cloud/CloudFileBrowse";
import { LocalFileBrowse, ILocalFileBrowseProps } from "./local/LocalFileBrowse";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { EclipseFileBrowse } from "./eclipse/EclipseFileBrowse";

export class FileBrowse extends React.Component<ILocalFileBrowseProps & Pick<IGlobalServiceProps, "modalService" | "errorStore">> {
	public override render() {
		if (isNode()) {
			return <LocalFileBrowse {...this.props} />;
		} else if (isCCS()) {
			return <EclipseFileBrowse {...this.props} />;
		} else {
			return <CloudFileBrowse {...this.props} />;
		}
	}
}
