import React = require("react");
import * as _ from "lodash";
import { isNode } from "../../services/platform";

interface IBaseProps {
	accept?: string;
	id: string;
	disabled?: boolean;
	saveAs?: string; // Undefined means it's a open vs save dialog.  null means "nothing has been saved previously"
	folder?: boolean;
}

export interface ILocalFileBrowseProps extends IBaseProps {
	onChange: (fname: string) => void;
}

interface ILocalFileBrowseEventProps extends IBaseProps {
	onChangeEvent: (event: React.ChangeEvent<HTMLInputElement>) => void;
}

export class LocalFileBrowse extends React.Component<ILocalFileBrowseProps | ILocalFileBrowseEventProps> {

	private nwAttributes: HTMLInputElement & { nwdirectory?: boolean, nwsaveas?: string };

	public override componentDidMount() {
		if (isNode()) {
			if (this.props.folder) {
				this.nwAttributes.nwdirectory = true;
			} else if (!_.isUndefined(this.props.saveAs)) {
				this.nwAttributes.nwsaveas = this.props.saveAs || "untitled.syscfg";
			}
		}
	}

	public override render() {
		return (
			<span>
				<input
					disabled={this.props.disabled}
					id={this.props.id}
					accept={this.props.accept}
					type="file"
					onChange={this.getHandler()}
					onClick={() => this.nwAttributes.value = ""} // clear the value so that onChange always fires
					style={
						{ display: "none" }
					}
					ref={(elem: HTMLInputElement) => this.nwAttributes = elem}
				/>
				<label htmlFor={this.props.id} >
					{this.props.children}
				</label>
			</span>
		);
	}

	private getHandler() {
		const props = this.props;
		if (isEvent(props)) {
			return props.onChangeEvent;
		} else {
			return (e: React.ChangeEvent<HTMLInputElement>) => {
				if (e.target.value) { // happens when clearing the keys when testing with protractor
					props.onChange(e.target.value);
				}
			};
		}
	}
}

function isEvent(props: ILocalFileBrowseProps | ILocalFileBrowseEventProps): props is ILocalFileBrowseEventProps {
	return !!(props as ILocalFileBrowseEventProps).onChangeEvent;
}
