import * as _ from "lodash";
import React = require("react");
import util = require("../../services/utils");
import { DeviceView } from "./BuiltInViews/DeviceView";
import { CollapsibleCard } from "../CollapsibleCard";
import { CollapsibleView } from "../CollapsibleView";
import { UserPreferenceView } from "./BuiltInViews/UserPreferenceView";
import { HistoryView } from "./BuiltInViews/HistoryView";
import { IOSetView } from "./BuiltInViews/IOSetView";
import { ITreeNode } from "../TreeNode";
import { ConfigStoreActions } from "../../services/configStore";
import { UserPreference } from "../../services/userPreferences";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { BoardView } from "./BuiltInViews/BoardView";
import { ReferencedFileView } from "./BuiltInViews/ReferencedFileView";
import { GeneratedFileView } from "./BuiltInViews/GeneratedFileView";
import { ProblemsView } from "./BuiltInViews/ProblemsView";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ResourceLoader } from "../../services/resources/metaContentLoaders/resourceLoader";
import { CardForGenerated } from "./GeneratedViewCard";
import { OutputViewMgr, GeneratedFilesViewMgr } from "../../services/ui/outputView";
import { getViewIcon } from "../ComponentUtils";
import { Typography, Grid } from "../../imports/material-ui-imports";
import { spacingUnit } from "../styles/themes";
import { Validations } from "../../services/objectManagers/validations";

interface IProps {
	actions: ConfigStoreActions;
	validations: Validations;
	formatter: IFormatter;
	selectedTreeNode: ITreeNode;
	userPreference: UserPreference;
	resourceLoader: ResourceLoader;
	viewMgrs: OutputViewMgr[];
	displayScriptName: boolean;
}

export function Output(props: IProps & IGlobalServiceProps) {
	const { viewMgrs } = props;
	let displayedViews = _.filter(viewMgrs, (v) => v.isDisplayed());
	const expandedView = _.find(displayedViews, (v) => v.isExpanded());
	displayedViews = expandedView ? [expandedView] : displayedViews;
	const latestShownSeqNum = _.maxBy(displayedViews, (v) => v.getToggleSeqNum()).getToggleSeqNum();
	return (
		<div id="viewDevicePins" style={{ width: "100%", height: "100%" }}>
			<div id="outputDefaultView" >
				{
					_.map(displayedViews, (viewMgr) => {
						return viewMgr.isExpanded() ?
							<CollapsibleView
								key={viewMgr.id}
								id={viewMgr.id}
								heading={viewMgr.getCardHeading()}
								iconDecorator={getViewIcon(viewMgr)}
								onClose={() => {
									props.actions.setOutputViewExpansion(viewMgr, false);
									props.actions.toggleOutputView(viewMgr);
								}}
								toggleExpand={() => props.actions.setOutputViewExpansion(viewMgr, false)}
								hideHeading={viewMgr instanceof GeneratedFilesViewMgr && !!viewMgr.getPreviewFileStatus()}
							>
								<View {...props} mgr={viewMgr} key={viewMgr.id} />
							</CollapsibleView> :
							< CollapsibleCard
								key={viewMgr.id}
								id={viewMgr.id + "_card"}
								heading={viewMgr.getCardHeading()}
								iconDecorator={getViewIcon(viewMgr)}
								onClose={() => {
									props.actions.setOutputViewExpansion(viewMgr, false);
									props.actions.toggleOutputView(viewMgr);
								}}
								toggleExpand={() => props.actions.setOutputViewExpansion(viewMgr, true)}
								scrollIntoView={latestShownSeqNum !== -1 && latestShownSeqNum === viewMgr.getToggleSeqNum()}
								formatter={props.formatter}
								actions={props.actions}
							>
								<View {...props} mgr={viewMgr} key={viewMgr.id} />
							</CollapsibleCard>;
					})
				}
			</div>
		</div >
	);
}

export function View(props: IProps & IGlobalServiceProps & { mgr: OutputViewMgr }) {
	const { mgr } = props;
	switch (mgr.type) {
		case "history":
			return <HistoryView {...props} mgr={mgr} />;
		case "meta":
			return <CardForGenerated {...props} mgr={mgr} formatter={mgr.getFormatter()} />;
		case "preference":
			return <UserPreferenceView {...props} mgr={mgr} />;
		case "code":
			return <GeneratedFileView
				mgr={mgr}
				actions={props.actions}
				userPreference={props.userPreference}
				resourceLoader={props.resourceLoader}
				modalService={props.modalService}
				notificationService={props.notificationService}
				errorStore={props.errorStore}
				theme={props.theme}
				branding={props.branding}
				currentHistoryPoint={props.actions.getHistory().getCurrentPoint()}
				mgrKey={mgr.getKey()}
			/>;
		case "refs":
			return <ReferencedFileView {...props} mgr={mgr} />;
		case "ioSets":
			return <IOSetView
				{...props}
				// Provide a unique key each time to force IOSetList to re-update each time
				// See the heading "Recommendation: Fully uncontrolled component with a key" at
				// https://reactjs.org/blog/2018/06/07/you-probably-dont-need-derived-state.html
				key={_.uniqueId()}
				mgr={mgr}
			/>;
		case "board":
			return <BoardView
				{...props}
				mgr={mgr}
			/>;
		case "device":
			return <DeviceView
				{...props}
				mgr={mgr}
				deviceData={mgr.getDeviceData()}
			/>;
		case "problems":
			return <ProblemsView
				{...props}
				formatter={mgr.getFormatter()}
				mgr={mgr}
			/>;
		default:
			util.assertUnreachable(mgr);
	}
}

export function getStyledHeading(heading: string | string[]) {
	return _.isString(heading) ?
		<Typography
			variant="body2"
			style={{ whiteSpace: "nowrap", paddingLeft: spacingUnit }}>{heading}
		</Typography> :
		<Grid
			container
			direction="column"
		>
			{
				_.map(heading, (h, i) => {
					return <Grid item key={i}>
						<Typography variant="body2">{h}</Typography>
					</Grid>;
				})
			}
		</Grid>;
}
