import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../../graph/styling/graphStyles";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";
import * as Layout from "../../graph/types/layoutTypes";
import { IStatusNodeProps, StatusNode } from "../../graph/nodes/StatusNode";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";

// A square box with the current frequency displayed inside

export function FrequencyLabelNode(props: Omit<IStatusNodeProps<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>, "text"> & ClassesType) {
	return <StatusNode {...props} text={getFrequency(props.node)} />;
}

function getFrequency(node: Layout.Node<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>) {
	const pinMemberMgr = _.find(node.inst.memberMgrs, (m) => m instanceof PinFrequencyConfigurableMgr) as PinFrequencyConfigurableMgr;
	return pinMemberMgr.getValueAsString();
}
