import * as React from "react";
import * as _ from "lodash";
import { Typography } from "../imports/material-ui-imports";
import { ErrorStore } from "../services/errorStore";
import { ExceptionText } from "./ExceptionText";
import { ATheme } from "./styles/themes";

interface IState {
	error: Error;
}

interface IChildProps {
	errorStore: ErrorStore;
}

interface IProps {
	theme: ATheme;
	children: React.ReactNode | ((props: IChildProps) => React.ReactNode);
	id: string;
}

export class InlineErrorBoundary extends React.Component<IProps, IState> {

	private readonly errorStore = new ErrorStore();

	constructor(props: IProps) {
		super(props);
		this.state = { error: null };
	}

	public override componentDidCatch(error: Error) {
		this.setState({ error });
	}

	public override componentDidUpdate(prevProps: Readonly<IProps>) {
		if (this.state.error && this.props.id !== prevProps.id) {
			this.setState({ error: null });
		}
	}

	public override componentDidMount() {
		this.errorStore.onException().addListener(this.handleException);
	}

	public override componentWillUnmount() {
		this.errorStore.onException().removeListener(this.handleException);
	}

	public override render() {
		const { theme, children } = this.props;
		const { error } = this.state;
		if (error) {
			return [
				<Typography variant="subtitle2" key="header" >
					Unable to render selection
				</Typography>,
				<ExceptionText key="exception" theme={theme} exception={error} />,
			];
		}
		return _.isFunction(children) ? children({ errorStore: this.errorStore }) : children;
	}

	private handleException = (error: Error) => {
		this.setState({ error });
	}
}
