import * as React from "react";
import { ClassesType } from "../styling/graphStyles";
import { NodeLabels } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { typedMemo } from "../../typedMemo";
import { Ports } from "../ports/Ports";
import { INodeProps } from "../types/nodeTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// Any node that isn't one of the specific types with custom rendering

export type IGenericNodeProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	= Omit<INodeProps<InstMgr, PortMgr>, "actions">;

export const GenericNode = typedMemo(function GenericNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	{
		node,
		onClickNode,
		onMouseDownNode,
		onMouseDownPort,
		onMouseUpPort,
		onClickPort,
		displayScriptName,
		classes,
		children,
		validations,
		formatter,
		cursorMode,
	}: React.PropsWithChildren<IGenericNodeProps<InstMgr, PortMgr> & ClassesType>
) {
	return (
		<PositionedNode
			node={node}
			onClick={onClickNode}
			onMouseDown={onMouseDownNode}
			className={classes.genericNode}
			validations={validations}
			cursorMode={cursorMode}
			formatter={formatter}
		>
			<NodeLabels node={node} displayScriptName={displayScriptName} classes={classes} />
			<Ports
				node={node}
				classes={classes}
				onMouseDownPort={onMouseDownPort}
				onMouseUpPort={onMouseUpPort}
				cursorMode={cursorMode}
				onClickPort={onClickPort} />
			{children}
		</PositionedNode>
	);
});
