import * as React from "react";
import * as _ from "lodash";
import { IFormatter } from "../services/formatting/formattingTypes";

type Action = "remove" | "copy";

interface IProps {
	formatter: IFormatter;
	reason: string;
	type: Action;
}

export class CannotDoActionPopup extends React.Component<IProps> {
	public override render() {
		const message = <span>Cannot be {this.props.type}:</span>;
		return (
			<span>
				{message}<br />
				{
					_.isString(this.props.reason) &&
					<CannotDoActionLine
						text={this.props.formatter(this.props.reason).toString()}
					/>
				}
			</span>
		);
	}
}

class CannotDoActionLine extends React.Component<{ text: string }> {
	public override render() {
		return (
			<React.Fragment>
				&nbsp;&nbsp;
				<span>
					{this.props.text}
				</span>
				< br />
			</React.Fragment>
		);
	}
}
