import * as React from "react";
import * as _ from "lodash";
import { Card, CardContent, Tab, Tabs } from "../../imports/material-ui-imports";
import { CView, IConfigProps } from "./ModuleInstance";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ContainerNode } from "../../services/objectManagers/viewNodes";
import { Tooltip } from "../Tooltip";
import { NodeStatusDecorator } from "../Decorators";
import { TabGroup } from "../../services/objectManagers/tabGroup";

interface IProps {
	tabGroup: TabGroup;
	readOnly: boolean;
}

const statusDecoratorStyle = { float: "left" } as const;

export class TabContainer extends React.Component<IProps & IConfigProps & IGlobalServiceProps> {
	public override render() {
		const { tabGroup, ...rest } = this.props;
		const currentNode = tabGroup.getCurrentTab();

		const titleNode = currentNode.getTitleNode();
		const children = currentNode.getChildren();
		let sharedInstanceSubItemPath;
		if (titleNode && titleNode.type === "sharedAssignLeafNode") {
			children.unshift(titleNode);
			sharedInstanceSubItemPath = this.props.focusedSubItemPath;
		}

		const currentNodeChildren = currentNode.getUINodes();

		return <Card variant="outlined" style={{ paddingTop: "3px", paddingBottom: "3px" }}>
			<CardContent>
				<Tabs
					variant="scrollable" indicatorColor="primary"
					value={currentNode}
					onChange={this.onChange}
					scrollButtons="auto"
					style={{ paddingBottom: "5px" }} >
					{
						_.map(tabGroup.getNodes(), (node) => {
							return (<Tab
								id={node.getKey() + "_tab"}
								key={node.getKey()}
								label={
									<div>
										<NodeStatusDecorator
											containerStyle={statusDecoratorStyle}
											id="statusDecorators"
											summary={node.getValidationsummary(this.props.validations)}
										/>
										<Tooltip
											title={node.getSecondaryHeading()}
											placement="top">
											{node.getHeading()}
										</Tooltip>
									</div>

								}
								wrapped
								value={node} />);
						})
					}
				</Tabs>
				{
					<span>
						<CView
							{...rest}
							readOnly={this.props.readOnly || currentNode.isReadOnly()}
							viewNodes={currentNodeChildren?.singleNodes}
							focusedSubItemPath={currentNode.matchSubItemPath(this.props.focusedSubItemPath)[1]}
							sharedInstanceSubItemPath={sharedInstanceSubItemPath}
							tabGroup={currentNodeChildren?.tabGroup}
						/>
					</span>
				}
			</CardContent>
		</Card >;
	}

	private onChange = (_event: React.ChangeEvent<{}>, value: ContainerNode) => {
		this.props.actions.updateTab(this.props.tabGroup, value);
		this.forceUpdate();
	}
}
