import * as _ from "lodash";
import { DiscoveryData } from "../discoveryData";
import { MigrationOptions } from "./migrationOptions";
import { findMigrationDialogInfoFn } from "./metaContentMigrationInfo";
import { getIntersectingTargetInfo } from "../product/available";
import { MigrationDialogInfo } from "public/defs";
import { DiscoveryJSON } from "dataInterfaces";
import { SysConfig } from "../sysConfig";
import { ResourceType } from "../resources/metaContentLoaders/resourceLoader";
import { FormatStyle } from "../formatting/formattingTypes";
import { ILinkActions } from "../../components/actions/ILinkActions";

// This factory accepts the first registered getMigrationDialogInfo meta-content callback function
// registered.  Then, it will call it and return the necessary data for the migration switch dialog
// to use

export function createMigrationOptions(sysConfig: SysConfig, discoveryData: DiscoveryJSON,
	actions: ILinkActions, runtimes = sysConfig.getRuntimes()) {
	const { getMigrationDialogInfo, ...rest } = findMigrationDialogInfoFn(sysConfig);
	const products = sysConfig.getProducts();
	return new MigrationOptions(
		getMigrationDialogInfo ? getMigrationDialogInfo() : defaultMigrationFunction(),
		new DiscoveryData(discoveryData),
		products,
		getIntersectingTargetInfo(products, discoveryData),
		{ resourceType: ResourceType.CODE, formatter: sysConfig.getMessageFormatter({ style: FormatStyle.UI }), actions: actions, ...rest },
		_.map(runtimes, (r) => r.getName()),
		sysConfig.getDeviceData(),
	);
}

function defaultMigrationFunction(): MigrationDialogInfo {
	return {
		extraMarkdown: "",
		isValid: () => ({}),
	};
}
