import * as React from "react";
import * as _ from "lodash";
import { Plus, Minus, ImageFilterCenterFocus, FileTreeOutline } from "../../../../imports/mdi-material-ui-imports";
import { ButtonGroup, Tooltip } from "../../../../imports/material-ui-imports";
import { IFZoomFloatingContentProps } from "../../../higherOrderComponents/WithZoom";
import { ButtonGroupIconButton } from "./ButtonGroupIconButton";
import { generateToolTipProps } from "../../../Tooltip"; // ButtonGroup prevents direct use of our template wrapper

interface IProps extends IFZoomFloatingContentProps {
	onAutoArrange: () => void;
}

export function FloatingNavigation({ zoomIn, zoomOut, reset, onAutoArrange }: IProps) {
	return <ButtonGroup orientation="vertical" variant="contained" >
		<ButtonGroupIconButton onClick={zoomIn} >
			<Tooltip {...generateToolTipProps({ title: "Zoom In" })}>
				<Plus fontSize="small" color="primary" />
			</Tooltip>
		</ButtonGroupIconButton>
		<ButtonGroupIconButton onClick={zoomOut} >
			<Tooltip {...generateToolTipProps({ title: "Zoom Out" })}>
				<Minus fontSize="small" color="primary" />
			</Tooltip>
		</ButtonGroupIconButton>
		<ButtonGroupIconButton onClick={reset} >
			<Tooltip {...generateToolTipProps({ title: "Recenter" })}>
				<ImageFilterCenterFocus fontSize="small" color="primary" />
			</Tooltip>
		</ButtonGroupIconButton>
		{onAutoArrange &&
			<ButtonGroupIconButton onClick={onAutoArrange} id="autoArrangeButton" >
				<Tooltip {...generateToolTipProps({ title: "Auto arrange" })}>
					<FileTreeOutline fontSize="small" color="primary" />
				</Tooltip>
			</ButtonGroupIconButton>
		}
	</ButtonGroup>;
}
