import {
	ExternalExecutableConfigurable,
	ExternalExecutableConfigurableResult,
	ExternalLaunchParams as MetaLaunchParams,
} from "public/defs";
import { launchExternalExecutable } from "../../externalExecutable";
import { IModalService } from "../../IModalService";
import { allowPathVisibility } from "../../pathsVisibility";
import { isCloud, isCCS } from "../../platform";
import { disableScriptingForCallback } from "../../scripting/scriptingGuard";
import { Validations } from "../validations";
import { ButtonClickOptions, ButtonConfigurableMgr } from "./buttonConfigurableMgr";

export interface ExternalLaunchParams extends MetaLaunchParams {
	filePath?: string;
}

export class ExternalExecutableConfigurableMgr
	extends ButtonConfigurableMgr<ExternalExecutableConfigurableResult, ExternalExecutableConfigurable> {

	public getClickResultImpl(
		productPath: string, modalService: IModalService, options: ButtonClickOptions
	): Promise<ExternalExecutableConfigurableResult> {
		const launchParams = this.getLaunchParams(options?.filePath);
		if (this.def.displayTerminal) {
			return launchExternalExecutable(productPath, launchParams, this.def.displayTerminal, modalService, options).response;
		} else {
			return modalService.showProgressDuring(
				"Running external process...",
				() => launchExternalExecutable(productPath, launchParams, this.def.displayTerminal, modalService, options).response,
			);
		}
	}

	public getLaunchParams(filePath?: string) {
		const launchParams = allowPathVisibility(() => disableScriptingForCallback(() => {
			return this.def.onLaunch(this.getParentRuntimeObj(), this.getPopupMgr()?.managedObject);
		}));
		return { ...launchParams, filePath };
	}

	protected override getDisabledReason(validations: Validations) {
		if (isCloud()) {
			return "Action unavailable in online version";
		} else if (isCCS() && this.def.displayTerminal && (!window.eclipseSpawn2 || !window.eclipseWriteToStdin)) {
			return "Action unavailable in this version of eclipse";
		}
		return super.getDisabledReason(validations);
	}
}
