import React = require("react");
import util = require("../services/utils");
import { Col1 } from "./Col1";
import { Col2 } from "./Col2";
import { ConfigStore } from "../services/configStore";
import { IFormatter } from "../services/formatting/formattingTypes";
import { Tab } from "../services/tabs";
import { UserPreference } from "../services/userPreferences";
import { commonStyles } from "./styles/common";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { ResourceLoader } from "../services/resources/metaContentLoaders/resourceLoader";
import { ErrorStore } from "../services/errorStore";
import { NavigationHistory } from "../services/navigationHistory";
import { OutputViewMgr } from "../services/ui/outputView";
import { UIContextSelection } from "./actions/IContextActions";
import { ContextSelector } from "./ContextSelector";
import { Validations } from "../services/objectManagers/validations";
import { isCCS } from "../services/platform";
import { Dock } from "./actions/IOutputActions";
import { IconMenu } from "./IconMenu";
import { TabName } from "../services/tabNames";
import { SimulationView } from "./simulation/SimulationView";
import { SimulationTreeNode } from "../services/simulation/simulationTreeNode";

interface IState {
	searchText: string;
	tabs: Tab[];
	selectedTab: Tab;
	formatter: IFormatter;
	validations: Validations;
	arePowerDomainSettingsEnabled: boolean;
	navHistory: NavigationHistory;
	userPreference: UserPreference;
	resourceLoader: ResourceLoader;
	col1Width: number;
	col1Displayed: boolean;
	col3Width: number;
	clockTreeHeight: number;
	focusedSubItemPath: string[];
	showUsed: boolean;
	showPinTable: boolean;
	viewMgrs: OutputViewMgr[];
	currentView: OutputViewMgr;
	outputDocking: Dock;
	contextSelection: UIContextSelection;
	simulationProgress: number;
}

interface IProps {
	configStore: ConfigStore;
	showPreferredVoltage: boolean;
	errorStore: ErrorStore;
}

export class Config extends React.Component<IProps & IGlobalServiceProps, IState> {
	constructor(props: IProps & IGlobalServiceProps) {
		super(props);
		this.state = this.getStateFromConfigStore();
	}

	public override render() {
		const isSimulation = this.state.selectedTab.getTitle() === TabName.SIMULATION;
		return (
			<React.Fragment>
				<ContextSelector
					contextSelection={this.state.contextSelection}
					actions={this.props.configStore}
				/>
				<div style={{ width: "100%", minWidth: 0, flex: 1, overflowY: "auto" }}>
					<span style={commonStyles.columnFlexLayout}>
						<div style={commonStyles.rowFlexLayout}>
							<IconMenu {...this.props} actions={this.props.configStore} {...this.state} />
							{!isSimulation &&
								<StandardView {...this.props} {...this.state} />
							}
							{isSimulation &&
								<SimulationView
									theme={this.props.theme}
									fetchSimData={this.props.configStore.getFetchSimDataFunc()}
									simulationTreeNode={this.state.selectedTab.getSelectedNode() as SimulationTreeNode}
									progress={this.state.simulationProgress}
									setProgress={this.progressCallback}
									branding={this.props.configStore.getBranding()}
								/>
							}
						</div>
					</span>
				</div>
			</React.Fragment>
		);
	}

	public override componentDidUpdate?(prevProps: Readonly<IProps & IGlobalServiceProps>) {
		if (this.props.configStore !== prevProps.configStore) {
			prevProps.configStore.onAnyChange().removeListener(this.listener);
			this.props.configStore.onAnyChange().addListener(this.listener);
		}
	}

	public override componentDidMount() {
		this.props.configStore.onAnyChange().addListener(this.listener);
		this.setState(this.getStateFromConfigStore());
		document.addEventListener("keydown", this.handleKeydown, false);
	}

	public override componentWillUnmount() {
		this.props.configStore.onAnyChange().removeListener(this.listener);
		document.removeEventListener("keydown", this.handleKeydown);
	}

	private progressCallback = (val: number | string) => this.props.configStore.setSimulationProgress(Number(val));

	private listener = () => {
		this.setState(this.getStateFromConfigStore());
	}

	private handleKeydown = (event: KeyboardEvent) => {
		if (event.ctrlKey) {
			if ("z" === event.key) {
				util.assertNeverThrows(this.props.errorStore, this.props.configStore.getHistory().undo());
				event.preventDefault();
			} else if ("y" === event.key) {
				util.assertNeverThrows(this.props.errorStore, this.props.configStore.getHistory().redo());
				event.preventDefault();
			} else if (isCCS() && "s" === event.key) {
				// Only handle ctrl + s in eclipse
				// ctrl + s is a handled along with other short cuts via the file menu in cloud/standalone
				this.props.configStore.saveProject();
				event.preventDefault();
			}
		}
	}

	private getStateFromConfigStore(): IState {
		return getStateFromConfigStore(this.props.configStore);
	}
}

export function StandardView({ configStore, userPreference, ...rest }: IProps & IState & IGlobalServiceProps) {
	const displayScriptName = userPreference.getPreferences().displayConfigurablesScriptingNames.getValue();
	return <>
		<Col1 {...rest} actions={configStore} displayScriptName={displayScriptName} />
		<Col2 {...rest} actions={configStore} displayScriptName={displayScriptName} userPreference={userPreference} />
	</>;
}

export function getStateFromConfigStore(configStore: ConfigStore): IState {
	return {
		tabs: configStore.getTabs(),
		selectedTab: configStore.getSelectedTab(),
		searchText: configStore.getSearchText(),
		formatter: configStore.getMessageFormatter(),
		validations: configStore.getValidations(),
		arePowerDomainSettingsEnabled: configStore.arePowerDomainSettingsEnabled(),
		navHistory: configStore.getNavHistory(),
		userPreference: configStore.getUserPreference(),
		resourceLoader: configStore.getResourceLoader(),
		col1Width: configStore.getCol1Width(),
		col1Displayed: configStore.getCol1Displayed(),
		col3Width: configStore.getCol3Width(),
		clockTreeHeight: configStore.getClockTreeHeight(),
		focusedSubItemPath: configStore.getFocusedSubItem(),
		showUsed: configStore.getPinmuxUIOptions().showUsed,
		showPinTable: configStore.getPinmuxUIOptions().showPinTable,
		viewMgrs: configStore.getViewMgrs(),
		currentView: configStore.getCurrentView(),
		outputDocking: configStore.getOutputDocking(),
		contextSelection: configStore.getContextSelection(),
		simulationProgress: configStore.getSimulationProgress(),
	};
}
