import * as _ from "lodash";
import { ParsedArg, ParsedArgs, ArgTypes } from "./argTypes";
import { CompilerType } from "public/runtime";
import { ThemeType } from "../../components/styles/themes";

function joinArgNameValue(
	arg: ParsedArg<string>
		| ParsedArg<CompilerType>
		| ParsedArg<boolean>
		| ParsedArg<ThemeType>,
) {
	if (_.isBoolean(arg.value)) {
		return [arg.userArgName];
	}
	return [arg.userArgName, arg.value];
}

export function toCLIArgs(parsedArgs: ParsedArgs) {
	const { script, ...rest } = parsedArgs;
	const initialArgs = _.flatMap(rest, (argValue) => {
		if (_.isArray(argValue)) {
			return _.flatMap(argValue, (v) => joinArgNameValue(v));
		} else {
			return joinArgNameValue(argValue);
		}
	});

	const scriptSpecificArgs = _.flatMap(script, (args) => {
		const argsWithScriptFirst = _.partition(args, (argValue) => _.isArray(argValue) ? false : argValue.userArgName === "--script");
		return _.chain(argsWithScriptFirst)
			.flatten()
			.flatMap((argValue) => {
				if (_.isArray(argValue)) {
					return _.flatMap(argValue, (v) => joinArgNameValue(v));
				} else {
					return joinArgNameValue(argValue);
				}
			})
			.value();
	});

	return [...initialArgs, ...scriptSpecificArgs];
}

export function argsToStringArray(args: ArgTypes) {
	return _.chain(args)
		.omitBy((value) => {
			return (
				(
					(_.isArray(value) || _.isString(value)) && _.isEmpty(value)
				)
				||
				(
					_.isBoolean(value) && !value
				)
			);
		})
		.map((value, arg) => {
			if (_.isArray(value)) {
				return _.flatMap(value, (v) => [`--${arg}`, `${v}`]);
			} else if (_.isBoolean(value)) {
				return [`--${arg}`];
			} else {
				return [`--${arg}`, `${value}`];
			}
		})
		.flatten()
		.value();
}
