import * as _ from "lodash";
import { Runtime } from "../resources/runtime";
import { Statement, BoosterPackAssignment, Assignment, quoteStrings } from "./serialize";
import { System } from "public/runtime";
import { scriptTemplate } from "./toScript";
import { SuggestSolutionMgr } from "../objectManagers/assignMembers";
import { cleanStaleModules } from "./runScript";
import { SysConfig } from "../sysConfig";
import { AccessSpecification } from "../deprecatedAccessGuard";
import { updateRuntimeWithScript } from "./runtimeUtils";

// Unlike runScript, this function lets you create and execute a script against an existing runtime
// that is already configured with the correct device and product data.
// ie it will clear out all user-level configuration, and apply the configuration applied.
// It does have an option to add/remove a board to/from the configuration however

export function resetAndUpdateRuntimes(sysConfig: SysConfig, runtimes: Runtime[], ...configuration: Statement[][]) {
	const statementsPerRuntime = fixAddHardware(configuration);

	// Generate the script to run

	const scriptSource = _.map(statementsPerRuntime, (statements) => scriptTemplate(statements));

	// Remove all existing modules/interfaces, run the specified script(s)

	resetAndUpdateRuntimeWithScript(sysConfig, runtimes, scriptSource);
}

export function resetAndUpdateRuntimeWithScript(
	sysConfig: SysConfig, runtimes: Runtime[], scriptsSource: string[],
	deprecatedAccess: AccessSpecification = {}) {

	// Clear any configuration that currently exists

	sysConfig.reset();

	// Clear suggest solution option, so we know if any calls were made to set $suggestSolution are set

	SuggestSolutionMgr.optionSet = false;

	// Run the scripts

	_.zipWith(runtimes, scriptsSource, (runtime, scriptSource) => updateRuntimeWithScript(runtime, scriptSource, deprecatedAccess));
	cleanStaleModules(sysConfig);
}

// We don't want to re-create the board when we restore the serialized statements, so we have to
// change any addHardware() calls into something that will fetch the boosterpack being added and
// return those components un-namespaced (the way addHardware() does)

function fixAddHardware(statementsPerRuntime: Statement[][]) {
	return _.map(statementsPerRuntime, (statements) => _.map(statements, (statement) => {
		if (statement instanceof BoosterPackAssignment) {

			// A typed function that returns the components of a booster pack without the namespace
			// Assumes runtime lodash is the same as the one we are using in the tool

			const fetchBP = (system: System, definition: string, attachedTo: string, lodash: typeof _) => {
				return {
					components: lodash.chain(lodash.values(system.deviceData.board.components))
						.filter((component) => component.source.definition === definition)
						.filter((component) => component.source.attachedTo === attachedTo)
						.mapKeys((component) => lodash.last(lodash.split(component.name, "/")))
						.value(),
				};
			};

			// That function is type-safe, so we know it's correct.  Now use it's source to replace
			// the call to addHardware()

			const { definition, attachedTo } = statement.source;
			const rvalue = `(${fetchBP.toString()})(system, ${quoteStrings(definition)}, ${quoteStrings(attachedTo)}, _)`;
			return new Assignment(statement.lvalue, rvalue);
		}
		return statement;
	}));
}
