import * as _ from "lodash";
import { EnumerationConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { AccessType, validateDeprecatedAccess } from "../../deprecatedAccessGuard";
import { FormattersMap } from "../../formatting/formattersMap";
import { SetSource } from "../member";
import { AObjectMgr } from "../object";
import { IOptions } from "../options";
import {
	BaseEnumerationConfigurableMgr,
	unknownOptionError,
} from "./baseEnumerationConfigurableMgr";
import { ConfigurableComponent } from "./configurableComponent";

export class EnumerationConfigurableMgr<
	RuntimeObjectType extends RuntimeObject = RuntimeObject,
	T extends number | string = string>
	extends BaseEnumerationConfigurableMgr<T, T, RuntimeObjectType, EnumerationConfigurable<T>>
	implements IOptions<T> {

	public readonly ui = ConfigurableComponent.CEnumerationConfigurable;

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		def: EnumerationConfigurable<T>,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);

		this.validateValue(this.value);
	}

	public getSelectedOption() {
		return this.value;
	}

	protected override getCurrentSelections() {
		return [this.value];
	}

	protected override validateValue(newVal: T, forceWrite?: boolean, source?: SetSource) {

		// Extend the base preSet method to validate and map input value to an option. By default
		// input value must exactly match the name of one of the options. However, this function
		// adds hooks to allow map child classes to map via any criteria. This is needed to support ease of 
		// use in scripting. For example pin names on some devices can be fairly long, it is desired that 
		// user specify only part of the name in the script which if possible 
		// should be mapped to th

		// validate type

		super.validateValue(newVal, forceWrite, source);

		// is valid option

		const val = this.transform(newVal);
		if (!this.isDynamic()) {
			if (!_.some(this.getOptions(), (o) => o.name === val)) {
				unknownOptionError(newVal, this.validOptions());
			}
		}
	}

	protected override transform(val: T): T {
		// check if it is a legacy name
		// class may not be constructed, so legacyNamesMap might not exist
		if (this.legacyNamesMap?.has(val)) {
			validateDeprecatedAccess(AccessType.WRITE);
			return this.legacyNamesMap.get(val);
		}
		return val;
	}

	protected validOptions() {
		return _.map(this.getOptions(), (o) => o.name);
	}
}

