import { ModuleRequirement } from "public/defs";
import { Runtime } from "../../resources/runtime";
import { StaticModuleInstanceMgr } from "../staticModuleInstance";
import { ViewNode, createUIStatements } from "../viewNodes";
import { SerializationOptions } from "../../scripting/toScript";
import { InstanceMemberMgr } from "./instanceMemberMgr";
import { ModuleInstanceMgr } from "../moduleInstance";

export class ModuleMemberMgr extends InstanceMemberMgr<StaticModuleInstanceMgr, ModuleRequirement> {

	private readonly disposeSharedRef: () => void;

	constructor(
		runtime: Runtime,
		valueObjectMgr: StaticModuleInstanceMgr,
		def: ModuleRequirement,
		instanceMgr: ModuleInstanceMgr,
		collapsed = true) {

		super(valueObjectMgr, runtime, def, instanceMgr, { collapsed });
		this.disposeSharedRef = valueObjectMgr.addSharedBy(instanceMgr);
	}

	// This exists as an internal reference and shouldn't be visible to meta-content

	public override excludeFromOwnProperties() {
		return true;
	}

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {

		if (!options.includeUIState) {
			return [];
		}

		return createUIStatements(parentIdentifier, this);
	}

	public override isUserModified() {
		// Only members that are owned by an instance affect its user modified state
		return false;
	}

	public override getHeading(): string {
		return this.valueObjectMgr.getModuleMgr().module.displayName;
	}

	public override getSecondaryHeading(): string {
		return this.valueObjectMgr.getModuleMgr().module.description;
	}

	public override remove(): void {
		this.clearInvalidAssignment();
		this.disposeSharedRef();
	}

	public override getChildren(): ViewNode[] {
		return this.valueObjectMgr.getStaticContainerViewNodes();
	}
}
