import * as bigInt from "big-integer";
import * as _ from "lodash";
import { Units, NumberAndUnits, UnitsPrefix, BaseUnits } from "public/defs";

// Units are arranged from largest to smallest
// we leverage their position in array to perform unit conversions
export const UNITS_PREFIX: UnitsPrefix[] = ["G", "M", "k", "", "m", "u", "n", "p"];
const BASEUNIT_TO_MULTIPLIER: { [unit in BaseUnits]: number } = {
	Hz: 1000,
	s: 1000,
	V: 1000,
	A: 1000,
	F: 1000,
	H: 1000,
	Ω: 1000,
	B: 1024,
};
const BASE_UNITS: BaseUnits[] = ["Hz", "s", "V", "A", "F", "H", "Ω", "B"];
const zeroIndex = _.indexOf(UNITS_PREFIX, "");
const UNITS_CONVERSION = new Map<UnitsPrefix, number>(_.map(UNITS_PREFIX, (prefix, index) => [prefix, zeroIndex - index]));

export function isUnitsPrefix(unitsPrefix: string): unitsPrefix is UnitsPrefix {
	return _.includes(UNITS_PREFIX, unitsPrefix);
}

function isBaseUnits(baseUnits: string): baseUnits is BaseUnits {
	return _.includes(BASE_UNITS, baseUnits);
}

export function getUnitsPrefix(u: Units): UnitsPrefix {
	if (isBaseUnits(u)) {
		return "";
	}
	return u.substring(0, 1) as UnitsPrefix;
}

export function getBaseUnits(u: Units): BaseUnits {
	if (isBaseUnits(u)) {
		return u;
	}
	return u.substring(1) as BaseUnits;
}

function isUnits(u: string): u is Units {
	if (isBaseUnits(u)) {
		return true;
	} else if (isUnitsPrefix(u.substring(0, 1)) && isBaseUnits(u.substring(1))) {
		return true;
	} else {
		return false;
	}
}

function isNumberAndUnits(val: any): boolean {
	if (val.val === undefined || typeof val.units != "string") {
		return false;
	} else if (!isUnits(val.units)) {
		return false;
	}

	return true;
}

export function isNumberAndUnitsNumber(val: any): val is NumberAndUnits<number> {
	return isNumberAndUnits(val) && typeof val.val === "number";
}

function coreConvertTo<T extends number | bigInt.BigInteger>(
	input: NumberAndUnits<T>, outputUnits: Units | UnitsPrefix, multiply: (a: T, b: number) => T
) {
	// Get multiplier corresponding to the base units
	// ie. we know 1kHz = 1000Hz (multiplier is 1000), but 1kB = 1024B (multiplier is 1024) 
	const baseUnit = getBaseUnits(input.units);
	const multiplier = BASEUNIT_TO_MULTIPLIER[baseUnit];
	// Find the amount of shift to perform based on unit prefix
	const unitIn = getUnitsPrefix(input.units);
	const unitOut = isUnitsPrefix(outputUnits) ? outputUnits : getUnitsPrefix(outputUnits);
	const shift = UNITS_CONVERSION.get(unitIn) - UNITS_CONVERSION.get(unitOut);
	// Convert based on unit prefix and multiplier
	return multiply(input.val, Math.pow(multiplier, shift));
}

export function numberConvertTo(input: NumberAndUnits<number>, outputUnits: Units | UnitsPrefix) {
	return coreConvertTo(input, outputUnits, (a, b) => a * b);
}

function unitSupportsAutoConvert(units: BaseUnits) {
	return BASEUNIT_TO_MULTIPLIER[units] === 1000;
}

// Converts something like 0.0001s to 1ms or 1000V to 1kV.  ie converts to engineering notation
// I'm implementing this just for number right now.  The BigInteger version would need to leverage .equals, .times, 
// .geq and .lt.  That would be silly to pass in each time, and we'd likely just split on the type.  However, we don't
// need that support yet, so I'm ignoring it

export function toIdealUnit(value: NumberAndUnits<number>, minUnitIndex: number, maxUnitIndex: number): NumberAndUnits<number> {

	// If already at zero or unit does not support auto-conversion, do not convert the unit to anything

	if (value.val === 0 || !unitSupportsAutoConvert(getBaseUnits(value.units))) {
		return value;
	}

	// Keep shifting the value left/right by three decimal places until it has 1-3 (no more or less) digits to the left
	// of the decimal place, or until we hit a unit that isn't appropriate for this value.

	// Note that we need to continually shift the original value, as otherwise precision issues will multiply

	let unitIndex = _.indexOf(UNITS_PREFIX, getUnitsPrefix(value.units));
	const { val } = value;
	let shift = 0;
	while (val * Math.pow(1000, shift) >= 1000 && unitIndex > minUnitIndex) {
		--unitIndex;
		shift -= 1;
	}
	while (val * Math.pow(1000, shift) < 1 && unitIndex < maxUnitIndex) {
		++unitIndex;
		shift += 1;
	}

	// Return the final value and the appropriate units

	return { val: val * Math.pow(1000, shift), units: `${UNITS_PREFIX[unitIndex]}${getBaseUnits(value.units)}` };
}

export function isDivisibleBy(divident: NumberAndUnits<number>, divisor: NumberAndUnits<number>): boolean {
	const valToDivide = numberConvertTo(divident, divisor.units);
	// We add a check to account for any floating point errors that may result from conversion
	return _.inRange(valToDivide % divisor.val, 0, 0.000001);
}
