import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { Validations, ValidationSummary } from "../../../services/objectManagers/validations";
import { NodeFactory } from "../types/nodeTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import * as Layout from "../types/layoutTypes";
import { Node, IUnStyledNodeProps } from "./Node";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// Renders all the nodes with errors/warnings, but ignores selection.  The assumption is that all nodes are rendered
// underneath this component, but with errors/warnings ignored, and thus can be rendered less often.  
// Effectively, this component filters just the nodes with errors/warnings, and then renders just those. 

export interface INodeValidationProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends Omit<IUnStyledNodeProps<InstMgr, PortMgr>, "node" | "selected"> {
	nodes: Layout.Node<InstMgr, PortMgr>[];
	nodeFactory: NodeFactory<InstMgr, PortMgr>;
	validations: Validations; 		// No longer optional
}

export function NodeStatusIndicator<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: INodeValidationProps<InstMgr, PortMgr> & ClassesType
) {
	const { nodes, validations } = props;
	return <>
		{
			_.chain(nodes)
				.filter((node) => validations.getSummary(node.inst) !== ValidationSummary.None)
				.map((node) => <Node {...props} node={node} key={node.id} />)
				.value()
		}
	</>;
}
