// In the mean time, you must statically define the paths.  This can be done by using the above function, fetching the 
// path info from the material design icon website, or inspecting the path in the debugger after loading it normally.

export enum PlotlyIcon {
	MapMarker,
	ArrowExpandVertical,
	Eraser,
}

const iconPaths = {
	// eslint-disable-next-line max-len
	[PlotlyIcon.MapMarker]: "M12,11.5A2.5,2.5 0 0,1 9.5,9A2.5,2.5 0 0,1 12,6.5A2.5,2.5 0 0,1 14.5,9A2.5,2.5 0 0,1 12,11.5M12,2A7,7 0 0,0 5,9C5,14.25 12,22 12,22C12,22 19,14.25 19,9A7,7 0 0,0 12,2Z",
	[PlotlyIcon.ArrowExpandVertical]: "M13,9V15H16L12,19L8,15H11V9H8L12,5L16,9H13M4,2H20V4H4V2M4,20H20V22H4V20Z",
	// eslint-disable-next-line max-len
	[PlotlyIcon.Eraser]: "M16.24,3.56L21.19,8.5C21.97,9.29 21.97,10.55 21.19,11.34L12,20.53C10.44,22.09 7.91,22.09 6.34,20.53L2.81,17C2.03,16.21 2.03,14.95 2.81,14.16L13.41,3.56C14.2,2.78 15.46,2.78 16.24,3.56M4.22,15.58L7.76,19.11C8.54,19.9 9.8,19.9 10.59,19.11L14.12,15.58L9.17,10.63L4.22,15.58Z",
};

// Given a material design icon component, this returns the same icon in a format that plotly can consume

export function asPlotlyIcon(icon: PlotlyIcon) {
	return {
		width: 24,					// Width/height is used to form the svg viewbox in plotly
		height: 24,					// MDI seems to use 24x24 for their icons, so that's what we're using
		path: iconPaths[icon],
	};
}
