// UI Views for meta content defined configurables
import * as React from "react";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";
import { Input } from "../../../imports/material-ui-imports";
import { commonStyles } from "../../styles/common";

interface IProps {
	mgr: PinFrequencyConfigurableMgr;
}

export function PinFrequencyConfigurable({ mgr }: IProps) {
	// We want it to look like a disabled text input
	// Since TextConfigurable uses Input underneath, that's what we're doing here as well

	return (
		<Input
			id={mgr.def.name}
			value={mgr.getValueAsString()}
			disabled={true}
			type={"text"}
			fullWidth={true}
			style={commonStyles.inputTextStyle}
			autoComplete={"off"} // prevents console warning
		/>
	);
}
