import * as _ from "lodash";
import { Requirements } from "./requirements";
import { SharedModuleInstanceRequirement } from "public/defs";
import { SharedInstanceMemberMgr } from "../moduleMemberMgrs/sharedInstanceMgr";
import { adaptNonStaticModuleReqs, compareInstanceReqs } from "../moduleArgs";
import { ChangesToChild, isAssignable } from "./sharedModuleCompatibility";
import { ModuleInstanceMgr } from "../moduleInstance";

export class SharedModuleInstanceRequirements extends Requirements<"sharedModuleInstances"> {

	protected adaptReqs(reqs: SharedModuleInstanceRequirement[]) {
		return adaptNonStaticModuleReqs(reqs);
	}

	protected categorizeReqs(reqs: SharedModuleInstanceRequirement[]) {
		return compareInstanceReqs(
			this.currentRequirements,
			reqs,
			this.instanceMgr.getModuleMgr().module.recreateOnArgsChange,
		);
	}

	protected getFunctionName(): "sharedModuleInstances" {
		return "sharedModuleInstances";
	}

	protected resolve(newReqs: SharedModuleInstanceRequirement[], updatedReqs: SharedModuleInstanceRequirement[]) {

		// Note that this order is important.  We need to apply updates before dealing with new requirements as the 
		// new requirements might try to reassign implied connections to those already in use

		this.resolveUpdates(updatedReqs);
		_.each(newReqs, (req) => this.resolveRecreateReq(req));
	}

	private resolveUpdates(reqs: SharedModuleInstanceRequirement[]) {
		_.each(
			reqs,
			(req) => {
				const memberMgr = this.instanceMgr.memberMgrs[req.name] as SharedInstanceMemberMgr;
				if (_.size(memberMgr.valueObjectMgr.getSharedBy()) > 1
					|| (!memberMgr.valueObjectMgr.isUserModified() && this.findCompatibleModuleToShare(req, memberMgr.valueObjectMgr))) {

					// This code in this block will remove the shared association, potentially deleting the instance, 
					// and then create a new association, either by re-using another module or creating a new one.  
					// So let me explain the if block:
					// 	- The existing child has more than one parent:
					//		Although it is possible to detect precisely whether updating a required arg would create 
					//		conflict with other existing parents, it introduces more behaviour variations so it was 
					//		decided that updating the required args when the child is shared by other parents would 
					//		cause the parent to go look for a new child.  If it's 100% compatible, it will re-use it.
					//	- The child is not user-modified and there's another compatible module that could be used 
					//		We don't want to preserve an auto created shared child, because there is no user change to 
					//		preserve at all.  And we want the parent to throw away the auto child and pick another 
					//		existing compatible child whenever possible.
					//		However, there's no point in doing that IF we know there's no compatible child, because 
					//		there may be non-user changes (a move in the graph case) where it would be nice to preserve
					//		those changes if we'll simply recreate the module, but don't want to preserve it as a 
					//		separate module if we can coalesce to a smaller set.
					// Any updated-preserve reqs that do not satisfy these two conditions go back to becoming updated-
					// recreate	

					this.instanceMgr.removeMember(memberMgr);
					return this.resolveRecreateReq(req);
				} else {
					return this.resolveUpdateReq(req);
				}
			});
	}

	private resolveRecreateReq(req: SharedModuleInstanceRequirement) {
		// Search for a pre-existing compatible module.  MemberManager will create a new one if none is found

		const resolvedInstMgr = this.findCompatibleModuleToShare(req);
		const collapsed = !!req.hidden || (_.isUndefined(req.collapsed) ? this.runtime.isTopModule(req.moduleName) : req.collapsed);
		return new SharedInstanceMemberMgr(this.runtime, resolvedInstMgr, req, this.instanceMgr, collapsed);
	}

	private resolveUpdateReq(req: SharedModuleInstanceRequirement) {
		const memberMgr = this.instanceMgr.memberMgrs[req.name] as SharedInstanceMemberMgr;
		memberMgr.update(req);
		return memberMgr;
	}

	// Look for an existing module instance that isn't exclusively owned 
	// And with members that are compatible with the args
	private findCompatibleModuleToShare(def: SharedModuleInstanceRequirement, exclude?: ModuleInstanceMgr) {
		const { moduleName, shareWithByDefault } = def;
		const moduleMgr = this.runtime.getModuleMgr(moduleName);
		return _.find(moduleMgr.instances, (instance) =>
			instance !== exclude &&
			instance.canBeShared() &&
			isAssignable(ChangesToChild.DISALLOWED, instance, def) &&
			instance.getShareWithByDefault() === shareWithByDefault
		);
	}
}
