import * as React from "react";
import * as _ from "lodash";
import { DotsVertical, Check } from "../../imports/mdi-material-ui-imports";
import { IconButton, Menu, MenuItem, ListItemText, Typography } from "../../imports/material-ui-imports";
import { Tooltip } from "../Tooltip";
import { spacingUnit, ColorIndex } from "../styles/themes";
import { commonStyles } from "../styles/common";
import { IGlobalServiceProps } from "../IGlobalServicesProps";

interface IProps {
	id: string,
	text: string,
	checked: boolean,
	onClick: () => void,
}

// Must be a class as Menu forwards refs to MenuItem
export class CheckedMenuItem extends React.Component<IProps> {
	public override render() {
		const { id, onClick, checked, text } = this.props;
		return <MenuItem
			id={id}
			onClick={onClick}
			style={commonStyles.extendOutputMenuStyle}
		>
			<Check style={{ ...commonStyles.smallIcon, visibility: checked ? "visible" : "hidden" }} />
			<ListItemText>
				<Typography>
					{text}
				</Typography>
			</ListItemText>
		</MenuItem>;
	}
}

interface ITripleDotMenuProps {
	children: React.ReactNode;
	disabled: boolean;
	buttonId: string;
	menuId: string;
}

// Triple dot menu on far right of breadcrumb bar
export class TripleDotMenu extends React.Component<ITripleDotMenuProps & IGlobalServiceProps, { open: boolean }> {

	public override state = { open: false };

	private buttonRef: HTMLElement = null;

	public override render() {
		return <React.Fragment>
			<span ref={(el) => this.buttonRef = el}>
				<Tooltip title={"Options"} disabled={this.props.disabled} noWrap>
					<IconButton
						id={this.props.buttonId}
						style={
							{
								padding: spacingUnit * 1.5,
								color: this.props.disabled ?
									this.props.theme.colors[ColorIndex.BACKGROUNDCOLOR] :
									this.props.theme.colors[ColorIndex.ICONCOLOR],
							}
						}
						onClick={this.onOpen}
						disabled={this.props.disabled}
					>
						<DotsVertical style={commonStyles.mediumIcon} />
					</IconButton>
				</Tooltip>
			</span>
			<Menu
				id={this.props.menuId}
				disableAutoFocusItem={true} // this will make sure no element is highlighted grey when menu is open
				anchorEl={this.buttonRef}
				open={this.state.open}
				onClick={this.onClose}
				getContentAnchorEl={null} // https://github.com/mui-org/material-ui/issues/7961
				anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
				transformOrigin={{ vertical: "top", horizontal: "center" }}
			>{this.props.children}
			</Menu>
		</React.Fragment >;
	}

	private onOpen = () => this.setState({ open: true });

	private onClose = () => this.setState({ open: false });
}
