import * as React from "react";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { ClassesType } from "../styling/graphStyles";
import { INodeProps } from "../types/nodeTypes";
import { MainLabel } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { withLayoutAdjustments } from "./withLayoutAdjustments";

function LabelNodeImpl<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(props: INodeProps<InstMgr, PortMgr> & ClassesType) {
	const { node, onClickNode, onMouseDownNode, classes, validations, formatter } = props;
	return <PositionedNode
		node={node}
		onClick={onClickNode}
		onMouseDown={onMouseDownNode}
		className={classes.positionedNode}
		validations={validations}
		formatter={formatter}
	>
		<MainLabel {...props} />
	</PositionedNode>;

}

// Offsets are forced to the middle, with the assumption y is always the middle

export const LabelNode = withLayoutAdjustments(LabelNodeImpl, {
	widthFactor: 0,
	heightFactor: 0,
});
