import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";
import { ClassesType } from "../styling/graphStyles";
import { Port } from "./Port";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { CursorMode } from "../CursorMode";

// Renders all the ports on a given node

interface IProps<PortMgr extends AnyMemberMgr> {
	node: Layout.Node<ModuleInstanceMgr, PortMgr>;
	onMouseDownPort: (event: React.MouseEvent, port: PortMgr) => void;
	onMouseUpPort: (event: React.MouseEvent, port: PortMgr) => void;
	onClickPort: (event: React.MouseEvent, port: PortMgr) => void;
	cursorMode: CursorMode;
}

export function Ports<PortMgr extends AnyMemberMgr>(
	{ node, onMouseDownPort, onMouseUpPort, onClickPort, classes, cursorMode }: IProps<PortMgr> & ClassesType) {
	return <>
		{
			_.map(node.ports, (port) =>
				<Port
					key={port.id}
					onMouseDown={onMouseDownPort}
					onMouseUp={onMouseUpPort}
					onClick={onClickPort}
					port={port}
					cursorMode={cursorMode}
					classes={classes}
				/>
			)
		}
	</>;
}

