import * as _ from "lodash";
import React = require("react");
import { BoardViewHeaders } from "../../BoardViewHeader";
import { BoardViewComponents } from "../../BoardViewComponents";
import { PinInfo, gatherSignals } from "../../../services/pinInfo";
import { pinColors } from "../../styles/colors";
import { Table, TableBody, TableRow, TableCell, TableHead } from "../../../imports/material-ui-imports";
import { BoardViewMgr } from "../../../services/ui/outputView";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { ITreeNode } from "../../TreeNode";
import { SecondaryButton } from "../../buttons/SecondaryButton";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { IOutputActions } from "../../actions/IOutputActions";
import { spacingUnit, ATheme, ColorIndex } from "../../styles/themes";
import { commonStyles } from "../../styles/common";
import { Circle, RecordCircle } from "../../../imports/mdi-material-ui-imports";
import { SwitchButton } from "../../buttons/SwitchButton";

const cardContentStyle = {
	paddingLeft: spacingUnit,
	paddingRight: spacingUnit,
};

interface IBoardViewProps {
	theme: ATheme;
	mgr: BoardViewMgr;
	formatter: IFormatter;
	selectedTreeNode: ITreeNode;
	actions: IOutputActions;
	displayScriptName: boolean;
}

// Draws the entire board based on the provided data
// Supports drawing headers, components, and pin legend
export class BoardView extends React.Component<IBoardViewProps & IGlobalServiceProps> {
	public override render() {
		const selectedPins = this.props.selectedTreeNode.getUsedPins();
		const pinInfo = new PinInfo(
			this.props.mgr.getDeviceData(),
			this.props.mgr.getDevicePinSolutionMap(),
			selectedPins,
			this.props.formatter,
			this.props.selectedTreeNode,
			this.props.actions,
		);
		// get list of unique components that have device pins but not header pins (checks subcomponents as well) 
		const componentsWithoutHeaderPin = _.uniq(_.filter(this.props.mgr.getDeviceData().board.components, (component) => {
			return _.some(gatherSignals(component),
				(signal) => !signal.headerPin && !!signal.devicePin);
		}));

		return (
			<div id={"boardViewContainer"}>
				<span style={{ marginLeft: 12 }}>
					<SecondaryButton
						theme={this.props.theme}
						id={"useCustomBoardBtn"}
						onClick={(e: React.MouseEvent<HTMLElement>) => {
							e.stopPropagation();
							this.props.actions.useCustomBoard();
						}}>{"Use custom board"}
					</SecondaryButton>
					<SwitchButton
						theme={this.props.theme}
						mgr={this.props.mgr}
						actions={this.props.actions}
					/>
				</span>
				<div style={cardContentStyle}>
					{_.map(this.props.mgr.getDeviceData().board.headers, (header) => {
						return (
							<BoardViewHeaders
								{...this.props}
								deviceData={this.props.mgr.getDeviceData()}
								pinInfo={pinInfo}
								key={header.name}
								header={header}
								shouldShowModeTable={this.props.mgr.shouldShowModeTable()}
							/>
						);
					})}

					{!_.isEmpty(componentsWithoutHeaderPin) &&
						<BoardViewComponents
							{...this.props}
							deviceData={this.props.mgr.getDeviceData()}
							pinInfo={pinInfo}
							components={componentsWithoutHeaderPin}
							shouldShowModeTable={this.props.mgr.shouldShowModeTable()}
						/>
					}
				</div>
				<BoardViewLegend theme={this.props.theme} />
			</div>
		);
	}
}

const legendTableCell: React.CSSProperties = {
	textAlign: "center",
};

const legendCells = [
	{
		name: "Available",
		style: {
			color: pinColors.available,
		},
	},
	{
		name: "Used",
		style: {
			color: pinColors.used,
		},
	},
	{
		name: "Used by currently selected",
		style: {
			color: pinColors.highlightedUsed,
			stroke: pinColors.selectedStroke,
			strokeWidth: 2,
		},
	},
	{
		name: "Shared",
		style: {
			color: pinColors.shared,
		},
	},
	{
		name: "Shared by currently selected",
		style: {
			color: pinColors.highlightedShared,
			stroke: pinColors.selectedStroke,
			strokeWidth: 2,
		},
	},
	{
		name: "N/A",
		style: {
			color: pinColors.fixed,
		},
	},
];

class BoardViewLegend extends React.Component<{ theme: ATheme }> {
	public override render() {
		return (
			<Table>
				<TableHead>
					<TableRow style={commonStyles.tableRowStyle}>
						<TableCell>Pin Types</TableCell>
						{
							_.map(legendCells, (c) => {
								return <TableCell id={c.name} key={c.name} style={legendTableCell}>{c.name}</TableCell>;
							})
						}
					</TableRow>
				</TableHead>
				<TableBody>
					<TableRow style={commonStyles.tableRowStyle}>
						<TableCell>Free Pin</TableCell>
						{
							_.map(legendCells, (c) => {
								return (
									<TableCell
										id={c.name}
										key={c.name}
										style={legendTableCell}
									><Circle style={c.style.stroke ?
										// eslint-disable-next-line max-len
										{ ...c.style, stroke: this.props.theme.colors[ColorIndex.SELECTEDPINSTROKECOLOR] } : c.style} />
									</TableCell>
								);
							})
						}
					</TableRow>
					<TableRow style={commonStyles.tableRowStyle}>
						<TableCell>Attached To Software</TableCell>
						{
							_.map(legendCells, (c) => {
								return (
									<TableCell
										key={c.name}
										style={legendTableCell}
									><RecordCircle style={c.style.stroke ?
										// eslint-disable-next-line max-len
										{ ...c.style, stroke: this.props.theme.colors[ColorIndex.SELECTEDPINSTROKECOLOR] } : c.style} />
									</TableCell>
								);
							})
						}
					</TableRow>
				</TableBody>
			</Table>
		);
	}
}
