import { createFinalSvgPathNode } from "./createSvgPathNode";

// Rectangle with a triangle on the right side.  Indicates flow is left to right, so this works for both input and 
// output pins

function pinPath(width: number, height: number) {
	const rectangleEnd = width * 3 / 4;
	return "M 0 0 " 					// Start in top left corner
		+ `H ${rectangleEnd} ` 			// Top of rectangle
		+ `L ${width} ${height / 2} `	// Top of triangle to left side all 1/2 way down
		+ `L ${rectangleEnd} ${height} `// Bottom of triangle
		+ "H 0 "						// Bottom of rectangle
		+ "V 0 Z"; 						// Vertical line back to the start and close
}

// Extra 5 as triangle may pinch on the label otherwise.  There will only ever be one output, so hight-based 
// adjustments aren't needed.

export const PinNode = createFinalSvgPathNode(pinPath, { heightFactor: 1 / 2, outputLabelXOffset: () => -5 });
