const themedStyles = (theme: Theme) => {
	const selectedList = {
		...list,
		borderLeftColor: theme.palette.type === "dark" ? "#3794ff" : "#117788",
	};
	const unSelectedList = {
		...list,
		borderLeftColor: "transparent",
	};
	return {
		selectedList,
		unSelectedList,
		selectedTableRowStyle: {
			...tableRowStyle,
			...selectedList,
		},
		unselectedTableRowStyle: {
			...tableRowStyle,
			...unSelectedList,
		},
	};
};

export const withCommonStyles = withStyles(themedStyles);

export type CommonClasses = WithStyles<typeof themedStyles>
