import React = require("react");
import { Input, InputBaseComponentProps } from "../imports/material-ui-imports";
import { commonStyles } from "./styles/common";

export interface IBasicInputProps {
	id: string;
	onChange: (value: string) => void;
	value: string;
	onFocus?: () => void;
	onBlur?: () => void;
	onClick?: () => void;
	placeholder?: string;
	inputProps?: InputBaseComponentProps;
	disabled: boolean;
}

interface IInputBoxProps extends IBasicInputProps {
	type: string;
}

export class InputBox extends React.Component<IInputBoxProps> {

	constructor(props: IInputBoxProps) {
		super(props);
	}

	public override render() {
		return (
			<Input
				id={this.props.id}
				value={this.props.value}
				onFocus={this.props.onFocus}
				onBlur={this.props.onBlur}
				onClick={this.props.onClick}
				placeholder={this.props.placeholder}
				inputProps={this.props.inputProps}
				disabled={this.props.disabled}
				type={this.props.type}
				fullWidth={true}
				onChange={(e) => { this.props.onChange(e.target.value); }}
				style={commonStyles.inputTextStyle}
				autoComplete={"off"} // prevents console warning
			/>
		);
	}
}
