import * as _ from "lodash";
import { enableTest } from "./platform";

const OriginalPromise = Promise;

function injectTestability() {

	// Save the original Promise on the windows object so we can refer to it
	// See webpack.common.js for the reason why
	// @ts-ignore
	window.ti_testing_originalPromise = Promise;

	(window as any).getAngularTestability = () => {
		return Testability.instance();
	};

	(window as any).getAllAngularTestabilities = () => {
		return [Testability.instance()];
	};

	class PromiseReplacement<T> extends OriginalPromise<T> {
		constructor(
			executor: (resolve: (value?: T | PromiseLike<T>) => void, reject: (reason?: any) => void) => void) {
			super((realResolve, realReject) => {

				const lock = Testability.instance().operationPending();
				try {

					const resolve = (value?: T | PromiseLike<T>) => {
						lock.dismiss();
						realResolve(value);
					};

					const reject = (reason?: any) => {
						lock.dismiss();
						realReject(reason);
					};

					// Call the original executor, but with our wrappers instead

					executor(resolve, reject);

				} catch (e) {
					lock.dismiss();
					throw e;
				}
			});
		}
	}
	Promise = PromiseReplacement;

	// eslint-disable-next-line @typescript-eslint/unbound-method
	const originalDebounce = _.debounce;
	function debounceReplacement<T extends (...args: any[]) => any>(
		func: T,
		wait?: number,
		options?: _.DebounceSettings,
	) {
		let lock: Dismissable = null;

		// Wrap the passed in function with something that will unlock protractor

		const unlockThenCallFunc = (...args: any[]) => {
			lock.dismiss();
			lock = null;
			return func(...args);
		};

		// Debounce our wrapped function

		const debouncedFunc = originalDebounce(unlockThenCallFunc, wait, options);

		// Return something that will lock, if not already locked, then call the debounce
		// version

		const replacementFunc = (...args: any[]) => {
			if (!lock) {
				lock = Testability.instance().operationPending();
			}
			return debouncedFunc(...args);
		};
		(replacementFunc as any).flush = () => debouncedFunc.flush();
		(replacementFunc as any).cancel = () => {
			if (lock) {
				lock.dismiss();
				debouncedFunc.cancel();
			}
		};
		return replacementFunc;
	}

	// @ts-ignore	
	_.debounce = debounceReplacement;

	(window as any).sysConfigTestOutstandingOperations = new Set<Dismissable>();
}

class DismissableBase {
	private dismissed = false;
	constructor(private readonly onDismissed: () => void) { }
	public dismiss() {
		if (!this.dismissed) {
			this.dismissed = true;
			this.onDismissed();
		}
	}
}

// Useful for finding promises that haven't resolved

class Dismissable extends DismissableBase {
	public stack = new Error().stack;
	constructor(onDismissed: () => void) {
		super(() => {
			(window as any).sysConfigTestOutstandingOperations.delete(this);
			onDismissed();
		});
		(window as any).sysConfigTestOutstandingOperations.add(this);
	}
}

class Testability {

	private static _instance = new Testability();

	public static instance() {
		return Testability._instance;
	}

	private pendingCount: number = 0;
	private protractorCallback: (didWork: boolean) => void = null;
	private internalCallback: () => void = null;

	// We need to skip counting and basically use the native promise when the promise comes from 
	// protractor, as obviously protractor wants to check the system for idle excluding itself.
	// This can be identified by the current call stack.

	public operationPending() {
		if (calledByProtractorInjectedCode()) {
			return new Dismissable(() => {
				this.runCBsIfReady();
			});
		} else {
			this.pendingCount++;
			return new Dismissable(() => {
				this.pendingCount--;
				this.runCBsIfReady();
			});
		}
	}

	// Protractor will look for and call this function register an event to
	// fire every time the application has no more work to do
	public whenStable(callback: (didWork: boolean) => void) {
		this.protractorCallback = callback;
		this.runCBsIfReady();
	}

	// Called by us to register to do something synchronous just before 
	// protractor is notified
	public runOnceBeforeStable(callback: () => void) {
		this.internalCallback = callback;
		this.runCBsIfReady();
	}

	private runCBsIfReady() {
		if (this.isStable()) {
			if (this.internalCallback) {
				const internalCallback = this.internalCallback;
				this.internalCallback = null;
				internalCallback();
			}
			if (this.protractorCallback) {
				this.protractorCallback(false);
			}
		}
	}

	private isStable() {
		return this.pendingCount === 0;
	}
}

function calledByProtractorInjectedCode() {
	return areAnyOnCurrentCallstack("callFunction", "executeAsyncScript");
}

function areAnyOnCurrentCallstack(...strings: string[]) {
	const stackTraceLimit = Error.stackTraceLimit;
	Error.stackTraceLimit = 100;
	const tempError = new Error();
	Error.stackTraceLimit = stackTraceLimit;

	return _.some(strings, (s) => tempError.stack.includes(s));
}

export function enableTestHooks(globalCallbacks: Record<string, (...args: any[]) => void>) {
	enableTest();
	injectTestability();
	_.each(globalCallbacks, (value, key) => {
		(window as any)[key] = (...args: any[]) => Testability.instance().runOnceBeforeStable(() => value(...args));
	});
	(window as any).sysconfigWaitForIdle = (onIdle: () => void) => {
		Testability.instance().runOnceBeforeStable(onIdle);
	};
}
