import * as _ from "lodash";
import React = require("react");
import { commonStyles } from "../../styles/common";
import {
	ListItem,
	Table,
	TableRow,
	TableBody,
	TableCell,
	TableHead,
	TableContainer,
	Avatar,
	Button,
} from "../../../imports/material-ui-imports";
import { ProblemsViewMgr } from "../../../services/ui/outputView";
import { FormattedMsg } from "../../FormattedMsg";
import { ConfigStoreActions } from "../../../services/configStore";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { StatusDecorator, StatusType } from "../../Decorators";
import { FormattedLinkAndDestination } from "../../../services/formatting/link";
import { CValidation } from "../../objectManagers/Validation";
import { assertUnreachable } from "../../../services/utils";
import { spacingUnit, ColorIndex, ATheme } from "../../styles/themes";
import { SwapVertical, CloseCircle, Alert, InformationOutline } from "../../../imports/mdi-material-ui-imports";
import { ISummaryItem } from "../../../services/summaryItems";
import { Validation, Validations } from "../../../services/objectManagers/validations";
import { Tooltip } from "../../Tooltip";

interface IProblemsViewProps {
	mgr: ProblemsViewMgr;
	actions: ConfigStoreActions;
	formatter: IFormatter;
	validations: Validations;
	theme: ATheme;
}

interface IProblemsViewState {
	showErrors: boolean;
	showWarnings: boolean;
	showSuppressed: boolean;
	showInfos: boolean;
	sortByAsc: boolean;
}

const statusDecoratorStyle = { verticalAlign: "bottom" } as const;

export class ProblemsView extends React.Component<IProblemsViewProps, IProblemsViewState> {
	public override state: IProblemsViewState = {
		showErrors: this.props.mgr.getStates().get("showErrors"),
		showWarnings: this.props.mgr.getStates().get("showWarnings"),
		showSuppressed: this.props.mgr.getStates().get("showSuppressed"),
		showInfos: this.props.mgr.getStates().get("showInfos"),
		sortByAsc: this.props.mgr.getStates().get("sortByAsc"),
	};
	public override render() {
		const items = this.getAllSummaryItems();
		const sortedItems = sortItems(this.filterItems(items), this.state.sortByAsc);
		const totals = getTotals(items);
		return _.isEmpty(items) ?
			<div id={"ProblemsView"}>
				<ListItem>
					<span>{"There are no problems in the current design."}</span>
				</ListItem>
			</div>
			:
			<div id={"ProblemsView"} style={{ maxHeight: "400px" }}>
				<TableContainer style={{ paddingBottom: spacingUnit }}>
					<Table id="ProblemsView">
						<TableBody>
							<TableRow style={{ float: "left" }}>
								<TableCell style={{ paddingLeft: spacingUnit, paddingRight: spacingUnit }}>
									<FilterButton
										id="errorButton"
										buttonBGColor={this.props.theme.colors[ColorIndex.BORDERCOLOR]}
										text={"Errors"}
										enabled={this.state.showErrors}
										icon={
											<CloseCircle
												style={totals.errors === 0 ?
													{ ...commonStyles.neutralIcon, verticalAlign: "top" } :
													{ ...commonStyles.errorIcon, verticalAlign: "top" }} />
										}
										onClick={this.showErrors}
										numIssues={totals.errors}
									/>
								</TableCell>
								<TableCell style={{ paddingLeft: spacingUnit, paddingRight: spacingUnit }}>
									<FilterButton
										id="warningButton"
										buttonBGColor={this.props.theme.colors[ColorIndex.BORDERCOLOR]}
										text={"Warnings"}
										enabled={this.state.showWarnings}
										icon={
											<Alert
												style={totals.warnings === 0 ?
													{ ...commonStyles.neutralIcon, verticalAlign: "top" } :
													{ ...commonStyles.warningIcon, verticalAlign: "top" }} />
										}
										onClick={this.showWarnings}
										numIssues={totals.warnings}
									/>
								</TableCell>
								<TableCell style={{ paddingLeft: spacingUnit, paddingRight: spacingUnit }}>
									<FilterButton
										id="suppressedWarningButton"
										buttonBGColor={this.props.theme.colors[ColorIndex.BORDERCOLOR]}
										text={"Suppressed"}
										enabled={this.state.showSuppressed}
										icon={
											<Alert
												style={{ ...commonStyles.neutralIcon, verticalAlign: "top" }} />
										}
										onClick={this.showSuppressed}
										numIssues={totals.suppressedWarnings}
									/>
								</TableCell>
								<TableCell style={{ paddingLeft: spacingUnit, paddingRight: spacingUnit }}>
									<FilterButton
										id="infoButton"
										buttonBGColor={this.props.theme.colors[ColorIndex.BORDERCOLOR]}
										text={"Infos"}
										enabled={this.state.showInfos}
										icon={
											<InformationOutline
												style={totals.infos === 0 ?
													{ ...commonStyles.neutralIcon, verticalAlign: "top" } :
													{ ...commonStyles.infoIcon, verticalAlign: "top" }} />
										}
										onClick={this.showInfos}
										numIssues={totals.infos}
									/>
								</TableCell>
							</TableRow>
						</TableBody>
					</Table>
				</TableContainer>
				<TableContainer>
					<Table id="ProblemsView">
						<TableHead>
							<TableRow hover={false} style={commonStyles.tableRowStyle}>
								<TableCell colSpan={2} style={{ width: "35%" }}>
									<div style={{ whiteSpace: "nowrap" }}>
										{"Location "}
										<Tooltip title={this.state.sortByAsc ? "Sort by ascending order" : "Sort by descending order"}>
											<SwapVertical
												onClick={this.sortByAscending}
												style={{ ...commonStyles.smallIcon, verticalAlign: "middle", cursor: "pointer" }} />
										</Tooltip>
									</div>
								</TableCell>
								<TableCell colSpan={2} style={{ width: "65%" }}>
									Details
								</TableCell>
							</TableRow>
						</TableHead>
						<TableBody id="problemsViewBody">
							{
								_.map(sortedItems, (item, index) => (
									<TableRow id={item.text} key={index} hover style={commonStyles.tableRowStyle}>
										<TableCell id={item.text + "button"} colSpan={2} style={{ width: "35%" }}>
											<Tooltip title={this.getItemLocation(item)}>
												<span
													style={{
														// Ensure link text does not wrap
														display: "flex",
														width: "max-content",
													}}
												>
													<StatusDecorator
														id={item.text + "status"}
														status={getStatusType(item)}
														containerStyle={statusDecoratorStyle}
													/>
													<FormattedMsg
														message={this.props.formatter(item.location)}
														actions={this.props.actions}
													/>
												</span>
											</Tooltip>
										</TableCell>
										<TableCell colSpan={2} style={{ width: "65%" }}>
											<CValidation
												validatableObj={item.validatableObj}
												validations={this.props.validations}
												formatter={this.props.formatter}
												actions={this.props.actions}
												withoutIcon={true}
												statusType={getStatusType(item)}
												singleMsg={item.text}
											/>
										</TableCell>
									</TableRow>
								))
							}
						</TableBody>
					</Table>
				</TableContainer>
			</div >;
	}

	private filterItems(items: ISummaryItem[]) {
		return _.filter(items, (item) => {
			const showErrors = this.state.showErrors;
			const showWarnings = this.state.showWarnings;
			const showSuppressed = this.state.showSuppressed;
			const showInfos = this.state.showInfos;
			return (
				(showErrors && item.type === "errors") ||
				(showWarnings && item.type === "warnings") ||
				(showInfos && item.type === "infos") ||
				(showSuppressed && item.type === "suppressedWarnings")
			);
		});
	}

	private getAllSummaryItems() {
		return this.props.mgr.getSummaryItems(true);
	}

	private getItemLocation(item: ISummaryItem) {
		return (this.props.formatter(item.location).toParts()[0] as FormattedLinkAndDestination).destination.treeNodePath[0];
	}

	private showErrors = () => {
		this.props.mgr.setStates("showErrors", !this.state.showErrors);
		this.setState({ showErrors: !this.state.showErrors });
	}

	private showWarnings = () => {
		this.props.mgr.setStates("showWarnings", !this.state.showWarnings);
		this.setState({ showWarnings: !this.state.showWarnings });
	}

	private showSuppressed = () => {
		this.props.mgr.setStates("showSuppressed", !this.state.showSuppressed);
		this.setState({ showSuppressed: !this.state.showSuppressed });
	}

	private showInfos = () => {
		this.props.mgr.setStates("showInfos", !this.state.showInfos);
		this.setState({ showInfos: !this.state.showInfos });
	}

	private sortByAscending = () => {
		this.props.mgr.setStates("sortByAsc", !this.state.sortByAsc);
		this.setState({ sortByAsc: !this.state.sortByAsc });
	}
}

function getStatusType(item: ISummaryItem) {
	const { type } = item;
	switch (type) {
		case "errors":
			return StatusType.Error;
		case "infos":
			return StatusType.Info;
		case "warnings":
			return StatusType.Warning;
		case "suppressedWarnings":
			return StatusType.SuppressedWarning;
		default:
			assertUnreachable(type);
	}
}

function sortItems(items: ISummaryItem[], sortByAsc: boolean) {
	return _.orderBy(items, "location", sortByAsc ? "asc" : "desc");
}

function getTotals(items: ISummaryItem[]): Record<keyof Validation, number> {

	// Group all items by their type, and then find the size

	const partialTotals = _.chain(items)
		.groupBy((i) => i.type)
		.mapValues(_.size)
		.value();

	// Ensure we don't return undefined but always zero

	return {
		errors: 0,
		warnings: 0,
		suppressedWarnings: 0,
		infos: 0,
		...partialTotals,
	};
}

interface IFilterButtonProps {
	id: string;
	enabled: boolean;
	icon: JSX.Element;
	text: string;
	buttonBGColor: string;
	numIssues: number;
	onClick: () => void;
}
function FilterButton(props: IFilterButtonProps) {
	return (
		<Button
			id={props.id}
			style={{
				backgroundColor: !props.enabled ?
					null :
					props.buttonBGColor,
				padding: "4px",
			}}
			onClick={props.onClick}
		>
			<div>
				<Tooltip title={!props.enabled ? "Show " + props.text :
					"Hide " + props.text}>
					<div>
						{props.icon}
						{props.text + " "}
						<Avatar
							style={commonStyles.avatarStyle}
							id={props.id + "Avatar"}
						>
							{props.numIssues}
						</Avatar>
					</div>
				</Tooltip>
			</div>
		</Button>
	);
}
