import * as React from "react";
import * as _ from "lodash";
import { TabbedOutput } from "../../OutputViews/TabbedOutput";
import { ResizableBorder } from "../../ResizableBorder";
import { commonStyles } from "../../styles/common";
import { Dock } from "../../actions/IOutputActions";
import { GraphConfigurables } from "./GraphConfigurables";
import { IGraphTreeNode } from "../types/IGraphTreeNode";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";

// This component represents the lower pane within a graph view

interface IAdditionalProps {
	treeNode: IGraphTreeNode<ModuleInstanceMgr>;
	col3Width: number;
	outputDocking: Dock;
}

type IProps = IAdditionalProps
	& React.ComponentProps<typeof GraphConfigurables>
	& Omit<React.ComponentProps<typeof TabbedOutput>, "selectedTreeNode">

export class GraphLowerPane extends React.Component<IProps> {

	public override render() {
		const { actions, treeNode, col3Width, outputDocking, ...rest } = this.props;
		const showOutput = outputDocking === Dock.BOTTOM;

		return (
			<div style={commonStyles.columnFlexLayout}>
				<div style={commonStyles.rowFlexLayout}>
					<GraphConfigurables {...this.props} />
					{showOutput &&
						<ResizableBorder
							theme={this.props.theme}
							borderAfterChild={false}
							position={col3Width}
							onPositionChanged={this.onPositionChanged}
							percentage={true}
							displayed={true}
							horizontal={true}
							showBorder={true}
							id="col2Col3Border"
						>
							<div id="Output" style={commonStyles.innerContentStyle}>
								<TabbedOutput
									{...rest}
									actions={actions}
									selectedTreeNode={treeNode}
								/>
							</div>
						</ResizableBorder>
					}
				</div>
			</div>
		);
	}

	private onPositionChanged = (width: number) => {
		this.props.actions.setCol3Width(width);
	}
}
