import * as _ from "lodash";
import React = require("react");
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { UserPreference, SelectPreference } from "../../services/userPreferences";
import { CodeGenTemplateFile } from "dataInterfaces";
import { ITemplateActions } from "../actions/ITemplateActions";
import { IUserPreferenceActions } from "../actions/IUserPreferenceActions";
import { LazyLoadedEditor } from "./Editor/LazyLoadedEditor";
import { ResourceLoader } from "../../services/resources/metaContentLoaders/resourceLoader";
import { OutputViewError, IOutputErrorProps } from "./OuputViewError";
import { List, ListItem, ListItemSecondaryAction, IconButton, Typography } from "../../imports/material-ui-imports";
import { Tooltip } from "../Tooltip";
import { Close } from "../../imports/mdi-material-ui-imports";
import { commonStyles } from "../styles/common";
import { SaveGeneratedCode } from "../SaveGeneratedCode";
import { TripleDotMenu, CheckedMenuItem } from "./TripleDotMenu";
import { convertUnknownToError } from "../../services/utils";

interface IOutputViewProps {
	file: CodeGenTemplateFile;
	getPreviousCode: () => string;
	getCode: () => string;
	toggleFilePreview: () => void;
	actions: ITemplateActions & IUserPreferenceActions;
	userPref: UserPreference;
	resourceLoader: ResourceLoader;
}

export class FilePreview extends React.Component<IOutputViewProps & IGlobalServiceProps> {
	public override render() {
		const {
			failureReason,
			exception,
			currentContent,
			previousContent,
		} = this.fetchData();
		const hasError = !!exception || !!failureReason;
		return (
			<OutputViewBorder
				{...this.props}
				outputError={{ exception, failureReason }}
				viewOptions={this.getViewOptions()}
			>
				{this.getView(currentContent, previousContent, hasError)}
			</OutputViewBorder>
		);
	}

	private fetchData() {
		let currentContent: string = "";
		let previousContent: string = "";
		let failureReason: string = "";
		let exception: Error = null;

		// Generate the current code
		try {
			currentContent = this.props.getCode();
		} catch (e) {
			if (_.isString(e)) {
				failureReason = e;
			} else {
				// Exception - save it to display it
				exception = convertUnknownToError(e);
			}
		}

		// Generate the previous code
		try {
			previousContent = this.props.getPreviousCode();
		} catch (e) {
			if (_.isString(e)) {
				// If we can't get the previous content for any reason, then set it as an empty string
				// (so the diff shows that EVERYTHING changed)
				previousContent = "";
			} else {
				// Exception - save it to display it
				//exception = e;
			}
		}

		return {
			failureReason,
			exception,
			currentContent,
			previousContent,
		};
	}

	private getView(currentContent: string, previousContent: string, hasError: boolean) {
		return <LazyLoadedEditor
			{...this.props}
			currentContent={currentContent}
			previousContent={previousContent}
			hasError={hasError}
			diffType={this.props.userPref.getEditorPreferences().editorDiffType.getSelectedOption()}
		/>;
	}

	private getViewOptions() {
		return this.props.userPref.getEditorPreferences().editorDiffType;
	}
}

interface IOutputViewBorderProps {
	file: CodeGenTemplateFile;
	outputError: IOutputErrorProps;
	children: React.ReactNode;
	actions: ITemplateActions & IUserPreferenceActions;
	viewOptions: SelectPreference<number>;
	toggleFilePreview: () => void;
}

// This component is for rendering the control border around the actual output view.
// It accepts possible selectable preference selection that will be rendered as a triple dot menu on this border.
// The current usage for this is the diff-options for the editor view.
function OutputViewBorder(props: IGlobalServiceProps & IOutputViewBorderProps) {
	const { actions, file, outputError, theme, children, toggleFilePreview, viewOptions } = props;
	const hasError = !!outputError.exception || !!outputError.failureReason;
	return (
		<div style={{
			border: theme.border,
			borderRadius: 4, height: "100%",
			display: "flex",
			flexDirection: "column",
		}}>
			<div id="outputViewHeader">
				<List>
					<ListItem style={{ padding: 0, paddingLeft: 12 }}>
						<Typography variant="body2" id="curOpenedFile" style={{ flexGrow: 1 }}>{file.name}</Typography>
						<ListItemSecondaryAction>
							{viewOptions &&
								<TripleDotMenu
									{...props}
									buttonId={"extendedMenuInEditorIcon"}
									menuId={"extendedMenuInEditor"}
									disabled={false}>
									{_.map(viewOptions.getAllSelectableOptions(), (option) => {
										return <CheckedMenuItem
											key={option.id.toString()}
											text={option.optionText}
											id={option.id.toString()}
											onClick={() => {
												const newPref = Number(option.id);
												actions.setPreferenceValue(viewOptions, newPref);
											}}
											checked={option.id === viewOptions.getSelectedOption()}
										/>;
									})}
								</TripleDotMenu>}
							<SaveGeneratedCode
								modalService={props.modalService}
								errorStore={props.errorStore}
								id="btnOutputViewDownload"
								actions={actions}
								files={[file]}
								disabled={hasError}
							/>
							<Tooltip title="Close" noWrap>
								<IconButton id="backToFileListView" onClick={toggleFilePreview} style={{ padding: 6 }}>
									<Close color="primary" style={commonStyles.smallIcon} />
								</IconButton>
							</Tooltip>
						</ListItemSecondaryAction>
					</ListItem>
				</List>
			</div>
			<div>
				{hasError &&
					<OutputViewError
						{...props}
						exception={outputError.exception}
						failureReason={outputError.failureReason} />
				}
			</div>
			{children}
		</div>
	);
}
