import React = require("react");
import { IBasicInputProps } from "../InputBox";

// Make an input only trigger onChange when the user leave focus.
// This should be used in places where triggering frequent onChange is problematic. 
// Or where the input value makes sense only as a whole completed entry.
export function onBlurInput<T extends IBasicInputProps>(BaseInput: React.ComponentClass<T>) {

	class OnBlurInput extends React.Component<T, { value: string, focused: boolean }> {

		public override state = {
			value: this.props.value,
			focused: false,
		};

		public override render() {
			return (
				<BaseInput
					{...this.props}
					value={this.state.focused ? this.state.value : this.props.value}
					onChange={(newVal: string) => this.setState({ value: newVal })}
					onFocus={() => {
						this.setState({ value: this.props.value, focused: true });
					}}
					onBlur={() => {
						this.props.onChange(this.state.value);
						this.setState({ focused: false });
					}}
				/>
			);
		}
	}

	return OnBlurInput;
}
