import * as React from "react";
import * as _ from "lodash";
import { Typography, Grid } from "../../imports/material-ui-imports";
import { spacingUnit } from "../styles/themes";
import { ConfirmModal } from "./ConfirmModal";
import { CheckBox } from "../CheckBox";
import { Tooltip } from "../Tooltip";
import { IModalMinProps } from "./BasicModal";

interface IProps extends IModalMinProps {
	confirmAction: (lockSolutionFirst: boolean) => void;
	cancelAction?: () => void;
	currentBoard: string;
}

interface IState {
	lockSolutionFirst: boolean;
}

// A confirm/cancel dialog with a specific message for board->device migration
// Includes an option to lock the pinmux

export class UseCustomBoard extends React.Component<IProps, IState> {
	constructor(props: IProps) {
		super(props);
		this.state = {
			lockSolutionFirst: true,
		};
	}

	public override render() {

		const { confirmAction, cancelAction, currentBoard, ...rest } = this.props;
		return <ConfirmModal
			{...rest}
			title={"Use Custom Board"}
			cancelAction={cancelAction}
			confirmAction={() => confirmAction(this.state.lockSolutionFirst)}
		>
			{this.getContent()}
		</ConfirmModal>;
	}

	private getContent() {
		return <div>
			{/* whiteSpace: "pre" preserves whitespace of content and only wrap on line break */}
			<Typography variant="body2" style={{ whiteSpace: "pre" }}>
				{this.getMigrateToDeviceWarning()}
			</Typography>

			<Grid container spacing={8}>
				<Grid container item alignItems="flex-start" justify="center" direction="row" xs={12} spacing={8}>
					<Grid item xs={3}>
						<Typography style={{ padding: spacingUnit }} variant="body2">Lock PinMux</Typography>
					</Grid>
					<Grid item xs={3}>
						<Tooltip title={this.getToolTip()}>
							<CheckBox
								id={"lockSolutionFirst"}
								onChange={(lockSolutionFirst) => this.setState({ lockSolutionFirst })}
								value={this.state.lockSolutionFirst}
							/>
						</Tooltip>
					</Grid>
				</Grid>
			</Grid>
		</div>;
	}

	private getToolTip() {
		return 'This will also lock the pin and peripheral selections set to "Any" to the value ' +
			"the tool currently has auto-solved for them";
	}

	private getMigrateToDeviceWarning() {
		return `
This will migrate the current configuration to the underlying device used by the 
${this.props.currentBoard}. All hardware component information will be removed,
and it will be up to you to select the correct pins. This will give you the freedom to pick
any compatible device pin according to your custom board without warning. 

It is recommended to leave the "Lock Pinmux" option enabled, so that the pins currently
used remain unchanged.  But if you unselect it, the tool will auto-solve using all device
pins.

Warning! There will be no way to change back to using a ${this.props.currentBoard}
other than undo (ctrl + z).

`;
	}
}
