import * as _ from "lodash";
import React = require("react");
import { List, ListItem, ListItemIcon, Badge } from "../imports/material-ui-imports";
import { Tab } from "../services/tabs";
import { TabName } from "../services/tabNames";
import { Tooltip } from "./Tooltip";
import {
	Alert,
	CloseCircle,
	Chip,
	Battery,
	Ballot,
	Deskphone,
	FamilyTree,
	ChartBellCurveCumulative,
} from "../imports/mdi-material-ui-imports";
import { ConfigStoreActions } from "../services/configStore";
import { tiStatusColor } from "./styles/colors";
import { assertUnreachable } from "../services/utils";
import { commonStyles } from "./styles/common";
import { ATheme, ColorIndex } from "./styles/themes";
import { Validations, ValidationSummary } from "../services/objectManagers/validations";

interface IProps {
	tabs: Tab[];
	selectedTab: Tab;
	col1Width: number;
	actions: ConfigStoreActions;
	theme: ATheme;
	validations: Validations;
}

export class IconMenu extends React.Component<IProps> {

	public override render() {
		return (
			<List style={{
				...commonStyles.listStyles,
				backgroundColor: this.props.theme.colors[ColorIndex.BACKGROUNDCOLOR],
			}}>
				{_.map(this.props.tabs, (tab) => {
					return (
						<Tooltip placement="bottom" title={this.getTabToolTip(tab)} key={tab.getTitle()}>
							<ListItem
								key={tab.getTitle()}
								id={tab.getId()}
								button
								style={{
									padding: this.props.theme.theme.spacing(2),
									borderLeft: "2px solid",
									borderColor: (this.props.selectedTab === tab) ?
										this.props.theme.colors[ColorIndex.SELECTEDICONCOLOR] :
										this.props.theme.colors[ColorIndex.BACKGROUNDCOLOR],
								}}
								onClick={() => this.props.actions.handleTabClick(tab)}
								disabled={this.tabIsDisabled(tab)}
							>
								<ListItemIcon
									id={tab.getId().concat((this.props.selectedTab === tab) ? "ActiveIcon" : "Icon")}
									style={{
										color: (this.props.selectedTab === tab) ?
											// eslint-disable-next-line max-len
											this.props.theme.colors[ColorIndex.SELECTEDICONCOLOR] : this.props.theme.colors[ColorIndex.ICONCOLOR],
										marginRight: 0,
									}}
								>
									<Badge badgeContent={this.getBadge(tab)}>
										{this.getIcon(tab.getTitle())}
									</Badge>
								</ListItemIcon>
							</ListItem>
						</Tooltip>
					);
				})}
			</List>
		);
	}

	private getBadge(tab: Tab) {
		let summary: ValidationSummary;
		if (tab.getTitle() === TabName.SIMULATION) {
			summary = this.props.validations.getOverallSummary();
		} else {
			summary = this.props.validations.getSummary(tab);
		}

		switch (summary) {
			case ValidationSummary.Error:
				return <CloseCircle id={tab.getTitle() + "Error"}
					style={{ ...commonStyles.smallIcon, color: tiStatusColor.error }} />;
			case ValidationSummary.Warning:
				return <Alert id={tab.getTitle() + "Warning"}
					style={{ ...commonStyles.smallIcon, color: tiStatusColor.warning }} />;
			default:
				assertUnreachable(summary);
			case ValidationSummary.None:
				return null;
		}
	}

	private getIcon(id: TabName) {
		switch (id) {
			case TabName.SOFTWARE:
				return <Ballot style={commonStyles.mediumIcon} />;
			case TabName.HARDWARE:
				return <Chip style={commonStyles.mediumIcon} />;
			case TabName.CLOCKTREE:
				return <FamilyTree style={{ ...commonStyles.mediumIcon, transform: "rotate(-90deg)" }} />;
			case TabName.PERIPHERALS:
				return <Chip style={commonStyles.mediumIcon} />;
			case TabName.POWER:
				return <Battery style={commonStyles.mediumIcon} />;
			case TabName.RESERVATION:
				return <Deskphone style={commonStyles.mediumIcon} />;
			case TabName.SIMULATION:
				return <ChartBellCurveCumulative style={commonStyles.mediumIcon} />;
			default:
				assertUnreachable(id);
				return null;
		}
	}

	private tabIsDisabled(tab: Tab) {
		return tab.getTitle() === TabName.SIMULATION && this.props.validations.getOverallSummary() === ValidationSummary.Error;
	}

	private getTabToolTip(tab: Tab) {
		const isSimulationAndHasErrors = tab.getTitle() === TabName.SIMULATION
			&& this.props.validations.getOverallSummary() === ValidationSummary.Error;

		return isSimulationAndHasErrors ? `${TabName.SIMULATION} (please fix errors...)` : tab.getTitle();
	}
}
