import * as _ from "lodash";
import {
	MetaContentConfigurableMgr,
	isBooleanConfigurable,
} from "./configurables/configurable";

import { AMemberMgr, SetSource } from "./member";

import { EnumerationOption } from "public/defs";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";

/**
 * Base class to group configurables. Utilized to provide a top level UI element that can
 * can act on all grouped configurables.
 */
export abstract class AHeader<ValueType> {
	protected value: ValueType;

	constructor(
		public name: string,
		public displayName: string,
		initValue: ValueType,
		private configurables: AMemberMgr<ValueType>[],
	) {
		this.value = initValue;
	}

	public abstract setValue(value: ValueType): void;

	public getValue() {
		return this.value;
	}

	public isHidden() {
		return !_.some(this.configurables, (c) => !c.uiState.hidden);
	}

	public isReadOnly() {
		return !_.some(this.configurables, (c) => !c.uiState.readOnly);
	}

	protected setConfigurables(value: ValueType) {
		_.each(
			_.filter(this.configurables, (c) => !c.uiState.readOnly),
			(c) => c.set(value, SetSource.USER_ASSIGN));
	}

}

class PrimitiveHeader<ValueType> extends AHeader<ValueType> {
	public setValue(value: ValueType) {
		this.value = value;
		this.setConfigurables(value);
	}
}

export class BooleanHeader extends PrimitiveHeader<boolean> { }
class TextHeader extends PrimitiveHeader<string> { }
export class EnumerationHeader extends PrimitiveHeader<string> {
	constructor(
		name: string,
		displayName: string,
		configurables: EnumerationConfigurableMgr[],
		public options: EnumerationOption[],

	) {
		super(name, displayName, options[0].name, configurables);
	}
	public getSelectedOption() {
		return _.find(this.options, (o) => o.name === this.value);
	}
}

export type ConfigurableHeader = BooleanHeader | TextHeader | EnumerationHeader;
export interface NameToConfigurableHeader {
	[name: string]: ConfigurableHeader;
}

// create list of header pseudo configurables that control 
export function createHeader(
	configurables: MetaContentConfigurableMgr[],
) {

	// group configurables with same name
	const groups = _.groupBy(configurables, (c) => c.def.name);
	const headers: NameToConfigurableHeader = {};

	_.each(groups, (group) => {

		// take the first item in the group to create the header from
		const configurable = _.first(group);
		const def = configurable.def;

		if (configurable instanceof EnumerationConfigurableMgr) {
			headers[def.name] = new EnumerationHeader(
				def.name,
				def.displayName,
				group as EnumerationConfigurableMgr[],
				configurable.getOptions()
			);
		} else if (isBooleanConfigurable(def)) {
			headers[def.name] = new BooleanHeader(
				def.name,
				def.displayName,
				def.default,
				group as AMemberMgr<boolean>[],
			);
		} else {
			throw new Error("Unsupported type!");
		}
	});

	return headers;
}
