import * as _ from "lodash";
import { Module, StandardConfigurable } from "public/defs";
import { ModuleInstance } from "public/runtime";

export const namedConnectionModuleName = "/ti/coreSysConfig/namedConnection";

export function getNamedConnectionModule(): Module {

	function extendConfig({ $ipInstance }: Pick<ModuleInstance, "$ipInstance">) {

		// Named connections will have one input and maybe one output.  If there is an output, it has to be hooked up
		// directly to the input

		const input = {
			name: "in",
			displayName: "Frequency",
			default: 0,
			getValue: () => 0,
		};

		if (!_.isEmpty($ipInstance.outPins)) {
			return [input, {
				name: "out",
				default: 0,
				getValue: (inst: ModuleInstance<{ in: { default: number } }>) => inst.in,
				hidden: true,
			}] as StandardConfigurable[];
		}
		return [input];
	}

	return {
		extendConfig,
	};
}
