import { andPath } from "./AndNode";
import { createFinalSvgPathNode } from "../createSvgPathNode";
import { notCirclePath, notCircleDiameter } from "./NotNode";

// Node for a NAND gate

function nandPath(width: number, height: number) {
	return andPath(width - notCircleDiameter, height) + notCirclePath(width, height);
}

// There will only ever be one output, so hight-based adjustments aren't needed.

export const NandNode = createFinalSvgPathNode(nandPath, { extraWidth: notCircleDiameter, outputLabelXOffset: () => -notCircleDiameter });
