import * as React from "react";
import type * as Plotly from "plotly.js-basic-dist-min";
import { ErrorStore } from "../errorStore";
import { assertNeverThrows } from "../utils";

// Web-pack function to dynamically fetch plotly on demand

function fetchPlotly() {
	return new Promise<typeof Plotly>((resolve, reject) => {
		require.ensure(
			[],
			(require) => resolve(require("plotly.js-basic-dist-min")),
			reject,
			"plotly.js-basic-dist-min");
	});
}

// React hook to get plotly 

export function usePlotly(errorStore: ErrorStore) {
	const [plotly, setPlotly] = React.useState<typeof Plotly>(null);
	React.useEffect(() => {
		assertNeverThrows(errorStore, async () => setPlotly(await fetchPlotly()));
	}, [errorStore, setPlotly]);
	return plotly;
}
