
// Every point on the graph must be aligned to this number

export const minimumGridAlignment = 5;

// This is the minimum distance between edges, which must be a multiple of the grid alignment above

export const minimumEdgeSeparation = minimumGridAlignment * 2;

// By making the node size a multiple of six and the minimum edge size, we can divide the ports up evenly by 1, 2, 3 
// and 5 and have them evenly aligned on the minimum grid aligment;

export const minimumNodeSize = minimumEdgeSeparation * 6;
