import * as _ from "lodash";
import { RuntimeInstance } from "public/runtime";
import { isIOptions } from "../../pinmux/services/objectManagers/options";
import { Runtime } from "../../pinmux/services/resources/runtime";
import { getManager } from "./getManager";

export function getOptions<T extends number | string>(runtime: Runtime, instance: RuntimeInstance, memberName: string) {

	const { memberMgr } = getManager(runtime, instance, memberName);

	if (isIOptions<T>(memberMgr)) {
		return memberMgr.getCLIOptions();
	} else {
		throw new Error(`getOptions not supported on member : ${memberName}`);
	}
}
