import * as _ from "lodash";
import * as Layout from "../../graph/types/layoutTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { PositionMemberMgr } from "../../../services/objectManagers/positionMemberMgr";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";
import { routeEdges } from "./routeEdges";
import { combineSegments } from "./combineSegments";
import { minimumEdgeSeparation, minimumNodeSize } from "./constants";
import { getNodeAdjustments } from "../nodes/NodeFactory";
import { NodeLayoutAdjustments } from "../../graph/nodes/withLayoutAdjustments";

export function getLayout(nodeInsts: ModuleInstanceMgr[]): Layout.Group<ModuleInstanceMgr, PortMemberMgr> {
	const nodes = getUnroutedLayout(nodeInsts);
	const maxX = _.maxBy(nodes, (n) => n.x + n.width);
	const maxY = _.maxBy(nodes, (n) => n.y + n.height);
	const directEdges = _.flatMap(nodeInsts, getEdges);
	const orthogonalSegments = routeEdges(nodes, directEdges);
	const { joints, edges } = combineSegments(orthogonalSegments);
	return {
		id: "$root",
		x: 0,
		y: 0,
		width: maxX ? maxX.x + maxX.width : 0,
		height: maxY ? maxY.y + maxY.height : 0,
		nodes,
		groups: [],
		edges,
		joints,
		name: "root",
		displayName: "",
	};
}

export function getUnroutedLayout(nodeInsts: ModuleInstanceMgr[]) {
	return _.map(nodeInsts, toNode);
}

export const maxPortsBeforeGrowth = minimumNodeSize / minimumEdgeSeparation - 1;
function getMinNodeSize(inst: ModuleInstanceMgr) {
	const maxPortsOneSide = _.maxBy(inst.getPorts(), (p) => p.length).length;
	if (maxPortsOneSide > maxPortsBeforeGrowth) {
		return (maxPortsOneSide + 1) * minimumEdgeSeparation; // Ensure no port is closer than the minimum. 
	}
	return minimumNodeSize;
}

export function getNodeSize(inst: ModuleInstanceMgr): Layout.Size {
	const nodeSize = getMinNodeSize(inst);
	const { extraWidth, heightFactor, widthFactor } = getNodeAdjustments(inst);
	return { width: (nodeSize * widthFactor) + extraWidth, height: nodeSize * heightFactor };
}

function toNode(inst: ModuleInstanceMgr): Layout.Node<ModuleInstanceMgr, PortMemberMgr> {
	const [x, y] = (inst.memberMgrs.$position as PositionMemberMgr).getValue();
	const [outputs, inputs] = inst.getPorts();
	const nodeSize = getNodeSize(inst);
	const adjustments = getNodeAdjustments(inst);
	return {
		id: inst.getID(),
		x,
		y,
		...nodeSize,
		ports: [
			..._.map(inputs, (port, index) => toPort(nodeSize, adjustments, port, index, inputs.length)),
			..._.map(outputs, (port, index) => toPort(nodeSize, adjustments, port, index, outputs.length)),
		],
		inst,
	};
}

const portSize = 8;

function toPort(
	nodeSize: Layout.Size, adjustments: NodeLayoutAdjustments, port: PortMemberMgr, index: number, total: number
): Layout.Port<PortMemberMgr> {
	const y = adjustments.portYOffset(nodeSize, index, total);
	const x = port.def.type === "output"
		? adjustments.outputPortXOffset(nodeSize, y) + nodeSize.width
		: adjustments.inputPortXOffset(nodeSize, y) - portSize;
	return {
		id: port.getID(),
		x,
		y,
		width: portSize,
		height: portSize,
		memberMgr: port,
		type: port.def.type,
	};
}

function getEdges(inst: ModuleInstanceMgr): Layout.Edge<PortMemberMgr>[] {
	const [outputs] = inst.getPorts();
	if (!outputs) {
		return [];
	}
	return _.flatMap(outputs, (source) =>
		_.map(source.getPortConnections(), ({ port: target, implied }) => ({
			id: source.getID() + target.getID(),
			start: getPoint(source),
			end: getPoint(target),
			source: source,
			targets: [target],
			implied,
		})));
}

export function getPoint(port: PortMemberMgr) {
	const node = port.getEnclosingNode();
	const [nodeXOffset, nodeYOffset] = (node.memberMgrs.$position as PositionMemberMgr).getValue();
	const [outputs, inputs] = node.getPorts();
	const ports = port.def.type === "output" ? outputs : inputs;
	const nodeSize = getNodeSize(node);
	const adjustments = getNodeAdjustments(node);
	const y = adjustments.portYOffset(nodeSize, _.indexOf(ports, port), ports.length);
	const x = port.def.type === "output"
		? adjustments.outputPortXOffset(nodeSize, y) + nodeSize.width
		: adjustments.inputPortXOffset(nodeSize, y);
	return {
		x: x + nodeXOffset,
		y: y + nodeYOffset,
	};
}

