import * as _ from "lodash";
import React = require("react");
import { InputFormatter } from "../services/formatting/inputFormatter";
import { Input } from "../imports/material-ui-imports";
import { tiTeal } from "./styles/colors";
import { IBasicInputProps } from "./InputBox";
import { commonStyles } from "./styles/common";

interface ICombinationBoxProps extends IBasicInputProps {
	formatter: InputFormatter;
}

interface ICombinationBoxState {
	borderBottomStyle: string;
	focused: boolean;
}

const borderLight = "inset 0 -1px grey";
const borderTeal = "inset 0 -2px" + tiTeal[700];

export class CombinationBox extends React.Component<ICombinationBoxProps, ICombinationBoxState> {
	private elementRefs: HTMLInputElement[];
	private containerRef: HTMLDivElement;
	private readonly placeholder: string[];

	constructor(props: ICombinationBoxProps) {
		super(props);
		this.state = {
			borderBottomStyle: borderLight,
			focused: false,
		};
		this.placeholder = this.props.placeholder && this.props.formatter.verifyEntireString(this.props.placeholder) ?
			_.chain(this.props.placeholder)
				.split(this.props.formatter.delimiter)
				.map((part) => this.props.formatter.formatPartOfString(part))
				.value()
			: Array(this.props.formatter.numOfParts).fill("");
		this.elementRefs = [];
	}

	public override componentDidMount() {
		document.addEventListener("keydown", this.handleGlobalKeyDown);
		document.addEventListener("focus", this.containerFocusListener, true);
		document.addEventListener("blur", this.containerBlurListener, true);
	}

	public override componentWillUnmount() {
		document.removeEventListener("keydown", this.handleGlobalKeyDown);
		document.removeEventListener("focus", this.containerFocusListener, true);
		document.removeEventListener("blur", this.containerBlurListener, true);
	}

	public override render() {
		return (
			<div
				id={this.props.id + "combBox"}
				style={{
					display: "inline-block",
					cursor: "text",
					whiteSpace: "nowrap",
					overflow: "hidden",
					outline: "none",
					boxShadow: this.state.borderBottomStyle,
				}}
				onCopy={(e) => { this.handleCopy(e); }}
				onMouseOver={() => {
					if (!this.state.focused && !this.props.disabled) {
						this.setState({ borderBottomStyle: borderTeal });
					}
				}}
				onMouseLeave={() => {
					if (!this.state.focused) {
						this.setState({ borderBottomStyle: borderLight });
					}
				}}
				tabIndex={0}
				ref={(el) => this.containerRef = el}
			>
				{
					// Each part of the string maps to an Input
					_.map(_.split(this.props.value, this.props.formatter.delimiter),
						(part, index) => {
							return (
								<span key={index.toString()}>
									<Input
										id={this.props.id + index}
										type="text"
										inputRef={(element) => { this.elementRefs[index] = element; }}
										value={part}
										placeholder={this.placeholder[index]}
										onChange={(e) => this.handleChange(e, index)}
										onKeyDown={(e) => this.handleKeyDown(e, index)}
										onPaste={(e) => this.handlePaste(e, index)}
										onClick={(e) => this.handleOnClick(e, index)}
										disabled={this.props.disabled}
										disableUnderline
										style={{
											...commonStyles.inputTextStyle,
											display: "inline-block",
											width: "90%",
											maxWidth: 10 * this.props.formatter.maxLengthOfPart,
										}}
										inputProps={{
											style: { textAlign: "center" },
										}}
									/>
									{index !== this.props.formatter.numOfParts - 1 &&
										<Input
											disableUnderline
											disabled={this.props.disabled}
											defaultValue={this.props.formatter.delimiter}
											style={{
												...commonStyles.inputTextStyle,
												display: "inline-block",
												width: "10%",
												maxWidth: 10 * this.props.formatter.delimiter.length,
											}}
											inputProps={{
												style: { textAlign: "center" },
												readOnly: true,
											}}
										/>
									}
								</span>

							);
						})
				}
			</div >
		);
	}

	private handleChange(e: React.ChangeEvent<HTMLTextAreaElement | HTMLInputElement>, index: number) {
		const newValue = e.target.value;
		const formatter = this.props.formatter;

		// Block illegal character entry
		if (!_.every(newValue, (char) => formatter.verifyLegalCharsetOfPart(char))) {
			return;
		}

		// For other illegal formatting, move to the next field if possible
		if (newValue.length > formatter.maxLengthOfPart ||
			!formatter.verifyNumericValueOfPart(newValue)
		) {
			if (index < formatter.numOfParts - 1) {
				const oldValue = this.getSplitString();
				oldValue[index + 1] = newValue.charAt(newValue.length - 1);
				this.changeValue(oldValue);
				this.jumpTo(index + 1, "end");
			}
			return;
		}

		const oldValue = this.getSplitString();
		oldValue[index] = newValue;
		this.changeValue(oldValue);
	}

	private handleKeyDown(e: React.KeyboardEvent<HTMLTextAreaElement | HTMLInputElement>, index: number) {
		const formatter = this.props.formatter;
		if (e.key === "ArrowLeft" && e.currentTarget.selectionStart === 0 && index > 0) {
			this.arrowLeftKeyDown(index, e);
		} else if (e.key === "ArrowRight"
			&& e.currentTarget.selectionEnd === e.currentTarget.value.length
			&& index < formatter.numOfParts - 1) {
			this.arrowRightKeyDown(index, e);
		} else if ((e.key === "Tab" || e.key === formatter.delimiter.charAt(0))
			&& index < formatter.numOfParts - 1) {
			this.tabKeyDown(index, e);
		} else if (e.key === "Backspace") {
			this.backspaceKeyDown(e, index);
		} else if (e.key === formatter.delimiter && index < formatter.numOfParts - 1) {
			this.jumpTo(index + 1, "start");
			e.preventDefault();
		} else if (e.key === "a" && e.ctrlKey) {
			this.selectAll();
			e.preventDefault();
		}
	}

	private backspaceKeyDown(e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>, index: number) {
		if (this.isMultiSelected()) {
			this.handleMassDelete();
		}
		if (e.currentTarget.selectionStart === e.currentTarget.selectionEnd
			&& e.currentTarget.selectionStart === 0
			&& index > 0) {
			this.jumpTo(index - 1, "end");
		}
	}

	private tabKeyDown(index: number, e: React.KeyboardEvent<HTMLTextAreaElement | HTMLInputElement>) {
		this.jumpTo(index + 1, "all");
		e.preventDefault();
	}

	private arrowRightKeyDown(index: number, e: React.KeyboardEvent<HTMLTextAreaElement | HTMLInputElement>) {
		this.jumpTo(index + 1, "start");
		e.preventDefault();
	}

	private arrowLeftKeyDown(index: number, e: React.KeyboardEvent<HTMLTextAreaElement | HTMLInputElement>) {
		this.jumpTo(index - 1, "end");
		e.preventDefault();
	}

	private handlePaste(e: React.ClipboardEvent<HTMLDivElement>, index: number) {
		const formatter = this.props.formatter;
		const pastedValue = _.chain(e.clipboardData.getData("text/plain"))
			.split(formatter.delimiter)
			.map((part) => _.trim(part))
			.value();
		const oldValue = this.getSplitString();
		_.each(pastedValue, (val, subindex) => {
			// Allow string with any amount of parts to be pasted, but will slice off parts that do not fit.
			if (index + subindex > oldValue.length - 1) {
				return false;
			}
			// Allow individual parts of any length to be pasted, but will slice off parts that do not fit.
			val = val.length > formatter.maxLengthOfPart ? val.substring(0, formatter.maxLengthOfPart) : val;
			// Check if the part is legal. I.e. character legality and value legality. Skip if illegal
			if (!formatter.verifyLegalCharsetOfPart(val) || !formatter.verifyNumericValueOfPart(val)) {
				return undefined;
			}
			oldValue[index + subindex] = val;
			return undefined;
		});
		this.changeValue(oldValue);
		return e.preventDefault();
	}

	// Handle copying in the combined level.
	private handleCopy(e: React.ClipboardEvent<HTMLSpanElement>) {
		const selection = window.getSelection();
		const selectedElementValue: string[] = [];
		_.each(this.elementRefs, (el, key) => {
			if (selection.containsNode(el, false)) {
				selectedElementValue.push(this.getSplitString()[key]);
			}
		});
		if (selectedElementValue.length !== 0) {
			e.clipboardData.setData("text/plain", _.join(selectedElementValue, this.props.formatter.delimiter));
			e.preventDefault();
		}
	}

	// Highlight box content when clicked
	private handleOnClick(e: React.MouseEvent<HTMLDivElement>, index: number) {
		this.jumpTo(index, "all");
		e.preventDefault();
	}

	// handle deletion in the combine level.
	private handleMassDelete() {
		const selectedElementKeys = this.isMultiSelected();
		if (selectedElementKeys) {
			const oldValue = this.getSplitString();
			_.each(selectedElementKeys, (key) => {
				oldValue[key] = "";
			});
			this.elementRefs[selectedElementKeys[0]].focus();
			this.changeValue(oldValue);
		}
	}

	// handle global key down effect to allow rudimentary drag selection
	private handleGlobalKeyDown = (e: KeyboardEvent) => {
		const selectedElementKeys = this.isMultiSelected();
		if (selectedElementKeys && (
			this.props.formatter.verifyLegalCharsetOfPart(e.key)
			|| e.key === "Delete"
			|| e.key === "Backspace"
			|| e.key === this.props.formatter.delimiter)
			&& !e.ctrlKey && !e.altKey && !e.shiftKey
		) {
			this.handleMassDelete();
		}
	}

	// Jump to the Input at index and position the cursor.
	private jumpTo(index: number, select?: "all" | "start" | "end") {
		const endCursor = this.getSplitString()[index].length;
		const startCursor = 0;
		this.elementRefs[index].focus();
		if (select === "start") {
			this.elementRefs[index].setSelectionRange(startCursor, startCursor);
		} else if (select === "end") {
			this.elementRefs[index].setSelectionRange(endCursor, endCursor);
		} else {
			this.elementRefs[index].setSelectionRange(startCursor, endCursor);
		}
	}

	// Select all of the Inputs and the delimiters in between.
	private selectAll() {
		const rangeObj = document.createRange();
		const selection = window.getSelection();
		rangeObj.setStartBefore(this.elementRefs[0]);
		rangeObj.setEndAfter(this.elementRefs[this.elementRefs.length - 1]);
		selection.removeAllRanges();
		selection.addRange(rangeObj);
	}

	// Check if multiple input box is selected and return the start and end
	private isMultiSelected() {
		const selection = window.getSelection();
		const selectedElementKeys: number[] = [];
		_.each(this.elementRefs, (el, key) => {
			if (selection.containsNode(el, false)) {
				selectedElementKeys.push(key);
			}
		});
		if (selectedElementKeys.length > 0) {
			return selectedElementKeys;
		} else {
			return null;
		}
	}

	private getSplitString() {
		return this.props.value.split(this.props.formatter.delimiter);

	}

	private changeValue(newValue: string[]) {
		this.props.onChange(_.join(newValue, this.props.formatter.delimiter));
	}

	private containerFocusListener = (ev: FocusEvent) => {
		if (this.containerRef) {
			if (this.containerRef.contains(ev.target as HTMLElement) && !this.state.focused) {
				if (!this.props.disabled) {
					this.setState({ focused: true, borderBottomStyle: borderTeal });
				}
			}
		}
	}

	private containerBlurListener = (ev: FocusEvent) => {
		if (this.containerRef) {
			if (!this.containerRef.contains(ev.relatedTarget as HTMLElement)
				&& this.state.focused
				&& this.containerRef.contains(ev.target as HTMLElement)
			) {
				if (this.props.onBlur) {
					this.props.onBlur();
				}
				this.setState({ focused: false, borderBottomStyle: borderLight });
			}
		}
	}
}
