import * as _ from "lodash";
import { InstanceArgType } from "../member";
import { ModuleInstanceRequirement } from "public/defs";
import { Runtime } from "../../resources/runtime";
import { Statement } from "../../scripting/serialize";
import { createUIStatements } from "../viewNodes";
import { SerializationOptions } from "../../scripting/toScript";
import { InstanceMemberMgr } from "./instanceMemberMgr";
import { ModuleInstanceMgr } from "../moduleInstance";
import { getRemovedArgs, getNewArgs, getUpdatedArgs } from "../moduleArgs";
import { forbiddenModification } from "../../utils";

export class ModuleInstanceMemberMgr
	extends InstanceMemberMgr<ModuleInstanceMgr, ModuleInstanceRequirement> {

	constructor(
		runtime: Runtime,
		valueObjectMgr: ModuleInstanceMgr,
		def: ModuleInstanceRequirement,
		parentObjectMgr: ModuleInstanceMgr,
		collapsed: boolean,
	) {
		super(valueObjectMgr, runtime, def, parentObjectMgr, { collapsed });
		this.valueObjectMgr.setValueFromRequiredArgs(
			this.def.requiredArgs,
			this.parentObjectMgr,
		);
		this.valueObjectMgr.setValueFromArgs(this.def.args, InstanceArgType.META);
		this.checkForHiddenArgs();
	}

	public reApplyArgs() {
		this.valueObjectMgr.removeReqArgs(this.def.requiredArgs, this.parentObjectMgr);
		this.valueObjectMgr.setValueFromRequiredArgs(
			this.def.requiredArgs,
			this.parentObjectMgr,
		);
		this.valueObjectMgr.setValueFromArgs(this.def.args, InstanceArgType.REAPPLY);
		this.checkForHiddenArgs();
	}

	public updateArgs(newReq: ModuleInstanceRequirement) {

		this.valueObjectMgr.removeReqArgs(this.def.requiredArgs, this.parentObjectMgr);

		this.valueObjectMgr.removeArgs(getRemovedArgs(this.def.args, newReq.args));

		this.valueObjectMgr.setValueFromRequiredArgs(newReq.requiredArgs, this.parentObjectMgr);

		// The following functions are called twice because it new args and updated args cannot be combined easily
		this.valueObjectMgr.setValueFromArgs(
			getNewArgs(this.def.args, newReq.args),
			InstanceArgType.META,
		);

		this.valueObjectMgr.setValueFromArgs(
			getUpdatedArgs(this.def.args, newReq.args),
			InstanceArgType.META,
		);

		this.def.requiredArgs = newReq.requiredArgs;
		this.def.args = newReq.args;
		this.checkForHiddenArgs();
	}

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions): Statement[] {

		let statements = super.generateScriptStatements(parentIdentifier, options);
		if (options.includeUIState) {
			statements = [
				...statements,
				...createUIStatements(parentIdentifier, this),
			];
		}

		return statements;
	}

	protected override validateValue() {
		forbiddenModification("Cannot assign to owned module instance");
	}
}
