import { ButtonClickResult, ButtonConfigurable } from "public/defs";
import { IModalService } from "../../IModalService";
import { storage } from "../../storage";
import { ButtonConfigurableMgr } from "./buttonConfigurableMgr";

export class StandardButtonConfigurableMgr<
	MemberDefinition extends ButtonConfigurable<ButtonClickResult> = ButtonConfigurable<ButtonClickResult>
	> extends ButtonConfigurableMgr<ButtonClickResult, MemberDefinition> {

	public override async getClickResultImpl(
		_productPath: string, _modalService: IModalService, options: { filePath?: string }): Promise<ButtonClickResult> {
		const fileOrFolder = options?.filePath;
		const popupModuleInst = this.getPopupMgr()?.managedObject;
		if (fileOrFolder && !this.def.pickDirectory) {
			const { data } = await storage.openFile(fileOrFolder);
			return { fileOrFolder, fileContents: data, popupModuleInst };
		}
		return { fileOrFolder, popupModuleInst };
	}
}
