import React = require("react");
import { commonStyles } from "../styles/common";
import { TableRow, TableCell } from "../../imports/material-ui-imports";

export class ConfigViewEntry extends React.Component<{ id: string; columns: number, noPadding?: boolean }> {
	public override render() {
		return (
			<TableRow style={commonStyles.tableRowStyle} >
				<TableCell
					id={this.props.id}
					style={this.props.noPadding ? commonStyles.unpaddedTableCellStyle : commonStyles.tableCellStyle}
					colSpan={this.props.columns}
				>
					{this.props.children}
				</TableCell>
			</TableRow>
		);
	}
}
