import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";

// A small circle to indicate that two edges connect vs cross over each other

interface IProps {
	joint: Layout.Point;
	className: string;
}

export function Joint({ joint, className }: IProps) {
	return (
		<circle
			r={4}
			cx={joint.x}
			cy={joint.y}
			className={className}
		/>
	);
}
