import * as _ from "lodash";
import { isCloud, isNodeWebkit } from "../../pinmux/services/platform";
import { envMap } from "../core/asyncCreateEnv";
import { CoreExports, SysConfigEnv } from "embed/core";
import { clearSysConfigCache } from "../../pinmux/services/sysConfigFactory";
import { TabName, UIExports } from "embed/widgets";
import { enableTestHooks } from "../../pinmux/services/testability";
import { extractStringFromRoute } from "../../pinmux/services/routing";
import { getMessageAndStack } from "../../pinmux/services/niceExceptions";

if (testParameterSet()) {
	let currentEnv: SysConfigEnv;
	let currentMount: HTMLElement;
	enableTestHooks({

		sysconfigTest_asyncCreateEnv: async (
			modalRoot: string, notificationRoot: string, args: string[], onComplete: (err: string | null) => void
		) => {
			try {
				const { asyncCreateEnv, unmount } = getSysConfig();

				// Cleanup previous environment and mount points, if they exist

				if (currentEnv) {
					if (currentMount) {
						unmount(currentMount);
						currentMount = null;
					}
					const { modalService } = envMap.get(currentEnv).globalServices;
					modalService.reset();
					clearSysConfigCache();
					if ((window as any).gc) {
						(window as any).gc();
					}
				}

				// Create a new environment and save it for later

				currentEnv = await asyncCreateEnv(
					modalRoot ? document.getElementById(modalRoot) : null,
					notificationRoot ? document.getElementById(notificationRoot) : null,
					args);
			} catch (e) {
				onComplete(e instanceof Error ? getMessageAndStack(e) : e.toString());
			}
			onComplete(null);
		},

		sysconfigTest_mountTab: (reactRoot: string, tabName: TabName, onComplete: (err: string | null) => void) => {
			try {

				// Clean up existing mount points, if they exist

				const { mountTab, unmount } = getSysConfig();
				if (currentMount) {
					unmount(currentMount);
				}

				// Mount and save the mount for for later unmounting

				currentMount = reactRoot ? document.getElementById(reactRoot) : null;
				mountTab(currentMount, currentEnv, tabName);
			} catch (e) {
				onComplete(e instanceof Error ? getMessageAndStack(e) : e.toString());
			}
			onComplete(null);
		},

		getSysConfig_getEnv: async (callback: (env: SysConfigEnv) => Promise<void> | void, onComplete: (err: string | null) => void) => {
			try {
				await callback(currentEnv);
			} catch (e) {
				onComplete(e instanceof Error ? getMessageAndStack(e) : e.toString());
			}
			onComplete(null);
		},
	});
}

function getSysConfig() {
	return (window as any).ti.SysConfig as CoreExports & UIExports;
}

function testParameterSet() {
	return (isNodeWebkit() && _.includes(nw.App.argv, "--test"))
		|| (isCloud() && extractStringFromRoute(window.location, "test"));
}
