import * as _ from "lodash";
import * as data from "dataInterfaces";
import { AbstractChoice, AbstractErrorChoice, RelatedChoices, RelatedSharedChoices } from "./common";
import { PinConflictTracker } from "../conflictTracker";
import { SuggestedSolution } from "../suggestedSolution";
import { nameChoices, formatNameChoice } from "../debug";
import { Pin } from "../requirements";
import { clearSolution, addErrorToSolution } from "../../utils";
import {
	mutuallyExcludeUnsharedChoices,
	dependentChoices,
	chooseAtLeastOneOf,
	mutuallyExclude,
} from "../clauseGeneration";
import { SolutionMap } from "../choices";
import { Optimizations, PinRestrictions, Restrictive } from "../optimizations";

interface ParentChoice extends AbstractChoice {
	getRequirementId: () => string;
	getShareHash: () => string;
	hasError: () => boolean;
}

// -----------------------------------------------------------------------------
// InterfacePinChoices
// A factory for creating a choice of a specific peripheral pin to meet a pin 
// requirement of one or more interface pins.
// -----------------------------------------------------------------------------

export class InterfacePinChoices {
	public readonly sharedChoices: { [sharedHash: string]: InterfacePinChoices.Choice[] } = {};
	public readonly allowedConflicts: { [assignment: string]: InterfacePinChoices.Choice[] } = {};
	private readonly byPeripheral = new RelatedChoices<number, InterfacePinChoices.Choice>();
	private readonly byInterfacePin = new RelatedSharedChoices<string, InterfacePinChoices.Choice>();
	private readonly byRequirement = new RelatedChoices<string, InterfacePinChoices.Choice>();
	private readonly errors: { [key: string]: InterfacePinChoices.Error } = {};
	private readonly sometimesRestrictive: { choice: InterfacePinChoices.Choice, name: string }[] = [];
	private readonly requirements: {
		[key: string]: {
			parentChoice: ParentChoice,
			pinReq: Pin,
			restricts: PinRestrictions,
		},
	} = {};

	constructor(
		private readonly suggestedSolution: SuggestedSolution,
		private readonly conflictAllower: PinConflictTracker,
		private readonly optimizations: Optimizations,
	) { }

	public newChoice(
		parentChoice: ParentChoice,
		peripheralPin: data.PeripheralPin,
		pinReq: Pin) {

		const requirementName = parentChoice.getRequirementId() + "->" + pinReq.getUnqualifiedName();
		if (!this.requirements[requirementName]) {
			this.requirements[requirementName] = {
				parentChoice,
				pinReq,
				restricts: this.optimizations.restrictions(pinReq),
			};
		}

		// Ensure the key is added, so we can't choose a peripheral where a requested interface pin has no choices

		this.byRequirement.addKey(requirementName);

		if (!peripheralPin) {
			return null;
		}

		const choice = new InterfacePinChoices.Choice(parentChoice, peripheralPin, pinReq);
		this.byRequirement.get(requirementName).push(choice);
		this.byPeripheral.get(parentChoice.id).push(choice);

		// If this restricts optimizable pins only sometimes, keep track of that.

		if (_.some(this.requirements[requirementName].restricts, (restriction) => Restrictive.SOMETIMES === restriction)) {
			this.sometimesRestrictive.push({ choice, name: requirementName });
		}

		if (this.conflictAllower.areConflictsAllowed(pinReq)) {

			// Add it under it's own unique category of shared pins

			const sharedHash = "allowedToConflict" + pinReq.userOverride;
			this.byInterfacePin.get(peripheralPin.name).pushShared(choice, sharedHash);

			// We must also keep track of it separately so that conflicts that are taken
			// correctly are counted when minimizing for optimizable pins

			this.allowedConflicts[pinReq.userOverride] = this.allowedConflicts[pinReq.userOverride] || [];
			this.allowedConflicts[pinReq.userOverride].push(choice);

		} else if (pinReq.canShareWith) {

			// Include the interface name in the key
			// Ensures we only share peripherals when used as the same interface

			const sharedHash = parentChoice.getShareHash() + pinReq.canShareWith;
			this.byInterfacePin.get(peripheralPin.name)
				.pushShared(choice, sharedHash);

			const shareableReqsHash = sharedHash + peripheralPin.interfacePin.id;
			this.sharedChoices[shareableReqsHash] = this.sharedChoices[shareableReqsHash] || [];
			this.sharedChoices[shareableReqsHash].push(choice);
		} else {
			this.byInterfacePin.get(peripheralPin.name).push(choice);
		}

		return choice;
	}

	public generateClauses() {
		const getPinError = (choiceName: string) => this.getPinError(choiceName);
		chooseAtLeastOneOf(this.byRequirement, getPinError, "each pin requirement must choose one interface pin mapping");
		dependentChoices(this.byPeripheral, "interface pins can only be chosen if their peripheral is also chosen");
		mutuallyExcludeUnsharedChoices(this.byInterfacePin,
			"only choose an interface pin for a specific peripheral once, unless shared");

		// Normally it's faster to allow the solver to choose an interface pin, even if marked as an error.  The error
		// choice is always created later, and thus applied later, and thus will erase that decision.  And the error
		// may only be set in order to free up optimizable pins, so letting the solver pick a pin vs an error doesn't 
		// hurt.  
		//
		// However, if it only sometimes restricts optimizable pins, then the choice will also be involved in 
		// optimizable pin minimization once we run low on pins.  Since we mark it as freeing up an optimizable pin 
		// when marked as an error, it's important that it doesn't get counted twice.  Thus we need to ensure we
		// explicitly do NOT pick anything for it in those cases.

		_.each(this.sometimesRestrictive, ({ choice, name }) => mutuallyExclude(choice, getPinError(name),
			"never choose an interface pin if it has an error and sometimes restricts an optimizable pin"));
	}

	private getPinError(requirementName: string) {
		if (requirementName in this.errors) {
			return this.errors[requirementName];
		}

		const { parentChoice, pinReq, restricts } = this.requirements[requirementName];
		return this.errors[requirementName] = new InterfacePinChoices.Error(
			parentChoice, pinReq, requirementName, _.keys(restricts), this.suggestedSolution);
	}
}

export namespace InterfacePinChoices {
	export class Choice extends AbstractChoice {

		constructor(
			public readonly parentChoice: ParentChoice,
			public readonly peripheralPin: data.PeripheralPin,
			public readonly pinReq: Pin) {
			super();

			if (nameChoices) {
				this.name = "Interface Pin " + formatNameChoice(pinReq) + "->" + peripheralPin.interfacePin.name;
			}
		}

		public apply() {
			// we don't need to do anything - device pin choice will update the solution
		}
	}

	export class Error extends AbstractErrorChoice {
		constructor(
			private readonly parentChoice: ParentChoice,
			private readonly pinReq: Pin,
			requirementName: string,

			// If it can restrict optimizable pins in any way, mark it as restricting
			// Other SAT clauses will be used to indicate if it solved for the non-restricting case or not

			restricts: string[],
			suggestedSolution: SuggestedSolution) {
			super(
				requirementName,
				restricts,
				suggestedSolution ? suggestedSolution.containsError(pinReq) : false);

			if (nameChoices) {
				this.name = "Resource (pin) conflict " + formatNameChoice(pinReq);
			}
		}

		public apply(solutionMap: SolutionMap) {

			// Remove our entry in the solution map
			// Can occur if interface pin is chosen while also marked an error (allowed for optimization)

			if (this.pinReq.solution.assignedInterfacePin) {

				pullAndDeleteIfEmpty(solutionMap.devicePins, this.pinReq.solution.assignedToName, this.pinReq);
				pullAndDeleteIfEmpty(solutionMap.peripheralPins, this.pinReq.solution.assignedToName, this.pinReq);
			}

			clearSolution(this.pinReq.solution);
			if (!this.parentChoice.hasError()) {
				// If the peripheral couldn't be chosen, we obviously couldn't choose a 
				// pin, so just leave the solution blank

				addErrorToSolution(this.pinReq.solution, "Resource conflict");
			}
		}
	}
}

function pullAndDeleteIfEmpty(collection: Record<string, Pin[]>, key: string, pinReq: Pin) {
	_.pull(collection[key], pinReq);
	if (_.isEmpty(collection[key])) {
		delete collection[key];
	}
}
