import * as _ from "lodash";
import { AbsolutePath } from "public/common";
import { Branding } from "public/defs";
import { ParsedArgs } from "../args/argTypes";
import { getToolVersion } from "../toolVersion";
import { setDocumentAppName } from "../ui/documentTitle";
import { AvailableProductsAndTargets } from "./types";

const defaultBranding: Branding = {
	softwareTitle: "SysConfig",
	version: getToolVersion(),
	links: [
		{
			displayName: "SYSCONFIG INFO",
			actualLink: "https://www.ti.com/tool/SYSCONFIG",
		},
		{
			displayName: "Release Notes",
			actualLink: "https://software-dl.ti.com/ccs/esd/sysconfig/docs/release_notes.html",
		},
		{
			displayName: "Getting Started",
			actualLink: "https://software-dl.ti.com/ccs/esd/sysconfig/docs/getting_started.html",
		},
	],
	softwareDownloadLink: "https://www.ti.com/tool/SYSCONFIG",
};

export function getDefaultBranding() {
	return defaultBranding;
}

export function applyBranding(productBranding: Branding) {
	setDocumentAppName(productBranding.softwareTitle ?? defaultBranding.softwareTitle);
	if (productBranding.icon) {
		changeIcon(productBranding.icon);
	}
}

export function getBranding(availableProducts: AvailableProductsAndTargets[], routeArgs: ParsedArgs) {
	let productBranding: Branding;
	if (routeArgs.product && routeArgs.product.length === 1) {
		const productInfo = _.find(availableProducts, (p) => {
			// on an initial load we can check for the product arg to have the path specified
			// however if we get the product argument from a script the argument will look something like
			// product_name@version and we should account for this
			const productArg = routeArgs.product[0].value;
			return p.path === productArg || productArg === p.name + "@" + p.version;
		});
		if (productInfo?.branding) {
			productBranding = productInfo.branding;
			productBranding.version = productInfo.version;
		}
	}
	return {
		...defaultBranding,
		...productBranding,
	};
}

function changeIcon(newIcon: AbsolutePath) {
	let icon = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
	if (!icon) {
		icon = document.createElement("link");
		icon.rel = "icon";
		document.head.appendChild(icon);
	}
	icon.href = newIcon;
}
