// UI Views for meta content defined configurables
import * as React from "react";
import * as _ from "lodash";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { MultiValueEnumerationConfigurableMgr } from "../../../services/objectManagers/configurables/multiValueEnumerationConfigurableMgr";
import { MultiDropDown } from "../../DropDown";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { ILinkActions } from "../../actions/ILinkActions";
import { CBaseEnumConfigurable } from "./BaseEnumConfigurable";

export class CMultiValueEnumerationConfigurable extends CBaseEnumConfigurable<{
	mgr: MultiValueEnumerationConfigurableMgr<string | number>;
	actions: IConfigurablesActions & ILinkActions;
	formatter: IFormatter;
	displayScriptName: boolean;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const { enabledOptions, disabledOptions } = mgr.getUIOptions();
		// selected options
		const selectedOptions = _.map(mgr.getValue(), (v) => v.toString());
		return (
			<MultiDropDown
				id={mgr.def.name}
				disabled={!!mgr.uiState.readOnly}
				selectedOptionName={selectedOptions}
				enabledOptions={this.formatOptions(enabledOptions)}
				disabledOptions={this.formatOptions(disabledOptions)}
				key={this.state.key} // Force re-render (closing drop down) when navigating away via tooltip
				withNoneOption={mgr.def.placeholder}
				clearable={mgr.minSelections === 0}
				displayScriptName={this.props.displayScriptName}
				onChange={this.onChanged}
				selectAll={mgr.minSelections === 0 && !mgr.def.disableSelectAll}
			/>
		);
	}

	private onChanged = (selectedValues: string[]) => {
		const mgr = this.props.mgr;
		if (selectedValues.length < mgr.minSelections) {
			return;
		}
		if (mgr.isNumeric()) {
			this.props.actions.setConfigurableValue(
				mgr as MultiValueEnumerationConfigurableMgr<number>,
				_.map(selectedValues, (v) => Number(v)));
		} else {
			this.props.actions.setConfigurableValue(mgr as MultiValueEnumerationConfigurableMgr<string>, selectedValues);
		}
	}
}
