import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";
import { keys } from "../../../services/utils";
import { minimumGridAlignment } from "../../graphableModules/layout/constants";

// This wraps a node react component with static properties indicating how the layout for this node.

export interface NodeLayoutAdjustments {
	extraWidth: number;																// How much extra wider should a node of this type be
	heightFactor: number;															// Height multiplier 
	widthFactor: number;															// Width multiplier
	portYOffset: (nodeSize: Layout.Size, index: number, total: number) => number;	// Find the y value for any port
	inputPortXOffset: (nodeSize: Layout.Size, y: number) => number; 				// The x offset for any input port
	outputPortXOffset: (nodeSize: Layout.Size, y: number) => number; 				// The x offset for any output port
}

export const nodeLayoutAdjustmentDefaults: NodeLayoutAdjustments = {
	extraWidth: 0,
	heightFactor: 1,
	widthFactor: 1,
	portYOffset: defaultPortYOffset,
	inputPortXOffset: () => 0,
	outputPortXOffset: () => 0,
};

export function withLayoutAdjustments<T extends {}>(component: T, staticProperties: Partial<NodeLayoutAdjustments>) {
	_.each(keys(nodeLayoutAdjustmentDefaults), (key) => {
		(component as any)[key] = staticProperties[key] ?? nodeLayoutAdjustmentDefaults[key];
	});
	return component as T & NodeLayoutAdjustments;
}

function defaultPortYOffset({ height: nodeHeight }: Layout.Size, index: number, total: number) {

	// We want the ports evenly distributed on the side of the node.  However, we also want the ports aligned to 
	// something divisible by the snap-to-grid amount to ensure anything can be lined up.  If both aren't possible, we
	// evenly distribute them evenly along the snap-to-grid amount, but slightly off of center.

	// How many places can we put a port

	const alignmentPoints = nodeHeight / minimumGridAlignment;
	const sizePerPoint = Math.floor(alignmentPoints / (total + 1));
	const first = sizePerPoint;
	const last = sizePerPoint * total;
	const diff = (first + alignmentPoints - last) / 2;
	const offset = Math.round(diff - first);
	return (offset + sizePerPoint * (index + 1)) * minimumGridAlignment;
}
