import * as React from "react";
import * as _ from "lodash";
import { discriminate, IPInstanceShape } from "../../../services/clockTree/discriminate";
import { assertUnreachable } from "../../../services/utils";
import { DividerNode } from "./DividerNode";
import { GenericNode } from "../../graph/nodes/GenericNode";
import { MuxNode } from "../../graph/nodes/MuxNode";
import { PinFunctionNode } from "../../graph/nodes/PinFunctionNode";
import { MultiplierNode } from "./MultiplierNode";
import { OscillatorNode } from "../../graph/nodes/OscillatorNode";
import { GateNode } from "../../graph/nodes/GateNode";
import { AdderNode } from "../../graph/nodes/AdderNode";
import * as Layout from "../../graph/types/layoutTypes";
import { INodeProps } from "../../graph/types/nodeTypes";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";
import { NamedConnectionNode } from "./NamedConnectionNode";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";

export function isDynamic(node: Layout.Node<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>, frequencyLabels: string[]) {
	const discriminated = discriminate(node.inst.getIpInstance());
	switch (discriminated.shape) {
		case IPInstanceShape.DIVIDER:
			return _.size(discriminated.ipInstance.divideValues) > 1;		// Configurable dividers will have a drop down for the value
		case IPInstanceShape.MULTIPLIER:
			return _.size(discriminated.ipInstance.multiplyValues) > 1;		// Configurable multipliers will have a drop down for the value
		case IPInstanceShape.GATE:											// Gates have a checkbox to enable/disable the gate
		case IPInstanceShape.MUX:											// Muxes have radio buttons that change based on config		
			return true;
		case IPInstanceShape.NAMED_CONNECTION:
			return _.includes(frequencyLabels, node.inst.getName());	// Named connections display the frequency if in this list
		case IPInstanceShape.PIN_FUNCTION:									// All other nodes are purely static rendering
		case IPInstanceShape.OSCILLATOR:
		case IPInstanceShape.ADDER:
		case IPInstanceShape.LARGE_SQUARE:
		case IPInstanceShape.MEDIUM_SQUARE:
		case IPInstanceShape.SMALL_SQUARE:
			return false;
		default:
			assertUnreachable(discriminated);
	}
}

// Based on the ipInstance type, renders the appropriate underlying node component

export function NodeComponent(
	{ frequencyLabels, ...props }: INodeProps<ClockIpInstanceMgr, PinFrequencyConfigurableMgr> & { frequencyLabels: string[] }
) {
	const discriminated = discriminate(props.node.inst.getIpInstance());

	// Filter out the props that are used just for styling so that nodes can render or not based on only the other settings

	switch (discriminated.shape) {
		case IPInstanceShape.DIVIDER:
			return <DividerNode {...props} />;
		case IPInstanceShape.MUX:
			return <MuxNode {...props} />;
		case IPInstanceShape.PIN_FUNCTION:
			return <PinFunctionNode {...props} />;
		case IPInstanceShape.MULTIPLIER:
			return <MultiplierNode {...props} />;
		case IPInstanceShape.OSCILLATOR:
			return <OscillatorNode {...props} />;
		case IPInstanceShape.GATE:
			return <GateNode {...props} />;
		case IPInstanceShape.ADDER:
			return <AdderNode {...props} />;
		case IPInstanceShape.NAMED_CONNECTION:
			return <NamedConnectionNode {...props} frequencyLabels={frequencyLabels} />;
		case IPInstanceShape.LARGE_SQUARE:
		case IPInstanceShape.MEDIUM_SQUARE:
		case IPInstanceShape.SMALL_SQUARE:
			return <GenericNode {...props} />;
		default:
			assertUnreachable(discriminated);
	}
}
