import React = require("react");
import * as _ from "lodash";
import { ModuleInstanceMgr } from "../../services/objectManagers/moduleInstance";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { ConfigStoreActions } from "../../services/configStore";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ResourceLoader, ResourceType } from "../../services/resources/metaContentLoaders/resourceLoader";
import { ContainerNode, ViewNode, LeafNode } from "../../services/objectManagers/viewNodes";
import { CConfigLeafNode } from "./ConfigLeafNode";
import { CPinMux } from "./PinMux";
import { SharedInstanceDropDown } from "./SharedInstanceDropDown";
import { defaultTheme, spacingUnit } from "../styles/themes";
import {
	Typography,
	Card,
	CardHeader,
	CardContent,
	Collapse,
	withStyles,
	List,
	ListItem,
	Table,
	TableBody,
} from "../../imports/material-ui-imports";
import { ChevronDown } from "../../imports/mdi-material-ui-imports";
import { NodeStatusDecorator } from "../Decorators";
import { commonStyles } from "../styles/common";
import { assertUnreachable } from "../../services/utils";
import { CValidation } from "./Validation";
import { LongDescription, DisplayLongDescButton } from "../LongDescription";
import { CModuleInstanceAdder } from "./ModuleInstanceAdder";
import { ConfigViewEntry } from "./ConfigViewEntry";
import { Tooltip } from "../Tooltip";
import { Validations } from "../../services/objectManagers/validations";
import { PinDisplayType } from "../../services/userPreferences";
import { TabContainer } from "./TabContainer";
import { SharedAssignLeafNodeView } from "./SharedAssignLeafNodeView";
import { TabGroup } from "../../services/objectManagers/tabGroup";

export interface IConfigProps {
	instMgr: ModuleInstanceMgr;
	actions: ConfigStoreActions;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	focusedSubItemPath: string[];
	showUsed: boolean;
	showPinTable: boolean;
	arePowerDomainSettingsEnabled: boolean;
	sharedInstanceSubItemPath?: string[];

	// If the module instance is being rendered as a popup than navigation and focus won't work
	isPopup?: boolean;
	tableStyle?: React.CSSProperties;
}

interface CModuleInstanceProps extends React.PropsWithChildren<IConfigProps & IGlobalServiceProps> {
}

export function CModuleInstance({ instMgr, ...rest }: CModuleInstanceProps) {
	const { singleNodes, tabGroup } = instMgr.getUINodes();
	return (<CView {...rest} instMgr={instMgr} viewNodes={singleNodes} readOnly={false} tabGroup={tabGroup} />);
}

interface CViewProps extends CModuleInstanceProps {
	viewNodes: ViewNode[],
	readOnly: boolean,
	tabGroup?: TabGroup
}

export class CView extends React.Component<CViewProps> {

	public override render(): JSX.Element {

		const { viewNodes, readOnly, tabGroup } = this.props;

		let style: React.CSSProperties = { width: "100%" };
		if (readOnly) {
			style = {
				...style,
				...commonStyles.disabled,
			};
		}

		const columns = _.chain(viewNodes)
			.map((n) => n.getNumColumns())
			.max()
			.value();

		return (
			<div className="CView" style={style} onClick={this.onClick} >
				<Table>
					<TableBody>
						{this.props.isPopup &&
							this.props.children
						}
						{
							_.map(viewNodes, (node) => {
								if (node.type === "container") {
									const { singleNodes, tabGroup: nodeTabGroup } = node.getUINodes();
									return node.isHidden() ? null : (
										<ConfigViewEntry id={node.getKey()} key={node.getKey()} columns={columns} noPadding={true}>
											<CContainerNode
												theme={this.props.theme}
												branding={this.props.branding}
												modalService={this.props.modalService}
												notificationService={this.props.notificationService}
												errorStore={this.props.errorStore}
												displayScriptName={this.props.displayScriptName}
												node={node}
												actions={this.props.actions}
												formatter={this.props.formatter}
												productLookupName={this.props.productLookupName}
												resourceLoader={this.props.resourceLoader}
												longDescription={node.getLongDescription()}
												titleNode={node.getTitleNode()}
												validations={this.props.validations}
											>
												<CView
													{...this.props}
													readOnly={readOnly || node.isReadOnly()}
													viewNodes={singleNodes}
													tabGroup={nodeTabGroup}
													focusedSubItemPath={node.matchSubItemPath(this.props.focusedSubItemPath)[1]}
												/>
											</CContainerNode >
										</ConfigViewEntry>
									);
								} else if (node.type === "configLeafNode") {
									const highlightedMember = this.props.focusedSubItemPath.length === 1
										? _.first(this.props.focusedSubItemPath) : "";
									return <CConfigLeafNode
										key={node.getKey()}
										node={node}
										highlightedMember={highlightedMember}
										columns={columns}
										actions={this.props.actions}
										formatter={this.props.formatter}
										validations={this.props.validations}
										displayScriptName={this.props.displayScriptName}
										devicePinDisplayType={this.props.devicePinDisplayType}
										headerPinDisplayType={this.props.headerPinDisplayType}
										resourceLoader={this.props.resourceLoader}
										productLookupName={this.props.productLookupName}
										modalService={this.props.modalService}
										notificationService={this.props.notificationService}
										errorStore={this.props.errorStore}
										theme={this.props.theme}
										branding={this.props.branding}
										isPopup={this.props.isPopup}
									/>;
								} else if (node.type === "instanceArrayLeafNode") {
									return (
										<ConfigViewEntry id={node.getKey()} key={node.getKey()} columns={columns} noPadding={true}>
											<CModuleInstanceAdder
												key={node.getKey()}
												adderMgr={node}
												actions={this.props.actions}
												formatter={this.props.formatter}
												validations={this.props.validations}
												displayScriptName={this.props.displayScriptName}
												devicePinDisplayType={this.props.devicePinDisplayType}
												headerPinDisplayType={this.props.headerPinDisplayType}
												resourceLoader={this.props.resourceLoader}
												productLookupName={this.props.productLookupName}
												modalService={this.props.modalService}
												notificationService={this.props.notificationService}
												errorStore={this.props.errorStore}
												theme={this.props.theme}
												branding={this.props.branding}
												showUsed={this.props.showUsed}
												showPinTable={this.props.showPinTable}
												arePowerDomainSettingsEnabled={this.props.arePowerDomainSettingsEnabled}
												focusedSubItemPath={this.props.focusedSubItemPath}
											/>
										</ConfigViewEntry>
									);
								} else if (node.type === "pinmuxLeafNode") {
									// for pinmux leaf node the member can either be a peripheral/pin
									// or a pin under a specific peripheral which will be identified through
									// interfaceID -> pin name
									let interfaceID = "";
									let highlightedMember = "";
									if (this.props.focusedSubItemPath.length === 1) {
										highlightedMember = _.first(this.props.focusedSubItemPath);
									} else if (this.props.focusedSubItemPath.length === 2) {
										interfaceID = this.props.focusedSubItemPath[0];
										highlightedMember = this.props.focusedSubItemPath[1];
									}
									return (
										<CPinMux
											key={node.getKey()}
											memberMgrs={node.getMembers()}
											highlightedMember={highlightedMember}
											highlightedInterfaceID={interfaceID}
											columns={columns}
											actions={this.props.actions}
											formatter={this.props.formatter}
											validations={this.props.validations}
											displayScriptName={this.props.displayScriptName}
											devicePinDisplayType={this.props.devicePinDisplayType}
											headerPinDisplayType={this.props.headerPinDisplayType}
											resourceLoader={this.props.resourceLoader}
											productLookupName={this.props.productLookupName}
											modalService={this.props.modalService}
											notificationService={this.props.notificationService}
											errorStore={this.props.errorStore}
											theme={this.props.theme}
											branding={this.props.branding}
											showUsed={this.props.showUsed}
											showPinTable={this.props.showPinTable}
											arePowerDomainSettingsEnabled={this.props.arePowerDomainSettingsEnabled}
										/>
									);
								} else if (node.type === "validationLeafNode") {
									if (!node.isHidden()) {
										return (
											<ConfigViewEntry id={node.getKey()} key={node.getKey()} columns={columns}>
												<CValidation
													validations={this.props.validations}
													validatableObj={node.getValidatableObj()}
													formatter={this.props.formatter}
													actions={this.props.actions}
												/>
											</ConfigViewEntry>
										);
									}
								} else if (node.type === "sharedAssignLeafNode") {
									const highlightedMember = _.first(this.props.sharedInstanceSubItemPath);
									return (
										<SharedAssignLeafNodeView
											highlightedMember={highlightedMember}
											node={node}
											actions={this.props.actions}
											formatter={this.props.formatter}
											validations={this.props.validations}
											displayScriptName={this.props.displayScriptName}
											devicePinDisplayType={this.props.devicePinDisplayType}
											headerPinDisplayType={this.props.headerPinDisplayType}
											resourceLoader={this.props.resourceLoader}
											productLookupName={this.props.productLookupName}
											modalService={this.props.modalService}
											notificationService={this.props.notificationService}
											errorStore={this.props.errorStore}
											theme={this.props.theme}
											branding={this.props.branding}
											isPopup={this.props.isPopup}
										/>
									);
								}
								else {
									assertUnreachable(node);
								}
								return null;
							})
						}

					</TableBody>
				</Table>
				{tabGroup &&
					<TabContainer {...this.props} tabGroup={tabGroup} readOnly={readOnly} />
				}
			</ div >
		);
	}

	private onClick = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => { e.stopPropagation(); }
}

const rootStyle: React.CSSProperties = {
	width: "100%",
	marginBottom: defaultTheme.theme.spacing(1) + "px",
};

const withTitleNodeStyle: React.CSSProperties = {
	maxWidth: "50%",
	textOverflow: "ellipsis",
	paddingLeft: "0",
	overflow: "hidden",
	whiteSpace: "nowrap",
	marginRight: "20px",
};

interface ContainerNodeProps {
	node: ContainerNode;
	actions: ConfigStoreActions;
	longDescription: string;
	productLookupName: string;
	resourceLoader: ResourceLoader;
	displayScriptName: boolean;
	titleNode?: LeafNode;
	validations: Validations;
	formatter: IFormatter;
}

const statusDecoratorStyle = { float: "left" } as const;

// render an IView in an expansion panel
class CContainerNode
	extends React.Component<ContainerNodeProps & IGlobalServiceProps,
		{ collapsed: boolean, showLongDescription: boolean, isHover: boolean }> {

	// This should be refactored.  Details are here: https://jira.itg.ti.com/browse/PMUX-3895
	public static getDerivedStateFromProps(nextProps: ContainerNodeProps) {
		return {
			collapsed: nextProps.node.isCollapsed(),
			showLongDescription: nextProps.node.isLongDescriptionVisible(),
		};
	}

	public constructor(props: ContainerNodeProps & IGlobalServiceProps) {
		super(props);
		this.state = { ...CContainerNode.getDerivedStateFromProps(props), isHover: false };
	}

	public override render() {

		const { node } = this.props;
		const heading = node.getHeading(this.props.displayScriptName);
		const secondaryHeading = node.getSecondaryHeading();

		const noHeader = _.isEmpty(heading) && _.isEmpty(secondaryHeading);

		return (
			<div id={node.getKey()} style={rootStyle} >
				<Card variant="outlined">
					{!noHeader &&
						<CardHeaderNoMinWidth
							onMouseEnter={this.onMouseEnter}
							onMouseLeave={this.onMouseLeave}
							onClick={this.onClick}
							title={this.getTitle(node, secondaryHeading, heading)}
						>
						</CardHeaderNoMinWidth>
					}
					<Collapse
						in={noHeader || !this.state.collapsed}
						unmountOnExit>
						<CardContent>
							{this.props.longDescription && this.state.showLongDescription && <LongDescription
								id={node.getKey() + "longDescription"}
								closeDescription={this.closeDescription}
								longDescription={this.props.longDescription}
								canonicalName={this.props.productLookupName}
								resourceType={ResourceType.CODE}
								resourceLoader={this.props.resourceLoader}
								actions={this.props.actions}
								formatter={this.props.formatter}
							/>}
							{this.props.children}
						</CardContent>
					</Collapse>
				</Card >
			</div >
		);
	}

	private onMouseEnter = () => { this.setState({ isHover: true }); }
	private onMouseLeave = () => { this.setState({ isHover: false }); };
	private onClick = () => {
		if (!this.hasSharedInstDropdown()) {
			this.handleClick();
		}
	}
	private closeDescription = () => {
		this.props.actions.setGroupLongDescriptionVisibility(this.props.node, false);
		this.setState({ showLongDescription: false });
	}

	private handleClick = () => {
		// As an optimization we keep expanded as local state and keep manually keep the external
		// state in sync. 
		const collapsed = !this.state.collapsed;
		this.props.actions.setCollapsed(this.props.node, collapsed);
		this.setState({ collapsed });
	}

	private getTitle(node: ContainerNode, secondaryHeading: string, heading: string) {
		const rotation = this.state.collapsed ? 0 : 180;
		const iconStyle = {
			...commonStyles.smallIcon,
			transition: "0.2s all ease",
			transform: `rotate(-${rotation}deg)`,
		};
		return <List style={{
			cursor: "pointer",
			alignItems: "center",
			padding: "0",
			minWidth: "0",
			display: "flex",
			flexDirection: "row",
		}}>
			<ListItem
				onClick={this.handleClick}
				style={this.props.titleNode ? withTitleNodeStyle : { maxWidth: "85%", paddingLeft: 0 }}
			>
				<div style={{ paddingLeft: "6px", paddingRight: "6px" }}>
					<NodeStatusDecorator
						containerStyle={statusDecoratorStyle}
						id="statusDecorators"
						summary={node.getValidationsummary(this.props.validations)} />
				</div>
				<Tooltip title={secondaryHeading || ""} placement="top">
					<div
						style={{
							flex: "1",
							minWidth: 0,
							alignItems: "center",
							textOverflow: "ellipsis",
							overflow: "hidden",
							display: this.hasSharedInstDropdown() ? "inline-flex" : "inline",
						}}
					>
						<Typography
							variant="subtitle2"
							style={{
								flex: "0 1 auto",
								paddingRight: "12px",
								fontWeight: 600,
							}}
							noWrap
							component="span"
						>
							{heading}
						</Typography>
						{node.getLongDescription() && !this.state.collapsed &&
							<DisplayLongDescButton
								name={node.getKey()}
								style={{
									verticalAlign: "baseline",
									flex: "0 0 auto",
									padding: "2px 2px 0px 2px",
								}}
								onClick={this.onClickLongDesc}
								hidden={!this.state.isHover}
							/>
						}
						{!this.props.titleNode &&
							<Typography
								variant="subtitle1"
								style={{
									flex: "1 10 auto",
								}}
								noWrap
								component="span"
							>
								{secondaryHeading}
							</Typography>
						}
					</div>
				</Tooltip>
			</ListItem>
			<ListItem style={{ maxWidth: "50%", paddingLeft: spacingUnit, justifyContent: "flex-end" }}>
				{this.props.titleNode && this.props.titleNode.type === "sharedAssignLeafNode" &&
					<div style={{ width: "calc(100% - 10px)", paddingRight: "12px" }}>
						<SharedInstanceDropDown
							{...this.props}
							key={this.props.titleNode.getKey()}
							memberMgr={this.props.titleNode.getMember()}
						/>
					</div>}
				<ChevronDown
					color="primary"
					style={{
						...iconStyle,
						flex: "0 0 24px",
						cursor: "pointer",
					}}
					onClick={this.handleClick}
					id={`${node.getKey()}CollapseIcon`} />
			</ListItem>
		</List>;
	}

	private hasSharedInstDropdown() {
		return this.props.titleNode && this.props.titleNode.type === "sharedAssignLeafNode";
	}

	private onClickLongDesc = (ev: React.MouseEvent<HTMLElement, MouseEvent>) => {
		ev.stopPropagation();
		const showLongDescription = !this.state.showLongDescription;
		this.props.actions.setGroupLongDescriptionVisibility(this.props.node, showLongDescription);
		this.setState({ showLongDescription });
	}
}

const CardHeaderNoMinWidth = withStyles({
	content: {
		minWidth: "0",
	},
	root: {
		padding: 0,
		lineHeight: "auto",
	},
})(CardHeader);
