import * as _ from "lodash";
import * as data from "dataInterfaces";
import { SCHEMA, SCHEMAToType, validateMeta } from "../JSONschemaValidator";
import { Named } from "public/common";
import {
	RawResourceLoader,
	ResourceLoader,
	ResourceType,
	toCanonicalPath,
} from "../resources/metaContentLoaders/resourceLoader";
import { Product } from "../product/types";
import { extendException } from "../niceExceptions";
import * as JSON from "public/defs";
import * as Runtime from "public/runtime";
import { getRenamedDeviceId, getDeviceDescriptions } from "../data";
import { convertUnknownToError } from "../utils";

interface InstancedHardwareComponent extends JSON.HardwareComponentOverrides, Named {
	type: string[];
	subComponents: {
		[name: string]: InstancedHardwareComponent | JSON.HardwareComponentLink;
	};
}

interface ConnectedHardwareComponent extends InstancedHardwareComponent {
	subComponents: {
		[name: string]: ConnectedHardwareComponent | JSON.HardwareComponentLink;
	};
	signals: {
		[signalName: string]: Runtime.HardwareComponentSignal;
	};
}

interface ProductAndResource<T> {
	product: Product;
	resource: T;
}

function allComponents(components: { [name: string]: Runtime.HardwareComponent }): Runtime.HardwareComponent[] {
	return _.uniq(allComponentsImpl(components));

	function allComponentsImpl(components2: { [name: string]: Runtime.HardwareComponent }): Runtime.HardwareComponent[] {
		return [
			..._.values(components2),
			..._.flatMap(components2, (c) => allComponentsImpl(c.subComponents)),
		];
	}
}

function isReference(
	component: JSON.HardwareComponentInclusion | JSON.HardwareComponentOverrides):
	component is JSON.HardwareComponentReference {
	return "definition" in component;
}

function isHeaderReference(header: JSON.Header): header is JSON.HeaderReference {
	return "definition" in header;
}

function isRowDimensions(dimensions: JSON.ColumnDimensions | JSON.RowDimensions):
	dimensions is JSON.RowDimensions {
	return "rows" in dimensions;
}

// eslint-disable-next-line @typescript-eslint/ban-types
export function isEmptySpace<T extends Object>(dimension: JSON.EmptySpace | T):
	dimension is JSON.EmptySpace {
	return "blank" in dimension;
}

export function isColumnDimensions(dimensions: JSON.ColumnDimensions | JSON.RowDimensions):
	dimensions is JSON.ColumnDimensions {
	return "columns" in dimensions;
}

function isLink(
	component: JSON.HardwareComponentInclusion | JSON.HardwareComponentOverrides):
	component is JSON.HardwareComponentLink {
	return "link" in component;
}

function tagComponent(component: Runtime.HardwareComponent, namespace: Named, source: Runtime.SourceLocation) {
	if (namespace && !_.startsWith(component.name, `${namespace.name}/`)) {
		component.name = `${namespace.name}/${component.name}`;
	}
	if (source) {
		component.source = source;
	}
}

function setNames(component: Partial<Named>) {
	if (!component.displayName) {
		component.displayName = component.name;
	}
	if (!component.description) {
		component.description = "";
	}
}

function validate(component: Runtime.HardwareComponent) {
	if (component.isBus && !_.isEmpty(component.subComponents)) {
		throw new Error("Bus-style components cannot define sub components");
	}
	if (component.isBus && _.isEmpty(component.signals)) {
		throw new Error("Bus-style components must define at least one signal");
	}
	if (!component.type) {

		// JSON validation will catch this for top level components, but not necessarily from 
		// sub components

		throw new Error("All components must define a type");
	}
	_.each(component.subComponents, validate);
}

function assignComponent(
	componentDef: JSON.HardwareComponentDefinition,
	componentRef: JSON.HardwareComponentReference): JSON.HardwareComponentDefinition {

	// Take the definition, but replace any value with what is in the overrides

	return _.assignWith(componentDef, componentRef, (defValue, refValue, key) => {
		if (key === "settings" && defValue && refValue) {

			// For "settings", we want to merge individual settings

			return _.assign(defValue, refValue);
		} else if (key === "subComponents" && defValue && refValue) {

			// For "subComponents", we want to merge each component, and thus must call this 
			// function recursively

			return _.assignWith(defValue, refValue, (defValue2, refValue2) => {
				if (defValue2 && refValue2) {
					return assignComponent(defValue2, refValue2);
				}
				return undefined;
			});
		}
		return undefined;
	});
}

export class BoardParser {
	constructor(
		private readonly resourceLoader: IJSONResourceLoader,
		private readonly deviceData: data.AdaptedDeviceInfo) {
	}

	public async loadBoard(boardFile: string) {

		// Load board data

		boardFile = toCanonicalPath(boardFile, ResourceType.DATA);
		const { product, resource: rawBoard } = this.getResource(SCHEMA.BoardDef, boardFile);

		// Instance headers

		const headers = _.map(rawBoard.headers, (header) => this.instanceHeader(header));

		// Instance referenced board components

		const source = {
			name: rawBoard.name,
			displayName: rawBoard.displayName,
			definition: boardFile,
		};
		const components = this.instanceComponents(product, rawBoard.components, source, (connection) => {
			const devicePin = this.deviceData.devicePins[connection];
			if (!devicePin) {
				throw new Error(
					`Unknown device pin '${connection}'`);
			}

			return { devicePin };
		});

		// Map device and emulated devices if they were renamed

		const discoveryData = await getDeviceDescriptions();
		const device = getRenamedDeviceId(rawBoard.device, discoveryData);
		const emulated = _.map(rawBoard.emulated, (e) => {
			return {
				...e,
				device: getRenamedDeviceId(e.device, discoveryData),
			};
		});

		// Return board data with components instanced

		this.deviceData.board = {
			...rawBoard,
			components,
			source: boardFile,
			headers,
			device,
			emulated,
		};
	}

	public loadBoosterPack(boosterPackFile: string, headerName?: string) {

		const board = this.deviceData.board;
		if (!board) {
			throw new Error("Boosterpacks can only be added to a board, not a device");
		}

		// Load BoosterPack data

		boosterPackFile = toCanonicalPath(boosterPackFile, ResourceType.DATA);
		const { product, resource: boosterPack } = this.getResource(SCHEMA.BoosterPack, boosterPackFile);

		// Find the header it fits on

		const header = this.findHeader(boosterPack.headerType, headerName);
		// Instance referenced board components, but merge bus components where possible

		const source = this.generateSourceInfo(boosterPack, boosterPackFile, headerName);
		const unnamespacedComponents = this.mergeBusComponents(
			this.instanceComponents(
				product,
				boosterPack.components,
				source,
				(connection) => {
					const headerPin = _.find(header.pins, (pin) => pin.number === connection);
					if (!headerPin) {
						throw new Error(
							`Unknown header pin '${connection}'`);
					}
					const devicePin = this.deviceData.devicePins[headerPin.ball];
					return { headerPin, devicePin };
				},
				source),
		);

		// Extend board component information, but namespace it

		const namespacedComponents = _.mapKeys(unnamespacedComponents, (_component, key) => source.name + "/" + key);
		const duplicates = _.intersection(_.keys(namespacedComponents), _.keys(board.components));
		if (!_.isEmpty(duplicates)) {
			throw new Error(`Duplicate component names detected: (${duplicates.join(", ")})`);
		}

		_.extend(board.components, namespacedComponents);

		// But return the un-namespaced ones

		return unnamespacedComponents;
	}

	private findHeader(headerType: string, headerName?: string) {
		let header;
		if (headerName) {
			header = _.find(this.deviceData.board.headers, (h) => h.name === headerName);
			if (!header) {
				throw new Error(`Board does not define a header named '${headerName}'`);
			}
			if (header.type !== headerType) {
				throw new Error(`Incorrect type for header '${headerName}': expected '${headerType}', found '${header.type}'`);
			}
		} else {
			header = _.find(this.deviceData.board.headers, (h) => h.type === headerType);
			if (!header) {
				throw new Error(`Board does not define a '${headerType}' header type`);
			}
		}
		return header;
	}

	private generateSourceInfo(boosterPack: Named, boosterPackFile: string, headerName?: string) {
		const source: Runtime.SourceLocation = {
			name: boosterPack.name,
			displayName: boosterPack.displayName,
			definition: boosterPackFile,
		};

		if (headerName) {
			source.attachedTo = headerName;
		}

		let index = 0;
		while (_.find(this.deviceData.board.components,
			(component) => component.source && component.source.name === source.name)) {
			++index;
			source.name = `${boosterPack.name}_${index}`;
			source.displayName = `${boosterPack.displayName} (${index})`;
		}
		return source;
	}

	private getResource<T extends SCHEMA>(schema: T, file: string): ProductAndResource<SCHEMAToType<T>> {
		const product = this.resourceLoader.getProduct(file, ResourceType.DATA);
		const resource = this.resourceLoader.getJSONResource(file);

		// Validate the content.
		// Hardware components may define a name for legacy reasons, and we may need one moving forward.
		// However, it's not typed as such (as it's the same definition as is used for a inlined definition)
		// so for now lets just delete it before moving on.

		if (schema === SCHEMA.HardwareComponentDefinition) {
			delete resource.name;
		}
		const validatedResource = validateMeta(resource, file, schema);
		if (schema !== SCHEMA.HardwareComponentDefinition) {
			setNames(validatedResource as Partial<Named>);
		}

		// Clone the content so modifications to it won't affect a subsequent fetch of this data

		return { product, resource: _.cloneDeep(validatedResource) };
	}

	private instanceHeader(headerRef: JSON.Header): Runtime.Header {
		let header: JSON.HeaderDefinition;
		if (isHeaderReference(headerRef)) {
			const headerDef = this.getResource(SCHEMA.HeaderDefinition, headerRef.definition).resource;
			delete headerRef.definition;
			header = _.assignWith(headerDef, headerRef, (defValue, refValue, key) => {
				if (key === "pins" && defValue && refValue) {

					// For "pins", we want to merge individual pins based on number
					// But we won't allow them to add new numberings

					return _.map(defValue as JSON.HeaderPin[],
						(pinDef) => _.assign(pinDef, _.find(refValue as JSON.HeaderPin[], (pinRef) => pinRef.number === pinDef.number)));
				}
				return undefined;
			});
		} else {
			header = headerRef;
		}

		// Set name-based values

		setNames(header);

		// Default for displayNumbers is true, so we must explicitly set if not set

		if (undefined === header.displayNumbers) {
			header.displayNumbers = true;
		}

		// Map the pin definitions to ensure the preferredType is defined, and an array, and that
		// boardNumber is set

		const boardNumberOffset = header.boardNumberOffset || 0;
		const pins = _.map(header.pins, (pin) => {
			const preferredType = _.isArray(pin.preferredType) ?
				pin.preferredType : (pin.preferredType ? [pin.preferredType] : []);
			const boardNumber = pin.number + boardNumberOffset;
			return _.extend(pin, { preferredType, boardNumber });
		});

		// Map the dimensions so that "increment" is set to 1 if not defined

		const dimensions = isRowDimensions(header.dimensions) ?
			{ rows: _.map(header.dimensions.rows, (row) => isEmptySpace(row) ? row : _.extend({ increment: 1 }, row)) } :
			{ columns: _.map(header.dimensions.columns, (col) => isEmptySpace(col) ? col : _.extend({ increment: 1 }, col)) };

		// Validation

		this.validateHeader(header);

		return _.extend(header, { pins, dimensions });
	}

	private validateHeader(header: JSON.HeaderDefinition) {

		// Validate header data ball listing

		_.each(header.pins, (pin) => {
			if (pin.ball && !(pin.ball in this.deviceData.devicePins)) {
				throw new Error(`Unknown device pin '${pin.ball}'`);
			}
		});

		// Verify dimensions data

		if (isRowDimensions(header.dimensions)) {
			_.each(header.dimensions.rows, (row) => {
				if (!isEmptySpace(row)) {
					verifyDimension(row.left);
					verifyDimension(row.right);
					verifyIncrement(row.increment, row.left, row.right);
				}
			});
		} else {
			_.each(header.dimensions.columns, (column) => {
				if (!isEmptySpace(column)) {
					verifyDimension(column.top);
					verifyDimension(column.bottom);
					verifyIncrement(column.increment, column.top, column.bottom);
				}
			});
		}

		function verifyDimension(dimension: number) {
			if (!_.find(header.pins, (pin) => pin.number === dimension)) {
				throw new Error(`Unknown header pin number listed in dimensions: ${dimension}`);
			}
		}

		function verifyIncrement(increment: number, start: number, stop: number) {
			if (!_.isUndefined(increment)) {
				if (increment < 1) {
					throw new Error("\"increment\" value must be positive");
				}
				if ((stop - start) % increment) {
					throw new Error(`An increment of ${increment} does not evenly count from ${start} to ${stop}`);
				}
			}
		}
	}

	private instanceComponent(
		productInfo: Product,
		componentRef: JSON.HardwareComponentInclusion | JSON.HardwareComponentOverrides,
		name: string):
		InstancedHardwareComponent | JSON.HardwareComponentLink {

		if (isLink(componentRef)) {
			return componentRef;
		}

		let component: JSON.HardwareComponentDefinition | JSON.HardwareComponentOverrides;
		if (isReference(componentRef)) {

			// Load the definition, then apply the overrides in the reference to the definition
			// "settings" and "subComponents" override at the individual map values, but everything 
			// else overrides at the top level key

			const info = this.getResource(SCHEMA.HardwareComponentDefinition, componentRef.definition);
			productInfo = info.product;
			delete componentRef.definition;
			component = assignComponent(info.resource, componentRef);

		} else {
			component = componentRef;
		}

		// If there are subComponents, then instance each of them too

		const subComponents = _.mapValues(component.subComponents,
			(subComponent, subName) => this.instanceComponent(productInfo, subComponent, subName));

		const type = _.isArray(component.type) ? component.type : [component.type];
		return _.extend(component, { subComponents, name, type });
	}

	private setnames(component: InstancedHardwareComponent | JSON.HardwareComponentLink) {
		if (!isLink(component)) {
			setNames(component);
			_.each(component.subComponents, (subComponent) => this.setnames(subComponent));
		}
	}

	private connectComponent(
		component: InstancedHardwareComponent | JSON.HardwareComponentLink,
		mapConnection: (connection: string | number) => Pick<Runtime.HardwareComponentSignal, "headerPin" | "devicePin">):
		ConnectedHardwareComponent | JSON.HardwareComponentLink {

		// Ignore links for now

		if (isLink(component)) {
			return component;
		}

		// Map each signal by mapping it's connection using the supplied function

		const signals: { [key: string]: Runtime.HardwareComponentSignal } =
			_.mapValues(component.signals, (signal, name) => {
				const connection = signal.connection || (component.connections ? component.connections[name] : null);
				if (!connection) {
					throw new Error(`No mapping exists for signal '${name}' for component ${component.name}`);
				}
				delete signal.connection;
				return _.extend(signal,
					mapConnection(connection),
					{
						name,
						type: _.isArray(signal.type) ? signal.type : [signal.type],
					});
			});
		delete component.connections;

		// Apply to subcomponents, and then extend our own definition with the updates

		const subComponents = _.mapValues(component.subComponents,
			(subComponent) => this.connectComponent(subComponent, mapConnection));

		return _.extend(component, { signals, subComponents });
	}

	private linkComponents(
		component: ConnectedHardwareComponent | JSON.HardwareComponentLink,
		instances: { [name: string]: Runtime.HardwareComponent },
		parent?: Runtime.HardwareComponent,
	): Runtime.HardwareComponent {

		// If we are a link, return what we link to with $parents updated

		if (isLink(component)) {
			const link = _.split(component.link, ".");
			if (!_.has(instances, link)) {
				throw new Error(`Unknown component used as link: '${component.link}'`);
			}
			if (parent) {
				(_.get(instances, link) as Runtime.HardwareComponent).$parents.push(parent);
			}
			return _.get(instances, link);
		}

		// Apply on sub-components, using ourself as the parent (we aren't of the correct type yet,
		// but will be once we return, so we must cast)

		const subComponents = _.mapValues(component.subComponents,
			(subComponent) => this.linkComponents(subComponent, instances, component as Runtime.HardwareComponent));

		// extend ourself with the updated subComponents and $parents

		const $parents = parent ? [parent] : [];
		return _.extend(component, { subComponents, $parents });
	}

	private instanceComponents(
		productInfo: Product,
		components: { [name: string]: JSON.HardwareComponentInclusion },
		source: Runtime.SourceLocation,
		mapConnection: (connection: string | number) => Pick<Runtime.HardwareComponentSignal, "headerPin" | "devicePin">,
		namespace?: Named) {

		return _.reduce<{ [name: string]: JSON.HardwareComponentInclusion }, { [name: string]: Runtime.HardwareComponent }>
			(components, (instances, componentInclusion, name) => {
				try {

					// Load any "definition" from another file, and merge overridden properties.
					// Update name-defaulted properties only after overrides are handled (must be done
					// after, as overrides may have several layers since a definition could have 
					// another definition in a subComponent)

					const phase1 = this.instanceComponent(productInfo, componentInclusion, name);
					this.setnames(phase1);

					// Connect the signals to header/device pins

					const phase2 = this.connectComponent(phase1, mapConnection);

					// If the component is a "link" to another, then use the other

					const component = this.linkComponents(phase2, instances);

					// Now we can tag where the component came from, validate, return it

					tagComponent(component, namespace, source);
					validate(component);
					instances[name] = component;
					return instances;

				} catch (e) {
					extendException(`while processing component '${name}'`, convertUnknownToError(e));
				}
			}, {});
	}

	private mergeBusComponents(instances: { [name: string]: Runtime.HardwareComponent }) {

		return _.mapValues(instances, (component) => {

			// For each component, if it's a bus-style, see if there is an equivalent version already present

			if (component.isBus) {
				const equivilentComp = _.find(allComponents(this.deviceData.board.components), (existingComp) => {
					return existingComp.isBus &&												// is it a bus-style component?
						_.isEqual(_.sortBy(existingComp.type), _.sortBy(component.type)) &&		// of the same type?
						_.isEqualWith(existingComp.signals, component.signals, (a, b, key) => {
							return undefined === key ?
								undefined :
								a.devicePin === b.devicePin;									// connected to the same pins
						});
				});

				// If so, use that version (update all subComponent/$parent links)

				if (equivilentComp) {
					equivilentComp.$parents = _.uniq([...equivilentComp.$parents, ...component.$parents]);
					_.each(component.$parents, (parent) => {
						const key = _.findKey(parent.subComponents, (subComp) => subComp === component);
						parent.subComponents[key] = equivilentComp;
					});
					return equivilentComp;
				}
			} else {
				component.subComponents = this.mergeBusComponents(component.subComponents);
			}
			return component;
		});
	}
}

type IJSONResourceLoader = ResourceLoader | RawResourceLoader;
