import * as React from "react";
import { ConfigStoreActions } from "../../services/configStore";
import { SharedAssignLeafNode } from "../../services/objectManagers/viewNodes";
import { IMemberRowProps, MemberRow } from "./MemberRow";
import { SharedInstanceDropDown } from "./SharedInstanceDropDown";

interface IProps extends Omit<IMemberRowProps, "highlight" | "memberMgr"> {
	node: SharedAssignLeafNode;
	actions: ConfigStoreActions;
	highlightedMember: string;
}

export function SharedAssignLeafNodeView(props: IProps) {
	const { node, highlightedMember, ...rest } = props;
	const {
		actions,
	} = props;
	return <>
		<MemberRow
			{...rest}
			key={node.getMember().def.name}
			memberMgr={node.getMember()}
			highlight={node.getMember().def.name === highlightedMember}
		>
			< SharedInstanceDropDown
				{...rest}
				actions={actions}
				key={node.getKey()}
				memberMgr={node.getMember()}
				margin={"0px"}
			/>
		</MemberRow>
	</>;
}
