import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { PositionedNode } from "./PositionedNode";
import { MainLabel } from "./NodeLabels";
import { CheckBox, defaultCheckBoxHeight } from "../../CheckBox";
import { BooleanConfigurableMgr } from "../../../services/objectManagers/configurables/booleanConfigurableMgr";
import { PositionedDiv } from "./PositionedDiv";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { INodeProps } from "../types/nodeTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// A gate node is a rectangle with a checkbox in the middle.  If the checkbox is checked, the gate is enabled and the 
// output is the same as the input.  If the checkbox is unchecked, the gate is disabled and the output is zero

class GateNodeImpl<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.PureComponent<INodeProps<InstMgr, PortMgr> & ClassesType & { value: boolean, mgr: BooleanConfigurableMgr }> {
	public override render() {
		const { node, onClickNode, onMouseDownNode, classes, displayScriptName, value, mgr, validations, formatter } = this.props;

		return (
			<PositionedNode
				node={node}
				onClick={onClickNode}
				onMouseDown={onMouseDownNode}
				className={classes.genericNode}
				validations={validations}
				formatter={formatter}
			>
				{/* 
					Ideally we'd render <NodeLabels> as well, but there's two issues:
					1) out label overlaps the checkbox, making it un-clickable
					2) with two pins, the labels likely add nothing
					I'm sure there's a solution to 1 should 2 ever change, but for now I'm just omitting pin labels
					amd rendering just the main label manually
				*/}

				<MainLabel
					node={node}
					displayScriptName={displayScriptName}
					classes={classes}
				/>

				{mgr &&
					<PositionedDiv
						x={0}
						y={node.height / 2 - defaultCheckBoxHeight / 2}
						className={classes.positionedNode}
					>
						<CheckBox
							id={"checkbox" + node.id}
							onChange={this.onChange}
							value={value}
						/>
					</PositionedDiv>
				}
			</PositionedNode>
		);
	}

	private onChange = (checked: boolean) => {
		const { mgr } = this.props;
		this.props.actions.setConfigurableValue(mgr, checked);
	}
}

export function GateNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: INodeProps<InstMgr, PortMgr> & ClassesType
) {
	const mgr = props.node.inst.memberMgrs.enable as BooleanConfigurableMgr;
	return <GateNodeImpl {...props} mgr={mgr} value={mgr?.getValue()} />;
}
