import * as React from "react";
import * as _ from "lodash";
import { Branding, ExternalSimulation, Plots } from "public/defs";
import { Card, CardContent, Typography, Link } from "../../imports/material-ui-imports";
import { ErrorStore } from "../../services/errorStore";
import { assertNeverThrows } from "../../services/utils";
import { SimulationTreeNode } from "../../services/simulation/simulationTreeNode";
import { InlineErrorBoundary } from "../InlineErrorBoundry";
import { ATheme } from "../styles/themes";
import { ProgressCallback } from "../../services/externalExecutable";
import { CircularProgressWithLabel } from "../CircularProgressWithLabel";
import { usePlotly } from "../../services/simulation/plotly";
import { PreScaledSimulationResults } from "./PreScaledSimulationResults";
import { isSpiceSimulation, SimulationFailedError, SimulationTooIntensiveError } from "../../services/simulation/simulation";
import { ProgressBar } from "../ProgressBar";
import { ExternalLink } from "../ExternalLink";
import { useToggle } from "../hooks/useToggle";

interface IProps {
	simulationTreeNode: SimulationTreeNode;
	fetchSimData: (simulationTreeNode: SimulationTreeNode, progressCallback?: ProgressCallback) => Promise<Plots>;
	progress: number;
	setProgress: (val: number | string) => void;
	branding: Branding,
}

export function SimulationView({
	simulationTreeNode,
	theme,
	fetchSimData,
	progress,
	setProgress,
	branding,
}: IProps & { theme: ATheme }) {
	return (
		<InlineErrorBoundary theme={theme} id="simulationViewErrorBoundary">
			{
				({ errorStore }) => <UnsafeSimulationView
					fetchSimData={fetchSimData}
					simulationTreeNode={simulationTreeNode}
					errorStore={errorStore}
					progress={progress}
					setProgress={setProgress}
					branding={branding}
				/>
			}
		</InlineErrorBoundary>
	);
}

function UnsafeSimulationView({
	errorStore,
	simulationTreeNode,
	fetchSimData,
	progress,
	setProgress,
	branding,
}: IProps & { errorStore: ErrorStore }) {
	const [plotData, setPlotData] = React.useState<Plots>(null);
	const [exception, setException] = React.useState<SimulationTooIntensiveError | SimulationFailedError>(null);

	React.useEffect(() => {
		const getPlots = async () => {
			try {
				setPlotData(await fetchSimData(simulationTreeNode, setProgress));
			} catch (e) {
				if (e instanceof SimulationTooIntensiveError || e instanceof SimulationFailedError) {
					setException(e);
				} else {
					throw e;
				}
			}
		};
		assertNeverThrows(errorStore, getPlots);
		return () => setProgress(0); // reset progress for next simulation run (avoids animation from 100->0)
	}, [errorStore, simulationTreeNode, fetchSimData, setProgress]);

	// We fetch plotly in this component and pass it on so that it can be loaded while the simulation is running in parallel

	const plotly = usePlotly(errorStore);
	const supportsProgress = isSpiceSimulation(simulationTreeNode.def.simulation)
		|| (simulationTreeNode.def.simulation as ExternalSimulation).hasProgress;
	if (exception) {
		return <SimulationException softwareDownloadLink={branding.softwareDownloadLink} exception={exception} />;
	} else if ((!plotData || !plotly)) {
		return <SimulationProgress progress={supportsProgress ? progress : null} />;
	}

	return <PreScaledSimulationResults plotData={plotData} errorStore={errorStore} plotly={plotly} />;
}

function SimulationProgress({ progress }: { progress?: number }) {
	if (!_.isNil(progress)) {
		return <CircularProgressWithLabel id="simulationProgress"
			title={progress < 100 ? "Running Simulation..." : "Gathering Results..."}
			value={progress} />;
	}
	return <ProgressBar id="simulationProgress" title="Running Simulation (this may take a while)... " />;
}

const centered = {
	alignSelf: "center",
	margin: "auto",
};

function SimulationException(
	{ softwareDownloadLink, exception }:
		{ softwareDownloadLink: string, exception: SimulationTooIntensiveError | SimulationFailedError }
) {
	if (exception instanceof SimulationTooIntensiveError) {
		return <SimulationTooIntensiveMessage softwareDownloadLink={softwareDownloadLink} />;
	} else {
		return <SimulationFailedMessage exception={exception} />;
	}
}

function SimulationTooIntensiveMessage({ softwareDownloadLink }: { softwareDownloadLink: string }) {
	return <Card id="simulationTooIntensive" style={centered} >
		<CardContent>
			<Typography variant="h6" component="div">Simulation too Intensive</Typography>
			<br />
			<Typography variant="body2" color="textSecondary" component="div">
				This simulation is too intensive to run in a browser. Try the following:
				<ul>
					<li>Reduce the simulation length</li>
					<li>Download the <ExternalLink href={softwareDownloadLink} >desktop version</ExternalLink></li>
				</ul>
			</Typography>
		</CardContent>
	</Card>;

}

const detailsBoxStyle = {
	fontFamily: "monospace",
	whiteSpace: "pre",
	overflow: "scroll",
	maxHeight: 300,
} as const;

function SimulationFailedMessage({ exception }: { exception: SimulationFailedError }) {
	const [showDetails, toggleShowDetails] = useToggle(false);
	return <Card id="simulationFailed" style={centered} >
		<CardContent>
			<Typography variant="h6" component="div"> Simulation Failed</Typography>
			<br />
			<Typography variant="body2" color="textSecondary" component="div">
				Simulation failed to run.  Please contact <ExternalLink href={"https://e2e.ti.com/"}>support</ExternalLink>
			</Typography>
			<Link
				display="inline"
				component="button"
				underline="hover"
				variant="subtitle2"
				onClick={toggleShowDetails}
			>
				{showDetails ? "Hide Details..." : "Show Details..."}
			</Link>
			{showDetails &&
				<Typography
					variant="body2"
					style={detailsBoxStyle}
					id="details"
				>
					{exception.consoleOutput}
				</Typography>
			}
		</CardContent>
	</Card >;
}
