import * as _ from "lodash";
import React = require("react");
import { FormattedDropDownOption } from "./ComponentUtils";
import {
	ListItemText,
	Typography,
	Autocomplete,
	TextField,
	AutocompleteProps,
	Popper,
	PopperProps,
	AutocompleteRenderInputParams,
} from "../imports/material-ui-imports";
import util = require("../services/utils");
import { CheckBox } from "./CheckBox";
import { MenuItemWithTooltip as MenuItem } from "./higherOrderComponents/ComposedComponents";
import { IProps as ITooltipProps } from "./Tooltip";
import { commonStyles } from "./styles/common";
import { AutocompleteChangeReason, AutocompleteChangeDetails } from "@material-ui/lab";

interface IDropDownImplProps<Value extends string | string[], Data = unknown> {
	id: string;
	onChange: (value: Value, option: Value extends string[] ? FormattedDropDownOption<Data>[] : FormattedDropDownOption<Data>) => void;
	withIcon?: boolean; // can display decorator icon
	selectedOptionName: Value;
	disabled: boolean;
	enabledOptions: FormattedDropDownOption<Data>[];
	actionOptions?: FormattedDropDownOption<Data>[];
	disabledOptions?: FormattedDropDownOption<Data>[];
	// Whether to add a empty value option, 
	// This value also specifies the render value(what is displayed when selected) of the empty entry
	// The option value(what is displayed when in the dropdown option list) is always None
	withNoneOption?: string;
	tooltipProps?: ITooltipProps;
	fullWidth?: boolean; // full Width of the container
	clearable?: boolean;
	displayScriptName: boolean;
	selectAll?: boolean;
}

interface IState {
	newInputValue: string;
}

class DropDownImpl<Value extends string | string[], Data = unknown> extends React.PureComponent<IDropDownImplProps<Value, Data>, IState> {

	public override state: IState = {
		newInputValue: "",
	};

	public override render() {

		let width = "100%";
		if (this.props.withIcon) { // 20px icon
			width = "calc(100% - 20px)";
		}

		const enabledOptions = this.getEnabledOptions();
		const disabledOptions = this.props.disabledOptions || [];
		const actionOptions = this.props.actionOptions || [];

		const isMultiple = _.isArray(this.props.selectedOptionName);
		const allOptions = [
			...enabledOptions,
			...actionOptions,
			...disabledOptions,
		];
		const autocompleteProps: AutocompleteProps<FormattedDropDownOption, boolean, boolean, boolean> = {
			style: {
				width,
				...commonStyles.inputTextStyle,
				paddingTop: 0,
				paddingBottom: 0,
				scrollSnapTypeY: "mandatory",
			},
			id: this.props.id + "Autocomplete",
			options: allOptions,
			getOptionLabel: this.getOptionDisplayName,
			renderInput: this.renderInput,
			// disable a dropdown when it has no options at all
			disabled: this.props.disabled || (_.isEmpty(disabledOptions) && _.isEmpty(enabledOptions)),
			disableClearable: !this.props.clearable,
			disableCloseOnSelect: !!isMultiple,
			disabledItemsFocusable: true,
			autoHighlight: true,
			fullWidth: this.props.fullWidth,
			renderOption: (option: FormattedDropDownOption) =>
				this.renderOption(option, this.optionIsDisabled(option, disabledOptions), isMultiple),
			PopperComponent: this.popper,
		};

		return (
			<span id={this.props.id}>
				<span className={"select"} data-disabled={this.props.disabled}>
					{!isMultiple &&
						<Autocomplete
							{...autocompleteProps}
							key={this.props.displayScriptName.toString()} // force a re-render if displayScriptName changes
							value={this.findOption(this.props.selectedOptionName as string, enabledOptions)}
							inputValue={this.state.newInputValue}
							onInputChange={this.handleInputChange}
							onChange={this.onChangeSingle}
						/>
					}
					{isMultiple &&
						<Autocomplete
							{...autocompleteProps as AutocompleteProps<FormattedDropDownOption, true, boolean, boolean>}
							multiple
							key={this.props.displayScriptName.toString()} // force a re-render if displayScriptName changes
							value={this.findOptions(this.props.selectedOptionName as string[], enabledOptions)}
							onChange={this.onChangeMulti}
							renderTags={this.renderTags}
						/>
					}
				</span>
			</span>
		);
	}

	private handleInputChange = (_event: unknown, newInputValue: string) => {
		const disabledOptions = this.props.disabledOptions || [];
		if (!this.findDisabledOption(newInputValue,
			[..._.filter(this.props.enabledOptions, (o) => o.isDisabled), ...disabledOptions],
		)) {
			this.setState({ newInputValue });
		}
	}

	private onChangeSingle = (_e: unknown, value: string | FormattedDropDownOption | (string | FormattedDropDownOption)[]) => {
		const newOption = value as FormattedDropDownOption;
		if (newOption) {
			if (!this.optionIsDisabled(newOption, this.props.disabledOptions || [])) {
				this.props.onChange(this.getNewOptionValues(newOption) as Value, newOption as any);
			}
		} else {
			this.props.onChange("" as Value, null);
		}
	}

	private onChangeMulti = (_e: unknown, value: (string | FormattedDropDownOption)[], _reason: AutocompleteChangeReason,
		details?: AutocompleteChangeDetails<FormattedDropDownOption>) => {
		const disabledOptions = this.props.disabledOptions || [];
		let newOptions = value as FormattedDropDownOption[]; //What options are selected
		if (details?.option.name === "$selectAll") { //Button clicked is selectAll
			if (newOptions.length - 1 < _.size(this.props.enabledOptions)) { //If not full
				newOptions = this.props.enabledOptions; //Drop select all
			}
			else { //if full 
				newOptions = []; //unclick all
			}
		}
		if (newOptions) {
			if (_.every(newOptions, (o) => !this.optionIsDisabled(o, disabledOptions))) {
				// Make sure every selected value isn't disabled
				// Do defined operation in .tsx file
				this.props.onChange(this.getNewOptionValues(newOptions) as Value, newOptions as any);
			}
		}
	}

	private renderTags = (value: FormattedDropDownOption[]) =>
		value.map((option, _index) => util.getDisplayName(option, this.props.displayScriptName) || "");

	private popper = (props: PopperProps) => {
		return (<Popper
			{...props}
			id={"menu-"}
			style={{ overflowX: "visible", width: "auto", boxShadow: "0px 0px 5px rgba(0, 0, 0, 0.2)" }}
			placement="bottom-start"
		/>);
	}

	private renderInput = (params: AutocompleteRenderInputParams) => {
		const limitTagsNum = 2;
		const emptyText = this.props.withNoneOption || "None";
		const { InputProps, ...restParams } = params;
		const { startAdornment, ...restInputProps } = InputProps;
		const newStartAdornment = _.isArray(startAdornment) ? _.take(startAdornment, limitTagsNum) :
			startAdornment ? startAdornment : "";
		const moreText = _.isArray(startAdornment) ? _.size(startAdornment) > limitTagsNum ?
			("+" + (_.size(startAdornment) - limitTagsNum).toString()) : "" : "";
		const itemsToDisplay = _.chain(newStartAdornment)
			.sortBy()
			.join(", ")
			.value();
		return (<TextField style={commonStyles.textFieldStyle}
			{...restParams}
			placeholder={_.isEmpty(this.props.selectedOptionName) ? emptyText : ""}
			{...params}
			InputProps={{
				...restInputProps,
				startAdornment: (
					<div style={{ overflow: "auto" }}>
						<span>{itemsToDisplay + " "}</span>
						<span>{moreText}</span>
					</div>
				),
			}}
			margin="normal"
		/>);
	}

	private renderOption(
		option: FormattedDropDownOption,
		disabled: boolean,
		isMultiple: boolean,
	) {
		const isAction = !!option.icon;
		const tooltipPlacement = this.props.tooltipProps?.placement ?? "left";
		return <MenuItem
			component="div"
			value={option.name}
			id={this.props.id + "-" + option.name}
			key={option.name}
			disabled={disabled}
			tooltipProps={{ ...this.props.tooltipProps, title: option.description, placement: tooltipPlacement }}
			className={
				(disabled ? "disabled-opt" : "enabled-opt") +
				(_.includes(this.props.selectedOptionName, option.name) ? " selected-opt" : "")
			}
			style={{ cursor: "pointer" }}
		>
			{
				isMultiple && (option.name !== "$selectAll") &&
				<CheckBox
					id={this.props.id + "-" + option.name + "checkbox"}
					value={_.includes(this.props.selectedOptionName, option.name)}
					onChange={ignored}
				/>
			}{
				isMultiple && (option.name === "$selectAll") &&
				<CheckBox
					id={this.props.id + "-" + option.name + "checkbox"}
					value={this.selectAllCheck()}
					onChange={ignored}
					indeterminate={this.indeterminateCheck()}
				/>
			}
			<ListItemText
				primary={
					< Typography variant="body2"
						style={{ fontWeight: isAction ? 500 : 400 }}
						className={"menu-item-text"} >
						{this.getOptionDisplayName(option)}
						{isAction &&
							option.icon}
					</Typography >
				}
				style={this.getPaddingStyle(option.level)}
			/>
		</MenuItem>;
	}

	// for single option dropdown
	private findOption(selectedOptionName: string, options: FormattedDropDownOption[]) {
		// null is needed here since Autocomplete component does not recognize undefined as "null" option
		return _.find(options, (o) => o.name === selectedOptionName) || null;
	}

	// for multiple option dropdown
	private findOptions(selectedOptionName: string[], options: FormattedDropDownOption[]) {
		return _.filter(options, (o) => !!_.includes(selectedOptionName, o.name));
	}

	private selectAllCheck(): boolean {
		if (this.props.selectedOptionName.length > 0) {
			return true;
		}
		else {
			return false;
		}
	}

	private indeterminateCheck(): boolean {
		const names = this.props.selectedOptionName;
		if (names.length > 0 && names.length < (_.size(this.props.enabledOptions))) {
			return true;
		}
		return false;
	}

	private getOptionDisplayName = (option: FormattedDropDownOption) => {
		return (option.name === util.Const.ANY && this.props.selectedOptionName !== option.name) ? option.name :
			util.getDisplayName(option, this.props.displayScriptName);
	}

	private findDisabledOption(selectedOptionName: string, options: FormattedDropDownOption[]) {
		return _.find(options, (o) => o.name === selectedOptionName || o.displayName === selectedOptionName);
	}

	private getNewOptionValues(option: FormattedDropDownOption | FormattedDropDownOption[]) {
		return _.isArray(option) ? _.map(option, (o) => o.name) : option.name;
	}

	private optionIsDisabled(option: FormattedDropDownOption, disabledOptions: FormattedDropDownOption[]) {
		return !!_.find(disabledOptions, (o) => o.name === option.name) || option.isDisabled;
	}

	// add padding per level to children entries to show parent/children relationship
	private getPaddingStyle(level: number = 0) {
		return {
			paddingLeft: 8 * level,
			width: "100%",
		};
	}

	private getEnabledOptions() {
		const $selectAllOption: FormattedDropDownOption = {
			name: "$selectAll",
			displayName: "Select All",
			description: "Select/deselect all options below",
		};
		if (this.props.selectAll) {
			return [$selectAllOption, ...(this.props.enabledOptions ?? [])];
		}
		return this.props.enabledOptions ?? [];
	}
}

// Empty function for required callbacks we explicity want to ignore
function ignored() { }

export class DropDown<Data = unknown> extends DropDownImpl<string, Data> { }
export class MultiDropDown<Data = unknown> extends DropDownImpl<string[], Data> { }
