import * as _ from "lodash";
import { PortRequirement } from "public/defs";
import {
	RuntimeInstance,
	PortConnection as IPortConnectionLValue,
	Port as IPortLValue,
	ModuleInstance,
	Probe,
	TProbe,
} from "public/runtime";
import { AMemberMgr, AnyMemberMgr, SetSource } from "./member";
import { createPortConnectionStatement, createProbeStatement, getScriptIdentifier } from "../scripting/serialize";
import { ModuleInstanceMgr } from "./moduleInstance";
import { getCurrentlyRunningCallbackName, isModuleAccessEnabled } from "../moduleAccessGuard";
import { Runtime } from "../resources/runtime";
import { SerializationOptions } from "../scripting/toScript";
import { assert, Equals } from "../typeAsserts";
import { shouldCapture } from "./invalidAssignment";
import { AObjectMgr } from "./object";
import { getInvalidMemberAccessProxy } from "./proxyHandlers/invalidAssignmentProxy";

// This is a class that manages a "port" on a module which allows the module to be connected to other modules.  It's a 
// bit different from most member managers in that it is written using an array of it's own class type, but read back
// as an array of PortConnection's (an object containing the module instance proxy object and a port member name).  The
// reason for this is we expect meta-content to write it using scripting.connect() because it's less confusing that a 
// function taking both would create the connection vs an assignment establishing a connection on both:
//
// scripting.connect(node1, "out", node2, "in");	// Clearly establishes a connection
// node1.out = [{inst: node2, port: "in"}]; 		// Do I have to now connect node2.in to node1.out?
// node1.out = [node2.in]; 							// Why is the write type different than the read type?
//
// Another reason is that scripting.connect can then be easily extended to return some "connection" object that can
// have it's own configurables.  
//
// Why do we have it take a write type at all?  It ensures that anything happening in the parent's "set" function will 
// take effect here.  That includes order, deprecation, future features etc.  Technically, this implementation allows 
// scripts to write node1.out = [] to disconnect, but we don't expect them to know that, and it won't harm anything 
// anyway.
//
// In addition, note that ports can only be read by the meta-content only for validation/templates, and written only by
// scripts.  If we didn't allow that, modules would be able to reflect on the configuration and suddenly we would have 
// serialization order dependencies between modules.

export class PortMemberMgr extends AMemberMgr<IPort, RuntimeInstance, PortRequirement, IPortLValue> {

	// We need to store the last value so that onSet can disconnect anything removed

	private previousValue: IPort = { portConnections: [], probes: [] };
	private readonly permittedProbeTypes: TProbe[];

	constructor(
		public override readonly parentObjectMgr: ModuleInstanceMgr,
		def: PortRequirement,
		runtime: Runtime,
	) {
		// the permitted probes for each port is the intersection of globally permitted probe types and the ones specified for this port
		// this prevents adding of probes that are not permitted globally 
		const permittedProbeTypes = def.permittedProbeTypes ?
			_.intersection(runtime.getPermittedProbes(), def.permittedProbeTypes) : runtime.getPermittedProbes();
		const misplacedProbeTypes = _.remove(def.initialProbeTypes, (type) => permittedProbeTypes && !permittedProbeTypes.includes(type));
		if (!_.isEmpty(misplacedProbeTypes)) {
			throw new Error(`The following probe types cannot be placed on this port: ${misplacedProbeTypes.join(", ")}`);
		}
		const initialProbes = _.chain(def.initialProbeTypes)
			.intersection(permittedProbeTypes)
			.uniq()
			.map((probeType) => ({
				inst: parentObjectMgr.managedObject.$name,
				port: def.name,
				type: probeType,
			})).value();
		super(
			parentObjectMgr,
			runtime.getFormattersMap(),
			def,
			{ portConnections: [], probes: initialProbes },
		);

		this.permittedProbeTypes = permittedProbeTypes;
	}

	// Prevent setting this value via args for serialization reasons mentioned above

	public override setValueFromRequiredArgs() {
		this.preventMetaUpdate();
	}

	public override setValueFromArgs() {
		this.preventMetaUpdate();
	}

	public override removeArgs() {
		this.preventMetaUpdate();
	}

	public override removeReqArgs() {
		this.preventMetaUpdate();
	}

	// Prevent writes from meta-content

	public override set(...args: Parameters<AMemberMgr<IPortLValue, RuntimeInstance, PortRequirement>["set"]>) {
		if (isModuleAccessEnabled()) {
			return super.set(...args);
		}
		this.preventMetaUpdate();
	}

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		if (options.cloneInstance) {
			return [];
		}
		const connectionStatements = this.generatePortConnectionStatements(parentIdentifier);

		// We don't need to serialize probes, if they are same as initial
		if (!this.probesHaveChanged()) {
			return connectionStatements;
		}
		// Unlike scripting.connect functions, probing functions must be serialized for every port
		const probeStatement = createProbeStatement(parentIdentifier, this.def, this.value.probes);
		return [...connectionStatements, probeStatement];
	}

	public override shouldSerialize() {
		return this.probesHaveChanged() || (!_.isEmpty(this.value.portConnections) && this.def.type === "output");
	}

	public override remove() {
		const toRemove = this.value.portConnections;
		this.value.portConnections = [];
		_.each(toRemove, (c) => disconnect(this, c.port, SetSource.TOOL_INTERNAL));
		super.remove();
	}

	// Checks if an implied connection can be established here, or if we should look for another module instance.  It 
	// assumes that the meta-code wouldn't be trying to connect invalid ports (output to output), so it's really only
	// checking if this would break an existing connection.  validateValue() will do the real sanity check that the 
	// meta-code does not have any bugs
	public canImplyConnection(breakUserConnections: BreakUserConnections) {
		if (this.def.type === "input") {
			return breakUserConnections
				? !_.first(this.getPortConnections())?.implied		// Disallow breaking an existing implied connection
				: _.isEmpty(this.getPortConnections());				// Disallow breaking any connection
		}
		return true;										// Additional connections are always allowed at outputs
	}

	// Unique id for graph
	public getID() {
		return this.def.name + this.parentObjectMgr.getID();
	}

	public getEnclosingNode() {
		// Ports for child modules are shown on the parent module's node.  So, if our parent object manager is owned by
		// some other module, we need to return that other module

		let enclosingParent = this.parentObjectMgr;
		while (enclosingParent.isExclusivelyOwned()) {
			enclosingParent = enclosingParent.getOwner();
		}
		return enclosingParent;
	}

	public override jsonify() {

		// Don't block jsonification within callbacks

		return new PortLValue(
			_.map(this.value.portConnections, ({ port, implied }) =>
				new PortConnectionLValue(port.parentObjectMgr.managedObject, port.def.name, implied)),
			this.value.probes,
		);
	}

	public getPortConnections(): IPortConnection[] {
		return this.value.portConnections;
	}

	public hasProbe(probe: TProbe) {
		return _.some(this.value.probes, ({ type }) => type === probe);
	}

	public removeProbe(typeToAdd: TProbe) {
		if (!this.hasProbe(typeToAdd)) {
			throw new Error(`There is no probe of type ${typeToAdd} on this port`);
		}
		this.set({
			...this.value,
			probes: _.filter(this.value.probes, ({ type }) => type !== typeToAdd),
		}, SetSource.USER_ASSIGN);
	}

	public addProbe(typeToAdd: TProbe) {
		if (this.hasProbe(typeToAdd)) {
			throw new Error(`There is already a probe of type ${typeToAdd} on this port`);
		}

		this.set({
			...this.value,
			probes: _.concat(this.value.probes, {
				inst: this.parentObjectMgr.managedObject.$name,
				port: this.def.name,
				type: typeToAdd,
			}),
		}, SetSource.USER_ASSIGN);
	}

	public probeTypeIsPermitted(probe: TProbe) {
		return _.some(this.permittedProbeTypes, (probeType) => probeType === probe);
	}

	protected override toLValue() {
		const cb = getCurrentlyRunningCallbackName();
		if (cb) {
			throw new Error(`Cannot access ports in '${cb}'`);
		}
		return new PortLValue(
			_.map(this.value.portConnections, ({ port, implied }) =>
				new PortConnectionLValue(port.parentObjectMgr.managedObject, port.def.name, implied)),
			this.value.probes,
		);
	}

	protected override validateValue(value: IPort) {
		const hasCorrectType = _.isObject(value) && !_.isArray(value);
		if (!hasCorrectType) {
			this.typeMismatch("object", typeof value);
		}
		if (this.def.type === "input" && _.size(value.portConnections) > 1) {
			throw new Error("An input port can only be assigned to one output port");
		}

		_.each(value.probes, (probe) => {
			if (!this.probeTypeIsPermitted(probe.type)) {
				throw new Error(`Cannot add a probe of type ${probe.type} to this port`);
			}
		});

		_.each(value.portConnections, (connection) => {
			if (!(connection?.port instanceof PortMemberMgr)) {
				throw new Error("Unknown port object");
			}
			if (connection.port.def.type === this.def.type) {
				throw new Error("Cannot connect two ports of the same type: " + this.def.type);
			}
			if (this.def.implied && !connection.implied) {
				throw new Error("Cannot connect ports intended for implied connections only");
			}
		});
	}

	protected override handleInvalidAssignment(
		_reason: string,
		value: IPort,
		oldDisplayName: string,
		e: Error
	) {
		this.parentObjectMgr.invalidPortAccess([], e.message, oldDisplayName);
		_.each(value.portConnections, (connection) => {
			connection.port.parentObjectMgr.invalidPortAccess([connection.port.def.name], e.message);
		});
		return false;
	}

	protected override onSet(_value: IPort, source: SetSource) {
		_.chain(this.previousValue.portConnections)
			.differenceBy(this.value.portConnections, "port")
			.each((c) => disconnect(this, c.port, source))
			.value();

		_.chain(this.value.portConnections)
			.differenceBy(this.previousValue.portConnections, "port")
			.each((c) => connect(c.port, { port: this, implied: c.implied }, source))
			.value();

		this.previousValue = this.value;
	}

	private preventMetaUpdate() {
		throw new Error("modules cannot be connected outside of scripts");
	}

	private generatePortConnectionStatements(parentIdentifier: string) {
		// We only need to generate scripting.connect functions for one side.  I've chosen the output side as it's one to 
		// many, so that should group the statements
		if (this.def.type === "output") {
			return _.chain(this.value.portConnections)
				.filter(({ implied }) => !implied)
				.map(({ port }) => createPortConnectionStatement(
					parentIdentifier,
					this.def,
					getScriptIdentifier(port.parentObjectMgr),
					port.def.name,
				))
				.value();
		}

		return [];
	}

	private probesHaveChanged() {
		const getProbeTypes = (probes: Probe[]) => _.chain(probes).map(({ type }) => type).sort().value();
		return !_.isEqual(getProbeTypes(this.initValue.probes), getProbeTypes(this.value.probes));
	}

}

export function createScriptingProbe(runtime: Runtime) {
	return function scriptingProbe(inst: RuntimeInstance, portMember: string, probeType: TProbe | TProbe[]) {
		const instMgr = runtime.getManager(inst);
		const portMgr = instMgr?.memberMgrs[portMember];

		if (portMgr instanceof PortMemberMgr) {
			const probes = _.chain(probeType)
				.castArray()
				.uniq()
				.map((type) => {
					return {
						inst: portMgr.parentObjectMgr.managedObject.$name,
						port: portMgr.def.name,
						type: type,
					};
				}).value();
			portMgr.set({ ...portMgr.getValue(), probes: probes }, SetSource.USER_ASSIGN);
		} else {
			const migratingOrCompatabilityMode = shouldCapture(SetSource.USER_ASSIGN, false, false);
			tagProbingError(portMember, inst, instMgr, portMgr, migratingOrCompatabilityMode);
		}
	};
}

// Implementation of scripting.connect

export function createScriptingConnect(runtime: Runtime) {
	return function scriptingConnect(
		outputInst: RuntimeInstance, outputMember: string,
		inputInst: RuntimeInstance, inputMember: string,
		...args: (RuntimeInstance | string)[]
	) {

		// Find manager objects referenced in first four arguments
		const inputInstMgr = runtime.getManager(inputInst);
		const outputInstMgr = runtime.getManager(outputInst);

		// Get port managers
		const inputPortMgr = inputInstMgr?.memberMgrs[inputMember];
		const outputPortMgr = outputInstMgr?.memberMgrs[outputMember];

		if (outputPortMgr instanceof PortMemberMgr && inputPortMgr instanceof PortMemberMgr) {
			// Establish connection
			const newVal: IPort = {
				portConnections: [...outputPortMgr.getPortConnections(), { port: inputPortMgr, implied: false }],
				probes: outputPortMgr.getValue().probes,
			};
			outputPortMgr.set(newVal, SetSource.USER_ASSIGN);

			// If there are other arguments, pass them along

			while (!_.isEmpty(args)) {
				const [nextInputInst, nextInputMember, ...rest] = args;
				scriptingConnect(outputInst, outputMember, nextInputInst as RuntimeInstance, nextInputMember as string);
				args = rest;
			}
		} else {
			// since we've established that both members are not ports we can tag errors here
			// other errors based on the port assignment itself should be handled in set
			// note that because we know something is wrong in the scripting.connect statement
			// there's 2 courses of actions we take dependent on what we're doing
			// if we're migrating or in compatibility mode we just want to tag errors on what we can and return
			// otherwise (usually a hand written script) don't handle anything gracefully and just throw 
			const migratingOrCompatabilityMode = shouldCapture(SetSource.USER_ASSIGN, false, false);
			tagConnectingErrors(
				inputMember,
				inputInst,
				inputInstMgr,
				inputPortMgr,
				outputMember,
				outputInst,
				outputInstMgr,
				outputPortMgr,
				migratingOrCompatabilityMode);
		}
	};
}

// Assert that port type is only input or output.  If this fails, categorize needs to be fixed up, 
// and canUserConnect's check that type != type needs to be extended

assert<Equals<PortMemberMgr["def"]["type"], "input" | "output">>();

function categorize(a: PortMemberMgr, b: PortMemberMgr): [input: PortMemberMgr, output: PortMemberMgr] {
	return a.def.type === "input" ? [a, b] : [b, a];
}

// Given any two ports picked by the user, checks if establishing a new connection between them is possible.

export function canUserConnect(a: PortMemberMgr, b: PortMemberMgr) {
	const [input, output] = categorize(a, b);
	const inputPortConnections = _.first(input.getValue().portConnections);
	return a.def.type !== b.def.type		// Only connect inputs to outputs
		&& inputPortConnections?.port !== output		// Don't re-connect if already connected
		&& !input.def.implied				// Disallow connecting to ports intended for implied connections only
		&& !output.def.implied
		&& !inputPortConnections?.implied;			// Disallow breaking an implied connection
}

// This is a connection request from the UI.  It will replace any existing connections automatically in order to 
// make this connection.
// Pre-conditions: canUserConnect() must return true
export function userConnect(a: PortMemberMgr, b: PortMemberMgr) {
	forceConnection(a, b, false, SetSource.USER_ASSIGN);
}
export function implyConnection(a: PortMemberMgr, b: PortMemberMgr) {
	forceConnection(a, b, true, SetSource.META_ARGS);
}

function forceConnection(a: PortMemberMgr, b: PortMemberMgr, implied: boolean, source: SetSource) {
	const [input, output] = categorize(a, b);
	openConnectionSlot(input);
	connect(input, { port: output, implied }, source);
}

// Connect the port using the given connection
function connect(toConnect: PortMemberMgr, connection: IPortConnection, source: SetSource) {
	const currentValue = toConnect.getValue();
	if (!_.some(currentValue.portConnections, ({ port }) => port === connection.port)) {
		const newVal: IPort = {
			...currentValue,
			portConnections: [...currentValue.portConnections, connection],
		};
		toConnect.set(newVal, source);
	}
}

export function canUserDisconnect(a: PortMemberMgr, b: PortMemberMgr) {
	const [input, output] = categorize(a, b);
	const connection = _.first(input.getPortConnections());
	return connection?.port === output && !connection?.implied;
}

// Disconnects two ports if they are connected.
// This explicitly checks the connection on the second port, so if called mid-disconnect then "this" should be passed
// first
export function disconnect(a: PortMemberMgr, b: PortMemberMgr, source: SetSource) {
	const currentValue = b.getValue();
	const connection = _.find(currentValue.portConnections, ({ port }) => port === a);
	if (connection) {
		const newVal: IPort = {
			...currentValue,
			portConnections: _.without(currentValue.portConnections, connection),
		};
		b.set(newVal, source);
	}
}

// Deletes any user connection on the input port
// Pre conditions: must be of type input
function openConnectionSlot(input: PortMemberMgr) {
	const connection = _.first(input.getPortConnections());
	if (connection && !connection.implied) {
		disconnect(input, connection.port, SetSource.TOOL_INTERNAL);
	}
}

export class PortLValue extends Array<IPortConnectionLValue> implements IPortLValue {
	constructor(arr: IPortConnectionLValue[],
		public probes: Probe[],
	) {
		super(...arr);
	}
}

// Implements the IPortConnectionLValue interface, but adds the ability for it to be passed to JSON.stringify without
// leading to a circular reference (by replacing "inst" with the name of the other instance)

class PortConnectionLValue implements IPortConnectionLValue {
	constructor(public inst: ModuleInstance, public port: string, public implied: boolean) { }
	public toJSON() {
		return {
			inst: this.inst.$name,
			port: this.port,
			implied: this.implied,
		};
	}
}

interface IPort {
	portConnections: IPortConnection[];
	probes: Probe[];
}

interface IPortConnection {
	port: PortMemberMgr;
	implied: boolean;
}

export const enum BreakUserConnections {
	DISALLOW = 0,
	ALLOW = 1,
}

function tagConnectingErrors(
	inputMember: string,
	inputInst: RuntimeInstance,
	inputInstMgr: AObjectMgr<RuntimeInstance>,
	inputPortMgr: AnyMemberMgr,
	outputMember: string,
	outputInst: RuntimeInstance,
	outputInstMgr: AObjectMgr<RuntimeInstance>,
	outputPortMgr: AnyMemberMgr,
	migratingOrCompatabilityMode: boolean) {

	if (!migratingOrCompatabilityMode) {
		throw new Error("Unknown object passed to scripting.connect");
	}

	// error messages
	const portNoLongerExists = "Tried connecting to a port which no longer exists";
	const failedConnectingPorts = "Failed connecting ports. Port configuration may have changed";

	if (_.isUndefined(inputInstMgr) || _.isUndefined(outputInstMgr) || _.isUndefined(inputPortMgr) || _.isUndefined(outputPortMgr)) {
		// check if they either are invalid member proxies, if they are we can tag the parents
		const inputInstInvalidMemberProxy = getInvalidMemberAccessProxy(inputInst);
		const outputInstInvalidMemberProxy = getInvalidMemberAccessProxy(outputInst);

		if (inputInstInvalidMemberProxy) {
			const { originalTarget, path } = inputInstInvalidMemberProxy;
			if (originalTarget instanceof AObjectMgr) {
				originalTarget.invalidPortAccess(path, portNoLongerExists);
			}
		}

		if (outputInstInvalidMemberProxy) {
			const { originalTarget, path } = outputInstInvalidMemberProxy;
			if (originalTarget instanceof AObjectMgr) {
				originalTarget.invalidPortAccess(path, portNoLongerExists);
			}
		}
		inputInstMgr?.invalidPortAccess([inputMember], portNoLongerExists);
		outputInstMgr?.invalidPortAccess([outputMember], portNoLongerExists);
	}

	// handle the case with no ports
	else if (!(outputPortMgr instanceof PortMemberMgr) || !(inputPortMgr instanceof PortMemberMgr)) {
		inputInstMgr.invalidPortAccess([inputMember], failedConnectingPorts);
		outputInstMgr.invalidPortAccess([outputMember], failedConnectingPorts);
	}
}

function tagProbingError(
	portMember: string,
	inst: RuntimeInstance,
	instMgr: AObjectMgr<RuntimeInstance>,
	portMgr: AnyMemberMgr,
	migratingOrCompatabilityMode: boolean) {

	if (!migratingOrCompatabilityMode) {
		throw new Error("Unknown object passed to scripting.probe");
	}

	const portNoLongerExists = "Tried probing a port which no longer exists";
	const failedProbingPort = "Failed probing port. Port configuration may have changed";

	if (_.isUndefined(instMgr) || _.isUndefined(portMgr)) {
		const instInvalidMemberProxy = getInvalidMemberAccessProxy(inst);
		if (instInvalidMemberProxy) {
			const { originalTarget, path } = instInvalidMemberProxy;
			if (originalTarget instanceof AObjectMgr) {
				originalTarget.invalidPortAccess(path, portNoLongerExists);
			}
		}

		instMgr?.invalidPortAccess([portMember], portNoLongerExists);
	} else if (!(portMgr instanceof PortMemberMgr)) {
		instMgr?.invalidPortAccess([portMember], failedProbingPort);
	}
}
