import * as _ from "lodash";
import * as path from "path";
import ELK, { ElkNode } from "elkjs/lib/elk-api";
import { isNodejs } from "../../../services/platform";
import { httpRootDir, rootDir } from "../../../services/paths";

// Note that ELK will fetch the elk-worker.min.js code once created.  That code is a few megs.  The reason we create 
// ELK here in a memoized getter, vs just statically once, is so that fetch only happens if we actually use ELK.  Most
// users will not, so this saves them a lot of network bandwidth.

const getElk = _.memoize(() => {
	const elk = isNodejs()
		? new ELK({ workerFactory: (url) => new (__non_webpack_require__(path.join(rootDir(), "./elk-worker.min.js")).Worker)(url) })
		: new ELK({ workerUrl: httpRootDir() + "elk-worker.min.js" });
	return elk;
});

export function elkLayout<T extends ElkNode>(graph: T) {

	// Uncomment to see what ELK exposes as the various options
	// const knownLayoutAlgorithms = await getElk().knownLayoutAlgorithms();
	// const knownLayoutCategories = await getElk().knownLayoutCategories();
	// const knownLayoutOptions = await getElk().knownLayoutOptions();

	return getElk().layout(graph) as Promise<T>;
}

export const elkRootLayoutOptions = {
	// This is the type of algorithm to use to do the layout.  The layered algorithm will try to arrange nodes
	// left to right (or top to bottom) so that one layer feeds into the next.
	"elk.algorithm": "layered",
};

export const elkNodeLayoutOptions = {
	// This prevents ports from being moved in order to minimize line crossings.  Without this, ports would change 
	// based on the current view
	"portConstraints": "FIXED_ORDER",

	// This indicates that the label for the node (not the ports) is centered at the bottom and outside
	"nodeLabels.placement": "[H_CENTER, V_BOTTOM, OUTSIDE]",
};
