import * as React from "react";

// React hook to return a boolean and a function to toggle that boolean's value.

export function useToggle(initialState: boolean) {
	const [toggleValue, setToggleValue] = React.useState(initialState);
	const toggler = React.useCallback(() => setToggleValue(!toggleValue), [toggleValue]);
	return [toggleValue, toggler] as const;
}
