import * as _ from "lodash";
import React = require("react");
import { TreeNode, ITreeNode, shouldBeDisplayed } from "./TreeNode";
import { List, Typography, ClickAwayListener } from "../imports/material-ui-imports";
import { ConfigStoreActions } from "../services/configStore";
import { commonStyles } from "./styles/common";
import { ATheme } from "./styles/themes";
import { Validations } from "../services/objectManagers/validations";

interface IProps {
	treeNodes: ITreeNode[];
	actions: ConfigStoreActions;
	selectedTreeNode: ITreeNode;
	searchText: string;
	theme: ATheme;
	validations: Validations;
	displayScriptName: boolean;
}

interface IState {
	focus: boolean;
}

// takes an array of TreeEntryContent and draws a tree list
export class Tree extends React.Component<IProps, IState> {

	public override state: IState = { focus: true }

	public override render() {
		return (
			_.some(this.props.treeNodes, (n) => shouldBeDisplayed(n, this.props.searchText)) ?
				<ClickAwayListener
					mouseEvent="onMouseDown"	// Required to intercept clicks on configurables
					touchEvent="onTouchStart"
					onClickAway={this.handleClickAway}
				>
					<List id="treeContainer" onClick={this.handleClick}>
						{
							_.map(this.props.treeNodes, (entry) => {
								return (
									<TreeNode
										theme={this.props.theme}
										key={entry.getID()}
										level={0}
										filterText={this.props.searchText}
										selectedTreeNode={this.props.selectedTreeNode}
										treeNode={entry}
										actions={this.props.actions}
										validations={this.props.validations}
										displayScriptName={this.props.displayScriptName}
										focus={this.state.focus}
									/>
								);
							})
						}
					</List>
				</ClickAwayListener>
				:
				<Typography
					variant="body2"
					style={commonStyles.neutralText}>
					No search results found
				</Typography>
		);
	}

	private handleClick = () => {
		if (!this.state.focus) {
			this.setState({ focus: true });
		}
	};

	private handleClickAway = () => {
		if (this.state.focus) {
			this.setState({ focus: false });
		}
	};
}
