import * as _ from "lodash";
import { DevicePin, AdaptedDeviceInfo } from "dataInterfaces";
import { DevicePinSolutionMap, Pin } from "./solver/requirements";
import { IFormatter } from "./formatting/formattingTypes";
import { ITreeNode } from "../components/TreeNode";
import { HardwareComponent, HardwareComponentSignal } from "public/runtime";
import { HeaderPin } from "public/defs";
import { HardwareComponentMgr } from "./instanceContainers/hardwareComponent";
import { getDisplayName } from "./utils";
import { ILinkActions } from "../components/actions/ILinkActions";
import { isFormattedLink } from "./formatting/link";

// given a hardware component, returns the list of signals for itself and the sub components
export function gatherSignals(component: HardwareComponent): HardwareComponentSignal[] {
	return ([
		..._.toArray(component.signals),
		..._.flatMap(component.subComponents, gatherSignals),
	]);
}

interface TooltipEntry {
	col1: string;		// content of the first column
	col2?: string[];	// content for the second column (array of strings)
	success?: boolean;	// decorates this row with success colours
	title?: boolean;	// decorates this row to indicate it is a title (ie; underline)
}

// A helper class to get information for a pin
export class PinInfo {

	constructor(
		private readonly deviceData: AdaptedDeviceInfo,
		private readonly devicePinSolutionMap: DevicePinSolutionMap,
		private readonly selectedPins: Set<string>,
		private readonly formatter: IFormatter,
		private readonly selectedTreeEntry: ITreeNode,
		private readonly actions: ILinkActions,
	) {
	}

	public navigateTo(devicePin: DevicePin) {
		const pinReqs = this.devicePinSolutionMap[devicePin.name];
		if (pinReqs) {
			const link = _.first(this.formatter(_.first(pinReqs)).toParts());
			if (isFormattedLink(link)) {
				link.linkAction(this.actions);
			}
		}
	}

	// given a device pin, determine if the pin is currently selected (based on currently selected hardware)
	public isPinSelected(devicePin: DevicePin, headerPin?: HeaderPin) {
		if (this.selectedTreeEntry instanceof HardwareComponentMgr) {
			const selectedHW = this.selectedTreeEntry.getHwComponent();
			return _.some(gatherSignals(selectedHW), (signal) => {
				return (!!signal.devicePin && signal.devicePin === devicePin) ||
					(!!signal.headerPin && signal.headerPin === headerPin);
			});
		}
		return false;
	}

	// check if a pin should be highlighted
	public isPinCurrentlySelected(devicePinName?: string) {
		return this.selectedPins.has(devicePinName);
	}

	// given a device pin, determine if the pin is currently in use
	public isPinInUse(devicePin?: DevicePin) {
		if (devicePin) {
			return !!this.devicePinSolutionMap[devicePin.name];
		}
		return false;
	}

	public isPinReserved(devicePin?: DevicePin) {
		if (this.isPinInUse(devicePin)) {
			return _.every(this.devicePinSolutionMap[devicePin.name], (p) => p.reserved);
		}
		return false;
	}

	// given a device pin, determine if the pin is currently in use
	public isPinShared(devicePin?: DevicePin) {
		if (devicePin) {
			return this.devicePinSolutionMap[devicePin.name] && this.devicePinSolutionMap[devicePin.name].length > 1;
		}
		return false;
	}

	// generates array of tooltip entries for generating the HTML for the tooltip popup
	public getTooltip(
		shouldShowModeTable: boolean, devicePin: DevicePin, headerPin?: HeaderPin, boardNumberOffset?: number
	): TooltipEntry[] {
		const tooltipEntryArr = getHeaderPinTooltip(devicePin, headerPin, boardNumberOffset);

		if (devicePin) {
			tooltipEntryArr.push(...this.getDevicePinTooltip(devicePin, headerPin, shouldShowModeTable));
		}

		return tooltipEntryArr;
	}

	// get the list of associated components that uses the given device or header pin
	public getAssociatedComponentsList(devicePin: DevicePin, headerPin?: HeaderPin) {
		return _.uniq(_.filter(this.deviceData.board?.components, (component) => {
			return !!_.find(gatherSignals(component), (signal) => {
				return (!!signal.devicePin && signal.devicePin === devicePin) ||
					(!!signal.headerPin && signal.headerPin === headerPin);
			});
		}));
	}

	private getDevicePinTooltip(devicePin: DevicePin, headerPin: HeaderPin, shouldShowModeTable: boolean) {
		const tooltipEntryArr: TooltipEntry[] = [];
		tooltipEntryArr.push({ col1: "Device Pin Name:", col2: [devicePin.designSignalName] });

		if (devicePin.powerDomain?.name) {
			tooltipEntryArr.push({ col1: "Power:", col2: [devicePin.powerDomain.name] });
		}

		const associatedHW = this.getAssociatedComponentsList(devicePin, headerPin);
		if (!_.isEmpty(associatedHW)) {
			tooltipEntryArr.push({ col1: "Hardware:", col2: _.map(associatedHW, (component) => getDisplayName(component, false)) });
		}

		const assignments = this.devicePinSolutionMap[devicePin.name] || [];
		if (!_.isEmpty(assignments)) {
			tooltipEntryArr.push({ col1: "Software:", col2: [_.map(assignments, (a) => this.format(a)).join(", ")] });
		}

		// devicePin.description was intended to be used for this tooltip and nothing else.  Unfortunately, when the 
		// converters were originally rush-created, they added filler values for description: either the pin name or
		// the pin name with "device pin" affixed to the end.  That isn't useful text for a tooltip, and there were 
		// requests to have a real description here.  
		//
		// Unfortunately, meta-content started accessing it as a substitute for the designSignalName, so changing
		// description now would break a lot of legacy products.  The solution is to use description2 instead.
		//
		// However, the c2k converter has useful descriptions in description, and is written where it can't be updated
		// as it is a direct dump from xml.  As such, we still look at description if there is no description2, but 
		// only if it's not "trivial".

		if (devicePin.description2) {
			tooltipEntryArr.push({ col1: "Description:", col2: [devicePin.description2] });
		} else if (
			devicePin.description &&
			devicePin.description !== devicePin.designSignalName &&
			devicePin.description !== devicePin.designSignalName + " device pin") {
			tooltipEntryArr.push({ col1: "Description:", col2: [devicePin.description] });
		}

		// INPUTXBAR is a C2000 peripheral where you can map any pin to almost anywhere.  In the device data this 
		// shows up as many "pseudo" modes on the mux named "XBAR#".  Showing those made it impossible to view the 
		// pop up.  The solution is to filter those modes out, and just add a summary to the description
		if (_.some(devicePin.mux?.muxSetting, isInputXBar)) {
			_.last(tooltipEntryArr).col2.push("(Supports INPUTXBAR)");
		}

		if (shouldShowModeTable && devicePin.mux) {
			tooltipEntryArr.push({ col1: "Mode:", col2: ["Function"], title: true });

			const assignedToNames = _.map(assignments, (assignment) => assignment.solution.assignedPeripheralPin);
			_.each(devicePin.mux.muxSetting, (muxSetting) => {
				const mode = muxSetting.mode;
				const signalName = muxSetting.peripheralPin.name;
				if (!isInputXBar(muxSetting)) {
					if (-1 !== _.indexOf(assignedToNames, signalName)) {
						tooltipEntryArr.push({ col1: mode, col2: [signalName], success: true });
					} else {
						tooltipEntryArr.push({ col1: mode, col2: [signalName] });
					}
				}
			});
		}
		return tooltipEntryArr;
	}

	// uses the formatter to format the pin requirement
	private format(pin: Pin) {
		return this.formatter(pin);
	}
}

function getHeaderPinTooltip(devicePin: DevicePin, headerPin?: HeaderPin, boardNumberOffset?: number) {
	const tooltipEntryArr: TooltipEntry[] = [];
	if (headerPin && !!headerPin.number) {
		tooltipEntryArr.push({ col1: "Board Pin Number:", col2: [(headerPin.number + (boardNumberOffset || 0)).toString()] });
	}
	if (headerPin && !!headerPin.name) {
		tooltipEntryArr.push({ col1: "Board Pin Name:", col2: [headerPin.name] });
	}

	if (headerPin && !!headerPin.ball) {
		tooltipEntryArr.push({ col1: "Device Pin Number:", col2: [headerPin.ball] });
	} else if (devicePin && !!devicePin.name) {
		tooltipEntryArr.push({ col1: "Device Pin Number:", col2: [devicePin.name] });
	}
	return tooltipEntryArr;
}

function isInputXBar(muxSetting: DeviceInfo.MuxSetting) {
	return _.startsWith(muxSetting.mode, "XBAR");
}
