import * as _ from "lodash";
import React = require("react");
import { IBasicInputProps } from "../InputBox";

interface IState {
	value: string;
	resyncTrigger: any;
}

interface IDebounceInputProps {
	resyncTrigger?: any;
}

export function debounceInput<T extends IBasicInputProps>(BaseInput: React.ComponentClass<T>) {

	class DebouncedInput extends React.Component<T & IDebounceInputProps, IState> {
		// The reason that we need a resyncTrigger is because of PMUX-2086 and PMUX-2177.
		// The "value provider" of this component can change in SysConfig.
		// I.e. when we switch the selected instance in the UI, this component's onChange will be attached to
		// the new selected instance but it will not know to update its state value when the switch happens,
		// keeping the stale value of the previous instance.
		// resyncTrigger is thus needed to notify this component that a resynchronization with the value provider is
		// immediately required.

		public static getDerivedStateFromProps(nextProps: T & IDebounceInputProps, prevState: IState) {
			return (nextProps.resyncTrigger !== prevState.resyncTrigger) ?
				{ resyncTrigger: nextProps.resyncTrigger, value: nextProps.value } :
				{};
		}

		private handleOnChange = _.debounce((value: string) => { this.props.onChange(value); }, 200);
		private containerRef: HTMLElement;

		constructor(props: T & IDebounceInputProps) {
			super(props);
			this.state = {
				value: this.props.value,
				resyncTrigger: this.props.resyncTrigger,
			};
		}

		public override render() {
			return (
				<span ref={this.setRef}>
					<BaseInput
						{...this.props}
						value={this.isFocused() ? this.state.value : this.props.value}
						onChange={this.onChange}
						onBlur={this.onBlur}
						onFocus={this.syncValue} // Sync the value when we initially gain focus as it may have changed due to an onChange
					/>
				</span>
			);
		}

		private setRef = (el: HTMLInputElement) => {
			this.containerRef = el;
		}

		private isFocused() {
			return this.containerRef && this.containerRef.contains(document.activeElement);
		}

		private onChange = (newVal: string) => {
			if (this.isFocused()) {
				this.setState({ value: newVal }, () => this.handleOnChange(this.state.value));
			}
		}

		private onBlur = () => {
			this.handleOnChange.flush();
			this.syncValue();
		}

		private syncValue = () => {
			if (this.state.value !== this.props.value) {
				this.setState({ value: this.props.value });
			}
		}
	}

	return DebouncedInput;
}
