import * as _ from "lodash";
import { MultiValueEnumerationConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { convertUnknownToError } from "../../utils";
import { AObjectMgr } from "../object";
import { IOptions } from "../options";
import { Validations } from "../validations";
import {
	BaseEnumerationConfigurableMgr, unknownOptionError,
} from "./baseEnumerationConfigurableMgr";
import { ConfigurableComponent } from "./configurableComponent";

export class MultiValueEnumerationConfigurableMgr<
	T extends number | string = string,
	RuntimeObjectType extends RuntimeObject = RuntimeObject>
	extends BaseEnumerationConfigurableMgr<T, T[], RuntimeObjectType, MultiValueEnumerationConfigurable<T>>

	implements IOptions<T> {

	public readonly minSelections: number;

	public readonly ui = ConfigurableComponent.CMultiValueEnumerationConfigurable;

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		def: MultiValueEnumerationConfigurable<T>,
	) {
		super(parentObjectMgr, formattersMap, def);

		// eslint-disable-next-line deprecation/deprecation
		this.minSelections = this.isDynamic() ? 0 : (this.def.minSelections ?? 1);

		// validate default
		try {
			this.validateValue(this.def.default);
		} catch (e) {
			throw new Error(`Can't set default: ${convertUnknownToError(e).message}`);
		}
		// freeze the init value
		this.onSet(this.value);
	}

	public override getScriptValue() {
		return { value: JSON.stringify(this.value), shouldQuoteStrings: false };
	}

	public override getToolTip(validations: Validations) {
		const baseTooltip = super.getToolTip(validations);
		return (baseTooltip + "\n" + this.getSelectedOptions()).trim();
	}

	protected override getCurrentSelections() {
		return this.value;
	}

	protected override transform(newVal: T[]): T[] {
		// Always save in sorted order
		// so [1,2] and [2,1] can be treated as being equal.
		// This can occur if the user is un-checking/checking items in the GUI
		return _.chain(newVal)
			.map((v) => this.legacyNamesMap?.get(v) ?? v)
			.sortBy()
			.sortedUniq()
			.value();
	}

	protected override validateValue(newVal: T[]): void {
		if (!this.isDynamic()) {
			const options = this.getOptions();
			if (!_.isArray(newVal)) {
				this.typeMismatch("array", typeof newVal);
			}

			// eslint-disable-next-line deprecation/deprecation
			if (newVal.length < this.minSelections) {
				throw new Error(`[] must contain at least ${this.minSelections} value(s)`);
			}

			if (_.uniq(_.map(newVal, (v) => typeof v)).length > 1) {
				throw new Error("All elements of the [] must be of the same type");
			}

			if (!_.isEmpty(newVal) && (typeof newVal[0] !== typeof options[0].name)) {
				throw new Error(`[] elements must be of type ${typeof options[0].name}`);
			}

			const validOptions = _.map(options, (o) => o.name);
			_.each(newVal, (val) => {
				if (!_.includes(validOptions, val) && !this.legacyNamesMap?.has(val)) {
					unknownOptionError(val, validOptions);
				}
			});
		} else {
			if (!_.isArray(newVal)) {
				this.typeMismatch("array", typeof newVal);
			}
		}
	}

	protected override onSet(newVal: T[]) {
		// To simplify implementation we don't support mutating a value after assignment.
		// The user must assign a new array with desired modifications.
		Object.freeze(newVal);
	}

	protected override isEqual(val: T[]) {
		return _.isEqual(this.value, val);
	}

	private getSelectedOptions(): string {
		const value = this.value;
		return (_.isEmpty(value) ? "" : "Selected: \n") +
			_.chain(this.getOptions())
				.filter((option) => _.includes(value, option.name))
				.map((o) => o.displayName ?? o.name.toString())
				.join("\n")
				.value() || "";
	}
}
