import * as React from "react";
import * as _ from "lodash";
import {
	ListItem, ListItemText, ListItemSecondaryAction, SvgIconProps, IconButton, Typography,
} from "../../imports/material-ui-imports";
import { Download, Delete, FileDocument, File } from "../../imports/mdi-material-ui-imports";
import { IStorageFile } from "../../services/storage";
import { commonStyles, CommonClasses, withCommonStyles } from "../styles/common";
import { defaultFontSize } from "../styles/themes";
import {
	paddingPerLevel, statusIconSize,
	ICommonItemProps, getFileStatusDecorator, getFileNameAndSizeComponent,
} from "./common";

interface IFileItemProps extends ICommonItemProps {
	file: IStorageFile;
	onFileSelect?: (f: IStorageFile) => void;
	onFileDownload?: (f: IStorageFile) => void;
	onFileDelete?: (f: IStorageFile) => void;
}

interface IBaseFileItemProps extends IFileItemProps {
	style: React.CSSProperties;
	dense: boolean;
	Icon: React.ComponentType<SvgIconProps>;
	statusDecorator?: JSX.Element;
	body: JSX.Element;
}

// The UI component that shows one list entry of a specific file.
class StyledBaseFileItem extends React.Component<IBaseFileItemProps & CommonClasses> {
	public override render() {
		const className = (this.props.file.path === this.props.selectedPath)
			? this.props.classes.selectedList
			: this.props.classes.unSelectedList;
		return this.matchesFilter(this.props.file, this.props.fnameFilter) &&
			<ListItem
				disabled={this.props.disabled}
				dense={this.props.dense}
				button
				id={this.props.file.path + "_file"}
				style={this.props.style}
				className={className}
				onClick={() => {
					if (this.props.onFileSelect) {
						this.props.onFileSelect(this.props.file);
					}
				}}
			>
				{this.props.statusDecorator}
				<this.props.Icon color="primary" style={commonStyles.smallIcon} />
				{this.props.body}
				<ListItemSecondaryAction>
					{
						this.props.onFileDownload &&
						<IconButton
							id={this.props.file.path + "download"}
							onClick={() => this.props.onFileDownload(this.props.file)}
						>
							<Download color="primary" style={commonStyles.smallIcon} />
						</IconButton>

					}
					{
						this.props.onFileDelete &&
						<IconButton
							onClick={() => this.props.onFileDelete(this.props.file)}
						>
							<Delete color="primary" style={commonStyles.smallIcon} />
						</IconButton>
					}
				</ListItemSecondaryAction >
			</ListItem>;
	}
	private matchesFilter(file: IStorageFile, fnameFilter: string) {
		return _.chain(fnameFilter)
			.split(",")
			.map((filter) => new RegExp(filter))
			.some((filter) => filter.test(file.name))
			.value();
	}
}

const BaseFileItem = withCommonStyles(StyledBaseFileItem);

export class FileExplorerFileItem extends React.Component<IFileItemProps> {
	public override render() {
		return <BaseFileItem
			{...this.props}
			style={{
				...commonStyles.extraDenseList,
				paddingLeft: ((paddingPerLevel * this.props.level)
					+ defaultFontSize
					- (this.props.status ? statusIconSize : 0)
					+ 3),
				color: commonStyles.modalTextColor,
			}}
			dense={false}
			Icon={FileDocument}
			statusDecorator={getFileStatusDecorator(this.props.file.relativePath, this.props.status)}
			body={<ListItemText
				style={{ paddingLeft: "5px", paddingRight: "0px" }}
				primary={getFileNameAndSizeComponent(this.props.file.name, this.props.getSize(this.props.file))}
			/>}
		/>;
	}
}

export class FileItem extends React.Component<IFileItemProps> {
	public override render() {
		return <BaseFileItem
			{...this.props}
			style={{
				paddingLeft: paddingPerLevel * this.props.level + defaultFontSize,
			}}
			dense={false}
			Icon={File}
			body={<ListItemText primary={<Typography>{this.props.file.name}</Typography>} />}
		/>;
	}
}
