// UI Views for meta content defined configurables
import * as React from "react";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { FileTextConfigurableMgr } from "../../../services/objectManagers/configurables/fileTextConfigurableMgr";
import { OnBlurInputBox } from "../../higherOrderComponents/ComposedComponents";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { FileBrowse } from "../../FileBrowse";
import { IconButton, Tooltip } from "../../../imports/material-ui-imports";
import { FolderSearchOutline } from "../../../imports/mdi-material-ui-imports";
import { spacingUnit } from "../../styles/themes";
import { commonStyles } from "../../styles/common";

export class CFileConfigurable extends React.Component<{
	mgr: FileTextConfigurableMgr;
	actions: IConfigurablesActions;
} & IGlobalServiceProps> {
	constructor(props: {
		mgr: FileTextConfigurableMgr;
		actions: IConfigurablesActions;
	} & IGlobalServiceProps) {
		super(props);
	}
	public override render() {
		const mgr = this.props.mgr;
		const actions = this.props.actions;
		const disabled = !!mgr.uiState.readOnly;
		return (<span style={{ display: "table" }}>
			<span style={{ display: "table-cell", paddingRight: "5px", width: "100%" }}>
				<OnBlurInputBox
					value={mgr.getValue()}
					type="text" placeholder={mgr.def.placeholder}
					id={mgr.def.name}
					onChange={(val) => actions.setConfigurableValue(mgr, val)}
					disabled={disabled} />
			</span>
			<span style={{ display: "table-cell" }}>
				{disabled ?
					<Tooltip title="disabled">
						<IconButton id={`${mgr.def.name}disabledIcon`} component="span" style={{ cursor: "default", padding: spacingUnit }}>
							<FolderSearchOutline color="primary" style={commonStyles.smallIcon} />
						</IconButton>
					</Tooltip> :
					<FileBrowse
						{...this.props}
						onChange={(fpath) => actions.setConfigurableValue(mgr, fpath)}
						id={`${mgr.def.name}FileBrowse`}
						accept={mgr.def.fileFilter}

						disabled={disabled}
						folder={mgr.def.pickDirectory}
					>
						<IconButton component="span" style={{ padding: spacingUnit }}>
							<FolderSearchOutline color="primary" style={commonStyles.smallIcon} />
						</IconButton>
					</FileBrowse>
				}
			</span>
		</span >);
	}
}
