import * as _ from "lodash";
import * as Layout from "../../graph/types/layoutTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";
import { mapAdjacentElems } from "../../../services/utils";
import { aStarFinder } from "./pathFinding/aStarFinder";
import { RoutingMatrix } from "./routingMatrix";
import { compressPath, Point } from "./pathFinding/util";

// This function will take the edges defined and route them around the nodes in a "pleasing" way typical for schematic
// diagrams (orthogonal edges, minimal crossings, few bends with bends typically in the middle).  It will return the 
// segments necessary for all the routing which might need to be further combined to render correctly

export function routeEdges(nodes: Layout.Node<ModuleInstanceMgr, PortMemberMgr>[], edges: Layout.Edge<PortMemberMgr>[]) {
	const matrix = new RoutingMatrix(nodes);

	// We don't want edges to overlap unless they are from the same source.  So we group by the source location and 
	// then don't mark the edges in the matrix until all edges for that source have been routed

	return _.chain(edges)
		.groupBy((e) => e.source.getID())
		.flatMap((edgesWithSameSource) => {
			const pathsWithSameSource: Point[][] = [];
			const routedSegments = _.flatMap(edgesWithSameSource, (e) => {

				// Use A* to find a path

				const grid = matrix.getGrid();
				const path = compressPath(aStarFinder(
					matrix.getGridStart(e.start),
					matrix.getGridEnd(e.end),
					grid,
				));
				pathsWithSameSource.push(path);

				// Convert from grid indexes back into graph coordinates

				const completePath = pathToCoordinates(e.start, path, e.end, matrix);

				// Convert the graph coordinates into Layout.Edge values

				return mapAdjacentElems(completePath, ([startX, startY], [endX, endY]) => {
					return {
						...e,
						id: `segment(${startX},${startY})-(${endX},${endY})`,
						start: { x: startX, y: startY },
						end: { x: endX, y: endY },
					};
				});
			});

			// Mark the paths we found for this source in the routing matrix so that subsequent paths will not be 
			// routed over top of these paths

			_.each(pathsWithSameSource, (path) => matrix.markEdge(path));
			return routedSegments;
		})
		.value();
}

function pathToCoordinates(start: Layout.Point, compressedPath: Point[], end: Layout.Point, matrix: RoutingMatrix): Point[] {

	// Empty means no path was found.  Size of one means start === end.  Either way, create a direct connection and 
	// don't worry about edge routing

	if (_.size(compressedPath) <= 1) {
		return [[start.x, start.y], [end.x, end.y]];
	}

	// Convert the path into coordinates

	let pathAsCoordinates = _.map(compressedPath, (indices) => matrix.toPoint(indices));

	// Since the conversion uses a matrix, converting back is not lossless, and the start/end location may not line up.
	// First, since we can have multiple edges connected to one source, we should shift everything to match that source
	// vs creating a bend at the start.  That way, later joints will extend from that same horizontal segment.

	const mappedSourceY = pathAsCoordinates[0][1];
	pathAsCoordinates[0][1] = start.y;
	if (pathAsCoordinates[1][1] === mappedSourceY) {
		pathAsCoordinates[1][1] = start.y;
	}

	// Next, if the end does not align, either update the final bend or create a new bend

	let len = _.size(pathAsCoordinates);
	if (end.y !== _.last(pathAsCoordinates)[1]) {
		if (len >= 3) {// if there's at least one bend, update it
			if (pathAsCoordinates[len - 2][1] === pathAsCoordinates[len - 1][1]) {
				pathAsCoordinates[len - 2][1] = end.y;
			}
			pathAsCoordinates[len - 1][1] = end.y;
		} else if (len !== 0) { // need to add a bend			
			pathAsCoordinates.push([pathAsCoordinates[len - 1][0], end.y]);
		}
	}

	// Now, extend the path with the end segments.  We could just add them and call compressPath(), but since we know 
	// it's already compressed in the middle, we can just look at the start/end

	// add and compress final start

	if (_.size(pathAsCoordinates) >= 2 && start.y === pathAsCoordinates[0][1] && start.y === pathAsCoordinates[1][1]) {
		pathAsCoordinates[0][0] = start.x;
	} else {
		pathAsCoordinates = [[start.x, start.y], ...pathAsCoordinates];
	}

	// add and compress final end

	len = _.size(pathAsCoordinates);
	if (len >= 2 && end.y === pathAsCoordinates[len - 1][1] && end.y === pathAsCoordinates[len - 2][1]) {
		_.last(pathAsCoordinates)[0] = end.x;
	} else {
		pathAsCoordinates.push([end.x, end.y]);
	}
	return pathAsCoordinates;
}
