import * as _ from "lodash";
import { DropDownOption } from "../../components/ComponentUtils";
import { HardwareOption } from "./hardwareMember";
import { EnumCLIOptions, HardwareCLIOptions } from "public/test";

export interface IOptions<T extends number | string> {
	getUIOptions(): { enabledOptions: DropDownOption[], disabledOptions: DropDownOption[] };
	getCLIOptions(): EnumCLIOptions<T>;
}

export interface IHardwareOptions {
	getUIOptions(): { enabledOptions: HardwareOption[], disabledOptions: HardwareOption[] };
	getCLIOptions(): HardwareCLIOptions;
}

export function isIOptions<T extends number | string>(obj: unknown): obj is IOptions<T> | IHardwareOptions {
	const asOptions = obj as IOptions<T>;
	return _.isObject(asOptions) && !!asOptions.getCLIOptions && !!asOptions.getUIOptions;
}
