import * as Layout from "../types/layoutTypes";
import { createFinalSvgPathNode } from "./createSvgPathNode";

// Rectangle with a triangle on both sides.  Like a pin, it indicates flow is left to right or right to left.

function biDirectionalPinPath(width: number, height: number) {
	const rectangleStart = width * 1 / 5;
	const rectangleEnd = width * 4 / 5;
	return `M 0 ${height / 2} ` 		// Start in middle of left side
		+ `L ${rectangleStart}, 0 `		// Top of left triangle
		+ `H ${rectangleEnd} ` 			// Top of rectangle
		+ `L ${width} ${height / 2} `	// Top of triangle right triangle
		+ `L ${rectangleEnd} ${height} `// Bottom of right triangle
		+ `H ${rectangleStart} `		// Bottom of rectangle
		+ `L 0 ${height / 2} Z`;		// Bottom of left triangle and close
}

function getInputXOffset({ width, height }: Layout.Size, y: number) {

	// There is a right triangle with hypotenuse starting at (0, height/2) and ending at (width * 1 / 5, 0)
	// Since the triangle is reflected horizontally, we can use abs(y-height/2) and find the intercept on the top only
	// So the equation is y = slope*x + yIntercept
	// y = abs(y-height/2)
	// slope = rise/run = (height/2)/(width*1/5)
	// yIntercept = 0
	// solve for x

	const triangleHeight = height / 2;
	return Math.abs(y - triangleHeight) / triangleHeight * width / 5;
}

function getOuputXOffset(nodeSize: Layout.Size, y: number) {
	return -getInputXOffset(nodeSize, y);
}

// The "2" is extra padding to prevent the triangle from pinching the label

function getLabelXOffset(input: boolean) {
	if (input) {
		return (nodeSize: Layout.Size, y: number) => getInputXOffset(nodeSize, y) + 2;
	}
	return (nodeSize: Layout.Size, y: number) => getOuputXOffset(nodeSize, y) - 2;
}

// Extra 5 as triangle may pinch on the label otherwise.  There will only ever be one output, so hight-based 
// adjustments aren't needed.

export const BiDirectionalPinNode = createFinalSvgPathNode(biDirectionalPinPath, {
	extraWidth: 15,
	heightFactor: 1 / 2,
	inputLabelXOffset: getLabelXOffset(true),
	outputLabelXOffset: getLabelXOffset(false),
	inputPortXOffset: getInputXOffset,
	outputPortXOffset: getOuputXOffset,
});

