import { createFinalSvgPathNode } from "../createSvgPathNode";
import { bufferPath } from "./BufferNode";

// Node for a NOT gate

const radius = 5;
export const notCircleDiameter = radius * 2;

function notPath(width: number, height: number) {
	return bufferPath(width - notCircleDiameter, height) + notCirclePath(width, height);
}

export function notCirclePath(width: number, height: number) {
	return `M ${width - notCircleDiameter} ${height / 2} `
		+ `a ${radius} ${radius} 0 1 1 ${notCircleDiameter} 0 `
		+ `a ${radius} ${radius} 0 1 1 -${notCircleDiameter} 0 Z`;
}

// There will only ever be one output, so hight-based adjustments at the output aren't needed.

export const NotNode = createFinalSvgPathNode(notPath, {
	extraWidth: notCircleDiameter,
	outputLabelXOffset: () => -notCircleDiameter - 5, // Extra 5 as triangle may pinch on the label otherwise
});
