import * as _ from "lodash";
import {
	InstanceArgs,
	InstanceArgsValue,
	NonStaticModuleRequirement,
	ModuleInstanceRequirement,
	SharedModuleInstanceRequirement,
} from "public/defs";

function legacyConvertHardwareToRequiredArgs<T extends NonStaticModuleRequirement>(req: T) {

	// "hardware" being null did not mean locking the child's $hardware to "none",
	// instead it meant that there were no restrictions.
	// However when using requiredArgs.$hardware, null means that child's $hardware should be locked to "none".
	// While undefined means that child's $hardware can be free.

	// eslint-disable-next-line deprecation/deprecation
	if (!req.hardware) {
		return req;
	}

	// eslint-disable-next-line deprecation/deprecation
	if (req.hardware && req.requiredArgs?.$hardware) {
		throw new Error("Cannot specify both 'hardware' and 'requiredArgs.$hardware'");
	}

	req = {
		...req,
		// eslint-disable-next-line deprecation/deprecation
		requiredArgs: { ...req.requiredArgs, $hardware: req.hardware },
	};
	_.unset(req, "hardware");
	return req;
}

function hasArgs(req: any): req is { args: InstanceArgs } {
	return !!(req as any).args;
}

function removeUndefinedArgs<T extends NonStaticModuleRequirement>(req: T) {
	if (hasArgs(req)) {
		req = { ...req, args: _.omitBy(req.args, _.isUndefined) };
	}
	if (req.requiredArgs) {
		req = { ...req, requiredArgs: _.omitBy(req.requiredArgs, _.isUndefined) };
	}
	return req;
}

export function adaptNonStaticModuleReqs<T extends NonStaticModuleRequirement>(reqs: T[]) {
	return _.map(reqs, (req) => {
		// deprecated "hardware" property is transformed into the $hardware field on requiredArgs
		req = legacyConvertHardwareToRequiredArgs(req);
		// all args properties with explicit "undefined" as value will be deleted because it messes up object comparison
		req = removeUndefinedArgs(req);
		return req;
	});
}

const invalidLabel = {};
function diffArgs(
	filter: (k: string, v: InstanceArgsValue, a1: InstanceArgs, a2: InstanceArgs) => InstanceArgsValue,
	args1: InstanceArgs = {},
	args2: InstanceArgs = {},
): InstanceArgs {
	return _.chain(args1)
		.mapValues((argVal, argKey) => {
			if (_.isPlainObject(argVal) && argKey !== "$hardware") {
				const subResult = diffArgs(
					filter,
					argVal as InstanceArgs,
					_.get(args2, argKey, {}) as InstanceArgs,
				);
				return _.isEmpty(subResult) ? invalidLabel : subResult;
			} else {
				return filter(argKey, argVal, args1, args2);
			}
		})
		.omitBy((v) => v === invalidLabel)
		.value() as any as InstanceArgs;
}

export function getRemovedArgs(prevArgs: InstanceArgs = {}, newArgs: InstanceArgs = {}) {
	return diffArgs(
		(k: string, v: InstanceArgsValue, _a1: InstanceArgs, a2: InstanceArgs) => {
			// only keep those arg entries that are in one arg but not the other
			if (k in a2) {
				return invalidLabel;
			} else {
				return v;
			}
		},
		prevArgs,
		newArgs,
	);
}

export function getUpdatedArgs(prevArgs: InstanceArgs = {}, newArgs: InstanceArgs = {}) {
	return diffArgs(
		(k: string, v: InstanceArgsValue, _a1: InstanceArgs, a2: InstanceArgs) => {
			// only keep those args that are both in prevArgs and newArgs, and have non equal values
			if (!(k in a2) || _.isEqual(a2[k], v)) {
				return invalidLabel;
			} else {
				return v;
			}
		},
		newArgs,
		prevArgs,
	);
}

export function getNewArgs(prevArgs: InstanceArgs = {}, newArgs: InstanceArgs = {}) {
	// the new args are the opposite of removed args
	return getRemovedArgs(newArgs, prevArgs);
}

// The new reqs are compared with the old reqs. 
// This is to categorize each reqs into one of the 4 categories: removed, added, updated-preserve, updated-recreate
// 	- removed reqs are those that are in the old reqs but no longer in the new reqs.
// 	  The members that were associated with these reqs need to be deleted.
// 	- added reqs are in the new reqs but were not in the old reqs. New members must be created to satisfy these reqs.
// 	- updated reqs are reqs that are part of both the old reqs and the new reqs.
// 		1. If only the args or required args are different, then the req will be preserved.
// 		2. If any other property other than args/required args are changed, then we will fallback to the old behaviour.
export function compareInstanceReqs<ReqType extends ModuleInstanceRequirement | SharedModuleInstanceRequirement>(
	prevReqs: ReqType[], currReqs: ReqType[], alwaysRecreate?: boolean,
) {
	// make a copy of the prev reqs as the initial removed reqs so we can remove un-removed reqs from here one by one
	const removedReqs = _.clone(prevReqs);
	const { newReqs, recreateReqs, preserveReqs } = _.groupBy(
		currReqs,
		(req) => {
			const matchingPrevReq = _.head(_.remove(removedReqs, (pr) => pr.name === req.name));
			if (matchingPrevReq) {
				if (!_.isEqual(matchingPrevReq, req)) {
					const propsPreserveChild = ["args", "requiredArgs", "impliedConnections"];
					const reqOmitted = _.omit(req, propsPreserveChild);
					const prevReqOmitted = _.omit(matchingPrevReq, propsPreserveChild);
					// recreateOnArgsChange is an escape for meta content developers to fall back to the old behavior
					return (_.isEqual(reqOmitted, prevReqOmitted) && !alwaysRecreate) ?
						"preserveReqs" :
						"recreateReqs";
				} else {
					return "unchangedReqs";
				}
			} else {
				return "newReqs";
			}
		},
	);
	return {
		removedReqs: [...removedReqs || [], ...recreateReqs || []],
		newReqs: [...newReqs || [], ...recreateReqs || []],
		updateReqs: preserveReqs || [],
	};
}
