import { PinmuxPinInterfaceInstanceMgr } from "./pinmuxPinInterfaceInstance";
import { OptimizablePinMgr } from "./optimizablePin";
import { InterfaceInstanceMgr } from "./interfaceInstance";
import { ModuleInstanceMgr } from "./moduleInstance";
import { MultiPinMgr } from "./multiPin";
import { ObjectMemberManager } from "./objectMember";
import { PinMgr } from "./pin";
import { PinInterfacePin, MultiPin, Pin } from "public/runtime";
import { Member } from "public/defs";
import { FormattersMap } from "../formatting/formattersMap";
import { decorate } from "../utils";
import { IPinsViewProvider } from "./pins";
import { NameToConfigurableHeader, createHeader } from "./header";
import { filterHiddenPinMembers } from "./funcs";
import { SetSource } from "./member";
import { Validations } from "./validations";

export class PinMemberMgr
	extends ObjectMemberManager
	<PinMgr, Pin, InterfaceInstanceMgr | PinmuxPinInterfaceInstanceMgr | MultiPinMgr> {

	constructor(
		valueObjectMgr: PinMgr,
		formattersMap: FormattersMap,
		def: Member,
		parentObjectMgr: InterfaceInstanceMgr | PinmuxPinInterfaceInstanceMgr | MultiPinMgr,
		private readonly decorateName = true,
	) {
		super(valueObjectMgr, formattersMap, def, parentObjectMgr);
	}

	public override getUIHash(validations: Validations) {

		// A pin member actually is a summary of multiple underlying other members
		// While the returned string will effectively cover all of them, we still need to check the validations of all 
		// of them

		if (validations.getValidation(this) ||
			validations.getValidation(this.valueObjectMgr.getOverrideMember()) ||
			validations.getValidation(this.valueObjectMgr.getConflictMember()) ||
			validations.getValidation(this.valueObjectMgr.getUsedMember())) {
			return null;
		}
		const obj = this.valueObjectMgr.managedObject;
		const pinValue = `${obj.$used}${obj.$assign}${obj.$solution?.devicePinName}`;
		const pinUIState = `${this.uiState.readOnly}${this.uiState.hidden}`;
		const pinLevelConfigurables = _.map(this.valueObjectMgr.metaContentConfigurableMgrs, (m) => m.getUIHash(validations)).join("");
		return `${pinValue}${pinUIState}${pinLevelConfigurables}`;
	}

	public override getDisplayName(displayScriptName: boolean) {
		if (this.decorateName) {
			return decorate(
				super.getDisplayName(displayScriptName),
				this.valueObjectMgr.getSolverRequirement().solution.assignedPeripheralPin);
		}
		return super.getDisplayName(displayScriptName);
	}
}

export class OptimizablePinMemberMgr extends ObjectMemberManager<OptimizablePinMgr, PinInterfacePin, ModuleInstanceMgr> {
	constructor(
		public override valueObjectMgr: OptimizablePinMgr,
		formattersMap: FormattersMap,
		def: Member,
		public override parentObjectMgr: ModuleInstanceMgr,
	) {
		super(valueObjectMgr, formattersMap, def, parentObjectMgr);
	}
}

export class PinGroupMemberMgr extends ObjectMemberManager<MultiPinMgr, MultiPin, InterfaceInstanceMgr> { }

// Same as PinMemberMgr, but manages the member on a module instance vs a interface instance

export class ExtendedPinMemberMgr
	extends ObjectMemberManager
	<PinMgr, Pin, ModuleInstanceMgr> implements IPinsViewProvider {
	private readonly pinConfigurableHeaders: NameToConfigurableHeader;
	private selectAll: boolean = true;

	constructor(
		valueObjectMgr: PinMgr,
		def: Member,
		parentObjectMgr: ModuleInstanceMgr,
		private readonly extendedInterfaceMgr: InterfaceInstanceMgr,
		formattersMap: FormattersMap) {
		super(valueObjectMgr, formattersMap, def, parentObjectMgr);

		// Associate pin requirement with peripheral requirement that is being extended

		const solverPinReq = valueObjectMgr.getSolverRequirement();
		extendedInterfaceMgr.getSolverRequirement().pinRequirements.push(solverPinReq);

		this.pinConfigurableHeaders
			= createHeader(
				_.flatMap(
					[
						...this.getVisiblePinMgrs(),
					],
					(p) => p.getNonBuiltInConfigurables(),
				),
			);
	}

	public getPinConfigurablesHeaders(): NameToConfigurableHeader {
		return this.pinConfigurableHeaders;
	}
	public getPinMemberMgrs() {
		return [this];
	}

	public getMultiPinMgr(): MultiPinMgr {
		return null;
	}

	public isSelectAllEnabled(): boolean {
		return this.selectAll;
	}

	public getVisiblePinMgrs(): PinMgr[] {
		return filterHiddenPinMembers(this.getPinMemberMgrs());
	}

	public setSelectAll(val: boolean): void {
		this.selectAll = val;
		this.valueObjectMgr.setUsed(val, SetSource.USER_ASSIGN);
	}

	public isReservation(): boolean {
		return false;
	}

	public getExtendedMgr() {
		return this.extendedInterfaceMgr;
	}

	protected override postRemove() {

		// Remove pin requirement associations
		const solverPinReq = this.valueObjectMgr.getSolverRequirement();
		_.pull(this.extendedInterfaceMgr.getSolverRequirement().pinRequirements, solverPinReq);

	}
}
