import * as _ from "lodash";
import * as Layout from "../../graph/types/layoutTypes";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";
import { ExtendedElkNode, ExtendedElkPort, ExtendedElkLine } from "./customTypes";
import { GraphType } from "./generateGraph";
import { Port } from "clockTree";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";

// Converts from the elk layout extended for clock tree, to the generic layout used by the graph UI components

let cache: Layout.Group<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>;
let layoutKey: ExtendedElkNode;
let instKey: ClockIpInstanceMgr;
export function toGenericLayout(layout: ExtendedElkNode, getIpInstanceMgr: (name: string) => ClockIpInstanceMgr) {

	// undo/redo can change what modules are loaded, but it won't change the layout (unless the device changes).  So we
	// need to check if the conversion we did before is still valid by checking if the looked up instance is the same

	if (layoutKey === layout && getIpInstanceMgr(_.first(cache.nodes).inst.getName()) === instKey) {
		return cache;
	}
	cache = toGenericGraph(layout, getIpInstanceMgr);
	layoutKey = layout;
	instKey = _.first(cache.nodes).inst;
	return cache;
}

function toGenericGraph(
	node: ExtendedElkNode, getIpInstanceMgr: (name: string) => ClockIpInstanceMgr
): Layout.Group<ClockIpInstanceMgr, PinFrequencyConfigurableMgr> {

	// elk declares some members as optional, but they are always present.  Casing with Required<> to ensure type

	const [nodes, groups] = _.partition(node.children, (c) => _.isEmpty(c.children));
	return {
		...node as Required<ExtendedElkNode>,
		edges: _.map(node.lines, (l) => toGenericEdge(l, getIpInstanceMgr)),
		nodes: _.map(nodes, (n) => toGenericNode(n, getIpInstanceMgr)),
		groups: _.map(groups, (g) => toGenericGraph(g, getIpInstanceMgr)),
		..._.pick(node.data.ipInstance, ["name", "displayName"]),
	};
}

function toGenericNode(
	node: ExtendedElkNode, getIpInstanceMgr: (name: string) => ClockIpInstanceMgr
): Layout.Node<ClockIpInstanceMgr, PinFrequencyConfigurableMgr> {

	// elk declares some members as optional, but they are always present.  Casing with Required<> to ensure type

	const inst = getIpInstanceMgr(node.data.ipInstance.name);
	return {
		..._.omit(node, "children") as Required<ExtendedElkNode>,
		inst,
		ports: _.map(node.ports, (p) => ({
			...p as Required<ExtendedElkPort>,
			memberMgr: inst.memberMgrs[p.data.pin.name] as PinFrequencyConfigurableMgr,
			type: _.some(node.data.ipInstance.inPins, (inPin) => inPin.name === p.data.pin.name) ? "input" : "output",
		})),
	};
}

function toGenericEdge(
	line: ExtendedElkLine, getIpInstanceMgr: (name: string) => ClockIpInstanceMgr
): Layout.Edge<PinFrequencyConfigurableMgr> {

	// All edges associated with this line should have the same source, so we can lookup just the first source		

	const source = getMemberMgr(_.first(line.data.edges).source, getIpInstanceMgr) as PinFrequencyConfigurableMgr;
	const targets = _.map(line.data.edges, (e) => getMemberMgr(e.target, getIpInstanceMgr)) as PinFrequencyConfigurableMgr[];
	return {
		id: `${line.start.x}_${line.start.y}_${line.end.x}_${line.end.y}`,
		...line,
		source,
		targets,
	};
}

function getMemberMgr(port: GraphType<Port>, getIpInstanceMgr: (name: string) => ClockIpInstanceMgr) {
	return getIpInstanceMgr(port.instName).memberMgrs[port.pinName];
}
