import { Walkable } from "./util";

/**
 * A node in grid. 
 * This class holds some basic information about a node and custom 
 * attributes may be added, depending on the algorithms' needs.
 * @constructor
 * @param {number} x - The x coordinate of the node on the grid.
 * @param {number} y - The y coordinate of the node on the grid.
 * @param {boolean} [walkable] - Whether this node is walkable.
 */
export class Node {

	public walkable = Walkable.Always;		// Whether this node can be walked through
	public parent?: Node; 					// How we got to this node.  Used by backtrace
	public costToReachNode?: number;		// How much it cost to get to this node from parent
	public estimatedCostToGoal?: number;	// The estimated cost to the goal based on some heuristic function (manhattan)
	public estimatedTotalCost?: number;		// costToReachNode + estimatedCostToGoal
	public opened?: boolean;				// If A* has reached this node and calculated the cost
	public closed?: boolean;				// If A* has processed this node and looked at all neighbours

	constructor(
		public x: number, 					// The x coordinate of the node on the grid.
		public y: number, 					// The y coordinate of the node on the grid.		
	) { }
}

export function backtrace(node: Node) {
	const path: [number, number][] = [[node.x, node.y]];
	while (node.parent) {
		node = node.parent;
		path.push([node.x, node.y]);
	}
	return path.reverse();
}
