import * as _ from "lodash";
import { IFormatter } from "../formatting/formattingTypes";
import { pinColors } from "../../components/styles/colors";
import { isFormattedLink } from "../formatting/link";
import { ILinkActions } from "../../components/actions/ILinkActions";
import { ATheme, ColorIndex } from "../../components/styles/themes";
import { getWindowHeight } from "../../components/ComponentUtils";
import { DevicePinSolutionMap, Pin as PinReq } from "../solver/requirements";
import * as data from "dataInterfaces";
import { PinInfo } from "../pinInfo";
import { assertUnreachable } from "../utils";
import {
	borderOffset,
	DEVICE_PIN_TO_PIN_TYPE,
	EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT,
	getPinColor,
	PinShape,
	PinType,
	PIN_ASSIGNED,
	PIN_FIXED,
	PIN_GROUND,
	PIN_NOT_AVAILABLE,
	PIN_POWER,
	PIN_RESERVED,
	PIN_SIZE,
	PIN_UNASSIGNED,
	PIN_WARNING,
	UIPin,
} from "./devicePinTypes";
import { Layer } from "konva/lib/Layer";
import { Rect } from "konva/lib/shapes/Rect";
import { Circle } from "konva/lib/shapes/Circle";
import { Text as KonvaText } from "konva/lib/shapes/Text";

const MINIMUM_WIDTH = 0;
const borderStrokeWidth = 1;

// NOTE: This class should really be a top-level abstract and then have classes qfp, bga, and custom inherit off it
// Since this is isolated we'll leave it as such. However, note that if you make changes to this class than you may also
// be affecting BGAPkg and CustomPkg. Also fyi QFP packages usually have pins sticking out on the edge of the chip
// see: https://www.ti.com/packaging/docs/searchtipackages.tsp?packageName=QFP

export class QFPPkg {
	public numColumns: number;
	public numRows: number;

	protected deviceData: data.AdaptedDeviceInfo;
	protected rowColumnInverted: boolean;

	protected pkgInfo: DeviceInfo.PackageDescription;

	protected pins: UIPin[] = [];
	protected extraTopLeft = (PIN_SIZE / 4) + EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT;
	protected extraBottomRight = 2 * EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT;

	// Device Dimensions
	protected width: number;
	protected height: number;
	protected extraXOffset: number;

	// Border position
	protected borderHeight: number;
	protected borderWidth: number;
	protected borderX: number;
	protected borderY: number;

	// We want to adjust the legend if the device is too small because we usually put the legend in the device itself
	protected adjustLegendIfNeccessary = true;

	private rotation: DeviceInfo.RotationType;

	constructor(
		public pinInfo: PinInfo,
		deviceData: data.AdaptedDeviceInfo,
		public devicePinSolutionMap: DevicePinSolutionMap,
		public selectedPins: Set<string>,
		public formatter: IFormatter,
		private readonly actions: ILinkActions,
		public theme: ATheme) {

		this.deviceData = deviceData;
		this.pkgInfo = deviceData.packageDescription;
		this.rowColumnInverted = deviceData.rowColumnInverted;
		this.rotation = deviceData.rotation ?? "BOTTOM_LEFT";

		// extra row and column needed , because the corner elements don't exist
		this.numColumns = this.pkgInfo.numColumns + 2;
		this.numRows = this.pkgInfo.numRows + 2;
		if (this.rotation === "TOP_LEFT" || this.rotation === "BOTTOM_RIGHT") {
			const temp = this.numColumns;
			this.numColumns = this.numRows;
			this.numRows = temp;
		}

		// calculate height and width of the device based on number of pins
		this.setDeviceDimensions();
	}

	public dimpleRadius() {
		return PIN_SIZE / 2;
	}

	public dimpleX() {
		if (this.rotation === "TOP_RIGHT" || this.rotation === "BOTTOM_RIGHT") {
			return this.width - PIN_SIZE * 3;
		}
		else {
			return PIN_SIZE * 3;
		}
	}

	public dimpleY() {
		if (this.rotation === "TOP_RIGHT" || this.rotation === "TOP_LEFT") {
			return PIN_SIZE * 3;

		}
		else {
			return this.height - (PIN_SIZE * 3);
		}

	}

	public addBorder(layer: Layer) {

		// Add border on the inside of pins
		const border = new Rect({
			x: this.borderX,
			y: this.borderY,
			width: this.borderWidth,
			height: this.borderHeight,
			stroke: this.theme.theme.palette.text.primary,
			strokeWidth: borderStrokeWidth,
			cornerRadius: 5,
		});

		layer.add(border);
	}

	public addDimple(layer: Layer) {
		// add the dimple
		const dimple = new Circle({
			radius: this.dimpleRadius(),
			stroke: this.theme.theme.palette.text.primary,
			strokeWidth: 2,
			x: this.dimpleX(),
			y: this.dimpleY(),
		});

		layer.add(dimple);
	}

	public addPins(layer: Layer) {
		for (let i = 0; i < this.numColumns; i++) {
			for (let k = 0; k < this.numRows; k++) {
				const pinX = (i * PIN_SIZE);
				const pinY = (k * PIN_SIZE);

				this.addCellContent(layer, pinX, pinY, k, i);
			}
		}
	}

	// Show tooltip and navigation for when pin is clicked
	public addPinActions(layer: Layer, shouldShowModeTable: boolean) {
		layer.on("mouseover", (obj) => {
			const shape = obj.target as PinShape;
			if (shape?.pin?.pinType) { // target is maybe a pin label on the edge?
				switch (shape.pin.pinType) {
					case PIN_WARNING:
					case PIN_ASSIGNED:
						document.body.style.cursor = "pointer";
						break;
					case PIN_UNASSIGNED:
					case PIN_RESERVED:
					case PIN_POWER:
					case PIN_GROUND:
					case PIN_FIXED:
					case PIN_NOT_AVAILABLE:
						break;
					default:
						assertUnreachable(shape.pin.pinType);
				}
				this.showPopUp(obj.target as PinShape, obj.evt.clientX, obj.evt.clientY, shouldShowModeTable);
			}
		});

		layer.on("mouseout", () => {
			document.body.style.cursor = "default";
			this.hidePopUp();
		});

		layer.on("click", (obj) => {
			const assignments = this.devicePinSolutionMap[(obj.target as PinShape).pin.pinName];
			if (!_.isEmpty(assignments)) {
				const link = _.first(this.formatter(_.first(assignments)).toParts());
				if (isFormattedLink(link)) {
					link.linkAction(this.actions);
				}
			}
		});
	}

	public getXPinOffSet(row: number, column: number) {
		if (row === 0 || row === (this.numRows - 1)) {
			return this.extraTopLeft;
		} else if (column === this.numColumns - 1) {
			return this.extraBottomRight + this.extraXOffset;
		}
		return 0;
	}

	public getYPinOffSet(row: number, column: number) {
		if (column === 0 || column === this.numColumns - 1) {
			return this.extraTopLeft;
		} else if (row === this.numRows - 1) {
			return this.extraBottomRight;
		}
		return 0;
	}

	public applyPinDecorations(pin: UIPin) {
		this.setPinType(pin);
		this.applyPinDecorationsToShape(pin);
	}

	public createLbl(x: number, y: number, row: number, column: number) {
		// base the calculation on the actual package information note the grid
		// package used for display
		const numPinsInColumn = this.numColumns - 2;
		const numPinsInRow = this.numRows - 2;

		const lbl = new KonvaText({
			x,
			y,
			text: "",
			fontSize: PIN_SIZE,
			fill: this.theme.theme.palette.text.primary,
			rotation: 0,
		});

		const pinWidthOffSet = (PIN_SIZE) + (lbl.width()) + 2;
		const pinHeightOffSet = (PIN_SIZE) + (lbl.width()) + 2;

		let pinNumber: number;

		if (row === this.numRows - 1) { // bottom 
			pinNumber = this.lblBottom(column, numPinsInColumn, numPinsInRow);
			lbl.text(this.lblText(pinNumber));
			lbl.x(lbl.x());
			lbl.y(lbl.y() - pinHeightOffSet + 3);
			lbl.rotation(-90);
		} else if (column === this.numColumns - 1) { // right
			pinNumber = this.lblRight(row, numPinsInColumn, numPinsInRow);
			lbl.text(this.lblText(pinNumber));
			lbl.y(lbl.y());
			// const offSetPadding = isNaN(parseInt(this.lblText(pinNumber), 10)) ? 14 : 4; // arbitrary based on eyeballing
			lbl.x(lbl.x() - pinWidthOffSet - 4);
		} else if (row === 0) { // top
			pinNumber = this.lblTop(column, numPinsInColumn, numPinsInRow);
			lbl.text(this.lblText(pinNumber));
			lbl.x(lbl.x());
			lbl.y(lbl.y() + pinHeightOffSet + PIN_SIZE);
			lbl.rotation(-90);
		} else if (column === 0) { // left
			pinNumber = this.lblLeft(row, numPinsInColumn, numPinsInRow);
			lbl.text(this.lblText(pinNumber));
			lbl.y(lbl.y());
			lbl.x(lbl.x() + pinWidthOffSet);

		} else {
			throw new Error("Unable to map pin name");
		}

		return lbl;
	}

	public addCellContent(layer: Layer, pinX: number, pinY: number, row: number, column: number) {

		if (this.isValidRowCol(row, column)) {

			let pinWidth = PIN_SIZE;
			let pinHeight = PIN_SIZE / 2;

			// rotate the top and bottom pins
			if (row === 0 || row === this.numRows - 1) {
				const temp = pinWidth;
				pinWidth = pinHeight;
				pinHeight = temp;
			}

			pinX += this.getXPinOffSet(row, column);
			pinY += this.getYPinOffSet(row, column);

			const lbl = this.createLbl(pinX, pinY, row, column);

			const shape: PinShape = new Rect({
				x: pinX,
				y: pinY,
				width: pinWidth,
				height: pinHeight,
				fill: "grey",
			});

			const pin: UIPin = {
				shape,
				pinName: lbl.text(),
				pinType: null,
			};

			shape.pin = pin;

			this.applyPinDecorations(pin);

			layer.add(pin.shape);
			layer.add(lbl);
			this.pins.push(pin);
		}
	}

	public redraw(strokeColor: string) {
		_.each(this.pins, (pin) => {
			// if it is not just a label pin
			if (pin.shape) {
				if (this.setPinType(pin)) {
					// smooth out edges in light/dark mode
					pin.shape.stroke(strokeColor);
					pin.shape.draw();
					this.applyPinDecorationsToShape(pin);
					pin.shape.draw();
				}
			}
		});
	}

	public getStageDimensions() {
		return { width: this.width + borderOffset, height: this.height + borderOffset };
	}

	protected setDeviceDimensions() {
		this.width = PIN_SIZE * (this.numColumns) + (2 * EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT);
		this.extraXOffset = (this.width > MINIMUM_WIDTH) ? 0 : MINIMUM_WIDTH - this.width;
		this.height = PIN_SIZE * (this.numRows) + (2 * EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT);
		this.setupBorderDimensions();
	}

	protected setupBorderDimensions() {
		// calculate border dimensions and styling here since it will be used for additional logic else where
		// i.e. where to add the legend and pins
		this.borderX = PIN_SIZE + borderStrokeWidth;
		this.borderY = PIN_SIZE + borderStrokeWidth;
		this.borderWidth = this.width - (2 * PIN_SIZE) - (2 * borderStrokeWidth);
		this.borderHeight = this.height - (2 * PIN_SIZE) - (2 * borderStrokeWidth);
	}

	private isValidRowCol(row: number, column: number) {
		return ((row === 0 || row === this.numRows - 1) && column > 0 && column < this.numColumns - 1) ||
			((column === 0 || column === this.numColumns - 1) && row > 0 && row < this.numRows - 1);
	}

	private createPopUpDetails(pin: UIPin, shouldShowModeTable: boolean) {

		const pinName = pin.pinName;
		const devicePin = this.deviceData.devicePins[pinName];
		if (!devicePin) {
			return null;
		}
		const tooltipInfo = this.pinInfo.getTooltip(shouldShowModeTable, devicePin);

		const rows = _.map(tooltipInfo, (rowInfo) => {
			let style = "white-space:nowrap;vertical-align:top";
			if (rowInfo.success) {
				style += ";color:#49b653";
			} else if (rowInfo.title) {
				style += ";text-decoration:underline";
			}

			const col2 = _.map(rowInfo.col2, (curCol2Content) => {
				if (rowInfo.col2.length > 1) {
					return `<span>${curCol2Content}<br/></span>`;
				} else {
					return curCol2Content;
				}
			}).join("");

			return `<tr style='${style}'> <td> ${rowInfo.col1} </td> <td> ${col2} </td> <tr>`;
		});

		return `<table> ${rows.join(" ")} </table>`;
	}

	private showPopUp(shape: PinShape, x: number, y: number, shouldShowModeTable: boolean) {

		const popUp = document.getElementById("pinDetails");

		if (shape.pin) {
			// get the document height
			const currentDocHeight = getWindowHeight();
			const html = this.createPopUpDetails(shape.pin, shouldShowModeTable);
			if (html) {
				popUp.innerHTML = html;
				popUp.style.display = "block";
				popUp.style.position = "fixed";

				// give it 30 px extra padding, so it"s not quite hugging the bottom
				const yOverFlow = (y + popUp.clientHeight + 30) - currentDocHeight;
				y = (yOverFlow > 0) ? (y - yOverFlow) : y;

				popUp.style.top = y + "px";
				// move the tooltip a bit away from the pin itself to prevent it blocks the pin
				popUp.style.left = (x - popUp.clientWidth - 10) + "px";
			}
		}
	}

	private setPinType(pin: UIPin) {

		const pinName = pin.pinName;
		const devicePin = this.deviceData.devicePins[pinName];
		const assignments = this.devicePinSolutionMap[pinName];

		let changed = false;
		let pinType: PinType = PIN_NOT_AVAILABLE;
		let currentlySelected = false;

		if (devicePin) {
			pinType = DEVICE_PIN_TO_PIN_TYPE[devicePin.devicePinType];

			if (assignments) {
				if (this.isCurrentlySelected(assignments)) {
					currentlySelected = true;
				}
				pinType = PIN_ASSIGNED;
				if (_.some(assignments, (assignment) => assignment.solution.warningDetailsText.length > 0)) {
					pinType = PIN_WARNING;
				} else if (_.every(assignments, (assignment) => assignment.reserved)) {
					pinType = PIN_RESERVED;
				}
			}
		}

		changed = (pin.currentlySelected !== currentlySelected) ||
			pin.pinType !== pinType;
		pin.currentlySelected = currentlySelected;
		pin.pinType = pinType;

		return changed;
	}

	private isCurrentlySelected(assignments: PinReq[]) {
		return _.some(assignments, (assignment) =>
			this.selectedPins.has(assignment.solution.assignedToName));
	}

	private applyPinDecorationsToShape(pin: UIPin) {
		if (pin.shape) {
			let fill;
			let stroke;
			const strokeWidth = 2;

			fill = stroke = getPinColor(pin.pinType, this.deviceData.showExtendedPinTypes);

			if (pin.currentlySelected) {
				stroke = this.theme.colors[ColorIndex.SELECTEDPINSTROKECOLOR];
				fill = (pin.pinType === PIN_WARNING) ?
					pinColors.highlightedShared : pinColors.highlightedUsed;
			}

			pin.shape.fill(fill);
			pin.shape.stroke(stroke);
			pin.shape.strokeWidth(strokeWidth);
		}
	}

	private hidePopUp() {
		const popUp = document.getElementById("pinDetails");
		popUp.style.display = "none";
	}

	private lblBottom(column: number, numPinsInColumn: number, numPinsInRow: number) {
		switch (this.rotation) {
			case "TOP_LEFT":
				return numPinsInRow + column;
				break;
			case "TOP_RIGHT":
				return numPinsInColumn + numPinsInRow + column;
				break;
			case "BOTTOM_RIGHT":
				return numPinsInColumn + (2 * numPinsInRow) + column;
				break;
			case "BOTTOM_LEFT":
				return column;
				break;
			default:
				assertUnreachable(this.rotation);
				break;
		}
	}

	private lblRight(row: number, numPinsInColumn: number, numPinsInRow: number) {
		switch (this.rotation) {
			case "TOP_LEFT":
				return numPinsInRow + numPinsInColumn + (this.numRows - row - 1);
				break;
			case "TOP_RIGHT":
				return (numPinsInColumn * 2) + numPinsInRow + (this.numRows - row - 1);
				break;
			case "BOTTOM_RIGHT":
				return (this.numRows - row - 1);
				break;
			case "BOTTOM_LEFT":
				return numPinsInColumn + (this.numRows - row - 1);
			default:
				assertUnreachable(this.rotation);
				break;
		}
	}

	private lblLeft(row: number, numPinsInColumn: number, numPinsInRow: number) {
		switch (this.rotation) {
			case "TOP_LEFT":
				return row;
				break;
			case "TOP_RIGHT":
				return numPinsInColumn + row;
				break;
			case "BOTTOM_RIGHT":
				return numPinsInColumn + numPinsInRow + row;
				break;
			case "BOTTOM_LEFT":
				return (numPinsInColumn * 2) + numPinsInRow + row;
			default:
				assertUnreachable(this.rotation);
				break;
		}
	}

	private lblTop(column: number, numPinsInColumn: number, numPinsInRow: number) {
		switch (this.rotation) {
			case "TOP_LEFT":
				return numPinsInColumn + (2 * numPinsInRow) + (this.numColumns - column - 1);
				break;
			case "TOP_RIGHT":
				return (this.numColumns - column - 1);
				break;
			case "BOTTOM_RIGHT":
				return numPinsInRow + (this.numColumns - column - 1);
				break;
			case "BOTTOM_LEFT":
				return numPinsInColumn + numPinsInRow + (this.numColumns - column - 1);
			default:
				assertUnreachable(this.rotation);
				break;
		}
	}

	private lblText(pinNumber: number) {
		return pinNumber.toString();
	}
}
