import * as _ from "lodash";
import * as path from "path";
import { isCCS, isEmbedded, isNodeWebkit, isNodejs, isCloud } from "./platform";
import { syncFetch } from "./syncFetch";

// In the UI case, SysConfig is loaded using a script tag in the html.  At load time, this script can be accessed using
// document.currentScript and the url root path extracted.  That allows us to know where SysConfig was loaded from on 
// the web (usually /sysconfig, but not always). 

const scriptRoot = (() => {
	if (isNodejs()) {
		return "/";
	} else if (isEmbedded()) {
		return path.dirname(document.currentScript.getAttribute("src")) + "/";
	} else {
		return _.replace(window.location.pathname, /index.html/, "");
	}
})();
export function httpRootDir() {
	return scriptRoot;
}

// The root directory is the full path on the file system to the folder containing our js files.  This folder is only
// available on the desktop, and is fetched in various ways depending on the browser/environment.  We calculate it once
// to avoid multiple fetches, but return it using a function to allow spying during testing.

const physicalDistDir = (() => {
	if (isCloud()) {
		return null;
	} else if (isCCS()) {
		return window.eclipseEnv.SYSCONFIG_TOOL_ROOT;
	} else if (isEmbedded()) {
		return syncFetch(httpRootDir() + "getPath");
	} else if (isNodeWebkit()) {
		return path.dirname(nw.__filename);
	} else if (!_.endsWith(__dirname, "dist")		// stand-alone, backend or run from git
		&& !_.endsWith(__dirname, "sysconfig")) {	// CCS desktop install
		return path.normalize(__dirname + "/../dist");
	} else {
		return __dirname;
	}
})();

export function rootDir() {
	if (!isCloud()) {
		return physicalDistDir;
	}
	throw new Error("Cannot access rootDir in a cloud environment");
}

export function deviceDataDir() {
	return rootDir() + "/deviceData";
}
