import * as _ from "lodash";
import { SelectionInConfigStore } from "../components/actions/selection";

// This class manages the navigation history of the config store.
// It is implemented on top of the built in browser history (back/forward).
// It tracks the user selections in a stack, similar to the browser. As the
// user moves back and forward the selections are reterieved and restored.  
export class NavigationHistory {

	// Stack to track user selections 
	private enteries: Entry[] = [];
	// Current point in the history	
	private currentIndex = -1;

	public constructor(
		private readonly navigate: (selection: SelectionInConfigStore) => void) {
	}

	public record(selection: SelectionInConfigStore) {

		if (!this.historyIsDefined()) {
			return;
		}

		const state: BrowserHistoryState = { index: ++this.currentIndex, type: "SysCfg" };
		history.pushState(state, "");

		// mimic browser history and pop additional enteries off the stack
		// to start a new path

		this.enteries = _.slice(this.enteries, 0, this.currentIndex);
		const entry: Entry = { selection, skip: false };
		this.enteries.push(entry);

		// mark entry skipped, if it was a preview entry
		// and now an extra instance has been added

		const last = this.enteries[this.currentIndex - 1];
		if (last) {
			const wasPreview = !last.selection.instanceId;
			if (wasPreview) {
				if (last.selection.tabName === entry.selection.tabName
					&& _.isEqual(last.selection.treeNodePath, entry.selection.treeNodePath)) {
					last.skip = true;
				}
			}
		}
	}

	public canMoveForward() {
		return this.nextValidIndex(false) < (this.enteries.length);
	}

	public canMoveBack() {
		return this.nextValidIndex(true) > -1;
	}

	public handleBrowserEvent(e: PopStateEvent) {
		const newState = e.state;
		if (isSysConfigHistoryState(newState)) {
			const entry = this.enteries[newState.index];
			const isBack = this.currentIndex > newState.index;
			this.currentIndex = newState.index;
			if (!entry.skip) {
				this.navigate(entry.selection);
			} else if (isBack) {
				if (this.canMoveBack()) {
					history.back();
				}
			} else {
				if (this.canMoveForward()) {
					history.forward();
				}
			}
		}
	}

	public back() {
		history.back();
	}

	public forward() {
		history.forward();
	}

	private historyIsDefined() { // history is not defined in CLI/SysCfg tests
		return typeof history !== "undefined";
	}

	// find the next valid index
	private nextValidIndex(inBackDirection: boolean) {
		const incr = inBackDirection ? -1 : + 1;
		let next = this.currentIndex + incr;
		while (next > -1 && next < this.enteries.length && this.enteries[next].skip) {
			next = next + incr;
		}
		return next;
	}
}

function isSysConfigHistoryState(state: any): state is BrowserHistoryState {
	return state && (state as BrowserHistoryState).type === "SysCfg";
}

// State tracked in the browser history
interface BrowserHistoryState {
	type: "SysCfg";
	index: number; // Index into internally tracked history enteries
}

interface Entry {
	selection: SelectionInConfigStore;
	skip: boolean; // Entry could be skipped because it is no longer relavent
}
