import * as _ from "lodash";
import React = require("react");
import { PinRequirements } from "./PinRequirements";
import { Table, TableBody } from "../../imports/material-ui-imports";
import { InterfaceInstanceMgr } from "../../services/objectManagers/interfaceInstance";
import { CConfigurable } from "./configurables/Configurable";
import { ConfigTableRow, MemberRow } from "./MemberRow";
import { PeripheralSelection } from "./PeripheralSelection";
import { UseCaseSelection } from "./UseCaseSelection";
import { PeripheralOverrideMgr, VoltageMgr } from "../../services/objectManagers/interfaceInstanceMembers";
import { VoltageSelection } from "./VoltageSelection";
import { UseCaseMgr } from "../../services/objectManagers/usecase";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { ConfigStoreActions } from "../../services/configStore";
import { InputBox } from "../InputBox";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ResourceLoader } from "../../services/resources/metaContentLoaders/resourceLoader";
import { MetaContentConfigurableMgr } from "../../services/objectManagers/configurables/configurable";
import { CValidation } from "./Validation";
import { ioSetTooltip } from "../../services/utils";
import { ConflictControl } from "../ConflictControl";
import { OverrideMgr } from "../../services/objectManagers/assignMembers";
import { Validations } from "../../services/objectManagers/validations";
import { PinDisplayType } from "../../services/userPreferences";

// React shared props
interface IInterfaceInstanceProps extends IGlobalServiceProps {
	instMgr: InterfaceInstanceMgr;
	actions: ConfigStoreActions;
	arePowerDomainSettingsEnabled: boolean;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	focusedSubItemPath: string[];
}

export class CInterfaceInstance
	extends React.Component<IInterfaceInstanceProps & IGlobalServiceProps, {}> {
	public override render() {

		const instMgr = this.props.instMgr;
		const formatter = this.props.formatter;
		const highlightedMember = _.size(this.props.focusedSubItemPath) === 1 ? _.first(this.props.focusedSubItemPath) : "";

		return (
			<React.Fragment>
				<CValidation
					validatableObj={instMgr}
					validations={this.props.validations}
					formatter={formatter}
					actions={this.props.actions}
					conflictControl={
						<ConflictControl
							req={instMgr}
							formatter={this.props.formatter}
							actions={this.props.actions}
						/>
					}
				/>
				<Table>
					<TableBody key="tablebody">
						{
							_.map(instMgr.getNonPinMembersInScriptOrder(), (m) => (
								<MemberRow
									{...this.props}
									memberMgr={m}
									key={m.def.name}
									highlight={highlightedMember === m.def.name}
									hideValidation={m instanceof OverrideMgr} // CNonPinMember will show validation for $assign
								>
									<CNonPinMember
										{...this.props}
										key={m.def.name}
										mgr={m}
										formatter={formatter} />
								</MemberRow>
							))
						}
						{instMgr.hasIOSet() &&
							<ConfigTableRow
								{...this.props}
								label="IO Set"
								labelToolTip={ioSetTooltip}
								valueToolTip={ioSetTooltip}
							>
								<InputBox
									type="text"
									id={"ioset"}
									disabled={true}
									value={instMgr.getSolverRequirement().solution.ioSet || ""}
									onChange={() => { }}
								/>
							</ConfigTableRow>
						}
					</TableBody>
				</Table>
				<div id="interfacePinTable">
					<Table id="requirementsTable">
						<TableBody>
							<PinRequirements
								{...this.props}
								pinsProvider={instMgr}
								showUsed={true}
								keyPrefix={instMgr.getSolverRequirement().id}
								highlightedMember={highlightedMember}
								showPinTable={true}
							/>
						</TableBody>
					</Table>
				</div>
			</React.Fragment>
		);
	}
}

class CNonPinMember
	extends React.Component<
	{
		mgr: PeripheralOverrideMgr | VoltageMgr | UseCaseMgr | MetaContentConfigurableMgr,
		actions: ConfigStoreActions,
		arePowerDomainSettingsEnabled: boolean,
		formatter: IFormatter;
		validations: Validations;
		resourceLoader: ResourceLoader;
	} & IGlobalServiceProps, {}> {
	public override render() {

		const { mgr, actions, formatter, validations } = this.props;

		if (mgr instanceof PeripheralOverrideMgr) {
			return (
				<PeripheralSelection
					instMgr={mgr.parentObjectMgr}
					formatter={formatter}
					validations={validations}
					onChange={(selected) => actions.setSelectedPeripheral(mgr.parentObjectMgr, selected)}
					actions={actions}
				/>
			);
		} else if (mgr instanceof VoltageMgr) {
			return (
				<VoltageSelection
					instMgr={mgr.parentObjectMgr}
					onChange={(val) => actions.setSelectedVoltage(mgr.parentObjectMgr, val)}
					arePowerDomainSettingsEnabled={this.props.arePowerDomainSettingsEnabled}
					formatter={formatter}
					actions={actions}
				/>
			);
		} else if (mgr instanceof UseCaseMgr) {
			return (
				<UseCaseSelection
					instMgr={mgr.parentObjectMgr}
					onChange={(val) => actions.setSelectedUseCase(mgr.parentObjectMgr, val)}
				/>
			);
		} else {
			// default render as configurable
			return (
				<CConfigurable {...this.props} displayScriptName={false} />
			);
		}

	}
}
