import * as _ from "lodash";
import { GraphSettings } from "../../../services/instanceContainers/clockTreeNode";
import { elkNodeLayoutOptions, elkRootLayoutOptions } from "../../graph/autoLayout/elkLayout";
import { GraphGroup, IPInstanceNode } from "./generateGraph";

const customLayoutOptions = {
	// crossingMinimization settings cause the layout algorithm to consider elk.position information in 
	// layoutOptions when trying to place nodes within a layer (ie vertical position)
	// See https://rtsys.informatik.uni-kiel.de/elklive/examples.html?e=user-hints%2Flayered%2FverticalOrder
	"elk.layered.crossingMinimization.strategy": "LAYER_SWEEP",
	"elk.layered.crossingMinimization.semiInteractive": "true",

	// Setting strategy for cycleBreaking and layering to INTERACTIVE will cause the layout algorithm to consider 
	// the x coordinate on the node/group elements in order to determine which layer (ie horizontal position) a 
	// node/group is placed in.  If this is set when there is no layout information, the layout will appear to be
	// random.  SemiInteractive mode can be used to consider layer information only when provided, but that mode 
	// does not work inside groups unless we want to process groups entirely on their own.  
	// See https://rtsys.informatik.uni-kiel.de/elklive/examples.html?e=user-hints%2Flayered%2FhorizontalOrder
	"elk.layered.cycleBreaking.strategy": "INTERACTIVE",
	"elk.layered.layering.strategy": "INTERACTIVE",
};

const enum Position {
	LEFT = "1",
	MIDDLE = "2",
	RIGHT = "3",
}

function getRelativePosition(node: IPInstanceNode | GraphGroup) {
	if ("ipInstances" in node) {
		// Group
		return Position.MIDDLE;
	} else {
		if (node.shape === "PinFunction") {
			return "inPins" in node && !_.isEmpty(node.inPins) ? Position.RIGHT : Position.LEFT;
		}
		return Position.MIDDLE;
	}
}

export function getNodeLayoutOptions(node: IPInstanceNode | GraphGroup, { layout: customLayout }: GraphSettings) {
	const layout = customLayout[node.id];
	if (!layout) {

		return {
			...elkNodeLayoutOptions,
			"elk.partitioning.partition": getRelativePosition(node),
		};
	}
	return {
		...elkNodeLayoutOptions,

		// elk.position is an x,y coordinate, but only the y coordinate is considered by
		// crossingMinimization.semiInteractive, so the x is always zero
		"elk.position": `0,${customLayout[node.id].position}`,
	};
}

const rootOptions = {
	...elkRootLayoutOptions,

	// This indicates that if a node has a children nodes (ie, the node is a group) we need to consider those 
	// nodes during the layout process.  The alternative would be to run every sub-group through it's own 
	// layout algorithm, but we have connections between nodes inside and outside of groups.
	"elk.hierarchyHandling": "INCLUDE_CHILDREN",

	// The spacing to be preserved between nodes and edges that are routed next to the node’s layer.
	// For the spacing between nodes and edges that cross the node’s layer ‘spacing.edgeNode’ is used.
	// see https://www.eclipse.org/elk/reference/options/org-eclipse-elk-layered-spacing-edgeNodeBetweenLayers.html
	"elk.layered.spacing.edgeNodeBetweenLayers": "20",
};

function getRootSpecificOptions(settings: GraphSettings) {
	return !_.isEmpty(settings.layout) ? rootOptions : {
		...rootOptions,
		"elk.partitioning.activate": "true",
	};
}

export function getGroupLayoutOptions(group: GraphGroup, settings: GraphSettings) {

	return {
		...getNodeLayoutOptions(group, settings),
		..._.isEmpty(settings.layout) ? {} : customLayoutOptions,
		...("root" === group.name) ? getRootSpecificOptions(settings) : {},
	};
}

export function getPosition(node: { id: string }, { layout: customLayout }: GraphSettings) {
	const layout = customLayout[node.id];
	if (!layout) {
		return {};
	}

	// Setting strategy for cycleBreaking and layering to INTERACTIVE will cause the layout algorithm to consider 
	// the x coordinate on the node/group elements in order to determine which layer (ie horizontal position) a 
	// node/group is placed in.  If this is set when there is no layout information, the layout will appear to be
	// random.  SemiInteractive mode can be used to consider layer information only when provided, but that mode 
	// does not work inside groups unless we want to process groups entirely on their own.  
	// Note that it considers x as an x,y coordinate, so a given x must differ from another x by the node size.  As 
	// such, we multiply x by 200 to ensure that

	return {
		x: layout.layer * 200,
	};
}
