import { ProductFile, Product, BoardInfo, AvailableProductsAndTargets } from "./types";
import * as _ from "lodash";
import { RawResourceLoader } from "../resources/metaContentLoaders/resourceLoader";
import { getBoardFiles } from "../boardSupport/boardUtils";
import { DiscoveryJSON, DeviceDescription } from "dataInterfaces";
import { isDataLessDevice, isImageOnlyDevice } from "../builtInDevices";

type SupportedDeviceProductFile = Pick<ProductFile, "devices">;

type SupportedBoardAndDeviceProductFile = Pick<AvailableProductsAndTargets, "devices" | "boards">;
export function deviceAppliesToAllProducts(productFiles: SupportedDeviceProductFile[], deviceName: string) {
	// in every product we should match some of the filters
	return (
		_.every(productFiles,
			(p) => {
				const regexs = _.map(p.devices, (pattern) => new RegExp(pattern));
				return _.some(regexs, (r) => r.test(deviceName));
			})
	);
}

export function getBoardOptions(products: Product[], discoveryData: DiscoveryJSON) {
	const productFiles = _.map(products, (p) => p.file);
	const loader = new RawResourceLoader(products);
	return _.filter(getBoardFiles(loader, discoveryData, products), ({ boardDef }) => {
		return deviceAppliesToAllProducts(productFiles, boardDef.device);
	});
}

export function filterStartPageDeviceOptions(
	deviceData: DiscoveryJSON,
	selectedProduct: SupportedBoardAndDeviceProductFile,
	isImageMode: boolean,
	selectedBoard?: string,
) {
	if (!selectedProduct) {
		// doesn't make sense to show device that don't have pinmux data
		return _.filter(deviceData.devices, (d) => !isDataLessDevice(d.name));
	} else {
		const filteredDevices = _.chain(deviceData.devices)
			.filter((d) => !isImageOnlyDevice(d.name) || isImageMode) // filter out image only devices in non image mode
			.filter((d) => deviceAppliesToAllProducts([selectedProduct], d.name))
			.value();

		return filterDevicesForBoard(selectedBoard, selectedProduct.boards, filteredDevices);
	}
}

function filterDevicesForBoard(selectedBoard: string, boards: BoardInfo[], filteredDevices: DeviceDescription[]) {

	if (selectedBoard) {
		const validBoard = _.find(boards, (b) => b.name === selectedBoard);
		const mainDevice = validBoard ? validBoard.device : null;
		const emulatedDevices = validBoard ? validBoard.emulated : [];

		return _.chain(filteredDevices)
			.filter((d) => _.some(emulatedDevices, (b) => b.device === d.name) || mainDevice === d.name)
			.map((d) => {
				if (_.some(emulatedDevices, (b) => b.device === d.name)) {
					return _.extend(d, { displayName: d.name + " (emulated)" });
				}
				return d;
			})
			.value();
	}
	return filteredDevices;
}
