import * as React from "react";
import { Box, CircularProgress, Grid, Typography } from "../imports/material-ui-imports";

// adapted from MUI docs: https://github.com/mui/material-ui/blob/v5.14.5/docs/data/material/components/progress/CircularWithValueLabel.tsx 

export function CircularProgressWithLabel(
	{ id, title, value }: { id: string, title: string, value: number },
) {
	return (
		<div style={{ margin: "auto" }}>
			<Grid container direction="column" alignItems='center' justify='center' spacing={5}>
				<Grid item xs>
					<Typography variant="subtitle1">{title}</Typography>
				</Grid>
				<Grid item xs>
					<CircularProgress id={id} variant={value === undefined ? "indeterminate" : "determinate"} value={value} size={100} />
					{typeof (value) === "number" &&
						<Box
							top={-60}
							left={3}
							bottom={0}
							right={0}
							position='relative'
							display='flex'
							alignItems='center'
							justifyContent='center'
						>
							<Typography
								variant="subtitle2"
								component="div"
							>{`${Math.min(100, Math.round(value))}%`}</Typography>
						</Box>
					}
				</Grid>
			</Grid>
		</div>
	);
}
