module.exports = "// !!NOTE!!: this file is used as a template\nfunction setupDirs(filePath) {\n\tconst dirs = filePath.split(\"/\");\n\tdirs.pop();\n\n\tlet path = \"\";\n\tdirs.forEach((folder) => {\n\t\t// If path starts with \"/\", first folder is empty string\n\t\tif (folder != \"\") {\n\t\t\tpath += \"/\" + folder;\n\t\t\ttry {\n\t\t\t\tFS.stat(path);\n\t\t\t} catch {\n\t\t\t\tFS.mkdir(path);\n\t\t\t}\n\t\t}\n\t});\n}\n\nModule = {\n\targuments: [\"-b\", \"sim.cir\"],\n\n\tpreRun: [\n\t\t(pr = async () => {\n\t\t\t// run dependencies need to be resolved before main function can be started\n\t\t\t// This is useful for making sure the async code below runs before main\n\t\t\taddRunDependency(\"states\");\n\t\t\t// https://emscripten.org/docs/api_reference/Filesystem-API.html#filesystem-api\n\t\t\tFS.writeFile(\"/sim.cir\", `initialData`);\n\t\t\tconst files = [`stateFiles.map((path) => '\"'+ path +'\"').join(',')`];\n\t\t\tconst promises = files.map(async (file) => {\n\t\t\t\tconst resp = self.oldFetch(\"`baseURI`\" + file);\n\t\t\t\tsetupDirs(file);\n\t\t\t\tconst fileData = (await resp).text();\n\t\t\t\tFS.writeFile(file, await fileData);\n\t\t\t});\n\t\t\tfor (i = 0; i < promises.length; i++) {\n\t\t\t\tawait promises[i];\n\t\t\t}\n\t\t\tremoveRunDependency(\"states\");\n\t\t}),\n\t],\n\tpostRun: [\n\t\t(ps = () => {\n\t\t\ttry {\n\t\t\t\tconst simulation = FS.readFile(\"`comFile`\", { encoding: \"utf8\" });\n\t\t\t\tpostMessage({\n\t\t\t\t\tstatus: \"finished\",\n\t\t\t\t\tdata: simulation\n\t\t\t\t});\n\t\t\t} catch (e) {\n\t\t\t\tpostMessage({\n\t\t\t\t\tstatus: \"finished\",\n\t\t\t\t\tdata: \"\"\n\t\t\t\t});\n\t\t\t}\n\t\t}),\n\t],\n\tprint: (function () {\n\t\treturn function (text) {\n\t\t\tpostMessage(text + \"\\n\");\n\t\t};\n\t})(),\n\tprintErr: (function () {\n\t\treturn function (text) {\n\t\t\tpostMessage(text + \"\\n\");\n\t\t};\n\t})(),\n}; //end of Module\n\nself.oldFetch = fetch;\nfetch = (...args) => {\n\targs[0] = \"`baseURI`\" + \"/ngspice/\" + args[0];\n\treturn self.oldFetch(...args);\n};\n"