import React = require("react");
import { Button } from "../../imports/material-ui-imports";
import { IButtonProps } from "./IButtonProps";
import { ColorIndex } from "../styles/themes";
import { commonStyles } from "../styles/common";

export function SecondaryButton(
	{ theme, disabled, onClick, children, id }: React.PropsWithChildren<Omit<IButtonProps, "style">> & Required<Pick<IButtonProps, "theme">>
) {
	const buttonStyle = React.useMemo(() => ({
		backgroundColor: theme.colors[ColorIndex.BUTTONBACKGROUNDCOLOR],
		whiteSpace: "nowrap" as const,
		...commonStyles.button,
		marginBottom: theme.theme.spacing(2),
	}), [theme]);

	return (
		<Button
			component="span"
			color="primary"
			variant="outlined"
			className={disabled ? " disabled-button" : ""}
			disabled={disabled}
			onClick={onClick}
			id={id}
			style={buttonStyle}
			size="small"
		>
			{children}
		</Button>
	);
}
