import * as _ from "lodash";
import { MinimizeResources, SharedChoices } from "./minimizeResources";
import { PeripheralChoices } from "./peripheral";
import { IChoice } from "./common";

// A factory for creating implications in order to minimize choices that restrict optimizable pin choices.
// This allows the pin optimization to succeed even in the presence of shared pins.

export class MinimizePeripherals extends MinimizeResources {

	constructor(private readonly peripheralChoices: PeripheralChoices) {
		super("Minimize Peripherals");
	}

	// Find all the shareable choices and group them by:
	// 1) those that can be shared together
	// 2) the requirements
	// 3) the choice of assignment for each requirement

	protected getSharedChoices() {

		// First, construct the SharedChoices map as described above

		const sharedPeripherals: SharedChoices = {};
		_.each(this.peripheralChoices.sharedChoices, (choices, sharedHash) => {
			_.each(choices, (choice) => {
				const requirementId = choice.getRequirementId();
				_.set(sharedPeripherals, [sharedHash, requirementId, choice.peripheral.name], choice);
			});
		});

		// Filter out entries where merging wouldn't free up resources us.  For instance, if there are 3 peripheral 
		// choices, and we find at least one requirement that is locked to each choice, there's no sense creating 
		// potentially complex SAT clauses to reduce it as every peripheral will be used.  

		// This is mostly being done to support cases where the GPIO is not described using an optimized method, but 
		// the meta-content is exposing it as if it does.  That will obviously lead to out of memory conditions, but
		// if we tell customers to lock down pins as they pick them, they can at least continue working.  However, even
		// if they apply that workaround, this code would still end up create huge numbers of clauses that obviously 
		// can't improve things, but take a long time to solve anyway.

		return _.omitBy(sharedPeripherals, (reqsToChoices) => {

			// For each requirement id, if there is only one choice for it, then it is effectively locked to that 
			// choice

			const unlockedPerfChoices: string[] = [];
			const lockedPerfChoices: string[] = [];
			_.each(reqsToChoices, (perfsToChoices) => {
				const perfChoices = _.keys(perfsToChoices);
				if (_.size(perfChoices) > 1) {
					unlockedPerfChoices.push(...perfChoices);
				} else {
					lockedPerfChoices.push(...perfChoices);
				}
			});

			// If every choice available on the unlocked requirements is also associated with a locked requirement, 
			// then it doesn't matter what we do - none of the choices will free up any peripherals.  In that case, 
			// we can return true to omit the entry and skip the clauses

			return _.chain(unlockedPerfChoices)
				.difference(lockedPerfChoices)
				.isEmpty()
				.value();
		});
	}

	protected getConflictingChoices() {
		return {};
	}

	protected getDirectlyMinimizingChoices(): IChoice[] {
		return [];
	}
}
