import React = require("react");
import * as _ from "lodash";
import ReactDOM = require("react-dom");
import { ErrorModal } from "../../components/modals/ErrorModal";
import { ConfirmModal } from "../../components/modals/ConfirmModal";
import { IModalService } from "../IModalService";
import { InvalidMinToolVersion } from "../product/versionCheck";
import { UpdateModal } from "../../components/modals/UpdateModal";
import { ATheme } from "../../components/styles/themes";
import { UseCustomBoard } from "../../components/modals/UseCustomBoard";
import { ITarget, SwitchBoardOrDevice } from "../../components/modals/SwitchBoardOrDevice";
import { ProgressBar } from "../../components/ProgressBar";
import { ThemeProvider, Typography } from "../../imports/material-ui-imports";
import { UnsupportedInstances } from "../../components/modals/UnsupportedInstances";
import { ITargetID } from "../migration/migrate";
import { MigrationOptions } from "../migration/migrationOptions";
import { LazyLoadedTerminal } from "../../components/modals/LazyLoadedTerminal";
import { IProcess } from "../IProcess";
import { AsyncModalWithProgess } from "../../components/AsyncProgressModal";
import { IModuleConfigModalProps, ModuleConfigModal } from "../../components/modals/ModuleConfigModal";

export class ModalService implements IModalService {

	// the base mount-point is modalRoot
	private mountPoints: HTMLElement[];

	constructor(public theme: ATheme, mountPoint: HTMLElement) {
		this.mountPoints = [mountPoint];
	}

	public showModal(
		title: string,
		content: JSX.Element | string,
		onClose = () => { },
		hideTitleIcon?: boolean,
	) {
		this.showConfirmModal(title, content, null, onClose, null, "OK", hideTitleIcon);
	}

	public showUseCustomBoardModal(currentBoard: string, confirmAction: (lockSolutionFirst: boolean) => void) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<UseCustomBoard
					currentBoard={currentBoard}
					// because the closure is only being passed down once, it doesn't matter
					// eslint-disable-next-line react/jsx-no-bind
					confirmAction={
						(lockSolutionFirst) => {
							this.closeModal();
							confirmAction(lockSolutionFirst);
						}
					}
					cancelAction={this.closeModal}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
				/>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showIncompatibleInstances(instances: string[]) {
		return new Promise<void>((resolve) => {
			this.showModal(
				"Incompatible Software and/or Peripherals",
				<UnsupportedInstances instances={instances} />,
				resolve,
			);
		});
	}

	public showSwitchBoardOrDeviceModal(
		currentTarget: ITarget,
		migrationOptions: MigrationOptions,
		confirmAction: (newTarget: ITargetID, lockSolutionFirst: boolean) => void,
	) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<SwitchBoardOrDevice
					currentTarget={currentTarget}
					migrationOptions={migrationOptions}
					// eslint-disable-next-line react/jsx-no-bind
					confirmAction={
						(newTarget, lockSolutionFirst) => {
							this.closeModal();
							confirmAction(newTarget, lockSolutionFirst);
						}
					}
					cancelAction={this.closeModal}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
				/>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showModuleConfigModal({ onConfirmAction, ...rest }:
		Omit<IModuleConfigModalProps, "modalService" | "closeModal" | "confirmAction" | "registerSubModalMountPoint"> &
		{ onConfirmAction: (closeModal: () => void) => void; }
	) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ModuleConfigModal
					{...rest}
					modalService={this}
					registerSubModalMountPoint={this.handleMountPointRef}
					closeModal={this.closeModal}
					confirmAction={onConfirmAction}
				/>
			</ThemeProvider>
			, _.last(this.mountPoints));
	}

	// This will block out the entire UI and show a progress spinner while "operation" runs.  This is for cases where 
	// the UI may not be valid at times during the operation and thus render calls should not happen (such as during a
	// migrate).
	public async showProgressAndBlankUIDuring<T>(title: string, operation: () => Promise<T>) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ProgressBar id="progressModal" title={title} />;
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
		try {
			return await operation();
		} finally {
			this.closeModal();
		}
	}

	// The above function will block out the entire UI, these are for cases where we just want to show 
	// progress with a popup modal without hiding the entire ui. (ex: a button click)
	// If the operation benefits from indicating to the user it has completed addDelay will add a 500ms delay
	// so the user will always see the spinner and thus know their operation has completed
	public async showProgressDuring<T>(
		title: string,
		operation: (setProgess: (progress: number) => void) => Promise<T>,
		addDelay?: boolean)
		: Promise<T> {
		try {
			return await new Promise((resolve, reject) => {
				ReactDOM.render(<AsyncModalWithProgess
					theme={this.theme}
					title={title}
					operation={operation}
					resolve={resolve}
					reject={reject}
					handleMountPointRef={this.handleMountPointRef}
					manualDelay={addDelay}
				/>,
					_.last(this.mountPoints));
			});
		} finally {
			this.closeModal();
		}
	}

	public showUpdateModal(error: InvalidMinToolVersion, confirmAction: () => void) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<UpdateModal
					error={error}
					theme={this.theme}
					registerSubModalMountPoint={this.handleMountPointRef}
					// eslint-disable-next-line react/jsx-no-bind
					confirmAction={
						() => {
							this.closeModal();
							confirmAction();
						}
					} />
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showOhSnapErrorModal(error: Error, onClose: () => void = () => { }) {
		this.showErrorModal(
			"Oh Snap! The last change caused an exception...",
			error,
			onClose,
		);
	}

	public showErrorModal(
		title: string,
		error: Error,
		onClose: () => void = () => { },
		onConfirm?: () => void,
		confirmText?: string,
		cancelText?: string,
		content?: string
	) {
		const confirmAction = onConfirm ? () => { this.closeModal(); onConfirm(); } : null;
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ErrorModal
					theme={this.theme}
					id={"errorModal"}
					title={title}
					error={error}
					// eslint-disable-next-line react/jsx-no-bind
					onClose={() => {
						this.closeModal();
						onClose();
					}}
					// eslint-disable-next-line react/jsx-no-bind
					onConfirm={confirmAction}
					confirmText={confirmText}
					cancelText={cancelText}
					registerSubModalMountPoint={this.handleMountPointRef}
					content={content}
				/>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showConfirmModal(
		title: string,
		content: JSX.Element | string,
		confirmCallback?: () => void,
		cancelCallback?: () => void,
		confirmText?: string,
		cancelText?: string,
		hideTitleIcon?: boolean,
	) {
		const confirmAction = !confirmCallback ? null :
			() => {
				this.closeModal();
				confirmCallback();
			};
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ConfirmModal
					hideTitleIcon={hideTitleIcon}
					id={"confirmationModal"}
					title={title}
					// eslint-disable-next-line react/jsx-no-bind
					confirmAction={confirmAction}
					// eslint-disable-next-line react/jsx-no-bind
					cancelAction={
						() => {
							this.closeModal();
							if (cancelCallback) {
								cancelCallback();
							}
						}
					}
					confirmText={confirmText}
					cancelText={cancelText}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
				>
					{(typeof content === "string") ?
						(<Typography variant="body2" style={{ whiteSpace: "pre" }}>
							{content}
						</Typography>) : (content)}
				</ConfirmModal>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showTerminalModal(
		title: string,
		confirmText: string,
		command: string,
		args: string[],
		process: IProcess,
	) {
		const confirmAction = () => {
			this.closeModal();
		};
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<LazyLoadedTerminal
					id={"terminalModal"}
					title={title}
					// eslint-disable-next-line react/jsx-no-bind
					confirmAction={confirmAction}
					confirmText={confirmText}
					command={command}
					args={args}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
					process={process}
				>
				</LazyLoadedTerminal>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);

	}

	public reset() {
		while (_.size(this.mountPoints) > 1) {
			this.closeModal();
		}
	}

	public updateTheme(theme: ATheme) {
		this.theme = theme;
	}

	private closeModal = () => {
		// remove the next mount point that hasn't been used yet
		if (_.size(this.mountPoints) > 1) {
			this.mountPoints = _.dropRight(this.mountPoints);
		}

		// un-mount the top-most modal so that another can be mounted if needed
		ReactDOM.unmountComponentAtNode(_.last(this.mountPoints));
	}

	// callback to obtain the reference to the next mount point
	private handleMountPointRef = (el: HTMLElement) => {
		if (el) {
			this.mountPoints.push(el);
		}
	}
}

