import * as React from "react";
import * as _ from "lodash";
import { Position } from "public/runtime";
import { withStyles } from "../../../imports/material-ui-imports";
import { ProgressBar } from "../../ProgressBar";
import { InnerGraph } from "./InnerGraph";
import { IFZoomFloatingContentProps, WithZoom } from "../../higherOrderComponents/WithZoom";
import { FloatingSearch } from "./floatingControls/FloatingSearch";
import { FloatingMetaButtons } from "./floatingControls/FloatingMetaButtons";
import { FloatingNavigation } from "./floatingControls/FloatingNavigation";
import { FloatingHelp } from "./floatingControls/FloatingHelp";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { ClassesType, graphStyles } from "../styling/graphStyles";
import { IGraphProps } from "../types/IGraphProps";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { FloatingCursorModeControls } from "./floatingControls/FloatingCursorControls";
import { CursorMode } from "../CursorMode";
import { IGraphActions } from "../../actions/IGraphActions";

// This component adds zoom/pan functionality as well as non-zooming floating controls on top of a graph component.  It
// does this by accepting the layout for a graph as a prop, and then instantiates the graph component within a WithZoom
// component that is based on the size of the layout provided.
//
// Because it adds floating buttons, and floating buttons provide search, it keeps track of the current search text and
// passes that along to the underlying graph component.  In also intercepts click events in order to cancel search on a
// click

type IProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	= IGraphProps<InstMgr, PortMgr> & Omit<React.ComponentProps<typeof FloatingMetaButtons>, "moduleMgr">;

interface IState {
	searchText: string;
}

interface ICursorProps {
	cursorMode: CursorMode;
	setCursorMode: (cursorMode: CursorMode) => void;
}

class StyledZoomableGraph<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.Component<IProps<InstMgr, PortMgr> & ClassesType, IState> {

	public override state: IState = {
		searchText: "",
	}

	public override render() {
		const {
			layout,
			nodeFactory,
			canMemoize,
			onMouseMove,
			onMouseEnterEdge,
			onMouseLeaveEdge,
			onClickEdge,
			getEdgeToolTip,
			usedInstances,
			disabledInstances,
			treeNode,
			validations,
			displayScriptName,
			actions,
			highlightedEdges,
			selectedEdges,
			classes,
			errorStore,
			formatter,
			resourceLoader,
			modalService,
			notificationService,
			theme,
			branding,
			userAction,
			setCursorMode,
			cursorMode,
		} = this.props;

		if (!layout) {
			return <ProgressBar title="rendering" />;
		}

		const { searchText } = this.state;
		const moduleMgr = treeNode.getStaticConfiguration();
		const childXOrigin = _.minBy(layout.nodes, (n) => n.x)?.x ?? 0;
		const childYOrigin = _.minBy(layout.nodes, (n) => n.y)?.y ?? 0;

		return (
			<WithZoom
				childXOrigin={childXOrigin}
				childYOrigin={childYOrigin}
				childWidth={layout.width - childXOrigin}
				childHeight={layout.height - childYOrigin}
				onMouseDown={this.onMouseDown}
				onMouseMove={onMouseMove}
				onMouseUp={this.props.onMouseUp}
				onClick={this.onClickPort}
				additionalProps={{ cursorMode, setCursorMode, actions }}
				floatingContentLeft={
					<FloatingMetaButtons
						moduleMgr={moduleMgr}
						validations={validations}
						displayScriptName={displayScriptName}
						actions={actions}
						errorStore={errorStore}
						formatter={formatter}
						resourceLoader={resourceLoader}
						modalService={modalService}
						notificationService={notificationService}
						theme={theme}
						branding={branding}
					/>
				}
				floatingContentRight={this.generateFloatingContentRight}
			>
				{
					({ onMouseDown, onMouseUp, onClick }) => <InnerGraph<InstMgr, PortMgr>
						layout={layout}
						nodeFactory={nodeFactory}
						canMemoize={canMemoize}
						onClickNode={this.onClickNode}
						onMouseDownNode={onMouseDown}
						onMouseEnterEdge={onMouseEnterEdge}
						onMouseLeaveEdge={onMouseLeaveEdge}
						onMouseDownPort={onMouseDown}
						onMouseUpPort={onMouseUp}
						onClickEdge={onClickEdge}
						getEdgeToolTip={getEdgeToolTip}
						usedInstances={usedInstances}
						disabledInstances={disabledInstances}
						highlightedEdges={highlightedEdges}
						selectedEdges={selectedEdges}
						treeNode={treeNode}
						validations={validations}
						actions={actions}
						displayScriptName={displayScriptName}
						searchText={searchText}
						classes={classes}
						userAction={userAction}
						onClickPort={onClick}
						formatter={formatter}
						cursorMode={cursorMode}
					/>
				}
			</WithZoom>
		);
	}

	private generateFloatingContentRight = (props: IFZoomFloatingContentProps & ICursorProps & { actions: IGraphActions }) => {
		const { searchText } = this.state;
		const { treeNode, onAutoArrange, onMouseDownNode, cursorMode, setCursorMode, actions } = this.props;

		return <>
			<FloatingSearch
				searchText={searchText}
				onSearchTextChanged={this.onSearchTextChanged}
				key={treeNode.getSelection().instanceId} // Ensures a selection change resets the search
			/>
			<div> {/* div ensures that FloatingHelp will be underneath */}
				<FloatingNavigation
					zoomIn={props.zoomIn}
					zoomOut={props.zoomOut}
					reset={props.reset}
					onAutoArrange={onAutoArrange}
				/>
			</div>
			<div>
				<FloatingCursorModeControls
					cursorMode={cursorMode}
					setCursorMode={setCursorMode}
					globalPermittedProbeTypes={actions.getPermittedProbeTypes()} />
			</div>
			<FloatingHelp movableNodes={!!onMouseDownNode} />
		</>;
	}

	private onSearchTextChanged = (filterText: string) => {
		this.setState({ searchText: filterText });
	}

	private onClickNode = (selection: InstMgr) => {
		this.setState({ searchText: "" });
		const { onClickNode } = this.props;
		if (onClickNode) {
			onClickNode(selection);
		}
	}

	private onMouseDown = (position: Position, data: InstMgr | PortMgr) => {
		const { onMouseDownNode, onMouseDownPort } = this.props;
		if (data instanceof ModuleInstanceMgr) {
			if (onMouseDownNode) {
				onMouseDownNode(position, data as InstMgr);
			}
		} else if (onMouseDownPort) {
			onMouseDownPort(position, data);
		}
	}

	private onClickPort = (position: Position, data: PortMgr) => {
		const { onClickPort } = this.props;
		if (onClickPort) {
			onClickPort(position, data);
		}
	}
}

// withStyles returns a function which takes a component and wraps it in another component that injects the classes 
// prop.  As such, it's signature should returns the type of the original component without the classes prop.  
// Unfortunately, due to a limitation in typescript, it drops any template arguments.  The workaround is to cast the
// return value to the correct type.  
// It's the same issue as with React.memo: https://github.com/DefinitelyTyped/DefinitelyTyped/issues/37087

type ZoomableGraphType = <InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(props: IProps<InstMgr, PortMgr>) => JSX.Element;
export const ZoomableGraph = withStyles(graphStyles)(StyledZoomableGraph) as ZoomableGraphType;
