import * as React from "react";
import * as _ from "lodash";
import { ThermometerProbe, Connection } from "../../../../imports/mdi-material-ui-imports";
import { ToggleButton, ToggleButtonGroup, Tooltip, Popover, withStyles } from "../../../../imports/material-ui-imports";
import { generateToolTipProps } from "../../../Tooltip"; // ToggleButtonGroup prevents direct use of our template wrapper
import { TProbe } from "public/runtime";
import { CursorMode, CursorModeType, isProbingMode } from "../../CursorMode";

interface IProps {
	cursorMode: CursorMode;
	setCursorMode: (setCursorMode: CursorMode) => void;
	globalPermittedProbeTypes: TProbe[]
}

const anchorOrigin = {
	vertical: "top",
	horizontal: "left",
} as const;

const transformOrigin = {
	vertical: "top",
	horizontal: "right",
} as const;

// For consistency with other floating buttons
const FloatingToggleButtonGroup = withStyles({
	root: {
		marginRight: 3,
	},
})(ToggleButtonGroup);

const PopupToggleButtonGroup = withStyles({
	root: {
		margin: 0,
	},
	grouped: {
		borderRadius: 0,
		maxHeight: 25,
	},
})(ToggleButtonGroup);

export function FloatingCursorModeControls({ cursorMode, setCursorMode, globalPermittedProbeTypes }: IProps) {
	const [anchorEl, setAnchorEl] = React.useState<HTMLElement>(null);
	const openProbeControls = React.useCallback((event: React.MouseEvent<HTMLElement>) => setAnchorEl(event.currentTarget), [setAnchorEl]);
	const handleClose = React.useCallback(() => setAnchorEl(null), [setAnchorEl]);
	const probeToggleOnClick = React.useCallback((e: React.MouseEvent<HTMLElement>) => {
		if (globalPermittedProbeTypes.length > 1) {
			return openProbeControls(e);
		} else if (globalPermittedProbeTypes.length === 1) {
			// If there is only one option, we don't need to open the menu
			setCursorMode({ mode: CursorModeType.Probing, probingMode: _.first(globalPermittedProbeTypes) });
		}
	}, [globalPermittedProbeTypes, openProbeControls, setCursorMode]);
	const toggleSelected = React.useCallback((_e: React.MouseEvent<HTMLElement>, newSelection: typeof cursorMode.mode) => {
		if (newSelection === CursorModeType.Connecting) {
			// We end probe mode and revert to default mode
			setCursorMode({ mode: CursorModeType.Connecting, dragConnecting: null, clickConnecting: null });
		}
	}, [setCursorMode, cursorMode]);

	if (!setCursorMode || !_.first(globalPermittedProbeTypes)) {
		// We are in clocktree OR
		// Probing is not enabled. Since there are currently only two options: connecting or probing,
		// it makes sense to not render this group if one of the options is disabled; we can only select
		// one option - connecting mode (which is default anyways).
		return null;
	}

	const probeControlsIsOpen = Boolean(anchorEl);
	return <>
		<FloatingToggleButtonGroup value={cursorMode.mode} orientation="vertical" onChange={toggleSelected} exclusive>
			<ToggleButton value={CursorModeType.Connecting}>
				<Tooltip {...generateToolTipProps({ title: "Connect wires" })}>
					<Connection style={{ padding: 1 }} fontSize="small" />
				</Tooltip>
			</ToggleButton>
			<ToggleButton onClick={probeToggleOnClick} value={CursorModeType.Probing}>
				<Tooltip {...generateToolTipProps({ title: "Attach a Probe" })}>
					<ThermometerProbe style={{ padding: 1 }} fontSize="small" />
				</Tooltip>
			</ToggleButton>
			<Popover
				open={probeControlsIsOpen}
				anchorEl={anchorEl}
				onClose={handleClose}
				elevation={2}
				anchorOrigin={anchorOrigin}
				transformOrigin={transformOrigin}
			>
				<ProbeControls
					cursorMode={cursorMode}
					setCursorMode={setCursorMode}
					closeMenu={handleClose}
					globalPermittedProbeTypes={globalPermittedProbeTypes}
				/>
			</Popover>
		</FloatingToggleButtonGroup>
	</>;
}

function ProbeControls({ cursorMode, setCursorMode, globalPermittedProbeTypes, closeMenu }: IProps & { closeMenu: () => void }) {
	const onChange = React.useCallback((_e: React.MouseEvent<HTMLElement>, nextSelection: TProbe) => {
		if (nextSelection != null) {
			// Atleast one of the options must be selected to activate probing mode
			setCursorMode({ mode: CursorModeType.Probing, probingMode: nextSelection });
		}
		closeMenu();
	}, [setCursorMode, closeMenu]);

	if (!globalPermittedProbeTypes || globalPermittedProbeTypes.length === 1) {
		return null;
	}
	return <PopupToggleButtonGroup
		orientation="vertical"
		value={isProbingMode(cursorMode) ? cursorMode.probingMode : null}
		onChange={onChange}
		exclusive>
		{
			_.map(globalPermittedProbeTypes, (probeType, i) =>
				<ToggleButton key={i} value={probeType}>
					<Tooltip {...generateToolTipProps({ title: `Add ${probeType} probes` })}>
						<span>{probeType}</span>
					</Tooltip>
				</ToggleButton>
			)
		}
	</PopupToggleButtonGroup >;
}
