import * as _ from "lodash";
import React = require("react");
import { List, ListItem, ListItemIcon, Typography } from "../../../imports/material-ui-imports";
import {
	Bell,
	BellOff,
	FileTreeOutline,
	Lock,
	Minus,
	MoveResizeVariant,
	OpenInNew,
	Pencil,
	Plus,
	Power,
	Resize,
	SourceBranch,
	SourceBranchRemove,
	TextBoxCheckOutline,
	TextBoxRemoveOutline,
	Wrench,
	ContentCopy,
} from "../../../imports/mdi-material-ui-imports";
import { commonStyles, withCommonStyles, CommonClasses } from "../../styles/common";
import { HistoryViewMgr } from "../../../services/ui/outputView";
import { ChangeHistory, HistoryPointDesc } from "../../../services/changeHistory";
import { assertUnreachable } from "../../../services/utils";

interface IProps {
	mgr: HistoryViewMgr;
}

const divStyle = {
	maxHeight: 320,
};

const listStyle = {
	margin: "0 5px 5px 5px",
};

const textStyle: React.CSSProperties = {
	color: "#999",
};

interface IEntryProps {
	marker: string;
	index: number;
	title: HistoryPointDesc;
	className: string
	history: ChangeHistory<unknown>;
}

class HistoryEntry extends React.Component<IEntryProps>{

	public override render() {
		const { marker, title, className } = this.props;
		return <ListItem
			id="history-entry"
			dense
			button
			onClick={this.onClick}
			className={className}
		>
			<ListItemIcon style={{ ...commonStyles.smallIcon, ...textStyle }}>
				<HistoryIcon text={title} />
			</ListItemIcon>
			<Typography variant="body2" style={{ flexGrow: 1 }}>{title}</Typography>
			<Typography variant="body2" className="history-marker" style={textStyle}>
				{marker}
			</Typography>
		</ListItem>;
	}

	private onClick = () => this.props.history.setCurrentPoint(this.props.index);
}

// returns the history list in reverse order (latest at the top)
function StyledHistoryView(props: IProps & CommonClasses) {
	const items = props.mgr.getHistoryUIItems();
	const history = props.mgr.getHistory();
	return (
		<div style={divStyle}>
			<List dense style={listStyle}>
				{_.map(items, (item) => {
					const { selected, index, title, key, ...rest } = item;
					return <HistoryEntry
						{...rest}
						key={`${index}:${title}`}
						index={index}
						title={title}
						history={history}
						className={selected ? props.classes.selectedList : props.classes.unSelectedList}
					/>;
				})
				}
			</List>
		</ div>
	);
}

export const HistoryView = withCommonStyles(StyledHistoryView);

function startsWith<T extends string>(a: string, t: T): a is `${T}${string}` {
	return _.startsWith(a, t);
}

// Yes, this has high cyclomatic complexity by definition, but it's straightforward and type-checked
// eslint-disable-next-line complexity
function HistoryIcon({ text }: { text: HistoryPointDesc }) {
	if (text === "Initial state") {
		return <Power color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Add") || startsWith(text, "Reserved")) {
		return <Plus color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Remove")) {
		return <Minus color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Change")) {
		return <Pencil color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Locked")) {
		return <Lock color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Switch")) {
		return <Resize color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Ignore")) {
		return <BellOff color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Don't ignore")) {
		return <Bell color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Clicked")) {
		return <OpenInNew color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Cleared error")) {
		return <Wrench color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Suppressed")) {
		return <BellOff color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Un-suppressed")) {
		return <Bell color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Excluded")) {
		return <TextBoxRemoveOutline color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Included")) {
		return <TextBoxCheckOutline color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Moved")) {
		return <MoveResizeVariant color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Connected")) {
		return <SourceBranch color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Disconnected")) {
		return <SourceBranchRemove color="primary" style={commonStyles.smallIcon} />;
	} else if (text === "Auto Arranged") {
		return <FileTreeOutline color="primary" style={commonStyles.smallIcon} />;
	} else if (startsWith(text, "Copied")) {
		return <ContentCopy color="primary" style={commonStyles.smallIcon} />;
	} else {
		assertUnreachable(text);
	}
}
