const version: string = require("../version.txt");

// development version
export const devVersion = "1.0.0+dev";
export function getToolVersion() {
	const versionTxt = getVersionTxtContent();
	if (versionTxt === "dev") {
		return devVersion;
	} else {
		return versionTxt;
	}
}

function getVersionTxtContent() {
	return version.replace(/(\r\n|\n|\r)/gm, ""); // Remove new line chars;
}
