import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { NodeFactory } from "../types/nodeTypes";
import * as Layout from "../types/layoutTypes";
import { IUnStyledNodeProps, Node } from "./Node";
import { IGraphTreeNode } from "../types/IGraphTreeNode";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { UserGraphAction } from "../types/IGraphProps";

// Renders just the node that is currently selected.  This is just rendered on top of the other node, and differs only 
// in that selected is passed to NodeComponent

interface IProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends Omit<IUnStyledNodeProps<InstMgr, PortMgr>, "node"> {
	nodes: Layout.Node<InstMgr, PortMgr>[];
	nodeFactory: NodeFactory<InstMgr, PortMgr>;
	treeNode: IGraphTreeNode<InstMgr>;
	userAction: UserGraphAction;
}

export function NodeSelectionIndicator<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: IProps<InstMgr, PortMgr> & ClassesType
) {
	const { nodes, treeNode, userAction, ...rest } = props;
	const selection = treeNode.getSelectedMyListItem();
	return <>
		{
			_.chain(nodes)
				.filter((n) => n.inst === selection)
				.map((node) =>
					<Node
						{...rest}
						node={node}
						selected={true}
						key={node.id}
						grabbing={userAction === UserGraphAction.DRAGGING}
					/>
				)
				.value()
		}
	</>;
}
