import * as _ from "lodash";
import React = require("react");
import { IconButton, ListItemIcon, ListItemText, Menu, MenuItem, Typography } from "../imports/material-ui-imports";
import { FileMoveOutline } from "../imports/mdi-material-ui-imports";
import { InstanceMgr } from "../services/instanceContainers/instanceContainer";
import { ModuleInstanceMgr } from "../services/objectManagers/moduleInstance";
import { UIContext, UIContextSelection } from "./actions/IContextActions";
import { commonStyles } from "./styles/common";
import { Tooltip } from "./Tooltip";

interface IProps {
	mgr: ModuleInstanceMgr;
	moveInstance: (mgr: InstanceMgr, contextName: string) => void;
	isTopModuleOnContext: (mgr: ModuleInstanceMgr, contextName: string) => boolean;
	getContextSelection(): UIContextSelection;
}

interface ContextOption {
	context: UIContext;
	// tells us if the module mgr is a top module on this context
	isTopModule: boolean;
}

export function MoveInstanceButton({ getContextSelection, mgr, isTopModuleOnContext, moveInstance }: IProps) {

	// only create menu items for the other contexts however if there's only 1 other context than we don't want to show any 
	// menu. We should just go ahead and move the instance to the other context and our tooltip should change here as well
	const { selectedIndex, contexts } = getContextSelection();
	const currentContext = contexts[selectedIndex];
	const otherContexts: ContextOption[] = _.chain(contexts)
		.without(currentContext)
		.map((context) => ({
			context,
			isTopModule: isTopModuleOnContext(mgr, context.name),
		}))
		.value();
	const onlyOneOtherContext = otherContexts.length === 1;

	// handle click and close for popover
	const [anchorEl, setAnchorEl] = React.useState<HTMLElement>(null);

	const onIconClick = React.useCallback((e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
		if (onlyOneOtherContext) {
			moveInstance(mgr, otherContexts[0].context.name);
		} else {
			setAnchorEl(e.currentTarget.parentElement);
		}
	}, [otherContexts, onlyOneOtherContext, mgr, moveInstance]);

	const onMenuClick = React.useCallback(() => {
		setAnchorEl(null);
	}, []);

	// if we only have 1 other context to move to than we should check if we actually can move and if we can't
	// our icon button should be disabled and the tooltip should explain why
	let tooltip = "";
	let canMoveToAnotherContext = true;

	const ownershipInfo = mgr.getOwnershipInfo();

	if (ownershipInfo) {
		canMoveToAnotherContext = false;
		tooltip = !!ownershipInfo.owner ? `Cannot be moved: Owned by ${ownershipInfo.owner.$name}` :
			`Cannot be moved: Shared by ${_.first(ownershipInfo.sharer).$name}`;
	} else if (_.every(otherContexts, (oContext) => !oContext.isTopModule)) {
		canMoveToAnotherContext = false;
		tooltip = `${mgr.getModuleMgr().getDisplayName(false)} only available on ${currentContext.name}`;
	} else if (onlyOneOtherContext) {
		tooltip = `Move to ${otherContexts[0].context.name}`;
	} else {
		tooltip = `Move ${mgr.getName()}`;
	}

	return (
		<>
			<ListItemIcon>
				<Tooltip title={tooltip}>
					<IconButton
						disabled={!canMoveToAnotherContext}
						onClick={onIconClick}
						className={"moveInstanceIcon"}
					>
						<FileMoveOutline style={commonStyles.smallIcon} />
					</IconButton>
				</Tooltip>
			</ListItemIcon>
			<Menu
				disableAutoFocusItem={true} // this will make sure no element is highlighted grey when menu is open
				anchorEl={anchorEl}
				open={Boolean(anchorEl)}
				hidden={onlyOneOtherContext}
				onClick={onMenuClick}
				getContentAnchorEl={null} // https://github.com/mui-org/material-ui/issues/7961
				anchorOrigin={anchorOrigin}
				transformOrigin={transformOrigin}
				id={"MoveInstanceMenu"}
			>
				{_.map(otherContexts, (contextOption, idx) =>
					<ContextMenuItem key={idx} currentContext={contextOption} mgr={mgr} moveInstance={moveInstance} />)}
			</Menu>
		</>
	);
}

const anchorOrigin = { vertical: "bottom", horizontal: "center" } as const;
const transformOrigin = { vertical: "top", horizontal: "center" } as const;

interface ContextMenuItemProps extends Omit<IProps, "getContextSelection" | "isTopModuleOnContext"> {
	currentContext: ContextOption;
}
function ContextMenuItem({ currentContext, moveInstance, mgr }: ContextMenuItemProps) {
	const { context, isTopModule } = currentContext;
	const onClick = React.useCallback(() => { moveInstance(mgr, context.name); }, [mgr, context, moveInstance]);
	return <Tooltip title={!isTopModule ? `${mgr.getModuleMgr().getDisplayName(false)} not available on ${context.name}` : ""}>
		<MenuItem
			disabled={!isTopModule}
			onClick={onClick}
			id={`menuItem_${context.name}`}
		>
			<ListItemText style={commonStyles.extendOutputMenuStyle}>
				<Typography>
					{_.toUpper(context.name)}
				</Typography>
			</ListItemText>
		</ MenuItem>
	</Tooltip>;
}
