import * as _ from "lodash";
import React = require("react");
import { InterfaceInstanceMgr } from "../../../services/objectManagers/interfaceInstance";
import { DropDown } from "../../DropDown";
import { Table, TableBody, TableRow, TableCell, TableHead, Typography } from "../../../imports/material-ui-imports";
import { Formatted2ColRow } from "../../Formatted2ColRow";
import { ITreeNode } from "../../TreeNode";
import { IOSetViewMgr } from "../../../services/ui/outputView";
import { commonStyles } from "../../styles/common";

interface IProps {
	mgr: IOSetViewMgr;
	selectedTreeNode: ITreeNode;
}

interface IState {
	peripheralSelection: string;
	ioSetSelection: string;
}

const tableStyle: React.CSSProperties = {
	margin: "0 10px 0 16px",	// padding to align with file list
};

export class IOSetView extends React.Component<IProps, IState> {

	constructor(props: IProps) {
		super(props);
		const instMgr = this.getCurrentSelection();
		const interfaceMgr = this.props.selectedTreeNode;
		const iFace = this.props.mgr.getDeviceData().interfaces[interfaceMgr.getDisplayName(false)];
		if (instMgr && instMgr.getSolverRequirement().solution.assignedToName) {
			this.state = {
				peripheralSelection: instMgr.getSolverRequirement().solution.assignedToName,
				ioSetSelection: instMgr.getSolverRequirement().solution.ioSet,
			};
		} else if (iFace) {
			const { peripherals } = iFace;
			const { ioSets } = _.first(peripherals);
			this.state = {
				peripheralSelection: _.first(peripherals).name,
				ioSetSelection: _.isEmpty(ioSets) ? null : _.first(ioSets).name,
			};
		} else {
			this.state = {
				peripheralSelection: null,
				ioSetSelection: null,
			};
		}
	}

	public override render() {
		const interfaceName = this.props.selectedTreeNode.getDisplayName(false);
		if (!this.state.ioSetSelection) {
			return <Typography variant="body2" style={commonStyles.centeredStyle}>
				No IO Sets available for {interfaceName}
			</Typography>;
		}
		const { ioSets } = this.props.mgr.getDeviceData().peripherals[this.state.peripheralSelection];
		const ioSet = _.find(ioSets, (i) => i.name === this.state.ioSetSelection);
		const ioSetRules = ioSet ? ioSet.ioSetRules : {};
		return (
			<div>
				<table style={tableStyle}>
					<tbody>
						<Formatted2ColRow
							col1={<Typography variant="body2">Peripheral:</Typography>}
							col2={
								<DropDown
									id="peripheralSelection"
									disabled={false}
									onChange={(value: string) => this.setPeripheral(value)}
									selectedOptionName={this.state.peripheralSelection}
									enabledOptions={_.map(
										this.props.mgr.getDeviceData().interfaces[interfaceName].peripherals,
										(peripheral) => ({ name: peripheral.name, displayName: peripheral.name }))}
									displayScriptName={false}
								/>
							}
						/>
						<Formatted2ColRow
							col1={<Typography variant="body2">IOSet:</Typography>}
							col2={
								<DropDown
									id="ioSetSelection"
									disabled={false}
									onChange={(value: string) => this.setIOSet(value)}
									selectedOptionName={this.state.ioSetSelection}
									enabledOptions={_.map(ioSets, (i) => ({ name: i.name, displayName: i.name }))}
									displayScriptName={false}
								/>
							}
						/>

					</tbody>
				</table>
				<Table>
					<TableHead>
						<TableRow style={commonStyles.tableRowStyle}>
							<TableCell>Signal</TableCell>
							<TableCell>Device Pin</TableCell>
						</TableRow>
					</TableHead>
					<TableBody>
						{_.map(ioSetRules, (devicePin, signal) => {
							const sigName = _.get(this.props.mgr.getDeviceData().devicePins[devicePin], "designSignalName", "");
							return (
								<TableRow key={signal} hover style={commonStyles.tableRowStyle}>
									<TableCell>
										{signal}
									</TableCell>
									<TableCell>
										{devicePin} ({sigName})
									</TableCell>
								</TableRow>
							);
						})}
					</TableBody>
				</Table>
			</div>
		);
	}

	private getCurrentSelection(): InterfaceInstanceMgr {
		const instMgr = this.props.selectedTreeNode.getSelectedMyListItem();
		return instMgr instanceof InterfaceInstanceMgr ? instMgr : null;
	}

	private setPeripheral(peripheralSelection: string) {
		if (peripheralSelection !== this.state.peripheralSelection) {
			const { ioSets } = this.props.mgr.getDeviceData().peripherals[peripheralSelection];
			this.setState({
				peripheralSelection,
				ioSetSelection: _.isEmpty(ioSets) ? null : _.first(ioSets).name,
			});
		}
	}

	private setIOSet(ioSetSelection: string) {
		if (ioSetSelection !== this.state.ioSetSelection) {
			this.setState({ ioSetSelection });
		}
	}
}
