import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { Group } from "./Group";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { IInnerGraphProps } from "../graph/InnerGraph";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// This component will render a <Group> node for every group in the layout passed in

export function Groups<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: IInnerGraphProps<InstMgr, PortMgr> & ClassesType
) {
	const { layout, ...rest } = props;
	return <>
		{
			_.map(layout.groups, (child) => {
				return <Group
					{...rest}
					layout={child}
					key={`group_${child.id}`}
				/>;
			})
		}
	</>;
}
