import { IModalService } from "../IModalService";
import { IProcess } from "../IProcess";

export class NOPModalService implements IModalService {
	private lockSolutionFirst = true;
	private resolve: (value?: void | PromiseLike<void>) => void = null;
	private reject: (reason?: any) => void = null;
	public showErrorModal() { }

	public showModal(_title: string, _content: JSX.Element | string, onClose?: () => void) {
		if (onClose) {
			onClose();
		}
	}

	public showIncompatibleInstances() {
		return Promise.resolve();
	}

	public showProgressAndBlankUIDuring<T>(_title: string, operation: () => Promise<T>) {
		return operation();
	}

	public showConfirmModal(_title: string, _content: string, confirmAction?: () => void) {

		// Make it look like the user clicked "confirm"

		setTimeout(() => {
			try {
				confirmAction();
				this.resolve();
				this.reject = this.resolve = null;
			} catch (e) {
				this.reject(e);
				this.reject = this.resolve = null;
			}
		});
	}

	public showSwitchBoardOrDeviceModal() {
		throw new Error("Method not implemented.");
	}

	public showUseCustomBoardModal(_boardName: string, confirmAction: (lockSolutionFirst: boolean) => void) {
		this.showConfirmModal("", "", () => confirmAction(this.lockSolutionFirst));
	}

	public showTerminalModal(
		_title: string,
		_confirmText: string,
		_command: string,
		_args: string[],
		_process: IProcess,
	): void {
	}

	public showProgressDuring<T>(
		_title: string,
		operation: (setProgess: (progress: number) => void) => Promise<T>,
		_addDelay?: boolean
	): Promise<T> {
		return operation(() => { });
	}

	public updateTheme() { }

	public reset() { }
}
