interface IAssignValue {
	memberMgrs: { [memberName: string]: AnyMemberMgr };
	getSolverRequirement(): Pin | Peripheral;
}

// if lock=true, set the value to be the solved value (only if there was a solution)
// ow, set the value to be ANY
export function setAssignedValue(lock: boolean, assignObj: IAssignValue) {
	const assignedName = assignObj.getSolverRequirement().solution.assignedToName;

	if (lock && assignObj.memberMgrs.$assignAllowConflicts.getValue() !== Const.ANY) {
		// Don't clear $assignAllowConflicts because they requested the entire solution be locked
		return;
	}

	if (!lock || !_.isEmpty(assignedName)) {
		assignObj.memberMgrs.$assign.set(lock ? assignedName : Const.ANY, SetSource.USER_ASSIGN);
	}
}

/**
 * Manages an interface instance runtime object
 */
export class InterfaceInstanceMgr
	extends AObjectMgr<InterfaceInstance>
	implements IMyListItem, IPinsViewProvider {

	public readonly metaContentConfigurableMgrs: { [memberName: string]: MetaContentConfigurableMgr } = {};
	protected useCaseMember?: UseCaseMgr;
	protected nonPinMembersInScriptOrder: (VoltageMgr | NameMemberMgr | UseCaseMgr | MetaContentConfigurableMgr)[] = [];
	protected pins: (ExtendedPinMemberMgr | PinMemberMgr)[] = [];
	protected pinGroup: PinGroupMemberMgr[] = [];
	private readonly nameMember: NameMemberMgr;
	private readonly solverRequirement: SolverRequirement;
	private readonly id: string;
	private pinConfigurableHeaders: NameToConfigurableHeader;
	private selectAll: boolean = true;
	private peripheralFilter: SelectionFilterGroup;
	private readonly solutionMember: FixedDataMember<PeripheralSolution, InterfaceInstance>;
	private readonly selection = {
		isOverridden: () => this.isOverridden(),
		getFiltersForOverridden: () => [this.getUsePeripheralMemberMgr().getValue()],
	};

	public constructor(
		runtime: Runtime,
		protected readonly iface: DeviceData.Interface,
		public readonly parentModuleMgr: ModuleInstanceMgr,
		solverOptions: Pick<InterfaceRequirement, "canShareWith" | "maxShareCount" | "filter">,
		nameParams: NameMemberMgrParams = { isReadOnly: false, isHidden: true },
	) {

		super(runtime, (options, member) => format(this, options, member));
		const formattersMap = runtime.getFormattersMap();
		this.runtime.interfaceMap.set(this.managedObject, this);
		this.addFixedMember(formattersMap, "$interface", iface);
		this.solutionMember = new FixedDataMember(this, formattersMap, "$solution", undefined);

		const { name, id } = this.runtime.getInterfaceInstanceNextNameAndId(this.iface.name);
		this.id = id;

		this.nameMember = new NameMemberMgr(
			this,
			formattersMap,
			{ default: name },
			nameParams,
		);

		this.nonPinMembersInScriptOrder = [this.nameMember];

		this.solverRequirement = new SolverRequirement(
			this, formattersMap, id, solverOptions, runtime.getPinMap());
		this.peripheralFilter = new SelectionFilterGroup();
		this.peripheralFilter.addSelection(this.selection);

		if (this.solverRequirement.getOverrideMgr()) {
			this.nonPinMembersInScriptOrder.push(this.solverRequirement.getOverrideMgr());
		}

		if (this.solverRequirement.getVoltageMgr()) {
			this.nonPinMembersInScriptOrder.push(this.solverRequirement.getVoltageMgr());
		}

		formattersMap.set(
			this.solverRequirement.getRequirementData(),
			(options, member) => format(this, options, member),
		);
	}

	public override getContainingInstanceMgrs() {
		if (this.parentModuleMgr) {
			return [this, ...this.parentModuleMgr.getContainingInstanceMgrs()];
		}
		return [this];
	}

	public override getContainingTreeNodes() {
		return this.parentModuleMgr?.getContainingTreeNodes() ?? [this.runtime.getInterfaceMgr(this.iface.name)];
	}

	public applyUIDefaults() {
		// nothing to do
	}

	public modifiedInUI() {
		if (this.parentModuleMgr) { // can be null in core pinmux case
			this.parentModuleMgr.modifiedInUI();
		}
	}

	public getPeripheralFilter() {
		return this.peripheralFilter;
	}

	public revealMember(_focusedListItemPath: string[]) {
	}

	// set current solution value if we are locking, or set it to any if unlocking
	public setLockStatus(status: boolean) {
		// set on the member manager
		setAssignedValue(status, this);

		// set on each of the pins
		_.each(this.pins, (pin) => setAssignedValue(status, pin.valueObjectMgr));

		// set on each pin in a multi-pin group
		if (this.getMultiPinMgr()) {
			_.each(this.getMultiPinMgr().getVisiblePinMgrs(), (pin) => setAssignedValue(status, pin));
		}
	}

	public hasIOSet() {
		const deviceData = this.runtime.getDeviceData();
		return deviceData.showIOSets ?
			_.some(this.iface.peripherals, (p) => !_.isEmpty(p.ioSets)) :
			false;
	}

	public getID() {
		return this.id;
	}

	public getName() {
		return this.getNameMgr().getValue();
	}

	public getNameMgr() {
		return this.nameMember;
	}

	public canRemove(): ActionState {
		return { enabled: ActionEnabled.YES };
	}

	public getSolverRequirements(): Peripheral[] | OptimizablePin[] {

		const solverReq = this.solverRequirement.getRequirementsForSolver();

		// If we have any multi-pin requirements, slice them off and add new ones
		// We do this because the number of them may have changed

		if (this.pinGroup.length > 0) {
			solverReq.pinRequirements =
				solverReq.pinRequirements
					.slice(0, this.pins.length)
					.concat(this.pinGroup[0].valueObjectMgr.getSolverRequirement());
		}

		return [solverReq];
	}

	public getSolverRequirement(): Peripheral {
		return this.getSolverRequirements()[0] as Peripheral;
	}

	public solveComplete() {

		// update the runtime instance accessible in meta content
		const solverReqData = this.solverRequirement.getRequirementData();

		this.solutionMember.changeData({
			peripheralName: solverReqData.solution.assignedToName,
			voltage: solverReqData.voltageSolution.assignedToName,
			ioSet: solverReqData.solution.ioSet,
			error: solverReqData.solution.errorText,
			warning: solverReqData.solution.warningText,
		});
		_.each([...this.pins, ...this.pinGroup], (p) => {
			p.valueObjectMgr.solveComplete();
		});
	}

	public setUseCase(useCaseName: string) {
		this.memberMgrs.$useCase.set(useCaseName, SetSource.USER_ASSIGN);
	}

	public setPeripheral(peripheralName: string) {
		this.memberMgrs.$assign.set(peripheralName, SetSource.USER_ASSIGN);
	}

	public setVoltage(voltage: string) {
		this.memberMgrs.$assignVoltage.set(voltage, SetSource.USER_ASSIGN);
	}

	public getUseCaseMgr() {
		return this.useCaseMember;
	}

	public getUsePeripheralMemberMgr() {
		return this.solverRequirement.getOverrideMgr();
	}

	public getConflictMgr() {
		return this.solverRequirement.getConflictMgr();
	}

	public getVoltageMgr() {
		return this.solverRequirement.getVoltageMgr();
	}

	public getFilteredPeripherals() {
		return this.peripheralFilter.filterOptions(
			this.selection,
			this.solverRequirement.getValidPeripherals(),
			(p) => [p.name]);
	}

	public isSelectAllEnabled() {
		return this.selectAll;
	}

	public getPinMemberMgrs() {
		return _.filter(this.pins, (pin) => pin.def.name in this.memberMgrs);
	}

	public getVisiblePinMgrs() {
		const memberPins = [
			...filterHiddenPinMembers(this.getPinMemberMgrs()),
			...this.getMultiPinMgr() ? this.getMultiPinMgr().getVisiblePinMgrs() : [],
		];
		return memberPins;
	}

	public getMultiPinMgr(): MultiPinMgr {
		return this.pinGroup.length === 1 ? this.pinGroup[0].valueObjectMgr : null;
	}

	public getPinConfigurablesHeaders(): NameToConfigurableHeader {
		return this.pinConfigurableHeaders;
	}

	public setSelectAll(val: boolean) {
		this.selectAll = val;
		_.each(this.pins, (p) => p.valueObjectMgr.setUsed(val, SetSource.USER_ASSIGN));
		_.each(this.pinGroup, (g) => {
			_.each(g.valueObjectMgr.getVisiblePinMgrs(), (p) => {
				p.setUsed(val, SetSource.USER_ASSIGN);
			});
		});
	}

	public getAddInstanceStatement(instIdentifier: string) {
		return createAddInterfaceInstanceStatement(this, instIdentifier);
	}

	public newPinReqs(
		reqs: PinReq[],
		component: HardwareComponent,
		signalTypes: SignalTypes = {},
		unchangedPinReqs: PinReq[] = [],
	) {
		// Remove the pins that aren't being changed

		const unchangedPins = _.intersectionWith(this.pins, unchangedPinReqs, (pin, req) => pin.def.name === req.name);
		_.pullAll(this.pins, unchangedPins);

		this.createPinsWrapper(
			() => {
				// create new pin members
				this.pins = _.map(reqs, (req) => {
					const unchangedPin = _.find(unchangedPins, (pin) => pin.def.name === req.name);
					if (unchangedPin) {
						return unchangedPin;
					}
					const preferredTypes = stringOrArrayToArray(signalTypes[req.name]);
					return new PinMemberMgr(
						new PinMgr(
							this.runtime,
							(options: FormatOptions) => format(this, options, req.name),
							req.name,
							this.peripheralFilter,
							req.interfacePins,
							fetchPinConnections(preferredTypes, component),
							_.extend({}, req.solverOptions, { preferredTypes }),
							this,
							undefined,
							this.isReservation(),
							this.parentModuleMgr,
							req.used,
							req.config,
						),
						this.runtime.getFormattersMap(),
						req,
						this,
						this.runtime.getPinmuxUIOptions().showSignals,
					);
				});
			},
		);
	}

	public override preRemove() {
		this.runtime.getFormattersMap().delete(this.solverRequirement.getRequirementData());
		this.runtime.removeInterfaceInstance(this);
		this.runtime.interfaceMap.delete(this.managedObject);
	}

	public getNonPinMembersInScriptOrder() {
		return this.nonPinMembersInScriptOrder;
	}

	public getAllVisibleMemberName() {
		const pinNames = _.map(this.getVisiblePinMgrs(), (p) => p.getName());
		if (this.getVoltageMgr()) {
			return [...pinNames, this.getVoltageMgr().def.name];
		}
		return pinNames;
	}

	public getEncodingTag() {
		return this.runtime.getFormattersMap().getEncodingTag(this.managedObject);
	}

	public getLockedAdversaries(): InterfaceInstanceMgr[] {
		const conflictPeripheralName = this.memberMgrs.$assign.getValue();
		const allInterfaceInstances = this.runtime.getAllInterfaceInstanceSetToPeripheral(conflictPeripheralName);
		const lockedAdversaries = _.chain(allInterfaceInstances)
			.without(this)
			.filter((i) => {
				const locked = i.getUsePeripheralMemberMgr().getSelectedOption() !== Const.ANY;
				return locked && i.getSolverRequirement().solution.errorText === ""
					&& this.getSolverRequirement().solution.errorText !== "";
			})
			.value();
		return lockedAdversaries;
	}

	public isReservation() {
		return false;
	}

	public getInterfaceConfigurables() {
		return this.iface.configurables;
	}

	public getUsedPins(): Set<string> {
		const reqs = this.getSolverRequirements();
		return getAssignedPins(reqs);
	}

	public applySolverValidation() {
		const solverReqData = this.solverRequirement.getRequirementData();
		if (solverReqData.solution.warningText) {
			this.runtime.getValidations().logWarning(
				{
					shortText: solverReqData.solution.warningText,
					longTexts: solverReqData.solution.warningDetailsText,
				},
				this.solverRequirement.getOverrideMgr());
		}
		if (solverReqData.solution.errorText) {
			this.runtime.getValidations().logError(
				{
					shortText: solverReqData.solution.errorText,
					longTexts: solverReqData.solution.errorDetailsText,
				},
				this.solverRequirement.getOverrideMgr());
		}
		if (solverReqData.voltageSolution.warningText) {
			this.runtime.getValidations().logWarning(
				{
					shortText: solverReqData.voltageSolution.warningText,
					longTexts: solverReqData.voltageSolution.warningDetailsText,
				},
				this.solverRequirement.getVoltageMgr());
		}
		if (solverReqData.voltageSolution.errorText) {
			this.runtime.getValidations().logError(
				{
					shortText: solverReqData.voltageSolution.errorText,
					longTexts: solverReqData.voltageSolution.errorDetailsText,
				},
				this.solverRequirement.getVoltageMgr());
		}
		_.each([...this.pins, ...this.pinGroup], (p) => {
			p.valueObjectMgr.applySolverValidation(p);
		});
	}

	public override getContainingModule() {
		if (!this.parentModuleMgr) {
			// for raw peripherals which will never have displayNames
			return { modInstMgr: null, memberPath: [] };
		}
		const me = _.find(this.parentModuleMgr.getInterfaceInstanceMemberMgrs(), (mgr) => mgr.valueObjectMgr === this);
		return { modInstMgr: this.parentModuleMgr, memberPath: [me.def.name] };
	}

	protected override getMembersInScriptOrder(options: SerializationOptions): AnyMemberMgr[] {

		// Ensure we serialize $useCase first, as it's the only thing that can affect
		// any other setting.  Otherwise, order doesn't matter (no side effects)

		const members = _.sortBy(super.getMembersInScriptOrder(options), (m) => m.def.name === "$useCase" ? 0 : 1);

		// $name is only meaningful in core-pinmux/reserve peripherals.  It really shouldn't
		// even exist if we are part of a module.  However, it has to exist for legacy
		// script compatibility.  But, we at least don't have to serialize it

		if (this.parentModuleMgr) {
			return _.reject(members, (m) => m.def.name === "$name");
		}
		return members;
	}

	protected createPinsWrapper(newPinCreator: () => void) {

		// remove members

		_.each(this.pins, (pinMem) => this.removeMember(pinMem));
		_.each(this.pinGroup, (pg) => this.removeMember(pg));

		// create new pin members

		newPinCreator();

		// clear solver reqs

		const solverReqData = this.solverRequirement.getRequirementData();
		solverReqData.pinRequirements = [];

		_.each(this.pins, (pinMem) => {
			solverReqData.pinRequirements.push(pinMem.valueObjectMgr.getSolverRequirement());
		});

		// create headers

		this.pinConfigurableHeaders
			= createHeader(
				_.flatMap(
					[
						...this.getVisiblePinMgrs(),
						..._.flatMap(this.pinGroup, (pg) => pg.valueObjectMgr.getVisiblePinMgrs()),
					],
					(p) => p.getNonBuiltInConfigurables(),
				),
			);
	}

	private isOverridden() {
		return this.getUsePeripheralMemberMgr().getValue() !== Const.ANY;
	}
}

export class PinmuxPeripheralInterfaceInstanceMgr extends InterfaceInstanceMgr {

	constructor(
		runtime: Runtime,
		iface: DeviceData.Interface,
		solverOptions: Pick<InterfaceRequirement, "canShareWith" | "maxShareCount" | "filter">,
		private readonly reservation: boolean,
	) {
		super(runtime, iface, null, solverOptions, { isReadOnly: false, isHidden: false });
		this.addBuildInConfigs();
	}

	public override onMemberChanged(mem: AMemberMgr<any>) {
		if (mem === this.useCaseMember) {
			this.useCaseChanged();
		}
	}

	public override getAllVisibleMemberName() {
		const nonPinMemberNames = _.map(this.getNonPinMembersInScriptOrder(), (m) => m.def.name);
		const pinMemberNames = _.map(this.getVisiblePinMgrs(), (p) => p.getName());
		const multiPinMemberNames = this.getMultiPinMgr() ?
			_.map(this.getMultiPinMgr().getVisiblePinMgrs(), (p) => p.getName()) : [];
		return [...nonPinMemberNames, ...pinMemberNames, ...multiPinMemberNames];
	}

	public override validate(validations: Validations): void {

		super.validate(validations);

		// simple validation for soc configurables

		_.chain(this.getInterfaceConfigurables())
			.map((c) => this.metaContentConfigurableMgrs[c.name])
			.each((m) => {
				if (m instanceof TextConfigurableMgr) {
					simpleValidation(m, validations);
				}
			})
			.value();
	}

	public override isReservation() {
		return this.reservation;
	}

	private addBuildInConfigs() {
		if (this.isReservation()) {
			// For reservation interface instance, just expose all pins
			this.createPinsWrapper(() => {

				const { pins } = createPinsAndPinGroupFromUseCase(
					this,
					this.runtime,
					createAllPinUseCase(this.iface),
				);

				this.pins = pins;
			});
		} else {
			const defaultUseCaseName = findDefaultUseCase(this.iface);

			addMetaContentConfigurableMgrs(
				this,
				_.map(this.getInterfaceConfigurables(),
					(def) => createMetaContentConfigurableMgr(def, this, this.iface.name, this.runtime, true),
				),
			);
			this.useCaseMember = new UseCaseMgr(this, this.runtime.getFormattersMap(), this.iface, defaultUseCaseName);
			this.useCaseChanged();
			this.nonPinMembersInScriptOrder.push(this.useCaseMember);
			this.nonPinMembersInScriptOrder.push(..._.values(this.metaContentConfigurableMgrs));
		}
	}

	private useCaseChanged() {
		const useCaseDef = this.iface.useCases[this.useCaseMember.getValue()];
		this.createPinsWrapper(() => {

			const { pins, pinGroup } = createPinsAndPinGroupFromUseCase(
				this,
				this.runtime,
				useCaseDef,
			);

			this.pins = pins;
			this.pinGroup = pinGroup;

			// reset ui and validation state of configurable members
			resetAndOverrideConfigsFromUseCase(
				this,
				useCaseDef,
			);
		});
	}
}

function stringOrArrayToArray(s: string | string[]) {
	return _.isString(s) ? [s] : s;
}
