import { TextConfigurableMgr } from "./configurables/textConfigurableMgr";
import { AObjectMgr } from "./object";
import { ModuleInstance, RuntimeInstance } from "public/runtime";
import { FormattersMap } from "../formatting/formattersMap";
import { shallowReadOnlyProxyHandler } from "./proxyHandlers/shallowReadOnlyProxyHandler";
import { SerializationOptions } from "../scripting/toScript";
import * as _ from "lodash";
import { forbiddenModification, isModuleInstance } from "../utils";
import { SetSource } from "./member";
import { ModuleInstanceMgr } from "./moduleInstance";
import { disableScriptingForCallback } from "../scripting/scriptingGuard";
import { NameConfigurable } from "public/defs";
/**
 * Common class for adding a name member to a configuration object.
 */

export interface NameMemberMgrParams {
	isReadOnly: boolean;
	isHidden: boolean;
	displayName?: string;
	isCIdentifier?: boolean;
}

interface NameTextConfig extends Partial<NameConfigurable> {
	default: string;
}

export class NameMemberMgr extends TextConfigurableMgr {
	constructor(
		public override readonly parentObjectMgr: AObjectMgr<RuntimeInstance>,
		formattersMap: FormattersMap,
		config: NameTextConfig,
		private readonly params: NameMemberMgrParams,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			{
				name: "$name",
				displayName: "Name",
				...config,
				readOnly: false,
				hidden: params.isHidden,
			},
		);

		const { graphFormat } = config;
		if (graphFormat && isModuleInstance(this.getParentRuntimeObj())) {
			this.graphFormat = () => disableScriptingForCallback(() => graphFormat(this.getParentRuntimeObj() as ModuleInstance));
		}
	}

	public override set(val: any, source: SetSource, forceWrite = false, reasonIfInvalid?: string) {
		if (this.params.isReadOnly) {
			forbiddenModification("$name is fixed for this instance");
		}
		super.set(val, source, forceWrite, reasonIfInvalid);
	}

	public getDisplayValue() {
		return this.graphFormat() ?? (this.params.displayName || this.value);
	}

	// The default value for $name is variable.
	// making it complicated to determine if it was user modified. 
	// Thus, mark it as always user created. This just means if the user only
	// modified $name on a non user created instance it will not get promoted to user created
	// and get removed. 
	public override isUserModified() {
		return false;
	}

	public override getScriptValue(options: SerializationOptions): { value: string, shouldQuoteStrings: boolean } {
		let name = this.value;
		if (options.cloneInstance) {
			// create/find copy name
			const instMgr = this.parentObjectMgr as ModuleInstanceMgr;
			const modMgr = instMgr.getModuleMgr();
			let counter = 1;
			const prefix = name + "_COPY";
			let copyName = prefix;
			while (_.find(modMgr.instances, (inst) => inst.getName() === copyName)) {
				copyName = `${prefix}${counter++}`;
			}
			name = copyName;
		}
		return { value: JSON.stringify(name), shouldQuoteStrings: false };
	}

	public isCIdentifier() {
		return this.params.isCIdentifier !== false; // Explicitly check for false as undefined implies true
	}

	protected override shouldSerialize(options: SerializationOptions) {
		return !(this.isFromMeta() && !this.isSideEffect(options)) && !this.params.isReadOnly;
	}

	protected override createManagedUIState() {
		return new Proxy(this.uiState, shallowReadOnlyProxyHandler);
	}

	private readonly graphFormat: () => string = () => null;
}
