import * as _ from "lodash";
import { NameMemberMgrParams } from "./name";
import * as DeviceData from "dataInterfaces";
import { Runtime } from "../resources/runtime";
import { InterfaceRequirement, SignalTypes } from "public/defs";
import { ModuleInstanceMgr } from "./moduleInstance";
import { InterfaceInstanceMgr } from "./interfaceInstance";
import { OptimizablePin, Peripheral, Pin } from "../solver/requirements";
import { clearSolution, updateSolution } from "../utils";
import { PinReq } from "./adaptModulePinReqs";
import { HardwareComponent } from "public/runtime";
import { format } from "../formatting/interfaceFormatter";

/**
 * This adapts a InterfaceInstanceMgr for an optimizable pin interface so that the solver is still handed requirement
 * objects that allow it to do it's optimization.  This allows meta-content to expose newly optimizable interfaces as
 * non-optimizable interfaces for legacy compatibility.
 */
export class OptimizableInterfaceAdapterMgr extends InterfaceInstanceMgr {

	// This is the OptimizablePin requirement that will be given to the solver

	private readonly adaptedSolverRequirement: OptimizablePin;

	public constructor(
		runtime: Runtime,
		iface: DeviceData.Interface,
		parentModuleMgr: ModuleInstanceMgr,
		solverOptions: Pick<InterfaceRequirement, "canShareWith" | "maxShareCount" | "filter">,
		nameParams: NameMemberMgrParams = { isReadOnly: false, isHidden: true },
	) {
		super(runtime, iface, parentModuleMgr, solverOptions, nameParams);

		this.adaptedSolverRequirement = new OptimizablePin(this.getID(), iface.name);
	}

	// When we are asked to create new pins, we pass that to the parent class, and then re-adapt our pin requirements
	// to match

	public override newPinReqs(
		reqs: PinReq[],
		component: HardwareComponent,
		signalTypes?: SignalTypes,
		unchangedPinReqs?: PinReq[],
	) {
		super.newPinReqs(reqs, component, signalTypes, unchangedPinReqs);

		// Ensure we can adapt it

		if (_.size(this.getSolverRequirement().pinRequirements) !== 1) {
			throw new Error(`Can only adapt one ${this.iface.name} pins, ${_.size(this.getSolverRequirement().pinRequirements)} requested`);
		}

		// Create a new Pin solver requirement based on the real one in the parent class

		const pinReq = _.first(this.getSolverRequirement().pinRequirements);
		const adaptedPinReq = new Pin(
			pinReq.getUnqualifiedName(),
			_.values(this.iface.interfacePins),
			pinReq.canShareWith,
			pinReq.reserved,
		);

		// Unregister any existing pins, assign the new pin, and then register that new pin

		const formattersMap = this.runtime.getFormattersMap();
		_.each(this.adaptedSolverRequirement.pinRequirements, (p) => formattersMap.delete(p));
		this.adaptedSolverRequirement.pinRequirements = [adaptedPinReq];
		formattersMap.set(adaptedPinReq, (options) => format(this, options, pinReq.getUnqualifiedName()));
	}

	// Called to provide the solver with requirements to solve for.  We need to adapt the peripheral/pin requirement
	// into a single optimizable pin requirement

	public override getSolverRequirements() {
		const { perfReq, pinReq, adaptedPinReq } = this.getRequirements();

		// Handle override, which could be set on the peripheral or pin

		if (pinReq.userOverride) {
			adaptedPinReq.userOverride = pinReq.userOverride;
		} else if (perfReq.userOverride) {
			adaptedPinReq.userOverride = this.peripheralToPin(perfReq.userOverride);
		} else {
			delete adaptedPinReq.userOverride;
		}

		// Allowing conflicts could be set at the perf or pin level

		adaptedPinReq.userAllowedConflicts = pinReq.userAllowedConflicts || perfReq.userAllowedConflicts;

		// Copy over settings from the pins only
		// A shared peripheral is ignored (only checked at the pin level)
		// Voltage requirements aren't supported for optimizable interfaces
		// IO sets don't make sense for a single pin

		adaptedPinReq.used = pinReq.used;
		adaptedPinReq.restrictTo = pinReq.restrictTo;
		adaptedPinReq.connectedToHardware = pinReq.connectedToHardware;
		adaptedPinReq.preferredPins = pinReq.preferredPins;

		return [this.adaptedSolverRequirement];
	}

	// This is overridden to be the same implementation.  This ensures that getSolverRequirement() continues to return
	// a peripheral style requirement

	public override getSolverRequirement() {
		return super.getSolverRequirements()[0] as Peripheral;
	}

	// Called when the solver has completed.  This needs to adapt the optimizable pin requirement back into a 
	// peripheral/pin style requirement

	public override solveComplete() {
		const { perfReq, pinReq, adaptedPinReq } = this.getRequirements();

		if (_.isEmpty(adaptedPinReq.solution.errorText)) {

			// No error - determine peripheral from the pin solution and copy the pin solution

			updateSolution(perfReq.solution, this.pinToPeripheral(adaptedPinReq.solution.assignedPeripheralPin));
			updateSolution(
				pinReq.solution,
				adaptedPinReq.solution.assignedToName,
				adaptedPinReq.solution.assignedPeripheralPin,
				adaptedPinReq.solution.assignedInterfacePin,
				adaptedPinReq.solution.assignedMuxMode);
		} else {

			// Show the error on the pin solution only

			clearSolution(perfReq.solution);
			clearSolution(pinReq.solution);
			pinReq.solution.errorText = adaptedPinReq.solution.errorText;
			pinReq.solution.errorDetailsText = adaptedPinReq.solution.errorDetailsText;
		}

		// Clear or copy warnings regardless

		pinReq.solution.warningText = adaptedPinReq.solution.warningText;
		pinReq.solution.warningDetailsText = adaptedPinReq.solution.warningDetailsText;

		super.solveComplete();
	}

	// This works because we know there is a one-to-one mapping of peripherals to device pins due to this being an 
	// optimizable interface

	private peripheralToPin(peripheralName: string) {
		return _.first(_.values(this.runtime.getDeviceData().peripherals[peripheralName].peripheralPins)).pinMappings[0].name;
	}

	private pinToPeripheral(pinName: string) {
		return this.runtime.getDeviceData().peripheralPins[pinName].peripheralName;
	}

	// Assumes we only have one pin, which is asserted in newPinReqs

	private getRequirements() {
		const perfReq = this.getSolverRequirement();
		const pinReq = perfReq.pinRequirements[0];
		const adaptedPinReq = this.adaptedSolverRequirement.pinRequirements[0];
		return { perfReq, pinReq, adaptedPinReq };
	}
}
