import { http } from "./http";
import { parseJSON } from "./utils";

interface UserInfo {
	firstname: string;
	lastname: string;
	uid: string;
	email: string;
	permanentid: string;
}

interface IdleInterval {
	idleTimeout: number;
}

export async function getIdleInterval() {
	const xmlhttp = await http.get("/timeouts/getIdleInterval");
	return parseJSON<IdleInterval>(xmlhttp).idleTimeout;
}

export async function getUserInfo() {
	const rawUserInfo = await http.get("/api/queryUserStatus/");
	if (rawUserInfo) {
		const parsedUserInfo = parseJSON<UserInfo>(rawUserInfo);
		return parsedUserInfo.firstname || parsedUserInfo.uid;
	}
	return null;
}
