import * as _ from "lodash";
import { Simulation, SpiceSimulation, ExternalSimulation } from "public/defs";

export function isExternalSimulation(def: Simulation): def is ExternalSimulation {
	return (def as ExternalSimulation).onLaunch !== undefined && (def as ExternalSimulation).onComplete !== undefined;
}

export function isSpiceSimulation(def: Simulation): def is SpiceSimulation {
	return (def as ExternalSimulation).onComplete === undefined && (def as SpiceSimulation).onLaunch !== undefined;
}

export class SimulationTooIntensiveError extends Error {
	constructor() {
		super("Simulation too Intensive");
	}
}

export class SimulationFailedError extends Error {
	constructor(public readonly consoleOutput: string) {
		super("Simulation Failed");
	}
}
