import * as _ from "lodash";
import { AbstractChoice, RelatedChoices, RelatedSharedChoices } from "./common";
import { SolutionMap } from "../choices";
import { PinConflictTracker } from "../conflictTracker";
import { ChoiceValidator } from "./choiceValidator";
import {
	chooseAtLeastOneOfOnlyIf,
	dependentChoices,
	mutuallyExcludeUnsharedChoices,
	mutuallyExclusive,
} from "../clauseGeneration";
import { formatNameChoice, nameChoices } from "../debug";
import { Pin } from "../requirements";
import { clearSolution, updateSolution } from "../../utils";
import * as data from "dataInterfaces";
import { Optimizations, Restrictive } from "../optimizations";

interface ParentChoice {
	id: number;
	parentChoice: {
		id: number;
	};
}

// -----------------------------------------------------------------------------
// DevicePinChoices
// A factory for creating a choice of a specific device pin to meet a pin 
// requirement.  Also eventually generates the clauses for all the 
// relationships of these choices and peripheral choices
// -----------------------------------------------------------------------------

export class DevicePinChoices {
	// public for IOSet/power choice dependencies
	public readonly byParent = new RelatedChoices<number, DevicePinChoices.Choice>();

	// public for minimizeOptimizablePins
	public readonly freesOneOptimizablePin: Record<string, RelatedChoices<number, DevicePinChoices.Choice>> = {};

	private readonly byDevicePin = new RelatedSharedChoices<string, DevicePinChoices.Choice>();
	private readonly byRequirement = new RelatedChoices<number, DevicePinChoices.Choice>();
	private readonly sometimesRestrictive = new RelatedChoices<number, DevicePinChoices.Choice>();
	private readonly bySharedPeripheralPin = new RelatedSharedChoices<string, DevicePinChoices.Choice>();

	constructor(
		private readonly choiceValidator: ChoiceValidator,
		private readonly conflictAllower: PinConflictTracker,
		private readonly optimizations: Optimizations,
	) { }

	public newChoice(
		interfacePinChoice: ParentChoice,
		peripheralPin: data.PeripheralPin,
		devicePin: data.DevicePin,
		pinReq: Pin) {

		if (!this.choiceValidator.isValid(pinReq, devicePin, peripheralPin)) {

			// Ensure the key is added, so we can't choose an interface pin with no ball choices

			this.byRequirement.addKey(interfacePinChoice.id);
			return;
		}

		const choice = new DevicePinChoices.Choice(peripheralPin, devicePin, pinReq);
		this.byRequirement.get(interfacePinChoice.id).push(choice);

		if (this.conflictAllower.areConflictsAllowed(pinReq)) {

			// Add it under it's own unique category of shared pins

			this.byDevicePin.get(devicePin.name).pushShared(choice, "allowedToConflict");

		} else if (pinReq.canShareWith) {

			// Include the peripheral pin name in the key
			// Ensures we only share the same peripheral pin, not any peripheral pin with the same key

			this.byDevicePin.get(devicePin.name)
				.pushShared(choice, peripheralPin.name + pinReq.canShareWith);

			// For each peripheral pin, group the various mapping choices together to the same pin
			// We can then ensure that any choice involving a particular peripheral pin will exclude
			// mappings that aren't to the same device pin

			this.bySharedPeripheralPin.get(peripheralPin.name)
				.pushShared(choice, devicePin.name);
		} else {
			this.byDevicePin.get(devicePin.name).push(choice);
		}

		const restrictions = this.optimizations.restrictions(pinReq);
		if (_.some(restrictions, (restriction) => Restrictive.SOMETIMES === restriction)) {
			this.sometimesRestrictive.get(interfacePinChoice.id).push(choice);
			_.each(restrictions, (restriction, interfaceName) => {
				if (Restrictive.SOMETIMES === restriction && !(devicePin.name in this.optimizations.getFreePins(interfaceName))) {
					if (!this.freesOneOptimizablePin[interfaceName]) {
						this.freesOneOptimizablePin[interfaceName] = new RelatedChoices<number, DevicePinChoices.Choice>();
					}
					this.freesOneOptimizablePin[interfaceName].get(interfacePinChoice.id).push(choice);
				}
			});
		}

		this.byParent.get(interfacePinChoice.parentChoice.id).push(choice);
	}

	public generateClauses() {
		chooseAtLeastOneOfOnlyIf(this.byRequirement, null,
			"each pin requirement must choose one device pin, but only if the corresponding interface pin was chosen");
		dependentChoices(this.byRequirement, "device pins can only be chosen if their interface pin is also chosen");
		mutuallyExcludeUnsharedChoices(this.byDevicePin, "only choose a device pin once, unless shared");
		mutuallyExcludeUnsharedChoices(this.bySharedPeripheralPin,
			"only choose a device pin mapping once for a shared peripheral");
		mutuallyExclusive(this.sometimesRestrictive, null,
			"ensure that only one device pin is picked if the choice impacts optimizable pin availability");
	}
}

export namespace DevicePinChoices {
	export class Choice extends AbstractChoice {

		public applied = false; // public for PowerChoices.Choice

		constructor(
			public readonly peripheralPin: data.PeripheralPin,
			public readonly devicePin: data.DevicePin,
			public readonly pinReq: Pin) {
			super();

			// Clear the solution so we can tell if it's later written to

			clearSolution(this.pinReq.solution);

			if (nameChoices) {
				this.name = "Device Pin " + formatNameChoice(pinReq) + "->" + devicePin.name;
			}
		}

		public apply(solutionMap: SolutionMap) {
			// If the solution was written to, then another pin was also chosen for it,
			// so we'll go with that choice instead.  This can occur because we call 
			// chooseAtLeastOneOf instead of chooseOneOf for the possible pin choices.
			// That allows us to greatly reduce the number of clauses if there are many
			// choices for a pin (96 choices == 4500+ clauses if we want to ensure that 
			// no more than one is chosen, and that can add up fast if there are also
			// many peripheral choices).

			if ("" === this.pinReq.solution.assignedToName) {
				const muxMode = _.find(this.devicePin.mux.muxSetting, (i) => i.peripheralPin === this.peripheralPin).mode;
				updateSolution(
					this.pinReq.solution, this.devicePin.name, this.peripheralPin.name, this.peripheralPin.interfacePin.name, muxMode);

				const ball = this.devicePin.name;
				const devicePins = solutionMap.devicePins[ball] || (solutionMap.devicePins[ball] = []);
				devicePins.push(this.pinReq);

				const name = this.peripheralPin.name;
				const peripheralPins = solutionMap.peripheralPins[name] || (solutionMap.peripheralPins[name] = []);
				peripheralPins.push(this.pinReq);

				this.applied = true;
			}
		}
	}
}
