import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../../graph/styling/graphStyles";
import { Multiplier } from "clockTree";
import { ISimpleDropDownNodeProps, SimpleDropDownNode } from "../../graph/nodes/SimpleDropDownNode";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";

// A multiplier node is a rectangle with the multiplication amount in the middle.  If the multiplication is configurable, then that 
// amount becomes a drop down

type IProps = Omit<
	ISimpleDropDownNodeProps<ClockIpInstanceMgr, PinFrequencyConfigurableMgr, number>,
	"formatPrefix" | "values" | "mgr" | "currentValue">;

export function MultiplierNode(props: IProps & ClassesType) {
	const ipInstance = props.node.inst.getIpInstance() as Multiplier;
	const mgr = props.node.inst.memberMgrs.multiplyValue;
	const value = mgr?.getValue() ?? _.first(ipInstance.multiplyValues);
	return <SimpleDropDownNode
		{...props}
		formatPrefix={"X "}
		values={ipInstance.multiplyValues}
		currentValue={value}
		mgr={mgr}
	/>;
}
