import React = require("react");
import * as _ from "lodash";
import { ILocalFileBrowseProps } from "../local/LocalFileBrowse";
import { getChildrenWithProps } from "../cloud/CloudFileBrowse";

export class EclipseFileBrowse
	extends React.Component<ILocalFileBrowseProps> {

	public override render() {
		return getChildrenWithProps(this.props.id, this.handleButtonClick, this.props.children);
	}

	private handleButtonClick = () => {
		// canceling the eclipse browse dialog doesn't return a string
		const path = this.props.folder ?
			eclipseOpenBrowseFolderDialog() :
			eclipseOpenBrowseFileDialog(
				undefined,
				undefined,
				this.props.accept ?
					fixEclipseFileExtensionFilters(this.props.accept) :
					undefined,
			);
		if (_.isString(path)) {
			this.props.onChange(path);
		}
	}
}

function fixEclipseFileExtensionFilters(inputFilter: string) {
	return _.chain(inputFilter)
		.split(",")
		.map((s) => {
			return `*${_.trim(s)}`;
		})
		.join(",")
		.value();
}
