import * as React from "react";
import { IconButton } from "../../imports/material-ui-imports";
import { Tooltip } from "../Tooltip";
import { IOutputActions } from "../actions/IOutputActions";
import { OutputViewMgr } from "../../services/ui/outputView";
import { getViewIcon } from "../ComponentUtils";
import { spacingUnit, ATheme, ColorIndex } from "../styles/themes";

interface IProps {
	mgr: OutputViewMgr;
	actions: IOutputActions;
	disabled: boolean;
	theme: ATheme;
}

const iconStyle = {
	padding: spacingUnit * 1.5,
};

export class OutputMenuEntry extends React.Component<IProps, {}> {

	public override render() {
		const { mgr } = this.props;
		const isDisplayed = mgr.isDisplayed();
		return (
			<Tooltip
				disabled={this.props.disabled}
				title={this.decodeCardStatus(isDisplayed) + " " + mgr.displayName}
				noWrap
			>
				<IconButton
					id={mgr.id + "Icon"}
					onClick={() => this.props.actions.toggleOutputView(mgr)}
					style={
						{
							...iconStyle,
							color: this.props.disabled ?
								this.props.theme.colors[ColorIndex.BACKGROUNDCOLOR] :
								isDisplayed ?
									this.props.theme.colors[ColorIndex.SELECTEDICONCOLOR] :
									this.props.theme.colors[ColorIndex.ICONCOLOR],
						}
					}
					disabled={this.props.disabled}
				>
					{getViewIcon(mgr)}
				</IconButton>
			</Tooltip >
		);
	}

	private decodeCardStatus = (status: boolean) => {
		return status ? "Hide" : "Show";
	}

}
