import React = require("react");
import * as _ from "lodash";
import { ErrorStore } from "../services/errorStore";

// This class is for components that generate state asynchronously from props, typically by fetching
// server-side data.  It's implementing the lifecycle methods based on advice at the below link
//
// https://reactjs.org/blog/2018/03/27/update-on-async-rendering.html#fetching-external-data-when-props-change

export abstract class AsyncComponent<IProps extends { errorStore: ErrorStore }, IState>
	extends React.Component<IProps, IState> {

	private currentAsyncLoad: Promise<void> = null;

	constructor(props: IProps) {
		super(props);
	}

	/**
	 * Called immediately after a component is mounted. Setting state here will trigger re-rendering.
	 */
	public override componentDidMount() {
		this.safelyFetchAsyncData();
	}

	/**
	 * Called to determine whether the change in props and state should trigger a re-render.
	 *
	 * `Component` always returns true.
	 * `PureComponent` implements a shallow comparison on props and state and returns true if any
	 * props or states have changed.
	 *
	 * If false is returned, `Component#render`, `componentWillUpdate`
	 * and `componentDidUpdate` will not be called.
	 */
	public override shouldComponentUpdate(nextProps: Readonly<IProps>, nextState: Readonly<IState>) {

		// If the target indicated that props changed, return false and begin fetching data.  The calls to setState will
		// trigger the re-render vs the prop change.  That ensures we won't render with outdated async data

		if (this.propsChanged(nextProps, nextState)) {
			this.safelyFetchAsyncData();
			return false;
		}
		return true;
	}

	/**
	 * Called immediately before a component is destroyed. Perform any necessary cleanup in this method, such as
	 * cancelled network requests, or cleaning up any DOM elements created in `componentDidMount`.
	 */
	public override componentWillUnmount() {
		// TODO: ideally we should use cancelable promises

		this.currentAsyncLoad = null;
	}

	// Derived classes should override to only update state if some props change
	protected abstract propsChanged(prevProps: Readonly<IProps>, nextState: Readonly<IState>): boolean;

	// Derived classes should implement this to null out this.state so rendering is defaulted
	protected abstract clearAsyncData(): void;

	// Derived classes should implement this to fetch state from props
	protected abstract fetchAsyncData(): Promise<Partial<IState>>;

	protected isLoading() {
		return this.currentAsyncLoad !== null;
	}

	protected reFetchAsyncData() {
		this.safelyFetchAsyncData();
	}

	// Ideally promises would be cancelable, but for the time it is processing all incoming requests,
	// and only set state on the last (most recent) operation
	private safelyFetchAsyncData() {
		const self = this.currentAsyncLoad = (this.currentAsyncLoad || Promise.resolve())
			.then(() => this.clearAsyncData())
			.then(() => this.fetchAsyncData())
			.then((state) => {
				if (this.currentAsyncLoad === self) { // are we the last operation?
					this.currentAsyncLoad = null;
					if (!_.isEmpty(state)) {
						this.setState(state as IState);
					}
				}
			})
			.catch((e) => this.props.errorStore.registerException(e));
	}
}
