import * as React from "react";
import * as _ from "lodash";
import type * as Plotly from "plotly.js-basic-dist-min";
import { ErrorStore } from "../../services/errorStore";
import { assertNeverThrows } from "../../services/utils";
import { useTheme } from "../../imports/material-ui-imports";
import { tiRed } from "../styles/colors";

// This is a component responsible for:
// 1) Exposing plotly as a react component
// 2) Adapting the somewhat broken plotly click events to correctly distinguish click and double click
// 3) Applying our custom theme to plotly layouts, regardless of what is passed in
//
// The intention is that it will be used anywhere a graph is required (simulation results, custom views, etc)

// cSpell:ignore relayout, ohlc

export interface IThemedPlotlyProps {
	plotly: typeof Plotly; 										// Plotly is lazily loaded and progress must be handled above this component
	data: Plotly.Data[],										// The three plotly data structures: data, layout and config
	layout: Partial<Plotly.Layout>,
	config: Partial<Plotly.Config>,
	errorStore: ErrorStore,										// Internal error store to handle async failures
	activeButtonTitle?: string;									// Which custom button (if any) is active
	onClick?: (event: Plotly.PlotMouseEvent) => void;			// Plotly events, adapted to split click from double click
	onDoubleClick?: (event: Plotly.PlotMouseEvent) => void;
	onReLayout?: (event: Plotly.PlotRelayoutEvent) => void;
}

export function ThemedPlotly({
	plotly,
	data,
	errorStore,
	layout,
	config,
	onClick,
	onDoubleClick,
	onReLayout,
	activeButtonTitle,
}: IThemedPlotlyProps) {

	// Plotly has click and double click events, but the click event also fires on a double click.  To distinguish, we 
	// look at the event detail which should be 1 in the single click case and 2 in the double click case.  When a 
	// click is received, we start a short timer and wait to see if a double click is registered within the timeout.
	// The timer is stored in a useRef, and canceled on a re-render or subsequent click

	const timer = React.useRef(null);

	function cleanupTimer() {
		if (timer.current) {
			clearTimeout(timer.current);
		}
	}

	React.useEffect(() => cleanupTimer, []);

	const onAnyClick = React.useCallback((event: Plotly.PlotMouseEvent) => {
		cleanupTimer();
		if (event.event.detail === 1) {
			timer.current = setTimeout(() => onClick(event), 200);
		} else {
			onDoubleClick(event);
		}
	}, [onClick, onDoubleClick, timer]);

	const theme = usePlotlyTheme();

	React.useEffect(() => {
		let plot: Plotly.PlotlyHTMLElement;
		assertNeverThrows(errorStore, async () => {

			// Apply theming to plotly layout/data and then create a new plot.
			// Note that while plotly has functions other than newPlot that should be more efficient if it's known 
			// only some of the data has changed, it was found that the bottleneck for our use case is hit regardless
			// of which function is used.  Using only newPlot keeps the code simpler

			plot = await plotly.newPlot(
				"PlotlyRoot",
				themeData(theme, data),
				themeLayout(theme, layout),
				config);

			// If there are toggleable mode bar buttons, we have to explicitly add/remove the active state from them.
			// Plotly does not provide a way to indicate what the button toggle state should be at the start, and it 
			// doesn't correctly track it's state if there's more than one toggleable button (custom or not)

			_.each(config?.modeBarButtonsToAdd, (button) => {
				if (!_.isString(button)) {
					const title = button.title;
					if (title === activeButtonTitle) {
						document.querySelector(`[data-title="${title}"]`).classList.add("active");
					} else {
						document.querySelector(`[data-title="${title}"]`).classList.remove("active");
					}
				}
			});

			// Register for events

			plot.on("plotly_relayout", onReLayout);
			plot.on("plotly_click", onAnyClick);
		});

		// Destroy when unmounting/rerendering

		return () => plotly.purge(plot);
	}, [
		plotly,
		data,
		errorStore,
		layout,
		config,
		onAnyClick,
		onReLayout,
		activeButtonTitle,
		theme,
	]);

	// This is the div where plotly will attach
	return <div id="PlotlyRoot" style={plotlyRootStyle} />;
}

const plotlyRootStyle = {
	height: "100%",
	width: "100%",
	overflow: "hidden",
};

// Applies our theme colours to lines/markers

function themeData(theme: PlotlyTheme, data: Plotly.Data[]) {
	return _.map(data, (plot) => {
		const clone = _.clone(plot);
		if (clone.type !== "pie") {
			clone.line = {
				...clone.line,
				color: theme.line,
			};
		}
		if (clone.type !== "ohlc" && clone.type !== "candlestick") {
			clone.marker = {
				...clone.marker,
				color: theme.marker,
			};
		}
		return clone;
	});
}

// Applies our theme colours to grid lines, spike lines, hover labels, background etc

function themeLayout(theme: PlotlyTheme, layout: Partial<Plotly.Layout>) {
	return {
		..._.mapValues(layout, (value: any, key) => {
			if (key.includes("axis")) {
				return {
					...value,
					gridcolor: theme.grid,
					color: theme.text,
					spikecolor: value.showspikes ? theme.spikecolor : undefined,
				};
			}
			return value;
		}),
		paper_bgcolor: theme.background,
		plot_bgcolor: theme.background,
		hoverlabel: {
			...layout?.hoverlabel,
			bgcolor: theme.background,
			bordercolor: theme.text,
		},
	};
}

// Adjust colours based on if this is a dark or light theme

function usePlotlyTheme() {
	const theme = useTheme();
	return {
		background: theme.palette.background.default,
		text: theme.palette.text.primary,
		grid: theme.palette.type === "dark" ? theme.palette.grey[800] : undefined,
		line: theme.palette.primary.main,
		marker: tiRed[50],
		spikecolor: "#999999",
	};
}

type PlotlyTheme = ReturnType<typeof usePlotlyTheme>;
