import * as _ from "lodash";
import * as React from "react";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { HardwareMemberMgr } from "../../../services/objectManagers/hardwareMember";
import { CHardware } from "./Hardware";
import { assertUnreachable } from "../../../services/utils";
import { ResourceLoader } from "../../../services/resources/metaContentLoaders/resourceLoader";
import { CEnumerationConfigurable } from "./EnumerationConfigurable";
import { CBooleanConfigurable } from "./BooleanConfigurable";
import { CNumericConfigurable } from "./NumericConfigurable";
import { CFormattedTextConfigurable } from "./FormattedTextConfigurable";
import { CFileConfigurable } from "./FileConfigurable";
import { CMultiValueEnumerationConfigurable } from "./MultiValueEnumerationConfigurable";
import { CTextConfigurable } from "./TextConfigurable";
import { CDateConfigurable } from "./DateConfigurable";
import { PinFrequencyConfigurable } from "./PinFrequencyConfigurable";
import { Validations } from "../../../services/objectManagers/validations";
import { MetaContentConfigurableMgr } from "../../../services/objectManagers/configurables/configurable";
import { MultiInstanceReferenceConfigurable } from "./MultiInstanceReferenceConfigurable";
import { SingleInstanceReferenceConfigurable } from "./SingleInstanceReferenceConfigurable";
import { ConfigurableComponent } from "../../../services/objectManagers/configurables/configurableComponent";
import { CUnitsConfigurable } from "./UnitsConfigurable";
import { ConfigStoreActions } from "../../../services/configStore";
import { CButtonConfigurable } from "./ButtonConfigurable";

export interface IConfigurableProps extends IGlobalServiceProps {
	mgr: MetaContentConfigurableMgr | HardwareMemberMgr,
	actions: ConfigStoreActions,
	formatter: IFormatter,
	resourceLoader: ResourceLoader,
	validations: Validations;
	displayScriptName: boolean;
}

// Wrapper component to delegate rendering a configurable to a particular component
// While this looks like it could be changed to a lookup table, we need to guard the mgr type passed in, so mapType in
// utils wouldn't work.  However, the switch is isolated and clear, even if technically it comes in as high cyclomatic
// complexity
// eslint-disable-next-line complexity
export function CConfigurable(props: IConfigurableProps) {
	const { mgr, ...rest } = props;
	switch (mgr.ui) {
		case ConfigurableComponent.CHardware:
			return <CHardware {...rest} mgr={mgr} />;
		case ConfigurableComponent.CDateConfigurable:
			return <CDateConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CEnumerationConfigurable:
			return <CEnumerationConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CBooleanConfigurable:
			return <CBooleanConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CNumericConfigurable:
			return <CNumericConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CTextConfigurable:
			return <CTextConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CFormattedTextConfigurable:
			return <CFormattedTextConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CFileConfigurable:
			return <CFileConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CMultiValueEnumerationConfigurable:
			return <CMultiValueEnumerationConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.CButtonConfigurable:
			return <CButtonConfigurable<unknown> {...rest} mgr={mgr} />;
		case ConfigurableComponent.CUnitsConfigurable:
			return <CUnitsConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.PinFrequencyConfigurable:
			return <PinFrequencyConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.SingleInstanceReferenceConfigurable:
			return <SingleInstanceReferenceConfigurable {...rest} mgr={mgr} />;
		case ConfigurableComponent.MultiInstanceReferenceConfigurable:
			return <MultiInstanceReferenceConfigurable{...rest} mgr={mgr} />;
		default:
			assertUnreachable(mgr);
	}
}
