import * as _ from "lodash";
import * as bigInt from "big-integer";
import { NumStrFormatType, Radix } from "../../utils/numberUtils";
import * as bigIntUtil from "../../utils/bigIntUtils";
import { Validations } from "../validations";
import { NumericConfigurableMgr } from "./numericConfigurableMgr";

export class BigIntConfigurableMgr extends NumericConfigurableMgr<bigInt.BigInteger> {

	public override getScriptValue() {
		const strVal = this.getValueAsString();
		const scriptValue =
			`system.utils.bigInt("${_.startsWith(strVal, "0x")
				? strVal.substring(2) : strVal}",${this.getRadix()})`;
		return {
			value: scriptValue,
			shouldQuoteStrings: false,
		};
	}

	public override getFormats(): NumStrFormatType[] {
		return this.getRadix() === Radix.HEX ? ["hex", "posInt"] : ["hex", "int"];
	}

	public override validate(validations: Validations) {
		super.validate(validations);
		if (!bigIntUtil.isInRange(this.value, this.def.range)) {
			validations.logError(`Must be in the range of ${this.def.range.join(" to ")}`, this);
		}
	}

	protected override validateValue(val: bigInt.BigInteger) {
		if (!bigInt.isInstance(val)) {
			this.typeMismatch("BigInteger", typeof val);
		}
	}

	protected override stringToNum(val: string) {
		return bigIntUtil.stringToNum(val);
	}

	protected override numToString(val: bigInt.BigInteger) {
		return bigIntUtil.numToString(val, this.def.displayFormat);
	}

	protected override isEqual(val: bigInt.BigInteger) {
		return this.value.equals(val);
	}
}
