import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { PositionedDiv } from "../nodes/PositionedDiv";
import { Tooltip } from "../../Tooltip";
import * as Layout from "../types/layoutTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// This component renders a tooltip for the frequency value if a edge is selected

interface IFrequencyProps<PortMgr extends AnyMemberMgr> {
	selectedEdge: Layout.Edge<PortMgr>;
	getEdgeToolTip: (edge: Layout.Edge<PortMgr>) => string;
}

// Note that the frequency on a specific edge can change as you update module settings.  As such, we can't use 
// React.memo on this function, as we explicitly WANT to update if the parent re-renders

export function EdgeTooltip<PortMgr extends AnyMemberMgr>(
	{ selectedEdge, getEdgeToolTip, classes }: IFrequencyProps<PortMgr> & ClassesType
) {
	if (!selectedEdge) {
		return null;
	}

	const tooltip = getEdgeToolTip(selectedEdge);
	if (!tooltip) {
		return null;
	}

	return <PositionedDiv
		x={(selectedEdge.start.x + selectedEdge.end.x) / 2}
		y={(selectedEdge.start.y + selectedEdge.end.y) / 2}
		width={1}
		height={1}
		className={classes.positionedDiv}
	>
		<Tooltip title={tooltip} open={true} />
	</PositionedDiv>;
}
