import * as React from "react";
import * as _ from "lodash";
import { TransformWrapper, TransformComponent, ReactZoomPanPinchHandlers, ReactZoomPanPinchRef } from "react-zoom-pan-pinch";
import { memoizeOne } from "../../services/utils";
import { Position } from "public/runtime";
import { DebouncedContainerDimensions } from "./DebouncedContainerDimensions";

// This component will handle zoom and pan of an underlying child component.  It will automatically zoom in on the 
// child so that the view is filled, and it will re-zoom if the containing area is re-sized (unless the user has 
// already zoomed in themselves).

// Props passed to floating content if floating content is a function
export interface IFZoomFloatingContentProps {
	zoomIn(this: void): void;
	zoomOut(this: void): void;
	reset(this: void): void;
}

// Props passed to children (ie what is zoomed on) if children is a function
interface IChildProps<T> {

	// Passed only if the corresponding events are passed to the main component.  The idea is that some underlying 
	// component(s) have mouseDown/Up events that fire with data and the mouse event object.  This class will adjust 
	// the x,y position according to the current scale/pan and re-fire the event on the passed in to WithZoom.  That 
	// allows the parent component to operate on the real x,y positions within whatever it is asking to be zoomable.

	onMouseDown(event: React.MouseEvent, data: T): void;
	onMouseUp(event: React.MouseEvent, data: T): void;
	onClick(event: React.MouseEvent, data: T): void;
}

interface IProps<T, AdditionalProps> {
	childXOrigin: number;
	childYOrigin: number;
	childWidth: number;
	childHeight: number;

	// Non-zoomable content to render on the right side of the graph.  Useful for legends/zoom controls etc
	floatingContentRight?: React.ReactElement | ((props: IFZoomFloatingContentProps & AdditionalProps) => React.ReactElement);

	// Non-zoomable content to render on the left side of the graph.  Useful for legends/zoom controls etc
	floatingContentLeft?: React.ReactElement | ((props: IFZoomFloatingContentProps & AdditionalProps) => React.ReactElement);

	// The components to be zoomed.  Pass as a function if part of the component set can be dragged.
	children: React.ReactNode | ((props: IChildProps<T>) => React.ReactNode);

	// Functions for mouse events.  The data is whatever the underlying children fire back up.
	onMouseDown(position: Position, data: T): void;
	onMouseMove(position: Position): void;
	onMouseUp(position: Position, data?: T): void;
	onClick(position: Position, data?: T): void;
	additionalProps: AdditionalProps;
}

interface IZoomProps<T, AdditionalProps> extends IProps<T, AdditionalProps> {
	width: number;
	height: number;
}

interface IState<T> {
	keyValueAfterZoomOrPan: string;
	positionX: number;
	positionY: number;
	scale: number;
	dragData: T
}

// This is memoized so that the same style object is passed each time, assuming props does not change

const getSizeAsStyle = memoizeOne((width: number, height: number) => {
	return {
		width: `${width}px`,
		height: `${height}px`,
	};
});

const floatingContentLeftStyle = {
	// Prevent it from using space that the graph will use
	position: "absolute",

	// Need to use transform here vs top:0 as there is a brief second where it would render on the nav bar as it's mounting
	transform: "translate(0px, 4px)",

	// Ensure it's over top of the graph
	zIndex: 2,
} as const;

const floatingContentRightStyle = {
	...floatingContentLeftStyle,
	right: 0, // push to the far right instead of top
	textAlign: "right",
} as const;

const buttonZoomRate = 1.5;

class ZoomComponent<T, AdditionalProps> extends React.Component<IZoomProps<T, AdditionalProps>, IState<T>> {

	private ref: HTMLDivElement = null;

	constructor(props: IZoomProps<T, AdditionalProps>) {
		super(props);
		const [x, y] = this.getPanSettingToCenterGraph();
		this.state = {
			keyValueAfterZoomOrPan: null,
			positionX: x,
			positionY: y,
			scale: this.getScaleToViewAll(),
			dragData: null,
		};
	}

	public override render() {

		// In order for the child to fill the view, we need to find a scale factor based on the parent width/height and
		// the child's

		const scaleToViewAll = this.getScaleToViewAll();
		const [x, y] = this.getPanSettingToCenterGraph();

		return (
			<TransformWrapper
				initialScale={this.state.scale}	// Default zoom level
				initialPositionX={x}
				initialPositionY={y}
				limitToBounds={false}			// Do not move the graph back into view if dragged beyond the border
				minScale={scaleToViewAll}		// Do not let the zoom out beyond the level where you can see everything
				key={this.getKey(this.state.scale, x, y)}
				onZoom={this.onZoomOrPan}
				onPanningStop={this.onZoomOrPan}
				// React-zoom-pan-pinch doesn't trigger zoom event on double-click
				// so we are disabling this until the issue is fixed upstream
				doubleClick={{ disabled: true }}
			>
				{(props: ReactZoomPanPinchHandlers) => <>

					{this.props.floatingContentLeft &&
						<div style={floatingContentLeftStyle}>
							{_.isFunction(this.props.floatingContentLeft)
								? this.props.floatingContentLeft(this.getChildProps(props))
								: this.props.floatingContentLeft}
						</div>
					}
					{this.props.floatingContentRight &&
						<div style={floatingContentRightStyle}>
							{_.isFunction(this.props.floatingContentRight)
								? this.props.floatingContentRight(this.getChildProps(props))
								: this.props.floatingContentRight}
						</div>
					}

					<TransformComponent>
						<div
							ref={this.assignRef}
							style={getSizeAsStyle(this.getChildWidth(), this.getChildHeight())}
						>
							{_.isFunction(this.props.children)
								? this.props.children({
									onMouseDown: this.props.onMouseDown ? this.onMouseDown : null,
									onMouseUp: this.props.onMouseUp ? this.onMouseUp : null,
									onClick: this.props.onClick ? this.onClick : null,
								})
								: this.props.children}
						</div>
					</TransformComponent>

				</>
				}
			</TransformWrapper>

		);
	}

	public override componentDidMount() {
		document.addEventListener("mousemove", this.onMouseMove, false);
		document.addEventListener("mouseup", this.onMouseUp, false);
		document.addEventListener("click", this.onClick, false);
	}

	public override componentWillUnmount() {
		document.removeEventListener("mousemove", this.onMouseMove);
		document.removeEventListener("mouseup", this.onMouseUp);
		document.removeEventListener("click", this.onClick);
	}

	public override shouldComponentUpdate(nextProps: IZoomProps<T, AdditionalProps>) {
		const newScale = this.getScaleToViewAll(nextProps);
		// Sometimes the div will auto-zoom when we add too many nodes in succession, unfortunately
		// transform wrapper does not fire the callback given to onZoom, therefore the scale does not update after the render
		// check to make sure that the state of the scale is in sync, if it isn't update the scale
		// and when the mouse gets transformed it does so with the appropriate scale
		if (this.getScaleToViewAll() !== newScale
			// If auto zoom is locked, we should also lock the scale
			// PMUX-3846: transformMouse does not work correctly if the scale does not correspond with the current zoom level
			&& !this.state.keyValueAfterZoomOrPan) {
			this.setState({ scale: newScale });
			// the call to setState is going to force a re-render so don't do it twice
			return false;
		}

		return true;
	}

	private assignRef = (el: HTMLDivElement) => this.ref = el;

	private onMouseDown = (event: React.MouseEvent, data: T) => {

		// stopPropagation prevents the the 3rd party library from interpreting the drag as the beginning of a pan 
		// operation

		event.stopPropagation();

		// Lock the zoom level so we don't auto-zoom if the parent starts adjusting the scale of the underlying child

		if (!this.state.keyValueAfterZoomOrPan) {
			this.setState({
				keyValueAfterZoomOrPan: this.getKey(this.getScaleToViewAll(), ...this.getPanSettingToCenterGraph()),
			});
		}

		// Fire the event, but with the position transformed according to the zoom/pan amount

		this.props.onMouseDown(this.transformMouse(event), data);
	}

	private onMouseMove = (event: MouseEvent) => {
		if (this.props.onMouseMove) {
			this.props.onMouseMove(this.transformMouse(event));
		}
	}

	private onMouseUp = (event: { clientX: number, clientY: number }, data?: T) => {
		if (this.props.onMouseUp) {
			this.props.onMouseUp(this.transformMouse(event), data);
		}
	}

	private onClick = (event: { clientX: number, clientY: number }, data?: T) => {
		if (this.props.onClick) {
			this.props.onClick(this.transformMouse(event), data);
		}
	}

	private transformMouse(event: { clientX: number, clientY: number }): Position {

		// The clientX/clientY are the relative offset from the viewport of the mouse in pixels
		// The x/y returned from getBoundingClientRect os the relative offset of the div being zoomed/panned from the viewport
		// So, subtracting one from the other will give us the offset in pixels within the transformed div
		// Dividing that by the scale will give the true x,y coordinate within the original child

		const { x, y } = this.ref.getBoundingClientRect();
		return [
			(event.clientX - x) / this.state.scale,
			(event.clientY - y) / this.state.scale,
		];
	}

	private onZoomOrPan = ({ state }: ReactZoomPanPinchRef) => {
		const { positionX, positionY, scale } = state;
		if (!this.state.keyValueAfterZoomOrPan) {
			this.setState({
				keyValueAfterZoomOrPan: this.getKey(this.getScaleToViewAll(), ...this.getPanSettingToCenterGraph()),
				positionX,
				positionY,
				scale,
			});
		} else {
			this.setState({
				positionX,
				positionY,
				scale,
			});
		}
	}

	private getChildProps({ setTransform }: ReactZoomPanPinchHandlers) {
		return {
			zoomIn: () => this.zoom(buttonZoomRate, setTransform),
			zoomOut: () => this.zoom(1 / buttonZoomRate, setTransform),
			reset: () => this.reset(setTransform),
			...this.props.additionalProps,
		};
	}

	private zoom(scale: number, setTransform: ReactZoomPanPinchHandlers["setTransform"]) {
		const scaleToViewAll = this.getScaleToViewAll();
		scale = Math.max(this.state.scale * scale, scaleToViewAll);
		const scaleDifference = scale - this.state.scale;
		const viewCenterX = (this.props.width / 2 / this.state.scale) - (this.state.positionX / this.state.scale);
		const positionX = this.state.positionX - (viewCenterX * scaleDifference);
		const viewCenterY = (this.props.height / 2 / this.state.scale) - (this.state.positionY / this.state.scale);
		const positionY = this.state.positionY - (viewCenterY * scaleDifference);
		setTransform(positionX, positionY, scale, undefined, undefined);
		this.setState({ scale, positionX, positionY });
	}

	private reset(setTransform: ReactZoomPanPinchHandlers["setTransform"]) {
		const scaleToViewAll = this.getScaleToViewAll();
		const [x, y] = this.getPanSettingToCenterGraph();
		this.setState({ positionX: x, positionY: y, scale: scaleToViewAll });
		setTransform(x, y, scaleToViewAll, undefined, undefined);
	}

	private getKey(scale: number, panX: number, panY: number) {

		// If the initial scale factor changes, the parent must have been resized.  But TransformWrapper will not re-
		// render if initialScale changes.  As such, we will set a key based on the initial scale to force a re-render.
		// However, once the user has zoomed/panned themselves, then we'll lock that key in so that latter re-sizing
		// does not undo the zooming/panning the user did

		return this.state.keyValueAfterZoomOrPan ?? `${scale}_${panX}_${panY}`;
	}

	private getScaleToViewAll(props = this.props) {
		// Extra 50 is to provide a bit of buffer (labels, tooltips, borders etc)
		return _.min([
			props.width / (props.childWidth + 50),
			props.height / (props.childHeight + 50),
			1,
		]);
	}

	private getPanSettingToCenterGraph(): [panX: number, panY: number] {
		const scale = this.getScaleToViewAll();
		return [
			(this.props.width - (this.props.childWidth * scale)) / 2 - this.props.childXOrigin * scale,
			(this.props.height - (this.props.childHeight * scale)) / 2 - this.props.childYOrigin * scale,
		];
	}

	// Need to render the child at least as big as the containing window

	private getChildWidth() {
		return Math.max(this.props.width, this.props.childWidth);
	}

	private getChildHeight() {
		return Math.max(this.props.height, this.props.childHeight);
	}
}

export function WithZoom<T, AdditionalProps>(props: React.PropsWithChildren<IProps<T, AdditionalProps>>) {

	// ContainerDimensions will pass width/height to it's child, but there's no way to indicate that in the types, 
	// hence the cast of props to the expected type

	return (
		<DebouncedContainerDimensions>
			<ZoomComponent {...props as IZoomProps<T, AdditionalProps>} />
		</DebouncedContainerDimensions>
	);
}
