import * as React from "react";
import * as _ from "lodash";
import { Edge } from "./Edge";
import { ClassesType } from "../styling/graphStyles";
import * as Layout from "../types/layoutTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// This component renders a collection of edges

interface IEdgeProps<PortMgr extends AnyMemberMgr> {
	edges: Layout.Edge<PortMgr>[];
	onMouseEnterEdge: (edge: Layout.Edge<PortMgr>) => void;
	onMouseLeaveEdge: () => void;
	onClickEdge: (edge: Layout.Edge<PortMgr>) => void;
	highlightedEdges: Layout.Edge<PortMgr>[];
	selectedEdges: Layout.Edge<PortMgr>[];
}

export class Edges<PortMgr extends AnyMemberMgr> extends React.Component<IEdgeProps<PortMgr> & ClassesType> {
	public override render() {
		const { edges, classes, onMouseEnterEdge, onMouseLeaveEdge, onClickEdge, selectedEdges, highlightedEdges } = this.props;
		return <>
			{_.map(edges, (edge) => {
				return <Edge
					key={edge.id}
					edge={edge}
					classes={classes}
					onMouseEnter={onMouseEnterEdge}
					onMouseLeave={onMouseLeaveEdge}
					onClick={onClickEdge}
					selected={_.includes(selectedEdges, edge)}
					highlight={_.includes(highlightedEdges, edge)}
				/>;
			})}
		</>;
	}

	public override shouldComponentUpdate(nextProps: Readonly<IEdgeProps<PortMgr> & ClassesType>) {
		// We are taking a shortcut here because we know how the parent works.  It will never send us new callbacks as 
		// those are assigned on component construction.  It won't change classes as that is fixed to the theme which 
		// is fixed to cli args.  Instead, we can just check the edges are unchanged as well as the selection/highlight

		return this.props.classes !== nextProps.classes ||
			this.props.edges !== nextProps.edges ||
			!_.isEqual(this.props.selectedEdges, nextProps.selectedEdges) ||
			!_.isEqual(this.props.highlightedEdges, nextProps.highlightedEdges);
	}
}

