import * as _ from "lodash";
import { Runtime } from "./resources/runtime";
import { Settings } from "./settings";
import { Solver } from "./solver/solver";
import { Device, InterfaceGroupMap, InterfaceGroup, OptimizablePin, Peripheral } from "./solver/requirements";
import { powerDomainsModuleName } from "./resources/builtIn/powerDomainsModule";
import { ResolvedArgs } from "./args/argTypes";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { UserPreference } from "./userPreferences";
import { Product } from "./product/types";
import { RawResourceLoader } from "./resources/metaContentLoaders/resourceLoader";
import { freezeDeep } from "./utils";
import { isCCS, isUnderTest } from "./platform";
import { PinMap } from "./pinMap";
import { PinmuxUIOptions } from "public/defs";
import { registerConstantFormatter } from "./formatting/constantFormatter";
import { registerDevicePins } from "./formatting/devicePinFormatter";
import { createFormattersMap } from "./formatting/formattersMap";
import { FormatOptions } from "./formatting/formattingTypes";
import { createContexts } from "./objectManagers/proxyHandlers/contextsProxy";
import { getRuntimeContexts } from "./contexts";
import { isDataLessDevice } from "./builtInDevices";
import { scriptDirProductName } from "./product/loadResources";
import { configurationChanged } from "./changeNumber";
import { InstanceType } from "./instanceContainers/instanceContainer";

export class SysConfig {

	private readonly deviceReq: Device;
	private readonly solver: Solver;
	private readonly runtimes: Runtime[];
	private pinMap: PinMap;
	private readonly pinmuxUIOptions: Required<PinmuxUIOptions>;
	private readonly formattersMap = createFormattersMap();

	constructor(
		private readonly resolvedArgs: ResolvedArgs,
		private readonly deviceData: AdaptedDeviceInfo,
		private readonly userPreference: UserPreference,
		private readonly rawResourceLoader: RawResourceLoader,
		private readonly userSettings: Settings,
		private readonly products: Product[],
		private readonly targetDBDevice: string,
	) {

		this.pinmuxUIOptions = determinePinmuxUIOptions(products, deviceData, resolvedArgs);

		this.pinMap = new PinMap(deviceData);

		// Register device data objects

		registerDevicePins(deviceData.devicePins, this.pinMap, this.formattersMap, userPreference);
		registerConstantFormatter(this.formattersMap);

		// Create the solver which is shared across all runtimes

		this.deviceReq = new Device(deviceData);
		this.solver = new Solver(deviceData, this.deviceReq, this.formattersMap, this.pinMap);

		// Create all the runtimes

		const runtimeContexts = getRuntimeContexts(products, deviceData, resolvedArgs);
		const contextsProxy = createContexts({ runtimeContexts, sysConfig: this });
		this.runtimes = _.map(runtimeContexts, (context, index) => {
			const core = _.find(deviceData.cores, (c) => c.name === context.name);

			// if the script is a reference design than we don't want to store it on the runtime 
			const scriptPath = resolvedArgs.referenceDesign ? null :
				_.find(resolvedArgs.script, (script) => script.context === context.name)?.script?.path;

			const runtime = new Runtime(
				{ ...deviceData, core },
				this.solver.getPinOptimizations(),
				userPreference,
				rawResourceLoader,
				products,
				resolvedArgs.compiler,
				scriptPath,
				resolvedArgs.ccxxImageMode,
				this.pinmuxUIOptions,
				this.pinMap,
				this.formattersMap,
				index,
				contextsProxy,
				context,
				resolvedArgs.rtos,
				this.getTotal
			);
			runtime.onBoardDataChanged().addListener(this.onBoardDataChanged);
			return runtime;
		});

		// Freeze everything other than board which is likely to be extended with calls to system.addHardware()

		_.each(this.runtimes, (runtime) => {
			_.each(runtime.getDeviceData(), (member, name) => {
				if (name !== "board" && !(isUnderTest() && name === "versions")) {
					freezeDeep(member);
				}
			});
			Object.freeze(runtime.getDeviceData());
		});
	}

	public getProducts() {
		return this.products;
	}

	public getTargetDBDevice() {
		return this.targetDBDevice;
	}

	public getRawResourceLoader() {
		return this.rawResourceLoader;
	}

	public getResolvedArgs() {
		return this.resolvedArgs;
	}

	public getSummaryItems(includeSuppressed?: boolean) {
		return _.flatMap(this.getRuntimes(), (r) => r.getValidations().getSummaryItems(this.formattersMap, includeSuppressed));
	}

	public clone(deviceData = this.deviceData, targetDBDevice = this.targetDBDevice, resolvedArgs = this.resolvedArgs) {
		return new SysConfig(
			resolvedArgs,
			deviceData,
			this.userPreference,
			this.rawResourceLoader,
			this.userSettings,
			this.products,
			targetDBDevice,
		);
	}

	// Resets the runtime to have zero configuration, but does not alter the device/board 
	// configuration as that might require meta-content to be re-run

	public reset() {

		// Clear out the formatters map at the start
		// It holds references to everything, and reset just wipes them out, but will also re-create some

		this.formattersMap.clear();

		_.each(this.runtimes, (r) => r.reset());

		// Add the device pin entries back into the formatters map

		registerDevicePins(this.deviceData.devicePins, this.pinMap, this.formattersMap, this.userPreference);
		registerConstantFormatter(this.formattersMap);
	}

	public getMessageFormatter(options: FormatOptions) {
		return this.formattersMap.getFormatter(options);
	}

	public getRuntimes() {
		return this.runtimes;
	}

	// Called from areas of the code that KNOW that there can only be one runtime in the system

	public getKnownSingleRuntime() {
		if (_.size(this.runtimes) !== 1) {
			throw new Error("Code logically expected one runtime");
		}
		return _.first(this.runtimes);
	}

	public freezeBoardContent() {

		// Board content is shared, so freezing one freezes all

		_.first(this.runtimes).freezeBoardContent();
	}

	// Use the last context specified on the command line, or pick the first context

	public getInitialContextSelection() {
		return _.last(this.resolvedArgs.script)?.context ?? _.first(this.runtimes).getName();
	}

	public getModuleMgrs() {
		return _.flatMap(this.runtimes, (r) => r.getModuleMgrs());
	}

	public getUserPreference() {
		return this.userPreference;
	}

	public validate() {
		_.each(this.runtimes, (r) => r.validate());
	}

	public finalValidate() {

		_.each(this.runtimes, (r) => r.finalValidate());
	}

	public isCorePinmux() {
		return !this.products;
	}

	public arePowerDomainSettingsEnabled() {
		return _.first(this.runtimes).arePowerDomainSettingsEnabled();
	}

	public getDevicePinSolutionMap() {
		return this.getDeviceReq().devicePinMap;
	}

	public getNumGPIO() {
		return this.getDeviceReq().gpioPinsTotal;
	}

	public getNumGPIOLeft() {
		return this.getNumGPIO() - this.getDeviceReq().gpioPinsUsed;
	}

	public getDeviceData() {
		return this.deviceData;
	}

	public setLockStatus(status: boolean) {
		_.chain(this.getInterfaceMgrs())
			.flatMap((c) => c.instances)
			.each((i) => i.setLockStatus(status))
			.value();

		_.chain(this.getModuleMgrs())
			.flatMap((c) => {
				return [c.static, ...c.instances];
			})
			.filter((i) => !!i)
			.each((i) => i.setLockStatus(status))
			.value();
	}

	public getUserSettings() {
		return this.userSettings;
	}

	// --------------------------------------------------------------------------------------------
	// Functions related to solving

	public getSolver() {
		return this.solver;
	}

	// Object that encapsulates the pinmux requirements for the solver
	public getDeviceRequirements() {
		this.deviceReq.interfaceRequirementsMap = this.generateRequirementsMap();

		// Power domains come from the system runtime

		const runtime = _.first(this.runtimes);
		if (runtime.arePowerDomainSettingsEnabled()) {
			const powerModule = runtime.getModuleMgr(powerDomainsModuleName).static;
			this.deviceReq.powerDomainSettings = powerModule.managedObject as any;
		} else {
			this.deviceReq.powerDomainSettings = {};
		}
		return this.deviceReq;
	}

	public applySolverValidation() {
		_.each(this.getInterfaceAndModuleMgrs(), (mgr) => mgr.applySolverValidation());
	}

	public solve(useSuggestedSolution = false) {

		this.solver.solve(this.getDeviceRequirements(), useSuggestedSolution, this.arePowerDomainSettingsEnabled());
		this.solveComplete();
		configurationChanged();
	}

	public postSolveValidation() {
		this.applySolverValidation();
		this.finalValidate();
	}

	public validateAndSolve(useSuggestedSolution?: boolean) {
		this.validate();
		this.solve(useSuggestedSolution);
		this.postSolveValidation();
	}

	public updateSolverSolution() {
		this.solver.saveSolution(this.getDeviceRequirements());
	}

	public showSaveIcons() {
		return !isCCS() || this.resolvedArgs.showSaveIcons;
	}

	private getDeviceReq() {
		return this.deviceReq;
	}

	private generateRequirementsMap() {
		const interfaceReqsMap: InterfaceGroupMap = {};

		_.each(this.getModuleMgrs(), (mod) => {
			addToReqsMap(mod.getSolverRequirements());
		});

		_.each(this.getInterfaceMgrs(), (i) => {

			const ifaceName = i.getName();
			const reqs = i.getSolverRequirements();
			addToReqsMap(reqs);

			// our tests (solver and sysconfig) require that the interfaceReqsMap
			// contains an entry for every interface, so if it hasn't been added by this point
			// init it.
			interfaceReqsMap[ifaceName] = interfaceReqsMap[ifaceName] || new InterfaceGroup(ifaceName);
		});

		function addToReqsMap(reqs: (Peripheral | OptimizablePin)[]) {
			_.each(reqs, (req) => {
				addReqToMap(req);
			});
		}

		function addReqToMap(req: Peripheral | OptimizablePin) {
			const ifaceName = req.interfaceName;
			interfaceReqsMap[ifaceName] = interfaceReqsMap[ifaceName] || new InterfaceGroup(ifaceName);
			interfaceReqsMap[req.interfaceName].requirements.push(req);
		}

		return interfaceReqsMap;
	}

	private solveComplete() {
		_.each(this.getInterfaceAndModuleMgrs(), (m) => {
			m.solveComplete();
		});
	}

	private onBoardDataChanged = () => {
		this.pinMap = new PinMap(this.deviceData);
		_.each(this.runtimes, (r) => r.setPinMap(this.pinMap));
		this.solver.initData(
			this.deviceData,
			this.deviceReq,
			this.formattersMap,
			this.pinMap,
		);
	}

	private getInterfaceMgrs() {
		return _.flatMap(this.runtimes, (r) => r.getInterfaceMgrs());
	}

	private getInterfaceAndModuleMgrs() {
		return [
			...this.getInterfaceMgrs(),
			...this.getModuleMgrs(),
		];
	}

	// Defined as a fat arrow function so it can be passed as an anonymous function
	private getTotal = (instanceName: string, instanceType: InstanceType): number => {
		return _.sumBy(this.runtimes, instanceType === InstanceType.Module ?
			(runtime) => runtime.getModuleMgr(instanceName, false)?.getNumberOfUsed() ?? 0 :
			(runtime) => runtime.getInterfaceMgr(instanceName).getNumberOfUsed());
	}

}

function determinePinmuxUIOptions(products: Product[], deviceData: AdaptedDeviceInfo, resolvedArgs: ResolvedArgs) {

	// Assume every option is the default, but if ANY product declares a non-default value,
	// we use that.  These options exist to be either globally enabled or disabled for each
	// BU, so for the time being this is a reasonable trade off.

	const groups = _.chain(products)
		.map((p) => p.file.pinmuxUIOptions?.group)
		.compact()
		.uniq()
		.value();

	if (1 < _.size(groups)) {
		throw new Error("Conflicting products detected");
	}

	const nonGeneratedProducts = _.filter(products, (p) => p.file.name !== scriptDirProductName);
	const hasNoPinmux = isDataLessDevice(deviceData.deviceId) ||
		resolvedArgs.ccxxImageMode ||
		(!_.isEmpty(nonGeneratedProducts) && _.every(nonGeneratedProducts, (p) => p.file.pinmuxUIOptions?.hasNoPinmux));

	return {
		showUsed: _.some(products, (p) => p.file.pinmuxUIOptions?.showUsed),
		showPinTable: _.some(products, (p) => p.file.pinmuxUIOptions?.showPinTable),
		showSignals: _.some(products, (p) => p.file.pinmuxUIOptions?.showSignals),
		group: _.first(groups) || "collapsed",
		hidePeripheralTab: hasNoPinmux || _.some(products, (p) => p.file.pinmuxUIOptions?.hidePeripheralTab),
		hasNoPinmux,
	};
}
