import * as React from "react";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { DateConfigurableMgr } from "../../../services/objectManagers/configurables/dateConfigurableMgr";
import DatePicker from "react-datepicker";
const isValid = require("date-fns/isValid");
const parse = require("date-fns/parse");
import { OnBlurInputBox } from "../../higherOrderComponents/ComposedComponents";
import { isNodejs } from "../../../services/platform";
import { assertUnreachable } from "../../../services/utils";

// Do not install CSS unless running in the UI
// While this code is all UI specific, this conditional import of the font allows this file to be imported at the top
// level, even if the code is not used at runtime, which is the case when used as a nodejs library

if (!isNodejs()) {
	require("react-datepicker/dist/react-datepicker.css");
}

interface IProps {
	handleDateTimeChange: (val: string) => void;
	value?: string;
	onClick?: () => void;
	type?: string;
}

export class CDateConfigurable extends React.Component<{
	mgr: DateConfigurableMgr;
	actions: IConfigurablesActions;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const type = mgr.def.type;
		const dateformat = (type === "time" ? "hh:mm:ss aa" : (type === "dateAndTime" ? "yyyy/MM/dd hh:mm:ss aa" : "yyyy/MM/dd"));
		return (
			<DatePicker
				adjustDateOnChange={true}
				popperPlacement={"auto-start"}
				customInput={<StartDate handleDateTimeChange={this.handleDateTimeChange} type={type} />}
				dateFormat={dateformat}
				selected={mgr.getValue()}
				onChange={this.onChange}
				showYearDropdown
				todayButton="Today"
				showTimeInput={type === "time" || type === "dateAndTime"}
				timeInputLabel="Time:"
				showTimeSelectOnly={type === "time"}
			/>
		);
	}

	private handleDateTimeChange = (val: string) => {
		// the date only configurable kept on updating after a focus and blur event, without actually picking a different date in the picker
		// To prevent that from happening, the hours are set to 00:00:00 every time
		let d;
		switch (this.props.mgr.def.type) {
			case "time":
				d = parse(val, "hh:mm:ss aa", new Date(0));
				break;
			case "date":
			case undefined: // since type is an optional parameter and date is the default type if it is not defined
				d = parse(val, "yyyy/MM/dd", new Date().setHours(0, 0, 0));
				break;
			case "dateAndTime":
				d = new Date(val);
				break;
			default:
				assertUnreachable(this.props.mgr.def.type);
		}
		if (isValid(d)) {
			this.props.actions.setConfigurableValue(this.props.mgr, d);
		}
	}

	private onChange = (val: Date) => {
		this.props.actions.setConfigurableValue(this.props.mgr, val);
	}
}

// forwardRef used here to remove React warning from console, we handle blur/focus events ourselves.
const StartDate = React.forwardRef(function startDate({ value, onClick, type, handleDateTimeChange }: IProps, _ref) {
	return (
		<OnBlurInputBox
			type={"text"}
			id={type === "dateAndTime" ? "date-time-input" : (type === "time" ? "time-input" :
				"date-input")}
			disabled={false}
			value={value}
			onClick={onClick}
			onChange={handleDateTimeChange}
			placeholder={type === "dateAndTime" ? "yyyy/mm/dd hh:mm:ss AM/PM" : (type === "time" ? "hh:mm:ss AM/PM" :
				"yyyy/mm/dd")}
		/>
	);
});

