import * as _ from "lodash";
import { RawResourceLoader, toFullPath } from "../resources/metaContentLoaders/resourceLoader";
import { BoardDef } from "public/defs";
import { findDeviceInfo, getDeviceDescriptions } from "../data";
import { Product } from "../product/types";
import { validateMeta, SCHEMA } from "../JSONschemaValidator";
import { DiscoveryJSON } from "dataInterfaces";
import { ParsedArgs, ArgsError } from "./argTypes";
import { getCLIContextChoices } from "../contexts";
import { convertUnknownToError } from "../utils";

export async function resolveTarget<T>(products: Product[], parsedArgs: ParsedArgs<T>) {
	const discoveryData = await getDeviceDescriptions();
	const deviceInfo = findDeviceAndBoard(discoveryData, products, toBoardAndDeviceInfo(parsedArgs));
	validateDeviceInfo(discoveryData, products, deviceInfo, _.map(parsedArgs.script, (s) => s.context?.value));
	return deviceInfo;
}

type BoardAndDeviceInfo = ReturnType<typeof toBoardAndDeviceInfo>
function toBoardAndDeviceInfo<T>(args: ParsedArgs<T>) {
	return {
		board: args.board?.value,
		device: args.device?.value,
		package: args.package?.value,
		part: args.part?.value,
	};
}

function findDeviceAndBoard(
	discoveryData: DiscoveryJSON,
	products: Product[],
	{ board: boardId, device, part, package: pkg }: BoardAndDeviceInfo) {

	// No board specified - just pass along the device info

	if (!boardId) {
		return findDeviceInfo(discoveryData, device, part, pkg);
	}

	// Otherwise, fetch and validate the board definition specified
	// Better validation (of all instanced components) will happen later,
	// but we want to at least make sure device/emulated keys are valid

	const resourceLoader = new RawResourceLoader(products);
	let boardDef: BoardDef;
	let boardDevices;
	try {
		const resource = resourceLoader.getJSONResource(toFullPath(null, boardId));
		boardDef = validateMeta(resource, boardId, SCHEMA.BoardDef);
		boardDevices = _.map([boardDef, ...boardDef.emulated || []],
			(info) => findDeviceInfo(discoveryData, info.device, info.part, info.package));

	} catch (e) {
		// Need to wrap as ArgsError to enable the correct type
		// handling up the stack.
		throw new ArgsError(`${boardId}: ${convertUnknownToError(e).message} `);
	}

	// If device was not specified, use the first board device

	if (!device) {
		return {
			..._.first(boardDevices),
			boardId,
		};
	}

	// Otherwise, verify that it matches one of the board devices and use that one

	const deviceInfo = findDeviceInfo(discoveryData, device, part, pkg);
	if (!_.some(boardDevices, (d) => _.isEqual(d, deviceInfo))) {
		throw new ArgsError(`${device} is not supported by board: ${boardId}'`);
	}

	return {
		...deviceInfo,
		boardId,
	};
}

type DeviceInfo = ReturnType<typeof findDeviceInfo>;

function validateDeviceInfo(deviceDescriptions: DiscoveryJSON, products: Product[], deviceInfo: DeviceInfo, contexts: string[]) {

	// Make sure every --context is a known context or the system context

	const device = _.find(deviceDescriptions.devices, (d) => d.name === deviceInfo.deviceId);
	const validContextNames = _.map(getCLIContextChoices(products, device), (c) => c.name);
	const unknownContext = _.find(contexts, (context) => context && !_.includes(validContextNames, context));
	if (unknownContext) {
		throw new ArgsError("Unknown context specified: " + unknownContext);
	}

	// Lastly, ensure that this device is valid to use with every product

	const invalidProduct = _.find(products, (product) => {
		return _.every(product.file.devices, (deviceRegex) => !(new RegExp(deviceRegex).test(deviceInfo.deviceId)));
	});
	if (invalidProduct) {
		throw new ArgsError(`${deviceInfo.deviceId} is not a valid device for the product ${invalidProduct.file.displayName}`);
	}
}
