import * as _ from "lodash";
import { FormattersMap } from "../formatting/formattersMap";
import { isScriptingEnabled } from "../scripting/scriptingGuard";
import { ModuleInstanceMgr } from "./moduleInstance";
import { AMemberMgr, isMetaChange, SetSource } from "./member";
import { Position, RuntimeInstance } from "public/runtime";
import { Member } from "public/defs";
import { createMemberValueAssignmentStatement } from "../scripting/serialize";
import { minimumGridAlignment, minimumNodeSize } from "../../components/graphableModules/layout/constants";
import { SerializationOptions } from "../scripting/toScript";
import { ModuleMgr } from "../instanceContainers/module";

// This represents one coordinate out of a (x,y) position.  It's the same as a number configurable, except it's always 
// hidden and inaccessible to meta content

const def = { name: "$position", hidden: true };

export class PositionMemberMgr extends AMemberMgr<Position, RuntimeInstance, Member> {
	constructor(
		parentObjectMgr: ModuleInstanceMgr,
		formattersMap: FormattersMap,
	) {
		super(parentObjectMgr, formattersMap, def, findValidPosition(parentObjectMgr.getModuleMgr(), [0, 0], parentObjectMgr.getID()));
	}

	// Only allow scripts to get/set this member
	// We can always relax that restriction in the future, but this allows positions to be set at the end of the script
	// as we know it won't cause any side effects.

	public override get() {
		if (!isScriptingEnabled()) {
			this.preventMetaUpdate();
		}
		return super.get();
	}

	// Prevent setting this value via args for serialization reasons mentioned above

	public override setValueFromRequiredArgs() {
		this.preventMetaUpdate();
	}

	public override setValueFromArgs() {
		this.preventMetaUpdate();
	}

	public override removeArgs() {
		this.preventMetaUpdate();
	}

	public override removeReqArgs() {
		this.preventMetaUpdate();
	}

	// Since accessing this member will most likely throw, exclude it as a visible member to loop over

	public override excludeFromOwnProperties() {
		return true;
	}

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {

		// If we are copying, then move the node one node length over and down so it's not immediately on top of the other node

		const value = options.cloneInstance ? _.map(this.value, (coor) => coor + minimumNodeSize) : this.value;

		// Then it's just a normal assignment of the position array

		return [
			createMemberValueAssignmentStatement(
				this.def,
				parentIdentifier,
				JSON.stringify(value),
				{ shouldQuoteStrings: false },
			)];
	}

	public override shouldSerialize() {

		// Always serialize.  Even if at 0,0, it may be re-instantiated out of order and we don't want to shift to 
		// avoid overlaps and not restore the value to 0,0

		return true;
	}

	// Do not treat position changes as being "modified" in by the user.  We do not want to promote stuff to be "user 
	// touched" just because it was moved - we want it "user touched" if it was actually configured

	public override isUserModified() {
		return false;
	}

	protected override modifiedInUI() { }

	// Verify it's a numeric tuple

	protected override validateValue(val: Position, _forceWrite: boolean, source: SetSource) {
		if (isMetaChange(source)) {
			this.preventMetaUpdate();
		}
		if (!_.isArray(val)) {
			this.typeMismatch("[number, number]", typeof val);
		} else if (2 !== _.size(val) || typeof val[0] !== "number" || typeof val[1] !== "number") {
			this.typeMismatch("[number, number]", `[${_.map(val, (v) => typeof v).join(", ")}]`);
		}
	}

	protected override transform(position: Position) {
		return _.map(position, snapToGrid) as Position;
	}

	private preventMetaUpdate() {
		throw new Error("$position can only be accessed in scripts");
	}
}

const snapToGridOffset = minimumGridAlignment;

function snapToGrid(x: number) {
	return Math.round(x / snapToGridOffset) * snapToGridOffset;
}

export function findValidPosition(moduleMgr: ModuleMgr, [initialX, initialY]: Position, id: string): Position {

	// This first filters on the x coordinates of all other nodes in the graph to find those that could create an 
	// overlap with the supplied initial x coordinate.  Then, the y coordinates are extracted and sorted.  Thus, we end
	// up with just the y coordinates of horizontally overlapping nodes in sorted order.

	// Sometimes we find a valid spot after initial placement (sharedModuleInstances)
	// in such cases, we want to avoid detecting an overlap with with the node itself
	const yPositions = _.chain(moduleMgr.getNodesInGraph())
		.filter((i) => i.getID() !== id) // Don't detect conflict with self
		.map((i) => (i.memberMgrs.$position as PositionMemberMgr).getValue())
		.filter(([existingX]) => existingX <= initialX + minimumNodeSize && existingX + minimumNodeSize >= initialX)
		.map(([, existingY]) => existingY)
		.sortBy()
		.value();

	// The first loop says "we have the index of an overlap, and it overlaps with the end of the node".  The inner loop
	// says "keep moving the node down until it's start is past the other node's end".  At the end we should have a 
	// vertical position where it won't overlap.

	let index = _.findIndex(yPositions, (y) => y <= initialY + minimumNodeSize);
	while (-1 !== index && yPositions[index] <= initialY + minimumNodeSize) {
		while (yPositions[index] + minimumNodeSize >= initialY) {
			initialY += minimumNodeSize;
		}
		++index;
	}
	return [initialX, initialY];
}
