import * as _ from "lodash";
import { PinMuxFileData } from "../legacy/loadJSONPinmuxFile";
import { parseJSON } from "../utils";
import { ScriptAndProductLoader } from "../resources/otherLoaders/scriptAndProductLoader";
import { ParsedArgs, ArgsError, Script } from "./argTypes";
import { parseArgs } from "./parseArgs";
import { parseArgsStringToArgv } from "./stringToArgv";

export async function resolveScriptArg(parsedArgs: ParsedArgs, loader: ScriptAndProductLoader) {

	const embeddedArgs = await Promise.all(_.map(parsedArgs.script, async (scriptArgs) => {
		if (scriptArgs.script?.value) {
			const path = loader.resolve(scriptArgs.script.value);
			const contents = await loader.readScriptFile(path);
			const { script, ...rest } = parseEmbeddedArgs(contents);
			return {
				...rest,
				script: [{
					...script[0],
					script: {
						path,
						contents,
					},
				}],
			};
		}
		return { script: [] };
	}));

	return mergeArgs(parsedArgs, embeddedArgs);
}

// Merge script embedded args with args specified on the command line, with the command line taking 
// precedence
function mergeArgs(cliArgs: ParsedArgs, embeddedArgs: ParsedArgs<Script>[]) {

	// We want to check if the embedded args conflict across scripts.  But, only if the conflicting
	// arg is not specified on the command line.  To do that, we'll delete any embedded args that 
	// were also specified on the command line, so that later we can throw if a conflicting arg is 
	// seen.  
	// Plus, if either board or device was supplied on the command line, ignore any target option

	const embeddedArgsToIgnore = _.pull(_.keys(cliArgs), "script");
	if (cliArgs.board || cliArgs.device) {
		embeddedArgsToIgnore.push("board", "device", "package", "part");
	}
	embeddedArgs = _.map(embeddedArgs, (embeddedArg) => _.omit(embeddedArg, embeddedArgsToIgnore));

	// Next, combine the script-specific args, but have the command line ones take precedence 

	const script = _.zipWith(cliArgs.script, embeddedArgs, (cliScript, embedded) => {
		return {
			...embedded.script[0],
			..._.omit(cliScript, "script"), // since script.contents is resolved as an embedded arg
		};
	});

	// Now combine the non-script-specific args, but throw if conflicting args are seen

	return _.reduce(embeddedArgs, (prev, curr) => {
		_.each(curr, (argValue, argName) => {
			if (argName !== "script" && argName in prev && !_.isEqual(prev[argName as keyof ParsedArgs], argValue)) {
				throw new ArgsError(`--${argName} specified differently across scripts`);
			}
		});
		return {
			...curr,
			...prev,
			script,
		};
	}, cliArgs as unknown as ParsedArgs<Script>); // invalid cast, but we'll replace the script parameter, so it's correct
}

const cliArgsSingleLineRegex = /^.*\/\/.*@cliArgs (.*)$/m;
const cliArgsMultiLineRegex = /.*\/\*[\s\S]*@cliArgs([\s\S]*?)(?:\*\/|^\s*\*)/m;

export function parseEmbeddedArgs(source: string) {
	const argString = extractEmbeddedArgs(source);
	const argv = parseArgsStringToArgv(argString);
	const { parsedArgs: args, argsError } = parseArgs(argv, false);
	if (argsError) {
		throw new ArgsError(`Error parsing CLI arguments in script file: ${argsError.toString()}`);

	}
	return args;
}

function extractEmbeddedArgs(source: string) {

	// Is this a legacy pinmux file?  If so, extract the device id and return that.
	// This will never actually be used, but it will satisfy the rest of the flow
	// to create config params to pass to run script which will ignore them

	try {

		const pinmuxFile = parseJSON<PinMuxFileData>(source);
		return `--device ${pinmuxFile.deviceId}`;
	} catch (e) { } // ignore exceptions and process as a script

	// ignore exceptions and process as a script
	const matches = cliArgsSingleLineRegex.exec(source) || cliArgsMultiLineRegex.exec(source);
	if (matches) {
		// ignore extra space, and new lines carriage returns etc..
		return matches[1].replace("/n/r", " ").replace(/\s\s+/g, " ");
	}
	return "";
}
