import * as Layout from "../../types/layoutTypes";
import { createFinalSvgPathNode } from "../createSvgPathNode";

// Node for an OR gate

const straightSideFraction = 1 / 5;
export function orPath(width: number, height: number, offset = 0) {
	const leftControlXOffset = width / 3;
	const rightControlXOffset = width / 12;
	const rightControlYOffset = height / 4;
	const leftControlX = width * straightSideFraction + leftControlXOffset + offset;
	const rightControlX = width - rightControlXOffset + offset;
	return `M ${offset} 0 ` 																	// Start in top left corner
		+ `H ${width * straightSideFraction + offset} ` 										// Horizontal line at top		
		+ `C ${leftControlX} 0 ${rightControlX} ${height / 2 - rightControlYOffset} `			// Cubic bezier curve
		+ `${width + offset} ${height / 2} `	 												// ... that ends here
		+ `C ${rightControlX} ${height / 2 + rightControlYOffset} ${leftControlX} ${height} `	// And now the bottom half
		+ `${width * straightSideFraction + offset} ${height} `
		+ `H ${offset} ` 																		// horizontal line at bottom
		+ `A ${width} ${height} 0 0 0 ${offset} 0 ` 											// Left side semi-circle
		+ "Z"; 																					// Close
}

export function getOrPortOffset({ height: nodeHeight }: Layout.Size, y: number) {

	// The left side will be the arc of a circle with a radius equal to the height that connects the top and bottom 
	// corners.  We can use some trig to find the x offset given y
	//
	//                        *              ---                          ---
	//                     *     *            |                            |
	//              r   *          *          |                            | y
	//               *              *         |  nodeHeight/2              |
	//            *                  *        |                           ---
	//         *                      *       |                            |
	//      *            r            *       |                            | nodeHeight/2 - y
	//   ******************************      ---                          ---
	//
	// First, we need to find the center of the circle.  Given we know that x = 0 when y = 0, we get a triangle with
	// hypotenuse equal to the radius (nodeHeight) and height equal to nodeHeight/2.  Using the pythagorean theorem,
	// that makes the other side:

	const hypotenuseSquared = Math.pow(nodeHeight, 2);
	const xOffsetOfCenterOfCircle = Math.sqrt(hypotenuseSquared - Math.pow(nodeHeight / 2, 2));

	// Now given y, we can create another triangle with a height of abs(nodeHeight/2 - y) and the same length 
	// hypotenuse.  That triangle's other side will thus be:

	const xOffsetOfPortFromCenterOfCircle = Math.sqrt(hypotenuseSquared - Math.pow(nodeHeight / 2 - y, 2));

	// Now we just need that difference to get the relative x offset of the port

	return xOffsetOfPortFromCenterOfCircle - xOffsetOfCenterOfCircle;
}

// There will only ever be one output, so hight-based adjustments at the output aren't needed.

export const OrNode = createFinalSvgPathNode(orPath, { inputPortXOffset: getOrPortOffset, inputLabelXOffset: getOrPortOffset });
