import * as _ from "lodash";
import * as React from "react";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { Validations } from "../../../services/objectManagers/validations";
import * as Layout from "../types/layoutTypes";
import { PositionedDiv } from "./PositionedDiv";
import { ErrorBadge, SimpleWarningBadge } from "../../Badges";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { getShortValidationString } from "../../../services/utils";
import { FormattedMsg as FormattedMsgClass } from "../../../services/formatting/link";
import { CursorMode, isProbingMode } from "../CursorMode";

// Adapts a PositionedDiv for a specific node layout

interface IProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr> {
	node: Layout.Group<InstMgr, PortMgr> | Layout.Node<InstMgr, PortMgr>;
	onClick: (selection: InstMgr) => void;
	onMouseDown: (event: React.MouseEvent, node: InstMgr) => void;
	className: string;
	children?: React.ReactNode;
	validations?: Validations;
	cursorMode?: CursorMode;
	formatter: IFormatter;
}

// There is no sense making this a PureComponent.  All clients are already PureComponents or memos

export class PositionedNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.Component<IProps<InstMgr, PortMgr>> {
	public override render() {
		const { node, className, children } = this.props;
		const { warnings, errors } = this.getErrorsWarningsUnderInst();
		const tooltip = _.isEmpty(warnings) && _.isEmpty(errors) ? this.getTooltip() : positionedNodeTooltip({ warnings, errors });
		return (
			<PositionedDiv
				x={node.x}
				y={node.y}
				height={node.height}
				width={node.width}
				onClick={this.onClick}
				onMouseDown={this.props.onMouseDown ? this.onMouseDown : null}
				className={className}
				tooltip={tooltip}
			>
				{children}
			</PositionedDiv>
		);
	}

	private onClick = () => {
		const { node } = this.props;
		if ("inst" in node) {
			this.props.onClick(node.inst);
		}
	}

	private onMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
		const { node } = this.props;
		if ("inst" in node) {
			this.props.onMouseDown(e, node.inst);
		}
	}

	private getErrorsWarningsUnderInst() {
		if ("inst" in this.props.node && this.props.validations && this.props.formatter) {
			const nodeValidations = this.props.validations.getValidationsUnderMgr(this.props.node.inst);
			return _.reduce(nodeValidations, (result: { warnings: FormattedMsgClass[], errors: FormattedMsgClass[] }, validation) => {
				return {
					warnings: _.concat(result.warnings,
						_.map(validation.warnings, (warning) => this.props.formatter(getShortValidationString(warning)))),
					errors: _.concat(result.errors,
						_.map(validation.errors, (error) => this.props.formatter(getShortValidationString(error)))),
				};
			}, { warnings: [], errors: [] });
		}
		return { warnings: [], errors: [] };
	}

	private getTooltip() {
		// We will show a tooltip on the port in probing mode
		if (this.props.cursorMode && isProbingMode(this.props.cursorMode)) {
			return "";
		} else if ("inst" in this.props.node) {
			return this.props.node.inst.getToolTip();
		}
		return "";
	}
}

function positionedNodeTooltip({ errors, warnings }:
	{
		errors: FormattedMsgClass[],
		warnings: FormattedMsgClass[],
	}) {
	if ((_.isEmpty(warnings) && _.isEmpty(errors))) {
		return "";
	}
	return (
		<div>
			{_.map(errors, (err, idx) =>
				<ErrorBadge message={err.toString()} key={"error" + idx} />
			)}
			{_.map(warnings, (warning, idx) =>
				<SimpleWarningBadge message={warning.toString()} key={"warning" + idx} />
			)}
		</div>
	);
}
