export type LeafNode = ConfigLeafNode |
	PinMuxLeafNode |
	SharedAssignLeafNode |
	ValidationLeafNode |
	ModuleInstanceAdderMgr;

export type ViewNode = LeafNode | ContainerNode;

export interface Node {
	getKey(): string;
	isHidden(): boolean;
	getNumColumns(): number;
}

export type MatchedPathRetType = [boolean, string[]];
export interface ContainerNode extends Node {
	type: "container";
	getChildren(): ViewNode[];
	getHeading(displayScriptName?: boolean): string;
	getSecondaryHeading(): string;
	isCollapsed(): boolean;
	setCollapsed(val: boolean): void;
	getDefaultCollapsedState(): boolean;
	isLongDescriptionVisible(): boolean;
	setLongDescriptionVisibility(val: boolean): void;
	getLongDescription(): string;
	isReadOnly(): boolean;
	matchSubItemPath(itemPath: string[]): MatchedPathRetType;
	getTitleNode(): LeafNode;
	getValidationsummary(validations: Validations): ValidationSummary;
	isCard(): boolean;
	getUINodes(): OrganizedViewNodes;
	setCurrentTab(): void;
	parentTabGroup: TabGroup;
	childTabGroup: TabGroup;
}
export function reveal(node: ContainerNode, itemPath: string[], tabUpdate?: boolean): boolean {
	const [matched, remaining] = node.matchSubItemPath(itemPath);
	if (matched) {
		node.setCollapsed(false);
		if (tabUpdate) {
			// tabbing could be disabled
			node.setCurrentTab();
		}
		_.each(node.getChildren(), (c) => {
			if (c.type === "container") {
				return !reveal(c, remaining, tabUpdate); // explicitly break out of loop if found
			}
			return true;
		});
		return true;
	}
	return false;
}

// A default base node implementation
abstract class ANode implements Node {

	constructor(private readonly key: string) {
	}

	public getKey(): string {
		return this.key;
	}

	public isHidden(): boolean {
		return false;
	}

	public getNumColumns() {
		return 2; // name + value
	}
}

// A default base container node implementation
export abstract class AContainerNode extends ANode implements ContainerNode {
	public readonly type = "container";
	public parentTabGroup: TabGroup;
	public childTabGroup: TabGroup;
	private showLongDescription = false;
	private readonly defaultCollapsedState: boolean;

	constructor(protected readonly instMgr: ModuleInstanceMgr, key: string, private collapsed = true) {
		super(key);
		this.defaultCollapsedState = collapsed;
	}

	public abstract getChildren(): ViewNode[];
	public abstract getHeading(): string;
	public abstract getSecondaryHeading(): string;
	public abstract getLongDescription(): string;
	public abstract getValidationsummary(valiationMap: Validations): ValidationSummary;

	// A Title node is a LeafNode in the title of the collapsible card. For example, 
	// in shared Assign module, the SharedAssignLeafNode is the title node. In this case,
	// the instance dropdown is like an instance picker. The user can pick the shared instance
	// without expand the collapsed card.
	public getTitleNode(): LeafNode {
		return null;
	}

	public override getNumColumns() {
		return 1;
	}

	public isCollapsed() {
		return this.collapsed;
	}

	public setCollapsed(val: boolean) {
		this.collapsed = val;
	}

	public setCurrentTab(): void {
		this.parentTabGroup?.setCurrentTab(this);
	}

	public getDefaultCollapsedState() {
		return this.defaultCollapsedState;
	}

	public isLongDescriptionVisible() {
		return this.showLongDescription;
	}

	public setLongDescriptionVisibility(val: boolean) {
		this.showLongDescription = val;
	}

	public getUIScriptStatements(parentIdentifier: string): Statement[] {
		return [
			...createUIStatements(parentIdentifier, this),
			..._.flatMap(this.getChildren(), (c) => {

				// MemberMgrs that are also container nodes, will be covered by the generic algorithm, when
				// the member is visited, so we need to look at the instance type, vs including all children

				if (c instanceof AContainerNode) {
					return c.getUIScriptStatements(parentIdentifier);
				} else {
					return [];
				}
			}),
		];
	}

	public isReadOnly() {
		return false;
	}

	public override isHidden(): boolean {
		return _.every(this.getChildren(), (c) => c.isHidden());
	}

	public matchSubItemPath(itemPath: string[]): MatchedPathRetType {
		const matched = _.some(this.getChildren(), (c) => {
			const [childMatched] = c.matchSubItemPath(itemPath);
			return childMatched;
		});
		return [matched, itemPath];
	}

	public isCard() {
		// check if the user preferences specifies using tabs via the runtime
		// in the future when we default to using tabs, this should return true
		return isCard(this.instMgr.showTabs(), undefined);
	}

	public getUINodes(): OrganizedViewNodes {
		return splitViewNodes(this.getChildren(), this);
	}
}

function sumarizeContainerNodes(validations: Validations, children: (ContainerNode | ConfigLeafNode)[]) {
	return combineSummaries(children, (c) => c.getValidationsummary(validations));
}

function combineSummaries<T>(children: T[], iterator: (obj: T) => ValidationSummary): ValidationSummary {
	let combinedSummary = ValidationSummary.None;
	for (const c of children) {
		const currSummary = iterator(c);
		if (currSummary === ValidationSummary.Error) {
			return currSummary;
		}
		if (currSummary === ValidationSummary.Warning) {
			combinedSummary = currSummary;
		}
	}
	return combinedSummary;
}

// Create view nodes from a module or a group
export function createViewNodesFromConfig(
	config: (AnyConfigurable | ConfigurableGroup)[],
	instMgr: ModuleInstanceMgr,
	key: string) {

	// Track consecutive non grouped configs to pull into a single table
	let currentConfigTableConfig: AnyConfigurable[] = [];
	const nodes: (ConfigLeafNode | ConfigGroupContainerNode)[] = [];

	_.each(config, (c) => {
		if (isConfigurableGroup(c)) {
			validateConfigurableGroup(c);
			addCurrentIfNeeded();
			nodes.push(new ConfigGroupContainerNode(c, instMgr, `${key}/${nodes.length.toString()}`));
		} else {
			// filter out built-ins
			if (!_.startsWith(c.name, "$")) {
				currentConfigTableConfig.push(c);
			}
		}
	});

	addCurrentIfNeeded();

	function addCurrentIfNeeded() {
		if (!_.isEmpty(currentConfigTableConfig)) {
			nodes.push(
				new ConfigLeafNode(
					_.map(
						currentConfigTableConfig, (c) => instMgr.memberMgrs[c.name] as NonObjectMemberMgr),
					`${key}/${nodes.length.toString()}`,
				),
			);

			currentConfigTableConfig = [];
		}
	}

	return nodes;
}

// Describes a set of configurables
export class ConfigLeafNode extends ANode {
	public readonly type = "configLeafNode";
	public constructor(
		private readonly configurables: NonObjectMemberMgr[],
		key: string,
	) {
		super(key);
	}

	public getConfigurables() {
		return this.configurables;
	}

	public override isHidden() {
		return _.every(this.configurables, (c) => c.uiState.hidden);
	}

	public matchSubItemPath(itemPath: string[]) {
		if (1 === _.size(itemPath) &&
			_.some(this.getConfigurables(), (c) => c.def.name === _.last(itemPath))) {
			return itemPath;
		}
		return [];
	}

	public getValidationsummary(validations: Validations) {
		return combineSummaries(this.configurables, (c) => toSummary(validations.getValidation(c)));
	}
}

// Describe a config group node
export class ConfigGroupContainerNode extends AContainerNode {

	private childNodes: (ConfigGroupContainerNode | ConfigLeafNode)[] = [];

	public constructor(
		private readonly group: ConfigurableGroup,
		instMgr: ModuleInstanceMgr,
		key: string,
	) {
		super(instMgr, key, _.isUndefined(group.collapsed) ? true : group.collapsed);
		this.childNodes = createViewNodesFromConfig(group.config, instMgr, key);
	}

	public override getChildren(): ViewNode[] {
		return [
			...this.childNodes,
			...(this.group.name ? this.instMgr.getViewNodesForGroup(this.group.name) : []),
		];
	}

	public override getValidationsummary(validations: Validations): ValidationSummary {
		return sumarizeContainerNodes(validations, this.childNodes);
	}

	public getHeading() {
		return this.group.displayName;
	}

	public getLongDescription() {
		return this.group.longDescription;
	}

	public getSecondaryHeading(): string {
		return this.group.description;
	}

	public override isCard() {
		return isCard(this.instMgr.showTabs(), this.group.style);
	}
}

// Describe a Pinmux requirements node
export class PinMuxContainerNode extends AContainerNode {

	private content: PinMuxLeafNode;
	private isTab: boolean;

	public constructor(
		instMgr: ModuleInstanceMgr,
		collapsed: boolean
	) {
		super(instMgr, "PinMux", collapsed);
	}

	public getValidationsummary(validations: Validations) {

		// Need to check for summaries on any underlying objects managers, as well as individual validations on the 
		// member managers

		return combineSummaries(this.content.getMembers(), (c) => {
			const memberSummary = toSummary(validations.getValidation(c));
			if (memberSummary !== ValidationSummary.Error && c instanceof InterfaceInstanceMemberMgr) {
				const objectSummary = validations.getSummary(c.valueObjectMgr);
				return Math.max(memberSummary, objectSummary);
			}
			return memberSummary;
		});
	}

	public setContent(content: PinMuxLeafNode) {
		this.content = content;
	}

	public getChildren() {
		return [this.content];
	}

	public getLongDescription() {
		return "";
	}

	public getHeading(): string {
		return this.getKey();
	}

	public getSecondaryHeading(): string {
		return "Peripheral and Pin Configuration";
	}

	public setIsTab(val: boolean) {
		this.isTab = val;
	}

	public override isCard(): boolean {
		return !this.isTab;
	}
}

// Describe a special pinmux node that renders all pinmux members
export class PinMuxLeafNode extends ANode {

	public readonly type = "pinmuxLeafNode";
	public constructor(
		private ifaceMgrs: (InterfaceInstanceMemberMgr | OptimizablePinMemberMgr | ExtendedPinMemberMgr)[]) {
		super("pinmuxLeafNode");
	}

	public getMembers() {
		return this.ifaceMgrs;
	}

	public override getNumColumns() {
		return _.chain(this.ifaceMgrs)
			.map((mgr) => {
				if (mgr instanceof InterfaceInstanceMemberMgr) {
					// We have one column per pin configurable, plus the pin name/value
					return _.size(mgr.valueObjectMgr.getPinConfigurablesHeaders()) + 2;
				}
				return 2; // name and value
			})
			.max()
			.value();
	}

	public matchSubItemPath(itemPath: string[]) {
		if (2 === _.size(itemPath)) {
			// pin under a specific peripheral
			const instMemMgr = _.find(this.getMembers(), (c) => {
				if (c.valueObjectMgr instanceof InterfaceInstanceMgr) {
					return c.valueObjectMgr.getID() === itemPath[0];
				} else {
					// shouldn't be any nested members for pins
					return false;
				}
			});
			if (instMemMgr && _.includes(instMemMgr.valueObjectMgr.getAllVisibleMemberName(), itemPath[1])) {
				return itemPath;
			}
		} else if (1 === _.size(itemPath)) {
			// just a pin or just a peripheral
			if (_.includes(_.flatMap(this.getMembers(),
				(c) => _.concat(c.def.name, c.valueObjectMgr.getAllVisibleMemberName())),
				_.last(itemPath))) {
				return itemPath;
			}
		}
		return [];
	}
}

// Describe a panel for the static instance
export class StaticContainerNode extends AContainerNode {

	public override readonly type = "container";
	constructor(
		private readonly staticInstMgr: StaticModuleInstanceMgr, collapsed = false) {
		super(staticInstMgr, "static", collapsed);
	}

	public getValidationsummary(validations: Validations): ValidationSummary {
		return validations.getSummary(this.staticInstMgr);
	}

	public getHeading() {
		return "Global Parameters";
	}

	public getSecondaryHeading(): string {
		return "Settings that affect all instances";
	}

	public getChildren() {
		return this.staticInstMgr.getStaticContainerViewNodes();
	}

	public getLongDescription() {
		return "";
	}

	public override matchSubItemPath(itemPath: string[]): MatchedPathRetType {
		const matched = this.staticInstMgr.getNameMgr().getValue() === _.first(itemPath);
		return [matched, _.tail(itemPath)];
	}

	public override getKey(): string {
		return this.getHeading();
	}

	public override isCard() {
		return true;
	}
}

// Special component to render the shared assign drop down
export class SharedAssignLeafNode extends ANode {

	public readonly type = "sharedAssignLeafNode";

	public constructor(
		private readonly member: SharedInstanceMemberMgr) {
		super("SharedMemberDropDown");
	}

	public getMember() {
		return this.member;
	}

	public matchSubItemPath(_itemPath: string[]): string[] {
		return []; // never
	}
}

// Special component to render the top level instance validation.
export class ValidationLeafNode extends ANode {

	public readonly type = "validationLeafNode";

	public constructor(
		private readonly validatable: IValidatable,
		private readonly validations: Validations,
	) {
		super("validationLeafNode");
	}

	public getValidatableObj() {
		return this.validatable;
	}

	public override isHidden(): boolean {
		return !this.validations.getValidation(this.validatable);
	}

	public matchSubItemPath(_itemPath: string[]): MatchedPathRetType {
		return [false, []]; // never
	}
}

export class OtherDepsContainerNode extends AContainerNode {

	private children: ContainerNode[];

	public constructor(instMgr: ModuleInstanceMgr) {
		super(instMgr, "Other Dependencies");
	}

	public getValidationsummary(validations: Validations) {
		return sumarizeContainerNodes(validations, this.children);
	}

	public setContent(children: ContainerNode[]) {
		this.children = children;
	}

	public getLongDescription() {
		return "";
	}

	public getChildren() {
		return this.children;
	}

	public getHeading() {
		return this.getKey();
	}

	public getSecondaryHeading() {
		return "";
	}

	public override isCard() {
		return true;
	}
}

// Find a node by key within the current module
// It does NOT walk owned modules, as keys are unique to their owning modules

export function findNode(nodes: ViewNode[], key: string): ContainerNode {
	for (const n of nodes) {
		if (n.type === "container") {
			if (n.getKey() === key) {
				return n;
			} else if (!(n instanceof ModuleInstanceMemberMgr) && !(n instanceof SharedInstanceMemberMgr)) {
				const found = findNode(n.getChildren(), key);
				if (found) {
					return found;
				}
			}
		}
	}

	return null;
}

export function findParentTabGroup(tabGroup: TabGroup, key: string): TabGroup {
	const nodes = tabGroup.getNodes();
	for (const n of nodes) {
		if (n.getKey() === key) {
			return tabGroup;
		}

		const childTabGroup = n.getUINodes().tabGroup;
		if (childTabGroup) {
			const found = findParentTabGroup(childTabGroup, key);
			if (found) {
				return found;
			}
		}
	}

	return null;
}

function validateConfigurableGroup(configGroup: ConfigurableGroup) {
	return validateMeta(configGroup, "ConfigurableGroup", SCHEMA.ValidateConfigurableGroup);
}

export function createUIStatements(parentIdentifier: string, node: ContainerNode): Statement[] {
	const statements = [];
	const collapsed = node.isCollapsed();
	if (collapsed !== node.getDefaultCollapsedState()) {
		statements.push(new FunctionCall(`collapse(${parentIdentifier}, "${node.getKey()}", ${node.isCollapsed()})`));
	}
	if (node.parentTabGroup?.getCurrentTab().getKey() === node.getKey()) {
		statements.push(new FunctionCall(`tabSelect(${parentIdentifier}, "${node.getKey()}")`));
	}
	return statements;
}

export function tabifyViewNodes(nodes: ViewNode[]): { singleNodes: ViewNode[], tabNodes: ContainerNode[] } {
	const [tabNodes, configurableNodes] = _.partition(nodes, (node) => isTab(node));
	if (tabNodes.length >= 2) {
		// check for otherDeps container node
		const otherDeps = _.remove(configurableNodes, (node) => node instanceof OtherDepsContainerNode);
		if (otherDeps) {
			tabNodes.push(...otherDeps);
		}
		// An array of viewNodes should be seen as tabs
		return { singleNodes: configurableNodes, tabNodes: (tabNodes as ContainerNode[]) };
	}
	return { singleNodes: nodes, tabNodes: [] };
}

export function isCard(userPreferenceTabs: boolean, style: "card" | "tab") {
	switch (style) {
		case "tab": return false;
		case "card": return true;
		default: return !userPreferenceTabs; // style is undefined
	}
}

function isTab(node: ViewNode) {
	return isContainerNode(node) && !node.isCard() && !node.isHidden();
}

function isContainerNode(node: ViewNode): node is ContainerNode {
	return node.type === "container";
}

export function splitViewNodes(
	nodes: ViewNode[],
	parent: ModuleInstanceMgr | ContainerNode,
): OrganizedViewNodes {
	const { singleNodes, tabNodes } = tabifyViewNodes(nodes);

	if (_.isEmpty(tabNodes)) {
		parent.childTabGroup = null;
		return { singleNodes: nodes, tabGroup: null };
	}

	if (!parent.childTabGroup) {
		parent.childTabGroup = new TabGroup(tabNodes);
	}
	// since the tabs can be dynamic we should refresh if anything changes
	parent.childTabGroup?.refresh(tabNodes);
	return { singleNodes, tabGroup: parent.childTabGroup };
}

export interface OrganizedViewNodes {
	singleNodes: ViewNode[];
	tabGroup: TabGroup;
}
