import * as _ from "lodash";
import React = require("react");
import { TableCell, TableRow, Typography } from "../../imports/material-ui-imports";
import { getPinColor, PinType, PIN_SIZE } from "./devicePinTypes";

interface LegendEntryProps {
	pinType: PinType;
	packageDescription: DeviceInfo.PackageDescription;
}

export function LegendEntry({ pinType, packageDescription }: LegendEntryProps) {

	const shapeStyle: React.CSSProperties = React.useMemo(() => ({
		...(packageDescription.type === "QFP" ? legendRectangleStyling : legendCircleStyling),
		backgroundColor: getPinColor(pinType, false),
	}), [pinType, packageDescription]);

	return (
		<TableRow>
			<TableCell>
				<Typography>{pinType}</Typography>
			</TableCell>
			<TableCell>
				<div style={shapeStyle} />
			</TableCell>
		</TableRow>
	);
}

const legendCircleStyling: React.CSSProperties = { width: PIN_SIZE / 1.5, height: PIN_SIZE / 1.5, borderRadius: "50%" };
const legendRectangleStyling: React.CSSProperties = { width: PIN_SIZE, height: PIN_SIZE / 2 };
