import * as  _ from "lodash";
import { SysConfigEnv } from "embed/core";
import { parseAndResolveArgs } from "../../pinmux/services/args/parseAndResolveArgs";
import { createLoader } from "../../pinmux/services/resources/otherLoaders/scriptAndProductLoader";
import { createAvailableProducts } from "../../pinmux/services/product/available";
import { fs as sysConfigFS } from "../../pinmux/services/fileSystem";
import { runScripts } from "../../pinmux/services/scripting/runScript";
import { ConfigStore } from "../../pinmux/services/configStore";
import { getDeviceDescriptions } from "../../pinmux/services/data";
import { darkTheme, defaultTheme, ThemeType } from "../../pinmux/components/styles/themes";
import { createGlobalServices } from "./globalServices";
import { createInternals } from "./createInternals";

interface InternalEnv {
	configStore: ConfigStore;
	globalServices: ReturnType<typeof createGlobalServices>
}

// Map of the creating environment to the configStore and global services.  This allows the UI to access the internal 
// objects without exposing them to the containing application

export const envMap = new WeakMap<SysConfigEnv, InternalEnv>();

export async function asyncCreateEnv(modalRoot: HTMLElement, notificationRoot: HTMLElement, argv: string[]) {
	const globalServices = createGlobalServices(modalRoot, notificationRoot);
	const knownProducts = await createAvailableProducts();
	const resolvedArgs = await parseAndResolveArgs(argv, createLoader(sysConfigFS), knownProducts);
	const sysConfig = await runScripts(resolvedArgs, globalServices.errorStore, true, undefined, true);

	const deviceDiscoveryData = await getDeviceDescriptions();
	const configStore = new ConfigStore(
		sysConfig,
		globalServices.notificationService,
		globalServices.modalService,
		globalServices.errorStore,
		argv,
		deviceDiscoveryData,
	);

	globalServices.updateTheme(resolvedArgs.theme === ThemeType.DARK ? darkTheme : defaultTheme);

	const internals = createInternals({ sysConfig, configStore });

	const env = {
		internals,
		get system() {
			return sysConfig.getRuntimes()[configStore.getContextSelection().selectedIndex].createSystemObj();
		},
		get scripting() {
			return sysConfig.getRuntimes()[configStore.getContextSelection().selectedIndex].getScripting();
		},
	};
	envMap.set(env, { configStore, globalServices });
	return env;
}

