import * as _ from "lodash";
import { ExternalSimulation, SpiceSimulation } from "public/defs";
import { ProgressCallback, launchExternalExecutable } from "../externalExecutable";
import { SCHEMA } from "../JSONschemata";
import { validateMeta } from "../JSONschemaValidator";
import { allowPathVisibility } from "../pathsVisibility";
import { disableScriptingForCallback } from "../scripting/scriptingGuard";
import { memoizeOneCancellable, doWhenUIIdle, assertUnreachable } from "../utils";
import { SimulationTreeNode } from "./simulationTreeNode";
import { isExternalSimulation, isSpiceSimulation } from "./simulation";
import { Runtime } from "../resources/runtime";
import { IModalService } from "../IModalService";
import { getAnalytics } from "../analytics";
import { onSpiceSimulationComplete, launchSpice } from "./spiceSimulation";

export function fetchSimData(
	simulationTreeNode: SimulationTreeNode, runtime: Runtime, modalService: IModalService, progressCallback: ProgressCallback
) {
	const { simulation, productPath } = simulationTreeNode.def;
	if (isExternalSimulation(simulation)) {
		return fetchSimDataMemo(simulation, productPath, simulationTreeNode.getUIHash(), modalService, progressCallback);
	} else if (isSpiceSimulation(simulation)) {
		return fetchSpiceSimDataMemo(simulation, productPath, simulationTreeNode.getUIHash(), modalService, runtime, progressCallback);
	} else {
		assertUnreachable(simulation);
	}
}

const fetchSpiceSimDataMemo = memoizeOneCancellable((
	simulation: SpiceSimulation,
	productPath: string,
	_uiHash: string,
	modalService: IModalService,
	runtime: Runtime,
	progressCallback: ProgressCallback,
) => {
	const simOptions = disableScriptingForCallback(() => allowPathVisibility(() => simulation.onLaunch()));
	const onDone = getAnalytics().recordSimulation(simOptions);
	try {
		const { response, cancel } = launchSpice(productPath, simOptions, runtime, modalService, progressCallback);
		const result = response.then((res) => doWhenUIIdle(() => onSpiceSimulationComplete(res)));
		result.then(() => onDone(), (e) => onDone(e.toString()));
		return { result, cancel };
	} catch (e) {
		onDone(e.toString());
		throw e;
	}
});

const fetchSimDataMemo = memoizeOneCancellable((
	simulation: ExternalSimulation,
	productPath: string,
	_hash: string,
	modalService: IModalService,
	progressCallback: ProgressCallback,
) => {
	const launchParams = allowPathVisibility(() => disableScriptingForCallback(() => simulation.onLaunch()));
	const { response, cancel } = launchExternalExecutable(productPath, launchParams, false, modalService, undefined,
		simulation.hasProgress ? progressCallback : null);

	// The validate call took 50ms for a 10 million point file.  So even though it's a huge object to validate, it seems 
	// to run fast enough that we don't have to worry about it

	const result = response.then((res) => disableScriptingForCallback(() => doWhenUIIdle(() =>
		validateMeta(simulation.onComplete(res), simulation.name, SCHEMA.Plots))));
	return { result, cancel };
});
