import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { Nodes } from "../nodes/Nodes";
import { Edges } from "../edges/Edges";
import { Joints } from "../edges/Joints";
import { EdgeTooltip } from "../edges/EdgeTooltip";
import { Groups } from "../groups/Groups";
import * as Layout from "../types/layoutTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { IGraphProps } from "../types/IGraphProps";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// This component renders a graph based on the passed in layout.
// If the layout contains groups, each group will render a group box, and then another one of these components.

type OuterGraphProps
	= "onMouseDownNode"
	| "onMouseMove"
	| "onMouseUp"
	| "onMouseDownPort"
	| "onMouseUpPort"
	| "onClickPort"
	| "onAutoArrange"
	| "onClickAway";

export interface IInnerGraphProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr> extends
	Omit<IGraphProps<InstMgr, PortMgr>, OuterGraphProps | "setCursorMode">,
	ClassesType {
	searchText: string;
	onMouseDownNode: (event: React.MouseEvent, node: InstMgr) => void;
	onMouseDownPort: (event: React.MouseEvent, port: PortMgr) => void;
	onMouseUpPort: (event: React.MouseEvent, port: PortMgr) => void;
	onClickPort: (event: React.MouseEvent, port: PortMgr) => void;
}

interface IState<PortMgr extends AnyMemberMgr> {
	currentlyHighlightedEdge: Layout.Edge<PortMgr>;
}

export class InnerGraph<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.Component<IInnerGraphProps<InstMgr, PortMgr>, IState<PortMgr>> {
	public override state: IState<PortMgr> = {
		currentlyHighlightedEdge: null,
	};

	public override render() {
		const {
			layout,
			treeNode,
			nodeFactory,
			canMemoize,
			onMouseDownNode,
			onClickNode,
			onMouseDownPort,
			onMouseUpPort,
			onClickEdge,
			getEdgeToolTip,
			actions,
			validations,
			displayScriptName,
			usedInstances,
			disabledInstances,
			searchText,
			classes,
			userAction,
			onClickPort,
			formatter,
			cursorMode,
		} = this.props;

		const result = <>
			<Groups {...this.props} />
			<Nodes
				treeNode={treeNode}
				nodeFactory={nodeFactory}
				canMemoize={canMemoize}
				nodes={layout.nodes}
				validations={validations}
				onClickNode={onClickNode}
				onMouseDownNode={onMouseDownNode}
				onMouseDownPort={onMouseDownPort}
				onMouseUpPort={onMouseUpPort}
				onClickPort={onClickPort}
				actions={actions}
				usedInstances={usedInstances}
				disabledInstances={disabledInstances}
				classes={classes}
				displayScriptName={displayScriptName}
				searchText={searchText}
				userAction={userAction}
				cursorMode={cursorMode}
				formatter={formatter}
			/>
			<EdgeTooltip selectedEdge={this.state.currentlyHighlightedEdge} getEdgeToolTip={getEdgeToolTip} classes={classes} />
			<svg className={classes.svgEdgesContainer}>
				<g>
					<Edges
						edges={layout.edges}
						classes={classes}
						onMouseEnterEdge={this.onMouseEnterEdge}
						onMouseLeaveEdge={this.onMouseLeaveEdge}
						onClickEdge={onClickEdge}
						highlightedEdges={this.props.highlightedEdges}
						selectedEdges={this.props.selectedEdges}
					/>
					<Joints key="joints" joints={layout.joints} className={classes.joint} />
				</g>
			</svg>
		</>;
		return result;
	}

	private onMouseEnterEdge = (currentlyHighlightedEdge: Layout.Edge<PortMgr>) => {
		this.setState({ currentlyHighlightedEdge });
		this.props.onMouseEnterEdge(currentlyHighlightedEdge);
	}

	private onMouseLeaveEdge = () => {
		this.setState({ currentlyHighlightedEdge: null });
		this.props.onMouseLeaveEdge();
	}
}
