// UI Views for meta content defined configurables
import * as React from "react";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { NumericConfigurableMgr } from "../../../services/objectManagers/configurables/numericConfigurableMgr";
import { stringMatchFormat } from "../../../services/utils/numberUtils";
import { DebouncedFilteredInputBox } from "../../higherOrderComponents/ComposedComponents";
import { isNumberConfigurable } from "../../../services/objectManagers/configurables/configurable";

export class CNumericConfigurable extends React.Component<{
	mgr: NumericConfigurableMgr<number | bigInt.BigInteger>;
	actions: IConfigurablesActions;
}> {
	public override render() {
		const mgr = this.props.mgr;
		return (
			<DebouncedFilteredInputBox
				value={mgr.getValueAsString()}
				id={mgr.def.name}
				type="text"
				disabled={!!mgr.uiState.readOnly}
				resyncTrigger={mgr}
				onChange={this.onChange}
				filter={this.filter}
			/>
		);
	}

	private onChange = (val: string) => {
		this.props.actions.setNumericConfigurableValue(this.props.mgr, val);
	}

	private filter = (val: string) => {
		return stringMatchFormat(val, this.props.mgr.getFormats(), isNumberConfigurable(this.props.mgr.def));
	}
}
