import * as _ from "lodash";
import * as Layout from "../../graph/types/layoutTypes";
import { ElkNode, ElkPort, ElkEdge } from "elkjs";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";
import { Position } from "public/runtime";
import { elkLayout, elkNodeLayoutOptions, elkRootLayoutOptions } from "../../graph/autoLayout/elkLayout";
import { getUnroutedLayout } from "./layout";

export async function autoArrange(nodes: ModuleInstanceMgr[]) {
	const elkGraph = generateElkGraph(nodes);
	const layout = await elkLayout(elkGraph);
	const positions = _.map(layout.children, ({ x, y }) => [x, y] as Position);
	return { nodes, positions };
}

function generateElkGraph(nodeInsts: ModuleInstanceMgr[]) {
	const nodes = toElk(getUnroutedLayout(nodeInsts));
	const edges = _.flatMap(nodeInsts, getEdges);
	return {
		id: "$root",
		layoutOptions: {
			...elkRootLayoutOptions,

			// Elk spacing settings are documented here: 
			// https://www.eclipse.org/elk/reference/groups/org-eclipse-elk-spacing.html
			// https://www.eclipse.org/elk/reference/groups/org-eclipse-elk-layered-spacing.html

			// The below options were chosen based on personal preference.  Longer term, we can adjust based on 
			// feedback or consider making then dynamic based on screen size or user settings

			"elk.layered.spacing.nodeNodeBetweenLayers": "100",
			"elk.spacing.nodeNode": "40",

			// Uncomment the following to drive settings from the first module's configurable.  Useful to quickly 
			// explore the effects of those settings

			// "elk.layered.spacing.nodeNodeBetweenLayers": _.first(nodeInsts).memberMgrs.nodeNodeBetweenLayers.getValue().toString(),
			// "elk.layered.spacing.edgeNodeBetweenLayers": _.first(nodeInsts).memberMgrs.edgeNodeBetweenLayers.getValue().toString(),
			// "elk.layered.spacing.edgeEdgeBetweenLayers": _.first(nodeInsts).memberMgrs.edgeEdgeBetweenLayers.getValue().toString(),
			// "elk.spacing.nodeNode": _.first(nodeInsts).memberMgrs.nodeNode.getValue().toString(),
			// "elk.spacing.edgeNode": _.first(nodeInsts).memberMgrs.edgeNode.getValue().toString(),
			// "elk.spacing.edgeEdge": _.first(nodeInsts).memberMgrs.edgeEdge.getValue().toString(),
		},
		children: nodes,
		edges,
	};
}

function toElk(nodes: Layout.Node<ModuleInstanceMgr, PortMemberMgr>[]): ElkNode[] {
	return _.map(nodes, (node) => {
		return {
			id: node.id,
			layoutOptions: elkNodeLayoutOptions,
			width: node.width,
			height: node.height,
			ports: toElkPorts(node.ports),
		};
	});
}

function toElkPorts(ports: Layout.Port<PortMemberMgr>[]): ElkPort[] {
	const [output, input] = _.partition(ports, (port) => port.type === "output");
	return [
		..._.map(output, (port, index) => toElkPort(port, "EAST", index)),
		..._.map(input, (port, index) => toElkPort(port, "WEST", (input.length - index - 1))),
	];
}

function toElkPort(port: Layout.Port<PortMemberMgr>, side: "EAST" | "WEST", index: number) {
	return {
		id: port.id,
		width: port.width,
		height: port.height,
		layoutOptions: {
			"port.side": side,
			"port.index": index.toString(),
		},
	};
}

function getEdges(inst: ModuleInstanceMgr): ElkEdge[] {
	const [outputs] = inst.getPorts();
	return _.flatMap(outputs, (source) =>
		_.map(source.getPortConnections(), ({ port: target }) => ({
			id: source.getID() + target.getID(),
			sources: [source.getID()],
			targets: [target.getID()],
		})));
}
