import { PinmuxPinInterfaceInstanceMgr } from "../objectManagers/pinmuxPinInterfaceInstance";
import { FormatStyle, CLIFormatOptions, UIFormatOptions, FormatOptions } from "./formattingTypes";
import { FormattedMsgPart, toFormattedLink, FormattedLinkAndDestination } from "./link";
import { assertUnreachable, formatRootInterfaceCLI } from "../utils";
import * as _ from "lodash";
import { TabName } from "../tabNames";

export function format(instMgr: PinmuxPinInterfaceInstanceMgr, options: CLIFormatOptions, member?: string): string;
export function format(
	instMgr: PinmuxPinInterfaceInstanceMgr, options: UIFormatOptions, member?: string): FormattedLinkAndDestination;
export function format(instMgr: PinmuxPinInterfaceInstanceMgr, options: FormatOptions, member?: string): FormattedMsgPart;
export function format(instMgr: PinmuxPinInterfaceInstanceMgr, options: FormatOptions, member?: string) {
	switch (options.style) {
		case FormatStyle.CLI:
			return formatCLI(instMgr, member);
		case FormatStyle.UI:
			return formatUI(instMgr, options, member);
		default:
			assertUnreachable(options);
			return "";
	}
}

function formatCLI(instMgr: PinmuxPinInterfaceInstanceMgr, member?: string) {
	return formatRootInterfaceCLI(instMgr, member);
}

function formatUI(instMgr: PinmuxPinInterfaceInstanceMgr, options: UIFormatOptions, member?: string) {

	// GPIO interface instances NEVER have a parent, so this is trivial
	return toFormattedLink(
		instMgr.getContextId(),
		instMgr.getContextDisplayName(),
		instMgr.isReservation() ?
			TabName.RESERVATION :
			TabName.PERIPHERALS,
		instMgr.iface.name,
		instMgr,
		member ?
			instMgr.memberMgrs[member].def :
			undefined,
		options.selection,
	);
}
