import * as bigInt from "big-integer";
import * as _ from "lodash";
import { DisplayFormat } from "public/defs";
import { Radix, getAdvancedDisplayFormatOptions, getRadix, numStringIsDec, strLenFromBitsize } from "./numberUtils";

// Convert a bigInt to a string with specific target radix
function formatBigInt(val: bigInt.BigInteger, radix: Radix = Radix.DEC, bitSize?: number) {
	const rawValueStr = val.toString(radix).toUpperCase();
	if (radix === Radix.HEX) {
		return "0x" + // leading 0x for readability
			(
				bitSize ?
					_.padStart(rawValueStr, strLenFromBitsize(bitSize), "0")
					: rawValueStr
			);
	} else {
		return rawValueStr;
	}
}

export function stringToNum(val: string) {
	let valInBigInt: bigInt.BigInteger;
	try {
		const inputRadix = numStringIsDec(val) ? 10 : 16;
		val = _.trimStart(val, "0x");
		valInBigInt = bigInt(val, inputRadix);
	} catch (_e) {
		valInBigInt = bigInt.zero;
	}
	return valInBigInt;
}

export function numToString(val: bigInt.BigInteger, displayFormat?: DisplayFormat) {
	return formatBigInt(val, getRadix(displayFormat), getAdvancedDisplayFormatOptions("bitSize", displayFormat));
}

export function isInRange(val: bigInt.BigInteger,
	range: [low: bigInt.BigInteger | number, high: bigInt.BigInteger | number]) {
	return _.isEmpty(range) || (val.geq(range[0]) && val.leq(range[1]));
}
