import * as _ from "lodash";
import { SerialPortConfigurable, SerialPortConfigurableResult } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { getAnalytics } from "../../analytics";
import { FormattersMap } from "../../formatting/formattersMap";
import { IModalService } from "../../IModalService";
import { isCloud } from "../../platform";
import { Runtime } from "../../resources/runtime";
import { disableScriptingForCallbackAsync } from "../../scripting/scriptingGuard";
import { AObjectMgr } from "../object";
import { Validations } from "../validations";
import { ButtonConfigurableMgr } from "./buttonConfigurableMgr";

export class SerialPortConfigurableMgr extends ButtonConfigurableMgr<SerialPortConfigurableResult, SerialPortConfigurable> {

	// The selected serial port is a static member because we want to remember what port 
	// was selected regardless of what happens in SysConfig. We can't serialize or store an index
	// of the available ports since the available ports may change every time

	private static selectedSerialPorts: Record<string, SerialPort> = {};

	private static setSelectedSerialPort(mgr: SerialPortConfigurableMgr, port: SerialPort) {
		this.selectedSerialPorts[mgr.getPortKey()] = port;
	}

	private static getSelectedSerialPort(mgr: SerialPortConfigurableMgr) {
		return this.selectedSerialPorts[mgr.getPortKey()];
	}

	constructor(
		parentObjectMgr: AObjectMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		def: SerialPortConfigurable,
		runtime: Runtime,
	) {
		super(parentObjectMgr, formattersMap, def, runtime);
	}

	public override getAdditionalSetting() {
		return {
			label: "Serial Port",
			buttonText: "Select",
			isSet: async () => !!(await this.getSelectedPort()),
			set: async () => !!(await this.selectPort()),
		};
	}

	public override async getClickResultImpl(_productPath: string, modalService: IModalService): Promise<SerialPortConfigurableResult> {
		let port = await this.getSelectedPort();
		if (!port) {
			port = await this.selectPort();
		}
		if (port) {
			return this.program(port, modalService);
		}
		return null;
	}

	protected override getDisabledReason(validations: Validations) {
		if (_.isUndefined(navigator.serial)) {
			return isCloud() ? "Not supported in this browser - try Chrome instead" : "Not supported in CCS";
		}

		return super.getDisabledReason(validations);
	}

	private getPortKey() {
		return JSON.stringify(this.def.serialPortFilter);
	}

	private async getSelectedPort(): Promise<SerialPort> {

		// Get previously selected port (if any) and verify it's still connected

		const port = SerialPortConfigurableMgr.getSelectedSerialPort(this);
		if (port) {
			const availablePorts = await navigator.serial.getPorts();
			return _.includes(availablePorts, port) ? port : null;
		}
		return null;
	}

	private async selectPort(): Promise<SerialPort> {
		try {
			const port = await navigator.serial.requestPort({ filters: this.def.serialPortFilter });
			SerialPortConfigurableMgr.setSelectedSerialPort(this, port);
			return port;
		} catch {

			// requestPort() throws if the user pressed cancel.  In that case, don't updating the pairing but return
			// the previous pairing

			return SerialPortConfigurableMgr.getSelectedSerialPort(this);
		}
	}

	private async program(port: SerialPort, modalService: IModalService): Promise<SerialPortConfigurableResult> {

		// If the meta-content returns a string this is an expected error and we show just an error modal (no stack trace)
		// If the meta-content throws this is an unexpected error and we will throw and show error modal (stack trace)
		// If void than the callback was successful

		const onDone = getAnalytics().recordSerialPort();
		try {
			const error = await modalService.showProgressDuring(
				this.def.callbackDescription,
				async (setProgress) => disableScriptingForCallbackAsync(async () => this.def.onSerial(
					this.parentObjectMgr.managedObject, port, setProgress, this.getPopupMgr()?.managedObject)),
				true);
			onDone(error);

			// Handle expected error

			if (_.isString(error)) {
				modalService.showErrorModal(
					`Something went wrong ${this.def.callbackDescription.toLowerCase()}`,
					null,
					undefined,
					undefined,
					undefined,
					undefined,
					error,
				);
			}
			return { error };
		} catch (e) {
			onDone(e.toString());
			throw e;
		}
	}
}
