import React = require("react");
import * as _ from "lodash";
import { Solution } from "../../services/solver/requirements";
import { DropDown } from "../DropDown";
import { SelectionSupplementary } from "../SelectionSupplementary";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { ILinkActions } from "../actions/ILinkActions";
import { OverrideMgr, AllowConflictsMgr } from "../../services/objectManagers/assignMembers";
import { InterfaceInstance, Pin } from "public/runtime";
import { Const, decorateAny } from "../../services/utils";
import { CValidation } from "./Validation";
import { Validations } from "../../services/objectManagers/validations";

interface IProps {
	wrapperId: string;
	wrapperClass: string;
	onChange: (value: string) => void;
	title?: string;
	selectedOptionName: string;
	disabled: boolean;
	solution: Solution;
	formatter: IFormatter;
	validations: Validations;
	actions: ILinkActions;
	assignMgr: OverrideMgr<InterfaceInstance | Pin>;
	conflictMgr: AllowConflictsMgr<InterfaceInstance | Pin>;
}

export class CAssign extends React.PureComponent<IProps, { isHover: boolean }> {
	constructor(props: IProps) {
		super(props);
		this.state = { isHover: false };
	}

	public override render() {
		const {
			assignMgr, solution, wrapperId, wrapperClass, selectedOptionName, formatter, onChange, actions, validations, conflictMgr,
		} = this.props;
		const readOnly = !!assignMgr.uiState.readOnly;
		const { enabledOptions, disabledOptions } = assignMgr.getUIOptions();
		const solutionDisplayName = solution.assignedToName ?
			_.find([...enabledOptions, ...disabledOptions],
				(o) => o.name === solution.assignedToName).displayName : "";
		const anyOption = {
			name: Const.ANY,
			displayName: decorateAny(solutionDisplayName),
		};
		return (
			<span
				id={wrapperId}
				className={wrapperClass}
				onMouseEnter={this.onMouseEnter}
				onMouseLeave={this.onMouseLeave}
			>
				<DropDown
					{...this.props}
					enabledOptions={[anyOption, ...enabledOptions]}
					disabledOptions={disabledOptions}
					id={wrapperId + "Select"}
					withIcon={true}
					displayScriptName={false}
					disabled={readOnly}
				/>
				<SelectionSupplementary
					solution={solution}
					selectedValue={selectedOptionName}
					formatter={formatter}
					onChange={onChange}
					isHover={this.state.isHover}
					actions={actions}
					memberName={wrapperId}
					disabledReason={readOnly && assignMgr.getToolTip(this.props.validations)}
				/>
				<CValidation
					validations={validations}
					validatableObj={assignMgr}
					formatter={formatter}
					actions={actions}
					memberName={assignMgr.def.name}
				/>
				<CValidation
					validations={validations}
					validatableObj={conflictMgr}
					formatter={formatter}
					actions={actions}
					memberName={conflictMgr.def.name}
				/>
			</span>
		);
	}

	private onMouseEnter = () => this.setState({ isHover: true });
	private onMouseLeave = () => this.setState({ isHover: false });
}
