import React = require("react");
import * as _ from "lodash";
import {
	Card, List, ListItem, IconButton, ListItemSecondaryAction, ListItemIcon,
} from "../imports/material-ui-imports";
import { commonStyles } from "../components/styles/common";
import { ChevronUp, ChevronDown, WindowClose, ArrowExpand } from "../imports/mdi-material-ui-imports";
import { DisplayLongDescButton, LongDescription } from "./LongDescription";
import { getStyledHeading } from "./OutputViews/Output";
import { IFormatter } from "../services/formatting/formattingTypes";
import { ILinkActions } from "./actions/ILinkActions";

interface CollapsibleCardProps {
	heading: string | string[];
	id?: string;
	collapsible?: boolean; // Optionally render chevrons to collapse the card. Has no effect when onClose is specified 
	collapsed?: boolean;
	headerDecorators?: JSX.Element; 	// Optionally display some info in the header
	iconDecorator?: JSX.Element; 		// Optionally icon decorator in the header
	noWrap?: boolean;
	longDescription?: string;
	onClose?: () => void; // Optionally render a close button that calls this function on click.
	toggleExpand?: () => void;
	scrollIntoView?: boolean;
	actions: ILinkActions;
	formatter: IFormatter;
	children: React.ReactNode;
}

interface CollapsibleCardState {
	collapsed: boolean;
	showLongDescription: boolean;
}

export class CollapsibleCard extends React.PureComponent<CollapsibleCardProps, CollapsibleCardState> {

	private cardRef: HTMLElement = null;
	constructor(props: CollapsibleCardProps, context: any) {
		super(props, context);
		this.state = {
			collapsed: (this.props.collapsed ? this.props.collapsed : false),
			showLongDescription: false,
		};
	}

	public override componentDidMount() {
		if (!!this.props.scrollIntoView) {
			this.cardRef.scrollIntoView({ block: "center", inline: "start" });
		}
	}

	public override render() {
		const curExpandedStyle = this.props.noWrap ?
			commonStyles.expandedCardWithNoWrapStyle :
			commonStyles.expandedCardStyle;
		const cardBodyStyle = this.state.collapsed ?
			commonStyles.collapsedCardStyle :
			curExpandedStyle;

		const styledHeading = getStyledHeading(this.props.heading);

		// the reason why we cast button as any: https://github.com/mui-org/material-ui/issues/14971
		return (
			<Card id={this.props.id} style={commonStyles.cardStyle} >
				<List style={{ ...commonStyles.headingStyle, minWidth: "0", display: "flex", flexDirection: "row" }} >
					<ListItem button={this.props.collapsible as any} onClick={this.handleClicked} id={this.props.id + "Toggle"}>
						{this.props.iconDecorator && <ListItemIcon>{this.props.iconDecorator}</ListItemIcon>}
						<div id={this.props.id + "heading"}>{styledHeading}</div>
						{this.props.longDescription && !this.state.collapsed && <DisplayLongDescButton
							name={this.props.id + "longdescription"}
							onClick={() => this.setShowDescription(!this.state.showLongDescription)}
							hidden={false}
						/>}
						{this.props.headerDecorators}
						{this.props.toggleExpand &&
							<div style={{ width: "100%" }}>
								<IconButton
									id={this.props.id + "_maximize"}
									onClick={this.props.toggleExpand}
									style={{ float: "right" }}
								>
									<ArrowExpand color="primary" style={commonStyles.smallIcon} />
								</IconButton>
							</div >
						}
						{this.props.onClose &&
							<div style={this.props.toggleExpand ? {} : { width: "100%" }}>
								<IconButton
									id={this.props.id + "_close"}
									onClick={this.props.onClose}
									style={{ float: "right" }}
								>
									<WindowClose color="primary" style={commonStyles.smallIcon} />
								</IconButton>
							</div >
						}
						{!this.props.onClose && this.props.collapsible &&
							< ListItemSecondaryAction >
								<IconButton onClick={this.handleClicked}>
									{this.state.collapsed ? <ChevronUp color="primary" style={commonStyles.smallIcon} /> :
										<ChevronDown color="primary" style={commonStyles.smallIcon} />}
								</IconButton>
							</ListItemSecondaryAction>
						}
					</ListItem>
				</List>
				<span style={{
					display: "block",
					textAlign: "left",
					paddingLeft: "30px",
					paddingRight: "30px",
				}}>
					{this.state.showLongDescription &&
						<LongDescription
							id={this.props.id + "longdescription"}
							closeDescription={() => this.setShowDescription(false)}
							longDescription={this.props.longDescription}
							canonicalName={this.props.id}
							disableClose={false}
							actions={this.props.actions}
							formatter={this.props.formatter}
						/>}
				</span>
				<div ref={(el) => this.cardRef = el} id={this.props.id + "Body"} style={cardBodyStyle}>
					{this.props.children}
				</div>
			</Card >
		);
	}

	private handleClicked = () => {
		if (this.props.collapsible) {
			this.setState({
				collapsed: !this.state.collapsed,
			});
		}
	}

	private setShowDescription = (status: boolean) => {
		this.setState({ showLongDescription: status });
	}
}
