import * as _ from "lodash";
import { InstanceReferenceConfigurable, PortRequirement } from "public/defs";
import { RuntimeInstance, PortConnection, ModuleInstance, RuntimeObject } from "public/runtime";
import { AMemberMgr, SetSource } from "../member";
import { createInstanceReferenceAssignmentStatement } from "../../scripting/serialize";
import { ModuleInstanceMgr } from "../moduleInstance";
import { getCurrentlyRunningCallbackName, isModuleAccessEnabled } from "../../moduleAccessGuard";
import { FormattersMap } from "../../formatting/formattersMap";
import { ConfigurableMgr } from "./configurableMgr";
import { AObjectMgr } from "../object";
import { Runtime } from "../../resources/runtime";
import { extendException } from "../../niceExceptions";
import { disableScriptingForCallback } from "../../scripting/scriptingGuard";
import { SerializationOptions } from "../../scripting/toScript";
import { convertUnknownToError, mapInternalObjectForJSON } from "../../utils";

export abstract class BaseInstanceReferenceConfigurableMgr<
	ValueType extends ModuleInstance | ModuleInstance[],
	MemberDefinition extends InstanceReferenceConfigurable<ValueType>,
	> extends ConfigurableMgr<ValueType, RuntimeObject, MemberDefinition>
{
	protected abstract onModuleRemoved: (inst: ModuleInstanceMgr) => void;

	// We need to store the last value so that onSet can disconnect anything removed

	private previousValue: ValueType;

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		def: MemberDefinition,
		private readonly defaultValue: ValueType,
		protected readonly runtime: Runtime,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
			defaultValue,
		);
		this.previousValue = this.value;
	}

	// Prevent setting this value via args for serialization reasons mentioned above

	public override setValueFromRequiredArgs() {
		this.preventMetaUpdate();
	}

	public override setValueFromArgs() {
		this.preventMetaUpdate();
	}

	public override removeArgs() {
		this.preventMetaUpdate();
	}

	public override removeReqArgs() {
		this.preventMetaUpdate();
	}

	// Prevent writes from meta-content

	public override set(...args: Parameters<AMemberMgr<PortConnection[], RuntimeInstance, PortRequirement>["set"]>) {
		if (isModuleAccessEnabled()) {
			return super.set(...args);
		}
		this.preventMetaUpdate();
	}

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		if (options.cloneInstance) {
			return [];
		}
		return [createInstanceReferenceAssignmentStatement(
			this.def,
			parentIdentifier,
			this.getRValue(),
		)];
	}

	public setDefault() {
		if (!this.def.getValue) {
			if (this.def.getDefault) {
				const newValue = disableScriptingForCallback(() => this.def.getDefault(this.parentObjectMgr.managedObject));
				try {
					this.set(newValue, SetSource.TOOL_INTERNAL);
				} catch (e) {
					extendException(`while processing getDefault() of ${this.def.name}`, convertUnknownToError(e));
				}
			} else {
				this.set(this.defaultValue, SetSource.TOOL_INTERNAL);
			}
		}
	}

	// We only need to generate scripting.connect functions for one side.  I've chosen the output side as it's one to 
	// many, so that should group the statements

	public override shouldSerialize() {
		return !this.def.getValue;
	}

	public override remove() {
		_.each(this.getValueMgrs(), (mgr) => {
			mgr.onRemove().removeListener(this.onModuleRemoved);
			mgr.onRename().removeListener(this.onModuleRenamed);
		});
		super.remove();
	}

	// Always re-render as we don't know if the set of options changed

	public override getUIHash(): string {
		return null;
	}

	public override jsonify() {
		return mapInternalObjectForJSON(this.value);
	}

	protected abstract getRValue(): string;

	protected abstract getValueMgrs(value?: ValueType): ModuleInstanceMgr[];

	protected getEnabledOptions() {
		const insts = disableScriptingForCallback(() => this.def.options(this.parentObjectMgr.managedObject));
		return _.map(insts, (inst) => ({
			name: this.runtime.getManager(inst).getID(),	// Allows options to work when we have duplicate names
			displayName: inst.$name,
			data: inst,
		}));
	}

	protected override defaultValueType(): string {
		return typeof this.defaultValue;
	}

	protected override toLValue() {
		const cb = getCurrentlyRunningCallbackName();
		if (cb && cb !== "ports") {
			throw new Error(`Cannot access module instance references in '${cb}'`);
		}

		return this.value;
	}

	protected override onSet() {
		const previous = this.getValueMgrs(this.previousValue);
		const current = this.getValueMgrs();
		_.each(_.difference(previous, current), (inst) => {
			inst.onRemove().removeListener(this.onModuleRemoved);
			inst.onRename().removeListener(this.onModuleRenamed);
		});
		_.each(_.difference(current, previous), (inst) => {
			inst.onRemove().addListener(this.onModuleRemoved);
			inst.onRename().addListener(this.onModuleRenamed);
		});
		this.previousValue = this.value;
	}

	private onModuleRenamed = (_inst: ModuleInstanceMgr, source: SetSource) => {
		this.parentObjectMgr.onMemberChanged(this, source);
	}

	private preventMetaUpdate() {
		throw new Error("module instance references cannot be set outside of scripts");
	}
}
