import { NumberConfigurable } from "public/defs";
import {
	errorIfNotInteger, isInRange, logErrorIfIntegerAndNotSafe,
	NumStrFormatType, numToString, Radix, stringToNum,
} from "../../utils/numberUtils";
import { SetSource } from "../member";
import { Validations } from "../validations";
import { NumericConfigurableMgr } from "./numericConfigurableMgr";

export class NumberConfigurableMgr extends NumericConfigurableMgr<number> {

	public override getScriptValue() {
		return {
			value: this.getValueAsString(),
			shouldQuoteStrings: false,
		};
	}

	public override validate(validations: Validations) {
		super.validate(validations);
		logErrorIfIntegerAndNotSafe(validations, this, this.value);
		if (!isInRange(this.value, this.def.range)) {
			validations.logError(`Must be in the range of ${this.def.range.join(" to ")}`, this);
		}
	}

	public override validateValue(val: number, forceWrite: boolean, source: SetSource) {
		super.validateValue(val, forceWrite, source);

		errorIfNotInteger(this.isInteger(), val);
	}

	// Since we want to automatically convert between the radix, we need to restrict the inputs depending on the radix
	// i.e. we can't allow floating point decimal input into a hex configurable but can allow a positive integer decimal
	public override getFormats(): NumStrFormatType[] {
		return this.getRadix() === Radix.HEX ? ["hex", "posInt"] :
			this.isInteger() ? ["hex", "int"] : ["hex", "dec"];
	}

	protected override stringToNum(val: string) {
		return stringToNum(val);
	}

	protected override numToString(val: number) {
		return numToString(val, this.def.displayFormat);
	}

	private isInteger() {
		return (this.def as NumberConfigurable).isInteger;
	}
}
