import { createFinalSvgPathNode } from "../createSvgPathNode";
import { notCirclePath, notCircleDiameter } from "./NotNode";
import { xorPath, getXOrLabelXOffset, xorWidthAdjustment } from "./XOrNode";
import { getOrPortOffset } from "./OrNode";

// Node for an XNOR gate

function xnorPath(width: number, height: number) {
	return xorPath(width - notCircleDiameter, height) + notCirclePath(width, height);
}

// There will only ever be one output, so hight-based adjustments at the output aren't needed.

export const XNorNode = createFinalSvgPathNode(xnorPath, {
	extraWidth: notCircleDiameter + xorWidthAdjustment,
	inputPortXOffset: getOrPortOffset,
	inputLabelXOffset: getXOrLabelXOffset,
	outputLabelXOffset: () => -notCircleDiameter,
});
