import * as  _ from "lodash";
import { Internals } from "embed/core";
import { ConfigStore } from "../../pinmux/services/configStore";
import { SysConfig } from "../../pinmux/services/sysConfig";
import { CodeGenTemplateFile } from "dataInterfaces";
import { GeneratedFilesViewMgr } from "../../pinmux/services/ui/outputView";
import { getOptions as getOptionsImpl } from "../../test/core/getOptions";
import { RuntimeInstance } from "public/runtime";
import { assertUnreachable } from "../../pinmux/services/utils";

// Given a pre-created SysConfig and ConfigStore, this returns a set of internal functions for an application that 
// embeds SysConfig in itself would need to use.  This is similar to the createInternals function used for testing, and
// where possible the same functions are leveraged, but this version goes through the configStore.  That makes it 
// slightly slower, but it handles undo/redo, history and unwinding after an exception

export function createInternals(impl: { sysConfig: SysConfig, configStore: ConfigStore }): Internals {

	function switchContext(contextName: string) {
		const contextIndex = _.findIndex(impl.configStore.getContextSelection().contexts, (c) => c.name === contextName);
		if (-1 === contextIndex) {
			throw new Error("Unknown context: " + contextName);
		}
		impl.configStore.setSelectedContext(contextIndex);
	}

	// eslint-disable-next-line @typescript-eslint/require-await
	async function asyncGetTemplates() {
		const codeView = _.find(impl.configStore.getViewMgrs(), (v): v is GeneratedFilesViewMgr => v.type === "code");
		return _.chain(codeView.getTemplates())
			.dropRight() // The last one is the .syscfg file
			.map((t) => t.path)
			.value();
	}

	// eslint-disable-next-line @typescript-eslint/require-await
	async function asyncGenerate(templateName: string) {
		const codeView = _.find(impl.configStore.getViewMgrs(), (v): v is GeneratedFilesViewMgr => v.type === "code");
		const template = _.find(codeView.getTemplates(), (t) => t.path === templateName);
		if (!template) {
			throw new Error("Unknown template: " + templateName);
		}
		return impl.configStore.generateCode(template);
	}

	// eslint-disable-next-line @typescript-eslint/require-await
	async function asyncSerialize(scriptPath: string = "untitled.syscfg") {
		const scriptTemplateEntry: CodeGenTemplateFile = {
			name: scriptPath,
			path: scriptPath,
			category: "Configuration Script",
			alwaysRun: true,
			ignoreErrors: true,
		};
		return impl.configStore.generateCode(scriptTemplateEntry);
	}

	// eslint-disable-next-line @typescript-eslint/require-await
	async function asyncChange(change: () => void) {
		impl.configStore.gcConfigChange(change);
	}

	function getRuntime() {
		return impl.sysConfig.getRuntimes()[impl.configStore.getContextSelection().selectedIndex];
	}

	function getOptions<T extends number | string>(instance: RuntimeInstance, memberName: string) {
		return getOptionsImpl<T>(getRuntime(), instance, memberName);
	}

	function onChange() {
		return impl.configStore.onUserChange();
	}

	function getTabs() {
		return _.map(impl.configStore.getTabs(), (t) => t.getTitle());
	}

	function setLeftPane(state: "open" | "closed" | "toggle") {
		switch (state) {
			case "open":
				impl.configStore.toggleTabExpansion(true);
				break;
			case "closed":
				if (impl.configStore.getCol1Displayed()) {
					impl.configStore.toggleTabExpansion();
				}
				break;
			case "toggle":
				impl.configStore.toggleTabExpansion();
				break;
			default:
				assertUnreachable(state);
		}
	}

	function lockModule(name: string) {
		impl.configStore.lockModule(name);
	}

	return {
		switchContext,
		asyncGenerate,
		asyncSerialize,
		asyncGetTemplates,
		getOptions,
		asyncChange,
		onChange,
		getTabs,
		setLeftPane,
		lockModule,
	};
}
