import * as _ from "lodash";
import * as path from "path";
import { isNode } from "./platform";
import { rootDir, httpRootDir } from "./paths";

export class HttpError extends Error {
	constructor(message: string, public readonly response: number) {
		super(message);
	}
}

class HttpService {
	public async get(url: string): Promise<string> {
		const req = await this.serverRequest<null>(url, "GET", null);
		return req.response;
	}

	public async put<T extends Document | XMLHttpRequestBodyInit>(url: string, body: T, contentType: string) {
		await this.serverRequest(url, "PUT", body, contentType);
	}

	public async delete(url: string) {
		await this.serverRequest<null>(url, "DELETE", null);
	}

	private serverRequest<T extends Document | XMLHttpRequestBodyInit>(
		url: string, type: "GET" | "POST" | "DELETE" | "PUT", body?: T, contentType?: string
	) {
		if (!_.startsWith(url, "/")) {
			url = httpRootDir() + url;
		}
		return new Promise<XMLHttpRequest>((resolve, reject) => {
			const req = new XMLHttpRequest();
			req.onreadystatechange = () => {
				if (req.readyState === XMLHttpRequest.DONE) {
					let { status } = req;
					if (status === 0) {
						// jxbrowser uses the undocumented status of 0
						// Instead, check if anything was returned

						status = type === "GET" ?
							(req.response ? 200 : 404) : 200;
					}
					if (status !== 200) {
						return reject(new HttpError(req.statusText, status));
					}
					resolve(req);
				}
			};
			req.open(type, url);
			if (contentType) {
				req.setRequestHeader("Content-type", contentType);
			}

			req.send(body);
		});
	}
}

class NodeHttpService extends HttpService {
	private readonly fs = require("fs-extra");
	public override async get(url: string) {
		try {
			const data = await this.fs.readFile(path.join(rootDir(), url));
			return data.toString();
		} catch (e) {
			throw new HttpError(e.toString(), 404);
		}
	}
}

export const http = isNode() ? new NodeHttpService() : new HttpService();
