import { IFormatter } from "../services/formatting/formattingTypes";
import { IConflictActions } from "./actions/IConflictActions";
import { ILinkActions } from "./actions/ILinkActions";
import { InterfaceInstanceMgr } from "../services/objectManagers/interfaceInstance";
import { PinMgr } from "../services/objectManagers/pin";
import * as React from "react";
import * as _ from "lodash";
import { Link } from "../imports/material-ui-imports";
import { FormattedMsg } from "./FormattedMsg";
import { Tooltip } from "./Tooltip";

interface IProps {
	req: PinMgr | InterfaceInstanceMgr;
	actions: IConflictActions & ILinkActions;
	formatter: IFormatter;
}

export class ConflictControl extends React.Component<IProps> {
	public override render() {
		const { req, actions, formatter } = this.props;
		const lockedAdversaries = req.getLockedAdversaries();
		const conflictTooltip = this.getIgnoreConflictTooltipText(lockedAdversaries);
		const allowLink = <Link
			id="ignoreError"
			component="button"
			display="inline"
			underline="always"
			variant="caption"
			color="inherit"
			onClick={(e: React.MouseEvent<HTMLElement>) => {
				e.stopPropagation();
				actions.allowConflict(req, lockedAdversaries);
			}}
		> (Ignore)
		</Link>;

		const disallowLink = <Link
			component="button"
			display="inline"
			underline="always"
			variant="caption"
			color="inherit"
			onClick={(e: React.MouseEvent<HTMLElement>) => {
				e.stopPropagation();
				actions.disallowConflict(req);
			}}
		> Don&apos;t ignore
		</Link>;

		// 3 possibilities:
		// 1. Has a conflict but cannot ignore due to adversaries not locked. Don't show ignore button.
		// 2. Has a conflict and can ignore, show ignore button.
		// 3. Already ignoring conflict, show don't ignore button.

		let conflictControl = null;
		let tooltip: string | JSX.Element = "";
		if (req.getSolverRequirement().areConflictsAllowed()) {
			conflictControl = disallowLink;
		} else if (!_.isEmpty(lockedAdversaries)) {
			conflictControl = allowLink;
			tooltip = <FormattedMsg
				message={formatter(conflictTooltip)}
				actions={actions}
			/>;
		}

		return (
			conflictControl &&
			<Tooltip
				title={tooltip}
				placement="top"
			>
				{conflictControl}
			</Tooltip>
		);
	}

	private getIgnoreConflictTooltipText(adversaries: PinMgr[] | InterfaceInstanceMgr[]) {
		return "Ignore resource conflict with "
			+ _.map<PinMgr | InterfaceInstanceMgr, string>(adversaries, (i) => i.getEncodingTag())
				.join(", ")
			+ ".";
	}
}
