import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";
import { NodeLabels } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { ClassesType } from "../styling/graphStyles";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { typedMemo } from "../../typedMemo";
import { INodeProps } from "../types/nodeTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { Ports } from "../ports/Ports";
import { NodeLayoutAdjustments, withLayoutAdjustments } from "./withLayoutAdjustments";

// This file exposes two functions for creating a react component to represent a node in a graph drawn using an svg 
// path element.  Both functions take a function that can be used to construct the "d" prop of a <path> element based
// on the size of a node.  They also take optional parameters to adjust the layout if the sides are not straight.

// This first function creates a the node component, but doesn't memoize it or apply any layout adjustments to it.  
// This is useful if the final component is going to be a composite of this component (perhaps supplying children).

export function createSvgPathNode(
	d: (width: number, height: number) => string,
	adjustments: LabelAdjustments = {},
) {
	return function SvgPathNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
		props: React.PropsWithChildren<INodeProps<InstMgr, PortMgr> & ClassesType>
	) {
		const {
			node,
			onClickNode,
			onMouseDownNode,
			onMouseDownPort,
			onMouseUpPort,
			onClickPort,
			displayScriptName,
			children,
			classes,
			validations,
			cursorMode,
			formatter,
		} = props;
		return (
			<PositionedNode
				node={node}
				onClick={onClickNode}
				onMouseDown={onMouseDownNode}
				className={classes.positionedNode}
				validations={validations}
				cursorMode={cursorMode}
				formatter={formatter}
			>
				<NodeLabels
					node={node}
					displayScriptName={displayScriptName}
					inputXOffset={adjustments.inputLabelXOffset}
					outputXOffset={adjustments.outputLabelXOffset}
					classes={classes}
				/>
				<Ports
					node={node}
					classes={classes}
					onMouseDownPort={onMouseDownPort}
					onMouseUpPort={onMouseUpPort}
					onClickPort={onClickPort}
					cursorMode={cursorMode}
				/>
				<svg className={classes.svgNodeContainer}>
					<path className={classes.svgNode} d={d(node.width, node.height)} />
				</svg>
				{children}
			</PositionedNode>
		);
	};
}

// This function creates a the node component as above, but memoizes it and applies optional layout adjustments to it.  
// This is useful if this will be the final component used to draw the node.

export function createFinalSvgPathNode(
	d: (width: number, height: number) => string,
	adjustments: Partial<LabelAdjustments & NodeLayoutAdjustments> = {},
) {
	const memoized = typedMemo(createSvgPathNode(d, adjustments));
	return withLayoutAdjustments(memoized, adjustments);
}

// This is the interface for the label adjustments.  These are just used for adjusting the final label offset and thus
// aren't part of the overall layout adjustments necessary

interface LabelAdjustments {
	inputLabelXOffset?: (nodeSize: Layout.Size, y: number) => number;	// The x offset for any input label
	outputLabelXOffset?: (nodeSize: Layout.Size, y: number) => number;	// The x offset for any output label
}
