import { TProbe } from "public/runtime";
import { PortMemberMgr } from "../../services/objectManagers/portMemberMgr";

export enum CursorModeType {
	Connecting,
	Probing,
}

export interface ConnectingMode {
	mode: CursorModeType.Connecting;

	// The port member manager being connected via drag
	dragConnecting: PortMemberMgr;

	// The port member manager being connected via click
	clickConnecting: PortMemberMgr;
}

interface ProbingMode {
	mode: CursorModeType.Probing;
	// specifies the type of probe to be added
	probingMode: TProbe;
}

export type CursorMode = ConnectingMode | ProbingMode;

export function isProbingMode(mode: CursorMode): mode is ProbingMode {
	return mode.mode === CursorModeType.Probing;
}

export function isConnectingMode(mode: CursorMode): mode is ConnectingMode {
	return mode.mode === CursorModeType.Connecting;
}

export function startedDragConnecting(mode: ConnectingMode): boolean {
	return !!mode.dragConnecting;
}

export function startedClickConnecting(mode: ConnectingMode): boolean {
	return !!mode.clickConnecting;
}
