import * as _ from "lodash";
import * as React from "react";
import { ButtonConfigurableMgr } from "../../../../services/objectManagers/configurables/buttonConfigurableMgr";
import { ModuleInstanceMgr, NonObjectMemberMgr } from "../../../../services/objectManagers/moduleInstance";
import { FormattedMsg } from "../../../FormattedMsg";
import { CConfigurable, IConfigurableProps } from "../../../objectManagers/configurables/Configurable";
import { Tooltip } from "../../../Tooltip";

interface IProps extends Omit<IConfigurableProps, "mgr"> {
	moduleMgr: ModuleInstanceMgr;
}

export function FloatingMetaButtons({ moduleMgr, validations, formatter, actions, ...rest }: IProps) {
	if (!moduleMgr) {
		return null;
	}

	const buttons = _.filter(moduleMgr.memberMgrs, (m) => m instanceof ButtonConfigurableMgr) as NonObjectMemberMgr[];
	return <div style={divStyle}>
		{_.map(buttons, (c) => {
			return (
				<Tooltip
					title={<FormattedMsg
						message={formatter(c.getToolTip(validations))}
						actions={actions}
					/>}
					key={c.def.name}
				>
					<CConfigurable
						{...rest}
						mgr={c}
						validations={validations}
						formatter={formatter}
						actions={actions}
					/>
				</Tooltip>
			);
		})}
	</div >;
}

const divStyle = { display: "inline-flex" } as const;
