import * as _ from "lodash";
import { http } from "./http";
import { getIdleInterval } from "./accountManagement";
import { isCloud, isEmbedded } from "./platform";
import { SimpleEvent } from "./simpleEvent";
import type * as Portal from "portal";

export class LoginServer {
	private event = new SimpleEvent<(status: boolean) => void>();
	private socket: Portal.connect;
	private allowPings: boolean;
	private idleInterval: number;
	private pingInterval: NodeJS.Timer;

	constructor() {
		this.init().catch((e) => { console.error(e); });
	}

	public onLoginChanged() {
		return this.event.asRegistration();
	}

	public userEvent = () => {
		// keep the user logged in since they are interacting with the tool
		this.allowPings = true;
	}

	public simulationEvent = () => {
		// keep the user logged in while a simulation is running
		this.userEvent();
	}

	public async handleLogOut() {
		this.clearPing();
		await http.get("/logout?reason=click");
	}

	public handleLogIn() {
		window.location.href = "/login?redirect=" + window.location.toString();
	}

	private setPing() {
		this.pingInterval = setInterval(() => this.ping(), this.idleInterval);
	}

	private clearPing() {
		clearInterval(this.pingInterval);
	}

	private async ping() {
		try {
			if (this.allowPings) {
				this.allowPings = false;
				const app = "?app=sysconfig";
				await http.get("/timeouts/renewIdle" + app);
			}
		} catch (e) {
			console.error(e);
		}
	}

	private notify(status: boolean) {
		this.event.fire(status);
	}

	private async init() {

		// In the cloud, the server will load socket.io from the proxy which embeds itself under window.io

		const Socket = (window as any as { io: typeof Portal }).io.connect;
		this.socket = new Socket(location.origin);
		this.socket.on("login", () => {
			this.notify(true);
			if (!isEmbedded()) {	// Let controlling application issue the reload
				location.reload();
			}
		});

		this.socket.on("logout", () => {
			this.notify(false);
		});

		this.socket.on("preparelogout", () => {
			this.socket.emit("logoutready");
		});

		this.socket.on("asklogout", (data: Portal.LogOutData) => {
			if (!isEmbedded()) {	// Let controlling application issue the logout
				const iframe = document.getElementById("authIFrame") as HTMLIFrameElement;
				iframe.src = "/logout?reason=" + data.reason + "&redirect=/emptypage";
			}
		});

		// Detect the idle interval and ping based on that

		this.idleInterval = await getIdleInterval();
		this.setPing();

		// Register listeners for user interaction
		// Since specific DOM node event listeners may block propagation, we also expose userEvent publicly so the 
		// ConfigStore can update us on any configuration change.  This is a super short and fast function, so extra
		// calls will not impact performance

		document.addEventListener("keydown", this.userEvent, false);
		document.addEventListener("mousedown", this.userEvent, false);
	}
}

export const loginServer = (isCloud()) ? new LoginServer() : null;
