import * as React from "react";
import * as _ from "lodash";
import { Typography, Link } from "../../imports/material-ui-imports";
import { InvalidMinToolVersion } from "../../services/product/versionCheck";
import { BasicModal, IModalMinProps } from "./BasicModal";
import { openExternalLink } from "../../services/externalLink";
import { ModalButton } from "../buttons/ModalButton";
import { isUnderTest } from "../../services/platform";

interface IUpdateProps extends IModalMinProps {
	error: InvalidMinToolVersion;
	confirmAction: () => void;
}

export const updateTitleText = "Update Required";

// main non dismissible update modal
export class UpdateModal extends React.Component<IUpdateProps> {
	public override render() {
		const { error, confirmAction, ...rest } = this.props;
		return (
			<BasicModal
				{...rest}
				title={updateTitleText}
				onClose={() => { }}
				actions={
					// Should be able to dismissible in testing
					// this because we can't go to a different route while a dialog is up
					isUnderTest() && (
						<ModalButton id="confirmYesBtn" onClick={confirmAction}>
							Go to start
						</ModalButton>)
				}
			>
				<UpdateModalContent error={error} />
			</BasicModal>
		);
	}
}

// Modal content
export class UpdateModalContent extends React.Component<Pick<IUpdateProps, "error">> {

	public override render() {
		const { error } = this.props;
		return (
			<Typography id="updateRequired" variant="body2" display="inline">
				{
					_.map(error.products, (p, index) => <span key={index}>{error.getProductErrorMessage(p)}<br></br></span>)
				}
				<span>For more information{" "}
					<Link
						display="inline"
						component="button"
						underline="hover"
						variant="body2"
						style={{ verticalAlign: "baseline" }}
						onClick={() => openExternalLink(error.moreInfoLink)}>see
					</Link>.
				</span>

			</Typography>
		);
	}
}
