import * as _ from "lodash";
import { SuggestedSolution } from "../suggestedSolution";
import { Peripheral as PeripheralReq, Pin } from "../requirements";
import * as DeviceData from "dataInterfaces";

// This class encapsulates the logic for any choice (perf, pin, optimized pin) on if it's valid or not
// This helps since we have different choice factories to handle each, but they all check fairly 
// similar stuff on if a choice is valid or not

export class ChoiceValidator {

	constructor(
		private readonly restrictToPreferredPins = false,
		private readonly suggestedSolution?: SuggestedSolution) { }

	public isSolveRestricted() {
		return this.restrictToPreferredPins || this.suggestedSolution;
	}

	// Returns true if the choice is valid, false if it's not for some reason

	public isValid(
		req: PeripheralReq,
		peripheral: DeviceData.Peripheral): boolean;
	public isValid(
		req: Pin,
		pin: DeviceData.DevicePin,
		signal: DeviceData.PeripheralPin): boolean;
	public isValid(
		req: PeripheralReq | Pin,
		perfOrPin: DeviceData.Peripheral | DeviceData.DevicePin,
		signal?: DeviceData.PeripheralPin) {

		// Is there a choice at all?

		return (
			perfOrPin &&

			// Is the requirement not an override, or a valid override

			(!req.userOverride || req.userOverride === perfOrPin.name) &&

			// Is it not a restricted requirement, or a valid restriction?

			(!req.restrictTo || (req instanceof Pin ?
				_.includes(req.restrictTo[signal.name], perfOrPin.name) :
				_.includes(req.restrictTo, perfOrPin.name))) &&

			// Is it a preferred pin, or are we not restricting to only preferred pins?
			// Note, we don't need to use preferred pins if connected to hardware or the
			// user overrode the pin choice - only for free header pins

			(!this.restrictToPreferredPins || (req instanceof PeripheralReq) ||
				req.userOverride || req.connectedToHardware ||
				_.includes(req.preferredPins, perfOrPin.name)) &&

			// Is there no suggested solution, or is the choice in it?
			// Note: Cast shouldn't be needed, but TS won't consider the overload restrictions

			(!this.suggestedSolution || this.suggestedSolution.contains(
				perfOrPin as DeviceData.DevicePin, req as Pin))
		);
	}
}
