import * as _ from "lodash";
import React = require("react");
import {
	ListItem, List, ListItemSecondaryAction, ListItemIcon, Typography,
} from "../imports/material-ui-imports";
import { ChevronDown } from "../imports/mdi-material-ui-imports";
import { IStatusDecoratorProps, StatusDecorator, StatusType, TextDecorator } from "./Decorators";
import { HardwareComponentMgr } from "../services/instanceContainers/hardwareComponent";
import { ConfigStoreActions } from "../services/configStore";
import { AddAdaptedTreeNodeButton } from "./AddAdaptedTreeNodeButton";
import { AttachDetachSoftwareButton } from "./AttachDetachSoftwareButton";
import { InterfaceMgr } from "../services/instanceContainers/interface";
import { ModuleMgr } from "../services/instanceContainers/module";
import { TreeNodeStatusType } from "../services/treeNodeStatusType";
import { Tooltip } from "./Tooltip";
import { commonStyles } from "./styles/common";
import { ATheme, spacingUnit, ColorIndex } from "./styles/themes";
import { IMyListItem } from "../services/IMyListItem";
import { SelectionInNode } from "./actions/selection";
import { RuntimeInstance } from "public/runtime";
import { Validations } from "../services/objectManagers/validations";
import { Tab } from "../services/tabs";
import { ButtonDisplay } from "../services/treeNodeButtonDisplay";
import { filterKeys } from "../services/utils";

// Status decorator; shows between the tree entry text and the action icon (if available)
export interface ITreeNodeStatus {
	getID(): string;					// get unique ID for identifying the status
	hasError(): boolean;				// entry has error
	hasWarning(): boolean;				// entry has warning
	isSuccess(): boolean;				// entry is successful
	getText(): string;					// get the text to display
	getType(): TreeNodeStatusType;		// get the type of the status
}

// Tree Entry contribution
export interface ITreeNode {
	getID(): string;					// get unique ID for identifying the entry
	getDisplayName(displayScriptName: boolean): string;			// display text
	getChildren(): ITreeNode[];			// list of ITreeEntryContent children
	isTitle(): boolean;					// titles are displayed differently
	getTooltip(): string;				// tooltip when hovering over the entry
	getStatus(validations: Validations): ITreeNodeStatus[];		// status contribution (see ITreeEntryStatus)
	isExpanded(): boolean;				// is expanded
	toggleExpanded(): void;				// toggle expanded
	isDisabled(): boolean;				// disable the entire tree entry
	setShowUserLongDescPref(status: boolean): void;
	showButton(): ButtonDisplay;
	getAlwaysShowUserLongDesc(): boolean;
	getSelection(): SelectionInNode;
	setSelection(selection: SelectionInNode, tabUpdate?: boolean): void;
	getNodePath(): string[];
	getSelectedMyListItem(): IMyListItem;
	getInstances(): IMyListItem[];
	getUsedPins(): Set<string>;
	getRuntimeSelection(): RuntimeInstance;
	getParentNode(): ITreeNode;
	getParentTab(): Tab;
	supportsOutputMenuDocking(): boolean;
	isGraphableNonTopMgr(): boolean;

	// a unique string that is fast to generate and changes if the underlying node changes.
	getUIHash(validations: Validations): string;
}

interface IProps {
	filterText: string;
	selectedTreeNode: ITreeNode;
	treeNode: ITreeNode;
	actions: ConfigStoreActions;
	level: number;
	theme: ATheme;
	validations: Validations;
	displayScriptName: boolean;
	focus: boolean;
}

function matchesFilter(treeNode: ITreeNode, filterText: string) {
	return new RegExp(filterText, "i").test(treeNode.getDisplayName(false));
}

export function shouldBeDisplayed(treeNode: ITreeNode, filterText: string): boolean {
	return (
		treeNode.isTitle() ?
			_.some(treeNode.getChildren(), (c) => shouldBeDisplayed(c, filterText))
			: matchesFilter(treeNode, filterText)
	);
}

const outerTextStyle: React.CSSProperties = {
	whiteSpace: "nowrap",
	overflow: "hidden",
	textOverflow: "ellipsis",
	flex: 1,
	marginRight: 3,
};

const listItemStyle = {
	paddingRight: spacingUnit * 2,
	right: spacingUnit,
};

const statusContainerStyle: React.CSSProperties = {
	verticalAlign: "middle",
	marginRight: 3,
	marginLeft: 3,
};

interface IState {
	nodeUIHash: string; // a unique string that is fast to generate and changes if the underlying node changes
}

const propKeysThatTriggerUpdate = filterKeys<IProps>({
	filterText: true,			// Filter we are using changed
	selectedTreeNode: false,	// We have special handling for this case
	treeNode: true,				// Node we are looking at changed
	actions: false,				// actions is the config store - it can't change without treeNode also changing
	level: false,				// Level must be fixed for each node
	theme: true,				// Theme is dynamic and can change
	validations: false,			// nodeUIHash considers validations
	displayScriptName: true,	// Title will change
	focus: true,				// focus changed
});

export class TreeNode extends React.Component<IProps, IState> {

	constructor(props: IProps) {
		super(props);
		this.state = {
			nodeUIHash: props.treeNode.getUIHash(this.props.validations),
		};
	}

	// shouldComponentUpdate and componentDidUpdate now do not update if a hash code derived from the underlying object
	// didn't change.  This optimization changes the render overhead of the left column from 60-80ms to 10-15ms which
	// means it's no longer the bottleneck of the render cycle

	public override shouldComponentUpdate(nextProps: Readonly<IProps>) {
		return _.some(propKeysThatTriggerUpdate, (key) => nextProps[key] !== this.props[key]) ||
			// Underlying node state changed (based on a quick-to-compare hash code - undefined means update always)
			(!this.state.nodeUIHash || this.state.nodeUIHash !== nextProps.treeNode.getUIHash(nextProps.validations)) ||
			// Selection changed, and it either did, or not does, include this node
			(this.props.selectedTreeNode !== nextProps.selectedTreeNode &&
				(this.props.selectedTreeNode === this.props.treeNode || nextProps.selectedTreeNode === nextProps.treeNode));
	}

	public override componentDidUpdate() {

		// We updated - fetch the ui hash code so we don't always update over and over

		const nodeUIHash = this.props.treeNode.getUIHash(this.props.validations);
		if (nodeUIHash !== this.state.nodeUIHash) {
			this.setState({ nodeUIHash });
		}
	}

	public override render(): JSX.Element {
		const { selectedTreeNode, filterText, actions, displayScriptName, level, focus } = this.props;
		const treeNode = this.props.treeNode;
		const selected = (treeNode === selectedTreeNode);

		const showButton = treeNode.showButton();
		const children = treeNode.getChildren();
		const filteredChildren = _.filter(children, (c) => shouldBeDisplayed(c, filterText));
		const isDisplayed = shouldBeDisplayed(treeNode, filterText);

		if (!isDisplayed) {
			return null;
		}

		return (
			<React.Fragment>
				<ListItem
					id={"interface" + treeNode.getID()}
					button
					onClick={this.handleClicked}
					style={this.getListStyle(level, selectedTreeNode, selected, focus)}
					disabled={treeNode.isDisabled()}
				>
					{this.getLeftDecorator()}
					<Typography variant="subtitle2" style={outerTextStyle}>
						<Tooltip title={treeNode.getTooltip()} placement="top">
							<span
								id={selected ? "selectedInterface" : treeNode.getID() + "NotSelected"}
								style={this.getInnerTextStyle(treeNode.isTitle())}
							>
								{this.getFormattedNodeText(
									treeNode.getDisplayName(displayScriptName), filterText, _.size(filteredChildren))}
							</span>
						</Tooltip>
					</Typography>

					{
						_.map(treeNode.getStatus(this.props.validations),
							(curStatus) => this.renderStatus(curStatus, showButton === ButtonDisplay.Remove))
					}

					{showButton === ButtonDisplay.Show &&
						<ListItemSecondaryAction style={listItemStyle}>
							{(treeNode instanceof ModuleMgr || treeNode instanceof InterfaceMgr)
								&& <AddAdaptedTreeNodeButton treeNode={treeNode} actions={actions} />
							}
							{treeNode instanceof HardwareComponentMgr &&
								<AttachDetachSoftwareButton
									treeNode={treeNode}
									actions={actions}
									displayScriptName={displayScriptName}
								/>
							}
						</ListItemSecondaryAction>
					}
					{showButton === ButtonDisplay.Hide &&
						// An empty ListItemSecondaryAction with the same style ensures the spacing if the status icons
						// when there is no +/- icon
						<ListItemSecondaryAction style={listItemStyle} />
					}
				</ListItem>
				{
					treeNode.isExpanded() && !_.isEmpty(this.props.treeNode.getChildren()) &&
					<List disablePadding id={treeNode.getID()} >
						{
							_.map(filteredChildren, (child) => {
								return (
									<TreeNode
										theme={this.props.theme}
										key={child.getID()}
										level={level + 1}
										treeNode={child}
										filterText={filterText}
										actions={actions}
										selectedTreeNode={selectedTreeNode}
										validations={this.props.validations}
										displayScriptName={displayScriptName}
										focus={focus}
									/>
								);
							})
						}
					</List>
				}
			</React.Fragment>
		);
	}

	// handle when entry is clicked
	private handleClicked = () => {
		this.props.actions.setSelectedNode(this.props.treeNode);
	}

	// controls how the overall entry looks
	private getListStyle(
		level: number,
		selectedTreeNode: ITreeNode,
		selected: boolean,
		focus: boolean) {

		// calculates the necessary padding
		let style: React.CSSProperties = {
			paddingLeft: this.props.theme.theme.spacing(3) * level,
			paddingTop: this.props.theme.theme.spacing(0.5) - 1,
			paddingBottom: this.props.theme.theme.spacing(0.5) - 1,
			height: this.props.theme.theme.spacing(2) + this.props.theme.theme.typography.fontSize + 2,
		};

		// selected style
		if (selected) {
			style = {
				...style,
				backgroundColor: focus ?
					this.props.theme.colors[ColorIndex.SELECTEDLISTBG] :
					this.props.theme.colors[ColorIndex.SELECTEDLISTBGDEFOCUS],
				color: this.props.theme.colors[ColorIndex.SELECTEDLISTFG],
			};
		} else {
			const currentTreeNode = this.props.treeNode;

			// Make sure the current entry and selected entry is pointer to same hardware component.
			// Tree entries can represent subcomponents that have the same ID, but is wired to different pins.
			// Casting HardwareComponent and comparing the underlying object allows us to make the entries are the same.

			if ((selectedTreeNode.getID() === currentTreeNode.getID()) &&
				selectedTreeNode instanceof HardwareComponentMgr &&
				currentTreeNode instanceof HardwareComponentMgr &&
				selectedTreeNode.getHwComponent() === currentTreeNode.getHwComponent()) {
				style = {
					...style,
				};
			}
		}

		return style;
	}

	// controls the left decorator
	private getLeftDecorator() {
		// show drop down arrow if children exists
		return <ListItemIcon color="primary"
			style={this.getArrowStyle()}><ChevronDown color="primary" style={commonStyles.smallIcon} /></ListItemIcon>;
	}

	// rotates the drop down arrow depending on if children are showing
	// hide the arrow if no children
	private getArrowStyle(): React.CSSProperties {
		if (_.isEmpty(this.props.treeNode.getChildren())) {
			return { opacity: 0, marginRight: 3 };
		}
		const commonStyle = { transition: "0.2s all ease", marginRight: 3 };
		return !this.props.treeNode.isExpanded() ?
			{ ...commonStyle, transform: "rotate(-90deg)" } : { ...commonStyle, transform: "rotate(0)" };
	}

	// controls inner text styling; titles are displayed differently for contrast
	private getInnerTextStyle(isTitle: boolean): React.CSSProperties {
		if (isTitle) {
			return {
				...commonStyles.innerTextStyle,
				color: this.props.theme.colors[ColorIndex.CUSTOMTEXTCOLOR],
				fontWeight: 600,
			};
		} else {
			return { fontWeight: 400 };
		}
	}

	// highlight the text based on the filter string
	private getFormattedNodeText(text: string, highlight: string, numDisplayedChildren: number) {

		if (this.props.treeNode.isTitle()) {
			return `${text} (${numDisplayedChildren})`;
		}

		// Split on highlight term and include term into parts, ignore case
		const parts = text.split(new RegExp(`(${highlight})`, "gi"));
		return <span> {parts.map((part, i) =>
			<span key={i} style={part.toLowerCase() === highlight.toLowerCase() ?
				{ backgroundColor: this.props.theme.colors[ColorIndex.SEARCHHIGHLIGHTCOLOR] } : {}}>
				{part}
			</span>)
		} </span>;
	}

	private renderStatus(status: ITreeNodeStatus, asListItem: boolean) {
		if (asListItem) {
			return <ListItemSecondaryAction style={listItemStyle} key={status.getID()}>
				{this.displayStatus(status)}
			</ListItemSecondaryAction>;
		}

		return this.displayStatus(status);
	}

	// draws the correct status decorator
	private displayStatus(status: ITreeNodeStatus) {
		if (status.getType() === TreeNodeStatusType.BADGE) {
			return <NodeStatusDecorator
				key={status.getID()}
				id={status.getID()}
				status={status}
				containerStyle={statusContainerStyle}
			/>;
		} else if (status.getType() === TreeNodeStatusType.TEXT) {
			return <TextDecorator
				key={status.getID()}
				id={status.getID()}
				text={status.getText()}
				containerStyle={statusContainerStyle}
			/>;
		}
		return (null);
	}
}

interface INodeStatusDecoratorProps extends Omit<IStatusDecoratorProps, "status"> {
	status: ITreeNodeStatus;
}

function NodeStatusDecorator(props: INodeStatusDecoratorProps) {
	const { status, ...rest } = props;
	const adapted = status.hasError() ? StatusType.Error :
		status.hasWarning() ? StatusType.Warning :
			status.isSuccess() ? StatusType.Success : StatusType.None;

	return <StatusDecorator status={adapted} {...rest} />;
}
