/* eslint-disable max-len */
import * as React from "react";
import * as _ from "lodash";
import {
	ButtonGroup,
	Card,
	CardContent,
	Popover,
	Table,
	TableRow,
	TableCell,
	TableBody,
	TableHead,
	Tooltip,
	Typography,
	withStyles,
} from "../../../../imports/material-ui-imports";
import { Help, SquareRounded } from "../../../../imports/mdi-material-ui-imports";
import { ClassesType, graphStyles } from "../../styling/graphStyles";
import { ButtonGroupIconButton } from "./ButtonGroupIconButton";
import { commonStyles } from "../../../styles/common";
import { generateToolTipProps } from "../../../Tooltip"; // ButtonGroup prevents direct use of our template wrapper

interface IState {
	anchorEl: HTMLButtonElement | null;
}

interface IProps {
	movableNodes: boolean;
}

export class FloatingHelp extends React.Component<IProps, IState> {

	public override state: IState = {
		anchorEl: null,
	}

	public override render() {
		const open = Boolean(this.state.anchorEl);
		return <>
			<ButtonGroup variant="contained">
				<ButtonGroupIconButton onClick={this.handleClick} >
					<Tooltip {...generateToolTipProps({ title: "Help" })}>
						<Help fontSize="small" color="primary" />
					</Tooltip>
				</ButtonGroupIconButton>
			</ButtonGroup>
			<Popover
				open={open}
				anchorEl={this.state.anchorEl}
				onClose={this.handleClose}
				elevation={2}
				anchorOrigin={anchorOrigin}
				transformOrigin={transformOrigin}
			>
				<HelpBox {...this.props} />
			</Popover>
		</>;
	}

	private handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
		this.setState({ anchorEl: event.currentTarget });
	}

	private handleClose = () => {
		this.setState({ anchorEl: null });
	}
}

const anchorOrigin = {
	vertical: "top",
	horizontal: "left",
} as const;

const transformOrigin = {
	vertical: "top",
	horizontal: "right",
} as const;

function HelpBox({ movableNodes }: IProps) {
	return <Card style={{ maxWidth: 345 }}>
		<CardContent>
			<div style={{ padding: "4px 8px 12px 8px" }}>
				<Typography gutterBottom variant="h6" component="div">
					Tips
				</Typography>
				{movableNodes &&
					<Typography variant="body2" color="textSecondary">
						Use mouse wheel or buttons to zoom.
						Click and drag in an empty area to pan, or on a node to move it.
						Click on a port and drag to connect it to another port.
						Click on a node to see its settings.
						Nodes and connections can be selected and deleted with the delete key.
					</Typography>
				}
				{!movableNodes &&
					<Typography variant="body2" color="textSecondary">
						Use mouse wheel or buttons to zoom.
						Click and drag to pan.
						Click components to see their settings and click/hover on connections to trace them.
					</Typography>
				}
			</div>
			<Table>
				<TableHead>
					<TableRow style={commonStyles.tableRowStyle}>
						<TableCell>
							Color
						</TableCell>
						<TableCell>
							Meaning
						</TableCell>
					</TableRow>
				</TableHead>
				<TableBody>
					<LegendEntry colour="normal" text="Default component" />
					<LegendEntry colour="error" text="Component has an error" />
					<LegendEntry colour="warning" text="Component has a warning" />
					{!movableNodes &&
						<>
							<LegendEntry colour="unused" text="Component output is unused" />
							<LegendEntry colour="disabled" text="Component output is off" />
						</>
					}
				</TableBody>
			</Table>
		</CardContent>

	</Card>;
}

interface ILegendEntryProps {
	colour: "normal" | "error" | "warning" | "unused" | "disabled";
	text: string;
}

const LegendEntry = withStyles(graphStyles)(({ colour, text, classes }: ILegendEntryProps & ClassesType) => {
	const key = "normal" === colour ? "svgNode" : `${colour}_svgNode` as keyof ClassesType["classes"];
	return <TableRow style={commonStyles.tableRowStyle}>
		<TableCell>
			<SquareRounded fontSize="small" className={classes[key]} />
		</TableCell>
		<TableCell>
			{text}
		</TableCell>
	</TableRow>;
});
