import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../graph/types/layoutTypes";
import { ClockTreeNode } from "../../services/instanceContainers/clockTreeNode";
import { ClockIpInstanceMgr } from "../../services/objectManagers/clockIpInstanceMgr";
import { memoizeResult } from "../../services/utils";
import { GraphView, INonGraphProps } from "../graph/GraphView";
import { isDynamic, NodeComponent } from "./nodes/NodeFactory";
import { AsyncComponent } from "../AsyncComponent";
import { PinFrequencyConfigurableMgr } from "../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";
import { AnyMemberMgr } from "../../services/objectManagers/member";
import { INodeProps } from "../graph/types/nodeTypes";
import { ExtendedElkNode } from "./layout/customTypes";
import { toGenericLayout } from "./layout/toGenericLayout";
import { UserGraphAction } from "../graph/types/IGraphProps";

interface IProps extends INonGraphProps {
	treeNode: ClockTreeNode;
}

interface IState {
	layout: ExtendedElkNode | null;
	highlightedEdge: Layout.Edge<PinFrequencyConfigurableMgr>;
	selectedEdge: Layout.Edge<PinFrequencyConfigurableMgr>;
	frequencyLabels: string[];
}

export class ClockTreeView extends AsyncComponent<IProps, IState> {
	public override state: IState = {
		layout: null,
		highlightedEdge: null,
		selectedEdge: null,
		frequencyLabels: [],
	};

	public override render() {
		const instances = this.props.treeNode.getInstances();
		return <GraphView
			{...this.props}
			layout={this.getLayout()}
			nodeFactory={this.nodeFactory}
			canMemoize={this.canMemoize}
			usedInstances={getUsedInstances(instances)}
			disabledInstances={getDisabledInstances(instances)}
			onClickNode={this.onClickNode}
			onMouseDownNode={null}
			onMouseDownPort={null}
			onMouseMove={null}
			onMouseUp={null}
			onClickPort={null}
			onMouseEnterEdge={this.onMouseEnterEdge}
			onMouseLeaveEdge={this.onMouseLeaveEdge}
			onClickEdge={this.onClickEdge}
			getEdgeToolTip={this.getEdgeToolTip}
			onAutoArrange={null}
			onClickAway={null}
			highlightedEdges={this.getSignalPath(this.state.highlightedEdge)}
			selectedEdges={this.getSignalPath(this.state.selectedEdge)}
			userAction={UserGraphAction.NONE}
			setCursorMode={null}
			cursorMode={null}
		/>;
	}

	protected propsChanged(nextProps: Readonly<IProps>) {
		// If the tree node changes, then the left pane selection changed and we need to refetch the layout.

		return this.props.treeNode !== nextProps.treeNode;
	}

	protected clearAsyncData() {
		this.setState({
			layout: null,
			highlightedEdge: null,
			selectedEdge: null,
		});
	}

	protected async fetchAsyncData() {
		const { treeNode } = this.props;
		const layout = await treeNode.getLayout();
		const { frequencyLabels } = treeNode.getGraphSettings();
		return { layout, frequencyLabels };
	}

	private getLayout() {
		return this.state.layout
			? toGenericLayout(this.state.layout, (name) => this.props.treeNode.getIpInstanceMgr(name))
			: null;
	}

	private nodeFactory = (props: INodeProps<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>) => {
		return <NodeComponent {...props} frequencyLabels={this.state.frequencyLabels} />;
	}

	private canMemoize = (node: Layout.Node<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>) =>
		isDynamic(node, this.state.frequencyLabels);

	private onClickNode = (selection: ClockIpInstanceMgr) =>
		this.props.actions.setSelectedMyListItem(this.props.treeNode, selection);

	private onMouseEnterEdge = (highlightedEdge: Layout.Edge<PinFrequencyConfigurableMgr>) => this.setState({ highlightedEdge });

	private onMouseLeaveEdge = () => {
		if (this.state.highlightedEdge) { // prevents a call to setState if this event happened while dragging
			this.setState({ highlightedEdge: null });
		}
	}

	private onClickEdge = (selectedEdge: Layout.Edge<PinFrequencyConfigurableMgr>) =>
		this.setState({ selectedEdge, highlightedEdge: null });

	private getEdgeToolTip = (edge: Layout.Edge<PinFrequencyConfigurableMgr>) => edge.source.getValueAsString();

	private getSignalPath(edge: Layout.Edge<PinFrequencyConfigurableMgr>) {

		if (!edge) {
			return [];
		}

		// Find the signal path this edge refers to by reading it from the source and including all targets

		const pinMgr = edge.source;
		const signalPath = [
			...pinMgr.getSignalPath(),
			...edge.targets,
		];

		// Now lookup all edges in the layout that have one target that is within the signal path.

		return getMatchingEdges(this.getLayout(), signalPath);
	}
}

const getUsedInstances = memoizeResult((ipInstances: ClockIpInstanceMgr[]) =>
	_.map(ClockIpInstanceMgr.getUsed(ipInstances), (i) => i.getID()));

const getDisabledInstances = memoizeResult((ipInstances: ClockIpInstanceMgr[]) => {
	return _.chain(ipInstances)
		.filter((i) => i.isDisabled())
		.map((i) => i.getID())
		.value();
});

function getMatchingEdges(
	group: Layout.Group<ClockIpInstanceMgr, PinFrequencyConfigurableMgr>, memberMgrs: AnyMemberMgr[]
): Layout.Edge<PinFrequencyConfigurableMgr>[] {

	// We do not look at sources as a source can branch to targets that aren't in the signal path.

	const edgesThisLevel = _.filter(group.edges, (e) => _.some(e.targets, (t) => _.includes(memberMgrs, t)));
	const childEdges = _.flatMap(group.groups, (g) => getMatchingEdges(g, memberMgrs));
	return [...edgesThisLevel, ...childEdges];
}

