import * as _ from "lodash";
import React = require("react");
import { Typography, Link } from "../imports/material-ui-imports";

import { FormattedMsg as Message, isFormattedLink } from "../services/formatting/link";
import { ILinkActions } from "./actions/ILinkActions";

// render the message in UI distinguishing links from plain text

interface FormattedMsgProps {
	actions: ILinkActions;
	message: Message;
	onClick?: () => void;
}

const textStyle = { whiteSpace: "pre-line" } as const;

export class FormattedMsg extends React.Component<FormattedMsgProps> {
	public override render() {
		return _.map(this.props.message.toParts(), (msg, key) => {
			if (isFormattedLink(msg)) {
				return (
					<Link
						display="inline"
						key={key}
						component="button"
						underline="always"
						variant="caption"
						color="inherit"
						onClick={(e: React.MouseEvent<HTMLElement>) => {
							e.stopPropagation();
							msg.linkAction(this.props.actions);
							if (this.props.onClick) {
								this.props.onClick();
							}
						}}
					>
						{msg.baseText}
					</Link>
				);
			} else {
				return (
					<Typography
						style={textStyle}
						key={key}
						variant="caption"
						color="inherit"
						display="inline"
					>
						{msg}
					</Typography>
				);

			}
		});
	}
}
