import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { PositionedNode } from "./PositionedNode";
import { Select, MenuItem } from "../../../imports/material-ui-imports";
import { AMemberMgr, AnyMemberMgr } from "../../../services/objectManagers/member";
import { MainLabel } from "./NodeLabels";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { INodeProps } from "../types/nodeTypes";

// A small rectangular node with a simple drop down control in the middle.  This drop down becomes a label if it only
// has one possible value.  
// This was created to handle multiplier/divider modes, but is generic to work with any sort of drop down

// Note this is not as powerful as the drop down configurable is. That's because handling tooltips, dynamic options, 
// read-only options etc would make this much longer to render, and we don't (so far) have a need for it.  By having it
// require a fixed set of values that can be a static array, we can render a simple select menu (vs autocomplete 
// component) and also have it not re-render if the current value doesn't change.

export interface ISimpleDropDownNodeProps<
	InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr, EnumType extends number | string>
	extends INodeProps<InstMgr, PortMgr> {
	formatPrefix: "/ " | "X " | "",
	values: EnumType[],
	currentValue: EnumType,
	mgr: AMemberMgr<EnumType>;
}

// We want to restrict the height of the opened drop down as we do have one case with a multiplier allowing any value 
// from X 2 to X 128
// And we declare this constant at the top so <Select> will always see the same style object each time

const selectMenuProps = {
	PaperProps: {
		style: {
			maxHeight: 250,
		},
	},
};

export class SimpleDropDownNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr, EnumType extends number | string>
	extends React.PureComponent<ISimpleDropDownNodeProps<InstMgr, PortMgr, EnumType> & ClassesType>
{
	public override render() {
		const {
			node,
			onClickNode,
			onMouseDownNode,
			classes,
			formatPrefix,
			values,
			mgr,
			displayScriptName,
			validations,
			formatter,
		} = this.props;
		const isFixed = _.size(values) === 1;

		return (
			<PositionedNode
				node={node}
				onClick={onClickNode}
				onMouseDown={onMouseDownNode}
				className={classes.genericNode}
				validations={validations}
				formatter={formatter}
			>
				{/* 
					Ideally we'd render <NodeLabels> as well, but there's two issues:
					1) out label overlaps the select, making it un-clickable
					2) with two pins, the labels likely add nothing
					I'm sure there's a solution to 1 should 2 ever change, but for now I'm just omitting pin labels
					amd rendering just the main label manually
				*/}

				<MainLabel
					node={node}
					displayScriptName={displayScriptName}
					classes={classes}
				/>

				<div className={classes.dropDown}>
					{isFixed &&
						// If the division value is fixed, just render the text
						`${formatPrefix}${_.first(values)}`
					}

					{!isFixed &&
						// We use a <Select> vs our custom <DropDown> as auto-complete is kinda-overkill for this use case
						// <Select> renders faster, and doesn't attempt to stretch
						<Select
							value={mgr.getValue()}
							onChange={this.onChange}
							MenuProps={selectMenuProps}
						>
							{_.map(values, (value) => <MenuItem key={value} value={value}>{`${formatPrefix}${value}`}</MenuItem>)}
						</Select>
					}
				</div>
			</PositionedNode>
		);
	}

	private onChange = (event: React.ChangeEvent<{ value: unknown }>) => {
		// Change the selection and then set the configurable.  The selection change ensures that the history remains 
		// correct

		const { actions, mgr, onClickNode, node } = this.props;
		onClickNode(node.inst);
		actions.setConfigurableValue(mgr, event.target.value);
	}
}
