import * as _ from "lodash";
import React = require("react");
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { assertUnreachable, convertUnknownToError } from "../../services/utils";
import { MarkdownContent } from "../MarkdownContent";
import { ResourceType } from "../../services/resources/metaContentLoaders/resourceLoader";
import { OutputViewError } from "./OuputViewError";
import { MetaViewMgr } from "../../services/ui/outputView";
import { ITreeNode } from "../TreeNode";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { ConfigStoreActions } from "../../services/configStore";
import { viewError } from "../../services/codeGeneration/codeGenerator";

interface ICardForGeneratedProps {
	mgr: MetaViewMgr;
	selectedTreeNode: ITreeNode;
	actions: ConfigStoreActions;
	formatter: IFormatter;
}

export function CardForGenerated(props: ICardForGeneratedProps & IGlobalServiceProps) {
	let content = "";
	let exception: Error;
	try {
		content = props.mgr.generateView(props.selectedTreeNode);
	} catch (e) {
		exception = convertUnknownToError(e);
	}

	if (exception || content === viewError) {
		return <OutputViewError
			{...props}
			exception={exception}
			failureReason={viewError} />;
	}
	else {
		const viewFile = props.mgr.getViewFile();
		const viewType = viewFile.viewType;
		switch (viewType) {
			case "markdown":
				return <MarkdownContent
					markdownSrc={content}
					canonicalName={viewFile.path}
					resourceType={ResourceType.TEMPLATE}
					formatter={props.formatter}
					resourceLoader={props.mgr.getResourceLoader()}
					actions={props.actions}
					style={style}
				/>;
			default:
				assertUnreachable(viewType);
		}
	}
}

const style = { padding: "0 10px 0 10px" };
