import * as _ from "lodash";
import { isCloud } from "./platform";
import { getToolVersion } from "./toolVersion";
import type { ResolvedArgs } from "./args/argTypes";
import type { SpiceLaunchParams } from "public/defs";

// On the desktop, analytics calls are a no-op

class DesktopAnalytics {
	public recordLoadConfig() { }
	public recordSimulation() {
		return () => { };
	}
	public recordExternalNavigate() { }
	public recordSerialPort() {
		return () => { };
	}
	public recordFileDownload() { }
	public recordSaveAs() { }
}

// In the cloud, we record how the config page was created in order to make that association for all calls

class CloudAnalytics {

	private readonly data: {
		script: string[],
		products: string[],
		board: string;
		device: {
			device: string;
			part: string;
			package: string;
		};
	}

	constructor(args: ResolvedArgs) {
		this.data = {
			script: _.chain(args.script).map((s) => s.script?.path).compact().value(),
			products: _.map(args.products, (p) => `${p.file.name}@${p.file.version}`),
			board: args.boardId,
			device: {
				device: args.deviceId,
				part: args.partId,
				package: args.packageId,
			},
		};
	}

	public recordLoadConfig(defaultModuleName: string) {
		record("configuration", { ...this.data, defaultModuleName: valOrUndefined(defaultModuleName) });
	}

	public recordSimulation(simulationParams: SpiceLaunchParams) {
		const data = { ...this.data, simulationParams };
		record("startSimulation", data);
		return this.recordDuration("endSimulation", data);
	}

	public recordExternalNavigate(url: string) {
		record("navigate", { ...this.data, url });
	}

	public recordSerialPort() {
		record("startSerialPort", this.data);
		return this.recordDuration("endSerialPort", this.data);
	}

	public recordFileDownload(fileName: string) {
		record("fileDownload", { ...this.data, fileName });
	}

	public recordSaveAs(fileName: string) {
		record("saveAs", { ...this.data, fileName });
	}

	// Allows the issuing of a second analytics call so the overall duration, and potential failure reason, can be provided

	private recordDuration<T extends {}>(action: string, data: T) {
		const start = Date.now();
		return (failureReason: string = null) => {
			const duration = Date.now() - start;
			record(action, { data, duration, failureReason: valOrUndefined(failureReason) });
		};
	}
}

// Analytics needs a bunch of data about the system (device, products...), however, I don't want to force clients of it 
// to have to know all of this information, nor do I want to store the class in some central location and pass it 
// around every time.  
// As such, we have one call to register it, and subsequent calls simply use it.  This does mean that if it's used 
// early, it will crash, but that seems like something we'd catch fairly quickly in testing...

let analytics: CloudAnalytics | DesktopAnalytics;
export function registerAnalytics(args: ResolvedArgs) {
	analytics = isCloud() ? new CloudAnalytics(args) : new DesktopAnalytics();
}

export function getAnalytics() {
	return analytics;
}

// map null (falsy) values to undefined, so it doesn't get logged saving DB space
function valOrUndefined<T>(val: T) {

	if (_.isArray(val)) {
		return _.isEmpty(val) ? undefined : val;
	}

	return val ? val : undefined;
}

function record<T extends {}>(action: string, data: T) {
	const toolVersion = getToolVersion();
	data = {
		app: "sysconfig",
		version: toolVersion,
		...data,
	};

	// Analytics should have already been pre-loaded in a script tag in the server-generated index.html.  However, 
	// don't crash if it's not for some reason

	try {
		(window as any).ti?.analytics?.logEvent("sysconfig", action, data);
	} catch (e) { } // swallow
}
