import { createFinalSvgPathNode } from "../createSvgPathNode";
import { notCirclePath, notCircleDiameter } from "./NotNode";
import { getOrPortOffset, orPath } from "./OrNode";

// Node for a NOR gate

function norPath(width: number, height: number) {
	return orPath(width - notCircleDiameter, height) + notCirclePath(width, height);
}

// There will only ever be one output, so hight-based adjustments at the output aren't needed.

export const NorNode = createFinalSvgPathNode(norPath, {
	extraWidth: notCircleDiameter,
	inputPortXOffset: getOrPortOffset,
	inputLabelXOffset: getOrPortOffset,
	outputLabelXOffset: () => -notCircleDiameter,
});
