import { Shape } from "konva/lib/Shape";
import { pinColors, tiStatusColor } from "../../components/styles/colors";
import { assertUnreachable } from "../utils";

export const PIN_UNASSIGNED = "Pin Available" as const;
export const PIN_ASSIGNED = "Pin Assigned" as const;
export const PIN_NOT_AVAILABLE = "Pin Not Available" as const;
export const PIN_WARNING = "Warning" as const;
export const PIN_RESERVED = "Pin Reserved" as const;
export const PIN_POWER = "Power" as const;
export const PIN_GROUND = "Ground" as const;
export const PIN_FIXED = "Fixed (N/A)" as const;

export const DEVICE_PIN_TO_PIN_TYPE: { [key: string]: PinType } = {
	Default: PIN_UNASSIGNED,
	Power: PIN_POWER,
	Ground: PIN_GROUND,
	Fixed: PIN_FIXED,
	Reserved: PIN_RESERVED,
};

// make this constant because with custom layouts BUs will be specifying coordinates
export const PIN_SIZE = 12;
export const EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT = PIN_SIZE * 3;

export interface UIPin {
	shape: PinShape;
	pinName?: string;
	pinType: PinType;
	currentlySelected?: boolean;
}

export type PinShape = Shape & { pin?: UIPin };

export type PinType = typeof PIN_UNASSIGNED |
	typeof PIN_ASSIGNED |
	typeof PIN_NOT_AVAILABLE |
	typeof PIN_WARNING |
	typeof PIN_RESERVED |
	typeof PIN_POWER |
	typeof PIN_GROUND |
	typeof PIN_FIXED;

export function getPinColor(pinType: PinType, showExtendedPinTypes: boolean) {
	switch (pinType) {
		case PIN_UNASSIGNED:
			return pinColors.available;
		case PIN_ASSIGNED:
			return pinColors.used;
		case PIN_WARNING:
			return tiStatusColor.warning;
		case PIN_POWER:
			return pinColors.power;
		case PIN_GROUND:
			return pinColors.ground;
		case PIN_RESERVED:
		// A legacy bug always showed reserved pins the same as fixed pins, so keep it the same for now
		// return pinColors.reserved;
		case PIN_FIXED:
			return pinColors.fixed;
		case PIN_NOT_AVAILABLE:
			// when showing extended pin types, set to undefined so they are not visible
			return showExtendedPinTypes ? undefined : pinColors.fixed;
		default:
			assertUnreachable(pinType);
	}
}

export function getPinTypes(includeExtendedPinTypes?: boolean): PinType[] {
	let pinTypes: PinType[] = [];
	pinTypes = pinTypes.concat([PIN_UNASSIGNED, PIN_ASSIGNED, PIN_WARNING]);

	if (includeExtendedPinTypes) {
		pinTypes = pinTypes.concat([PIN_POWER, PIN_GROUND]);
	}

	pinTypes = pinTypes.concat([PIN_FIXED]);

	return pinTypes;
}

export function transformCustomPosition<T extends { x: number, y: number }>(obj: T): T {
	if (obj) {
		return { ...obj, x: obj.x + borderOffset, y: obj.y + borderOffset };
	} else {
		// in the case where the BU hasn't specified a dimple position just return null and handle this later in customPackage
		return null;
	}
}

export const borderOffset = PIN_SIZE + 1;
