import { IProcess, IStandardReadablePipe } from "./IProcess";

class ProcessEvent<T> {

	private listener: (data: T) => void;

	public fire(data: T) {
		if (this.listener) {
			this.listener(data);
		} else {
			console.error("nothing listened to this event");
		}
	}

	public addListener(listener: (data: T) => void) {
		this.listener = listener;
	}
}

class ReadablePipe implements IStandardReadablePipe {
	public onData = new ProcessEvent<any>();
	public on(event: "error", listener: (err: Error) => void): void;
	public on(event: "data", listener: (chunk: any) => void): void;
	public on(event: "data" | "error", listener: (chunk: any) => void) {
		if (event === "data") {
			this.onData.addListener(listener);
		}
		else {
			// eclipse doesn't support these events
		}
	}
}

export function launchEclipseTerminalProcess(command: string): IProcess {
	// Events on process object
	const onExit = new ProcessEvent<void>();

	// stdout/err
	const stdout = new ReadablePipe();
	const stderr = new ReadablePipe();

	(window as any).eclipseTerminalComplete = (response: IEclipseSpawnResponse) => {
		onExit.fire();
		(window as any).eclipseSpawnCallback(response);
	};

	(window as any).eclipseTerminalWrite = (data: string) => {
		stdout.onData.fire(data);
	};

	(window as any).eclipseTerminalError = (data: string) => {
		stderr.onData.fire(data);
	};

	const pid = window.eclipseSpawn2(command, "eclipseTerminalComplete", "eclipseTerminalWrite", "eclipseTerminalError");
	return {
		on: (event: string, listener: (args: any) => void) => {
			if (event === "exit") {
				onExit.addListener(listener);
			}
		},
		stdout,
		stderr,
		stdin: {
			write: (text: string) => {
				window.eclipseWriteToStdin(pid, text);
				return true;
			},
		},
	};
}
