import { System } from "public/runtime";
import { getOldIpInstance } from "../../migration/migrateUtils";
import { getCurrentlyRunningCallbackName, isModuleAccessEnabled } from "../../moduleAccessGuard";
import { isScriptingEnabled } from "../../scripting/scriptingGuard";
import { invalidModuleAccessed, shouldCapture } from "../invalidAssignment";
import { SetSource } from "../member";
import { createInvalidAssignmentProxy } from "./invalidAssignmentProxy";
import { shallowReadOnlyProxyHandler } from "./shallowReadOnlyProxyHandler";

function createModuleAccessProxyHandler(name: keyof System): ProxyHandler<any> {
	return {
		...shallowReadOnlyProxyHandler,
		get: (target, key: Extract<PropertyKey, string>) => {
			if (isModuleAccessEnabled()) {
				return target[key];
			} else {
				throw new Error(
					`Cannot access system.${name}.` +
					` ${getCurrentlyRunningCallbackName()} should only depend on the configuration of the current instance.`,
				);
			}
		},
	};
}

function createClockTreeAccessProxyHandler(): ProxyHandler<any> {
	const defaultHandler = createModuleAccessProxyHandler("clockTree");
	return {
		...defaultHandler,
		get: (target, key: Extract<PropertyKey, string>, receiver: any) => {
			if (!target.hasOwnProperty(key) && isScriptingEnabled() && shouldCapture(SetSource.USER_ASSIGN, false, false)) {

				// Notify that there was an attempt to access this module

				const inst = getOldIpInstance(key);
				invalidModuleAccessed(inst.getGraphLabel(false) || inst.getGraphLabel(true));

				// Return a proxy so the script doesn't fail, but ignore the final set as we don't really care
				// beyond which module this was
				return createInvalidAssignmentProxy([key], { invalidAccess: () => { } }); // Ignore final callback
			} else {
				return defaultHandler.get(target, key, receiver);
			}
		},
	};
}

export const moduleAccessProxyHander = createModuleAccessProxyHandler("modules");
export const clockModuleAccessProxyHander = createClockTreeAccessProxyHandler();
