// base badge
import React = require("react");
import { Typography, Link } from "../imports/material-ui-imports";
import { commonStyles } from "./styles/common";
import { Alert, CloseCircle, Information } from "../imports/mdi-material-ui-imports";
import * as _ from "lodash";
import { Tooltip } from "./Tooltip";

interface IBadgeProps {
	message: string | JSX.Element;
	id?: string;
	children?: React.ReactNode;
}

const badgeSpanStyle = { display: "inline-flex", verticalAlign: "bottom" };
const messageStyle = { display: "inline-block", marginLeft: 3 };

class Badge extends React.PureComponent<IBadgeProps, {}> {
	public override render() {
		return (
			<span style={badgeSpanStyle}>
				{this.props.children}
				{
					_.isString(this.props.message) ?
						<Typography variant="body2" id={this.props.id} style={messageStyle}>
							{this.props.message}
						</Typography> :
						<span id={this.props.id}>
							{this.props.message}
						</span>
				}
			</span>
		);
	}
}

interface IExtendedBadgeProps extends IBadgeProps {
	withoutIcon?: boolean;
}

export class ErrorBadge extends React.PureComponent<IExtendedBadgeProps> {
	public override render() {
		return (
			<Badge {...this.props}>
				{!this.props.withoutIcon &&
					<CloseCircle
						className="svgIcon errorIcon"
						id={"error_" + this.props.message + "_tooltip"}
						style={commonStyles.errorIcon}
					/>
				}
			</Badge>
		);
	}
}

export class InfoBadge extends React.PureComponent<IExtendedBadgeProps> {
	public override render() {
		return (
			<Badge {...this.props}>
				{!this.props.withoutIcon &&
					<Information
						className="svgIcon infoIcon"
						id={"info_" + this.props.message + "_tooltip"}
						style={commonStyles.infoIcon}
					/>
				}
			</Badge >
		);
	}
}

interface IWarningBadgeProps extends IExtendedBadgeProps {
	onClick: () => void;
	tooltip: string;
	suppressed: boolean;
}

export class WarningBadgeWithSuppress extends React.PureComponent<IWarningBadgeProps> {
	public override render() {
		return (
			<Badge
				{...this.props}
				message={
					<React.Fragment>
						{this.props.message}
						<Link
							component="button"
							display="inline"
							underline="always"
							variant="caption"
							color="inherit"
							onClick={this.onClick}
						>
							{this.props.suppressed ? "(Un-suppress)" : "(Suppress)"}
						</Link>
					</React.Fragment>
				}
			>
				{!this.props.withoutIcon &&
					<Tooltip
						title={this.props.tooltip}
						disabled={!this.props.tooltip}
					>
						<Alert
							onClick={this.props.onClick}
							className="svgIcon warningIcon"
							id="warning"
							style={this.props.suppressed ? commonStyles.neutralIcon : commonStyles.warningIcon}
						/>
					</Tooltip>
				}
			</Badge >
		);
	}

	private onClick = (e: React.MouseEvent<HTMLElement>) => {
		e.stopPropagation();
		this.props.onClick();
	}
}

// This component does not support suppression unlike the above
export class SimpleWarningBadge extends React.PureComponent<IExtendedBadgeProps> {
	public override render() {
		return (
			<Badge {...this.props}>
				{!this.props.withoutIcon &&
					<Alert
						className="svgIcon warningIcon"
						id={"warning_" + this.props.message + "_tooltip"}
						style={commonStyles.warningIcon}
					/>
				}
			</Badge>
		);
	}
}
