import * as React from "react";
import * as _ from "lodash";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { INodeProps, NodeFactory } from "../types/nodeTypes";
import { applyNodeStyles } from "./StyleNode";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

export interface IUnStyledNodeProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr> extends INodeProps<InstMgr, PortMgr> {
	nodeFactory: NodeFactory<InstMgr, PortMgr>;
	searchText: string;
	disabledInstances: string[];
	usedInstances: string[];
	selected?: boolean;
	grabbing?: boolean;
}

export function Node<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(props: IUnStyledNodeProps<InstMgr, PortMgr>) {
	const {
		node,
		onClickNode,
		onMouseDownNode,
		onMouseDownPort,
		onMouseUpPort,
		onClickPort,
		actions,
		displayScriptName,
		nodeFactory: NodeComponent,
		validations,
		cursorMode,
		formatter,
	} = props;
	return <NodeComponent
		node={node}
		onClickNode={onClickNode}
		onMouseDownNode={onMouseDownNode}
		onMouseDownPort={onMouseDownPort}
		onMouseUpPort={onMouseUpPort}
		onClickPort={onClickPort}
		actions={actions}
		displayScriptName={displayScriptName}
		classes={applyNodeStyles(props)}
		validations={validations}
		cursorMode={cursorMode}
		formatter={formatter}
	/>;
}
