import storageForType = require("../../services/storage");
import { StatusDecorator, StatusType } from "../Decorators";
import * as React from "react";
import { Typography } from "../../imports/material-ui-imports";
import { toKB } from "../../services/utils";

export interface ICommonProps {
	fnameFilter: string;
	pickDir?: boolean;
	selectedPath?: string;
}

export interface ICommonItemProps {
	status?: FileStatusType;
	disabled: boolean;
	level: number;
	selectedPath?: string;
	fnameFilter: string;
	getSize: (file: storageForType.IStorageFile) => number;
}

export type FileStatusType = "error" | "warning";
export const paddingPerLevel = 17;
export const statusIconSize = 18;

export function getFileStatusDecorator(path: string, status?: FileStatusType) {
	return status && <StatusDecorator
		id={"decorators" + path}
		key="decorators"
		status={status === "error" ? StatusType.Error : StatusType.Warning}
	/>;
}

export function getFileNameAndSizeComponent(fname: string, size: number) {
	return <div style={{ display: "flex" }}>
		<Typography variant="body2" display="inline" style={{ flex: 1 }} component="span" color="textPrimary">
			{fname}
		</Typography>
		{
			<Typography variant="body2" noWrap display="inline" align="right" style={{ color: "grey" }} component="span">
				{toKB(size)}
			</Typography>
		}
	</div>;
}
