import * as React from "react";
import * as _ from "lodash";
import { PositionedDiv } from "./PositionedDiv";
import { assertUnreachable, getDisplayName } from "../../../services/utils";
import { ClassesType } from "../styling/graphStyles";
import { Radio } from "../../../imports/material-ui-imports";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import * as Layout from "../types/layoutTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// When instantiated as a child of a node, will render all the labels (pins as well as name of node)

interface IProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr> {
	node: Layout.Node<InstMgr, PortMgr>;
	checked?: string;
	onChecked?: (port: string) => void;
	displayScriptName: boolean;
	inputXOffset?: (nodeSize: Layout.Size, y: number) => number;
	outputXOffset?: (nodeSize: Layout.Size, y: number) => number;
}

export function NodeLabels<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(props: IProps<InstMgr, PortMgr> & ClassesType) {

	// x === 0 means on the left (ie input), but x can be negative if ports have a size

	const [inPorts, outPorts] = _.partition(props.node.ports, (port) => port.type === "input");
	return <>
		{"inst" in props.node && <TopLabel {...props} />}
		<MainLabel {...props} />
		{
			// Ensure out ports are rendered first, so inputs (with radio checks) are on top

			_.map(outPorts, (port) =>
				<OutputLabel
					key={port.id}
					port={port}
					{...props}
				/>
			)
		}
		{
			_.map(inPorts, (port) =>
				<InputLabel
					key={port.id}
					port={port}
					{...props}
				/>
			)
		}
	</>;
}

export const enum Alignment {
	CENTER,
	LEFT,
	RIGHT,
}

interface IMainLabelProps {
	node: Layout.Node<ModuleInstanceMgr, AnyMemberMgr> | Layout.Group<ModuleInstanceMgr, AnyMemberMgr>
	displayScriptName: boolean;
	alignment?: Alignment;
}

export function MainLabel({ node, displayScriptName, alignment, classes }: IMainLabelProps & ClassesType) {
	alignment = alignment ?? Alignment.CENTER;
	return <PositionedDiv 								// Main label (name of the ip block)
		x={null}										// Allow the x position to be centered with the node
		y={node.height} 								// Underneath the ip block
		className={getClassName(classes, alignment) + " MainLabel"}
	>
		{"inst" in node ? node.inst.getGraphLabel(displayScriptName) : getDisplayName(node, displayScriptName)}
	</PositionedDiv>;
}

function TopLabel({ node, classes }: { node: Layout.Node<ModuleInstanceMgr, AnyMemberMgr> } & ClassesType) {
	// Seems like a good magic number which works for all nodes, since we're using multi-lines
	// for any \n shift up the offset by 15
	const label = node.inst.getGraphTopLabel();
	const yOffset = -15 - (15 * label.split("\n").length - 1);
	return <PositionedDiv
		x={null}
		y={yOffset}
		className={getClassName(classes, Alignment.CENTER)}
	>
		<div className="topLabel">
			{label.split(/\n/).map((line, index) => index === 0 ? line :
				<React.Fragment key={line}><br />{line}</React.Fragment>)}
		</div>
	</PositionedDiv >;
}

function getClassName(classes: ClassesType["classes"], alignment: Alignment) {
	switch (alignment) {
		case Alignment.CENTER:
			return classes.ipBlockLabel;
		case Alignment.LEFT:
			return classes.inputOnlyConnectionLabel;
		case Alignment.RIGHT:
			return classes.outputOnlyConnectionLabel;
		default:
			assertUnreachable(alignment);
	}
}

const portHeightAdjustment = 8;

class InputLabel<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.Component<{ port: Layout.Port<PortMgr> } & IProps<InstMgr, PortMgr> & ClassesType> {
	public override render() {
		const { node, port, checked, onChecked, displayScriptName, inputXOffset, classes } = this.props;
		return <PositionedDiv
			x={inputXOffset ? inputXOffset(node, port.y) : 0}	// Left justified if there's no offset given
			y={port.y - portHeightAdjustment}									// At the height of the port
			className={classes.inPinLabel}
		>
			{checked && onChecked &&
				<Radio
					id={`muxCheck${port.memberMgr.def.name}`}
					onChange={this.onChange}
					checked={checked === port.memberMgr.def.name}
					className={classes.radioButton}
					color="primary"
				/>
			}
			{getDisplayName(port.memberMgr.def, displayScriptName)}
		</PositionedDiv>;
	}

	private onChange = () => this.props.onChecked(this.props.port.memberMgr.def.name);
}

function OutputLabel<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	{ port, node, displayScriptName, outputXOffset, classes }: { port: Layout.Port<PortMgr> } & IProps<InstMgr, PortMgr> & ClassesType
) {
	return <PositionedDiv
		x={0}
		y={port.y - portHeightAdjustment}												// At the height of the port
		width={node.width + (outputXOffset ? outputXOffset(node, port.y) : 0)}	// Instead of starting on the right, we end on
		className={classes.outPinLabel}													// the right, and then right-justify the text
	>
		{getDisplayName(port.memberMgr.def, displayScriptName)}
	</PositionedDiv>;
}

