import * as _ from "lodash";
import React = require("react");
import { RequirementsList } from "../RequirementsList";
import { ConfigStoreActions } from "../../services/configStore";
import { ModuleInstanceAdderMgr } from "../../services/objectManagers/moduleInstanceAdderMgr";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { List, Divider } from "../../imports/material-ui-imports";
import { layoutListStyle, LayoutListItem, InstanceContainer } from "../Requirements";
import { CModuleInstance } from "./ModuleInstance";
import { ResourceLoader, ResourceType } from "../../services/resources/metaContentLoaders/resourceLoader";
import { ILinkActions } from "../actions/ILinkActions";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ModuleInstanceAdderHeader } from "../RequirementsHeader";
import { LongDescription } from "../LongDescription";
import { Validations } from "../../services/objectManagers/validations";
import { PinDisplayType } from "../../services/userPreferences";
import { ModuleInstanceMgr } from "../../services/objectManagers/moduleInstance";
import { ActionEnabled, ActionState } from "../../services/IMyListItem";

interface IProps {
	actions: ConfigStoreActions & ILinkActions;
	adderMgr: ModuleInstanceAdderMgr;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	showUsed: boolean;
	showPinTable: boolean;
	arePowerDomainSettingsEnabled: boolean;
	focusedSubItemPath: string[];
}

export class CModuleInstanceAdder extends React.Component<IProps & IGlobalServiceProps> {
	public override render() {
		const arrayMgr = this.props.adderMgr;

		const childFocusedSubItemPath =
			(arrayMgr.getNumberOfUsed() > 0 && arrayMgr.getSelectedMyListItem().getName() === _.head(this.props.focusedSubItemPath)) ?
				_.tail(this.props.focusedSubItemPath) :
				[];

		const shouldShowLongDescription = arrayMgr.getModuleMgr().getShowUserLongDescPref();

		const cannotRemoveReason =
			`Must have at least ${arrayMgr.getMinInstanceCount()} instance${arrayMgr.getMinInstanceCount() === 1 ? "" : "s"}.`;

		const addedText = _.isFinite(arrayMgr.getMaxAllowed()) ?
			`${arrayMgr.getNumberOfUsed()}/${arrayMgr.getMaxAllowed()} added` :
			`${arrayMgr.getNumberOfUsed()} added`;

		return (
			<List style={layoutListStyle}>
				<LayoutListItem key="instanceHeader">
					<ModuleInstanceAdderHeader
						{...this.props}
						selectedTreeNode={arrayMgr.getModuleMgr()}
						title={addedText}
						showLongDescription={shouldShowLongDescription}
						hideLongDescriptionButton={false}
						cannotRemoveReason={cannotRemoveReason}
					/>
				</LayoutListItem>
				{shouldShowLongDescription &&
					<LongDescription
						key="reqsDescription"
						id="module_documentation"
						closeDescription={this.closeDescription}
						longDescription={arrayMgr.getModuleMgr().getLongDescription()}
						canonicalName={arrayMgr.getModuleMgr().getName()}
						resourceType={ResourceType.CODE}
						disableClose={false}
						resourceLoader={this.props.resourceLoader}
						actions={this.props.actions}
						formatter={this.props.formatter}
					/>
				}
				<RequirementsList
					selectedTreeNode={arrayMgr}
					formatter={this.props.formatter}
					validations={this.props.validations}
					getItemName={this.getItemName}
					onSelect={this.onSelect}
					canRemove={this.canRemove}
					onRemove={this.onRemove}
					canCopy={this.canCopy}
					onCopy={null}
					moveInstance={null}
					isTopModuleOnContext={this.isTopModuleOnContext}
					getContextSelection={this.getContextSelection}
					instruction={
						<React.Fragment>Click the <b>Add</b> button to add a new element to
							{arrayMgr.getDisplayName(false)}</React.Fragment>
					}
				/>
				{arrayMgr.getNumberOfUsed() > 0 &&
					<React.Fragment>
						<Divider key="listOrInstDiv" />
						< LayoutListItem key="instance">
							<InstanceContainer isPreview={false} id="moduleInstanceContainer">
								<CModuleInstance
									{...this.props}
									instMgr={arrayMgr.getSelectedMyListItem()}
									productLookupName={arrayMgr.getModuleMgr().getName()}
									formatter={this.props.formatter}
									focusedSubItemPath={childFocusedSubItemPath}
								/>
							</InstanceContainer>
						</LayoutListItem>
					</React.Fragment>
				}
			</List>
		);
	}

	private getItemName = (item: ModuleInstanceMgr) => {
		if (item.getNameMgr().uiState.hidden) {
			return this.props.displayScriptName ?
				this.props.adderMgr.getInstanceScriptIdentifier(item) :
				this.props.adderMgr.getInstanceDisplayIdentifier(item);
		} else {
			return this.props.displayScriptName ?
				this.props.adderMgr.getInstanceScriptIdentifier(item) :
				item.getName();
		}
	}
	private onSelect = (item: ModuleInstanceMgr) => this.props.actions.navigateToArrayMember(item);
	private onRemove = (item: ModuleInstanceMgr) => this.props.actions.adderRemoveInstance(this.props.adderMgr, item);
	// TODO: https://jira.itg.ti.com/browse/PMUX-3569 implement copy so instance appears under the instance adder itself
	// private onCopy = (_item: ModuleInstanceMgr) => this.props.actions.copyInstance(item);
	private closeDescription = () => this.props.actions.setShowUserLongDescPref(this.props.adderMgr.getModuleMgr(), false);
	private canCopy = (): ActionState => ({ enabled: ActionEnabled.NEVER });
	private isTopModuleOnContext = (mgr: ModuleInstanceMgr, context: string) => this.props.actions.isTopModuleOnContext(mgr, context);
	private getContextSelection = () => this.props.actions.getContextSelection();
	private canRemove = (item: ModuleInstanceMgr): ActionState => {
		if (this.props.adderMgr.canRemove(item)) {
			return { enabled: ActionEnabled.YES };
		}
		return { enabled: ActionEnabled.NOT_NOW, reason: this.props.adderMgr.getCannotRemoveReason(item) };
	}
}
