import { RuntimeInstance } from "public/runtime";
import { AnyMemberMgr } from "../../pinmux/services/objectManagers/member";
import { AObjectMgr } from "../../pinmux/services/objectManagers/object";
import { Runtime } from "../../pinmux/services/resources/runtime";

export function getManager(runtime: Runtime, inst: RuntimeInstance, memberName?: string): {
	modMgr: AObjectMgr<RuntimeInstance>,
	memberMgr?: AnyMemberMgr
} {
	const mgr = runtime.getManager(inst);
	if (!mgr) {
		throw new Error(`unknown object passed as instance: ${inst}`);
	}
	if (!memberName) {
		return { modMgr: mgr };
	}

	const memberMgr = mgr.memberMgrs[memberName];
	if (!memberMgr) {
		throw new Error(`No such member ${memberName}`);
	}
	return { modMgr: mgr, memberMgr: memberMgr };
}
