import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import { PositionedNode } from "../nodes/PositionedNode";
import { MainLabel } from "../nodes/NodeLabels";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { IInnerGraphProps, InnerGraph } from "../graph/InnerGraph";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// This component renders a graph for a given inner group within a larger layout and outlines it with a box to 
// visually separate it from the containing graph. 

export function Group<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: IInnerGraphProps<InstMgr, PortMgr> & ClassesType
) {
	const { layout, displayScriptName, classes, formatter } = props;
	return <>

		{
			// First, render two PositionedNodes.  The first is the group label and bounding box.  The second is the
			// fill.  The fill is done separately so that it can have a partial opacity and thus groups inside of 
			// groups will be drawn darker over time
		}
		<PositionedNode
			node={layout}
			onClick={noSelect}
			onMouseDown={noSelect}
			className={classes.genericGroupNodeoutline}
			formatter={formatter}
		>
			<MainLabel key="labels" node={layout} displayScriptName={displayScriptName} classes={classes} />
		</PositionedNode>
		<PositionedNode
			node={layout}
			onClick={noSelect}
			onMouseDown={noSelect}
			className={classes.genericGroupNodeFill}
			formatter={formatter}
		/>

		{
			// Now graph the elements inside the group.  Note that ELK will provide all x,y coordinates to nodes, edges
			// and subsequent groups as offset from the group's position.  As such, the graph component will render 
			// everything correctly, as long as we position it where this child group is positioned.  As such, we wrap
			// it in a PositionedNode at the this group's coordinates 
		}
		<PositionedNode
			node={layout}
			onClick={noSelect}
			onMouseDown={noSelect}
			className={classes.positionedDiv}
			formatter={formatter}
		>
			<InnerGraph {...props} />
		</PositionedNode>
	</>;
}

function noSelect() { }
