import { ExternalExecutableConfigurableResult, ExternalLaunchParams, Plots, SpiceLaunchParams } from "public/defs";
import { runTemplate } from "../codeGeneration/templateRunner";
import { Runtime } from "../resources/runtime";
import { isCloud, isNodejs, isWin } from "../platform";
import * as _ from "lodash";
import { ProgressCallback, getExternalComFilePath, launchExternalExecutable } from "../externalExecutable";
import { backendContentPath, getSpicePath, memoizeOne } from "../utils";
import * as path from "path";
import { compileTemplate } from "../resources/templateCompiler";
import { contextifySpicePrejsScript } from "../resources/contextify";
import { IModalService } from "../IModalService";
import { loginServer } from "../loginServer";
import { SimulationFailedError, SimulationTooIntensiveError } from "./simulation";
import { http } from "../http";
import { ResourceType } from "../resources/metaContentLoaders/resourceLoader";
import { httpRootDir } from "../paths";

export function launchSpice(
	productPath: string,
	simOptions: SpiceLaunchParams,
	runtime: Runtime,
	modalService: IModalService,
	progressCallback: ProgressCallback
) {
	const wrappedCallback = createProgressCallback(progressCallback, simOptions.simulationLength);
	if (isCloud()) {
		return launchSpiceInCloud(simOptions, runtime, wrappedCallback);
	} else {
		return launchSpiceOnDesktop(productPath, simOptions, runtime, modalService, wrappedCallback);
	}
}

function getSpiceSimulationLaunch(filePath: string, runtime: Runtime): ExternalLaunchParams {
	return {
		command: getSpicePath(),
		args: ["-b", "$comFile"],
		initialData: prepareCircuitFile(filePath, runtime),
		inSystemPath: true,
	};
}

// get environment variables for running ngspice on desktop
function getSpiceVars() {
	// We need to make sure the correct spinit file is picked up
	const spinit_dir = path.normalize(path.join(getSpicePath(), "..", "..", "share", "ngspice", "scripts"));
	// Change the working directory so that the relative paths in spinit file make sense
	const working_dir = path.normalize(path.join(getSpicePath(), ".."));
	return { cwd: working_dir, env: { SPICE_SCRIPTS: spinit_dir } };
}

function launchSpiceOnDesktop(
	productPath: string,
	simOptions: SpiceLaunchParams,
	runtime: Runtime,
	modalService: IModalService,
	progressCallback: ProgressCallback
) {
	const launchParams = getSpiceSimulationLaunch(simOptions.circuitTemplateName, runtime);
	return launchExternalExecutable(productPath, launchParams, false, modalService, null, progressCallback, getSpiceVars());
}

function simulationIsBelowPointsLimit(simOptions: SpiceLaunchParams): boolean {
	const numPoints = Math.round(simOptions.simulationLength / simOptions.simulationStepSize) * (simOptions.numProbes + 1);
	// Equates to 12s simulation length on TPLD 1201 EVM demo
	// Note: the simulation actually ends up producing more points (maybe ~33% more) than expected
	// Since we are keeping using the same estimation method for all simulations, there should still be
	// some consistency between the number of points we expected to see and whether we could actually run the simulation,
	// even if expected number of points doesn't match actual number of points
	return numPoints < 10800000;
}

// Lazy load ngspice.js (wasm glue code)
function loadWasmGlueCode() {
	return http.get("ngspice/ngspice.js");
}

// Prepare the ngspice cloud launch script to pass to WebWorker
async function getCloudLaunchScriptURL(filePath: string, runtime: Runtime) {
	const additionalFilesFormat = new RegExp("\"" + backendContentPath + "/.*\"", "g");
	const glueCode = await loadWasmGlueCode();
	const circFile = prepareCircuitFile(filePath, runtime);
	// Get the additional files to be loaded for simulation and remove quotations around them
	const additionalFilesPath = _.map(circFile.match(additionalFilesFormat), (file) => file.slice(1, -1));
	const uri = `${window.location.origin}${httpRootDir()}`;
	const loader = compilePrejs();
	const prejsCode = loader("`" + circFile + "`", getOutFile(), uri, additionalFilesPath)();
	return URL.createObjectURL(new Blob([prejsCode + "\n" + glueCode]));
}

// Kick off simulation in webworker
let worker: Worker;
function setupCloudSpiceWorker(script: string, progressCallback: ProgressCallback) {
	return new Promise<string>(((resolve, reject) => {
		worker = new Worker(script);
		worker.onmessage = (ev) => {
			// We manually bubble errors up to the main thread as some errors 
			// don't trigger onerror
			if (ev.data.status === "finished") {
				const res = ev.data.data;
				worker.terminate();
				worker = null;
				resolve(res);
			} else {
				if (ev.data.startsWith("malloc")) {
					// Couldn't allocate mem, so probably too intensive for cloud
					worker.terminate();
					reject(new SimulationTooIntensiveError());
				}
				progressCallback(ev.data);
			}
		};
		worker.onerror = (ev) => {
			reject(ev.error);
		};
	}));
}

function launchSpiceInCloud(simOptions: SpiceLaunchParams, runtime: Runtime, progressCallback: ProgressCallback) {
	if (!simulationIsBelowPointsLimit(simOptions)) {
		throw new SimulationTooIntensiveError();
	}

	const scriptLoader = getCloudLaunchScriptURL(simOptions.circuitTemplateName, runtime);
	const data = scriptLoader.then((script) => setupCloudSpiceWorker(script, progressCallback));
	return {
		response: data,
		cancel: () => {
			// In the scenario that cancel is called before setupCloudSpiceWorker, the worker will not yet be setup and thus would 
			// not be deleted. We can add a .finally callback to scriptLoader to make sure that the worker will terminated even if
			// cancel is called before scriptLoader promise has been fulfilled (in other words before the worker thread has been setup).
			// eslint-disable-next-line @typescript-eslint/no-floating-promises
			scriptLoader.finally(() => {
				if (worker) {
					worker.terminate();
				}
			});
		},
	};
}

const compilePrejs = memoizeOne(() => {
	const prejs: string = require("./ngspice-prejs.js");
	const compiled = compileTemplate(prejs);
	const loader = contextifySpicePrejsScript("", compiled);
	return loader;
});

function prepareCircuitFile(filePath: string, runtime: Runtime) {
	return runTemplate(runtime.getResourceLoader().getResource(filePath, ResourceType.TEMPLATE))
		// We don't need plot commands for running simulation, so remove them
		.replace(/^plot .*$/gm, "")
		// Add a new control block (.control [...] .endc) with our code (i.e. file output commands)
		.replace(/\.end(\r\n|\n)*$/, getCodeInjection());
}

// Code to inject into circuit file
function getCodeInjection(): string {
	return ".control\n" +
		"set filetype=ascii\n" +
		`write ${getOutFile()}\n` +
		".endc\n" +
		".end\n";
}

// ngspice will output to this file
function getOutFile() {
	return isCloud() ? "/out.txt" : getExternalComFilePath();
}

/**
 * When ngspice completes, SysConfig will call this function with the contents of the communication file, which for 
 * this case will be the rawfile ascii output from ngspice.  This function is responsible for converting that output
 * into the simulation results format that SysConfig expects and understands.
 * 
 * This file that ngspice generates will look something like this:
 * 
 *	Title:  transient simulation 
 *	Date: Wed Jun  7 09:08:04  2023
 *	Plotname: Transient Analysis
 *	Flags: real
 *	No. Variables: 4
 *	No. Points: 28361
 *	Variables:
 *		0	time	time
 *		1	v(a__input_din)	voltage
 *		2	v(a__outand_out)	voltage
 *		3	v(outcnt)	voltage
 *	Values:
 *	 0	0.000000000000000e+00
 *		1.649999998167519e+00
 *		1.650000000009799e+00
 *		1.650000000000593e+00
 *	
 *	 1	9.989999999999999e-12
 *		1.650000001520223e+00
 *		1.650000000009799e+00
 *		1.650000000000593e+00
 *
 * Note also that these files can easily be over 200 MB with over 10 million lines, as such manipulating the data can
 * be expensive.  As such, I tried a number of implementations to see what was the fastest.  My first approach was to 
 * split the text by \n and then process it line by line.  However, just the split operation takes longer than the 
 * overall below implementation.  In general, creating additional arrays from this data is expensive (hence why I'm 
 * searching the text vs using split and map).  Second, anything done in the main loop that extracts the data points 
 * will clearly dominate the overall performance (ie it's best not to use something like _trim if we don't have to)
 * 
 * @param {import("public/defs").ExternalExecutableConfigurableResult} result
 * @returns {import("public/defs").PlotData[]}
 */
export function onSpiceSimulationComplete(result: ExternalExecutableConfigurableResult | string): Plots {
	const newLine = isWin() && !isCloud() ? "\r\n" : "\n";
	let text: string;
	if (typeof result == "string") {
		text = result;
	} else {
		text = result.data;
	}
	let index = 0;

	/**
	 * Starting from the current value of 'index', search for 'begin', then 'end', and return the text in between.  
	 * Update 'index' to be after the end text searched for
	 * 
	 * @param {string} begin 
	 * @param {string} end 
	 * @returns {string}
	 */
	function stringBetween(begin: string, end: string) {
		const startIndex = text.indexOf(begin, index) + begin.length;
		const endIndex = text.indexOf(end, startIndex);
		index = endIndex + end.length;
		return text.substring(startIndex, endIndex);
	}

	// Extract how many variables and points we are expecting

	const numVars = Number.parseInt(stringBetween("No. Variables: ", newLine), 10);
	let numPoints = Number.parseInt(stringBetween("No. Points: ", newLine), 10);

	// If we couldn't find this, most likely simulation failed to provide any data.
	// Abort with console information

	if (Number.isNaN(numVars) || Number.isNaN(numPoints)) {
		throw new SimulationFailedError(consoleOutput);
	}

	// Extract the names of the variables
	// Should be in the form \t<number>\t<name to extract>\t<unit><newline>

	index = text.indexOf("Variables:" + newLine + "\t", index) + ("Variables:" + newLine + "\t").length;
	const variables = [];
	for (let i = 0; i < numVars; ++i) {
		variables.push(stringBetween("\t", "\t"));
		index = text.indexOf("\n", index) + 2; // find the end, and skip over the new line and \t
	}

	// Extract the data points.  Each block of points should look something like this:
	// \t<data point index>\t<data point 1>
	// \t<data point 1>
	// \t<data point 1>
	// \t<data point 1>
	// <blank line>

	const data = variables.map(() => []);
	index += ("Values:" + newLine).length;
	while (numPoints--) {
		index = text.indexOf("\t", index + 1) + 1; // shift index to past the data point index
		for (let i = 0; i < numVars; ++i) {
			const floatingPointLength = text[index] === "-" ? 22 : 21;
			data[i].push(Number.parseFloat(text.substring(index, index + floatingPointLength)));
			index += (floatingPointLength + newLine.length + 1); // 1 for the tab on the next line 
		}
		index += 1; // skip the blank line
	}

	// Format the data into multiple plot arrays to return to SysConfig

	const time = _.indexOf(variables, "time");
	return _.chain(variables)
		.map((variable, i) => {
			if (i === time) return null;
			return {
				x: data[time],
				y: data[i],
				xAxisName: "Time",
				yAxisName: variable,
			};
		})
		.compact()
		.value();
}

// Extract progress from output and scale it with total simulation length to get percentage
const expr = /\d+\.\d+e[+-]\d+/;
let consoleOutput = "";
function createProgressCallback(callback: ProgressCallback, simulationLength: number): ProgressCallback {
	consoleOutput = ""; // clear console from previous run
	return (val: string): void => {

		// Remain logged in if the simulation is running

		if (loginServer) {
			loginServer.simulationEvent();
		}

		// Record the simulation so it can be displayed should something fail

		consoleOutput += val;

		// In the UI, log the simulation data to the console for debug

		if (!isNodejs()) {
			// eslint-disable-next-line no-console
			console.log(val);
		}

		// ngspice on MacOS may give value that starts with carriage return
		// lodash utility would not trim this

		val = val.trimStart();

		// If the value would indicate progress, call the original callback with that number

		if (_.includes(val, "No. of Data Rows")) {
			callback("100");
		} else if (val.startsWith("Reference value")) {
			const progress = val.match(expr);
			if (progress) {
				callback(scaleProgress(simulationLength, progress.toString()));
			}
		}
	};
}

function scaleProgress(simLength: number, progress: string): string {
	return ((Number(progress) / simLength) * 100).toString();
}
