// UI Views for meta content defined configurables
import * as React from "react";
import * as _ from "lodash";
import { ATheme, ColorIndex } from "../../styles/themes";
import { Validations } from "../../../services/objectManagers/validations";
import { ButtonConfigurableMgr } from "../../../services/objectManagers/configurables/buttonConfigurableMgr";
import { SecondaryButton } from "../../buttons/SecondaryButton";
import { FileBrowse } from "../../FileBrowse";
import { ResourceLoader, ResourceType } from "../../../services/resources/metaContentLoaders/resourceLoader";
import { assertNeverThrows } from "../../../services/utils";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { IModuleConfigProps } from "../../modals/ModuleConfigModal";
import { Button, ButtonGroup } from "../../../imports/material-ui-imports";
import { commonStyles } from "../../styles/common";
import { Ellipsis } from "../../../imports/mdi-material-ui-imports";

interface IButtonConfigurableProps<T> extends IGlobalServiceProps, IModuleConfigProps {
	mgr: ButtonConfigurableMgr<T>;
	validations: Validations;
	resourceLoader: ResourceLoader;
}

// This is a button controlled by a configurable.  It can appear as a configurable, or as a global button in the wire-
// connections or clocktree views

export function CButtonConfigurable<T>(
	{ mgr, ...rest }: IButtonConfigurableProps<T>) {

	if ((mgr.getPopupMgr() || mgr.getAdditionalSetting()) && mgr.def.popupStyle !== "always") {
		return <DualButtonConfigurable mgr={mgr} {...rest} />;
	} else {
		return <SingleButtonConfigurable mgr={mgr} {...rest} />;
	}
}

function SingleButtonConfigurable<T>(
	{ mgr, validations, errorStore, modalService, theme, ...rest }: IButtonConfigurableProps<T>) {

	const [performMainAction, configurePopupModule] = useButtonActions({ mgr, validations, errorStore, modalService, theme, ...rest });

	// As this is a single button, if there is a popup, then the click has to execute that first.  Otherwise, we can 
	// just perform the main action

	const onClick = React.useCallback((filePath?: string) => {
		if (configurePopupModule) {
			configurePopupModule();
		} else {
			performMainAction(filePath);
		}
	}, [performMainAction, configurePopupModule]);

	// This exists to prevent passing an event object as the path in the case of a non-browsing button.

	const onClickNoPath = React.useCallback(() => onClick(), [onClick]);

	// We need to render a regular button.  If a file/folder must be browsed for, then that work is 
	// offloaded to the FileBrowse component 

	const isDisabled = mgr.isDisabled(validations);
	const id = mgr.def.name + "_Button";
	if (mgr.def.fileFilter || mgr.def.pickDirectory) {
		return <FileBrowse
			onChange={onClick}
			errorStore={errorStore}
			modalService={modalService}
			id={id}
			disabled={isDisabled}
			folder={mgr.def.pickDirectory}
			accept={mgr.def.fileFilter}
		>
			<SecondaryButton
				theme={theme}
				disabled={isDisabled}
				id={id}
			>
				{mgr.def.buttonText}
			</SecondaryButton>
		</FileBrowse>;
	} else {
		return <SecondaryButton
			theme={theme}
			onClick={onClickNoPath}
			disabled={isDisabled}
			id={id}
		>
			{mgr.def.buttonText}
		</SecondaryButton>;
	}
}

function DualButtonConfigurable<T>(
	{ mgr, validations, errorStore, theme, ...rest }: IButtonConfigurableProps<T>) {

	const [performMainAction, configurePopupModule] = useButtonActions({ mgr, validations, errorStore, theme, ...rest });

	// As this is a dual button, the main action is associated with the main part of the button always.  The ... button
	// is to either configure the popup module or set the one additional setting

	const onClick = React.useCallback(() => performMainAction(), [performMainAction]);
	const onEllipsesClick = React.useCallback(() => {
		if (configurePopupModule) {
			configurePopupModule();
		} else {
			assertNeverThrows(errorStore, () => mgr.getAdditionalSetting().set());
		}
	}, [mgr, configurePopupModule, errorStore]);

	// Render a button group consisting of the main button and a ... button

	const [groupStyle, buttonStyle] = useButtonGroupStyle(theme);
	const isDisabled = mgr.isDisabled(validations);
	return (
		<ButtonGroup style={groupStyle} component="span" color="primary" variant="outlined" size="small" disabled={isDisabled}>
			<Button style={buttonStyle} onClick={onClick} id={"actionSerialPortButton"}>
				{mgr.def.buttonText}
			</Button>
			<Button style={buttonStyle} onClick={onEllipsesClick} id={"configureSerialPortButton"}>
				<Ellipsis />
			</Button>
		</ButtonGroup>
	);
}

function useButtonActions<T>(
	{ mgr, validations, errorStore, modalService, theme, resourceLoader, actions, ...rest }: IButtonConfigurableProps<T>
) {
	// This is the main action for this button to perform

	const performMainActionAndGetValidationStatus = React.useCallback(async (filePath?: string) => {
		const productPath = resourceLoader.getProduct(mgr.parentObjectMgr.getModulePath(), ResourceType.CODE).file.path;
		const { result, validationSuccess } = await mgr.getClickResult(productPath, modalService, { filePath: filePath });
		actions.buttonClicked(mgr, result);
		return validationSuccess;
	}, [resourceLoader, mgr, modalService, actions]);

	const performMainAction = React.useCallback((filePath?: string) => {
		assertNeverThrows(errorStore, () => performMainActionAndGetValidationStatus(filePath));
	}, [errorStore, performMainActionAndGetValidationStatus]);

	// If there is a popup module associated with this button, this will pop it up and allow the user to configure it.  
	// If ok is pressed, the main action associated with this button will be performed

	const popupModuleInst = mgr.getPopupMgr();
	const configurePopupModule = React.useCallback(() => {
		const additionalSetting = mgr.getAdditionalSetting();
		modalService.showModuleConfigModal({
			...rest,
			resourceLoader,
			actions,
			validations,
			errorStore,
			theme,
			popupModuleInst,
			onConfirmAction: (closeModal) => {
				assertNeverThrows(errorStore, async () => {
					const validationSuccess = await performMainActionAndGetValidationStatus();
					if (validationSuccess && (!additionalSetting || await additionalSetting.isSet())) {
						closeModal();
					} else if (validationSuccess && additionalSetting.set()) {
						closeModal();
					}
				});
			},
			title: mgr.def.buttonText,
			embeddedButtonProps: additionalSetting ? {
				label: additionalSetting.label,
				buttonText: additionalSetting.buttonText,
				onClick: () => assertNeverThrows(errorStore, () => additionalSetting.set()),
			} : undefined,
		});
	}, [mgr, resourceLoader, actions, validations, errorStore,
		theme, modalService, performMainActionAndGetValidationStatus, rest, popupModuleInst]);

	return [performMainAction, popupModuleInst ? configurePopupModule : null];
}

// Theme-based styling

function useButtonGroupStyle(theme: ATheme) {
	const groupStyle = React.useMemo(() => ({
		backgroundColor: theme.colors[ColorIndex.ALTBACKGROUNDCOLOR],
		margin: 0,
		...commonStyles.button,
		marginBottom: theme.theme.spacing(2),
	}), [theme]);

	const buttonStyle: React.CSSProperties = React.useMemo(() => ({
		backgroundColor: theme.colors[ColorIndex.BUTTONBACKGROUNDCOLOR],
		whiteSpace: "nowrap",
	}), [theme]);

	return [groupStyle, buttonStyle];
}
