import * as React from "react";
import {
	Modal, ModalProps, Typography, Divider,
} from "../../imports/material-ui-imports";
import { commonStyles } from "../styles/common";
import { ATheme, defaultTheme, ThemeType } from "../styles/themes";

export interface IModalMinProps {
	registerSubModalMountPoint: (el: HTMLDivElement) => void;
	theme: ATheme;
}

export interface IBasicModalProps extends IModalMinProps {
	title?: string;
	actions?: JSX.Element;
	modalProps?: Omit<ModalProps, "children">;
	onClose: () => void;
	id?: string;
	titleIcon?: JSX.Element;
	hideTitleIcon?: boolean;
}

export class BasicModal extends React.Component<React.PropsWithChildren<IBasicModalProps>> {
	public override render() {
		const showTitleIcon = !this.props.hideTitleIcon && this.props.titleIcon;
		return (
			<Modal {...this.props.modalProps} id={this.props.id} open={true} onClose={this.props.onClose}>
				<div style={this.props.theme.name === ThemeType.LIGHT ? commonStyles.lightModalStyle : commonStyles.darkModalStyle}>
					{/* whiteSpace: "pre" preserves whitespace of content and only wrap on line break */}
					{
						<div style={{ paddingBottom: defaultTheme.theme.spacing(1) }}>
							{showTitleIcon && this.props.titleIcon}
							{<Typography variant="subtitle1"
								style={{
									whiteSpace: "pre",
									display: "inline",
									paddingLeft: defaultTheme.theme.spacing(1),
								}}>
								{this.props.title}
							</Typography>
							}
						</div>
					}
					<Divider light={true} />
					<div style={{
						paddingLeft: defaultTheme.theme.spacing(1),
						paddingBottom: defaultTheme.theme.spacing(2),
						paddingTop: defaultTheme.theme.spacing(2),
					}}>

						{this.props.children}
					</div>
					<div>
						{this.props.actions}
					</div>
					{this.props.registerSubModalMountPoint &&
						<div ref={this.props.registerSubModalMountPoint}></div>
					}
				</div>
			</Modal>
		);
	}
}
