import * as _ from "lodash";
import {
	EnumerationOption,
	DisplayFormat,
	EnumerationConfigurable,
	NumberEnumerationConfigurable,
} from "public/defs";
import { ModuleInstance, RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { SCHEMA, validateMeta } from "../../JSONschemaValidator";
import { getOldMemberMgr, getOldModInstMgr } from "../../migration/migrateUtils";
import { disableScriptingForCallback } from "../../scripting/scriptingGuard";
import { formatNumStr, getRadix, getAdvancedDisplayFormatOptions } from "../../utils/numberUtils";

import { AObjectMgr } from "../object";
import { IOptions } from "../options";
import { Validations } from "../validations";
import { ConfigurableMgr } from "./configurableMgr";

export abstract class BaseEnumerationConfigurableMgr<
	Type extends number | string = string,
	Value extends Type | Type[] = Type,
	RuntimeObjectType extends RuntimeObject = RuntimeObject,
	DefType extends EnumerationConfigurable<Type, Value> = EnumerationConfigurable<Type, Value>>
	extends ConfigurableMgr<Value, RuntimeObjectType, DefType>
	implements IOptions<Type> {

	protected legacyNamesMap = new Map<Type, Type>();

	private defIsNumeric: boolean;

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		def: DefType,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);
		this.defIsNumeric = isNumeric(def);
		this.createLegacyNamesMap();
	}

	public getUIOptions() {
		const options = _.clone(this.getOptions());
		const disabledOptions = _.map(this.getDisabledOptions(), (disabledOpt) => {
			const opt = _.find(options, (o) => o.name === disabledOpt.name);
			if (!opt) {
				throw new Error(`${this.def.name}: attempted to disable unknown option '${disabledOpt.name}'`);
			}
			_.pull(options, opt);
			return { ...opt, description: disabledOpt.reason };
		});

		const displayFormat = (this.def as NumberEnumerationConfigurable).displayFormat;
		return {
			disabledOptions: toDropDownOptions(disabledOptions, displayFormat),
			enabledOptions: toDropDownOptions(options, displayFormat),
		};
	}

	public getCLIOptions() {
		const options = _.clone(this.getOptions());
		const disabledOptions = this.getDisabledOptions();
		_.each(disabledOptions, (disabledOpt) => {
			const opt = _.find(options, (o) => o.name === disabledOpt.name);
			if (!opt) {
				throw new Error(`${this.def.name}: attempted to disable unknown option '${disabledOpt.name}'`);
			}
			_.pull(options, opt);
		});
		return {
			disabledOptions: disabledOptions,
			enabledOptions: _.map(options, (o) => o.name),
		};
	}

	public override getUIHash(validations: Validations): string {
		if (this.def.getDisabledOptions || this.isDynamic()) {
			return null;
		}
		return super.getUIHash(validations);
	}

	public getOptions(): EnumerationOption<Type>[] {
		const options = this.def.options;
		if (_.isFunction(options)) {
			const inst = this.getParentRuntimeObj() as ModuleInstance;
			const currentOptions = disableScriptingForCallback(() => options(inst));
			const schema = this.checkAndUpdateIsNumeric(currentOptions) ? SCHEMA.NumericEnumOptions : SCHEMA.StringEnumOptions;
			validateMeta(currentOptions, this.def.name, schema);
			const invalidOptions = _.chain(this.getCurrentSelections())
				.differenceWith(currentOptions, (a, b) => a === b.name)
				.map((name) => ({ name }))
				.value();
			return [
				...currentOptions,
				...invalidOptions,
			];
		}
		return options;
	}

	public isNumeric() {
		return this.defIsNumeric;
	}

	public isDynamic() {
		return _.isFunction(this.def.options);
	}

	protected abstract getCurrentSelections(): Type[];

	protected override formatInvalidValue(value: unknown): string {
		const { modInstMgr, memberPath } = this.parentObjectMgr.getContainingModule();
		const copyPath = [...memberPath, this.def.name];
		const oldModMgr = getOldModInstMgr(modInstMgr);
		if (oldModMgr) {
			const memberMgr = getOldMemberMgr(oldModMgr, copyPath);
			if (memberMgr instanceof BaseEnumerationConfigurableMgr) {
				const options = memberMgr.getDropdownOptions();
				if (options) {
					return _.find(options, (o) => o.name === value)?.displayName;
				}
			}
		}
		return null;
	}

	private getDisabledOptions() {
		if (this.def.getDisabledOptions) {
			const disabledOptions = disableScriptingForCallback(
				() => this.def.getDisabledOptions(this.parentObjectMgr.managedObject as ModuleInstance));
			const schema = this.checkAndUpdateIsNumeric(disabledOptions) ? SCHEMA.DisabledNumericOptions : SCHEMA.DisabledStringOptions;
			validateMeta(disabledOptions, this.def.name, schema);
			return disabledOptions;
		}
		return [];
	}

	private createLegacyNamesMap() {
		if (!this.isDynamic()) {
			const options = this.getOptions();
			// create map with legacy names
			_.each(options, (o) => {
				_.each(o.legacyNames, (legacyName) => {
					this.legacyNamesMap.set(legacyName, o.name);
				});
			});
		}
	}

	private getDropdownOptions() {
		return this.getUIOptions().enabledOptions;
	}

	private checkAndUpdateIsNumeric(options: { name: string | number }[]): options is { name: number }[] {
		if (null === this.defIsNumeric && !_.isEmpty(options)) {
			this.defIsNumeric = _.isNumber(_.first(options)?.name);
		}
		return this.defIsNumeric;
	}
}

function isNumeric<
	Type extends number | string = string,
	Value extends (Array<Type> | Type) = Type
>(
	def: EnumerationConfigurable<Type, Value>
) {
	if (_.isArray(def.default)) {
		if (!_.isEmpty(def.default)) {
			return _.isNumber(_.first(def.default));
		} else if (_.isArray(def.options)) {
			return _.isNumber(_.first(def.options).name);
		}

		// Multi-select, no default and dynamic options.  
		// Return null with the plan to set it when the dynamic options are fetched later

		return null;
	}
	return _.isNumber(def.default);
}

export function unknownOptionError<T extends number | string>(val: T, validOptions: T[]) {
	throw new Error(`No option named ${val} defined, valid options are\n${validOptions.join("\n")}`);
}

// Convert options to always have a string-based name 
// also format numeric enum values and use that as displayName if none is provided

function toDropDownOptions<T extends string | number>(
	options: (EnumerationOption<T>)[], displayFormat?: DisplayFormat
) {
	return _.map(options, (o) => {
		if (_.isNumber(o.name) && !o.displayName) {
			const nameAsString = formatNumStr(o.name.toString(), getRadix(displayFormat), {
				bitSize: getAdvancedDisplayFormatOptions("bitSize", displayFormat),
				fixedPoint: getAdvancedDisplayFormatOptions("fixedPoint", displayFormat),
			});
			return { ...o, name: o.name.toString(), displayName: nameAsString };
		} else {
			return { ...o, name: o.name.toString() };
		}
	});
}
