/**
 * Apply a use case override to a configurable member
 * @param memberMgr 
 * @param override 
 */
export function applyUseCaseOverride(memberMgr: AnyMemberMgr, override: DeviceInfo.ConfigurableOverride) {

	const configurable = memberMgr.def;
	const uiState = memberMgr.uiState;

	uiState.readOnly = configurable.readOnly || override.readOnly;
	uiState.hidden = configurable.hidden || override.hidden;

	// Some times device data has garbage value data when the configurable is hidden.
	// We don't support setting values on hidden configurables.

	if (!uiState.hidden) {
		if (isCheckBoxOverride(override) && memberMgr instanceof BooleanConfigurableMgr) {
			memberMgr.set(override.checked, SetSource.TOOL_INTERNAL);
		} else if (isTextBoxOverride(override) && memberMgr instanceof TextConfigurableMgr) {
			memberMgr.set(override.value, SetSource.TOOL_INTERNAL);
		} else if (isDropDownOverride(override) && memberMgr instanceof EnumerationConfigurableMgr) {
			memberMgr.set(override.optionName, SetSource.TOOL_INTERNAL);
		} else {
			throw new Error("Unsupported override type!");
		}
	}
}

export function createPinsAndPinGroupFromUseCase(
	instMgr: PinmuxPeripheralInterfaceInstanceMgr,
	runtime: Runtime,
	useCaseDef: UseCase,
) {
	const pins = _.chain(useCaseDef.useCasePins)
		.map((uc) => {
			const newPin = new PinMgr(
				runtime,
				(options: FormatOptions) => format(instMgr, options, uc.name),
				uc.name,
				instMgr.getPeripheralFilter(),
				uc,
				null,
				{},
				instMgr,
				undefined,
				instMgr.isReservation(),
			);

			// The BUs define use-cases/interfaces that cross multiple devices.  As such, sometimes a pin won't
			// actually have any muxing associated with it.  For those pins, the BU has asked that we filter 
			// them out

			if (_.isEmpty(newPin.getOverrideMember().getDevicePins())) {
				newPin.remove();
				return null;
			}

			newPin.applyUseCaseOverrides(uc);
			return new PinMemberMgr(
				newPin,
				runtime.getFormattersMap(),
				{
					name: uc.name,
				},
				instMgr,
			);
		})
		.compact() // filter out the nulls returned above
		.value();

	const pinGroup = _.map(useCaseDef.useCasePinSets, (useCasePinSet) => {
		const def = {
			name: _.isEmpty(useCasePinSet.name) ?
				defaultPinGroupName :
				useCasePinSet.name,
		};
		return (
			new PinGroupMemberMgr(
				new MultiPinMgr(
					runtime,
					instMgr.getPeripheralFilter(),
					useCasePinSet,
					instMgr,
					instMgr.isReservation(),
				),
				runtime.getFormattersMap(),
				def,
				instMgr,
			)
		);
	});

	return { pins, pinGroup };
}

// Default pin group name
// Currently, there is only ever 1 pin group and may not have a name so we need to give it a default name
const defaultPinGroupName: keyof InterfaceInstance = "$pinGroup";

export function resetAndOverrideConfigsFromUseCase(
	instMgr: PinmuxPeripheralInterfaceInstanceMgr,
	useCaseDef: UseCase,
) {
	_.each(instMgr.getInterfaceConfigurables(), (c) => {
		const configMember = instMgr.memberMgrs[c.name];
		// TODO?
		// configMember.resetValidation();

		// override
		const override = _.find(useCaseDef.configurables, (o) => o.name === c.name);
		if (override) {
			applyUseCaseOverride(configMember, override);
		} else {
			configMember.resetDefaultUIState();
		}
	});
}

/**
 * Simple validation for text configurables defined in device data.
 */
export function simpleValidation(configurable: TextConfigurableMgr, validationLogger: InternalValidationLogger) {
	const def = configurable.def;
	if (isJSONConfigurable(def)) {
		if (!configurable.getValue().match(def.validationRegex)) {
			validationLogger.logError(def.validationFailMessage, configurable);
		}
	}
}

function isJSONConfigurable(def: TextConfigurableDef): def is DeviceInfo.TextBox {
	return typeof (def as any).validationRegex !== "undefined";
}

export function isPinInterfaceRequirement(
	req: InterfaceRequirement | PinInterfaceRequirement, isOptimizable: boolean): req is PinInterfaceRequirement {
	if (req.pinOnly && !isOptimizable) {
		throw new Error("pinOnly set to true for non-optimizable interface " + req.interfaceName);
	}
	return req.pinOnly ?? (isOptimizable && req.interfaceName === "GPIO");
}

export function filterHiddenPinMembers(pinMemberMgrs: (ExtendedPinMemberMgr | PinMemberMgr)[]) {
	return (
		_.chain(pinMemberMgrs)
			.filter((pm) => !pm.uiState.hidden)
			.map((pm) => pm.valueObjectMgr)
			.value()
	);
}

export function addMetaContentConfigurableMgrs(
	col: { metaContentConfigurableMgrs: { [memberName: string]: MetaContentConfigurableMgr } },
	toAdd: MetaContentConfigurableMgr[],
) {
	_.each(toAdd, (member) => {
		col.metaContentConfigurableMgrs[member.def.name] = member;
	});
}

export function findDefaultUseCase(ifaceData: Interface) {
	// try to use the legacy one
	const defaultUseCaseName =
		ifaceData.useCases[ifaceData.name + "_0"]
			? ifaceData.name + "_0" : _.sortBy(ifaceData.useCases, "description")[0].name;
	return defaultUseCaseName;
}

export function createAllPinUseCase(iface: Interface): UseCase {

	const allPins: UseCasePin[] =
		_.chain(iface.interfacePins)
			.values()
			.map((iPin) => {
				return {
					name: iPin.name,
					description: iPin.description,
					configurables: [],
					interfacePin: iPin,
					async: false,
					optional: false,
					id: null,
					attributes: null,
				};
			})
			.value();

	return {
		name: "All Pins",
		description: "All Pins",
		configurables: [],
		interface: iface,
		useCasePins: toNameMap(allPins),
		useCasePinSets: [],
		id: null,
		attributes: null,
	};
}

// get all the assignedTo name for pins
export function getAssignedPins(reqs: OptimizablePin[] | Peripheral[]) {
	const allPins = _.flatMap(reqs, (r) => {
		return _.chain(r.pinRequirements)
			.map((p) => p.solution.assignedToName) // get the assignedTo name
			.compact()  // ignore empty strings (error case)
			.value();
	});

	const pinMap: Set<string> = new Set(allPins);

	return pinMap;
}

export function isModuleInstanceAdderRequirement(
	req: ModuleInstanceRequirement,
): req is ModuleInstanceAdderRequirement {
	return !!req.useArray;
}
