import * as _ from "lodash";
import * as React from "react";
import {
	// Note that we are using the MUI tooltip, and not our own wrapper.  We do 
	// this because our wrapper adds a <span> over top of the child in order to
	// work with disabled and internal components, and also so that the 
	// onChange of Tabs gets a callback.  Ideally, we need to fix our wrapper 
	// so it can be used	
	Tooltip,
} from "../../../imports/material-ui-imports";
import { generateToolTipProps } from "../../Tooltip";

// Renders a <div> at a specific position
// Used as a building block for other components

interface IProps {
	x: number;
	y: number;
	id?: string;
	width?: number,
	height?: number,
	onClick?: React.MouseEventHandler<HTMLDivElement>;
	onMouseDown?: React.MouseEventHandler<HTMLDivElement>;
	onMouseUp?: React.MouseEventHandler<HTMLDivElement>;
	className: string;
	tooltip?: React.ReactNode;

	// These props are used for displaying a contextual summary of the node for TPLD
	errors?: string[];
	warnings?: string[];
}

export function PositionedDiv(
	{ x, y, id, width, height, onClick, onMouseDown, onMouseUp, className, children, tooltip }: React.PropsWithChildren<IProps>) {

	return (
		// Note that tooltip must be placed here since it must be the parent of a div in order to attach listeners
		<Tooltip {...generateToolTipProps({ title: tooltip, interactive: false })}>
			<div
				style={{
					top: y,
					left: x,
					width: width,
					height: height,
				}}
				id={id}
				onClick={onClick}
				onMouseDown={onMouseDown}
				onMouseUp={onMouseUp}
				className={className}
			>
				{children}
			</div>
		</Tooltip>
	);
}
