import * as React from "react";
import * as _ from "lodash";
import type * as Plotly from "plotly.js-basic-dist-min";
import { IThemedPlotlyProps, ThemedPlotly } from "./ThemedPlotly";

// This is a component that wraps ThemedPlotly so that zoom events can be handled by the parent component and not 
// plotly.  This is desired if the data is very large as plotly grinds to a halt in those cases.  As such:
// 1) This component will handle vertical zoom itself
// 2) Events are exposed to allow the parent to re-scale the data on a horizontal zoom 
//
// To accomplish this, the initial y axes are fixed to the max/min of the initial scaled data, unless overridden by 
// the parent component.  In addition, the "reset axes" button is removed and replaced so that it's click will reset
// the zoom to the start (plotly would just reset the zoom to the current which doesn't help)

// cSpell:ignore dragmode, yaxis, xaxis

interface IProps extends Omit<IThemedPlotlyProps, "onReLayout" | "onDoubleClick"> {
	data: Partial<Plotly.PlotData>[],
	onResetZoom: () => void;
	onZoom: (min: number, max: number) => void;
}

export function PreScaledPlotly({
	plotly,
	data,
	layout,
	config,
	onResetZoom,
	onZoom,
	...rest
}: IProps) {

	const [initialRanges] = React.useState(() => getRanges(data, layout));
	const [ranges, setRanges] = React.useState(initialRanges);
	const [dragMode, setDragMode] = React.useState<Plotly.Layout["dragmode"]>("zoom");

	// This event is fired when the drag mode changes, or when a zoom event happens.  The cause can be determined by
	// looking at the members on the event object

	const onReLayout = React.useCallback(
		(event: Plotly.PlotRelayoutEvent) => {

			// Check for a vertical zoom and update the ranges

			const newRanges = _.map(ranges, (old, index) => {
				const yaxisRange0 = `${yaxis(index)}.range[0]`;
				if (yaxisRange0 in event) {
					return [(event as any)[yaxisRange0], (event as any)[`${yaxis(index)}.range[1]`]];
				}
				return old;
			});
			if (!_.isEqual(ranges, newRanges)) {
				setRanges(newRanges);
			}

			// Check for a drag mode change (clicking on the pan or zoom button)

			if (event.dragmode) {
				setDragMode(event.dragmode);
			}

			// Check for a horizontal zoom, which can happen at the same time as a vertical zoom

			if ("xaxis.range[0]" in event) {
				onZoom(event["xaxis.range[0]"], event["xaxis.range[1]"]);
			}

		},
		[ranges, onZoom]);

	// Double click === reset zoom

	const onHorizontalAndVerticalZoomReset = React.useCallback(() => {
		setRanges(initialRanges);
		onResetZoom();
	}, [initialRanges, onResetZoom]);

	return <ThemedPlotly
		{...rest}
		plotly={plotly}
		data={data}
		layout={setVerticalZoom(layout, ranges, dragMode)}
		config={overrideResetAxes(config, plotly, onHorizontalAndVerticalZoomReset)}
		onDoubleClick={onHorizontalAndVerticalZoomReset}
		onReLayout={onReLayout}
	/>;
}

// Base the ranges on the min/max of the data, unless a specific range is set in the layout

function getRanges(data: Partial<Plotly.PlotData>[], layout: Partial<Plotly.Layout>) {
	return _.map(data, (plot, index) => {
		return layout[yaxis(index)]?.range ?? [_.min(plot.y as Plotly.Datum[]), _.max(plot.y as Plotly.Datum[])];
	});
}

// Set the vertical zoom by adjusting the range in the yaxis.  This function also updates the drag mode

function setVerticalZoom(layout: Partial<Plotly.Layout>, ranges: number[][], dragMode: Plotly.Layout["dragmode"]) {
	const yaxes = _.map(ranges, (range, index) => {
		const key = yaxis(index);
		const rangeExtra = (range[1] - range[0]) * 0.05;
		return [
			key,
			{
				...layout[key],
				range: [range[0] - rangeExtra, range[1] + rangeExtra],
			},
		];
	});
	return {
		...layout,
		..._.fromPairs(yaxes),
		dragmode: dragMode,
	};
}

// This function adapts the passed in config object to remove the "reset axes" button and add our own that looks the 
// same, but calls our own function to do the reset

function overrideResetAxes(
	config: Partial<Plotly.Config>,
	plotly: typeof Plotly,
	onResetAxes: () => void,
): Partial<Plotly.Config> {

	return {
		...config,
		modeBarButtonsToRemove: [
			...config.modeBarButtonsToRemove,
			"resetScale2d",
		],
		modeBarButtonsToAdd: [
			{
				name: "resetScale2d",
				title: "Reset axes",
				icon: plotly.Icons.home,
				click: onResetAxes,
				toggle: false,
				attr: "clickMode",	// If not defined, any other toggle button will toggle us
			},
			...config.modeBarButtonsToAdd,
		],
	};
}

// This function/type combo allows us to get the name of the yaxis configuration key such that using that dynamically 
// generated key on a layout object will return something sensible type-wise

type YAxisKey = "yaxis" | "yaxis2" | "yaxis3" | "yaxis4" | "yaxis5" | "yaxis6" | "yaxis7" | "yaxis8" | "yaxis9";
function yaxis(index: number): YAxisKey {
	return `yaxis${index ? index + 1 : ""}` as YAxisKey;
}
