/* eslint-disable react/jsx-no-bind */
import * as React from "react";
import * as _ from "lodash";
import { MultiDropDown } from "../../DropDown";
import { IConfigurablesActions } from "../../actions/configurableActions";
import {
	MultiInstanceReferenceConfigurableMgr,
} from "../../../services/objectManagers/configurables/multiInstanceReferenceConfigurableMgr";
import { FormattedDropDownOption } from "../../ComponentUtils";
import { ModuleInstance } from "public/runtime";

interface IProps {
	mgr: MultiInstanceReferenceConfigurableMgr;
	actions: IConfigurablesActions;
}

export function MultiInstanceReferenceConfigurable({ mgr, actions }: IProps) {
	const { enabledOptions, selectedOptionName } = mgr.getUIOptions();

	const onChange = React.useCallback((_instNames: string[], actualOptions: FormattedDropDownOption<ModuleInstance>[]) => {
		actions.setConfigurableValue(mgr, _.map(actualOptions, ({ data }) => data));
	}, [mgr, actions]);

	return (
		<MultiDropDown
			id={mgr.def.name}
			disabled={!!mgr.uiState.readOnly}
			selectedOptionName={selectedOptionName}
			enabledOptions={enabledOptions}
			disabledOptions={[]}
			onChange={onChange}
			displayScriptName={false} // script name is a variable in the script, and we can't determine that trivially
			selectAll={!mgr.def.disableSelectAll}
		/>
	);
}
