import * as Layout from "../../types/layoutTypes";
import { createFinalSvgPathNode } from "../createSvgPathNode";
import { orPath, getOrPortOffset } from "./OrNode";

// Node for an XOR gate

const thickness = 0.1; // This allows us to draw a non-zero horizontal line at the top which ensures a flat edge
const gap = 10; // Includes thickness
export function xorPath(width: number, height: number) {
	return orPath(width - gap, height, gap)
		+ " M 0 0 "
		+ `H ${thickness} `
		+ `A ${width} ${height} 0 0 1 ${thickness} ${height} `
		+ "H 0 "
		+ `A ${width} ${height} 0 0 0 0 0 Z`;
}

export function getXOrLabelXOffset(nodeSize: Layout.Size, y: number) {
	return getOrPortOffset(nodeSize, y) + gap;
}

export const xorWidthAdjustment = gap;

// There will only ever be one output, so hight-based adjustments at the output aren't needed.

export const XOrNode = createFinalSvgPathNode(xorPath,
	{ extraWidth: gap, inputPortXOffset: getOrPortOffset, inputLabelXOffset: getXOrLabelXOffset });

