import * as _ from "lodash";
import * as React from "react";
import * as ReactDOM from "react-dom";
import { TabName as TabNameStringUnion } from "embed/widgets";
import { SysConfigEnv } from "embed/core";
import { ConfigStore } from "../../pinmux/services/configStore";
import { ThemeProvider, CssBaseline } from "../../pinmux/imports/material-ui-imports";
import { TabName } from "../../pinmux/services/tabNames";
import { StandardView, getStateFromConfigStore } from "../../pinmux/components/Config";
import { envMap } from "../core/asyncCreateEnv";
import { ModalService } from "../../pinmux/services/ui/modals";
import { NotificationService } from "../../pinmux/services/ui/notification";
import { SimulationTreeNode } from "../../pinmux/services/simulation/simulationTreeNode";
import { SimulationView } from "../../pinmux/components/simulation/SimulationView";
import { commonStyles } from "../../pinmux/components/styles/common";
import { IGlobalProps } from "../../pinmux/components/IGlobalServicesProps";
import { isNodejs } from "../../pinmux/services/platform";

// Do not install CSS unless running in the UI
// While this code is all UI specific, this conditional import of the font allows this file to be imported at the top
// level, even if the code is not used at runtime, which is the case when used as a nodejs library

if (!isNodejs()) {
	require("typeface-roboto");
}

interface IProps extends IGlobalProps {
	configStore: ConfigStore,
}

const rootDivStyle = {
	...commonStyles.rowFlexLayout,
	boxSizing: "border-box",
} as const;

function GCTabWidget({ configStore, theme, ...rest }: IProps) {

	const [, forceRender] = React.useReducer((x) => x + 1, 0);
	React.useEffect(() => {
		configStore.onAnyChange().addListener(forceRender);
		return () => {
			configStore.onAnyChange().removeListener(forceRender);
		};
	}, [forceRender, configStore]);

	const progressCallback = React.useCallback((val: number | string) => configStore.setSimulationProgress(Number(val)), [configStore]);

	const isSimulation = configStore.getSelectedTab().getTitle() === TabName.SIMULATION;
	return (
		<ThemeProvider theme={theme.theme}>
			<CssBaseline />
			<div style={rootDivStyle} id="TabWidget">
				{!isSimulation &&
					<StandardView
						{...rest}
						{...getStateFromConfigStore(configStore)}
						configStore={configStore}
						showPreferredVoltage={configStore.getDeviceData().showPreferredVoltage}
						branding={configStore.getBranding()}
						theme={theme}
					/>
				}
				{isSimulation &&
					<SimulationView
						theme={theme}
						fetchSimData={configStore.getFetchSimDataFunc()}
						simulationTreeNode={configStore.getSelectedTab().getSelectedNode() as SimulationTreeNode}
						progress={configStore.getSimulationProgress()}
						setProgress={progressCallback}
						branding={configStore.getBranding()}
					/>
				}
			</div>
		</ThemeProvider >
	);
}

export function mountTab(htmlElement: HTMLElement, env: SysConfigEnv, tabName: TabNameStringUnion) {
	const { configStore, globalServices } = envMap.get(env);
	const { theme, errorStore, notificationService, modalService } = globalServices;
	if (!(modalService instanceof ModalService)) {
		throw new Error("No <span> provided for modals - must call asyncCreateEnv with two valid span ids for notifications/modals");
	}
	if (!(notificationService instanceof NotificationService)) {
		throw new Error("No <span> provided for notifications - must call asyncCreateEnv with two valid span ids for notifications/modals");
	}
	if (!(htmlElement)) {
		throw new Error("No <span> provided for UI");
	}

	const tab = _.find(configStore.getTabs(), (t) => t.getTitle() === tabName);
	if (!tab) {
		throw new Error("Unknown tab: " + tabName);
	}
	if (configStore.getSelectedTab() !== tab) {
		configStore.handleTabClick(tab);
	}

	ReactDOM.render(
		<GCTabWidget
			configStore={configStore}
			theme={theme}
			errorStore={errorStore}
			notificationService={notificationService}
			modalService={modalService}
		/>,
		htmlElement
	);
}

export function unmount(htmlElement: HTMLElement) {
	ReactDOM.unmountComponentAtNode(htmlElement);
}
