import { createFinalSvgPathNode } from "../createSvgPathNode";

// Node for an AND gate

const semiCircleFraction = 2 / 5;
const rectFraction = 1 - semiCircleFraction;
export function andPath(width: number, height: number) {
	return "M 0 0 " 															// Start in top left corner
		+ `H ${width * rectFraction} ` 											// Horizontal line at top
		+ `a ${width * semiCircleFraction} ${height / 2} 0 0 1 0 ${height} `	// Semi circle on right side
		+ "H 0 " 																// Horizontal line at bottom
		+ "v 0 " 																// Vertical line back to the start
		+ "Z";																	// Close shape
}

// While the output side is curved, ANDs will only ever have one output which will be centered and thus no adjustments
// are necessary

export const AndNode = createFinalSvgPathNode(andPath);
