import * as React from "react";
import * as _ from "lodash";
import { CModuleInstance, CView, IConfigProps } from "../../objectManagers/ModuleInstance";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { Typography, IconButton } from "../../../imports/material-ui-imports";
import { ContentCopy, DeleteOutline } from "../../../imports/mdi-material-ui-imports";
import { shouldShowLongDescription } from "../../../services/utils";
import { DisplayLongDescButton, LongDescription } from "../../LongDescription";
import { ResourceType } from "../../../services/resources/metaContentLoaders/resourceLoader";
import { IGraphTreeNode } from "../types/IGraphTreeNode";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { Popup } from "../../Popup";
import { CannotDoActionPopup } from "../../CannotDoActionPopup";
import { commonStyles } from "../../styles/common";
import { ModuleMgr } from "../../../services/instanceContainers/module";
import { ActionEnabled } from "../../../services/IMyListItem";

// This component represents the configurables for the currently selected node in the graph

interface IProps extends Omit<IConfigProps, "instMgr" | "productLookupName">, IGlobalServiceProps {
	treeNode: IGraphTreeNode<ModuleInstanceMgr>;
}

const divStyle = { width: "100%", height: "100%", display: "flex", flexDirection: "column", overflowY: "hidden" } as const;
const headerContainerStyle = { padding: 8, display: "flex", whiteSpace: "nowrap" } as const;
const flexSpaceInHeaderStyle = { width: "100%" } as const;
const contentContainerStyle = { flex: 1, height: "100%", overflowY: "auto" } as const;

export class GraphConfigurables extends React.Component<IProps> {

	public override render() {
		const { actions, treeNode, ...rest } = this.props;
		const instMgr = this.getInstMgr();
		if (!instMgr) {
			return <div style={divStyle} />;
		}
		const moduleMgr = instMgr.getModuleMgr();
		const showLongDescription = shouldShowLongDescription(moduleMgr, false);
		const canCopy = instMgr.canCopy();
		const canRemove = instMgr.canRemove();

		return (
			<div style={divStyle}>
				<div style={headerContainerStyle}>
					<Typography variant="button" display="inline" gutterBottom>
						{instMgr.getGraphConfigurablesTitle(this.props.displayScriptName)}
					</Typography>
					<DisplayLongDescButton
						onClick={this.toggleLongDescription}
						name={moduleMgr.getDisplayName(false)}
						hidden={!moduleMgr.getLongDescription()}
					/>
					{/* div ensures copy/remove icons are pushed to the far right */}
					<div style={flexSpaceInHeaderStyle} />
					<>
						{canCopy.enabled !== ActionEnabled.NEVER &&
							<Popup
								align="left"
								getContent={this.getCopyButtonTooltip}
							>
								<IconButton
									disabled={canCopy.enabled === ActionEnabled.NOT_NOW}
									onClick={this.onCopy}
									className={"copyIcon"}
								>
									<ContentCopy style={commonStyles.smallIcon} />
								</IconButton>
							</Popup>
						}
						{canRemove.enabled !== ActionEnabled.NEVER &&
							<Popup
								align="left"
								getContent={this.getRemoveButtonTooltip}
							>
								<IconButton
									disabled={canRemove.enabled === ActionEnabled.NOT_NOW}
									onClick={this.onRemove}
									className={"deleteIcon"}
								>
									<DeleteOutline style={commonStyles.smallIcon} />
								</IconButton>
							</Popup>
						}
					</>
				</div>
				<div style={contentContainerStyle}>
					{showLongDescription &&
						<LongDescription
							id="module_documentation"
							closeDescription={this.toggleLongDescription}
							longDescription={moduleMgr.getLongDescription()}
							canonicalName={moduleMgr.getName()}
							resourceType={ResourceType.CODE}
							disableClose={false}
							resourceLoader={this.props.resourceLoader}
							formatter={this.props.formatter}
							actions={this.props.actions}
						/>
					}
					{!instMgr.isStatic() && !moduleMgr.static.getViewNodes()[0].isHidden() &&
						<CView
							{...rest}
							instMgr={moduleMgr.static}
							actions={this.props.actions}
							productLookupName={moduleMgr.getName()}
							viewNodes={moduleMgr.static.getViewNodes()}
							readOnly={false}
						/>
					}
					<CModuleInstance
						{...rest}
						instMgr={instMgr}
						actions={this.props.actions}
						productLookupName={moduleMgr.getName()}
					/>
				</div>
			</div>
		);
	}

	private toggleLongDescription = () => {
		const instMgr = this.getInstMgr();
		const moduleMgr = instMgr.getModuleMgr();
		const showLongDescription = shouldShowLongDescription(moduleMgr, false);
		this.props.actions.setShowUserLongDescPref(moduleMgr, !showLongDescription);
	}

	private getActionButtonTooltip(type: "copy" | "remove") {
		const { formatter } = this.props;
		const instMgr = this.getInstMgr();
		const canDoAction = "copy" === type ? instMgr.canCopy() : instMgr.canRemove();
		if (canDoAction.enabled !== ActionEnabled.NOT_NOW) {
			return null;
		}
		return <CannotDoActionPopup
			formatter={formatter}
			reason={canDoAction.reason}
			type={type}
		/>;
	}

	private getCopyButtonTooltip = () => {
		return this.getActionButtonTooltip("copy");
	}

	private getRemoveButtonTooltip = () => {
		return this.getActionButtonTooltip("remove");
	}

	private onCopy = () => {
		const { actions, treeNode } = this.props;
		actions.copyInstance(treeNode.getSelectedMyListItem());
	}

	private onRemove = () => {
		const { actions } = this.props;
		actions.removeInstance(this.getInstMgr());
	}

	private getInstMgr() {
		const { treeNode } = this.props;
		const instMgr = treeNode.getSelectedMyListItem();
		if (!instMgr) {
			const asModuleMgr = treeNode as any as ModuleMgr;
			if (asModuleMgr.static && asModuleMgr.getUIAdd() === "staticOnly") {
				return asModuleMgr.static;
			}
		}
		return instMgr;
	}
}
