// Wraps and blocks href, so it can work as regular button

import React = require("react");
import { Tooltip } from "./Tooltip";
import { Link } from "../imports/material-ui-imports";

type IProps
	= Partial<Omit<React.DetailedHTMLProps<React.AnchorHTMLAttributes<HTMLAnchorElement>, HTMLAnchorElement>, "href">>;

export class AnchorButton extends React.PureComponent<IProps, {}> {
	public override render() {

		const { title } = this.props;

		return (
			<Tooltip title={title || ""}>
				<span>{/* wrap in span, If <a> is disabled (via disabling pointer events) we still need a target for tooltip*/}
					<Link
						onClick={this.props.onClick}
						href={void (0)} // This stops click event from propagating and resetting the url
					>{this.props.children}</Link>
				</span>
			</Tooltip>
		);

	}
}
