import * as React from "react";
import * as _ from "lodash";
import { Link } from "../imports/material-ui-imports";
import { openExternalLink } from "../services/externalLink";

// React component to render a clickable link that will open in another tab.  This is a replacement for <a>

export function ExternalLink({ href, children }: React.PropsWithChildren<{ href: string }>) {
	const onClick = React.useCallback(() => openExternalLink(href), [href]);
	return <Link
		component="button"
		display="inline"
		underline="hover"
		variant="body2"
		onClick={onClick}>
		{children}
	</Link>;
}
