import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { typedMemo } from "../../typedMemo";
import { ClassesType } from "../styling/graphStyles";
import { INodeProps } from "../types/nodeTypes";
import { createSvgPathNode } from "./createSvgPathNode";
import { withLayoutAdjustments } from "./withLayoutAdjustments";

// An oscillator node, a circle with a sine-wave symbol inside.

function squareWave(size: number) {

	const min = size * .3;
	const max = size * .7;
	const mid = size / 2;

	// Draw the wave in two parts.  Doing one line messes with the fill

	return `M ${min} ${mid} ` 			// start on the far left
		+ `V ${min} H ${mid} V ${mid} `	// go up, over and down 1/2 way
		+ `M ${max} ${mid} ` 			// move to the far right
		+ `V ${max} H ${mid} V ${mid}`;	// go down, over and up 1/2 way
}

function oscillatorPath(width: number, height: number) {
	return `M 0 ${height / 2} `									// Start at the mid on the far left
		+ `a ${width / 2} ${height / 2} 0 1 1 ${width} 0 `		// Draw one 1/2 of the circle
		+ `a ${width / 2} ${height / 2} 0 1 1 -${width} 0 Z `;	// Now the other half and close it off
	// + squareWave(width);
}

function getXOffset({ height }: Layout.Size, y: number) {
	// We have a circle of radius "height/2" and a y intercept at abs(y-radius).
	// 
	//                        |-------|
	//                            x
	//                        *              ---
	//                     *     *            |
	//              r   *          *          |
	//               *              *         |  abs(y - height/2)
	//            *                  *        |
	//         *                      *       |
	//      *            r            *       |
	//   ******************************      ---
	//   |----------------------------|
	//                height/2        
	//
	// We want to solve for x.  There will be a triangle on the left with hypotenuse being r and height being
	// abs(y - height/2).  We can use the pythagorean theorem to find the width

	const leftWidth = Math.sqrt(Math.pow(height / 2, 2) - Math.pow(y - height / 2, 2));

	// And so the x offset would be the max width minus that value

	return height / 2 - leftWidth;
}

function getOutputXOffset(nodeSize: Layout.Size, y: number) {
	return -getXOffset(nodeSize, y);
}

const OscillatorNodeOutline = createSvgPathNode(oscillatorPath, {
	inputLabelXOffset: getXOffset,
	outputLabelXOffset: getOutputXOffset,
});

const OscillatorNodeWithSquareWave = typedMemo(
	function OscillatorNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
		props: INodeProps<InstMgr, PortMgr> & ClassesType
	) {
		const { node, classes } = props;
		return <OscillatorNodeOutline {...props}>
			<svg className={classes.svgNodeContainer}>
				<path className={classes.edge} d={squareWave(node.width)} />
			</svg>
		</OscillatorNodeOutline>;
	}
);

export const OscillatorNode = withLayoutAdjustments(OscillatorNodeWithSquareWave, {
	outputPortXOffset: getOutputXOffset,
	inputPortXOffset: getXOffset,
});
