import * as React from "react";
import * as _ from "lodash";
import ContainerDimensions, { Dimensions } from "react-container-dimensions";

// This extends the ContainerDimensions library so that the dimensions are not sent to the child immediately when they
// change, and are instead debounced.  This ensures that resizing doesn't render until the user stops dragging the 
// window.  Use this when the underlying component is expensive to re-render on a dimension change.

interface ContainerDimensionsProps {
	children: ((props: Dimensions) => React.ReactElement) | React.ReactElement<Dimensions>;
}

export function DebouncedContainerDimensions({ children }: ContainerDimensionsProps) {
	return (
		<ContainerDimensions>
			{(props: Dimensions) => <DebounceProps {...props}>
				{children}
			</DebounceProps>}
		</ContainerDimensions>
	);
}

function DebounceProps({ children, ...props }: Dimensions & ContainerDimensionsProps) {

	// Create state from the initial props, and update it when it changes using a debounced setter

	const [debouncedProps, setProps] = React.useState(props);
	const deboucedSetProps = React.useMemo(() => _.debounce(setProps, 100), [setProps]);
	if (!_.isEqual(props, debouncedProps)) {
		deboucedSetProps(props);
	}

	// Pass those props onto the children

	if (_.isFunction(children)) {
		return children(debouncedProps);
	}
	return React.Children.only(React.cloneElement(children, debouncedProps));
}
