import * as React from "react";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { TextConfigurableMgr } from "../../../services/objectManagers/configurables/textConfigurableMgr";
import { DebouncedInputBox } from "../../higherOrderComponents/ComposedComponents";
import { MultilineInputBox } from "../../MultilineInputBox";

export function CTextConfigurable({ mgr, actions }: {
	mgr: TextConfigurableMgr;
	actions: IConfigurablesActions;
}) {
	const onChange = React.useCallback((val: string) => actions.setConfigurableValue(mgr, val), [actions, mgr]);
	if (mgr.def.multiline) {
		return <MultilineInputBox
			value={mgr.getValue()}
			type="text"
			placeholder={mgr.def.placeholder}
			id={mgr.def.name}
			onChange={onChange}
			disabled={!!mgr.uiState.readOnly}
		/>;
	} else {
		return <DebouncedInputBox
			value={mgr.getValue()}
			type="text"
			placeholder={mgr.def.placeholder}
			id={mgr.def.name}
			onChange={onChange}
			resyncTrigger={mgr}
			disabled={!!mgr.uiState.readOnly}
		/>;
	}
}
