import React = require("react");
import * as _ from "lodash";
import { commonStyles } from "../../styles/common";
import { Table, TableRow, TableCell, Typography, TableBody, Grid } from "../../../imports/material-ui-imports";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { DeviceViewMgr } from "../../../services/ui/outputView";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { IOutputActions } from "../../actions/IOutputActions";
import { defaultFontSize } from "../../styles/themes";
import { ITreeNode } from "../../TreeNode";
import { redraw, destroy, init } from "../../../services/pinview";
import { SwitchButton } from "../../buttons/SwitchButton";
import { PinInfo } from "../../../services/pinInfo";
import { LegendEntry } from "../../../services/devicePinviews/PinLegend";
import { getPinTypes } from "../../../services/devicePinviews/devicePinTypes";

interface IDeviceViewProps {
	mgr: DeviceViewMgr;
	deviceData: AdaptedDeviceInfo;
	selectedTreeNode: ITreeNode;
	formatter: IFormatter;
	actions: IOutputActions;
}

export class DeviceView extends React.Component<IDeviceViewProps & IGlobalServiceProps> {

	public override render() {

		const numGPIO = this.props.mgr.getNumGPIO();
		const numGPIOLeft = this.props.mgr.getNumGPIOLeft();

		const { packageDescription, showExtendedPinTypes } = this.props.mgr.getDeviceData();

		return (
			<div style={parentDivStyling}>
				<div id="pinDetails" style={pinDetailsStyling}> Place Holder </div>
				<Grid container spacing={10} justify="center">
					<Grid item>
						<div id="deviceView" />
					</Grid>
					<Grid item>
						<div id="legendAndStatusContainer" style={legendStatusDivStyling}>
							<span style={{ marginLeft: defaultFontSize, paddingBottom: 5 }}>
								<SwitchButton
									theme={this.props.theme}
									mgr={this.props.mgr}
									actions={this.props.actions}
								/>
							</span>
							<Table style={legendTableStyling}>
								<TableBody>
									{_.map(getPinTypes(showExtendedPinTypes), (pinType, idx) =>
										<LegendEntry key={idx} pinType={pinType} packageDescription={packageDescription} />
									)}
									{numGPIO > 0 &&
										<TableRow key={"gpioInfo"}>
											<TableCell><Typography>GPIO Used</Typography></TableCell>
											<TableCell><Typography>{numGPIO - numGPIOLeft}/{numGPIO}</Typography></TableCell>
										</TableRow>}
								</TableBody>
							</Table>
						</div>
					</Grid>
				</Grid>
				<div id="deviceViewMargin" style={{ clear: "both" }}></div>
			</div >
		);
	}

	public override componentDidMount() {
		this.updateDeviceViewCanvas();
	}

	public override componentDidUpdate(prevProps: Readonly<IDeviceViewProps & IGlobalServiceProps>) {
		if (prevProps.deviceData === this.props.deviceData && prevProps.theme === this.props.theme) {
			const { mgr, theme, formatter } = this.props;
			redraw(
				this.getPinInfo(),
				formatter,
				this.getSelectedPins(),
				mgr.getDevicePinSolutionMap(),
				theme.colors[4]);
		} else {
			destroy();
			this.updateDeviceViewCanvas();
		}
	}

	public override componentWillUnmount() {
		destroy();
	}

	private updateDeviceViewCanvas() {
		const { mgr, actions, theme, formatter } = this.props;
		init(
			this.getPinInfo(),
			mgr.getDeviceData(),
			mgr.getDevicePinSolutionMap(),
			this.getSelectedPins(),
			formatter,
			mgr.shouldShowModeTable(),
			actions,
			theme);
	}

	private getPinInfo() {
		const { mgr, actions, formatter, selectedTreeNode } = this.props;
		return new PinInfo(
			mgr.getDeviceData(),
			mgr.getDevicePinSolutionMap(),
			this.getSelectedPins(),
			formatter,
			selectedTreeNode,
			actions,
		);
	}

	private getSelectedPins() {
		return this.props.selectedTreeNode.getUsedPins();
	}
}

const pinDetailsStyling: React.CSSProperties = { ...commonStyles.popupStyle, display: "none", top: "-5px" };
const parentDivStyling: React.CSSProperties = { overflow: "hidden", paddingBottom: 20 };
const legendStatusDivStyling: React.CSSProperties = { textAlign: "center" };
const legendTableStyling: React.CSSProperties = { marginTop: 10 };
