import { isWin, isCCS, getProcess, isCloud } from "./platform";
import { fs } from "./fileSystem";
import * as path from "path";
import * as _ from "lodash";

export type EclipseEnv = typeof eclipseEnv;

// App data dir - writable directory to store application specific data
// Project data dir - writable directory to store project level application specific data

const appName = "TI_pinmux";

export class EclipseFSUtils {
	constructor(private env: EclipseEnv) {
	}

	public getTempProjectFilePath(filePath: string) {
		return path.join(this.env.CCS_PROJECT_TEMP_DIR || "", filePath);
	}

	public getAppDataDir() {
		return this.env.CCS_WORKSPACE_TEMP_DIR || "";
	}
}

export class NodeFSUtils {
	constructor(
		private env: NodeJS.ProcessEnv) {
	}

	public getTempProjectFilePath(filePath: string) {
		return path.join(this.getAppDataDir(), filePath);
	}

	public getAppDataDir() {
		let rootDir = isWin() ? (this.env.LOCALAPPDATA || this.env.USERPROFILE) : this.env.HOME;
		rootDir = rootDir || "";

		const appDir = path.join(rootDir, appName);
		if (!fs.fileExists(appDir)) {
			fs.mkdir(appDir, { recursive: true });
		}

		return appDir;
	}
}

// For use on cloud, these functions are just placeholders.
// These functions are called in common locations, but aren't really used
// in the cloud case.
class NullFSUtils {
	public getTempProjectFilePath(_filePath: string) {
		return "";
	}

	public getAppDataDir() {
		return "";
	}
}

export const fsUtils
	= isCCS() ? new EclipseFSUtils(eclipseEnv) : (isCloud() ? new NullFSUtils() : new NodeFSUtils(getProcess().env));
