import Heap = require("heap");
import { Grid } from "./grid";
import { backtrace, Node } from "./node";
import { manhattan, Point } from "./util";

const weight = 1; // heuristic weight
const heuristic = manhattan;

/**
 * A* path-finder. Based upon https://github.com/bgrins/javascript-astar
 * @constructor
 * @param {Object} opt
 * @param {boolean} opt.allowDiagonal Whether diagonal movement is allowed.
 *     Deprecated, use diagonalMovement instead.
 * @param {boolean} opt.dontCrossCorners Disallow diagonal movement touching 
 *     block corners. Deprecated, use diagonalMovement instead.
 * @param {DiagonalMovement} opt.diagonalMovement Allowed diagonal movement.
 * @param {function} opt.heuristic Heuristic function to estimate the distance
 *     (defaults to manhattan).
 * @param {number} opt.weight Weight to apply to the heuristic to allow for
 *     suboptimal paths, in order to speed up the search.
 */
/**
 * Find and return the the path.
 * @return {Array<Array<number>>} The path, including both start and
 *     end positions.
 */
export function aStarFinder([startX, startY]: Point, [endX, endY]: Point, grid: Grid): Point[] {

	const tieBreaker = getTieBreaker(startX, startY, endX, endY);
	const openList = new Heap((nodeA: Node, nodeB: Node) =>
		nodeA.estimatedTotalCost - nodeB.estimatedTotalCost || tieBreaker(nodeA, nodeB));
	const startNode = grid.getNodeAt(startX, startY),
		endNode = grid.getNodeAt(endX, endY),
		abs = Math.abs;
	let node, neighbors, neighbor, i, l, x, y, nextCostToReachNode;

	// set the `g` and `f` value of the start node to be 0
	startNode.costToReachNode = 0;
	startNode.estimatedTotalCost = 0;

	// push the start node into the open list
	openList.push(startNode);
	startNode.opened = true;

	// while the open list is not empty
	while (!openList.empty()) {
		// pop the position of node which has the minimum `f` value.
		node = openList.pop();
		node.closed = true;

		// if reached the end position, construct the path and return it
		if (node === endNode) {
			return backtrace(endNode);
		}

		// get neighbours of the current node
		neighbors = grid.getNeighbors(node);
		for (i = 0, l = neighbors.length; i < l; ++i) {
			neighbor = neighbors[i];

			if (neighbor.closed) {
				continue;
			}

			x = neighbor.x;
			y = neighbor.y;

			// get the distance between current node and the neighbor
			// and calculate the next g score
			// A grid means that we can always infer the cost is 1
			// ng = node.costToReachNode + ((x - node.x === 0 || y - node.y === 0) ? 1 : SQRT2);
			nextCostToReachNode = node.costToReachNode + 1;

			// check if the neighbor has not been inspected yet, or
			// can be reached with smaller cost from the current node
			if (!neighbor.opened || nextCostToReachNode < neighbor.costToReachNode) {
				neighbor.costToReachNode = nextCostToReachNode;
				neighbor.estimatedCostToGoal = neighbor.estimatedCostToGoal || weight * heuristic(abs(x - endX), abs(y - endY));
				neighbor.estimatedTotalCost = neighbor.costToReachNode + neighbor.estimatedCostToGoal;
				neighbor.parent = node;

				if (!neighbor.opened) {
					openList.push(neighbor);
					neighbor.opened = true;
				} else {
					// the neighbor can be reached with smaller cost.
					// Since its f value has been updated, we have to
					// update its position in the open list
					openList.updateItem(neighbor);
				}
			}
		} // end for each neighbor
	} // end while not open list empty

	// fail to find the path
	return [];
}

// TI specific functionality change
//
// The tiebreaker is called if the estimated total cost of two nodes are the same.  It's designed to prefer horizontal
// neighbours until the half way point, and then prefer vertical neighbours.  That preference, in a grid environment 
// with equal edge traversal cost, will generate two horizontal lines at either end with a vertical line in the middle.
// That is the general layout that schematic diagrams tend to draw, so that's why we are using it.
//
// Note that if we eventually allow ports on the top/bottom, we will likely need to adjust this function

function getTieBreaker(startX: number, startY: number, endX: number, endY: number) {
	return function tieBreaker(nodeA: Node, nodeB: Node) {
		if (Math.abs(startX - nodeA.x) > Math.abs(nodeA.x - endX) ||
			Math.abs(startX - nodeB.x) > Math.abs(nodeB.x - endX)) {

			// After the mid-way point - prefer to go up-down

			return nodeA.x - nodeB.x
				|| (startY < endY ? nodeA.y - nodeB.y : nodeB.y - nodeA.y);
		}

		// Before the mid-way point - prefer to go across

		return (startY < endY ? nodeA.y - nodeB.y : nodeB.y - nodeA.y)
			|| nodeA.x - nodeB.x;
	};
}
