import * as _ from "lodash";
export abstract class InputFormatter {
	constructor(
		public readonly numOfParts: number, // The number of parts divided by the delimiter. I.e. 192.168.0.1 is 4
		public readonly delimiter: string, // The delimiter character. I.e. 192.168.0.1 is "."
		private readonly legalCharset: RegExp, // Regex for checking each individual parts, not including the delimiter.
		public readonly maxLengthOfPart: number, // The maximum character length of each part. 
		public readonly formatName: string, // Name of the format
	) {
	}
	// Check if the character is a legal character
	public verifyLegalCharsetOfPart(part: string) {
		return part === "" || this.legalCharset.test(part);
	}
	// Check if the string value is legal
	public verifyNumericValueOfPart(_part: string) {
		return true;
	}
	// Check if the whole string is legal
	public verifyEntireString(str: string) {
		const splitted = _.split(str, this.delimiter);
		return splitted.length === this.numOfParts &&
			_.every(splitted, (part) => {
				return part.length <= this.maxLengthOfPart
					&& _.every(part, (char) => this.verifyLegalCharsetOfPart(char))
					&& this.verifyNumericValueOfPart(part);
			});
	}
	// Format each individual parts divided by the delimiter
	public formatPartOfString(part: string) {
		return part;
	}
	// Format the entire string
	public formatEntireString(str: string) {
		return _.chain(str)
			.split(this.delimiter)
			.map((part) => this.formatPartOfString(part))
			.join(this.delimiter)
			.value();
	}

	public noPartIsEmpty(str: string) {
		const splitted = _.split(str, this.delimiter);
		return _.every(splitted, (part) => {
			return part !== "";
		});
	}
}

export class IPv4InputFormatter extends InputFormatter {
	constructor() {
		super(4, ".", new RegExp("[0-9]"), 3, "IPv4 address");
	}
	public override verifyNumericValueOfPart(part: string) {
		if (part === "") {
			return true;
		}
		// isNAN works on number and + sign casts the input into a number
		if (isNaN(+part)) {
			return false;
		}
		if (Number(part) > 255 || Number(part) < 0) {
			return false;
		}
		return true;
	}

	public override formatPartOfString(part: string) {
		if (part === "") {
			return "";
		}
		return Number(part).toString(10);
	}
}

export class MACInputFormatter extends InputFormatter {
	constructor(bitSize: number) {
		super(Math.ceil(bitSize / 8), ":", new RegExp("[0-9a-fA-F]"), 2, "MAC address");
	}
	public override formatPartOfString(part: string) {
		if (part === "") {
			return "";
		}
		// Pad the numbers with 0s until two characters 
		part = "00" + part;
		return part.slice(-2);
	}
}
