import * as _ from "lodash";
import * as path from "path";
import * as marked from "marked";
import { isCloud } from "./platform";
import { ResourceLoader, ResourceType } from "./resources/metaContentLoaders/resourceLoader";
import { resolveRelativePathToProduct } from "./utils";
import { openExternalLink } from "./externalLink";
import { IFormatter } from "./formatting/formattingTypes";
import { isFormattedLink, FormattedLink } from "./formatting/link";
import { ILinkActions } from "../components/actions/ILinkActions";

// These are the properties needed in order to render links to to internal content properly

export interface MarkdownRenderProps {
	resourceLoader?: ResourceLoader;
	canonicalName?: string;
	resourceType?: ResourceType;
	formatter: IFormatter;
	actions: ILinkActions;
	linkClass?: string
	productPath?: string;
	documentationPath?: string;
}

class TiMarkdownRenderer extends marked.Renderer {

	private documentationBasePath: string = null;
	private allowHTML = false;
	private linkClass?: string;

	constructor({ resourceLoader, canonicalName, resourceType, linkClass, productPath, documentationPath }: MarkdownRenderProps) {
		super();

		this.linkClass = linkClass;

		if (productPath && documentationPath) {
			this.documentationBasePath = resolveRelativePathToProduct(productPath, documentationPath);
		}

		else if (canonicalName && !_.isUndefined(resourceType) && resourceLoader) {
			const product = resourceLoader.getProduct(canonicalName, resourceType);
			if (product.file.documentationPath) {
				this.documentationBasePath = resolveRelativePathToProduct(product.file.path, product.file.documentationPath);
			}
			this.allowHTML = product.file.name === "K3-Respart-Tool";
		}
	}

	// For testing only
	public _getDocumentationBasePath() {
		return this.documentationBasePath;
	}

	// All headings are treated as normal paragraphs
	public override heading(text: string) {
		return `<p>${text}</p>`;
	}

	// blockquote becomes normal paragraph
	public override blockquote(quote: string) {
		return `<p>${quote}</p>`;
	}

	// All htmls are removed completely for safety
	public override html(html: string): string {
		if (this.allowHTML) {
			return html;
		} else {
			return "<p>$$$$ommitted_html$$$$</p>";
		}
	}

	// Tables have borders added
	public override table(header: string, body: string) {
		return `<table border="1"><thead>${header}</thead><tbody>${body}</tbody></table>`;
	}

	// process the image link
	public override image(href: string, title: string, text: string) {
		const titleParam = title ? ` title="${title}"` : "";
		const altTextParam = text ? ` alt="${text}"` : "";
		return `<img src="${this.processLink(href)}"${titleParam}${altTextParam}>`;
	}

	// Add custom click handler for opening links
	public override link(href: string, title: string, text: string) {
		const props = {
			href: this.processLink(href),
			title: title,
			class: this.linkClass,
			onclick: "return tiMarkdownClickLinkHandler(this);",
		};
		const attributes = _.chain(props)
			.map((value, key) => value ? `${key}="${value}"` : null)
			.compact()
			.join(" ")
			.value();
		const altTextParam = text || "";
		return `<a ${attributes}>${altTextParam}</a>`;
	}

	private processLink(href: string) {
		let link;
		if (_.isEmpty(href)) {
			link = "";
		} else if (_.includes(href, "://")) {
			// URL, just return the full encoded URL string (replaces circle brackets)
			link = encodeURI(href);
			link = link.replace(/\(/g, "%28");
			link = link.replace(/\)/g, "%29");
		} else if (!this.documentationBasePath) {
			throw new Error("Markdown contained a relative link but the documentationPath was not defined in product.json");
		} else if (isFormattedLink(formatter(href).toParts()[0])) {
			return "internalnavlink://" + href;
		}
		else {
			// local documentation file link
			// product path + documentation relative path + documentation filename
			link = path.join(this.documentationBasePath, href);
			if (!isCloud()) {
				// nw and eclipse needs to read from local directory
				link = "file:\\\\\\" + link;
			}
		}
		return link;
	}
}
let actions: ILinkActions;
let formatter: IFormatter;

export function markdownToHtml(markdownText: string, renderProps: MarkdownRenderProps) {
	formatter = renderProps.formatter;
	actions = renderProps.actions;
	return marked(markdownText, { renderer: new TiMarkdownRenderer(renderProps) });
}

// For testing only

export function _getDocumentationBasePath(renderProps: MarkdownRenderProps) {
	const renderer = new TiMarkdownRenderer(renderProps);
	return renderer._getDocumentationBasePath();
}

if (typeof window !== "undefined") {
	// given a properly formatted raw html link
	// determine how to show the documentation in the current environment (Node, Eclipse, Cloud)
	function tiMarkdownClickLinkHandler(rawLink: HTMLLinkElement) {
		const link = rawLink.href;
		if (link.includes("internalnavlink://")) {
			const formattedLink = formatter(link.substring(link.indexOf("@"))).toParts()[0] as FormattedLink;
			formattedLink.linkAction(actions);
		} else {
			openExternalLink(link);
		}
		return false;
	}

	// inject link handler
	(window as any).tiMarkdownClickLinkHandler = tiMarkdownClickLinkHandler;
}
