import * as _ from "lodash";
import React = require("react");
import { HardwareComponentMgr } from "../services/instanceContainers/hardwareComponent";
import { ConfigStoreActions } from "../services/configStore";
import { Menu, MenuList, MenuItem } from "../imports/material-ui-imports";
import { commonStyles } from "./styles/common";
import { ButtonType, createButton } from "./ComponentUtils";
import { Tooltip } from "./Tooltip";

interface IProps {
	treeNode: HardwareComponentMgr;
	actions: ConfigStoreActions;
	displayScriptName: boolean;
	type?: ButtonType;
}

interface IState {
	anchorEl: HTMLElement;	// stores where the menu should be opened
	menuOpened: boolean;	// show/hide menu
}

export class AttachDetachSoftwareButton extends React.Component<IProps, IState> {

	public constructor(props: IProps) {
		super(props);
		this.state = {
			anchorEl: null,
			menuOpened: false,
		};
	}

	public override render() {

		const { treeNode: hwComponentMgr, actions, displayScriptName, type } = this.props;
		const attachButtonInfo = hwComponentMgr.getAttachButtonInfo();
		const detachButtonInfo = hwComponentMgr.getDetachButtonInfo();

		if (attachButtonInfo.show()) {

			const mainButton = createButton(attachButtonInfo, this.handleAttachButtonClick, type);

			const menu = (
				<Menu
					key={`${attachButtonInfo.getID()}Menu`}
					id={`${attachButtonInfo.getID()}Menu`}
					anchorEl={this.state.anchorEl}
					open={this.state.menuOpened}
					onClose={() => this.setState({ menuOpened: false })}
				>
					<MenuList style={commonStyles.noOutline}>
						{
							_.map(attachButtonInfo.getMenuChoices(), (choice) => {
								return (
									<Tooltip
										title={choice.getModuleMgr().getModuleCategory()}
										key={choice.getText(false)}
										placement="right"
									>
										<MenuItem
											onClick={() => {
												actions.addModuleToHardware(hwComponentMgr, choice.getModuleMgr());
												this.setState({ menuOpened: false });
											}}
											id={choice.getText(true) + "MenuItem"}
											disabled={choice.isDisabled()}
										>
											{choice.getText(displayScriptName)}
										</MenuItem>
									</Tooltip>
								);
							})
						}
					</MenuList>
				</Menu>
			);

			return [
				mainButton,
				this.state.menuOpened ? menu : null,
			];
		} else if (detachButtonInfo.show()) {
			return createButton(detachButtonInfo, this.handleDetachButtonClick, type);
		}

		return null;

	}

	private handleAttachButtonClick = (event: React.MouseEvent<HTMLElement>) => {

		const hwComponentMgr = this.props.treeNode;
		const buttonInfo = hwComponentMgr.getAttachButtonInfo();
		const actions = this.props.actions;

		if (_.size(buttonInfo.getMenuChoices()) === 1) {
			actions.addModuleToHardware(hwComponentMgr, hwComponentMgr.getSupportedModules()[0]);
		} else {
			this.setState({
				menuOpened: true,
				anchorEl: event.currentTarget,
			});
		}
	}

	private handleDetachButtonClick = () => {
		const hwComponentMgr = this.props.treeNode;
		const actions = this.props.actions;
		actions.removeAllModulesFromHardware(hwComponentMgr);
	}
}
