import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../graph/types/layoutTypes";
import { assertNeverThrows, memoizeResult } from "../../services/utils";
import { GraphView, INonGraphProps } from "../graph/GraphView";
import { getLayout, getPoint } from "./layout/layout";
import { canMemoize, nodeFactory } from "./nodes/NodeFactory";
import { GraphableModuleMgr } from "../../services/instanceContainers/graphableModuleMgr";
import { ModuleInstanceMgr } from "../../services/objectManagers/moduleInstance";
import { PositionMemberMgr } from "../../services/objectManagers/positionMemberMgr";
import { SetSource } from "../../services/objectManagers/member";
import { PortMemberMgr } from "../../services/objectManagers/portMemberMgr";
import { Position } from "public/runtime";
import { autoArrange } from "./layout/autoArrange";
import { UserGraphAction } from "../graph/types/IGraphProps";
import {
	ConnectingMode,
	CursorMode,
	CursorModeType,
	isConnectingMode,
	isProbingMode,
	startedClickConnecting,
	startedDragConnecting,
} from "../graph/CursorMode";
import { ActionEnabled } from "../../services/IMyListItem";
import { isUnderTest } from "../../services/platform";

interface IProps extends INonGraphProps {
	treeNode: GraphableModuleMgr;
}

interface IState {
	// The node being dragged

	dragging: ModuleInstanceMgr;

	// When dragging, this is the original position of the node

	originalPosition: Position;

	// If connecting, this is the current mouse position.  If dragging, this is the initial mouse offset within the 
	// node such that the node can be re-positioned with respect to subsequent mouse events

	offset: Position;

	// When dragging this is the bounding box in which the node can be moved
	// This prevents nodes from being moved too far from the other nodes, which can cause significant computational load on the routing algo

	bounds: { top: number, left: number, bottom: number, right: number };

	// The targets of an edge that is highlighted or selected

	highlighedEdgeTargets: PortMemberMgr[];
	selectedEdgeTargets: PortMemberMgr[];

	// The currently selected node that should be deleted if the delete key is pressed.  Note that if the user clicks
	// away from this node, it will still "look" selected in the graph and still be the focus of the underlying 
	// configurables, but it will not respond to "delete" key presses

	selectedNode: ModuleInstanceMgr;

	// Can be incremented to force a re-render should we want to force a re-center of the graph

	key: number;

	cursorMode: CursorMode;
}

export class GraphableModulesView extends React.Component<IProps, IState> {
	public override state: IState = {
		dragging: null,
		bounds: null,
		originalPosition: [0, 0],
		offset: [0, 0],
		selectedNode: null,
		highlighedEdgeTargets: [],
		selectedEdgeTargets: null,
		key: 0,
		cursorMode: { mode: CursorModeType.Connecting, dragConnecting: null, clickConnecting: null },
	};
	// If the test value is changed, the tests in graphableModules-spec must be adjusted
	private MAX_DRAG_DISTANCE = isUnderTest() ? 200 : 1000;

	public override render() {
		const { treeNode } = this.props;
		const layout = this.getLayout();
		const highlightedEdges = _.filter(layout.edges, (e) => _.some(this.state.highlighedEdgeTargets, (t) => _.includes(e.targets, t)));
		const selectedEdges = _.filter(layout.edges, (e) => _.some(this.state.selectedEdgeTargets, (t) => _.includes(e.targets, t)));
		return <GraphView
			{...this.props}
			key={this.state.key}
			layout={layout}
			nodeFactory={nodeFactory}
			canMemoize={canMemoize}
			usedInstances={getUsedInstances(treeNode)}
			disabledInstances={[]}
			onClickNode={null}
			onMouseDownNode={this.onMouseDownNode}
			onMouseDownPort={this.onMouseDownPort}
			onClickPort={this.onClickPort}
			onMouseMove={this.onMouseMove}
			onMouseUp={this.onMouseup}
			onMouseEnterEdge={this.onMouseEnterEdge}
			onMouseLeaveEdge={this.onMouseLeaveEdge}
			onClickEdge={this.onClickEdge}
			getEdgeToolTip={this.getEdgeToolTip}
			onAutoArrange={this.onAutoArrange}
			onClickAway={this.onClickAway}
			highlightedEdges={highlightedEdges}
			selectedEdges={selectedEdges}
			userAction={this.getUserAction()}
			setCursorMode={this.setCursorMode}
			cursorMode={this.state.cursorMode}
		/>;
	}

	// We need to listen for the delete key being pressed, and then either remove a node or a connection

	public override componentDidMount() {
		document.addEventListener("keydown", this.handleKeydown, false);
		this.leftPaneSelected();
	}

	public override componentWillUnmount() {
		document.removeEventListener("keydown", this.handleKeydown);
	}

	public override componentDidUpdate(prevProps: Readonly<IProps>) {
		if (this.props.treeNode !== prevProps.treeNode) {
			this.leftPaneSelected();
		}
	}

	private getUserAction() {
		const cursorMode = this.state.cursorMode;
		if (isConnectingMode(cursorMode) && (startedDragConnecting(cursorMode) && startedClickConnecting(cursorMode))) {
			return UserGraphAction.CONNECTING;
		}
		else if (this.state.dragging) {
			return UserGraphAction.DRAGGING;
		}
		return UserGraphAction.NONE;
	}

	// Whenever something in the left pane is selected, make sure there is a selection if there is anything that could be
	// selected.

	private leftPaneSelected() {
		if (!this.props.treeNode.getSelectedMyListItem()) {
			const instances = this.props.treeNode.getInstances();
			if (!_.isEmpty(instances)) {
				this.props.actions.setSelectedMyListItem(this.props.treeNode, _.first(instances));
			}
		}
	}

	private handleKeydown = (event: KeyboardEvent) => {
		if (event.key === "Delete") {
			if (this.state.selectedEdgeTargets) {
				_.each(this.state.selectedEdgeTargets, (port) => {
					this.props.actions.disconnect(port, _.first(port.getPortConnections()).port);
				});
				this.setState({ selectedEdgeTargets: [] });
			} else if (this.state.selectedNode?.canRemove().enabled === ActionEnabled.YES) {
				this.props.actions.removeInstance(this.state.selectedNode);
				this.setState({ selectedNode: null });
			}
		}
	}

	// A mouse down event on a node begins a drag operation.  On a port begins a connect operation.  In both cases we
	// need to save the thing being operated on in order to handle subsequent mouse move/up events.
	// When the event is for a node, we also select it.  That way it's selected during the drag vs the end of the drag,
	// plus it means we don't need a click event as well.

	private onMouseDownNode = (mousePosition: Position, node: ModuleInstanceMgr,) => {
		this.props.actions.setSelectedMyListItem(node.getModuleMgr(), node);
		const originalPosition = (node.memberMgrs.$position as PositionMemberMgr).getValue();
		this.setState({
			dragging: node,
			offset: subtractPositions(originalPosition, mousePosition),
			originalPosition,
			bounds: this.computeDraggingBounds(node),
			selectedEdgeTargets: null,
			selectedNode: node,
		});
	};

	private onMouseDownPort = (position: Position, port: PortMemberMgr,) => {
		if (isConnectingMode(this.state.cursorMode) && !startedDragConnecting(this.state.cursorMode)) {
			const cursorMode = { ...this.state.cursorMode, dragConnecting: port };
			this.setState({ cursorMode, offset: position });
		}
	}

	private toggleProbe(port: PortMemberMgr) {
		if (!port || !isProbingMode(this.state.cursorMode) || !port.probeTypeIsPermitted(this.state.cursorMode.probingMode)) {
			return;
		}

		if (port.hasProbe(this.state.cursorMode.probingMode)) {
			this.props.actions.removeProbe(port, this.state.cursorMode.probingMode);
		} else {
			this.props.actions.addProbe(port, this.state.cursorMode.probingMode);
		}
	}

	private onClickPort = (position: Position, port: PortMemberMgr) => {
		if (isProbingMode(this.state.cursorMode)) {
			this.toggleProbe(port);
		} else if (isConnectingMode(this.state.cursorMode) && !startedClickConnecting(this.state.cursorMode)) {
			const cursorMode: ConnectingMode = { mode: CursorModeType.Connecting, clickConnecting: port, dragConnecting: null };
			this.setState({ cursorMode, offset: position });
		} else if (isConnectingMode(this.state.cursorMode)) {
			// User has not started connecting two ports by clicking 
			if (port) {
				const source = this.state.cursorMode.clickConnecting;
				this.props.actions.connect(source, port);
			}
			const cursorMode: ConnectingMode = { ...this.state.cursorMode, clickConnecting: null };
			this.setState({ cursorMode });
		}
	}

	private setCursorMode = (cursorMode: CursorMode) => {
		if (cursorMode) {
			this.setState({ cursorMode });
		} else {
			this.setToDefaultCursorMode();
		}
	}

	private setToDefaultCursorMode() {
		const defaultCursorMode: ConnectingMode = {
			mode: CursorModeType.Connecting,
			clickConnecting: null,
			dragConnecting: null,
		};
		this.setState({ cursorMode: defaultCursorMode });
	}

	// Connecting we can just update the position so the new connection line appears from the original port and 
	// connects out to the mouse location.  If dragging, we don't update position but the embedded position of the node
	// so that it's re-drawn on the next render at the new mouse location

	private onMouseMove = (position: Position) => {
		if (isConnectingMode(this.state.cursorMode) &&
			(startedDragConnecting(this.state.cursorMode) || startedClickConnecting(this.state.cursorMode))) {
			this.setState({ offset: position });
		} else if (this.state.dragging) {
			this.state.dragging.memberMgrs.$position
				.set(this.clampPosition(sumPositions(position, this.state.offset)), SetSource.USER_ASSIGN);
			this.forceUpdate();
		}
	}

	// A mouse up over top of another port will include that port in the callback.  We can then connect the original 
	// port to this one.  If not over a port, we just end the connecting operation.
	// A mouse up while dragging, over a port or not, simply finishes the drag operation and locks in the move

	private onMouseup = (position: Position, port?: PortMemberMgr) => {
		if (isConnectingMode(this.state.cursorMode) && startedDragConnecting(this.state.cursorMode)) {
			if (port) {
				const source = this.state.cursorMode.dragConnecting;
				this.props.actions.connect(source, port);
			}
			this.setState({ cursorMode: { ...this.state.cursorMode, dragConnecting: null } });
		} else if (this.state.dragging) {
			const newPosition = sumPositions(position, this.state.offset);
			if (!_.isEqual(newPosition, this.state.originalPosition)) {
				this.props.actions.move(this.state.dragging, this.clampPosition(sumPositions(position, this.state.offset)));
			}
			this.setState({ bounds: null, dragging: null });
		}
	}

	private onMouseEnterEdge = (edge: Layout.Edge<PortMemberMgr>) => {
		this.setState({ highlighedEdgeTargets: edge.targets });
	};

	private onMouseLeaveEdge = () => {
		this.setState({ highlighedEdgeTargets: null });
	};

	private onClickEdge = (edge: Layout.Edge<PortMemberMgr>) => {
		this.setState({ selectedEdgeTargets: edge.targets, selectedNode: null });
	};

	private getEdgeToolTip = (_edge: Layout.Edge<PortMemberMgr>) => ""; // No tooltip yet

	// Get the layout, but if we're actively connecting then include a line from the port being connected to the 
	// current mouse position

	private getLayout() {

		// Uncomment the following to auto-arrange on every render (useful for exploring differences in elk options)
		// if (this.props.treeNode.getNodesInGraph()[0].memberMgrs.autoArrange.getValue()) {
		// 	this.onAutoArrange();
		// }

		const layout = getLayout(this.props.treeNode.getNodesInGraph());
		const cursorMode = this.state.cursorMode;
		const currentPosition = isConnectingMode(cursorMode) ? cursorMode.dragConnecting ?? cursorMode.clickConnecting : null;
		if (currentPosition) {
			layout.edges.push({
				id: "$connecting",
				start: getPoint(currentPosition),
				end: { x: this.state.offset[0], y: this.state.offset[1] },
				source: currentPosition,
				targets: [],
			});
		}
		return layout;
	}

	private computeDraggingBounds(draggedNode: ModuleInstanceMgr) {
		const nodeId = draggedNode.getID();
		const nodes = this.props.treeNode.getNodesInGraph();
		const nodesFiltered = _.filter(nodes, (mod) => mod.getID() !== nodeId);
		const nodeWithId = _.find(nodes, (mod) => mod.getID() === nodeId);
		const nodeWithIdLocation = (nodeWithId.memberMgrs.$position as PositionMemberMgr).getValue();

		const topNode = _.minBy(nodesFiltered, (node) => (node.memberMgrs.$position as PositionMemberMgr).getValue()[1]);
		const top = topNode ? (topNode.memberMgrs.$position as PositionMemberMgr).getValue()[1] : Number.NEGATIVE_INFINITY;
		const leftNode = _.minBy(nodesFiltered, (node) => (node.memberMgrs.$position as PositionMemberMgr).getValue()[0]);
		const left = leftNode ? (leftNode.memberMgrs.$position as PositionMemberMgr).getValue()[0] : Number.NEGATIVE_INFINITY;
		const bottomNode = _.maxBy(nodesFiltered, (node) => (node.memberMgrs.$position as PositionMemberMgr).getValue()[1]);
		const bottom = bottomNode ? (bottomNode.memberMgrs.$position as PositionMemberMgr).getValue()[1] : Number.POSITIVE_INFINITY;
		const rightNode = _.maxBy(nodesFiltered, (node) => (node.memberMgrs.$position as PositionMemberMgr).getValue()[0]);
		const right = rightNode ? (rightNode.memberMgrs.$position as PositionMemberMgr).getValue()[0] : Number.POSITIVE_INFINITY;

		return {
			top: Math.min(top - this.MAX_DRAG_DISTANCE, nodeWithIdLocation[1]),
			left: Math.min(left - this.MAX_DRAG_DISTANCE, nodeWithIdLocation[0]),
			bottom: Math.max(bottom + this.MAX_DRAG_DISTANCE, nodeWithIdLocation[1]),
			right: Math.max(right + this.MAX_DRAG_DISTANCE, nodeWithIdLocation[0]),
		};
	}

	private clampPosition(position: Position): Position {
		return [
			_.clamp(position[0], this.state.bounds.left, this.state.bounds.right),
			_.clamp(position[1], this.state.bounds.top, this.state.bounds.bottom),
		];
	}

	private onAutoArrange = () => {
		assertNeverThrows(this.props.errorStore, async () => {
			const { nodes, positions } = await autoArrange(this.props.treeNode.getNodesInGraph());
			if (this.props.actions.autoArrange(nodes, positions)) {
				this.setState({ key: this.state.key + 1 });
			}
		});
	}

	private onClickAway = () => {
		if (this.state.selectedEdgeTargets || this.state.selectedNode) {
			this.setState({ selectedEdgeTargets: null, selectedNode: null });
		}
	}
}

const getUsedInstances = memoizeResult((treeNode: GraphableModuleMgr) =>
	_.map(treeNode.getNodesInGraph(), (i) => i.getID()));

function sumPositions(a: Position, b: Position): Position {
	return [a[0] + b[0], a[1] + b[1]];
}

function subtractPositions(a: Position, b: Position): Position {
	return [a[0] - b[0], a[1] - b[1]];
}
