import * as _ from "lodash";
import { IUserPreferenceActions } from "../components/actions/IUserPreferenceActions";
import { isCCS, isEmbedded, isUnderTest } from "./platform";
import { assertNeverThrows } from "./utils";
import { ErrorStore } from "./errorStore";
import { Settings } from "./settings";
import { ATheme, darkTheme, defaultTheme } from "../components/styles/themes";

interface AnySelectOption<T extends number> {
	id: T;
	optionText: string;
	description: string;
}

export const enum PinDisplayType {
	DEVICENAME = 0,
	DEVICENUM,
	HEADERNAME,
	HEADERNUM,
}

export const enum EditorDiffType {
	NODIFF = 0,
	INLINE,
	SIDEBYSIDE,
}

export const enum PreferenceType {
	Switch,
	MULTISELECT,
	SELECT,
}

interface IPreference {
	type: PreferenceType;
	description: string;
	requireBoard?: boolean;
	save: () => void;
	load: () => void;
}

export class SelectPreference<OptionType extends number> implements IPreference {
	public readonly type = PreferenceType.SELECT;
	private selected: OptionType;

	constructor(
		private readonly name: string,
		public readonly description: string,
		private readonly optionsList: AnySelectOption<OptionType>[],
		public readonly requireBoard: boolean = false,
		private readonly defaultOptionID: OptionType,
		private readonly settings: Settings,
		private readonly errorStore: ErrorStore,
	) {
		this.selected = this.defaultOptionID;
	}

	public save() {
		assertNeverThrows(this.errorStore, this.settings.setUserPreference(this.name, this.selected));
	}

	public load() {
		const id = this.settings.getUserPreference<OptionType>(this.name);
		if (!_.isUndefined(id)) {
			this.selected = id;
		}
	}

	public setValue(id: OptionType) {
		if (!_.isUndefined(id)) {
			this.selected = id;
		}
	}

	// return the option objects that are selected and also satisfy board condition
	public getSelectedOption() {
		return this.selected;
	}

	public getAllSelectableOptions() {
		return this.optionsList;
	}

	public getDefaultOptionID() {
		return this.defaultOptionID;
	}
}

export class MultiSelectPreference<OptionType extends number> implements IPreference {
	public readonly type = PreferenceType.MULTISELECT;
	private selected: OptionType[];

	constructor(
		private readonly name: string,
		public readonly description: string,
		private readonly optionsList: AnySelectOption<OptionType>[],
		public readonly requireBoard: boolean = false,
		private readonly defaultOptionIDs: OptionType[],
		private readonly settings: Settings,
		private readonly errorStore: ErrorStore,
	) {
		this.selected = _.sortBy(this.defaultOptionIDs);
	}

	public save() {
		assertNeverThrows(this.errorStore, this.settings.setUserPreference(this.name, this.selected));
	}

	public load() {
		const ids = this.settings.getUserPreference<OptionType[]>(this.name);
		if (!_.isUndefined(ids)) {
			this.selected = _.sortBy(ids);
		}
	}

	public setValue(ids: OptionType[]) {
		if (!_.isUndefined(ids)) {
			this.selected = _.sortBy(ids);
		}
	}

	// returns the enums the selected options represent
	// Note: It's important that this isn't transformed as react will compare the array using === when deciding if it
	// should perform an update or not
	public getSelectedEnums() {
		return this.selected;
	}

	public getAllSelectableOptions() {
		return this.optionsList;
	}

	public getDefaultOptionIDs() {
		return this.defaultOptionIDs;
	}
}

export class SwitchPreference implements IPreference {
	public readonly type = PreferenceType.Switch;

	constructor(
		public readonly name: string,
		public readonly description: string,
		public value: boolean,
		private readonly settings: Settings,
		public readonly requireBoard: boolean,
		private readonly errorStore: ErrorStore,
		private readonly updateTheme?: (theme: ATheme) => void,
		private readonly readOnly = false,
	) {

	}

	public save() {
		assertNeverThrows(this.errorStore, this.settings.setUserPreference(this.name, this.value));
	}

	public load() {
		const newValue = this.settings.getUserPreference<boolean>(this.name);
		if (!_.isUndefined(newValue)) {
			this.value = newValue;
		}
	}

	public getValue() {
		return this.value;
	}

	public setValue(newValue: boolean) {
		// This should only be used for dark mode preference
		if (this.updateTheme) {
			if (newValue) {
				this.updateTheme(darkTheme);
			} else {
				this.updateTheme(defaultTheme);
			}
		}
		this.value = newValue;
	}

	public getTooltipIfDisabled() {
		if (this.readOnly) {
			if (isCCS()) {
				return "Theme controlled by Code Composer Studio";
			} else if (isEmbedded()) {
				return "Theme controlled by host application";
			}
			return "Theme set on command line";
		} else {
			// note a tooltip won't be shown if there is no content
			return "";
		}
	}
}

export class ButtonAction {
	constructor(
		public readonly description: string,
		public readonly buttonName: string,
		public readonly tooltip: string,
		public readonly requireBoard: boolean,
		public readonly onClick: (action: IUserPreferenceActions) => void,
	) { }
}

export class UserPreference {

	private readonly preferences: {
		devicePinDisplayType: MultiSelectPreference<PinDisplayType>;
		headerPinDisplayType: MultiSelectPreference<PinDisplayType>;
		displayConfigurablesScriptingNames: SwitchPreference;
		displayTabs: SwitchPreference;
		darkMode: SwitchPreference;
	};

	private readonly editorPreferences: {
		editorDiffType: SelectPreference<EditorDiffType>;
	};

	private readonly lockCurrentSolution = new ButtonAction(
		"Lock PinMux",
		"Lock",
		'Lock down pin and peripheral selections set to "Any" for auto solving with their currently solved for values',
		false,
		(action) => action.lockEntireSolution(),
	);

	constructor(settings: Settings, errorStore: ErrorStore, private readonly updateTheme: (theme: ATheme) => void, themeSetByArg: boolean) {
		this.preferences = {
			devicePinDisplayType: new MultiSelectPreference<PinDisplayType>(
				"devicePinDisplayTypev2",
				"Device Pin Label",
				this.createDevicePinDisplayNameOptions(),
				false,
				isUnderTest() ? [PinDisplayType.DEVICENUM] : [PinDisplayType.DEVICENUM, PinDisplayType.DEVICENAME],
				settings,
				errorStore,
			),
			headerPinDisplayType: new MultiSelectPreference<PinDisplayType>(
				"headerPinDisplayType",
				"Header Pin Label",
				this.createHeaderPinDisplayNameOptions(),
				true,
				[PinDisplayType.HEADERNAME, PinDisplayType.HEADERNUM],
				settings,
				errorStore,
			),
			displayConfigurablesScriptingNames: new SwitchPreference(
				"displayConfigurablesScriptingNames",
				"Show Scripting Names",
				false,
				settings,
				false,
				errorStore,
			),
			displayTabs: new SwitchPreference(
				"displayTabs",
				"Show Groups as Tabs",
				false,
				settings,
				false,
				errorStore,
			),
			darkMode: new SwitchPreference(
				"darkMode",
				"Dark Mode",
				false,
				settings,
				false,
				errorStore,
				this.updateTheme,
				themeSetByArg,
			),
		};

		this.editorPreferences = {

			editorDiffType: new SelectPreference(
				"EditorDiffType",
				"Choose how the editor displays diffs",
				this.createEditorDiffTypeOptions(),
				false,
				isUnderTest() ? EditorDiffType.NODIFF : EditorDiffType.INLINE,
				settings,
				errorStore,
			),
		};

		_.each(this.preferences, (p) => p.load());
		_.each(this.editorPreferences, (p) => p.load());
	}

	public getPreferences() {
		return this.preferences;
	}

	public getEditorPreferences() {
		return this.editorPreferences;
	}

	public getLockAction() {
		return this.lockCurrentSolution;
	}

	private createDevicePinDisplayNameOptions() {
		const options: AnySelectOption<PinDisplayType>[] = [];
		options[PinDisplayType.DEVICENAME] = {
			id: PinDisplayType.DEVICENAME,
			optionText: "Device pin name",
			description: "Display the device pin name",
		};
		options[PinDisplayType.DEVICENUM] = {
			id: PinDisplayType.DEVICENUM,
			optionText: "Device pin number",
			description: "Display the device pin number",
		};
		return options;
	}
	private createHeaderPinDisplayNameOptions() {
		const options: AnySelectOption<PinDisplayType>[] = [];
		options[PinDisplayType.DEVICENAME] = {
			id: PinDisplayType.DEVICENAME,
			optionText: "Device pin name",
			description: "Display the corresponding device pin name",
		};
		options[PinDisplayType.DEVICENUM] = {
			id: PinDisplayType.DEVICENUM,
			optionText: "Device pin number",
			description: "Display the corresponding device pin number",
		};
		options[PinDisplayType.HEADERNAME] = {
			id: PinDisplayType.HEADERNAME,
			optionText: "Board pin name",
			description: "Display the Board pin name",
		};
		options[PinDisplayType.HEADERNUM] = {
			id: PinDisplayType.HEADERNUM,
			optionText: "Board pin number",
			description: "Display the Board pin number",
		};
		return options;
	}

	private createEditorDiffTypeOptions() {
		const options: AnySelectOption<EditorDiffType>[] = [];
		options[EditorDiffType.NODIFF] = {
			id: EditorDiffType.NODIFF,
			optionText: "No diff",
			description: "Turn off diff",
		};
		options[EditorDiffType.INLINE] = {
			id: EditorDiffType.INLINE,
			optionText: "Unified diff",
			description: "Show diffs in one continuous column",
		};
		options[EditorDiffType.SIDEBYSIDE] = {
			id: EditorDiffType.SIDEBYSIDE,
			optionText: "Side-by-side diff",
			description: "Show diffs split into two columns",
		};
		return options;
	}
}
