import * as _ from "lodash";
import * as path from "path";
import { http } from "../../http";
import { MetaContentLocation } from "./resourceLoader";
import { isNode, isCloud } from "../../platform";
import { deviceDataDir } from "../../paths";

// This function loads all metadata associated with the SOC device data.  It first 
// looks for a bundle specific to that device id, but if not found, will use 
// the raw path to load resources (assuming non-cloud of course)
export function loadSocMetadata(deviceId: string) {
	const filePath = isNode() ? deviceDataDir() : undefined;
	const mainBundle = fetchBundle("deviceData/" + deviceId + "/metadata.bundle", filePath);
	const legacyAdaptionBundle = fetchBundle("deviceData/legacy/metadata.bundle", filePath);
	return Promise.all([mainBundle, legacyAdaptionBundle]);
}

// Load Product metadata content
export async function loadProductMetaData(productFilePath: string, includePaths: string[]): Promise<MetaContentLocation[]> {
	return isCloud()
		? loadProductMetaDataCloud(productFilePath)
		: loadProductMetaDataDesktop(productFilePath, includePaths);
}

async function loadProductMetaDataDesktop(productFilePath: string, includePaths: string[]) {

	// Support trying to load product bundles on the desktop in order to test bundling

	try {
		return [await fetchBundle(productFilePath + ".bundle")];
	} catch (e) { } // swallow

	// By default, just return the resolved include paths as a FilePath type of meta content location

	return _.map(includePaths, (includePath) => {
		const productFileDirPath = path.dirname(productFilePath);
		const filePath = path.resolve(productFileDirPath, includePath);
		return { filePath };
	});
}

async function loadProductMetaDataCloud(productFilePath: string) {
	return [await fetchBundle(productFilePath + ".bundle")];
}

// try to fetch .bundle file, optionally fall back to file system loader
async function fetchBundle(bundle: string, filePath?: string): Promise<MetaContentLocation> {
	try {
		return { bundle: await http.get(_.trimStart(bundle, "/")) };
	} catch (e) {
		if (filePath) {
			return { filePath };
		} else {
			throw e;
		}
	}
}
