import React = require("react");
import { IBasicInputProps } from "./InputBox";
import { Input, Popover, TextField } from "../imports/material-ui-imports";
import { commonStyles } from "./styles/common";
import * as _ from "lodash";

interface IProps extends IBasicInputProps {
	type: string;
}

interface IState {
	value: string;
	open: boolean;
	textAreaWidth: number;
}

export class MultilineInputBox extends React.Component<IProps, IState> {
	public override state: IState = {
		open: false,
		value: this.props.value,
		textAreaWidth: 0,
	};

	private anchorEl: HTMLElement = undefined;

	public override render() {
		return (
			<React.Fragment>
				<Input
					inputRef={this.inputRef}
					id={this.props.id}
					value={this.shortenString(this.state.open ? this.state.value : this.props.value)}
					onClick={this.handleClick}
					placeholder={this.props.placeholder}
					inputProps={{
						...this.props.inputProps, style: {
							textOverflow: "ellipsis",
						},
					}}
					disabled={this.props.disabled}
					type={this.props.type}
					fullWidth={true}
					style={commonStyles.inputTextStyle}
					readOnly={true}
				/>
				<Popover
					open={this.state.open}
					anchorEl={this.anchorEl}
					anchorOrigin={{
						vertical: "top",
						horizontal: "left",
					}}
					transformOrigin={{
						vertical: "top",
						horizontal: "left",
					}}
					PaperProps={{
						style: {
							width: this.state.textAreaWidth,
						},
					}}
					onClose={this.handleClickAway}
				>
					<TextField
						autoFocus={true}
						onMouseEnter={this.onMouseEvent}
						onMouseOver={this.onMouseEvent}
						onClick={this.onTextFieldClick}
						inputProps={{
							style: {
								whiteSpace: "pre",
								fontFamily: "monospace",
							},
						}}
						fullWidth={true}
						id={this.props.id + "_popperInput"}
						multiline={true}
						rows={"4"}
						rowsMax={"20"}
						value={this.state.value}
						variant="outlined"
						onChange={this.handleChange}
						disabled={this.props.disabled}
					/>
				</Popover>
			</React.Fragment >
		);
	}

	public override componentDidMount() {
		this.updateTextAreaWidth();
		window.addEventListener("resize", this.updateTextAreaWidth);
	}

	public override componentWillUnmount() {
		window.removeEventListener("resize", this.updateTextAreaWidth);
	}

	private handleClick = () => {
		if (!this.state.open) {
			this.setState({ open: true, value: this.props.value }, this.updateTextAreaWidth);
		}
	}

	private handleClickAway = () => {
		// We don't want to update the history if no changes are made [PMUX-2415]
		if (this.state.value !== this.props.value) {
			this.props.onChange(this.state.value);
		}
		this.setState({ open: false });
	}

	private handleChange = (ev: React.ChangeEvent<any>) => {
		this.setState({ value: ev.target.value }, this.updateTextAreaWidth);
	}

	private shortenString(str: string) {
		const lines = _.split(str, "\n");
		const andMore = lines.length > 1 ?
			`, +${lines.length - 1} more lines` :
			"";
		return `${_.first(lines)}${andMore}`;
	}

	private findLongestStringLength(input: string) {
		return _.chain(input)
			.replace(/\t/g, "\s\s\s\s\s\s\s\s")
			.split("\n")
			.map((str) => str.length)
			.max()
			.value();
	}

	private updateTextAreaWidth = () => {
		let textAreaWidth;
		if (!this.anchorEl) {
			textAreaWidth = 0;
		} else {
			const referenceWidth = this.anchorEl.offsetWidth;
			textAreaWidth = _.max([
				_.min([this.findLongestStringLength(this.state.value) * 7.2 + 43, referenceWidth * 3]),
				referenceWidth,
			]);
		}
		this.setState({ textAreaWidth });
	}

	private inputRef = (el: any) => this.anchorEl = el;
	private onMouseEvent = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => e.stopPropagation();
	private onTextFieldClick = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
		e.preventDefault();
		e.stopPropagation();
	}

}
