import * as React from "react";
import * as _ from "lodash";
import { NodeLabels } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { ClassesType, svgStrokeWidth } from "../styling/graphStyles";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { INodeProps } from "../types/nodeTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// A mux node (trapezoid), drawn using svg inside a positioned div

class MuxNodeImpl<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>
	extends React.PureComponent<INodeProps<InstMgr, PortMgr> & ClassesType & { selectedInput: string }> {
	public override render() {
		const {
			node,
			onClickNode,
			onMouseDownNode,
			displayScriptName,
			selectedInput,
			classes,
			validations,
			formatter,
		} = this.props;

		const edgeAdjustment = svgStrokeWidth / 2;
		const slopeOffset = node.width / 3;
		const topLeft = `${0 + edgeAdjustment},${0 + edgeAdjustment}`;
		const bottomLeft = `${0 + edgeAdjustment},${node.height - edgeAdjustment}`;
		const bottomRight = `${node.width - edgeAdjustment},${(node.height - slopeOffset) - edgeAdjustment}`;
		const topRight = `${node.width - edgeAdjustment},${slopeOffset + edgeAdjustment}`;
		return (
			<PositionedNode
				node={node}
				onClick={onClickNode}
				onMouseDown={onMouseDownNode}
				className={classes.positionedNode}
				validations={validations}
				formatter={formatter}
			>
				<NodeLabels
					node={node}
					checked={selectedInput}
					onChecked={this.onSelectedInputChanged}
					displayScriptName={displayScriptName}
					classes={classes}
				/>
				<svg className={classes.svgNodeContainer}>
					<polygon
						points={`${topLeft} ${bottomLeft} ${bottomRight} ${topRight}`}
						className={classes.svgNode}
					/>
				</svg>
			</PositionedNode>
		);
	}

	private onSelectedInputChanged = (selectedInput: string) => {

		// Change the selection and then set the configurable.  The selection change ensures that the history remains 
		// correct

		const { actions, onClickNode, node } = this.props;
		const { inst } = node;
		onClickNode(inst);
		actions.setConfigurableValue(inst.memberMgrs.inputSelect, selectedInput);
	}
}

// Fetches the current value and passes it along as a prop.  That way, the full implementation can be a PureComponent

export function MuxNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: INodeProps<InstMgr, PortMgr> & ClassesType
) {
	const selectedInput: string = props.node.inst.memberMgrs.inputSelect.getValue();
	return <MuxNodeImpl {...props} selectedInput={selectedInput} />;
}
