import * as _ from "lodash";
import * as Layout from "../../graph/types/layoutTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";
import { Point, Walkable } from "./pathFinding/util";
import { mapAdjacentElems } from "../../../services/utils";
import { Grid } from "./pathFinding/grid";
import { minimumEdgeSeparation } from "./constants";

// This class is responsible for translating between a set of nodes on an x,y coordinate graph, and a simple a "Grid"
// object for the path-finding algorithm (A*) to use, which uses simple indexes.  The translation between coordinates
// and grid indices is based on a scaling factor as well as a width/height adjustment (to ensure a zero-based index).  
// The translation is thus somewhat lossy, and any found paths may have to be adjusted after.  
// 
// The side effect of the scaling factor ensures that parallel lines will always be that many pixels apart, and it's 
// value should be considered when spacing ports and determining a grid for a snap-to-grid feature

const SCALING_FACTOR = minimumEdgeSeparation;
const LABEL_HEIGHT = SCALING_FACTOR * 2;

export class RoutingMatrix {

	private readonly widthAdjustment;
	private readonly heightAdjustment;
	private readonly grid: Grid;

	// Creates a grid object and notes the width/heigh adjustments

	constructor(nodes: Layout.Node<ModuleInstanceMgr, PortMemberMgr>[]) {
		const { widthAdjustment, heightAdjustment, width, height } = getMatrixDimensions(nodes);
		this.widthAdjustment = widthAdjustment;
		this.heightAdjustment = heightAdjustment;
		this.grid = new Grid(width, height);
		this.markNodes(nodes);
	}

	// Convert a start point to a grid indices
	// This moves the x position forwards until a valid start location is found.  This handles overlapping nodes

	public getGridStart({ x, y }: { x: number, y: number }): Point {
		let startX = this.toGridX(x);
		const startY = this.toGridY(y);
		while (this.grid.getWalkability(startX, startY) === Walkable.Never && startX < this.grid.width - 1) {
			++startX;
		}
		return [startX, startY];
	}

	// Convert an end point to a grid indices
	// This moves the x position backwards until a valid start location is found.  This handles overlapping nodes as 
	// well as shapes with ports on the inside such as OR gates

	public getGridEnd({ x, y }: { x: number, y: number }): Point {
		let startX = this.toGridX(x);
		const startY = this.toGridY(y);
		while (this.grid.getWalkability(startX, startY) === Walkable.Never && startX > 0) {
			--startX;
		}
		return [startX, startY];
	}

	// Translates grid indices back to coordinates (somewhat lossy)

	public toPoint([x, y]: Point): Point {
		return [(x - this.widthAdjustment) * SCALING_FACTOR, (y - this.heightAdjustment) * SCALING_FACTOR];
	}

	// Returns the grid.  Note that it clones the grid as the path-finding algorithm will mark it up

	public getGrid() {
		return this.grid.clone();
	}

	// Mark all found edges such that subsequent searches will allow paths to cross but not overlap

	public markEdge(compressedPath: Point[]) {

		mapAdjacentElems(compressedPath, ([startX, startY], [endX, endY]) => {
			// Mark vertical lines as only allowing left/right walking going forward, and vice versa for horizontal
			// That will allow vertical lines to cross horizontal lines, but not other vertical lines (and vice versa)
			// But, if already marked, then the point is a cross point already, and nothing is ever allowed again

			if (startX === endX) {
				_.each(_.range(startY, endY), (y) => {
					const currentState = this.grid.getWalkability(startX, y);
					if (Walkable.Always === currentState || Walkable.StartOnly === currentState || Walkable.EndOnly === currentState) {
						this.grid.setWalkableAt(startX, y, Walkable.LeftRightOnly);
					} else if (Walkable.LeftRightOnly !== currentState) {
						this.grid.setWalkableAt(startX, y, Walkable.Never);
					}
				});
			} else {
				_.each(_.range(startX, endX), (x) => {
					const currentState = this.grid.getWalkability(x, startY);
					if (Walkable.Always === currentState || Walkable.StartOnly === currentState || Walkable.EndOnly === currentState) {
						this.grid.setWalkableAt(x, startY, Walkable.UpDownOnly);
					} else if (Walkable.UpDownOnly !== currentState) {
						this.grid.setWalkableAt(x, startY, Walkable.Never);
					}
				});
			}

			// Mark the ends so we never cross at a bend point

			this.grid.setWalkableAt(startX, startY, Walkable.Never);
			this.grid.setWalkableAt(endX, endY, Walkable.Never);
		});
	}

	// Translate coordinates to grid indices

	private toGridX(x: number) {
		return Math.round(x / SCALING_FACTOR + this.widthAdjustment);
	}

	private toGridY(y: number) {
		return Math.round(y / SCALING_FACTOR + this.heightAdjustment);
	}

	private markNodes(nodes: Layout.Node<ModuleInstanceMgr, PortMemberMgr>[]) {
		_.each(nodes, (node) => {
			if (node.height && node.width) {
				const startX = this.toGridX(node.x);
				const endX = this.toGridX(node.x + node.width);
				const startY = this.toGridY(node.y);
				const endY = this.toGridY(node.y + node.height + LABEL_HEIGHT);

				// Block off the node's location internal locations, with extra at the top and bottom

				for (let x = startX; x <= endX; ++x) {
					for (let y = startY - 1; y < endY + 1; ++y) {
						this.grid.setWalkableAt(x, y, Walkable.Never);
					}
				}

				// Mark the sides as start/end only

				for (let y = startY - 1; y < endY + 1; ++y) {
					this.grid.setWalkableAt(startX - 1, y, Walkable.EndOnly);
					this.grid.setWalkableAt(endX + 1, y, Walkable.StartOnly);
				}
			}
		});
	}
}

function getMatrixDimensions(nodes: Layout.Node<ModuleInstanceMgr, PortMemberMgr>[]) {
	if (_.isEmpty(nodes)) {
		return {
			widthAdjustment: 0,
			heightAdjustment: 0,
			width: 0,
			height: 0,
		};
	}
	const maxX = _.maxBy(nodes, (n) => n.x + n.width);
	const maxY = _.maxBy(nodes, (n) => n.y + n.height);
	const minX = _.minBy(nodes, (n) => n.x);
	const minY = _.minBy(nodes, (n) => n.y);

	return {
		widthAdjustment: -minX.x / SCALING_FACTOR + 2,
		heightAdjustment: -minY.y / SCALING_FACTOR + 2,
		width: Math.ceil((maxX.x + maxX.width - minX.x) / SCALING_FACTOR + 4),
		height: Math.ceil((maxY.y + maxY.height + LABEL_HEIGHT - minY.y) / SCALING_FACTOR + 4),
	};
}
