import React = require("react");
import * as _ from "lodash";

import { InterfaceInstanceMemberMgr } from "../../services/objectManagers/interfaceInstanceMemberMgr";
import { OptimizablePinMemberMgr, ExtendedPinMemberMgr } from "../../services/objectManagers/pinObjectMembers";
import { ConfigStoreActions } from "../../services/configStore";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { ResourceLoader } from "../../services/resources/metaContentLoaders/resourceLoader";
import { MemberRow, ConfigTableRow } from "./MemberRow";
import { InterfaceInstanceMgr } from "../../services/objectManagers/interfaceInstance";
import { PeripheralSelection } from "./PeripheralSelection";
import { getDisplayName, ioSetTooltip } from "../../services/utils";
import { VoltageSelection } from "./VoltageSelection";
import { InputBox } from "../InputBox";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { PinSelectRow } from "./PinSelectRow";
import { PinRequirements } from "./PinRequirements";
import { ConflictControl } from "../ConflictControl";
import { Validations } from "../../services/objectManagers/validations";
import { PinDisplayType } from "../../services/userPreferences";

interface IBaseProps extends IGlobalServiceProps {
	actions: ConfigStoreActions;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	showUsed: boolean;
	showPinTable: boolean;
	highlightedMember: string;
	highlightedInterfaceID: string;
	arePowerDomainSettingsEnabled: boolean;
	columns: number;
}

interface IPinMuxConfigTableProps extends IBaseProps {
	memberMgrs: (InterfaceInstanceMemberMgr | OptimizablePinMemberMgr | ExtendedPinMemberMgr)[];
}

export class CPinMux extends React.Component<IPinMuxConfigTableProps> {
	public override render() {
		const { memberMgrs } = this.props;
		return _.map(memberMgrs, (m) => {
			return (
				<InterfaceInstanceRows
					{...this.props}
					memberMgr={m}
					key={m.def.name}
				/>
			);
		});
	}
}

interface IInterfaceInstanceRows extends IBaseProps {
	memberMgr: InterfaceInstanceMemberMgr | OptimizablePinMemberMgr | ExtendedPinMemberMgr;
}

class InterfaceInstanceRows extends React.Component<IInterfaceInstanceRows> {

	public override render() {
		const { memberMgr, actions, formatter, displayScriptName, validations } = this.props;
		const keyPrefix = memberMgr.def.name;
		if (isInterfaceInstanceMemberMgr(memberMgr)) {
			// we need to distinguish between highlighting the actual peripheral selection
			// and selecting a pin under a specific peripheral
			const ifaceInstanceMgr = memberMgr.valueObjectMgr;
			const voltageMgr = ifaceInstanceMgr.getVoltageMgr();

			const peripheralIsHighlighted =
				!this.props.highlightedInterfaceID && memberMgr.def.name === this.props.highlightedMember;
			const highlightedMemberOnPeripheral =
				!this.props.highlightedInterfaceID || this.props.highlightedInterfaceID === ifaceInstanceMgr.getID() ?
					this.props.highlightedMember : "";

			return (
				<React.Fragment>
					<MemberRow
						{...this.props}
						memberMgr={memberMgr}
						key={`${keyPrefix}Peripheral`}
						highlight={peripheralIsHighlighted}
						conflictControl={
							<ConflictControl
								req={memberMgr.valueObjectMgr}
								formatter={this.props.formatter}
								actions={this.props.actions}
							/>
						}
					>
						<PeripheralSelection
							instMgr={memberMgr.valueObjectMgr}
							onChange={(value) =>
								actions.setSelectedPeripheral(ifaceInstanceMgr, value, getDisplayName(memberMgr.def, false))}
							formatter={formatter}
							validations={validations}
							actions={this.props.actions}
						/>
					</MemberRow>

					{voltageMgr &&
						<MemberRow
							{...this.props}
							memberMgr={voltageMgr}
							key={`${keyPrefix}$voltage`}
							highlight={voltageMgr.def.name === highlightedMemberOnPeripheral}
						>
							<VoltageSelection
								instMgr={voltageMgr.parentObjectMgr}
								onChange={(val) => actions.setSelectedVoltage(voltageMgr.parentObjectMgr, val)}
								arePowerDomainSettingsEnabled={this.props.arePowerDomainSettingsEnabled}
								formatter={formatter}
								actions={actions}
							/>
						</MemberRow>
					}

					{ifaceInstanceMgr.hasIOSet() &&
						<ConfigTableRow
							{...this.props}
							label="IO Set"
							labelToolTip={ioSetTooltip}
							valueToolTip={ioSetTooltip}
						>
							<InputBox
								type="text"
								id={"ioset"}
								disabled={true}
								value={ifaceInstanceMgr.getSolverRequirement().solution.ioSet || ""} // avoid react warning on empty ioSet
								onChange={() => { }}
							/>
						</ConfigTableRow>
					}
					<PinRequirements
						{...this.props}
						keyPrefix={keyPrefix}
						pinsProvider={ifaceInstanceMgr}
						highlightedMember={highlightedMemberOnPeripheral}
					/>
				</React.Fragment>
			);
		} else if (isExtendedPinMemberMgr(memberMgr)) {
			const ifaceInstanceMgr = memberMgr.getExtendedMgr();
			const highlightedMemberOnPeripheral =
				!this.props.highlightedInterfaceID || this.props.highlightedInterfaceID === ifaceInstanceMgr.getID() ?
					this.props.highlightedMember : "";
			return (
				<PinRequirements
					{...this.props}
					keyPrefix={keyPrefix}
					pinsProvider={memberMgr}
					highlightedMember={highlightedMemberOnPeripheral}
				/>
			);
		} else {
			return <PinSelectRow
				{...this.props}
				key={`${keyPrefix}`}
				memberMgr={memberMgr} actions={actions}
				displayScriptName={displayScriptName}
				configurablesOrder={[]}
			/>;
		}
	}
}

function isInterfaceInstanceMemberMgr(
	memberMgr: InterfaceInstanceMemberMgr | OptimizablePinMemberMgr | ExtendedPinMemberMgr)
	: memberMgr is InterfaceInstanceMemberMgr {
	return memberMgr.valueObjectMgr instanceof InterfaceInstanceMgr;
}

function isExtendedPinMemberMgr(
	memberMgr: InterfaceInstanceMemberMgr | OptimizablePinMemberMgr | ExtendedPinMemberMgr)
	: memberMgr is ExtendedPinMemberMgr {
	return memberMgr instanceof ExtendedPinMemberMgr;
}
