import * as _ from "lodash";
// Contains managers for built-in configurables tied to a solver requirement

import { InterfaceInstanceMgr } from "./interfaceInstance";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { EnumerationConfigurable, EnumerationOption, InterfaceRequirement } from "public/defs";
import { InterfaceInstance } from "public/runtime";
import { OverrideMgr, AllowConflictsMgr, SuggestSolutionMgr, StaticEnumerationConfigurable } from "./assignMembers";
import { PinMap, PinType } from "../pinMap";
import { createMemberValueAssignmentStatement } from "../scripting/serialize";
import { FormattersMap } from "../formatting/formattersMap";
import { IOptions } from "./options";
import { Const, createAnyOption } from "../utils";
import { Peripheral as PeripheralReq } from "../solver/requirements";
import * as data from "dataInterfaces";
import { disableScriptingForCallback } from "../scripting/scriptingGuard";

const voltageConfigurableName: keyof InterfaceInstance = "$assignVoltage";

function createVoltageConfigurableDef(ifaceData: data.Interface, pinMap: PinMap): EnumerationConfigurable {

	const powerValuesMap: { [key: string]: string } = {}; // To filter duplicates

	// create voltage selections

	pinMap.forEachMapping(ifaceData.interfacePins, PinType.FREE, (devicePin) => {
		if (devicePin.powerDomain && devicePin.powerDomain.powerValue) {
			_.each(devicePin.powerDomain.powerValue, (powerValue) => {
				if (powerValue && powerValue !== "" && !powerValuesMap[powerValue]) {
					powerValuesMap[powerValue] = powerValue;
				}
			});
		}
	});

	const options: EnumerationOption[] = _.map(_.values(powerValuesMap), (powerValue) => {
		return {
			name: powerValue,
			displayName: powerValue,
		};
	});

	const anyOption = createAnyOption();
	options.unshift(anyOption);

	return {
		name: voltageConfigurableName,
		displayName: "Preferred Voltage",
		description: "Indicates the voltage expected for every pin on this peripheral.  " +
			'Voltage domains can be enabled and configured under the "Device Settings" tab',
		default: anyOption.name,
		options,
	};
}

const peripheralDisableReason = "This selection is not possible with your current pin overrides";
/**
 * Manage $assign on a interface instance
 * Do not change to a type since we use "instanceof" on it
 */
export class PeripheralOverrideMgr
	extends OverrideMgr<InterfaceInstance, InterfaceInstanceMgr>
	implements IOptions<string> {
	public override generateScriptStatements(parentIdentifier: string) {
		const rvalue = Const.ANY === this.value ? this.solverReq.solution.assignedToName : this.value;
		return [createMemberValueAssignmentStatement(this.def, parentIdentifier, rvalue)];
	}

	public override getCLIOptions() {

		const filtered = this.parentObjectMgr.getFilteredPeripherals();

		const enabledOptions = _.map(filtered.enabled, (o) => o.name);

		const disabledOptions = _.map(filtered.disabled, (o) => {
			return {
				name: o.name,
				reason: peripheralDisableReason,
			};
		});

		return {
			enabledOptions,
			disabledOptions,
		};

	}

	public override getUIOptions() {

		const filtered = this.parentObjectMgr.getFilteredPeripherals();

		const enabledOptions = _.map(filtered.enabled, (o) => {
			return {
				name: o.name,
				displayName: o.name,
			};
		});

		const disabledOptions = _.map(filtered.disabled, (o) => {
			return {
				name: o.name,
				displayName: o.name,
				description: peripheralDisableReason,
			};
		});

		return {
			disabledOptions,
			enabledOptions,
		};
	}
}

/**
 * Manage $assignAllowConflicts on a interface instance
 */
class PeripheralAllowConflictsMgr extends AllowConflictsMgr<InterfaceInstance> { }

/**
 * Manage $suggestSolution on a interface instance
 */
class PeripheralSuggestSolutionMgr extends SuggestSolutionMgr<InterfaceInstance, PeripheralReq> { }

const usePeripheralConfigurableName: keyof InterfaceInstance = "$assign";

function createUsePeripheralConfigurableDef(
	peripherals: data.Peripheral[]): StaticEnumerationConfigurable {

	const options: EnumerationOption[] = _.map(peripherals, (p) => {
		return {
			name: p.name,
			displayName: p.name,
		};
	});

	const anyOption = createAnyOption();
	options.unshift(anyOption);

	return {
		name: usePeripheralConfigurableName,
		displayName: "Use Peripheral",
		default: anyOption.name,
		options,
	};
}

/**
 * Manage $voltage on an interface instance
 */
export class VoltageMgr extends EnumerationConfigurableMgr {

	public constructor(
		public override parentObjectMgr: InterfaceInstanceMgr,
		formattersMap: FormattersMap,
		def: EnumerationConfigurable,
		private readonly solverReq: PeripheralReq) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);

		solverReq.userVoltageOverride = this.value === Const.ANY ? null : this.value;
	}

	protected override onSet(newVal: string) {
		this.solverReq.userVoltageOverride = newVal === Const.ANY ? null : this.value;
	}
}

/**
 * Manages interaction with underlying solver requirement.
 */
export class SolverRequirement {
	private readonly solverReq: PeripheralReq;
	private readonly voltage: VoltageMgr;
	private readonly overrideMgr: PeripheralOverrideMgr;
	private readonly allowConflictsMgr: PeripheralAllowConflictsMgr;
	private readonly peripherals: data.Peripheral[];
	private readonly canShareWith: () => string;

	constructor(
		parent: InterfaceInstanceMgr,
		formattersMap: FormattersMap,
		id: string,
		options: Pick<InterfaceRequirement, "canShareWith" | "maxShareCount" | "filter" | "signalTypes"> = {},
		pinMap: PinMap,
	) {
		const canShareWith = options.canShareWith;
		this.solverReq
			= new PeripheralReq(
				id,
				parent.managedObject.$interface.name,
				_.isFunction(canShareWith) ? null : canShareWith,
				options.maxShareCount);

		this.peripherals = parent.managedObject.$interface.peripherals;
		if (options.filter) {
			this.peripherals = _.filter(this.peripherals, options.filter);
			this.solverReq.restrictTo = _.map(this.peripherals, (p) => p.name);
		}

		if (_.isFunction(canShareWith)) {
			this.canShareWith = () => disableScriptingForCallback(() => canShareWith(parent.parentModuleMgr.managedObject));
		}

		const assignDef = createUsePeripheralConfigurableDef(this.peripherals);
		const conflictsDef = _.extend(
			_.clone(assignDef),
			{ name: "$assignAllowConflicts", displayName: "Assign peripheral (ignoring conflicts)" },
		);
		const suggestSolutionsDef = _.extend(
			_.clone(assignDef),
			{ name: "$suggestSolution", displayName: "Suggest solution" },
		);
		this.overrideMgr = new PeripheralOverrideMgr(parent, formattersMap, this.solverReq, assignDef);
		this.allowConflictsMgr = new PeripheralAllowConflictsMgr(parent, formattersMap, this.solverReq, conflictsDef);
		new PeripheralSuggestSolutionMgr(
			parent, formattersMap, this.solverReq, suggestSolutionsDef);
		const volageDef = createVoltageConfigurableDef(parent.managedObject.$interface, pinMap);
		if (volageDef.options.length > 1) { // there is always 1 any option
			this.voltage = new VoltageMgr(parent, formattersMap, volageDef, this.solverReq);
		}
	}

	public getOverrideMgr() {
		return this.overrideMgr;
	}

	public getConflictMgr() {
		return this.allowConflictsMgr;
	}

	public getVoltageMgr() {
		return this.voltage;
	}

	public getRequirementsForSolver() {
		if (this.canShareWith) {
			this.solverReq.canShareWith = this.canShareWith();
		}
		return this.getRequirementData();
	}

	public getRequirementData() {
		return this.solverReq;
	}

	public getValidPeripherals() {
		return this.peripherals;
	}
}
