import * as _ from "lodash";
// Contains base class providing facilities for object manager classes

import { ConfigurableMgr } from "./configurables/configurableMgr";
import { AnyMemberMgr, SetSource, InstanceArgType } from "./member";
import { RuntimeObject } from "public/runtime";
import { createValidationSuppressionStatement, Statement, ValidationStatement } from "../scripting/serialize";
import { InstanceArgs, InstanceArgsValue } from "public/defs";
import { ObjectMemberManager } from "./objectMember";
import { FormattersMap } from "../formatting/formattersMap";
import { FixedDataMember } from "./fixedDataMember";
import { managedObjectProxyHandler } from "./proxyHandlers/managedObjectProxyHandler";
import { InternalValidationLogger, IValidatableObject, Validations } from "./validations";
import { SerializationOptions } from "../scripting/toScript";
import { Runtime } from "../resources/runtime";
import { FormatOptions } from "../formatting/formattingTypes";
import { FormattedMsgPart } from "../formatting/link";
import { ModuleInstanceMgr, OnModuleChangedType } from "./moduleInstance";
import { InvalidMemberAccess, InvalidPortAccess } from "./invalidAssignment";
import { ITreeNode } from "../../components/TreeNode";
import { InstanceMgr } from "../instanceContainers/instanceContainer";
import { getValidationKey } from "../utils";
import { getOldDisplayName } from "../migration/migrateUtils";

/**
 * Abstract class which all module instance types must extend.
 */
export abstract class AObjectMgr<RuntimeObjectType extends RuntimeObject> implements IValidatableObject {

	/**
	 * Runtime object being managed
	 */
	public readonly managedObject: RuntimeObjectType;

	/**
	 * Managers for all members
	 */
	public memberMgrs: { [memberName: string]: AnyMemberMgr } = {};

	private invalidMemberAccesses: InvalidMemberAccess[] = [];

	// Used to generate sequence numbers assigned to configurables on user modifications
	// to track the order for serialization.

	constructor(
		protected readonly runtime: Runtime,
		formatter: (options: FormatOptions, member?: string) => FormattedMsgPart,
	) {
		// create the instance
		this.managedObject = new Proxy(this, managedObjectProxyHandler) as any as RuntimeObjectType;
		this.runtime.getFormattersMap().set(this.managedObject, formatter);
		this.runtime.setManager(this.managedObject, this);
	}

	public abstract getContainingTreeNodes(): ITreeNode[];

	public abstract getContainingInstanceMgrs(): InstanceMgr[];

	public getContainingModule(): { modInstMgr: ModuleInstanceMgr, memberPath: string[] } {
		return { modInstMgr: null, memberPath: [] };
	}

	public getContextId() {
		return this.runtime.getId();
	}

	public getContextDisplayName() {
		return this.runtime.getDisplayName();
	}

	public invalidAccess(value: any, path: string[], reason?: string) {
		const displayName = getOldDisplayName(path, this);
		this.invalidMemberAccesses.push(new InvalidMemberAccess(value, this, path,
			this.runtime.getFormattersMap(), reason, displayName));
	}

	public invalidPortAccess(path: string[], reason: string, oldDisplayName?: string) {
		const displayName = oldDisplayName ?? getOldDisplayName(path, this);
		this.invalidMemberAccesses.push(new InvalidPortAccess(null, this, path, this.runtime.getFormattersMap(), reason, displayName));
	}

	public clearInvalidAccess() {
		_.each(this.invalidMemberAccesses, (i) => i.remove());
		this.invalidMemberAccesses = [];
	}

	public abstract modifiedInUI(): void;

	/**
	 * Currently allow assignments from meta content.
	 */
	public currentlyAllowMetaAssign() {
		return false;
	}

	/**
	 * Current non user change being applied.
	 * A ConfigurableMgr indicates the meta assign is because of an onChange
	 * An object indicates onModuleChanged
	 */
	public currentMetaAssign(): ConfigurableMgr<any> | OnModuleChangedType {
		return null;
	}

	/**
	 * Invoked when a member is changed
	 * @param _memberMgr - manager for the changed member 
	 * @param _source - source of the member change
	 */
	public onMemberChanged(_memberMgr: AnyMemberMgr, _source: SetSource) {
	}

	// Validate managed object
	public validate(validationLogger: InternalValidationLogger) {
		if (!_.isEmpty(this.invalidMemberAccesses)) {
			let errorMsg = "";
			_.each(this.invalidMemberAccesses, (ima) => {
				errorMsg += ima.getError();
			});
			const firstError = _.first(this.invalidMemberAccesses);
			// it seems really unlikely the reasons would differ
			errorMsg += firstError.getClickHereMsg() + " " + firstError.getReasonMsg();
			validationLogger.logError(errorMsg, this);
		}
		_.each(this.memberMgrs, (mem) => mem.validate(validationLogger));
	}

	public addMember(member: AnyMemberMgr) {

		// Must check for duplicates here as well as in adaptToModule, as we need to also watch dynamic configurables

		if (this.memberMgrs[member.def.name]) {
			throw new Error(`Duplicate configurable definition: '${member.def.name}'`);
		}
		this.memberMgrs[member.def.name] = member;
	}

	public removeMember(member: AnyMemberMgr) {
		member.remove();
		delete this.memberMgrs[member.def.name];
	}

	public setValueFromRequiredArgs(requiredArgs: InstanceArgs, origin: ModuleInstanceMgr) {
		this.iterateArgs(
			requiredArgs,
			(member, val) => member.setValueFromRequiredArgs(val, origin),
		);
	}

	public removeArgs(args: InstanceArgs) {
		this.iterateArgs(
			args,
			(member, val) => member.removeArgs(val),
		);
	}

	public removeReqArgs(requiredArgs: InstanceArgs, origin: ModuleInstanceMgr) {
		this.iterateArgs(
			requiredArgs,
			(member, val) => member.removeReqArgs(val, origin),
		);
	}

	public setValueFromArgs(args: InstanceArgs, argType: InstanceArgType) {

		this.validateInstanceArgs(args);

		// Separate object and non-object members

		const groupedArgs = _.groupBy(_.map(args, (value, name) => ({ value, name })), (arg) => {
			const member = this.memberMgrs[arg.name];
			return (member && !(member instanceof ObjectMemberManager)) ? "nonObject" : "object";
		});

		// Since object members can be added dynamically based on values of other non object 
		// members, we must add them first.

		// keep trying to set non readOnly members
		// since setting a member can make another member non readOnly
		// we keep trying until no non set members become non readOnly
		let someSet = true;
		while (someSet) {
			someSet = false;
			groupedArgs.nonObject = _.filter(groupedArgs.nonObject, (arg) => {
				const member = this.memberMgrs[arg.name];
				// try to only set readOnly
				if (!member.uiState.readOnly) {
					member.setValueFromArgs(arg.value, argType);
				} else {
					return true; // don't filter out
				}
				someSet = true;
				return false; // filter out
			});
		}

		// Now we can set those remaining non-object members, and then the object members.  
		// Anything failing from this point is a real exception that we'll propagate

		const remaining = [...groupedArgs.nonObject, ...(groupedArgs.object || [])];
		_.each(remaining, (arg) => {
			const member = this.memberMgrs[arg.name];
			if (member) {
				member.setValueFromArgs(arg.value, argType);
			} else {
				throw new Error(`Unknown member '${arg.name}'`);
			}
		});
	}

	/**
	 * Walk all members that need to be serialized and gather script statements 
	 * @param identifier - Script identifier for this object.
	 */
	public getScriptStatements(identifier: string, options: SerializationOptions): Statement[] {
		const validations = this.runtime.getValidations();
		const statements = [
			..._.flatMap(this.getMembersInScriptOrder(options), (mem) => mem.getScriptStatements(identifier, options, validations)),
			..._.flatMap(this.invalidMemberAccesses, (i) => i.getScriptStatements(identifier)),
		];
		const [validationStatements, configs] = _.partition(statements, (s) => s instanceof ValidationStatement);
		return [
			...configs,
			...this.generateValidationStatements(identifier, validations),
			...validationStatements,
		];
	}

	public isUserModified() {
		return _.some(this.memberMgrs, (m) => m.isUserModified());
	}

	public remove() {
		this.preRemove();
		const formattersMap = this.runtime.getFormattersMap();
		formattersMap.delete(this.managedObject);
		this.removeMembers();
		this.removeFromRuntime();
	}

	protected removeFromRuntime() {
		this.runtime.deleteManager(this.managedObject);
	}

	protected preRemove() { }

	/**
	 * Members which need assignment statements in the script file. 
	 * Note that statements will be added to the script in the array order.
	 */
	protected getMembersInScriptOrder(_options: SerializationOptions): AnyMemberMgr[] {
		return _.values(this.memberMgrs);
	}

	protected addFixedMember<key extends keyof RuntimeObjectType>(
		formattersMap: FormattersMap,
		memberName: key,
		value: RuntimeObjectType[key]
	): FixedDataMember<RuntimeObjectType[key], RuntimeObjectType> {
		return new FixedDataMember(this, formattersMap, memberName, value);
	}

	private iterateArgs(
		args: InstanceArgs,
		action: (member: AnyMemberMgr, val: InstanceArgsValue, key: string) => void,
	) {
		_.each(args, (val, key) => {
			const member = this.memberMgrs[key];
			if (member) {
				action(member, val, key);
			} else {
				throw new Error(`Unknown member '${key}'`);
			}
		});
	}

	private generateValidationStatements(parentIdentifier: string, validations: Validations): Statement[] {
		const validation = validations.getValidation(this);
		return _.map(validation?.suppressedWarnings,
			(v) => createValidationSuppressionStatement(parentIdentifier, getValidationKey(v).matcher));
	}

	private removeMembers() {

		// get members, also works as a clone so we don't mutate map while iterating

		const members = _.values(this.memberMgrs);
		_.each(members, (mem) => this.removeMember(mem));

	}

	private validateInstanceArgs(args: InstanceArgs) {
		if (!(_.isUndefined(args) || _.isObject(args))) {
			throw new Error(`${args} must be an object`);
		}
	}
}
