import React = require("react");
import { IBasicInputProps } from "../InputBox";

interface IFilterInputProps {
	filter: (value: string) => boolean;
}

export function filterInput<T extends IBasicInputProps>(BaseInput: React.ComponentClass<T>) {
	class FilterInput extends React.Component<T & IFilterInputProps, { value: string }> {
		public override render() {
			return (
				<BaseInput
					{...this.props}
					onChange={
						(value: string) => {
							if (this.props.filter(value)) {
								this.props.onChange(value);
							}
						}
					}
				/>
			);
		}
	}
	return FilterInput;
}
