import * as React from "react";
import * as _ from "lodash";
import type * as Plotly from "plotly.js-basic-dist-min";
import { Plot } from "public/defs";
import { ErrorStore } from "../../services/errorStore";
import { PlotWithRange, SimulationResults } from "./SimulationResults";

// This is a component that adapts a SimulationResults component such that the data is pre-scaled and re-scaled on a 
// zoom.  This allows all the underlying components to operate against significantly smaller datasets and thus remain 
// responsive

// We want to get some points from outside the selected zoom range so plot isn't cut off when a discontinuity is encountered
// The offsets define how many points extra points should be retrieved from each end
const SMOOTHING_START_OFFSET = 1;
const SMOOTHING_END_OFFSET = 1;

interface IProps {
	plotData: Plot[];
	errorStore: ErrorStore;
	plotly: typeof Plotly;
}

export function PreScaledSimulationResults({ plotData, errorStore, plotly }: IProps) {

	// We pre-scale the data with the zoom level set to the min/max of the x values

	const initialData = React.useMemo(() => scaleAndZoom(plotData, plotData[0].x[0], _.last(plotData[0].x)), [plotData]);

	// Set the zoomed data to be the initial scaling

	const [zoomedData, setZoomedData] = React.useState(initialData);

	// Respond to zoom/resetZoom events by either zooming in or setting the data to the initial set

	const onZoom = React.useCallback((min: number, max: number) => setZoomedData(scaleAndZoom(plotData, min, max)), [plotData]);
	const onResetZoom = React.useCallback(() => setZoomedData(initialData), [initialData]);

	return <SimulationResults
		plotly={plotly}
		plotData={zoomedData}
		errorStore={errorStore}
		onResetZoom={onResetZoom}
		onZoom={onZoom}
	/>;
}

function scaleAndZoom(plotData: Plot[], min: number, max: number): PlotWithRange[] {

	// For the given range, chunk up the point indexes and then find the indices with the min/max y value's for each of
	// the plots for each chunk.  This ensures that when the plot is scaled in each chunk, we are including any min/max 
	// values so that data spikes will never be hidden, and also so that the time associated with any point is always 
	// an actual point (ie it's not an average around that point).
	//
	// Since we'll return 2 points per plot, the chunk size needs to scale by number of plots.  However, since we 
	// remove duplicate entries, the size could be much less.  3000 was chosen as a number that:
	// 1) Ensures that at low zoom levels is at least one point per pixel
	// 2) Isn't so big as to cause performance issues with plotly

	const chunkSize = 3000;
	let start = _.findIndex(plotData[0].x, (x) => x >= min);
	let end = _.findLastIndex(plotData[0].x, (x) => x <= max);
	// We want to get some points from outside the selected zoom range so plot isn't cut off when a discontinuity is encountered
	start = _.clamp(start - SMOOTHING_START_OFFSET, 0, plotData[0].x.length - 1);
	end = _.clamp(end + SMOOTHING_END_OFFSET, 0, plotData[0].x.length - 1);

	const indexes = _.chain(_.range(start, end + 1))
		.chunk(Math.ceil((end - start) / chunkSize * _.size(plotData)))
		.flatMap((chunk) => {
			return _.chain(plotData)
				.flatMap((plot) => [
					_.maxBy(chunk, (index) => plot.y[index]),
					_.minBy(chunk, (index) => plot.y[index]),
				])
				.sortBy()
				.sortedUniq()
				.value();
		}
		)
		.value();

	// Now, filter the plot data by only returning the data at those indexes

	const x = _.at(plotData[0].x, indexes);
	return _.map(plotData, (plot) => {
		const y = _.at(plot.y, indexes);
		return {
			...plot,
			x,
			y,
			xRange: [min, max],
		};
	});
}
