import * as _ from "lodash";
import React = require("react");
import { ListItem, ListItemIcon, ListItemText, Typography, IconButton } from "../imports/material-ui-imports";
import { ContentCopy, DeleteOutline } from "../imports/mdi-material-ui-imports";
import { commonStyles, withCommonStyles, CommonClasses } from "./styles/common";
import { InstanceStatusDecorator } from "./Decorators";
import { Popup } from "./Popup";
import { CannotDoActionPopup } from "./CannotDoActionPopup";
import { IFormatter } from "../services/formatting/formattingTypes";
import { ActionEnabled, ActionState, OwnershipInfo } from "../services/IMyListItem";
import { InstanceMgr, AInstanceContainer } from "../services/instanceContainers/instanceContainer";
import { Validations } from "../services/objectManagers/validations";
import { ModuleInstanceMgr } from "../services/objectManagers/moduleInstance";
import { MoveInstanceButton } from "./MoveInstanceButton";
import { UIContextSelection } from "./actions/IContextActions";

interface IListItemProps<T extends InstanceMgr> {
	name: string;
	canRemove: ActionState;
	remove: (item: T) => void;
	canCopy: ActionState;
	copy: (item: T) => void;
	isSelected: boolean;
	select: (item: T) => void;
	index: number;
	formatter: IFormatter;
	validations: Validations;
	getCannotRemoveReason?: (item: T) => OwnershipInfo | string;
	item: T;

	// moving instance to other runtime
	moveInstance: (item: InstanceMgr, contextName: string) => void;
	isTopModuleOnContext: (mgr: ModuleInstanceMgr, contextName: string) => boolean;
	getContextSelection(): UIContextSelection;
}

class StyledItem<T extends InstanceMgr> extends React.PureComponent<IListItemProps<T> & CommonClasses> {
	public override render() {
		const className = this.props.isSelected ? this.props.classes.selectedList : this.props.classes.unSelectedList;
		const numContexts = this.props.getContextSelection().contexts.length;
		return (
			// wrap and id for testing
			<ListItem
				id={"req" + this.props.index}
				button
				onClick={this.onSelect}
				className={className}
			>
				<InstanceStatusDecorator
					id={"decorators" + this.props.index}
					key="decorators"
					instanceMgr={this.props.item}
					validations={this.props.validations}
				/>
				<ListItemText id="requirementText"
					primary={<Typography variant="subtitle2">{this.props.name}</Typography>} />

				{this.props.canCopy.enabled !== ActionEnabled.NEVER &&
					<Popup
						align="left"
						getContent={this.getCloneContent}
					>
						<ListItemIcon>
							<IconButton
								onClick={this.onClone}
								disabled={this.props.canCopy.enabled === ActionEnabled.NOT_NOW}
								className={"copyIcon"}
							>
								<ContentCopy style={commonStyles.smallIcon} />
							</IconButton>
						</ListItemIcon>
					</Popup>
				}
				{this.props.moveInstance && this.props.item instanceof ModuleInstanceMgr && numContexts > 1 &&
					< MoveInstanceButton
						getContextSelection={this.props.getContextSelection}
						moveInstance={this.props.moveInstance}
						isTopModuleOnContext={this.props.isTopModuleOnContext}
						mgr={this.props.item}
					/>
				}

				{this.props.canRemove.enabled !== ActionEnabled.NEVER &&
					< Popup
						align="left"
						getContent={this.getDeleteContent}
					>
						<ListItemIcon>
							<IconButton
								disabled={this.props.canRemove.enabled === ActionEnabled.NOT_NOW}
								onClick={this.onRemove}
								className={"deleteIcon"}
							>
								<DeleteOutline style={commonStyles.smallIcon} />
							</IconButton>
						</ListItemIcon>
					</Popup>
				}
			</ListItem>
		);
	}

	private onSelect = () => {
		this.props.select(this.props.item);
	}

	private onRemove = (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
		e.stopPropagation();
		this.props.remove(this.props.item);
	}

	private onClone = (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
		e.stopPropagation();
		this.props.copy(this.props.item);
	}

	private getCloneContent = (): any => {
		return this.props.canCopy.enabled === ActionEnabled.NOT_NOW &&
			<CannotDoActionPopup
				formatter={this.props.formatter}
				reason={this.props.canCopy.reason}
				type={"copy"}
			/>;
	}

	private getDeleteContent = () => {
		return this.props.canRemove.enabled === ActionEnabled.NOT_NOW &&
			<CannotDoActionPopup
				formatter={this.props.formatter}
				reason={this.props.canRemove.reason}
				type={"remove"}
			/>;
	}
}

const ItemImpl = withCommonStyles(StyledItem);

function Item<T extends InstanceMgr>(props: IListItemProps<T>) {
	return <ItemImpl {...props as any} />;
}

interface IProps<T extends InstanceMgr> {
	selectedTreeNode: AInstanceContainer<T>;
	formatter: IFormatter;
	validations: Validations;
	onSelect: (item: T) => void;
	canRemove: (item: T) => ActionState;
	onRemove: (item: T) => void;
	canCopy: (item: T) => ActionState;
	onCopy: (item: T) => void;
	getItemName: (item: T) => string;
	instruction?: JSX.Element;

	// moving instance to other runtime
	moveInstance: (item: InstanceMgr, contextName: string) => void;
	isTopModuleOnContext: (mgr: ModuleInstanceMgr, contextName: string) => boolean;
	getContextSelection(): UIContextSelection;
}

export const requirementsListStyle: React.CSSProperties = {
	overflowY: "auto",
	width: "100%",
	maxHeight: 200, // shows 5 entries before overflow
	padding: 0,
};

// Container for the entire list view
export function RequirementsList<T extends InstanceMgr>(
	{ selectedTreeNode,
		instruction,
		getItemName,
		formatter,
		onSelect,
		onRemove,
		canRemove,
		onCopy,
		canCopy,
		validations,
		getContextSelection,
		moveInstance,
		isTopModuleOnContext,
	}: IProps<T>) {
	const selectedMyListItem = selectedTreeNode.getSelectedMyListItem();
	const listItems: T[] = selectedTreeNode.getInstances();
	const showInstructions = listItems.length === 0;
	if (showInstructions) {
		return (
			<Instructions
				instruction={
					instruction ??
					<React.Fragment>
						Click the <b>Add</b> button to add a {selectedTreeNode.getDisplayName(false)} to your design
					</React.Fragment>
				}
			/>
		);
	}
	return (
		<div style={requirementsListStyle}>
			{
				_.map(listItems, (item, index) => {
					return (
						<Item
							key={item.getID()}
							name={getItemName(item)}
							index={index}
							item={item}
							isSelected={item === selectedMyListItem}
							formatter={formatter}
							select={onSelect}
							remove={onRemove}
							copy={onCopy}
							canCopy={canCopy(item)}
							canRemove={canRemove(item)}
							validations={validations}
							isTopModuleOnContext={isTopModuleOnContext}
							moveInstance={moveInstance}
							getContextSelection={getContextSelection}
						/>
					);
				})
			}
		</div>
	);
}

class Instructions extends React.PureComponent<{ instruction: JSX.Element }> {
	public override render() {
		return (
			<Typography variant="body2" style={{ textAlign: "center", width: "100%" }}>
				{this.props.instruction}
			</Typography>
		);
	}
}
