import React = require("react");
import * as _ from "lodash";
import { BasicModal } from "./modals/BasicModal";
import { Box, CircularProgress, ThemeProvider, Typography } from "../imports/material-ui-imports";
import { ATheme } from "./styles/themes";
import { useDelay } from "./customHooks";
import { useEffect, useState } from "react";
import { delay } from "../services/utils";

interface AsyncProgressModalProps<T> {
	operation: (setProgress: (progress: number) => void) => Promise<T>;
	resolve: (value: T | PromiseLike<T>) => void;
	reject: (value: T | PromiseLike<T>) => void;
	title: string;
	handleMountPointRef: (el: HTMLDivElement) => void
	theme: ATheme;

	// some operations may occur very quickly in which case we want to induce a slight delay to display this modal
	manualDelay?: boolean;
}
// This function needs to be implemented as a part of a promise (see what references this class)
// when the promise resolves it should unmount and close this modal
export function AsyncModalWithProgess<Result>(
	{ operation,
		resolve,
		reject,
		title,
		handleMountPointRef,
		theme,
		manualDelay,
	}: AsyncProgressModalProps<Result>
) {

	// Note that if the asynchronous function is very fast we'll get a flicker on the ui
	// since the modal service will open and then close immediately after
	// In this case we can schedule the modal service to run in 250ms
	// When we resolve or reject it will unmount the component which will in turn call clearTimeout
	// and not call the modal service and thus not give us the flicker
	const delayAmount = 250;
	const [showingModal, setDisplay] = useState<boolean>(false);
	useDelay(delayAmount, () => setDisplay(true));

	// setProgress is a callback which will be passed to operation
	// currently it is being passed to a button mgr onClickResult
	const [progress, setProgress] = useState<number>(0);
	useEffect(() => {
		const asyncEffect = async () => {
			const startTime = new Date();
			try {
				return await operation(setProgress);
			} finally {
				const endTime = new Date();
				const executionTime = endTime.getTime() - startTime.getTime();
				if (manualDelay && executionTime < delayAmount) {
					await delay(500 - executionTime);
				}
			}
		};
		asyncEffect().then(resolve, reject);
	}, [resolve, reject, operation, manualDelay]);

	// If the operation hasn't been executing for over >=250ms and progress hasn't been explicity set
	// then we don't want to show the modal
	if (!showingModal && progress === 0) {
		return <></>;
	}
	return (
		<ThemeProvider theme={theme.theme}>
			<BasicModal
				modalProps={{
					disableBackdropClick: true,
					disableEscapeKeyDown: true,
					open: true,
				}}
				title={title}
				registerSubModalMountPoint={handleMountPointRef}
				onClose={null}
				theme={theme}
			>
				<div style={{ textAlign: "center" }}>
					<CircularProgressBasedOnValue value={progress} />
				</div>
			</BasicModal>
		</ThemeProvider>
	);
}

function CircularProgressBasedOnValue({ value }: { value: number }) {
	if (value === 0) {
		return <CircularProgress variant="indeterminate" />;
	} else {
		return <CircularProgressWithLabel value={value} />;
	}
}

function CircularProgressWithLabel(
	{ value }: { value: number },
) {
	return (
		<Box style={{ position: "relative", display: "inline-flex" }}>
			<CircularProgress variant="determinate" value={value} />
			<Box
				style={{
					top: 0,
					left: 0,
					bottom: 0,
					right: 0,
					position: "absolute",
					display: "flex",
					alignItems: "center",
					justifyContent: "center",
				}}
			>
				<Typography
					variant="caption"
					component="div"
					color="textSecondary"
				>{`${Math.round(value)}%`}</Typography>
			</Box>
		</Box>
	);
}
