import * as _ from "lodash";
import React = require("react");
import { commonStyles } from "./styles/common";
import { CloseCircle, Alert, CheckCircle, InformationOutline } from "../imports/mdi-material-ui-imports";
import { Typography } from "../imports/material-ui-imports";
import { assertUnreachable } from "../services/utils";
import { Validations, ISummarizeable, ValidationSummary } from "../services/objectManagers/validations";

// A status decorator used to describe if an item/list is valid, or has errors or warnings
// Error decorator supersedes warnings; otherwise the success (or optionally empty icon) decorator will be displayed

export const enum StatusType {
	None,
	Error,				// show error status with error color
	Warning,			// show warning status with warning color
	SuppressedWarning,	// show warning status with neutral color
	Info,				// show info status with info color
	Success,			// show success status with with success color
}

export interface IStatusDecoratorProps {
	id: string;
	status: StatusType;
	containerStyle?: React.CSSProperties;  // CSS style for the container (ie; add extra padding/margin as needed)
}

export const StatusDecorator = React.memo(function StatusDecorator(props: IStatusDecoratorProps) {
	const containerStyle = props.containerStyle || {};

	switch (props.status) {
		case StatusType.None:
			return null;
		case StatusType.Error:
			return <CloseCircle
				id={props.id}
				key="error"
				className="svgIcon errorIcon"
				style={{ ...commonStyles.errorIcon, ...containerStyle }} />;
		case StatusType.SuppressedWarning:
			return <Alert
				id={props.id}
				key="suppressedWarning"
				className="svgIcon suppressedWarningIcon"
				style={{ ...commonStyles.neutralIcon, ...containerStyle }} />;
		case StatusType.Warning:
			return <Alert
				id={props.id}
				key="warning"
				className="svgIcon warningIcon"
				style={{ ...commonStyles.warningIcon, ...containerStyle }} />;
		case StatusType.Success:
			return <CheckCircle
				id={props.id}
				key="success"
				className="svgIcon successIcon"
				style={{ ...commonStyles.successIcon, ...containerStyle }} />;
		case StatusType.Info:
			return <InformationOutline
				id={props.id}
				key="success"
				className="svgIcon infoIcon"
				style={{ ...commonStyles.infoIcon, ...containerStyle }} />;
		default:
			assertUnreachable(props.status);
	}
});

interface INodeStatusDecoratorProps extends Omit<IStatusDecoratorProps, "status"> {
	summary: ValidationSummary;
	showSuccess?: boolean;
}

export const NodeStatusDecorator = React.memo(function NodeStatusDecorator(props: INodeStatusDecoratorProps) {
	const { summary, showSuccess, ...rest } = props;
	const status = ValidationSummary.Error === summary ? StatusType.Error :
		ValidationSummary.Warning === summary ? StatusType.Warning :
			showSuccess ? StatusType.Success : StatusType.None;

	return <StatusDecorator status={status} {...rest} />;
});

interface IInstanceStatusDecoratorProps extends Omit<IStatusDecoratorProps, "status"> {
	instanceMgr: ISummarizeable;
	validations: Validations;
}

export function InstanceStatusDecorator(props: IInstanceStatusDecoratorProps) {
	const { instanceMgr, validations, ...rest } = props;
	return <NodeStatusDecorator summary={validations.getSummary(instanceMgr)} showSuccess={true} {...rest} />;
}

interface ITextDecoratorProps {
	id: string;
	containerStyle: React.CSSProperties;
	text: string;
}

// error - display text with error color
// warning - display text with warning color
// success - display text with success color
// partial - display text with neutral color
// containerStyle - CSS style for the container (ie; add extra padding/margin as needed)
export const TextDecorator = React.memo(function TextDecorator({ id, containerStyle, text }: ITextDecoratorProps) {
	return (
		<span style={containerStyle ?? {}}>
			<Typography variant="body2" id={id} style={commonStyles.neutralText}>{text}</Typography>
		</span>
	);
});
