import { createFinalSvgPathNode } from "../createSvgPathNode";

// Triangular node, like a NOT gate without the circle.  Can represent a buffer or an analog comparator. 

export function bufferPath(width: number, height: number) {
	return "M 0 0 " 					// Start in top left corner
		+ `L ${width} ${height / 2} ` 	// Top of triangle to right side 1/2 way down
		+ `L 0 ${height} `				// Bottom of triangle to left side all the way down
		+ "V 0 Z"; 						// Vertical line back to the start and close
}

// Extra 5 as triangle may pinch on the label otherwise.  There will only ever be one output, so hight-based 
// adjustments aren't needed.

export const BufferNode = createFinalSvgPathNode(bufferPath, { outputLabelXOffset: () => -5 });
