import * as React from "react";
import { ConfirmModal } from "./ConfirmModal";
import { ExceptionText } from "../ExceptionText";
import { IModalMinProps } from "./BasicModal";
import { Typography } from "../../imports/material-ui-imports";

interface IErrorModalProps extends IModalMinProps {
	error: Error;
	onClose: () => void;
	title: string;
	id?: string;
	cancelText?: string;
	confirmText?: string;
	onConfirm?: () => void;
	content?: string;
}

export class ErrorModal extends React.Component<IErrorModalProps> {
	public override render() {
		const { error, onClose, title, id, cancelText, confirmText, onConfirm, content, ...rest } = this.props;
		return (
			<ConfirmModal
				{...rest}
				title={title}
				id={id}
				cancelAction={onClose}
				cancelText={cancelText ?? "Go Back"}
				confirmText={confirmText}
				type={"Error"}
				confirmAction={onConfirm}
			>
				{error &&
					<ExceptionText theme={this.props.theme} exception={error} />
				}
				{content &&
					<Typography variant="body2" style={{ whiteSpace: "pre" }}>
						{content}
					</Typography>
				}
			</ConfirmModal>
		);
	}
}
