import * as _ from "lodash";
import * as React from "react";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { HardwareMemberMgr } from "../../../services/objectManagers/hardwareMember";
import { DropDown } from "../../DropDown";
import { CBaseEnumConfigurable } from "./BaseEnumConfigurable";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { ILinkActions } from "../../actions/ILinkActions";

interface Props {
	formatter: IFormatter;
	mgr: HardwareMemberMgr;
	actions: IConfigurablesActions & ILinkActions;
	displayScriptName: boolean;
}

export class CHardware extends CBaseEnumConfigurable<Props> {
	public override render() {

		const mgr = this.props.mgr;

		const selectedValue = mgr.getValue();
		const { enabledOptions, disabledOptions } = mgr.getUIOptions();
		const selectedOptionName = _.find(enabledOptions, (o) => o.component === selectedValue).name;

		return (
			<DropDown
				id={mgr.def.name}
				disabled={!!mgr.uiState.readOnly}
				selectedOptionName={selectedOptionName}
				enabledOptions={this.formatOptions(enabledOptions)}
				disabledOptions={this.formatOptions(disabledOptions)}
				onChange={(selectedOption) => {
					const option = _.find(enabledOptions, (o) => o.name === selectedOption);
					this.props.actions.setConfigurableValue(mgr, option.component);
				}}
				key={this.state.key}	// Force re-render (closing drop down) when navigating away via tooltip
				displayScriptName={this.props.displayScriptName}
			/>
		);
	}
}
