import * as _ from "lodash";
import { ValidationSummary } from "../../../services/objectManagers/validations";
import { assertUnreachable } from "../../../services/utils";
import { applyDisabled, applyError, applyFiltered, applyGrabbing, applySelected, applyUnused, applyWarning } from "../styling/applyStyles";
import { ClassesType } from "../styling/graphStyles";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import * as Layout from "../types/layoutTypes";
import { IUnStyledNodeProps } from "./Node";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

export function applyNodeStyles<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>({
	node,
	displayScriptName,
	searchText,
	disabledInstances,
	usedInstances,
	classes,
	validations,
	selected,
	grabbing,
}: IUnStyledNodeProps<InstMgr, PortMgr>
) {
	// Error trumps warnings trumps disabled trumps unused
	// Filtered and selected are applied additively

	const styledClasses = applyAdditiveStyles(selected, searchText, node, displayScriptName, grabbing, classes);
	const summary = validations?.getSummary(node.inst) ?? ValidationSummary.None;
	switch (summary) {
		case ValidationSummary.Error:
			return applyError(styledClasses);
		case ValidationSummary.Warning:
			return applyWarning(styledClasses);
		case ValidationSummary.None:
			if (_.includes(disabledInstances, node.id)) {
				return applyDisabled(styledClasses);
			} else if (!_.includes(usedInstances, node.id)) {
				return applyUnused(styledClasses);
			}
			return styledClasses;
		default:
			assertUnreachable(summary);
	}
}

function applyAdditiveStyles<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	selected: boolean,
	searchText: string,
	node: Layout.Node<InstMgr, PortMgr>,
	displayScriptName: boolean,
	grabbing: boolean,
	classes: ClassesType["classes"],
) {
	if (!_.isEmpty(searchText) &&
		!node.inst.getGraphLabel(displayScriptName).toLowerCase().includes(searchText.toLowerCase())) {
		classes = applyFiltered(classes);
	}
	if (selected) {
		classes = applySelected(classes);
	}
	if (grabbing) {
		classes = applyGrabbing(classes);
	}
	return classes;
}
