import * as _ from "lodash";
import React = require("react");
import { Popup } from "./Popup";
import DeviceData = require("dataInterfaces");
import { HeaderPin } from "public/defs";
import { PinInfo } from "../services/pinInfo";
import { pinColors } from "./styles/colors";
import { Circle, RecordCircle } from "../imports/mdi-material-ui-imports";
import { Typography } from "../imports/material-ui-imports";
import { commonStyles } from "./styles/common";
import { defaultFontSize, ATheme, ColorIndex } from "./styles/themes";
import { DEVICE_PIN_TO_PIN_TYPE, PinType, PIN_FIXED } from "../services/devicePinviews/devicePinTypes";

export type Placement = "top" | "bottom" | "left" | "right";

interface ILabelEntryProps {
	label: string;			// label text
	fullWidth?: boolean;	// override default (max) width of the label to expand to full width
	placement?: Placement;	// placement with respect to a pin (ie; use left to place a label to the left of a pin)
	horizontal?: boolean;	// determine if this entry needs to be inline
}

// draws one label entry
export class BoardViewLabelEntry extends React.Component<ILabelEntryProps> {
	public override render() {
		return (
			<li style={this.getOuterStyle()}>
				<Typography variant="body2" style={this.getInnerStyle()}>{this.props.label || "\u00A0"}</Typography>
			</li>
		);
	}

	// set the width and height of the entry
	private getOuterStyle() {
		let style: React.CSSProperties = {
			minWidth: defaultFontSize * 2 - 2,
			height: defaultFontSize * 2 - 2,
			verticalAlign: "middle",
		};

		// override the default width to expand as needed
		if (this.props.fullWidth) {
			style = {
				...style,
				width: "auto",
			};
		}
		// inline the block so that it aligns with other <li> horizontally
		if (this.props.horizontal) {
			style = {
				...style,
				display: "inline-block",
			};
		}
		return style;
	}

	// set the colour, font, and alignment of the label
	private getInnerStyle() {
		let style: React.CSSProperties = {
			color: "#999",
			width: "100%",
			height: "100%",
			fontSize: "9px",
			display: "flex",
		};

		// set alignItems and justifyContent depending on how we want to align the label
		if (this.props.placement === "left") {
			style = {
				...style,
				alignItems: "center",
				justifyContent: "flex-end",
				paddingRight: "6px",
			};
		} else if (!this.props.placement || this.props.placement === "right") {
			style = {
				...style,
				alignItems: "center",
				justifyContent: "flex-start",
				paddingLeft: "6px",
			};
		} else if (this.props.placement === "top") {
			style = {
				...style,
				alignItems: "flex-end",
				justifyContent: "center",
				paddingBottom: "3px",
			};
		} else if (this.props.placement === "bottom") {
			style = {
				...style,
				alignItems: "flex-start",
				justifyContent: "center",
				paddingTop: "3px",
			};
		}
		return style;
	}
}

// draws a empty entry (with set width and height to align other entries)
// wraps the LabelEntry implementation and uses an empty label
export class BoardViewEmptyEntry extends React.Component<{
	horizontal: boolean;
}> {
	public override render() {
		return (
			<BoardViewLabelEntry label="&nbsp;" horizontal={this.props.horizontal} />
		);
	}
}

interface IBoardViewEntryProps {
	theme: ATheme;
	top: boolean;			// draw a border at the top of the entry
	bottom: boolean;		// draw a border at the bottom of the entry
	left: boolean;			// draw a border at the left of the entry
	right: boolean;		// draw a border at the right of the entry
	selected: boolean;		// pin is selected (based on selected tree entry)
	currentlySelected: boolean; // pin is currently selected
	fixed: boolean;		// pin is fixed (n/a)
	inUse: boolean;		// pin is in used
	shared: boolean;		// pin is shared because allow pin conflict
	hasHardware: boolean;	// hardware is attached to pin
	horizontal?: boolean;	// horizontal orientation of the pin
	reserved: boolean; 	// pin is reserved
	fixedWidth?: boolean;   // fixed width or not
	getTooltip: () => JSX.Element;
	onClick: () => void;
	pinName: string;
}

interface IBoardViewState {
	hover: boolean;			// pin is currently hovered over
}

// draws one pin entry
class BoardViewPinEntry extends React.Component<IBoardViewEntryProps, IBoardViewState> {
	constructor(props: IBoardViewEntryProps, context: any) {
		super(props, context);
		this.state = {
			hover: false,
		};
	}

	public override render() {
		const pinStyle: React.CSSProperties = {
			...commonStyles.smallIcon,
			position: "relative",
			top: 1,
		};
		return (
			<li
				id={this.props.pinName}
				style={this.getOuterStyle()}
				onMouseEnter={this.onMouseEnter}
				onMouseLeave={this.onMouseLeave}
				onClick={this.props.onClick}
			>
				<Popup
					align="left"
					alignOffset={0.75}
					getContent={this.props.getTooltip}

				>
					<div style={this.getInnerStyle()}>
						{this.props.hasHardware ?
							<RecordCircle style={pinStyle} />
							:
							<Circle style={pinStyle} />
						}
					</div>
				</Popup>
			</li>
		);
	}

	private onMouseEnter = () => this.setState({ hover: true });

	private onMouseLeave = () => this.setState({ hover: false });

	// controls the size, border, shadow, and colour
	private getOuterStyle() {
		let style: React.CSSProperties = {
			padding: 0,
			margin: "0",
			cursor: "pointer",
			textAlign: "center",
			verticalAlign: "middle",
			color: "#777",
			backgroundColor: this.props.theme.colors[ColorIndex.PINBACKGROUNDCOLOR],
			height: defaultFontSize * 2 - 2,
			...this.getBoarderStyle(),
			...this.getBorderRadiusStyle(),
		};

		// box shadow style
		if (this.props.right || this.props.bottom) {
			style = { ...style, boxShadow: "2px 2px 2px #bbb" };
		}

		// highlight style
		if (this.props.fixed) {
			style = { ...style, color: pinColors.fixed };
		} else if (this.props.shared) { // this check needs to be before inUse
			style = { ...style, color: pinColors.shared };
		} else if (this.props.reserved) {// this check needs to be before inUse
			style = { ...style, color: pinColors.reserved };
		} else if (this.props.inUse) {
			style = { ...style, color: pinColors.used };
		}

		if (this.props.currentlySelected) {
			style.stroke = this.props.theme.colors[ColorIndex.SELECTEDPINSTROKECOLOR];
			style.color = this.props.shared ? pinColors.highlightedShared : pinColors.highlightedUsed;
			style.strokeWidth = 2;
		}

		if (this.props.horizontal) {
			style = { ...style, display: "inline-block" };
		}
		style = this.props.fixedWidth ?
			{ ...style, width: defaultFontSize * 2 - 2 } : { ...style, minWidth: defaultFontSize * 2 - 2 };

		return style;
	}

	private getBorderRadiusStyle() {
		const borderRadiusDef = "4px ";
		let borderRadiusTL = "0 ";
		let borderRadiusTR = "0 ";
		let borderRadiusBR = "0 ";
		let borderRadiusBL = "0 ";

		// border radius style
		if (this.props.top && this.props.left) {
			borderRadiusTL = borderRadiusDef;
		}
		if (this.props.top && this.props.right) {
			borderRadiusTR = borderRadiusDef;
		}
		if (this.props.bottom && this.props.right) {
			borderRadiusBR = borderRadiusDef;
		}
		if (this.props.bottom && this.props.left) {
			borderRadiusBL = borderRadiusDef;
		}
		return { borderRadius: borderRadiusTL + borderRadiusTR + borderRadiusBR + borderRadiusBL };
	}

	private getBoarderStyle() {
		const borderStyleText = "2px solid #777";
		let style = {};
		if (this.props.top) {
			style = { borderTop: borderStyleText };
		}
		if (this.props.bottom) {
			style = { ...style, borderBottom: borderStyleText };
		}
		if (this.props.left) {
			style = { ...style, borderLeft: borderStyleText };
		}
		if (this.props.right) {
			style = { ...style, borderRight: borderStyleText };
		}
		return style;
	}

	// controls the background colour
	private getInnerStyle() {
		let style: React.CSSProperties = {
			width: "100%",
			height: "100%",
			fontSize: "12px",
			textAlign: "center",
		};

		if (this.state.hover) {
			style = { ...style, backgroundColor: this.props.theme.colors[ColorIndex.PINHOVERBGCOLOR] };
		} else if (this.props.selected) {
			style = { ...style, backgroundColor: this.props.theme.colors[ColorIndex.PINSELECTEDBGCOLOR] };
		} else {
			style = { ...style, backgroundColor: this.props.theme.colors[ColorIndex.PINBACKGROUNDCOLOR] };
		}
		return style;
	}
}

const tooltipContainerStyle: React.CSSProperties = {
	margin: "2px 6px",
	fontSize: defaultFontSize - 1,
};

const rowStyle: React.CSSProperties = {
	verticalAlign: "top",
};

const successRowStyle: React.CSSProperties = {
	...rowStyle,
	color: "#49b653",
};

const col1CellStyle: React.CSSProperties = {
	whiteSpace: "nowrap",
	paddingRight: 2,
};

const titleCellStyle: React.CSSProperties = {
	textDecoration: "underline",
};

const col1TitleCellStyle: React.CSSProperties = {
	...col1CellStyle,
	...titleCellStyle,
};

// BoardViewPinEntry wrapper with device pin/header pin information
export class BoardViewDevicePinEntry extends React.Component<{
	theme: ATheme;
	devicePin: DeviceData.DevicePin;
	pinInfo: PinInfo;
	shouldShowModeTable: boolean;
	headerPin?: HeaderPin;
	top: boolean;
	bottom: boolean;
	left: boolean;
	right: boolean;
	horizontal?: boolean;
	fixedWidth?: boolean;
	boardNumberOffset?: number;
}, IBoardViewState> {
	public override render() {
		let pinType: PinType = PIN_FIXED;
		if (this.props.devicePin) {
			pinType = DEVICE_PIN_TO_PIN_TYPE[this.props.devicePin.devicePinType];
		}
		return (
			<BoardViewPinEntry
				{...this.props}
				theme={this.props.theme}
				pinName={this.getName()}
				currentlySelected={
					this.props.pinInfo.isPinCurrentlySelected(
						this.props.devicePin?.name,
					)}
				selected={this.props.pinInfo.isPinSelected(this.props.devicePin, this.props.headerPin)}
				reserved={this.props.pinInfo.isPinReserved(this.props.devicePin)}
				inUse={this.props.pinInfo.isPinInUse(this.props.devicePin)}
				shared={this.props.pinInfo.isPinShared(this.props.devicePin)}
				fixed={(!!this.props.headerPin && !this.props.headerPin.ball) || (pinType === PIN_FIXED)}
				hasHardware={!_.isEmpty(this.props.pinInfo.getAssociatedComponentsList(this.props.devicePin, this.props.headerPin))}
				getTooltip={this.getTooltip}
				onClick={this.onClick}
			/>
		);
	}

	private onClick = () => {
		this.props.pinInfo.navigateTo(this.props.devicePin);
	}

	private getTooltip = () => {
		return (
			<div style={tooltipContainerStyle}>
				<table>
					<tbody>
						{
							_.map(this.props.pinInfo.getTooltip(this.props.shouldShowModeTable, this.props.devicePin,
								this.props.headerPin, this.props.boardNumberOffset),
								(entry, index) => {
									return (
										<tr key={index} style={entry.success ? successRowStyle : rowStyle}>
											<td style={entry.title ? col1TitleCellStyle : col1CellStyle}>{entry.col1}</td>
											<td style={entry.title ? titleCellStyle : {}}>
												{
													_.map(entry.col2, (curCol2Content, index2) => {
														if (entry.col2.length > 1) {
															return <span key={index2}>{curCol2Content}<br /></span>;
														} else {
															return curCol2Content;
														}
													})
												}
											</td>
										</tr>
									);
								})
						}
					</tbody>
				</table>
			</div>
		);
	}

	private getName() {
		if (this.props.headerPin) {
			return this.props.headerPin.name;
		} else if (this.props.devicePin) {
			return this.props.devicePin.name;
		}
		return null;
	}
}
