import React = require("react");
import { IProcess } from "../../services/IProcess";
import { ProgressBar } from "../ProgressBar";
import { IModalMinProps } from "./BasicModal";

export interface ITerminalProps extends IModalMinProps {
	id: string;
	title: string;
	confirmAction: () => void;
	confirmText?: string;
	command: string;
	args: string[];
	process: IProcess;
}
interface IState {
	Terminal: React.ComponentClass<ITerminalProps>;
}
export class LazyLoadedTerminal extends React.Component<ITerminalProps, IState> {
	public override state: IState = { Terminal: null };

	public override componentDidMount() {
		require.ensure([], () => {
			this.setState({ Terminal: require("./TerminalModal") });
		}, () => { }, "LazyTerminal");
	}

	public override render() {
		if (this.state.Terminal) {
			return (< this.state.Terminal {...this.props} />);
		} else {
			return (
				<ProgressBar title={"Loading Terminal..."} />
			);
		}
	}
}
