/**
 * Manhattan distance. (https://en.wikipedia.org/wiki/Taxicab_geometry)
 * This calculates the distance on a square grid with equal movement cost.  This is simpler
 * than say a euclidean distance which would calculate the hypotenuse 
 * @param {number} dx - Difference in x.
 * @param {number} dy - Difference in y.
 * @return {number} dx + dy
 */
export function manhattan(dx: number, dy: number) {
	return dx + dy;
}

export type Point = [x: number, y: number];

/**
 * Compress a path, remove redundant nodes without altering the shape
 * The original path is not modified
 * @param {Array<Array<number>>} path The path
 * @return {Array<Array<number>>} The compressed path
 */
export function compressPath(path: Point[]) {

	// nothing to compress
	if (path.length < 3) {
		return path;
	}

	const compressed: Point[] = [],
		sx = path[0][0], // start x
		sy = path[0][1]; // start y
	let px = path[1][0], // second point x
		py = path[1][1], // second point y
		dx = px - sx, // direction between the two points
		dy = py - sy, // direction between the two points
		lx, ly,
		ldx, ldy,
		sq, i;

	// normalize the direction
	sq = Math.sqrt(dx * dx + dy * dy);
	dx /= sq;
	dy /= sq;

	// start the new path
	compressed.push([sx, sy]);

	for (i = 2; i < path.length; i++) {

		// store the last point
		lx = px;
		ly = py;

		// store the last direction
		ldx = dx;
		ldy = dy;

		// next point
		px = path[i][0];
		py = path[i][1];

		// next direction
		dx = px - lx;
		dy = py - ly;

		// normalize
		sq = Math.sqrt(dx * dx + dy * dy);
		dx /= sq;
		dy /= sq;

		// if the direction has changed, store the point
		if (dx !== ldx || dy !== ldy) {
			compressed.push([lx, ly]);
		}
	}

	// store the last point
	compressed.push([px, py]);

	return compressed;
}

export const enum Walkable {
	Never,			// Edges can never go through this node
	Always,			// Edges can always go through this node
	UpDownOnly,		// Edges can only go here if moving up or down (prevents overlaps, but allows crossing)
	LeftRightOnly,	// Edges can only go here if moving left or right (prevents overlaps, but allows crossing)
	StartOnly,		// Edges may only start here (start may move to another start, but other cases will never be returned as a neighbour)
	EndOnly,		// Edges may only end here (always returned as a neighbour, but will never return neighbours that aren't ends)
}
