import * as _ from "lodash";
import * as path from "path";
import { ModuleCategory, ProductComponent, TemplateInfo, MetaViewInfo, ReferenceInfo, TreeCategory } from "public/defs";
import { Product } from "./types";
import { ResourceLoader, NoSuchResourceError, ResourceType, toCanonicalPath } from "../resources/metaContentLoaders/resourceLoader";
import { AbsolutePath } from "public/common";
import { CodeGenTemplateFile, ReferenceFile, MetaViewTemplateFile, AdaptedDeviceInfo } from "dataInterfaces";
import { SCHEMA, validateMeta } from "../JSONschemaValidator";
import { getDisplayName, getDuplicates } from "../utils";
import { filterProductsByContext } from "../contexts";
import { FrequencyFormat } from "../objectManagers/configurables/pinFrequencyConfigurableMgr";
import { SimulationEntry } from "../simulation/simulationTreeNode";
import { TProbe } from "public/runtime";

// local internal interface for information extracted from a product component
interface ComponentInfo {
	moduleNames: { [modName: string]: string };
	categories: ModuleCategory[];
	templates: CodeGenTemplateFile[];
	views: MetaViewTemplateFile[];
	references: ReferenceFile[];
	clockTreeMap: { [ipName: string]: string };
	clockTreeCategories: TreeCategory[];
	frequencyFormat: Partial<FrequencyFormat>;
	clockTreeStaticConfig?: string;
	graphableStaticConfig?: string;
	permittedProbeTypes?: TProbe[];
	initialView?: string;
	alwaysPresent: string[];
	simulations: SimulationEntry[];
}

const defaultFrequencyFormat: FrequencyFormat = {
	defaultUnit: "MHz",
	precision: 4,
};

// Abstracts top modules, templates and system-level functions
export class TopModules {

	private readonly moduleNames: { [modName: string]: string };
	private readonly categories: ModuleCategory[];
	private readonly templates: CodeGenTemplateFile[];
	private readonly views: MetaViewTemplateFile[];
	private readonly references: ReferenceFile[];
	private readonly clockTreeMap: { [ipName: string]: string };
	private readonly clockTreeCategories: TreeCategory[];
	private readonly frequencyFormat: FrequencyFormat;
	private readonly clockTreeStaticConfig?: string;
	private readonly graphableStaticConfig?: string;
	private readonly initialView?: string;
	private readonly alwaysPresent: string[];
	private readonly simulations: SimulationEntry[];
	private readonly permittedProbeTypes: TProbe[];

	constructor(
		products: Product[],
		resourceLoader: ResourceLoader,
		ccxxImageMode: boolean,
		context: string,
		deviceData: AdaptedDeviceInfo
	) {

		const componentInfo: ComponentInfo = {
			moduleNames: {},
			categories: [],
			templates: [],
			views: [],
			references: [],
			clockTreeMap: {},
			clockTreeCategories: [],
			frequencyFormat: {},
			alwaysPresent: [],
			simulations: [],
		};

		// Filter out products that don't support this context

		products = filterProductsByContext(products, context, deviceData);

		// Process the remaining products
		// If we can't find any components in a product file wait till the end to log a warning
		const missingComponents: string[] = [];

		_.each(products, (product) => {
			processComponent(product.file, componentInfo, getDisplayName(product.file, false), path.dirname(product.file.path));
			_.each(product.file.components, (componentName) => {
				try {
					componentName = toCanonicalPath(componentName, ResourceType.CODE);
					const component = resourceLoader.getResource(componentName, ResourceType.CODE) as ProductComponent;

					if (ccxxImageMode === !!component.ccxxImageComponent) {
						validate(component, componentName);
						processComponent(
							component,
							componentInfo,
							component.displayName || componentName,
							path.dirname(product.file.path),
						);
					}

				} catch (e) {
					if (e instanceof NoSuchResourceError) {
						// in some variants (mainly during development) of the product
						// some components may be missing
						missingComponents.push(e.fullPath);
					} else {
						throw e;
					}
				}
			});
		});

		if (!_.isEmpty(missingComponents)) {
			console.warn("Ignoring the following missing components: " + missingComponents.join(", "));
		}

		this.moduleNames = componentInfo.moduleNames;
		this.categories = mergeModuleCategories(componentInfo.categories);
		this.templates = componentInfo.templates;
		this.views = componentInfo.views;
		this.references = componentInfo.references;
		this.clockTreeMap = componentInfo.clockTreeMap;
		this.clockTreeCategories = mergeClockTreeCategories(componentInfo.clockTreeCategories);
		this.frequencyFormat = {
			...defaultFrequencyFormat,
			...componentInfo.frequencyFormat,
		};
		this.clockTreeStaticConfig = componentInfo.clockTreeStaticConfig;
		this.graphableStaticConfig = componentInfo.graphableStaticConfig;
		this.permittedProbeTypes = componentInfo.permittedProbeTypes;
		this.initialView = componentInfo.initialView;
		this.alwaysPresent = componentInfo.alwaysPresent;
		this.simulations = componentInfo.simulations;

		this.checkForDuplicates();
	}

	public getTemplates() {
		return this.templates;
	}

	public getViews() {
		return this.views;
	}

	public getReferences() {
		return this.references;
	}

	public getModuleNames() {
		return _.values(this.moduleNames);
	}

	public isTopModule(moduleName: string) {
		return moduleName in this.moduleNames;
	}

	public getModuleCategories(): ModuleCategory[] {
		return this.categories;
	}

	public getClockTreeMap() {
		return this.clockTreeMap;
	}

	public getClockTreeCategories() {
		return this.clockTreeCategories;
	}

	public getFrequencyFormat() {
		return this.frequencyFormat;
	}

	public getClockTreeStaticConfig() {
		return this.clockTreeStaticConfig;
	}

	public getGraphableStaticConfig() {
		return this.graphableStaticConfig;
	}

	public getPermittedProbeTypes(): TProbe[] {
		return this.permittedProbeTypes;
	}

	public getInitialView() {
		return this.initialView;
	}

	public getAlwaysPresentModules() {
		return this.alwaysPresent;
	}

	public getSimulations() {
		return this.simulations;
	}

	private checkForDuplicates() {
		// We want to guard against accidentally declaring templates more than once as most likely 
		// it's a copy/paste error.  However, it's also possible that radically different templates
		// are needed based on an option, so it's perfectly valid to have different templates 
		// generate the same file, as long as it's not at the same time.  Ideally, this would be
		// hidden behind a top level template, but existing legacy products are just using 
		// different templates and pull them in separately (z_stack).  As such, we can only guard
		// against "always run" templates.
		// Note: name is output location, path is canonical name
		ensureUnique(_.filter(this.templates, (t) => t.alwaysRun), "name", "templates");

		// Views and references are simpler 
		ensureUnique(this.views, "displayName", "views");
		ensureUnique(this.references, "path", "references"); // path is output location

		const duplicates = getDuplicates(this.alwaysPresent, (i) => i);
		if (!_.isEmpty(duplicates)) {
			throw new Error(`The following always present modules are declared more than once: ${duplicates}`);
		}
	}
}

function ensureUnique<T extends Record<K, string>, K extends keyof any>(arr: T[], memberName: K, collectionName: string) {
	const duplicates = getDuplicates(arr, (i) => i[memberName]);
	if (!_.isEmpty(duplicates)) {
		throw new Error(`The following ${collectionName} are declared more than once: ${duplicates}`);
	}
}

function isCategoryArray<T>(val: string[] | T[]): val is T[] {
	return !_.isEmpty(val) && _.isObject(val[0]);
}

function adaptToModuleCategory(modules: AbsolutePath[] | ModuleCategory[], defaultCategoryName: string): ModuleCategory[] {

	if (!modules) {
		return [];
	}

	if (isCategoryArray(modules)) {
		return _.map(modules, (category) => {
			return {
				...category,
				modules: _.map(category.modules, (m) => toCanonicalPath(m, ResourceType.CODE)),
				categories: adaptToModuleCategory(category.categories, defaultCategoryName),
			};
		});
	} else {
		return [
			{
				displayName: defaultCategoryName,
				modules: _.map(modules, (m) => toCanonicalPath(m, ResourceType.CODE)),
			}];
	}
}

function adaptTemplate(templates: TemplateInfo[], category: string): CodeGenTemplateFile[] {
	return _.map(templates, (t) => {
		return {
			name: t.outputPath,
			path: toCanonicalPath(t.name, ResourceType.TEMPLATE),
			category,
			alwaysRun: t.alwaysRun,
			ignoreErrors: t.ignoreErrors,
			excludable: true,
			isExecutable: t.isExecutable,
		};
	});
}

function adaptView(views: MetaViewInfo[]): MetaViewTemplateFile[] {
	return _.map(views, (v) => {
		return {
			displayName: v.displayName,
			path: toCanonicalPath(v.name, ResourceType.CODE),
			viewType: v.viewType,
			ignoreErrors: v.ignoreErrors,
			icon: v.icon ?? "file-outline",
		};
	});
}

function adaptReference(references: ReferenceInfo[], category: string, productPath: string): ReferenceFile[] {
	return _.map(references, (r) => {
		return {
			name: r.path,
			path: path.join(productPath, r.path),
			category,
			alwaysInclude: r.alwaysInclude,
			iarPath: r.iarPath,
		};
	});
}

function getModuleNames(categories: ModuleCategory[]): string[] {
	return (
		_.flatMap(categories, (m) => [
			...(_.map(m.modules, (name) => toCanonicalPath(name, ResourceType.CODE))),
			...getModuleNames(m.categories),
		])
	);
}

// Categories with the same displayName are grouped. Their
// modules and categories are merged by concatenating. The description
// and any other properties are set to the first defined in the group.
// The merged categories are further merged recursively using the
// same algorithm
function mergeCategories<T extends { displayName: string, categories?: T[] }>(
	unMergedCategories: T[],
	mergeEntries: (mergedSoFar: T, next: T) => Partial<T>) {

	const group = _.groupBy(unMergedCategories, (c) => c.displayName);
	if (_.size(group) === _.size(unMergedCategories)) { // nothing to merge, return the categories
		return unMergedCategories;
	}

	// merge all grouped

	return _.chain(group)
		.map((grouped) => {
			return _.reduce<T, T>(grouped,
				(mergedSoFar, next) => {
					const categories = [
						...mergedSoFar.categories,
						...(next.categories ?? []),
					];
					return {
						...next,
						...mergedSoFar,
						categories,
						...mergeEntries(mergedSoFar, next),
					};
				},
				{
					...grouped[0],
					categories: [],
				});
		})

		// further merge sub categories

		.each((m) => {
			m.categories = mergeCategories(m.categories, mergeEntries);
		})
		.value();
}

function mergeClockTreeCategories(unMergedCategories: TreeCategory[]) {
	return mergeCategories(unMergedCategories, (mergedSoFar, next) => {
		const entries = _.uniqBy([
			...mergedSoFar.entries ?? [],
			...next.entries ?? [],
		], (e) => e.displayName);
		return { entries };
	});
}

function mergeModuleCategories(unMergedCategories: ModuleCategory[]) {
	return mergeCategories(unMergedCategories, (mergedSoFar, next) => {
		const modules = _.uniq([
			...mergedSoFar.modules ?? [],
			...next.modules ?? [],
		]);
		return { modules };
	});
}

function processComponent(
	c: ProductComponent,
	componentInfo: ComponentInfo,
	categoryName: string,
	productPath: string
) {
	const categories = adaptToModuleCategory(c.topModules, categoryName);
	componentInfo.categories.push(...categories);

	_.each(getModuleNames(categories), (m) => componentInfo.moduleNames[m] = m);

	componentInfo.templates.push(...adaptTemplate(c.templates, categoryName));

	componentInfo.views.push(...adaptView(c.views));

	componentInfo.references.push(...adaptReference(c.references, categoryName, productPath));

	processClockTreeInfo(componentInfo, c);

	if (c.graphable?.staticConfiguration) {
		if (componentInfo.graphableStaticConfig) {
			throw new Error("'graphable.staticConfiguration' is declared in multiple component files");
		}
		componentInfo.graphableStaticConfig = c.graphable?.staticConfiguration;
	}

	if (c.graphable?.permittedProbeTypes) {
		if (componentInfo.permittedProbeTypes) {
			throw new Error("'graphable.permittedProbeTypes' is declared in multiple component files");
		}
		componentInfo.permittedProbeTypes = c.graphable?.permittedProbeTypes;
	}

	componentInfo.alwaysPresent.push(..._.map(c.alwaysPresent, (m) => toCanonicalPath(m, ResourceType.CODE)));

	if (!_.isEmpty(c.simulations)) {
		if (!_.isEmpty(componentInfo.simulations)) {
			throw new Error("'simulations' is declared in multiple component files");
		}
		componentInfo.simulations = _.map(c.simulations, (simulation) => ({ simulation, productPath }));
	}

	return componentInfo;
}

function processClockTreeInfo(componentInfo: ComponentInfo, c: ProductComponent) {
	componentInfo.clockTreeMap = {
		...c.clockTree?.typeMap,
		...componentInfo.clockTreeMap,
	};

	componentInfo.clockTreeCategories.push(...(c.clockTree?.tree ?? []));

	if (componentInfo.frequencyFormat.defaultUnit && c.clockTree?.defaultUnit) {
		throw new Error("'clockTree.defaultUnit' is declared in multiple component files");
	}
	if (_.isNumber(c.clockTree?.precision)) {
		if (componentInfo.frequencyFormat.precision && c.clockTree.precision) {
			throw new Error("'clockTree.precision' is declared in multiple component files");
		}
		if (!_.isInteger(c.clockTree.precision)) {
			throw new Error(`Expected integer value for 'clockTree.precision' but got ${c.clockTree.precision}`);
		}
		if (0 >= c.clockTree.precision) {
			throw new Error(`Expected 1 or greater value for 'clockTree.precision' but got ${c.clockTree.precision}`);
		}
	}
	componentInfo.frequencyFormat = {
		...componentInfo.frequencyFormat,
		..._.pick(c.clockTree, ["precision", "defaultUnit"]),
	};

	if (c.clockTree?.staticConfiguration) {
		if (componentInfo.clockTreeStaticConfig) {
			throw new Error("'clockTree.staticConfiguration' is declared in multiple component files");
		}
		componentInfo.clockTreeStaticConfig = c.clockTree?.staticConfiguration;
	}

	if (c.clockTree?.initialView) {
		if (componentInfo.initialView) {
			throw new Error("'clockTree.initialView' is declared in multiple component files");
		}
		componentInfo.initialView = c.clockTree?.initialView;
	}
}

function validate(component: ProductComponent, componentName: string) {
	validateMeta(component, componentName, SCHEMA.ProductComponent);
}

export function recursiveFindTopModuleCategory(moduleCat: ModuleCategory[], moduleName: string): string {
	for (const cat of moduleCat) {
		if (_.includes(cat.modules, moduleName)) {
			return cat.displayName;
		} else if (!_.isEmpty(cat.categories)) {
			const found = recursiveFindTopModuleCategory(cat.categories, moduleName);
			if (found) {
				return found;
			}
		}
	}
	return "";
}
