import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../../graph/styling/graphStyles";
import { LabeledConnectionNode } from "../../graph/nodes/LabeledConnectionNode";
import { FrequencyLabelNode } from "./FrequencyLabelNode";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";
import { INodeProps } from "../../graph/types/nodeTypes";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";

// Either a label on a connection, or a box with the current frequency embedded in it

interface IProps extends INodeProps<ClockIpInstanceMgr, PinFrequencyConfigurableMgr> {
	frequencyLabels: string[];
}

export function NamedConnectionNode({ frequencyLabels, ...rest }: IProps & ClassesType) {
	if (_.includes(frequencyLabels, rest.node.inst.getName())) {
		return <FrequencyLabelNode {...rest} />;
	}
	return <LabeledConnectionNode {...rest} />;
}
