import * as _ from "lodash";
import { ModuleInstanceMgr } from "./moduleInstance";
import { Runtime } from "../resources/runtime";
import { ModuleMgr } from "../instanceContainers/module";
import { createAddModuleStatement } from "../scripting/serialize";
import { InstanceArgs } from "public/defs";
import { guardScriptingFunction } from "../scripting/scriptingGuard";
import { ModuleInstanceFactory, ModuleInstance } from "public/runtime";
import { NameMemberMgr } from "./name";
import { splitViewNodes, StaticContainerNode, ViewNode } from "./viewNodes";
import { adaptToModule } from "../product/adaptToModule";
import { AnyMemberMgr, SetSource } from "./member";
import { TabGroup } from "./tabGroup";
import { ActionEnabled, ActionState } from "../IMyListItem";

export class StaticModuleInstanceMgr extends ModuleInstanceMgr<ModuleInstanceFactory & ModuleInstance> {
	public static createStatic(
		runtime: Runtime,
		parent: ModuleMgr,
		userCreated: boolean) {
		const inst = new StaticModuleInstanceMgr(runtime, parent, userCreated);
		parent.static = inst;
		runtime.addModule(parent);
		inst.initMetaConfigurables();
		inst.initDynamicConfigurables();
		inst.runDependentModuleChangedHandlers();
		inst.checkForDepenencies();
		return inst;
	}
	private alreadyRemoved: boolean = false;
	private viewNode: StaticContainerNode;
	private alwaysPresent = false;

	// dependent configurables for whose onModChanged still needs to run
	private delayedOnModChanged: string[] = [];

	private constructor(
		runtime: Runtime,
		private parent: ModuleMgr,
		userCreated: boolean,
	) {
		super(
			runtime,
			parent.module.moduleStatic || adaptToModule({}, `${parent.module.$name}$static`),
			false,
		);
		this.setUserCreatedOrTouched(userCreated);
		this.addFixedMember(runtime.getFormattersMap(), "addInstance",
			guardScriptingFunction(
				(instArgs?: InstanceArgs, userCreated2?: boolean) =>
					parent.addInstance(instArgs, userCreated2).managedObject, "addInstance"));
		const collapseStaticNode = this.getModuleMgr().getUIAdd() === "instanceOnly";
		this.viewNode = new StaticContainerNode(this, collapseStaticNode);
	}

	public override getUINodes(): { singleNodes: ViewNode[], tabGroup: TabGroup } {
		return splitViewNodes(this.getStaticContainerViewNodes(), this);
	}

	public override isStatic(): this is StaticModuleInstanceMgr {
		return true;
	}

	public override remove() {

		// guard multiple removes
		if (this.alreadyRemoved) {
			return;
		}

		this.alreadyRemoved = true;

		super.remove();
		this.runtime.removeModule(this.parent);
		this.runtime.getFormattersMap().delete(this.managedObject);
		this.runtime.deleteManager(this.managedObject);
		this.getModuleMgr().static = null;
		this.getModuleMgr().updateDependentsOfDeletion();
	}

	public override getModuleMgr(): ModuleMgr {
		return this.parent;
	}

	public override getScriptIdentifier() {
		return this.getModuleMgr().getScriptIdentifier();
	}

	public override getModulePath() {
		return this.getModuleMgr().getName();
	}

	public override setLockStatus(status: boolean) {
		_.each(this.getInterfaceInstanceMemberMgrs(), (l) => l.valueObjectMgr.setLockStatus(status));
	}

	public override isTopModule() {
		return this.getModuleMgr().isTop();
	}

	public override getViewNodes() {
		return [this.viewNode];
	}

	public getStaticContainerViewNodes() {
		return super.getViewNodes();
	}

	public setAlwaysPresent() {
		this.alwaysPresent = true;
	}

	public isAlwaysPresent() {
		return this.alwaysPresent;
	}

	public override canRemove(): ActionState {
		if (this.alwaysPresent) {
			return { enabled: ActionEnabled.NEVER };
		}
		return super.canRemove();
	}

	public override onMemberChanged(member: AnyMemberMgr, source: SetSource): void {
		super.onMemberChanged(member, source);

		const modMgr = this.getModuleMgr();
		// if a dependent configurable is changed from another configurable's onChange handler
		// make sure the onChange handler completes before running onModuleChanged
		if (!this.inOnChange && !this.inOnModuleChanged) {
			const dependencies = modMgr.getDependencies();
			const cfgsToCheck = _.intersection([member.def.name, ...this.delayedOnModChanged], this.getMembersWithDependents());
			_.chain(dependencies)
				.pick(cfgsToCheck)
				.flatMap((i) => i)
				.uniq()
				.flatMap((dep) => {
					if (dep.isInstance) {
						return dep.moduleMgr.instances;
					} else {
						return dep.moduleMgr.static ?? [];
					}
				})
				.each((inst) => inst.runOnModuleChanged(modMgr, this.getModulePath(), cfgsToCheck))
				.value();
		}
		// we're in another configurables onChange, so we should push our onModuleChanged to do later
		else {
			this.delayedOnModChanged.push(member.def.name);
		}

	}

	public override copyToRuntime() {
		throw new Error("Can't copy static manager");
	}

	public override canCopy(): ActionState {
		return { enabled: ActionEnabled.NEVER };
	}

	// For a non-static instance, if they indicated the ui view is graph, it's always displayed.  But for a static 
	// instance it's more complex:
	// 1) We don't want to show static modules where the purpose is to support global settings
	// 2) We don't want to show static modules that don't have ports (to allow for always-present settings that don't
	//	  want to change the UI layout like TPLD's simulation settings module)
	public override appearsInGraph() {
		return super.appearsInGraph()
			&& this.getModuleMgr().getUIAdd() !== "instanceOnly"
			&& !!this.module.ports;
	}

	protected override preRemove() { }

	protected override createNameMemberMgr(): { id: string, nameMemberMgr: NameMemberMgr } {
		const config = {
			default: this.parent.module.$name,
		};

		return {
			id: this.parent.module.$name,
			nameMemberMgr: new NameMemberMgr(this, this.runtime.getFormattersMap(), config,
				{
					isReadOnly: true,
					isHidden: true,
					displayName: this.parent.getDisplayName(false),
				}),
		};
	}

	protected override createAddInstanceStatements() {
		return [createAddModuleStatement(this.getModuleMgr(), this.isUserCreatedOrTouched())];
	}

	private getMembersWithDependents() {
		return _.keys(this.getModuleMgr().getDependencies());
	}

	private runDependentModuleChangedHandlers() {
		// if module has any dependencies run the onModuleChangedHandler for the dependent module instances
		_.each(this.getModuleMgr().getDependentModuleInstMgrs(), (mgr) => {
			mgr.runOnModuleChanged(this.getModuleMgr(), this.getModulePath(), []);
		});
	}
}
