import { createFinalSvgPathNode } from "./createSvgPathNode";

// Looks like a giant horizontal line down to an upside down triangle made with horizontal line.  Single output port 
// always connects at the top

function groundPath(width: number, height: number) {
	return `M ${width / 2} 0 `						// Start at the top in the middle
		+ `V ${height / 2} `						// Vertical line to 1/2 way point
		+ `M 0 ${height / 2} `						// Move to the middle of the left side
		+ `H ${width} `								// Horizontal bar of full width
		+ `M ${width * 1 / 5} ${height * 3 / 4} `	// Move back to the middle, but further down
		+ `h ${width * 3 / 5} `						// Horizontal bar of 3/5 width
		+ `M ${width * 2 / 5} ${height} `			// Move back to the middle, but all the way down
		+ `h ${width * 1 / 5}`;						// Final horizontal bar of only 1/5 width
}

// Offsets are forced to the middle, with the assumption y is always the middle

export const GroundNode = createFinalSvgPathNode(groundPath, {
	heightFactor: 1 / 2,
	widthFactor: 1 / 2,
	portYOffset: () => 0,
	outputLabelXOffset: (nodeSize) => -nodeSize.width / 2,
	outputPortXOffset: (nodeSize) => -nodeSize.width / 2,
});
