import * as _ from "lodash";
import { Module } from "public/runtime";
import { IGraphTreeNode } from "../../components/graph/types/IGraphTreeNode";
import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";
import { StaticModuleInstanceMgr } from "../objectManagers/staticModuleInstance";
import { addAlwaysPresentModule } from "../product/alwaysPresentModules";
import { Runtime } from "../resources/runtime";
import { ModuleMgr } from "./module";
import { NodeSelection } from "./nodeSelection";

// A node in the left pane that represents a specific IP instance node in the clock tree

export class GraphableModuleMgr extends ModuleMgr implements IGraphTreeNode<ModuleInstanceMgr> {

	constructor(
		runtime: Runtime,
		module: Module,
	) {
		super(runtime, module, NoAutoSelectNodeSelection);
	}

	// Functions specific to this class

	public override getNodesInGraph() {
		return _.chain(this.runtime.getModuleMgrs())
			.filter((m) => m instanceof GraphableModuleMgr)
			.flatMap((m) => m.allInstancesIncludingStatic())
			.filter((inst) => inst.appearsInGraph())
			.value();
	}

	// Necessary to implement IGraphTreeNode

	public getStaticConfiguration(): StaticModuleInstanceMgr {

		const staticConfig = this.runtime.getTopModules().getGraphableStaticConfig();
		if (staticConfig) {
			return addAlwaysPresentModule(this.runtime, staticConfig);
		}
		return null;
	}

	// Overrides of ModuleMgr

	public override supportsOutputMenuDocking() {
		return true;
	}

	public override isGraphableNode() {
		return true;
	}

	public override isGraphableNonTopMgr() {
		return !this.isTop();
	}
}

class NoAutoSelectNodeSelection extends NodeSelection<ModuleInstanceMgr> {
	protected override fixInvalidSelection() {
		this.setSelection({ instanceId: null, memberPath: [] });
	}
}
