import * as React from "react";
import { AnyMemberMgr } from "../../../services/objectManagers/member";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { typedMemo } from "../../typedMemo";
import { ClassesType } from "../styling/graphStyles";
import { GenericNode, IGenericNodeProps } from "./GenericNode";

// A normal node (square), but smaller with an X in the middle

export const PinFunctionNode = typedMemo(function PinFunctionNode<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	props: IGenericNodeProps<InstMgr, PortMgr> & ClassesType
) {
	const { classes } = props;
	return (
		<GenericNode {...props} >
			<svg className={classes.svgNodeContainer}>
				<line x1="0" y1="100%" x2="100%" y2="0" className={classes.edge} />
				<line x1="100%" y1="100%" x2="0" y2="0" className={classes.edge} />
			</svg>
		</GenericNode>
	);
});
