import * as _ from "lodash";
import { Requirements } from "./requirements";
import { PortRequirement } from "public/defs";
import { PortMemberMgr } from "../portMemberMgr";
import { SetSource } from "../member";

export class PortRequirements extends Requirements<"ports"> {

	protected adaptReqs(reqs: PortRequirement[]) {
		return reqs;
	}

	protected categorizeReqs(reqs: PortRequirement[]) {
		const removedReqs = _.clone(this.currentRequirements);
		const { newReqs, updateReqs } = _.groupBy(
			reqs,
			(req) => {
				if (req.key) {
					const match = _.head(_.remove(removedReqs, (pr) => pr.key && pr.key === req.key));
					if (match) {
						if (!_.isEqual(match, req)) {
							return "updateReqs";
						} else {
							return "unchangedReqs";
						}
					}
					return "newReqs";
				} else {
					const match = _.head(_.remove(removedReqs, (pr) => _.isEqual(pr, req)));
					return match ? "unchangedReqs" : "newReqs";
				}
			},
		);
		return {
			removedReqs,
			newReqs,
			updateReqs,
		};
	}

	protected resolve(newReqs: PortRequirement[], updatedReqs?: PortRequirement[]) {

		if (!_.isEmpty(updatedReqs)) {

			// Updates.  First, find the existing reqs with the same keys

			const toUpdate = _.map(updatedReqs, ({ key }) =>
				_.find(this.instanceMgr.memberMgrs, (mgr) => mgr instanceof PortMemberMgr && mgr.def.key === key)) as PortMemberMgr[];

			// Now, save the connections to those reqs

			const connections = _.map(toUpdate, (mgr) => mgr.getValue());

			// Now, remove those members

			_.each(toUpdate, (req) => this.instanceMgr.removeMember(req));

			// Now create new members, but set the original connections

			_.zipWith(updatedReqs, connections, (req, connection) => {
				const mgr = new PortMemberMgr(this.instanceMgr, req, this.runtime);
				mgr.set(connection, SetSource.USER_ASSIGN);
			});
		}

		// Once updates are complete, add the any new requirements

		_.each(newReqs, (req) => new PortMemberMgr(this.instanceMgr, req, this.runtime));
	}

	protected getFunctionName(): "ports" {
		return "ports";
	}
}
