import * as _ from "lodash";
import React = require("react");
import DeviceData = require("dataInterfaces");
import { HardwareComponent } from "public/runtime";
import { BoardViewLabelEntry, BoardViewDevicePinEntry } from "./BoardViewEntry";
import { PinInfo, gatherSignals } from "../services/pinInfo";
import { getDisplayName } from "../services/utils";
import { ATheme } from "./styles/themes";

const listContainerStyle: React.CSSProperties = {
	listStyleType: "none",
	padding: "15px",
	margin: 0,
	borderRadius: "4px",
	display: "inline-block",
};

interface IBoardViewComponentsProps {
	deviceData: DeviceData.AdaptedDeviceInfo;
	pinInfo: PinInfo;
	components: HardwareComponent[];
	shouldShowModeTable: boolean;
	theme: ATheme;
	displayScriptName: boolean;
}

// draws components (and subcomponents) that are not on header pins
export class BoardViewComponents extends React.Component<IBoardViewComponentsProps, {}> {
	public override render() {
		return (
			<span style={{ display: "inline-flex", width: "100%" }}>
				{
					_.map(this.props.components, (component) => {
						const signalsDevicePinsOnly = _.filter(gatherSignals(component),
							(signal) => !!signal.devicePin && !signal.headerPin);

						return (
							<ul style={listContainerStyle} key={component.name}>
								<BoardViewLabelEntry
									label={getDisplayName(component, this.props.displayScriptName)}
									placement="top"
									fullWidth
								/>
								{
									_.map(signalsDevicePinsOnly, (signal, index) => {
										return (<BoardViewDevicePinEntry
											theme={this.props.theme}
											fixedWidth={true}
											key={signal.devicePin?.name ?? signal.name}
											devicePin={signal.devicePin}
											top={index === 0}
											bottom={index === signalsDevicePinsOnly.length - 1}
											left
											right
											pinInfo={this.props.pinInfo}
											shouldShowModeTable={this.props.shouldShowModeTable}
										/>);
									})
								}
							</ul>
						);
					})
				}
			</span>
		);
	}
}
