import React = require("react");
import { LinearProgress, Typography } from "../imports/material-ui-imports";

interface IProgressBarProps {
	title: string;
	id?: string;
	/* Number between 0 and 100 */
	value?: number;
}

const progressContainerStyle: React.CSSProperties = { height: "100%", width: "100%", textAlign: "center" };
const progressWrapperStyle: React.CSSProperties = { position: "relative", top: "45%", padding: "0 75px" };

export class ProgressBar extends React.Component<IProgressBarProps> {
	public override render() {
		return (
			<div style={progressContainerStyle}>
				<div style={progressWrapperStyle}>
					<Typography variant="subtitle1">{this.props.title}</Typography>
					<LinearProgress variant={this.props.value === undefined ? "indeterminate" : "determinate"}
						id={this.props.id} value={Math.min(this.props.value, 100)} />
				</div>
			</div>
		);
	}
}
