// UI Views for meta content defined configurables
import * as _ from "lodash";
import * as React from "react";
import { IConfigurablesActions } from "../../actions/configurableActions";
import { UnitsConfigurableMgr } from "../../../services/objectManagers/configurables/unitsConfigurableMgr";
import { FilteredOnBlurInputBox } from "../../higherOrderComponents/ComposedComponents";
import { withStyles, WithStyles, Grid, MenuItem, Select } from "../../../imports/material-ui-imports";

const styles = {
	select: {
		marginTop: "2px",
	},
};

interface IProps extends WithStyles<typeof styles> {
	mgr: UnitsConfigurableMgr<number | bigInt.BigInteger>;
	actions: IConfigurablesActions;
}

function StyledUnitsConfigurable({ mgr, actions, classes }: IProps) {
	const onChangeTBox = React.useCallback((val: string) => {
		const parsed = mgr.parseString(val);
		if (!_.isEqual(mgr.getValue(), parsed)) {
			actions.setConfigurableValue(mgr, parsed);
		}
	}, [actions, mgr]);

	const onChangeUnits = React.useCallback((e: React.ChangeEvent<{ value: unknown }>) => {
		actions.setConfigurableValue(mgr, { val: mgr.getValue().val, units: e.target.value });
	}, [actions, mgr]);

	const filter = React.useCallback((val: string) => {
		return mgr.checkFormatMatch(val);
	}, [mgr]);

	return (
		<Grid container direction="row" spacing={3}>
			<Grid item xs>
				<FilteredOnBlurInputBox
					value={mgr.getMagnitudeAsString()}
					id={`${mgr.def.name}-val`}
					onChange={onChangeTBox}
					type="text"
					disabled={!!mgr.uiState.readOnly}
					filter={filter}
				/>
			</Grid>
			<Grid item xs={3}>

				<Select
					className={classes.select}
					value={mgr.getUnits()}
					id={`${mgr.def.name}-units`}
					onChange={onChangeUnits}
					disabled={!!mgr.uiState.readOnly}
					fullWidth={true}
				>
					{_.map(mgr.getUIOptions(), (value) => <MenuItem key={value} value={value}>{`${value}`}</MenuItem>)}
				</Select>
			</Grid>
		</Grid>
	);
}

export const CUnitsConfigurable = withStyles(styles)(StyledUnitsConfigurable);
