import React = require("react");
import * as _ from "lodash";

import { Requirements } from "./Requirements";
import { Output } from "./OutputViews/Output";
import { HardwareRequirements } from "./HardwareRequirements";
import { HardwareComponentMgr } from "../services/instanceContainers/hardwareComponent";
import { ConfigStoreActions } from "../services/configStore";
import { IFormatter } from "../services/formatting/formattingTypes";
import { Tab } from "../services/tabs";
import { InterfaceMgr } from "../services/instanceContainers/interface";
import { ModuleMgr } from "../services/instanceContainers/module";
import { UserPreference } from "../services/userPreferences";
import { commonStyles } from "./styles/common";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { ResourceLoader } from "../services/resources/metaContentLoaders/resourceLoader";
import { InlineErrorBoundary } from "./InlineErrorBoundry";
import { Breadcrumb } from "./Breadcrumb";
import { ResizableBorder } from "./ResizableBorder";
import { NavigationHistory } from "../services/navigationHistory";
import { OutputViewMgr } from "../services/ui/outputView";
import { ClockTreeNode } from "../services/instanceContainers/clockTreeNode";
import { Validations } from "../services/objectManagers/validations";
import { Dock } from "./actions/IOutputActions";
import { ClockTreeView } from "./clockTree/ClockTreeView";
import { GraphableModuleMgr } from "../services/instanceContainers/graphableModuleMgr";
import { GraphableModulesView } from "./graphableModules/GraphableModulesView";

interface IProps {
	showPreferredVoltage: boolean;
	actions: ConfigStoreActions;
	selectedTab: Tab;
	arePowerDomainSettingsEnabled: boolean;
	formatter: IFormatter;
	validations: Validations;
	navHistory: NavigationHistory;
	userPreference: UserPreference;
	resourceLoader: ResourceLoader;
	col3Width: number;
	clockTreeHeight: number;
	focusedSubItemPath: string[];
	showUsed: boolean;
	showPinTable: boolean;
	viewMgrs: OutputViewMgr[];
	currentView: OutputViewMgr;
	outputDocking: Dock;
	displayScriptName: boolean;
}

export class Col2 extends React.Component<IProps & IGlobalServiceProps> {
	constructor(props: IProps & IGlobalServiceProps) {
		super(props);
	}

	public override render() {

		const selectedTreeNode = this.props.selectedTab.getSelectedNode();
		const preview = this.props.selectedTab.getPreview();
		const showingOutputMenu = !selectedTreeNode.supportsOutputMenuDocking() || this.props.outputDocking === Dock.RIGHT;
		const showingOutput = showingOutputMenu && _.some(this.props.viewMgrs, (v) => v.isDisplayed());

		let configurationContent = null;
		const prefs = this.props.userPreference.getPreferences();
		const displayScriptName = this.props.displayScriptName;
		const devicePinDisplayType = prefs.devicePinDisplayType.getSelectedEnums();
		const headerPinDisplayType = prefs.headerPinDisplayType.getSelectedEnums();
		if (selectedTreeNode instanceof GraphableModuleMgr) {
			configurationContent = <GraphableModulesView
				actions={this.props.actions}
				treeNode={selectedTreeNode}
				displayScriptName={displayScriptName}
				devicePinDisplayType={devicePinDisplayType}
				headerPinDisplayType={headerPinDisplayType}
				focusedSubItemPath={this.props.focusedSubItemPath}
				showUsed={this.props.showUsed}
				showPinTable={this.props.showPinTable}
				arePowerDomainSettingsEnabled={this.props.arePowerDomainSettingsEnabled}
				formatter={this.props.formatter}
				resourceLoader={this.props.resourceLoader}
				modalService={this.props.modalService}
				notificationService={this.props.notificationService}
				errorStore={this.props.errorStore}
				theme={this.props.theme}
				branding={this.props.branding}
				validations={this.props.validations}
				heightPercent={this.props.clockTreeHeight}
				userPreference={this.props.userPreference}
				viewMgrs={this.props.viewMgrs}
				currentView={this.props.currentView}
				col3Width={this.props.col3Width}
				outputDocking={this.props.outputDocking}
			/>;
		} else if (selectedTreeNode instanceof ModuleMgr || selectedTreeNode instanceof InterfaceMgr) {
			configurationContent = <Requirements
				{...this.props}
				selectedTreeNode={selectedTreeNode}
				displayScriptName={displayScriptName}
				devicePinDisplayType={devicePinDisplayType}
				headerPinDisplayType={headerPinDisplayType}
				preview={preview}
			/>;
		} else if (selectedTreeNode instanceof ClockTreeNode) {
			configurationContent = <ClockTreeView
				actions={this.props.actions}
				treeNode={selectedTreeNode}
				displayScriptName={displayScriptName}
				devicePinDisplayType={devicePinDisplayType}
				headerPinDisplayType={headerPinDisplayType}
				focusedSubItemPath={this.props.focusedSubItemPath}
				showUsed={this.props.showUsed}
				showPinTable={this.props.showPinTable}
				arePowerDomainSettingsEnabled={this.props.arePowerDomainSettingsEnabled}
				formatter={this.props.formatter}
				resourceLoader={this.props.resourceLoader}
				modalService={this.props.modalService}
				notificationService={this.props.notificationService}
				errorStore={this.props.errorStore}
				theme={this.props.theme}
				branding={this.props.branding}
				validations={this.props.validations}
				heightPercent={this.props.clockTreeHeight}
				userPreference={this.props.userPreference}
				viewMgrs={this.props.viewMgrs}
				currentView={this.props.currentView}
				col3Width={this.props.col3Width}
				outputDocking={this.props.outputDocking}
			/>;
		} else {
			// get the selected hardware entry and the associated modules
			const hwComponentMgr = selectedTreeNode;
			if (hwComponentMgr instanceof HardwareComponentMgr) {
				configurationContent = <HardwareRequirements
					{...this.props}
					hwComponentMgr={hwComponentMgr}
					displayScriptName={displayScriptName}
					devicePinDisplayType={devicePinDisplayType}
					headerPinDisplayType={headerPinDisplayType}
				/>;
			}
		}

		return (
			<div style={{ ...commonStyles.containerStyle, backgroundColor: this.props.theme.theme.palette.background.default }}>
				<div style={commonStyles.columnFlexLayout}>
					<Breadcrumb {...this.props} selectedTreeNode={selectedTreeNode} showingOutput={showingOutputMenu} />
					<div style={{ flex: 1, height: "100%", overflowX: "auto" }}>
						<div style={commonStyles.rowFlexLayout}>
							<div style={{ flex: 1, overflowX: "auto" }}>
								<div id="Configurations" style={commonStyles.innerContentStyle}>
									<div style={{ width: "100%", height: "100%" }}>
										<InlineErrorBoundary theme={this.props.theme} id={selectedTreeNode.getID()}>
											{configurationContent}
										</InlineErrorBoundary>
									</div>
								</div>
							</div>
							{showingOutput &&
								<ResizableBorder
									theme={this.props.theme}
									borderAfterChild={false}
									position={this.props.col3Width}
									onPositionChanged={this.updateWidth}
									percentage
									displayed={true}
									horizontal={true}
									id="col2Col3Border"
								>
									<div id="Output" style={commonStyles.innerContentStyle}>
										<Output
											{...this.props}
											selectedTreeNode={selectedTreeNode}
										/>
									</div>
								</ResizableBorder>
							}
						</div>
					</div>
				</div>
			</div>
		);
	}

	private updateWidth = (width: number) => {
		this.props.actions.setCol3Width(width);
	}
}
