import React = require("react");
import { IEditorProps } from "./IEditor";
import { ProgressBar } from "../../ProgressBar";

interface IState {
	Editor: React.ComponentClass<IEditorProps>;
}

export class LazyLoadedEditor extends React.Component<IEditorProps, IState> {

	public override state: IState = { Editor: null };

	public override componentDidMount() {
		require.ensure([], () => {
			this.setState({ Editor: require("./Editor") });
		}, () => { }, "LazyEditor");
	}

	public override render() {
		if (this.state.Editor) {
			return (< this.state.Editor {...this.props} />);
		} else {
			return (
				<ProgressBar title={"Loading Editor..."} />
			);
		}
	}
}
