import { TextConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { SerializationOptions } from "../../scripting/toScript";
import { AObjectMgr } from "../object";
import { ConfigurableMgr } from "./configurableMgr";
import { ConfigurableComponent } from "./configurableComponent";

export class TextConfigurableMgr extends ConfigurableMgr<string> {
	public readonly ui = ConfigurableComponent.CTextConfigurable;
	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		public override readonly def: TextConfigurable,
	) {
		super(parentObjectMgr, formattersMap, def);
	}

	public override getScriptValue(_options: SerializationOptions) {
		// we need to stringify the string so that we get the same string back when we read the script
		// i.e. this will escape actual backslashes so that when it is read back it doesn't become an escape character
		return { value: JSON.stringify(this.value), shouldQuoteStrings: false };
	}
}
