import * as _ from "lodash";

// Classes and functions related to managing configurables

import {
	AMemberMgr,
	SetSource,
	isMetaCauseAssignCurrent,
	InstanceArgType,
} from "../member";
import { AObjectMgr } from "../object";
import {
	Configurable,
	ConfigurableValueType,
	InstanceArgs,
	InstanceArgsValue,
} from "public/defs";
import { RuntimeObject, ModuleInstance } from "public/runtime";
import { createMemberValueAssignmentStatement } from "../../scripting/serialize";
import { FormattersMap } from "../../formatting/formattersMap";
import { convertUnknownToError, memoizeOne } from "../../utils";
import { SerializationOptions, MigrationType } from "../../scripting/toScript";
import { extendException, assignmentToString } from "../../niceExceptions";
import { ModuleInstanceMgr } from "../moduleInstance";
import { disableScriptingForCallback } from "../../scripting/scriptingGuard";
import { Validations } from "../validations";
import { getConfigurationChangeNumber } from "../../changeNumber";

/**
 * Base class for all configurable managers providing common functionality.
 * @param ValueType - configurable value type.
 */
export abstract class ConfigurableMgr<
	ValueType extends ConfigurableValueType,
	RuntimeObjectType extends RuntimeObject = RuntimeObject,
	MemberDefinition extends Configurable<ValueType> = Configurable<ValueType>>
	extends
	AMemberMgr<ValueType, RuntimeObjectType, MemberDefinition> {

	private static cacheDynamicConfigurables = true;

	protected static withoutDynamicConfigurableCaching<T>(operation: () => T) {
		if (ConfigurableMgr.cacheDynamicConfigurables) {
			try {
				ConfigurableMgr.cacheDynamicConfigurables = false;
				return operation();
			} finally {
				ConfigurableMgr.cacheDynamicConfigurables = true;
			}
		} else {
			return operation();
		}
	}

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		def: MemberDefinition,
		defaultValue: ValueType = def.default,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
			defaultValue,
		);

		if (def.getValue) {
			if (def.onChange) {
				throw new Error("Configuration has onChange handler, getValue not valid");
			}

			// Replace this.value with a defined property that calls the meta-content defined getValue to get the value
			// and does not provide a setter.  The lack of a set function ensures the property is read only.
			// To reduce calls into meta-content when not needed, memoize the result on the configuration number so we 
			// don't call it if nothing has changed.  But, provide a mechanism to escape that in order to calculate 
			// signal paths in clock tree (which requires detecting which getters are read).

			delete this.value;
			const getValue = (_key: number) =>
				disableScriptingForCallback(() => {
					const value = def.getValue(parentObjectMgr.managedObject as ModuleInstance);
					this.validateValue(value, false, SetSource.TOOL_INTERNAL);
					return value;
				});
			const getValueMemo = memoizeOne(getValue);
			Object.defineProperty(this, "value", {
				get: () => {
					if (ConfigurableMgr.cacheDynamicConfigurables) {
						return getValueMemo(getConfigurationChangeNumber());
					} else {
						return getValue(getConfigurationChangeNumber());
					}
				},
			});

			// Also mark UI state as read only so the read-only-ness is propagated to UI controls too

			this.uiState.readOnly = true;
		}
	}

	public override getUIHash(validations: Validations): string {
		if (this.def.getValue) {
			return null;
		}
		return super.getUIHash(validations);
	}

	public generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {

		const forceWrite = this.wasForceWritten();

		const { value, shouldQuoteStrings } = this.getScriptValue(options);
		return [
			createMemberValueAssignmentStatement(
				this.def,
				parentIdentifier,
				value,
				{ shouldQuoteStrings, forceWrite },
			)];
	}

	// can return type any because createMemberValueAssignmentStatement takes type any for val
	public getScriptValue(_options: SerializationOptions): { value: any, shouldQuoteStrings: boolean } {
		return { value: this.value, shouldQuoteStrings: true };
	}

	public override removeRequiredByParent(origin: ModuleInstanceMgr) {
		if (_.includes(this.requiredByParent, origin)) { // If this is not locked by origin, do nothing.
			// it is possible for a single inst to have multiple references to us
			// we only want to remove one reference for each call
			_.pullAt(this.requiredByParent, _.indexOf(this.requiredByParent, origin));
			// When all the parents locking this config go away, and when the instance that owns
			// this configurable will still remain after all its parents goes away, we should 
			// unlock the value and promote it to USER_ASSIGN so that it can be properly serialized.
			if (_.isEmpty(this.requiredByParent)) {
				this.setReadOnly(this.readOnlyBeforeRequiredByParent);
				this.valueAssignSource = SetSource.USER_ASSIGN;
			}
		}
	}

	public setValueFromRequiredArgs(
		val: InstanceArgsValue,
		origin: ModuleInstanceMgr,
	) {
		try {
			if (_.isEmpty(this.requiredByParent)) {
				this.readOnlyBeforeRequiredByParent = this.uiState.readOnly;
			}
			this.set(val, SetSource.META_ARGS);
			this.requiredByParent.push(origin);
			this.setReadOnly(true);
		} catch (e) {
			extendException(`while setting '${this.def.name}' to ${assignmentToString(val)}`, convertUnknownToError(e));
		}
	}

	public setValueFromArgs(
		val: InstanceArgsValue,
		argType: InstanceArgType,
	) {
		try {
			if (argType === InstanceArgType.REAPPLY) {
				// don't overwrite user change when reapplying parent args
				if (!this.isUserModified() && this.valueAssignSource !== SetSource.META_ASSIGN) {
					this.set(val, SetSource.META_ARGS);
				}
			} else {
				this.set(val, argType === InstanceArgType.USER ? SetSource.USER_ARGS : SetSource.META_ARGS);
			}
		} catch (e) {
			extendException(`while setting '${this.def.name}' to ${assignmentToString(val)}`, convertUnknownToError(e));
		}
	}

	public removeArgs() {
		// When we remove arg, if this member has not been modified after the last arg then make it a
		// user change instead.
		this.lastArgValue = null;
		if (this.valueAssignSource === SetSource.META_ARGS) {
			this.valueAssignSource = SetSource.USER_ASSIGN;
		}
	}

	public removeReqArgs(_argval: InstanceArgs, origin: ModuleInstanceMgr) {
		this.removeRequiredByParent(origin);
	}

	protected override shouldSerialize(options: SerializationOptions): boolean {
		// serialize user modified or side effects
		return (this.isUserModified() || this.isSideEffect(options)) && !this.def.deprecated &&
			(!this.def.nonSerializable || options.includeNonSerializable);
	}

	protected override defaultValueType(): string {
		return typeof this.def.default;
	}

	// Side effect - The current value of the configurable was caused (onChange) by setting another 
	// configurable to some value that has been changed but the current value of this configurable
	// was not updated, leaving behind a side effect of the first change.
	protected isSideEffect(options: SerializationOptions) {

		// only meta assign can be side effect
		if (this.valueAssignSource !== SetSource.META_ASSIGN) {
			return false;
		}

		// When the value is set back to the init value, we don't 
		// consider it as a side effect since a config will take the default 
		// value even if we don't serialize it. The only exception to this rule
		// is if this member is currently set by an arg (and meta assign overwrites it)
		// of parent. This essentially changes the "default" that the config will take on.
		if (this.isEqual(this.initValue)) {
			return this.lastArgValue && !this.isEqual(this.lastArgValue);
		}

		const cause = this.valueMetaAssignCause;

		if (cause.inOnModuleChanged) {
			const staticDependency = cause.inOnModuleChanged.moduleMgr.static;
			if (staticDependency) {
				// If configurables don't exist in inOnModuleChanged than we know the change is due to static being added/removed
				const staticWillSerialize = staticDependency.shouldSerializeAdd();
				if (cause.inOnModuleChanged.configurables.length === 0) {
					// Only serialize, if the static add will not be serialized and this is not the default value (checked above)
					return !staticWillSerialize;
				}
				const dependencyConfigurables = cause.inOnModuleChanged.configurables;
				const configurablesWillSerialize = _.every(dependencyConfigurables, (cfgName) => {
					// check if the configurables which caused my last change will serialize
					// also check if my current value is because of the change to these configurables
					// TODO: Extract lower part of function (where we check isMetaCauseAssignCurrent(cause)) and
					// then recursively call that function with cause
					const staticConfigurable = staticDependency.memberMgrs[cfgName] as ConfigurableMgr<any>;
					return staticConfigurable.getAnyModSeqNum() < this.getAnyModSeqNum()
						&& isMetaCauseAssignCurrent(staticConfigurable.getValueMetaAssignCause())
						&& (staticConfigurable.shouldSerialize(options) || staticConfigurable.isFromMeta());
				});

				return !configurablesWillSerialize;
			} else {
				// We only want to serialize if we are not our original default value
				// If our modChanged changes us back to an original meta value set by onChange than we also don't want to serialize
				// however we also want to make sure that the configurable's which cause the onChange is being serialized

				if (!this.lastValueSetByOnChange) {
					return true;
				}

				// TODO: can we assign this.lastValueSetByOnChange.configurableName to cause and fall through?
				const onChangeMetaValueCheck =
					!((this.parentObjectMgr.memberMgrs[this.lastValueSetByOnChange.configurableName] as ConfigurableMgr<any>)
						.shouldSerialize(options) && this.isEqual(this.lastValueSetByOnChange.value));

				return onChangeMetaValueCheck;
			}
		}

		// If the causing configurable has a later sequence number, then it may not be set
		// to the value that changes us so we should serialize (ie causing was set to a value 
		// that causes a change in us, but then later changed again - only the latter change is
		// serialized).

		if (!isMetaCauseAssignCurrent(cause)) {
			return true;
		}

		if (cause.configurable.shouldSerialize(options)) {

			// The causing configurable will be serialized, and should change us.

			return false;

		} else {

			// If the cause is not going to be serialized because it was set via args that's ok

			return (
				(cause.configurable.valueAssignSource !== SetSource.META_ARGS)

				// Except when migrating to a device and the cause is $hardware, as $hardware will
				// be excluded for serialization, but we still need to preserve its side effects.

				|| (options.deviceDataMigration === MigrationType.BOARD_TO_DEVICE && cause.configurable.def.name === "$hardware")

				// Or, if the cause's value doesn't differ from the default, in which case the args 
				// wouldn't run the onChange, just lock the value (change and then revert back)

				|| cause.configurable.isEqual(cause.configurable.def.default)
			);
		}
	}

	protected override isCalculated() {
		return !!this.def.getValue;
	}
}
