import * as _ from "lodash";
import * as path from "path";
import * as React from "react";

import { ITemplateActions } from "./actions/ITemplateActions";
import { ErrorBadge as Error } from "./Badges";
import { Table, TableBody, TableCell, TableRow, Typography, Switch, TableHead, Grid } from "../imports/material-ui-imports";
import { AnchorButton } from "./AnchorButton";
import { Formatted2ColRow } from "./Formatted2ColRow";
import { Tooltip } from "./Tooltip";
import { DropDown } from "./DropDown";
import { SaveGeneratedCode } from "./SaveGeneratedCode";
import { ReferenceFile, CodeGenTemplateFile } from "dataInterfaces";
import { commonStyles } from "./styles/common";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { FileErrorOutline, FileOutline, FilePencilOutline } from "../imports/mdi-material-ui-imports";
import { getGenerationErrorMsg } from "../services/codeGeneration/codeGenerator";

interface IProps<T> extends Pick<IGlobalServiceProps, "modalService" | "errorStore"> {
	id: string;
	files: T[];
	onFileOpen?: (file: T) => void;
	actions?: ITemplateActions<T>;
	hasErrors: boolean;
	showGenerateOption?: boolean;
	showSaveIcons: boolean;
	filesThatChanged?: Set<string>;
	filesWithErrors?: Set<string>;
}

interface IState {
	selectedCatagoryValue: string;
}

const tableStyle = {
	margin: "0 10px 0 16px",	// padding to align with file list
};

const ALL = "all";

export class BaseFileList<T extends CodeGenTemplateFile | ReferenceFile>
	extends React.Component<IProps<T>, IState> {
	public override state = {
		selectedCatagoryValue: ALL,
	};

	public override shouldComponentUpdate(nextProps: Readonly<IProps<T>>, nextState: Readonly<IState>) {
		// _.isEqual will do a deep comparison, which we need for the files array
		// Hence why PureComponent is not good enough
		return !_.isEqual(nextProps, this.props) || !_.isEqual(nextState, this.state);
	}

	public override render() {

		// pre-sorted

		const filteredFiles =
			this.state.selectedCatagoryValue === ALL ? this.props.files
				: _.filter(this.props.files, (f) => f.category === this.state.selectedCatagoryValue);

		const categories = [ALL, ..._.uniq(_.map(this.props.files, (f) => f.category))];

		return (
			<div>
				<table style={tableStyle}>
					<tbody>
						<Formatted2ColRow
							col1={<Typography variant="body2">Filter:</Typography>}
							col2={
								<DropDown
									id={`${this.props.id}CategoryFilter`}
									disabled={false}
									onChange={(value: string) => this.setState({ selectedCatagoryValue: value })}
									selectedOptionName={this.state.selectedCatagoryValue}
									enabledOptions={_.map(categories, (category) => ({ name: category, displayName: category }))}
									displayScriptName={false}
								/>
							}
						/>
					</tbody>
				</table>
				<div id={`${this.props.id}FileListView`}>
					<Table id={`${this.props.id}FileListTable`}>
						<TableHead>
							<TableRow hover={false} style={commonStyles.tableRowStyle}>
								<TableCell>File name</TableCell>
								<TableCell>Category</TableCell>
								{
									this.props.showGenerateOption &&
									<TableCell
										style={{
											width: "1%",
											whiteSpace: "nowrap",
										}}
									>Include in build</TableCell>
								}
								<TableCell></TableCell>
							</TableRow>
						</TableHead>
						<TableBody>
							{_.map(filteredFiles, (file, index) => {
								return (
									<TableRow key={index} hover style={commonStyles.tableRowStyle}>
										<TableCell style={{
											cursor: "pointer",
										}}  >
											<Grid container direction="row" alignItems="center" wrap="nowrap" spacing={2}>
												<Grid item> {this.renderFileOutLine(file)} </Grid>
												<Grid item> {this.renderFileName(file)} </Grid>
											</Grid>
										</TableCell>
										<TableCell>{file.category}</TableCell>
										{
											this.props.showGenerateOption &&
											<TableCell>
												{
													this.isExcludable(file) &&
													<div
														style={{
															textAlign: "center",
														}}
													>
														<Tooltip
															title={
																"An excluded file would no longer be generated at the output directory."
															}
															placement={"left"}
														>
															<Switch
																color={"primary"}
																disabled={!this.isExcludable(file)}
																id={`include${file.name}`}
																checked={!this.isExcluded(file)}
																size={"small"}
																// eslint-disable-next-line max-len
																onChange={(_event: any, checked: boolean) => this.props.actions.excludeFromBuild(file, !checked)} />
														</Tooltip>
													</div>
												}
											</TableCell>
										}
										{
											this.props.actions && this.props.showSaveIcons &&
											<TableCell padding="none">
												<SaveGeneratedCode<T>
													modalService={this.props.modalService}
													errorStore={this.props.errorStore}
													disabled={this.isExcludable(file) && this.isExcluded(file)}
													id={file.name + "DownloadBtn"}
													actions={this.props.actions}
													files={[file]}
												/>
											</TableCell>
										}
									</TableRow>
								);
							})}
							<TableRow hover style={commonStyles.tableRowStyle}>
								<TableCell>{this.getTotal(filteredFiles)} Total Files</TableCell>
								<TableCell>
									{this.props.hasErrors &&
										<Tooltip title={this.getErrorsTooltipText()} placement="top">
											<span>
												<Error id="fileListErrorNote" message={"Design contains errors"} />
											</span>
										</Tooltip>
									}
								</TableCell>
								{
									this.props.showGenerateOption &&
									<TableCell></TableCell>
								}
								{this.props.actions && !_.isEmpty(filteredFiles) && this.props.showSaveIcons &&
									<TableCell padding="none">
										<SaveGeneratedCode
											modalService={this.props.modalService}
											errorStore={this.props.errorStore}
											id="btnDownloadAll"
											actions={this.props.actions}
											files={filteredFiles}
										/>
									</TableCell>
								}
							</TableRow>
						</TableBody>
					</Table>
				</div>
			</div >
		);
	}

	private getTotal(files: T[]) {
		return _.chain(files)
			.filter((file) => !this.isExcluded(file))
			.size()
			.value();
	}

	private renderFileName(file: T) {

		if (this.props.onFileOpen) {
			return <Tooltip title="Preview" placement="right">
				<AnchorButton
					color="primary"
					style={commonStyles.smallIcon}
					onClick={() => this.props.onFileOpen(file)}
				>
					{file.name}
				</AnchorButton>
			</Tooltip>;
		} else {
			return <Tooltip title={file.path} noWrap placement="right">
				<AnchorButton
					color="primary"
					style={commonStyles.smallIcon}>
					{path.basename(file.name)}
				</AnchorButton>
			</Tooltip>;
		}
	}

	private isExcluded(file: CodeGenTemplateFile | ReferenceFile): file is CodeGenTemplateFile {
		return !!(file as any as CodeGenTemplateFile).excluded;
	}

	private isExcludable(file: CodeGenTemplateFile | ReferenceFile): file is CodeGenTemplateFile {
		return !!(file as any as CodeGenTemplateFile).excludable;
	}

	private getErrorsTooltipText() {
		return "You can still generate files when errors exist," +
			"but the files generated might not work in your system. Please consider fixing the errors first.";
	}

	private renderFileOutLine(file: CodeGenTemplateFile | ReferenceFile) {
		if (this.props.filesWithErrors?.has(file.name)) {
			return <Tooltip title={getGenerationErrorMsg(file.name)} placement={"left"}>
				<FileErrorOutline className="FileErrorIcon" />
			</Tooltip>;
		} else if (!this.props.filesThatChanged?.has(file.name)) {
			return <FileOutline className="FileIcon" />;
		} else {
			return <Tooltip title={"File has been updated"} placement={"left"}>
				<FilePencilOutline className="FilePencilIcon" />
			</Tooltip>;
		}
	}
}
