import * as React from "react";
import * as _ from "lodash";
import * as Layout from "../types/layoutTypes";
import { ModuleInstanceMgr } from "../../../services/objectManagers/moduleInstance";
import { defaultFontSize } from "../../styles/themes";
import { typedMemo } from "../../typedMemo";
import { ClassesType } from "../styling/graphStyles";
import { MainLabel } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { INodeProps } from "../types/nodeTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// A square box with some status text displayed inside.  Originally intended to highlight the frequency at specific
// locations in a clock tree

export interface IStatusNodeProps<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr> extends INodeProps<InstMgr, PortMgr> {
	text: string;
}

export const StatusNode = typedMemo(function FrequencyLabelNodeImpl<InstMgr extends ModuleInstanceMgr, PortMgr extends AnyMemberMgr>(
	{
		node,
		onClickNode,
		onMouseDownNode,
		displayScriptName,
		classes,
		text,
		validations,
		formatter,
	}: IStatusNodeProps<InstMgr, PortMgr> & ClassesType
) {
	const fontSize = getFontSize(node, text);
	return (
		<PositionedNode
			node={node}
			onClick={onClickNode}
			onMouseDown={onMouseDownNode}
			className={classes.frequencyLabelNode}
			validations={validations}
			formatter={formatter}
		>
			<MainLabel node={node} displayScriptName={displayScriptName} classes={classes} />
			<div className={classes.centralText} style={{ fontSize }}>
				{text}
			</div>
		</PositionedNode>
	);
});

function getFontSize(node: Layout.Shape, text: string) {
	const width = node.width;
	const textLength = text.length;

	// 1.5 is a scaling factor that seems to work (to compare box width against font size)

	const size = Math.min(defaultFontSize, width / textLength * 1.5);
	return `${size}px`;
}
