import * as _ from "lodash";
import { ErrorStore } from "../../pinmux/services/errorStore";
import { NOPModalService } from "../../pinmux/services/ui/NOPModalService";
import { ATheme, defaultTheme } from "../../pinmux/components/styles/themes";
import { INotification } from "../../pinmux/services/INotification";
import { ModalService } from "../../pinmux/services/ui/modals";
import { NotificationService } from "../../pinmux/services/ui/notification";

class NOPNotification implements INotification {
	public pushNotification() { }
	public updateTheme() { }
}

const theme = defaultTheme;

// Memoized functions to get the same service object if the mount point has been previously used
// Return a dummy service if no mount points were supplied

const getModalService = _.memoize((mountPoint: HTMLElement) => {
	if (mountPoint) {
		return new ModalService(theme, mountPoint);
	} else {
		return new NOPModalService();
	}
});

const getNotificationService = _.memoize((mountPoint: HTMLElement) => {
	if (mountPoint) {
		return new NotificationService(theme, mountPoint);
	} else {
		return new NOPNotification();
	}
});

const errorStore = new ErrorStore();

export function createGlobalServices(modalRoot: HTMLElement, notificationRoot: HTMLElement) {
	const globalServices = {
		modalService: getModalService(modalRoot),
		notificationService: getNotificationService(notificationRoot),
		errorStore,
		theme,
		updateTheme: (newTheme: ATheme) => {
			globalServices.theme = newTheme;
			globalServices.modalService.updateTheme(newTheme);
			globalServices.notificationService.updateTheme(newTheme);
		},
	};

	return globalServices;
}
