import React = require("react");
import * as _ from "lodash";
import { SecondaryButton } from "../buttons/SecondaryButton";
import { ConfirmModal } from "./ConfirmModal";
import { CModuleInstance } from "../objectManagers/ModuleInstance";
import { commonStyles } from "../styles/common";
import { TableCell, TableRow } from "../../imports/material-ui-imports";
import { ConfigStoreActions } from "../../services/configStore";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { StaticModuleInstanceMgr } from "../../services/objectManagers/staticModuleInstance";
import { ResourceLoader, ResourceType } from "../../services/resources/metaContentLoaders/resourceLoader";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { Validations, ValidationSummary } from "../../services/objectManagers/validations";
import { MarkdownContent } from "../MarkdownContent";

interface IEmbeddedButtonProps {
	label: string;
	buttonText: string;
	onClick: () => void;
}

export interface IModuleConfigModalProps extends IModuleConfigProps {
	popupModuleInst: StaticModuleInstanceMgr;
	title: string;
	closeModal: () => void;
	confirmAction: (closeModal: () => void) => void;
	registerSubModalMountPoint: (el: HTMLDivElement) => void;
	embeddedButtonProps?: IEmbeddedButtonProps;
}

export interface IModuleConfigProps extends IGlobalServiceProps {
	actions: ConfigStoreActions;
	formatter: IFormatter;
	displayScriptName: boolean;
	resourceLoader: ResourceLoader;
	validations: Validations;
}

export function ModuleConfigModal({
	popupModuleInst,
	title,
	closeModal,
	confirmAction,
	registerSubModalMountPoint,
	theme,
	errorStore,
	modalService,
	actions,
	embeddedButtonProps,
	formatter,
	resourceLoader,
	validations,
	...rest
}: IModuleConfigModalProps) {

	// Since the component is most being mounted using ReactDom.Render we need a way to trigger a re-render
	// when the module instance changes. Configstore will fire an event which we can add a listener for
	// when the listener fires we just want to arbitrarily set state (reducer)

	const [, forceRender] = React.useReducer((x) => x + 1, 0);
	React.useEffect(() => {
		actions.onAnyChange().addListener(forceRender);
		return () => {
			actions.onAnyChange().removeListener(forceRender);
		};
	}, [forceRender, actions]);

	// We need to unregister for events if the confirm callback asks us to close (as the rest of the onConfirm will 
	// cause us to unmount which doesn't synchronously unregister the listener

	const confirmIsDisabled = validations.getSummary(popupModuleInst) === ValidationSummary.Error;
	const onConfirm = React.useCallback(() => confirmAction(() => {
		actions.onAnyChange().removeListener(forceRender);
		closeModal();
	}), [actions, closeModal, forceRender, confirmAction]);

	const scrollStyle = React.useMemo(() => ({ overflow: "scroll", maxHeight: 400, minWidth: 600 }), []);
	const moduleMgr = popupModuleInst.getModuleMgr();
	const longDescription = moduleMgr.getLongDescription();

	return <ConfirmModal
		registerSubModalMountPoint={registerSubModalMountPoint}
		title={title}
		theme={theme}
		confirmAction={onConfirm}
		disableConfirmButton={confirmIsDisabled}
		confirmText="Ok"
		cancelText="Back"
		cancelAction={closeModal}
		type={"None"}
	>

		<div style={scrollStyle}>
			{/* Use MarkdownContent vs LongDescription here, as we want this to appear like dialog text vs a closeable card */}

			{longDescription &&
				< MarkdownContent
					markdownSrc={moduleMgr.getLongDescription()}
					canonicalName={moduleMgr.getName()}
					resourceType={ResourceType.CODE}
					resourceLoader={resourceLoader}
					formatter={formatter}
					actions={actions}
				/>
			}
			<CModuleInstance
				{...rest}
				// It doesn't make sense to be doing pinmuxing/navigation in this popup so just pass generic values
				arePowerDomainSettingsEnabled={false}
				devicePinDisplayType={[]}
				showPinTable={false}
				headerPinDisplayType={[]}
				showUsed={false}
				focusedSubItemPath={[]}
				sharedInstanceSubItemPath={[]}
				actions={actions}
				theme={theme}
				instMgr={popupModuleInst}
				errorStore={errorStore}
				modalService={modalService}
				productLookupName={popupModuleInst.getModulePath()}
				formatter={formatter}
				resourceLoader={resourceLoader}
				validations={validations}
				isPopup={true}>
				{embeddedButtonProps &&
					<EmbeddedButton {...embeddedButtonProps} theme={theme} />
				}
			</CModuleInstance>
		</div>
	</ConfirmModal>;
}

// This button is used in the pop on the modal service
function EmbeddedButton({ label, buttonText, onClick, theme }: IEmbeddedButtonProps & Pick<IGlobalServiceProps, "theme">) {
	return (
		<TableRow>
			<TableCell style={{ ...commonStyles.tableCellStyle, ...commonStyles.noWrap }}>
				<span className="cfgName">
					{label}
				</span>
			</TableCell>
			<TableCell style={commonStyles.tableCellStyle}>
				<SecondaryButton theme={theme} onClick={onClick} id={"selectSerialPort"}>
					{buttonText}
				</SecondaryButton>
			</TableCell>
		</TableRow>
	);
}
