import * as _ from "lodash";
import * as Layout from "../../graph/types/layoutTypes";
import { PortMemberMgr } from "../../../services/objectManagers/portMemberMgr";
import { mapAdjacentElems } from "../../../services/utils";

// The incoming segments will:
//	1) include a source port and single target port
//	2) will always be horizontal or vertical
//	3) will not necessarily start/end at the source/target, but at the end/start of another segment with the same source/target
//
// The purpose of this function is to combine those segments into edges where:
//	1) No two edges overlap
//	2) Where segments overlapped, the resulting edge will contain multiple targets
//	3) Where two edges split, a "joint" will be created and returned at that point

export function combineSegments(orthogonalSegments: Layout.Edge<PortMemberMgr>[]) {
	// return { joints: [], edges: orthogonalSegments }; // uncomment to see uncombined segments directly

	// First, group the segments based on their source port

	const joints: Layout.Point[] = [];
	const edges = _.chain(orthogonalSegments)
		.groupBy((e) => e.source.getID())
		.flatMap((groupedBySourcePort) => {

			// Now, group those segments by their start point

			return _.chain(groupedBySourcePort)
				.groupBy((e) => `${e.start.x},${e.start.y}`)
				.flatMap((groupedByStartPoint: Layout.Edge<PortMemberMgr>[]) => {

					// Optimization: Most of the time the segment won't overlap with anything, so we can return it as is

					if (_.size(groupedByStartPoint) === 1) {
						return groupedByStartPoint[0];
					}

					// Otherwise, lets take the various segments and group/sort them according to how
					// long they are (note that there could be segments extending in different directions from the same
					// start point)

					const { start, source } = _.first(groupedByStartPoint);
					return _.chain(groupedByStartPoint)
						.map((e) => {
							const end = e.end;
							const horizontalVect = start.x - e.end.x;
							const verticalVect = start.y - e.end.y;
							return {
								end,
								dist: Math.abs(horizontalVect + verticalVect),
								direction: horizontalVect === 0
									? verticalVect > 0 ? "down" : "up"
									: horizontalVect > 0 ? "left" : "right",
								implied: e.implied,
							};
						})
						.groupBy((e) => e.direction)

						// If we have segments extending from this same starting point, yet going in different 
						// directions, we need a joint at the start

						.tap((groupedByDirection) => {
							if (2 <= _.size(groupedByDirection)) {
								joints.push(start);
							}
						})
						.flatMap((sameStartAndDirection) => {

							// Since these are all extending from the same starting point and going in the same 
							// direction, we'll need a joint at every end location except for the last, as the only 
							// reason a segment would extend part way is if there were a joint there to branch off
							// in another direction

							const ends = _.chain(sameStartAndDirection)
								.sortBy((e) => e.dist)
								.sortedUniqBy((e) => e.dist)
								.map(({ end }) => end)
								.value();
							joints.push(..._.dropRight(ends));

							// Now we can create segments between every point.  This eliminates overlaps between a 
							// shorter and longer segment, while also ensuring that there's a separate segment for each
							// part of the continuous line which allows for individual selection and hover effects.  
							// Note that each segment must include all the targets based on what overlaps with that 
							// section.

							return mapAdjacentElems([start, ...ends], (curStart, curEnd) => {
								return {
									id: `segment(${curStart.x},${curStart.y})-(${curEnd.x},${curEnd.y})`,
									start: curStart,
									end: curEnd,
									source,
									targets: _.chain(groupedByStartPoint)
										.filter((e) => isOnSegment(e, curEnd))
										.map((e) => _.first(e.targets))
										.value(),
									implied: _.every(sameStartAndDirection, (e) => e.implied),
								};
							});
						})
						.value();
				})
				.value();
		})
		.value();

	return { joints: _.uniqWith(joints, _.isEqual), edges };
}

// True if the point (second parameter) lays on the segment (first parameter)

function isOnSegment({ start, end }: { start: Layout.Point, end: Layout.Point }, point: Layout.Point) {
	return isBetween(start.x, end.x, point.x) && isBetween(start.y, end.y, point.y);
}

// True if mid is between start and end inclusive

function isBetween(start: number, end: number, mid: number) {
	return start > end ? start >= mid && mid >= end : start <= mid && mid <= end;
}

