import * as _ from "lodash";
import { PinInfo } from "../pinInfo";
import { QFPPkg } from "./qfpPackage";
import * as data from "dataInterfaces";
import { DevicePinSolutionMap } from "../solver/requirements";
import { IFormatter } from "../formatting/formattingTypes";
import { ILinkActions } from "../../components/actions/ILinkActions";
import { ATheme } from "../../components/styles/themes";
import { borderOffset, PIN_SIZE, UIPin } from "./devicePinTypes";
import { assertUnreachable } from "../utils";

import { Layer } from "konva/lib/Layer";
import { Circle } from "konva/lib/shapes/Circle";
import { Text as KonvaText } from "konva/lib/shapes/Text";
import { Rect } from "konva/lib/shapes/Rect";

export class CustomPkg extends QFPPkg {

	constructor(
		pinInfo: PinInfo,
		deviceData: data.AdaptedDeviceInfo,
		devicePinSolutionMap: DevicePinSolutionMap,
		selectedPins: Set<string>,
		formatter: IFormatter,
		actions: ILinkActions,
		theme: ATheme) {
		super(pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);
	}

	public override dimpleX() { return this.deviceData.customDeviceView.dimplePosition.x; }
	public override dimpleY() { return this.deviceData.customDeviceView.dimplePosition.y; }

	public override addDimple(layer: Layer) {
		// BU may not specify dimple
		if (this.deviceData.customDeviceView.dimplePosition) {
			super.addDimple(layer);
		}
	}

	public override addPins(layer: Layer) {
		_.each(this.deviceData.customDeviceView.pinPositions, ({ x, y, shape }, pinName) => {
			this.addCustomCellContent(layer, this.deviceData.devicePins[pinName].name, x, y, shape);
		});

		// add text positions
		_.each(this.deviceData.customDeviceView.textPositions, ({ text, x, y, rotation }) => {
			this.addTextPosition(layer, text, x, y, rotation);
		});
	}

	public override getStageDimensions() {
		// to place numbers on the outside without rotation we need to add more spacing
		const additionalSpacing = 5;
		return { width: this.width + borderOffset * 2 + additionalSpacing, height: this.height + borderOffset * 2 + additionalSpacing };
	}

	protected override setDeviceDimensions() {
		const { width, height } = this.deviceData.customDeviceView;
		this.width = width;
		this.height = height;
		this.extraXOffset = 0;
		this.setupBorderDimensions();
	}

	protected override setupBorderDimensions() {
		this.borderX = this.borderY = borderOffset;
		this.borderWidth = this.width;
		this.borderHeight = this.height;
	}

	private addCustomCellContent(layer: Layer, pinName: string, x: number, y: number, shape: DeviceInfo.PinShape) {
		const pin: UIPin = {
			shape: null,
			pinName: pinName,
			pinType: null,
		};
		this.setPinShape(pin, x, y, shape);
		pin.shape.pin = pin;
		this.applyPinDecorations(pin);
		layer.add(pin.shape);
		this.pins.push(pin);
	}

	private setPinShape(pin: UIPin, x: number, y: number, shape: DeviceInfo.PinShape) {

		const pinWidth = PIN_SIZE;
		const pinHeight = PIN_SIZE / 2;
		const fill = "grey";
		switch (shape) {
			case "CIRCLE": {
				const radius = PIN_SIZE / 2.5;
				pin.shape = new Circle({
					x,
					y,
					radius,
					fill,
				});
				break;
			}
			case "HORIZONTALRECTANGLE":
			case "VERTICALRECTANGLE": {
				pin.shape = new Rect({
					x,
					y,
					width: pinWidth,
					height: pinHeight,
					fill,
					rotation: shape === "VERTICALRECTANGLE" ? 90 : 0,
				});
				break;
			}
			case "BIGSQUARE": {
				pin.shape = new Rect({
					x,
					y,
					width: pinWidth,
					height: pinWidth,
					fill,
				});
				break;
			}
			case "SMALLSQUARE": {
				pin.shape = new Rect({
					x,
					y,
					width: pinHeight,
					height: pinHeight,
					fill,
				});
				break;
			}
			default:
				assertUnreachable(shape);
		}
	}

	private addTextPosition(layer: Layer, text: string, x: number, y: number, rotation: number) {
		const lbl = new KonvaText({
			x,
			y,
			text,
			fontSize: PIN_SIZE,
			fill: this.theme.theme.palette.text.primary,
			rotation,
		});

		layer.add(lbl);
	}
}
