import * as _ from "lodash";
import * as React from "react";
import { ATheme, ColorIndex } from "./styles/themes";

interface IProps {
	borderAfterChild: boolean;	// True if the border is rendered after (to the right or below) the child element
	position: number;			// Initial position of the border equating to the height/width of the child
	percentage?: boolean;		// True if the position prop is a percent
	displayed: boolean;			// False if the child is hidden
	showBorder?: boolean;		// False if the border is to be drawn when not hovered over
	horizontal: boolean;		// Orientation of the border
	onPositionChanged: (position: number) => void; 	// Fired when the drag is completed
	id: string;					// id to attach to for testing
	theme: ATheme;
}

const commonStyleHorizontal = {
	height: "100%",
	cursor: "col-resize",
};

const commonStyleVertical = {
	width: "100%",
	cursor: "row-resize",
};

interface IDragOperation {

	// The initial x or y coordinate of the mouse when the drag operation started
	initialMousePosition: number;

	// The initial width or height of the child element when the drag operation started
	initialChildSize: number;
}

// This component takes a child and draws a border on one side of that child that can be dragged to adjust the size of 
// the child.  Internally, it renders the child under a div who's styling is updated as the mouse moves when dragging.
// When the drag operation is complete, the callback will fire to allow saving the position for future renders

export function ResizableBorder({
	borderAfterChild,
	position: initialPosition,
	displayed,
	showBorder,
	percentage,
	onPositionChanged,
	theme,
	horizontal,
	id,
	children,
}: React.PropsWithChildren<IProps>) {
	const [isHovering, onMouseEnter, onMouseLeave] = useHover();
	const [positionDuringDrag, setPositionDuringDrag] = React.useState(initialPosition);
	const [dragging, setDragging] = React.useState<IDragOperation>(null);
	const childRef = React.useRef<HTMLDivElement>(null);

	// Calculates the new position for the child, based on the mouse position

	const calculatePosition = React.useCallback((mousePosition: number) => {

		// How many pixels have we dragged so far

		const positionDelta = borderAfterChild
			? (mousePosition - dragging.initialMousePosition)
			: (dragging.initialMousePosition - mousePosition);

		if (percentage) {

			// Determine how big the child should now be, and then convert that to a percentage

			const newPosition = dragging.initialChildSize + positionDelta;
			return newPosition / dragging.initialChildSize * initialPosition;
		} else {

			// Add the delta to the initial position

			return initialPosition + positionDelta;
		}
	}, [dragging, borderAfterChild, percentage, initialPosition]);

	// When the mouse is depressed on the border, capture the initial positions and enter the dragging state

	const onMouseDown = React.useCallback((event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
		setDragging({
			initialMousePosition: getMousePosition(event, horizontal),
			initialChildSize: horizontal ? childRef.current.clientWidth : childRef.current.clientHeight,
		});
		setPositionDuringDrag(initialPosition);
		event.stopPropagation();
		event.preventDefault();
	}, [horizontal, initialPosition]);

	// When the mouse is moved, update the position to render the border at

	const onMouseMove = React.useCallback((event: MouseEvent) => {
		const pos = getMousePosition(event, horizontal);
		setPositionDuringDrag(calculatePosition(pos));
		event.stopPropagation();
		event.preventDefault();
	}, [horizontal, calculatePosition]);

	// When the mouse is unpressed, save the new position

	const onMouseUp = React.useCallback(() => {
		onPositionChanged(positionDuringDrag);
		setDragging(null);
	}, [onPositionChanged, positionDuringDrag]);

	// When dragging, have event listeners for mouse move/up

	React.useEffect(() => {
		if (dragging) {
			document.addEventListener("mousemove", onMouseMove, false);
			document.addEventListener("mouseup", onMouseUp, false);
			return () => {
				document.removeEventListener("mousemove", onMouseMove, false);
				document.removeEventListener("mouseup", onMouseUp, false);
			};
		}
		return () => { };
	}, [dragging, onMouseMove, onMouseUp]);

	// Create the style for the child which should limit it's size based on the border's position

	const childStyle = React.useMemo(() => {
		const pos = dragging ? positionDuringDrag : initialPosition;
		const positionStr = (percentage) ? pos + "%" : pos + "px";

		if (horizontal) {
			return {
				height: "100%",
				width: positionStr,
				maxWidth: positionStr,
				minWidth: positionStr,
			};
		}
		return {
			height: positionStr,
			maxHeight: positionStr,
			minHeight: positionStr,
		};
	}, [positionDuringDrag, horizontal, percentage, dragging, initialPosition]);

	// Style for the border

	const borderStyle = React.useMemo(() => {
		let borderColour = "transparent";
		if (isHovering) {
			borderColour = theme.colors[ColorIndex.SELECTEDICONCOLOR];
		} else if (showBorder) {
			borderColour = theme.colors[ColorIndex.BORDERCOLOR];
		}

		const style = "3px solid " + borderColour;
		if (horizontal) {
			return { ...commonStyleHorizontal, borderRight: style };
		} else {
			return { ...commonStyleVertical, borderBottom: style };
		}
	}, [theme, horizontal, showBorder, isHovering]);

	if (!displayed) {
		return null;
	}

	// The main content to show who's style is updated as the border is dragged

	const child = (
		<div
			key="child"
			style={childStyle}
			ref={childRef}
			id={`${id}Child`}
		>
			{children}
		</div>
	);

	// The border line that is draggable

	const border = <div
		key="border"
		id={id}
		style={borderStyle}
		onMouseDown={onMouseDown}
		onMouseEnter={onMouseEnter}
		onMouseLeave={onMouseLeave}
	/>;

	// Determine if the draggable border is before or after the content

	const contentArr = (borderAfterChild) ? [child, border] : [border, child];
	return <>{contentArr}</>;
}

function getMousePosition(e: { clientX: number, clientY: number }, horizontal: boolean) {
	return horizontal ? e.clientX : e.clientY;
}

function useHover() {
	const [isHovering, setHovering] = React.useState(false);
	const onMouseEnter = React.useCallback(() => setHovering(true), []);
	const onMouseLeave = React.useCallback(() => setHovering(false), []);
	return [isHovering, onMouseEnter, onMouseLeave] as const;
}
