import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/graphStyles";
import * as Layout from "../types/layoutTypes";
import { AnyMemberMgr } from "../../../services/objectManagers/member";

// A straight edge to indicate a connection on the graph.  The edge is small, so the hover area is wider

function getPathForEdge<PortMgr extends AnyMemberMgr>(edge: Layout.Edge<PortMgr>) {

	// The ui tests rely on the spacing here, so do not alter that!

	const start = `M ${edge.start.x},${edge.start.y}`;
	const end = `L ${edge.end.x},${edge.end.y}`;
	return start + " " + end;
}

interface IProps<PortMgr extends AnyMemberMgr> {
	edge: Layout.Edge<PortMgr>;
	onMouseEnter: (edge: Layout.Edge<PortMgr>) => void;
	onMouseLeave: () => void;
	onClick: (edge: Layout.Edge<PortMgr>) => void;
	highlight: boolean;
	selected: boolean;
}

export class Edge<PortMgr extends AnyMemberMgr> extends React.PureComponent<IProps<PortMgr> & ClassesType> {
	public override render() {
		const { edge, onMouseLeave, highlight, selected, classes } = this.props;
		const edgePath = getPathForEdge(edge);

		return <>
			<path
				className={getClassName(selected, highlight, edge.implied, classes)}
				d={edgePath}
			/>
			<path
				className={classes.hoverSelectEdge}
				d={edgePath}
				onMouseEnter={this.onMouseEnter}
				onMouseLeave={onMouseLeave}
				onClick={this.onClick}
			/>
		</>;
	}

	private onMouseEnter = (e: React.MouseEvent<SVGPathElement, MouseEvent>) => {

		// Do not fire a edge-hover event when dragging.  The hover event can fire if the dragged elements don't keep 
		// up with the mouse, and that causes a large amount of unnecessary re-rendering which then immediately 
		// reverts once the dragged elements catch up to the mouse.  This makes the drag feel very unresponsive

		if (0 === e.buttons) { // buttons will be non-zero if any are clicked
			this.props.onMouseEnter(this.props.edge);
		}
	}

	private onClick = () => {
		this.props.onClick(this.props.edge);
	}
}

function getClassName(selected: boolean, highlight: boolean, implied: boolean, classes: ClassesType["classes"]) {
	if (selected) {
		return classes.selectedEdge;
	}
	if (highlight) {
		return classes.highlightedEdge;
	}
	if (implied) {
		return classes.impliedEdge;
	}
	return classes.edge;
}
