import {
	PinInterfaceInstance,
	InterfaceInstance,
} from "public/runtime";

import { Runtime } from "../resources/runtime";

export class PeripheralsImpl {

	constructor(private readonly runtime: Runtime) {
	}

	public readonly add = (interfaceName: string): InterfaceInstance | PinInterfaceInstance => {

		// If we're adding peripherals, we can now safely freeze the board content

		this.runtime.freezeBoardContent();

		const container = this.runtime.getInterfaceMgr(interfaceName);

		if (!container) {
			throw new Error("interface " + interfaceName + " not found");
		}

		return container.addInstance().managedObject;
	}
}
